import React from 'react';
import { Sale, Expense } from '../types';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, LineChart, Line } from 'recharts';

interface DashboardProps {
  sales: Sale[];
  expenses: Expense[];
}

const Dashboard: React.FC<DashboardProps> = ({ sales, expenses }) => {
  const totalRevenue = sales.reduce((acc, s) => acc + s.total, 0);
  const totalExpenses = expenses.reduce((acc, e) => acc + e.amount, 0);
  const netProfit = totalRevenue - totalExpenses;
  const averageTicket = sales.length > 0 ? totalRevenue / sales.length : 0;

  // Group sales by day for the chart
  const last7Days = Array.from({ length: 7 }, (_, i) => {
    const d = new Date();
    d.setDate(d.getDate() - i);
    return d.toISOString().split('T')[0];
  }).reverse();

  const chartData = last7Days.map(date => ({
    date: date.split('-').slice(1).join('/'),
    revenue: sales
      .filter(s => s.timestamp.startsWith(date))
      .reduce((acc, s) => acc + s.total, 0)
  }));

  const stats = [
    { label: 'Total Revenue', value: `$${totalRevenue.toLocaleString()}`, icon: '💰', color: 'bg-emerald-100 text-emerald-700' },
    { label: 'Total Expenses', value: `$${totalExpenses.toLocaleString()}`, icon: '💸', color: 'bg-rose-100 text-rose-700' },
    { label: 'Net Profit', value: `$${netProfit.toLocaleString()}`, icon: '📈', color: 'bg-blue-100 text-blue-700' },
    { label: 'Avg Ticket', value: `$${averageTicket.toFixed(2)}`, icon: '🎟️', color: 'bg-amber-100 text-amber-700' },
  ];

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-end">
        <div>
          <h2 className="text-3xl font-bold text-slate-800 font-brand">Business Overview</h2>
          <p className="text-slate-500 mt-1">Real-time performance analytics for your shop.</p>
        </div>
        <div className="text-right">
            <span className="text-xs font-semibold text-slate-400 uppercase tracking-widest">Today is</span>
            <p className="text-slate-800 font-medium">{new Date().toLocaleDateString('en-US', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' })}</p>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        {stats.map((stat, idx) => (
          <div key={idx} className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 flex items-center gap-4 transition-transform hover:scale-[1.02]">
            <div className={`w-12 h-12 rounded-xl flex items-center justify-center text-2xl ${stat.color}`}>
              {stat.icon}
            </div>
            <div>
              <p className="text-sm font-medium text-slate-400 uppercase tracking-wider">{stat.label}</p>
              <p className="text-2xl font-bold text-slate-800">{stat.value}</p>
            </div>
          </div>
        ))}
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
          <h3 className="text-lg font-bold text-slate-800 mb-6 flex items-center gap-2">
            <svg className="w-5 h-5 text-amber-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13 7h8m0 0v8m0-8l-8 8-4-4-6 6"/></svg>
            Revenue Trends (Last 7 Days)
          </h3>
          <div className="h-64">
            <ResponsiveContainer width="100%" height="100%">
              <LineChart data={chartData}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis dataKey="date" axisLine={false} tickLine={false} tick={{fill: '#94a3b8', fontSize: 12}} dy={10} />
                <YAxis axisLine={false} tickLine={false} tick={{fill: '#94a3b8', fontSize: 12}} />
                <Tooltip 
                  contentStyle={{borderRadius: '12px', border: 'none', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)'}}
                />
                <Line type="monotone" dataKey="revenue" stroke="#f59e0b" strokeWidth={3} dot={{fill: '#f59e0b', strokeWidth: 2, r: 4}} activeDot={{r: 6}} />
              </LineChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 overflow-hidden">
          <h3 className="text-lg font-bold text-slate-800 mb-6">Recent Sales</h3>
          <div className="space-y-4">
            {sales.slice(-5).reverse().map((sale) => (
              <div key={sale.id} className="flex items-center justify-between py-3 border-b border-slate-50 last:border-0">
                <div className="flex items-center gap-3">
                  <div className="w-10 h-10 rounded-full bg-slate-100 flex items-center justify-center text-slate-500">
                    {sale.paymentMethod === 'card' ? '💳' : '💵'}
                  </div>
                  <div>
                    <p className="text-sm font-semibold text-slate-800">Sale #{sale.id.slice(-4)}</p>
                    <p className="text-xs text-slate-400">{new Date(sale.timestamp).toLocaleTimeString()}</p>
                  </div>
                </div>
                <div className="text-right">
                  <p className="text-sm font-bold text-slate-800">${sale.total.toFixed(2)}</p>
                  <p className="text-xs text-amber-600 font-medium capitalize">{sale.paymentMethod}</p>
                </div>
              </div>
            ))}
            {sales.length === 0 && (
                <div className="flex flex-col items-center justify-center h-48 text-slate-400 italic">
                    <p>No sales today yet.</p>
                </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState } from 'react';
import { Service, Product, Staff, Sale, SaleItem } from '../types';

interface POSProps {
  services: Service[];
  products: Product[];
  staff: Staff[];
  onCompleteSale: (sale: Sale) => void;
}

const POS: React.FC<POSProps> = ({ services, products, staff, onCompleteSale }) => {
  const [cart, setCart] = useState<SaleItem[]>([]);
  const [selectedStaff, setSelectedStaff] = useState<string>(staff[0]?.id || '');
  const [paymentMethod, setPaymentMethod] = useState<'cash' | 'card'>('card');
  const [discount, setDiscount] = useState<number>(0);

  const addToCart = (item: Service | Product, type: 'service' | 'product') => {
    setCart(prev => {
      const existing = prev.find(i => i.id === item.id);
      if (existing) {
        return prev.map(i => i.id === item.id ? { ...i, quantity: i.quantity + 1 } : i);
      }
      return [...prev, { id: item.id, name: item.name, price: item.price, type, quantity: 1 }];
    });
  };

  const removeFromCart = (id: string) => {
    setCart(prev => prev.filter(i => i.id !== id));
  };

  const subtotal = cart.reduce((acc, i) => acc + (i.price * i.quantity), 0);
  const tax = subtotal * 0.1; // 10% tax
  const total = (subtotal + tax) - discount;

  const handleCheckout = () => {
    if (cart.length === 0) return;

    const newSale: Sale = {
      id: Math.random().toString(36).substr(2, 9).toUpperCase(),
      timestamp: new Date().toISOString(),
      items: cart,
      staffId: selectedStaff,
      total,
      tax,
      discount,
      paymentMethod
    };

    onCompleteSale(newSale);
    setCart([]);
    setDiscount(0);

    // Auto-print prompt
    setTimeout(() => {
        window.print();
    }, 100);
  };

  return (
    <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 h-[calc(100vh-8rem)]">
      {/* Items Selection */}
      <div className="lg:col-span-8 flex flex-col gap-8 overflow-y-auto pr-2 no-print">
        <section>
          <div className="flex items-center justify-between mb-4">
            <h3 className="text-xl font-bold text-slate-800 flex items-center gap-2">
                <svg className="w-6 h-6 text-amber-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M21 13.255A23.931 23.931 0 0112 15c-3.183 0-6.22-.62-9-1.745M16 6V4a2 2 0 00-2-2h-4a2 2 0 00-2 2v2m4 6h.01M5 20h14a2 2 0 002-2V8a2 2 0 00-2-2H5a2 2 0 00-2 2v10a2 2 0 002 2z"/></svg>
                Services
            </h3>
          </div>
          <div className="grid grid-cols-2 sm:grid-cols-3 gap-4">
            {services.map(service => (
              <button
                key={service.id}
                onClick={() => addToCart(service, 'service')}
                className="bg-white p-4 rounded-xl border border-slate-100 shadow-sm text-left hover:border-amber-400 hover:shadow-md transition-all group"
              >
                <p className="text-xs font-bold text-amber-600 uppercase mb-1">{service.category}</p>
                <p className="font-bold text-slate-800">{service.name}</p>
                <p className="text-slate-500 text-sm mt-2">${service.price}</p>
                <div className="mt-3 w-full h-1 bg-slate-50 rounded-full overflow-hidden">
                    <div className="w-0 group-hover:w-full h-full bg-amber-400 transition-all duration-300"></div>
                </div>
              </button>
            ))}
          </div>
        </section>

        <section>
          <div className="flex items-center justify-between mb-4">
            <h3 className="text-xl font-bold text-slate-800 flex items-center gap-2">
                <svg className="w-6 h-6 text-amber-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M16 11V7a4 4 0 00-8 0v4M5 9h14l1 12H4L5 9z"/></svg>
                Products
            </h3>
          </div>
          <div className="grid grid-cols-2 sm:grid-cols-3 gap-4">
            {products.map(product => (
              <button
                key={product.id}
                onClick={() => addToCart(product, 'product')}
                disabled={product.stock <= 0}
                className={`bg-white p-4 rounded-xl border border-slate-100 shadow-sm text-left hover:border-amber-400 hover:shadow-md transition-all ${product.stock <= 0 ? 'opacity-50 cursor-not-allowed' : ''}`}
              >
                <p className="font-bold text-slate-800">{product.name}</p>
                <p className="text-slate-500 text-sm mt-2">${product.price}</p>
                <p className={`text-xs mt-1 ${product.stock < 5 ? 'text-rose-500 font-bold' : 'text-slate-400'}`}>
                  Stock: {product.stock}
                </p>
              </button>
            ))}
          </div>
        </section>
      </div>

      {/* Cart & Checkout */}
      <div className="lg:col-span-4 bg-white rounded-3xl shadow-lg border border-slate-100 flex flex-col no-print">
        <div className="p-6 border-b border-slate-50">
          <h3 className="text-xl font-bold text-slate-800">Current Session</h3>
          <div className="mt-4 space-y-3">
             <label className="text-xs font-bold text-slate-400 uppercase tracking-wider block">Assigned Barber</label>
             <select 
               value={selectedStaff}
               onChange={(e) => setSelectedStaff(e.target.value)}
               className="w-full bg-slate-50 border-0 rounded-xl px-4 py-3 focus:ring-2 focus:ring-amber-400 outline-none"
             >
               {staff.map(s => <option key={s.id} value={s.id}>{s.name} ({s.role})</option>)}
             </select>
          </div>
        </div>

        <div className="flex-1 overflow-y-auto p-6 space-y-4">
          {cart.map(item => (
            <div key={item.id} className="flex justify-between items-start">
              <div className="flex-1">
                <p className="font-semibold text-slate-800">{item.name}</p>
                <p className="text-sm text-slate-400">Qty: {item.quantity} × ${item.price}</p>
              </div>
              <div className="text-right">
                <p className="font-bold text-slate-800">${(item.price * item.quantity).toFixed(2)}</p>
                <button onClick={() => removeFromCart(item.id)} className="text-rose-500 text-xs font-medium hover:underline">Remove</button>
              </div>
            </div>
          ))}
          {cart.length === 0 && (
            <div className="text-center py-12 text-slate-400 italic">
              Cart is empty. Select services or products.
            </div>
          )}
        </div>

        <div className="p-6 bg-slate-50 rounded-b-3xl space-y-3">
          <div className="flex justify-between text-slate-500">
            <span>Subtotal</span>
            <span>${subtotal.toFixed(2)}</span>
          </div>
          <div className="flex justify-between text-slate-500">
            <span>Tax (10%)</span>
            <span>${tax.toFixed(2)}</span>
          </div>
          <div className="flex justify-between items-center text-slate-500">
            <span>Discount</span>
            <input 
              type="number" 
              value={discount} 
              onChange={(e) => setDiscount(Number(e.target.value))}
              className="w-20 bg-transparent text-right border-b border-slate-300 focus:border-amber-500 outline-none" 
            />
          </div>
          <div className="flex justify-between text-xl font-bold text-slate-900 pt-2 border-t border-slate-200">
            <span>Total</span>
            <span>${total.toFixed(2)}</span>
          </div>

          <div className="grid grid-cols-2 gap-4 mt-6">
            <button 
              onClick={() => setPaymentMethod('card')}
              className={`py-3 rounded-xl border-2 transition-all font-semibold ${paymentMethod === 'card' ? 'bg-amber-100 border-amber-500 text-amber-700' : 'bg-white border-transparent text-slate-400'}`}
            >
              💳 Card
            </button>
            <button 
              onClick={() => setPaymentMethod('cash')}
              className={`py-3 rounded-xl border-2 transition-all font-semibold ${paymentMethod === 'cash' ? 'bg-amber-100 border-amber-500 text-amber-700' : 'bg-white border-transparent text-slate-400'}`}
            >
              💵 Cash
            </button>
          </div>

          <button
            onClick={handleCheckout}
            disabled={cart.length === 0}
            className="w-full mt-4 bg-slate-900 text-white py-4 rounded-xl font-bold text-lg hover:bg-slate-800 transition-colors shadow-lg disabled:opacity-50 disabled:cursor-not-allowed"
          >
            Checkout & Print
          </button>
        </div>
      </div>

      {/* Hidden Print Receipt Template */}
      <div className="print-only p-8 text-black bg-white w-full">
          <div className="text-center mb-6">
              <h1 className="text-2xl font-bold uppercase tracking-widest">TrimTime Barber</h1>
              <p className="text-sm">123 Street Ave, Barber City</p>
              <p className="text-sm">Tel: (555) 123-4567</p>
          </div>
          <div className="border-t border-b border-black py-2 my-4 flex justify-between text-xs font-mono uppercase">
              <span>Receipt ID: #DEMO</span>
              <span>{new Date().toLocaleDateString()}</span>
          </div>
          <div className="space-y-2 mb-6 font-mono text-sm">
              {cart.map(item => (
                  <div key={item.id} className="flex justify-between">
                      <span>{item.quantity}x {item.name}</span>
                      <span>${(item.price * item.quantity).toFixed(2)}</span>
                  </div>
              ))}
          </div>
          <div className="border-t border-black pt-2 space-y-1 font-mono text-sm">
              <div className="flex justify-between">
                  <span>Subtotal:</span>
                  <span>${subtotal.toFixed(2)}</span>
              </div>
              <div className="flex justify-between">
                  <span>Tax:</span>
