                key={customer.id} 
                onClick={() => setSelectedCustomer(customer)}
                className={`bg-white p-6 rounded-2xl border transition-all cursor-pointer flex justify-between items-center ${selectedCustomer?.id === customer.id ? 'border-amber-400 ring-2 ring-amber-100 shadow-md' : 'border-slate-100 hover:border-slate-200 shadow-sm'}`}
