                  <div className="hidden sm:block">
                    <p className="text-xs text-slate-400 uppercase font-bold tracking-widest">Last Visit</p>
                    <p className="text-sm font-semibold text-slate-700">{stats.lastVisit}</p>
                  </div>
                  <div>
                    <p className="text-xs text-slate-400 uppercase font-bold tracking-widest">Visits</p>
                    <p className="text-sm font-bold text-amber-600">{stats.visitCount}</p>
