                  <svg className="w-5 h-5 text-slate-300" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 5l7 7-7 7"/></svg>
                </div>
              </div>
            );
          })}
        </div>

        {/* Selected Customer Profile */}
        <div className="bg-white rounded-3xl border border-slate-100 shadow-lg p-8 sticky top-8 h-fit">
          {selectedCustomer ? (
            <div className="space-y-6">
              <div className="text-center pb-6 border-b border-slate-100">
                <div className="w-20 h-20 rounded-full bg-amber-100 text-amber-600 flex items-center justify-center text-3xl font-bold mx-auto mb-4">
                  {selectedCustomer.name.charAt(0)}
                </div>
                <h3 className="text-2xl font-bold text-slate-800">{selectedCustomer.name}</h3>
                <p className="text-slate-400">{selectedCustomer.email}</p>
                <div className="mt-4 flex flex-wrap justify-center gap-2">
                  <span className="px-3 py-1 bg-emerald-50 text-emerald-600 rounded-full text-xs font-bold uppercase">Active Member</span>
                  {getCustomerStats(selectedCustomer.id).visitCount > 5 && (
                    <span className="px-3 py-1 bg-amber-50 text-amber-600 rounded-full text-xs font-bold uppercase">VIP Guest</span>
                  )}
                </div>
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div className="bg-slate-50 p-4 rounded-xl">
                  <p className="text-[10px] text-slate-400 uppercase font-bold">Total Spent</p>
                  <p className="text-lg font-bold text-slate-800">${getCustomerStats(selectedCustomer.id).totalSpent.toFixed(2)}</p>
                </div>
                <div className="bg-slate-50 p-4 rounded-xl">
                  <p className="text-[10px] text-slate-400 uppercase font-bold">Avg Spend</p>
                  <p className="text-lg font-bold text-slate-800">
                    ${(getCustomerStats(selectedCustomer.id).totalSpent / (getCustomerStats(selectedCustomer.id).visitCount || 1)).toFixed(2)}
                  </p>
                </div>
              </div>

              <div>
                <h5 className="text-sm font-bold text-slate-800 mb-2 flex items-center gap-2">
                  <svg className="w-4 h-4 text-amber-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z"/></svg>
                  Client Notes & Preferences
                </h5>
                <div className="bg-amber-50 p-4 rounded-xl border border-amber-100 text-amber-900 text-sm leading-relaxed italic">
                  "{selectedCustomer.notes || 'No specific notes recorded.'}"
                </div>
              </div>

              <div>
                <h5 className="text-sm font-bold text-slate-800 mb-2">Visit History</h5>
                <div className="space-y-3">
                  {sales
                    .filter(s => s.customerId === selectedCustomer.id)
                    .sort((a,b) => b.timestamp.localeCompare(a.timestamp))
                    .slice(0, 3)
                    .map(sale => (
                      <div key={sale.id} className="flex justify-between items-center text-sm py-2 border-b border-slate-50 last:border-0">
                        <span className="text-slate-500">{new Date(sale.timestamp).toLocaleDateString()}</span>
                        <span className="font-semibold text-slate-700">${sale.total.toFixed(2)}</span>
                      </div>
                    ))}
                  {getCustomerStats(selectedCustomer.id).visitCount === 0 && (
                    <p className="text-xs text-slate-400 italic">No previous visits recorded.</p>
                  )}
                </div>
              </div>
            </div>
          ) : (
            <div className="flex flex-col items-center justify-center h-full text-slate-400 py-12">
              <svg className="w-16 h-16 mb-4 opacity-10" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M16 7a4 4 0 11-8 0 4 4 0 018 0zM12 14a7 7 0 00-7 7h14a7 7 0 00-7-7z"/></svg>
              <p>Select a customer to view details</p>
            </div>
          )}
        </div>
      </div>

      {/* Modal for adding new customer */}
      {isAdding && (
        <div className="fixed inset-0 bg-slate-900/50 backdrop-blur-sm z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-3xl w-full max-w-md p-8 shadow-2xl">
            <h3 className="text-2xl font-bold text-slate-800 mb-6">Register New Client</h3>
            <div className="space-y-4">
              <div>
                <label className="text-xs font-bold text-slate-400 uppercase block mb-1">Full Name</label>
