                  />
                </div>
              </div>
              <div>
                <label className="text-xs font-bold text-slate-400 uppercase block mb-1">Hair/Style Notes</label>
                <textarea 
                  value={newCust.notes}
                  onChange={e => setNewCust({...newCust, notes: e.target.value})}
                  className="w-full bg-slate-50 border-0 rounded-xl px-4 py-3 focus:ring-2 focus:ring-amber-400 outline-none h-24 resize-none"
