                <button 
                  onClick={() => {
                    if(!newCust.name) return;
                    onAddCustomer({
                      id: 'c' + (customers.length + 1),
                      name: newCust.name,
                      phone: newCust.phone,
                      email: newCust.email,
                      notes: newCust.notes,
