import React, { useState } from 'react';
import { Service, Product, Staff, Sale, SaleItem, Customer } from '../types';

interface POSProps {
  services: Service[];
  products: Product[];
  staff: Staff[];
  customers: Customer[];
  onCompleteSale: (sale: Sale) => void;
  onAddCustomer: (customer: Customer) => void;
}

const POS: React.FC<POSProps> = ({ services, products, staff, customers, onCompleteSale, onAddCustomer }) => {
  const [cart, setCart] = useState<SaleItem[]>([]);
  const [selectedStaff, setSelectedStaff] = useState<string>(staff[0]?.id || '');
  const [selectedCustomer, setSelectedCustomer] = useState<string>('');
  const [paymentMethod, setPaymentMethod] = useState<'cash' | 'card'>('card');
  const [discount, setDiscount] = useState<number>(0);
  const [customerSearch, setCustomerSearch] = useState('');
  const [isQuickAdd, setIsQuickAdd] = useState(false);
  const [quickCust, setQuickCust] = useState({ name: '', phone: '' });

  const addToCart = (item: Service | Product, type: 'service' | 'product') => {
    setCart(prev => {
      const existing = prev.find(i => i.id === item.id);
      if (existing) {
        return prev.map(i => i.id === item.id ? { ...i, quantity: i.quantity + 1 } : i);
      }
      return [...prev, { id: item.id, name: item.name, price: item.price, type, quantity: 1 }];
    });
  };

  const removeFromCart = (id: string) => {
    setCart(prev => prev.filter(i => i.id !== id));
  };

  const subtotal = cart.reduce((acc, i) => acc + (i.price * i.quantity), 0);
  const tax = subtotal * 0.1; // 10% tax
  const total = (subtotal + tax) - discount;

  const handleCheckout = () => {
    if (cart.length === 0) return;

    const newSale: Sale = {
      id: Math.random().toString(36).substr(2, 9).toUpperCase(),
      timestamp: new Date().toISOString(),
      items: cart,
      staffId: selectedStaff,
      customerId: selectedCustomer || undefined,
      total,
      tax,
      discount,
      paymentMethod
    };

    onCompleteSale(newSale);
    setCart([]);
    setDiscount(0);
    setSelectedCustomer('');

    // Auto-print prompt
    setTimeout(() => {
        window.print();
    }, 100);
  };

  const filteredCustomers = customers.filter(c => 
    c.name.toLowerCase().includes(customerSearch.toLowerCase()) || 
    c.phone.includes(customerSearch)
  );

  return (
    <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 h-[calc(100vh-8rem)]">
      {/* Items Selection */}
      <div className="lg:col-span-8 flex flex-col gap-8 overflow-y-auto pr-2 no-print">
        <section>
          <div className="flex items-center justify-between mb-4">
            <h3 className="text-xl font-bold text-slate-800 flex items-center gap-2">
                <svg className="w-6 h-6 text-amber-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M21 13.255A23.931 23.931 0 0112 15c-3.183 0-6.22-.62-9-1.745M16 6V4a2 2 0 00-2-2h-4a2 2 0 00-2 2v2m4 6h.01M5 20h14a2 2 0 002-2V8a2 2 0 00-2-2H5a2 2 0 00-2 2v10a2 2 0 002 2z"/></svg>
                Services
            </h3>
          </div>
          <div className="grid grid-cols-2 sm:grid-cols-3 gap-4">
            {services.map(service => (
              <button
                key={service.id}
                onClick={() => addToCart(service, 'service')}
                className="bg-white p-4 rounded-xl border border-slate-100 shadow-sm text-left hover:border-amber-400 hover:shadow-md transition-all group"
              >
                <p className="text-xs font-bold text-amber-600 uppercase mb-1">{service.category}</p>
                <p className="font-bold text-slate-800">{service.name}</p>
                <p className="text-slate-500 text-sm mt-2">${service.price}</p>
              </button>
            ))}
          </div>
        </section>

        <section>
          <div className="flex items-center justify-between mb-4">
            <h3 className="text-xl font-bold text-slate-800 flex items-center gap-2">
                <svg className="w-6 h-6 text-amber-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M16 11V7a4 4 0 00-8 0v4M5 9h14l1 12H4L5 9z"/></svg>
                Products
            </h3>
          </div>
          <div className="grid grid-cols-2 sm:grid-cols-3 gap-4">
            {products.map(product => (
              <button
                key={product.id}
                onClick={() => addToCart(product, 'product')}
                disabled={product.stock <= 0}
                className={`bg-white p-4 rounded-xl border border-slate-100 shadow-sm text-left hover:border-amber-400 hover:shadow-md transition-all ${product.stock <= 0 ? 'opacity-50 cursor-not-allowed' : ''}`}
              >
                <p className="font-bold text-slate-800">{product.name}</p>
                <p className="text-slate-500 text-sm mt-2">${product.price}</p>
                <p className={`text-xs mt-1 ${product.stock < 5 ? 'text-rose-500 font-bold' : 'text-slate-400'}`}>
                  Stock: {product.stock}
                </p>
              </button>
            ))}
          </div>
        </section>
      </div>

      {/* Cart & Checkout */}
      <div className="lg:col-span-4 bg-white rounded-3xl shadow-lg border border-slate-100 flex flex-col no-print">
        <div className="p-6 border-b border-slate-50 space-y-4">
          <div className="flex justify-between items-center">
            <h3 className="text-xl font-bold text-slate-800">Checkout</h3>
            <button 
              onClick={() => setIsQuickAdd(true)}
              className="text-xs font-bold text-amber-600 bg-amber-50 px-3 py-1.5 rounded-full hover:bg-amber-100"
            >
              + Quick Add Client
            </button>
          </div>

          <div className="space-y-3">
             <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest block">Client Selection</label>
             <div className="relative group">
               <input 
                 type="text" 
                 placeholder="Search customer..." 
                 value={customerSearch}
                 onChange={e => setCustomerSearch(e.target.value)}
                 onFocus={() => setSelectedCustomer('')}
                 className="w-full bg-slate-50 border-0 rounded-xl px-4 py-3 focus:ring-2 focus:ring-amber-400 outline-none text-sm"
               />
               {customerSearch && !selectedCustomer && (
                 <div className="absolute top-full left-0 w-full mt-1 bg-white border border-slate-100 shadow-xl rounded-xl z-10 max-h-48 overflow-y-auto">
                   {filteredCustomers.length > 0 ? (
                     filteredCustomers.map(c => (
                       <button
                         key={c.id}
                         onClick={() => {
                           setSelectedCustomer(c.id);
                           setCustomerSearch(c.name);
                         }}
                         className="w-full px-4 py-3 text-left hover:bg-slate-50 border-b border-slate-50 last:border-0 text-sm"
                       >
                         <div className="font-semibold text-slate-800">{c.name}</div>
                         <div className="text-xs text-slate-400">{c.phone}</div>
                       </button>
                     ))
                   ) : (
                     <div className="px-4 py-3 text-xs text-slate-400 italic">No matches found</div>
                   )}
                 </div>
               )}
             </div>
          </div>

          <div className="space-y-3">
             <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest block">Barber</label>
             <select 
               value={selectedStaff}
               onChange={(e) => setSelectedStaff(e.target.value)}
               className="w-full bg-slate-50 border-0 rounded-xl px-4 py-3 focus:ring-2 focus:ring-amber-400 outline-none text-sm font-medium"
             >
               {staff.map(s => <option key={s.id} value={s.id}>{s.name}</option>)}
             </select>
          </div>
        </div>

        <div className="flex-1 overflow-y-auto p-6 space-y-4">
          {cart.map(item => (
            <div key={item.id} className="flex justify-between items-start">
              <div className="flex-1">
                <p className="font-semibold text-slate-800 text-sm">{item.name}</p>
                <p className="text-xs text-slate-400">Qty: {item.quantity} × ${item.price}</p>
              </div>
              <div className="text-right">
                <p className="font-bold text-slate-800 text-sm">${(item.price * item.quantity).toFixed(2)}</p>
                <button onClick={() => removeFromCart(item.id)} className="text-rose-500 text-[10px] font-medium hover:underline">Remove</button>
              </div>
            </div>
          ))}
          {cart.length === 0 && (
            <div className="text-center py-12 text-slate-400 italic text-sm">
              Cart is empty.
            </div>
          )}
        </div>

        <div className="p-6 bg-slate-50 rounded-b-3xl space-y-3">
          <div className="flex justify-between text-slate-500 text-sm">
            <span>Subtotal</span>
            <span>${subtotal.toFixed(2)}</span>
          </div>
          <div className="flex justify-between items-center text-slate-500 text-sm">
            <span>Discount</span>
            <input 
              type="number" 
              value={discount} 
              onChange={(e) => setDiscount(Number(e.target.value))}
              className="w-20 bg-transparent text-right border-b border-slate-300 focus:border-amber-500 outline-none" 
            />
          </div>
          <div className="flex justify-between text-xl font-bold text-slate-900 pt-2 border-t border-slate-200">
            <span>Total</span>
            <span>${total.toFixed(2)}</span>
          </div>

          <div className="grid grid-cols-2 gap-4 mt-6">
            <button 
              onClick={() => setPaymentMethod('card')}
              className={`py-3 rounded-xl border-2 transition-all font-semibold ${paymentMethod === 'card' ? 'bg-amber-100 border-amber-500 text-amber-700' : 'bg-white border-transparent text-slate-400'}`}
            >
              💳 Card
            </button>
            <button 
              onClick={() => setPaymentMethod('cash')}
              className={`py-3 rounded-xl border-2 transition-all font-semibold ${paymentMethod === 'cash' ? 'bg-amber-100 border-amber-500 text-amber-700' : 'bg-white border-transparent text-slate-400'}`}
            >
              💵 Cash
            </button>
          </div>

          <button
            onClick={handleCheckout}
            disabled={cart.length === 0}
            className="w-full mt-4 bg-slate-900 text-white py-4 rounded-xl font-bold text-lg hover:bg-slate-800 transition-colors shadow-lg disabled:opacity-50"
          >
            Complete Order
          </button>
        </div>
      </div>

      {/* Quick Add Client Modal */}
      {isQuickAdd && (
        <div className="fixed inset-0 bg-slate-900/40 backdrop-blur-sm z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-3xl w-full max-w-sm p-6 shadow-2xl">
            <h4 className="text-lg font-bold text-slate-800 mb-4">Fast Client Sign-up</h4>
            <div className="space-y-4">
              <input 
                type="text" 
                placeholder="Full Name" 
                value={quickCust.name}
                onChange={e => setQuickCust({...quickCust, name: e.target.value})}
                className="w-full bg-slate-50 border-0 rounded-xl px-4 py-3 focus:ring-2 focus:ring-amber-400 outline-none" 
              />
              <input 
                type="tel" 
                placeholder="Phone Number" 
                value={quickCust.phone}
                onChange={e => setQuickCust({...quickCust, phone: e.target.value})}
                className="w-full bg-slate-50 border-0 rounded-xl px-4 py-3 focus:ring-2 focus:ring-amber-400 outline-none" 
              />
              <div className="flex gap-3">
                <button onClick={() => setIsQuickAdd(false)} className="flex-1 py-3 text-slate-400 font-bold">Cancel</button>
                <button 
                  onClick={() => {
                    if(!quickCust.name) return;
                    const id = 'c' + Date.now();
                    onAddCustomer({
                      id,
                      name: quickCust.name,
                      phone: quickCust.phone,
                      email: '',
                      notes: '',
                      createdAt: new Date().toISOString()
                    });
                    setSelectedCustomer(id);
                    setCustomerSearch(quickCust.name);
                    setIsQuickAdd(false);
                    setQuickCust({name: '', phone: ''});
                  }}
                  className="flex-1 bg-amber-500 text-slate-900 py-3 rounded-xl font-bold shadow-md"
                >
                  Register
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Hidden Print Receipt Template */}
      <div className="print-only p-8 text-black bg-white w-full">
          <div className="text-center mb-6">
              <h1 className="text-2xl font-bold uppercase tracking-widest">TrimTime Barber</h1>
              <p className="text-sm">Receipt for {customerSearch || 'Valued Guest'}</p>
          </div>
          <div className="border-t border-b border-black py-2 my-4 flex justify-between text-xs font-mono uppercase">
              <span>Date: {new Date().toLocaleDateString()}</span>
              <span>Barber: {staff.find(s => s.id === selectedStaff)?.name}</span>
          </div>
          <div className="space-y-2 mb-6 font-mono text-sm">
              {cart.map(item => (
                  <div key={item.id} className="flex justify-between">
                      <span>{item.quantity}x {item.name}</span>
                      <span>${(item.price * item.quantity).toFixed(2)}</span>
                  </div>
              ))}
          </div>
          <div className="border-t border-black pt-2 space-y-1 font-mono text-sm">
              <div className="flex justify-between font-bold text-lg pt-2">
                  <span>TOTAL:</span>
                  <span>${total.toFixed(2)}</span>
              </div>
          </div>
      </div>
    </div>
  );
};

