import { GoogleGenAI } from "@google/genai";
import { Sale, Expense } from "../types";

// Always use process.env.API_KEY directly as a named parameter
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export async function getFinancialInsights(sales: Sale[], expenses: Expense[]) {
  // Using gemini-3-flash-preview for general business analysis tasks
  const model = 'gemini-3-flash-preview';

  const totalRevenue = sales.reduce((acc, s) => acc + s.total, 0);
  const totalExpenses = expenses.reduce((acc, e) => acc + e.amount, 0);
  const profit = totalRevenue - totalExpenses;

  const prompt = `
    As a business consultant for a boutique Barber Shop, analyze the following financial data:
    Total Revenue: $${totalRevenue}
    Total Expenses: $${totalExpenses}
    Net Profit: $${profit}

    Number of Sales: ${sales.length}
    Recent Expenses: ${expenses.slice(0, 5).map(e => `${e.category}: $${e.amount}`).join(', ')}

    Please provide:
    1. A short summary of the financial health.
    2. Three actionable tips to increase revenue or reduce costs.
    3. An observation on sales volume vs expenses.

    Return the response in a clean, professional format.
  `;

  try {
    // Generate content using the recommended structure
    const response = await ai.models.generateContent({
      model: model,
      contents: prompt,
    });
    // Accessing .text as a property, not a method
    return response.text || "No insights could be generated.";
  } catch (error) {
    console.error("Gemini Insight Error:", error);
    return "Unable to generate insights at this time. Please check your data or try again later.";
  }
}

import React, { useState, useMemo } from 'react';
import { Service, Product, Staff, Sale, SaleItem, Customer } from '../types';
import { INITIAL_DISCOUNT_CODES } from '../constants';

interface POSProps {
  services: Service[];
  products: Product[];
  staff: Staff[];
  customers: Customer[];
  onCompleteSale: (sale: Sale) => void;
  onAddCustomer: (customer: Customer) => void;
}

const POS: React.FC<POSProps> = ({ services, products, staff, customers, onCompleteSale, onAddCustomer }) => {
  const [cart, setCart] = useState<SaleItem[]>([]);
  const [selectedStaff, setSelectedStaff] = useState<string>('');
  const [selectedCustomer, setSelectedCustomer] = useState<string>('');
  const [discountCode, setDiscountCode] = useState<string>('');
  const [activeTab, setActiveTab] = useState<'services' | 'products'>('services');

  const addToCart = (item: Service | Product, type: 'service' | 'product') => {
    setCart(prev => {
      const existing = prev.find(i => i.id === item.id && i.type === type);
      if (existing) {
        return prev.map(i => i.id === item.id && i.type === type ? { ...i, quantity: i.quantity + 1 } : i);
      }
      return [...prev, { id: item.id, name: item.name, price: item.price, type, quantity: 1 }];
    });
  };

  const removeFromCart = (id: string, type: 'service' | 'product') => {
    setCart(prev => prev.filter(i => !(i.id === id && i.type === type)));
  };

  const appliedDiscount = useMemo(() => {
    const code = INITIAL_DISCOUNT_CODES.find(c => c.code === discountCode.toUpperCase());
    return code || null;
  }, [discountCode]);

  const subtotal = cart.reduce((acc, item) => acc + (item.price * item.quantity), 0);
  const discountAmount = appliedDiscount 
    ? (appliedDiscount.type === 'percentage' ? (subtotal * appliedDiscount.value / 100) : appliedDiscount.value)
    : 0;
  const tax = (subtotal - discountAmount) * 0.08;
  const total = subtotal - discountAmount + tax;

  const handleComplete = () => {
    if (!selectedStaff || cart.length === 0) return;

    const sale: Sale = {
      id: Math.random().toString(36).substr(2, 9),
      timestamp: new Date().toISOString(),
      items: cart,
      staffId: selectedStaff,
      customerId: selectedCustomer || undefined,
      total: total,
      tax: tax,
      discount: discountAmount,
      discountCode: appliedDiscount?.code,
      paymentMethod: 'card'
    };

    onCompleteSale(sale);
    setCart([]);
    setSelectedStaff('');
    setSelectedCustomer('');
    setDiscountCode('');
  };

  return (
    <div className="flex flex-col lg:flex-row gap-8 h-[calc(100vh-160px)]">
      {/* Items Grid */}
      <div className="flex-1 flex flex-col gap-6 overflow-hidden">
        <div className="flex gap-4 no-print">
          <button 
            onClick={() => setActiveTab('services')}
            className={`px-8 py-3 rounded-2xl font-bold transition-all shadow-sm ${activeTab === 'services' ? 'bg-amber-500 text-slate-900 ring-2 ring-amber-200' : 'bg-white text-slate-400 hover:bg-slate-50'}`}
          >
            Services
          </button>
          <button 
            onClick={() => setActiveTab('products')}
            className={`px-8 py-3 rounded-2xl font-bold transition-all shadow-sm ${activeTab === 'products' ? 'bg-amber-500 text-slate-900 ring-2 ring-amber-200' : 'bg-white text-slate-400 hover:bg-slate-50'}`}
          >
            Products
          </button>
        </div>

        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4 overflow-y-auto pr-2 pb-8">
          {activeTab === 'services' ? (
            services.map(s => (
              <button 
                key={s.id}
                onClick={() => addToCart(s, 'service')}
                className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm hover:border-amber-400 hover:shadow-xl transition-all text-left flex flex-col justify-between h-40 group"
              >
                <div>
                    <span className="text-[10px] font-black text-amber-600 uppercase tracking-widest bg-amber-50 px-2 py-1 rounded-md">{s.category}</span>
                    <h4 className="font-bold text-slate-800 mt-2 group-hover:text-amber-600 transition-colors">{s.name}</h4>
                </div>
                <div className="flex justify-between items-end">
                  <span className="text-xs text-slate-400">{s.duration} min</span>
                  <span className="text-lg font-black text-slate-900">${s.price}</span>
                </div>
              </button>
            ))
          ) : (
            products.map(p => (
              <button 
                key={p.id}
                onClick={() => addToCart(p, 'product')}
                disabled={p.stock <= 0}
                className={`bg-white p-6 rounded-3xl border border-slate-100 shadow-sm transition-all text-left flex flex-col justify-between h-40 group ${p.stock <= 0 ? 'opacity-50 grayscale' : 'hover:border-amber-400 hover:shadow-xl'}`}
              >
                <div>
                    <span className="text-[10px] font-black text-blue-600 uppercase tracking-widest bg-blue-50 px-2 py-1 rounded-md">Product</span>
                    <h4 className="font-bold text-slate-800 mt-2 group-hover:text-amber-600 transition-colors">{p.name}</h4>
                </div>
                <div className="flex justify-between items-end">
                  <span className={`text-xs font-bold ${p.stock < 5 ? 'text-rose-500' : 'text-slate-400'}`}>Stock: {p.stock}</span>
                  <span className="text-lg font-black text-slate-900">${p.price}</span>
                </div>
              </button>
            ))
          )}
        </div>
      </div>

      {/* Checkout Panel */}
      <div className="w-full lg:w-96 bg-white rounded-[2rem] border border-slate-100 shadow-2xl flex flex-col overflow-hidden no-print">
        <div className="p-8 border-b border-slate-50 flex justify-between items-center bg-slate-50/50">
          <h3 className="text-xl font-bold text-slate-800">Current Ticket</h3>
          <span className="bg-slate-900 text-white text-[10px] px-2 py-1 rounded-full font-bold">{cart.reduce((a, b) => a + b.quantity, 0)} Items</span>
        </div>

        <div className="flex-1 overflow-y-auto p-8 space-y-6">
          {cart.length === 0 ? (
            <div className="h-full flex flex-col items-center justify-center text-slate-300 py-12">
              <svg className="w-16 h-16 mb-4 opacity-10" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M16 11V7a4 4 0 00-8 0v4M5 9h14l1 12H4L5 9z"/></svg>
              <p className="font-medium">Your ticket is empty</p>
            </div>
          ) : (
            cart.map(item => (
              <div key={`${item.type}-${item.id}`} className="flex justify-between items-center group">
                <div className="flex-1">
                  <p className="font-bold text-slate-800 text-sm">{item.name}</p>
                  <p className="text-xs text-slate-400 font-medium">{item.quantity}x @ ${item.price.toFixed(2)}</p>
                </div>
                <div className="flex items-center gap-4">
                  <p className="font-bold text-slate-800">${(item.price * item.quantity).toFixed(2)}</p>
                  <button 
                    onClick={() => removeFromCart(item.id, item.type)}
                    className="p-1 text-slate-200 hover:text-rose-500 transition-colors"
                  >
                    <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12"/></svg>
                  </button>
                </div>
              </div>
            ))
          )}
        </div>

        <div className="p-8 bg-slate-900 text-white rounded-t-[2rem] space-y-6">
          <div className="space-y-4">
            <div>
              <label className="text-[10px] font-black text-slate-500 uppercase tracking-[0.2em] block mb-2">Service Provided By</label>
              <select 
                value={selectedStaff}
                onChange={(e) => setSelectedStaff(e.target.value)}
                className="w-full bg-slate-800 border-0 rounded-xl px-4 py-3 text-sm focus:ring-2 focus:ring-amber-400 outline-none transition-all"
              >
                <option value="">Select Professional</option>
                {staff.map(s => <option key={s.id} value={s.id}>{s.name} ({s.role})</option>)}
              </select>
            </div>

            <div>
              <div className="flex justify-between items-center mb-2">
                <label className="text-[10px] font-black text-slate-500 uppercase tracking-[0.2em]">Customer</label>
                <button 
                    onClick={() => {
                        const name = prompt("Client Name:");
                        if (name) onAddCustomer({ id: 'c' + Date.now(), name, phone: '', email: '', notes: '', createdAt: new Date().toISOString().split('T')[0] });
                    }}
                    className="text-[10px] font-bold text-amber-400 hover:underline"
                >
                    + Add New
                </button>
              </div>
              <select 
                value={selectedCustomer}
                onChange={(e) => setSelectedCustomer(e.target.value)}
                className="w-full bg-slate-800 border-0 rounded-xl px-4 py-3 text-sm focus:ring-2 focus:ring-amber-400 outline-none transition-all"
              >
                <option value="">Guest Walk-in</option>
                {customers.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
              </select>
            </div>
          </div>

          <div className="pt-6 space-y-3 border-t border-slate-800">
            <div className="flex justify-between text-xs text-slate-400">
              <span>Subtotal</span>
              <span>${subtotal.toFixed(2)}</span>
            </div>

            <div className="flex items-center gap-3">
              <input 
                type="text" 
                placeholder="Discount Code" 
                value={discountCode}
                onChange={(e) => setDiscountCode(e.target.value)}
                className="flex-1 bg-slate-800 border-0 rounded-lg px-3 py-2 text-xs focus:ring-2 focus:ring-amber-400 outline-none text-white"
              />
              {appliedDiscount && <span className="text-[10px] font-black text-emerald-400">APPLIED</span>}
            </div>

            {discountAmount > 0 && (
              <div className="flex justify-between text-xs text-rose-400">
                <span>Discount ({appliedDiscount?.code})</span>
                <span>-${discountAmount.toFixed(2)}</span>
              </div>
            )}

            <div className="flex justify-between text-xs text-slate-400">
              <span>Sales Tax (8%)</span>
              <span>${tax.toFixed(2)}</span>
            </div>

            <div className="flex justify-between text-2xl font-black pt-4 border-t border-slate-800">
              <span className="text-slate-400">Total</span>
              <span className="text-amber-500">${total.toFixed(2)}</span>
            </div>
          </div>

          <button 
            onClick={handleComplete}
            disabled={!selectedStaff || cart.length === 0}
            className="w-full bg-amber-500 text-slate-900 py-5 rounded-[1.25rem] font-black text-lg hover:bg-amber-400 transition-all shadow-xl shadow-amber-500/10 disabled:opacity-50 disabled:grayscale cursor-pointer"
          >
            Finalize Payment
          </button>
        </div>
      </div>
    </div>
  );
};

