                  <div className="flex-1 w-full space-y-6">
                    <div className="grid grid-cols-2 gap-4">
                      <div className="bg-slate-50 p-4 rounded-xl">
                        <p className="text-[10px] text-slate-400 uppercase font-black tracking-widest mb-1">Lifetime Spend</p>
                        <p className="text-xl font-black text-slate-800">${getCustomerStats(selectedCustomer.id).totalSpent.toFixed(2)}</p>
