                  type="text" 
                  value={newCust.name}
                  onChange={e => setNewCust({...newCust, name: e.target.value})}
                  className="w-full bg-slate-50 border-0 rounded-xl px-4 py-3 focus:ring-2 focus:ring-amber-400 outline-none" 
                />
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="text-xs font-bold text-slate-400 uppercase block mb-1">Phone</label>
                  <input 
                    type="tel" 
                    value={newCust.phone}
                    onChange={e => setNewCust({...newCust, phone: e.target.value})}
                    className="w-full bg-slate-50 border-0 rounded-xl px-4 py-3 focus:ring-2 focus:ring-amber-400 outline-none" 
                  />
                </div>
                <div>
                  <label className="text-xs font-bold text-slate-400 uppercase block mb-1">Email</label>
                  <input 
                    type="email" 
                    value={newCust.email}
                    onChange={e => setNewCust({...newCust, email: e.target.value})}
                    className="w-full bg-slate-50 border-0 rounded-xl px-4 py-3 focus:ring-2 focus:ring-amber-400 outline-none" 
                  />
                </div>
              </div>
              <div>
                <label className="text-xs font-bold text-slate-400 uppercase block mb-1">Hair/Style Notes</label>
                <textarea 
                  value={newCust.notes}
                  onChange={e => setNewCust({...newCust, notes: e.target.value})}
                  className="w-full bg-slate-50 border-0 rounded-xl px-4 py-3 focus:ring-2 focus:ring-amber-400 outline-none h-24 resize-none"
                />
              </div>
              <div className="flex gap-4 mt-6">
                <button 
                  onClick={() => setIsAdding(false)}
                  className="flex-1 px-4 py-3 border border-slate-200 rounded-xl font-bold text-slate-400 hover:bg-slate-50 transition-all"
                >
                  Cancel
                </button>
                <button 
                  onClick={() => {
                    if(!newCust.name) return;
                    onAddCustomer({
                      id: 'c' + (customers.length + 1),
                      name: newCust.name,
                      phone: newCust.phone,
                      email: newCust.email,
                      notes: newCust.notes,
                      createdAt: new Date().toISOString().split('T')[0]
                    });
                    setIsAdding(false);
                    setNewCust({ name: '', phone: '', email: '', notes: '' });
                  }}
                  className="flex-1 px-4 py-3 bg-slate-900 text-white rounded-xl font-bold hover:bg-slate-800 transition-all shadow-lg"
                >
                  Create Profile
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

