          <div className="space-y-2 mb-8">
              <div className="flex justify-between">
                  <span>DATE:</span>
                  <span>{new Date().toLocaleDateString()}</span>
              </div>
              <div className="flex justify-between">
                  <span>BARBER:</span>
                  <span>{staff.find(s => s.id === selectedStaff)?.name || 'N/A'}</span>
              </div>
              <div className="flex justify-between">
                  <span>CLIENT:</span>
                  <span>{customers.find(c => c.id === selectedCustomer)?.name || 'WALK-IN'}</span>
              </div>
          </div>

          <div className="border-b border-black mb-4"></div>

          <div className="space-y-3 mb-8">
              {cart.map((item, i) => (
                  <div key={i} className="flex justify-between">
                      <span className="flex-1">{item.quantity}x {item.name}</span>
                      <span className="w-24 text-right">{settings.currency}{(item.price * item.quantity).toFixed(2)}</span>
                  </div>
              ))}
          </div>

          <div className="border-b-2 border-black mb-4"></div>

          <div className="space-y-2">
              <div className="flex justify-between">
                  <span>SUBTOTAL:</span>
                  <span>{settings.currency}{subtotal.toFixed(2)}</span>
              </div>
              {discountAmount > 0 && (
                  <div className="flex justify-between">
                      <span>DISCOUNT:</span>
                      <span>-{settings.currency}{discountAmount.toFixed(2)}</span>
                  </div>
              )}
              <div className="flex justify-between">
                  <span>TAX ({settings.taxRate}%):</span>
                  <span>{settings.currency}{tax.toFixed(2)}</span>
              </div>
              <div className="flex justify-between text-xl font-black pt-4">
                  <span>TOTAL PAID:</span>
                  <span>{settings.currency}{total.toFixed(2)}</span>
              </div>
          </div>

          <div className="mt-12 text-center border-t border-black pt-8">
              <p className="font-bold">{settings.receiptFooter}</p>
              <p className="text-[10px] mt-4 opacity-50">Transaction ID: {Math.random().toString(36).substr(2, 12).toUpperCase()}</p>
          </div>
      </div>
    </div>
  );
};

