              <label className="text-xs font-bold text-slate-400 uppercase block mb-1">Category</label>
              <input
                type="text"
                value={newExpense.category}
                onChange={e => setNewExpense({...newExpense, category: e.target.value})}
                placeholder="Rent, Utilities, Supplies..."
                className="w-full bg-slate-50 border-0 rounded-xl px-4 py-3 focus:ring-2 focus:ring-amber-400 outline-none"
              />
            </div>
            <div>
              <label className="text-xs font-bold text-slate-400 uppercase block mb-1">Amount ({currency})</label>
              <input
                type="number"
                value={newExpense.amount}
                onChange={e => setNewExpense({...newExpense, amount: Number(e.target.value)})}
                className="w-full bg-slate-50 border-0 rounded-xl px-4 py-3 focus:ring-2 focus:ring-amber-400 outline-none"
              />
            </div>
            <div>
              <label className="text-xs font-bold text-slate-400 uppercase block mb-1">Description</label>
              <textarea
                value={newExpense.description}
                onChange={e => setNewExpense({...newExpense, description: e.target.value})}
                className="w-full bg-slate-50 border-0 rounded-xl px-4 py-3 focus:ring-2 focus:ring-amber-400 outline-none h-24 resize-none"
                placeholder="Optional details..."
              />
            </div>
            <button
              onClick={() => {
                if (!newExpense.category || newExpense.amount <= 0) return;
                onAddExpense({
                  id: Math.random().toString(36).substr(2, 9),
                  date: new Date().toISOString().split('T')[0],
                  category: newExpense.category,
                  amount: newExpense.amount,
                  description: newExpense.description
                });
                setNewExpense({ category: '', amount: 0, description: '' });
              }}
              className="w-full bg-slate-900 text-white py-4 rounded-xl font-bold hover:bg-slate-800 transition-colors shadow-lg"
            >
              Add Expense
            </button>
          </div>
        </div>

        <div className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm overflow-hidden">
          <h3 className="text-lg font-bold text-slate-800 mb-4">Expense History</h3>
          <div className="space-y-3 max-h-[400px] overflow-y-auto pr-2">
            {expenses.slice().reverse().map(exp => (
              <div key={exp.id} className="flex justify-between items-center py-3 border-b border-slate-50 last:border-0 group">
                <div>
                  <p className="font-semibold text-slate-800">{exp.category}</p>
                  <p className="text-xs text-slate-400">{new Date(exp.date).toLocaleDateString()}</p>
                </div>
                <div className="text-right">
                    <p className="font-bold text-rose-500">-{currency}{exp.amount.toLocaleString()}</p>
                    <p className="text-[10px] text-slate-300 italic truncate w-24 group-hover:w-auto">{exp.description}</p>
                </div>
              </div>
            ))}
            {expenses.length === 0 && (
                <p className="text-center py-8 text-slate-400 italic text-sm">No expenses recorded yet.</p>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default Finance;

import React, { useState } from 'react';
import { Customer, Sale } from '../types';

interface CustomersProps {
  customers: Customer[];
  sales: Sale[];
  onAddCustomer: (customer: Customer) => void;
  currency: string;
}

const Customers: React.FC<CustomersProps> = ({ customers, sales, onAddCustomer, currency }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedCustomer, setSelectedCustomer] = useState<Customer | null>(null);
  const [isAdding, setIsAdding] = useState(false);
  const [newCust, setNewCust] = useState({ name: '', phone: '', email: '', notes: '' });

  const filteredCustomers = customers.filter(c => 
    c.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
    c.phone.includes(searchTerm)
  );

  const getCustomerStats = (id: string) => {
    const custSales = sales.filter(s => s.customerId === id);
    const totalSpent = custSales.reduce((acc, s) => acc + s.total, 0);
    const lastVisit = custSales.length > 0 
      ? new Date(custSales.sort((a,b) => b.timestamp.localeCompare(a.timestamp))[0].timestamp).toLocaleDateString()
      : 'Never';
    return { totalSpent, lastVisit, visitCount: custSales.length };
  };

  const customerTransactions = selectedCustomer 
    ? sales.filter(s => s.customerId === selectedCustomer.id).sort((a,b) => b.timestamp.localeCompare(a.timestamp))
    : [];

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center no-print">
        <div>
          <h2 className="text-3xl font-bold text-slate-800 font-brand">Customer Directory</h2>
          <p className="text-slate-500">Manage client profiles and service preferences.</p>
        </div>
        <button 
          onClick={() => setIsAdding(true)}
          className="bg-slate-900 text-white px-6 py-3 rounded-xl font-bold flex items-center gap-2 hover:bg-slate-800 transition-all shadow-lg"
        >
          <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 6v6m0 0v6m0-6h6m-6 0H6"/></svg>
          New Client
        </button>
      </div>

      <div className="relative no-print">
        <svg className="w-5 h-5 absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z"/></svg>
        <input 
          type="text" 
          placeholder="Search by name or phone number..." 
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
          className="w-full bg-white border border-slate-200 rounded-2xl py-4 pl-12 pr-6 outline-none focus:ring-2 focus:ring-amber-400 shadow-sm"
        />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        {/* List of Customers */}
        <div className="lg:col-span-1 space-y-4 max-h-[80vh] overflow-y-auto pr-2 no-print">
          {filteredCustomers.map(customer => {
            const stats = getCustomerStats(customer.id);
            return (
              <div 
                key={customer.id} 
                onClick={() => setSelectedCustomer(customer)}
                className={`bg-white p-5 rounded-2xl border transition-all cursor-pointer flex justify-between items-center ${selectedCustomer?.id === customer.id ? 'border-amber-400 ring-2 ring-amber-100 shadow-md' : 'border-slate-100 hover:border-slate-200 shadow-sm'}`}
              >
                <div className="flex items-center gap-3">
                  <div className="w-10 h-10 rounded-full bg-slate-100 flex items-center justify-center text-slate-500 text-lg font-bold">
                    {customer.name.charAt(0)}
                  </div>
                  <div>
                    <h4 className="font-bold text-slate-800 text-sm">{customer.name}</h4>
                    <p className="text-[10px] text-slate-400 font-bold uppercase tracking-tight">{customer.phone}</p>
                  </div>
                </div>
                <div className="text-right">
                    <p className="text-[10px] text-slate-400 uppercase font-bold tracking-widest">Visits</p>
                    <p className="text-xs font-bold text-amber-600">{stats.visitCount}</p>
                </div>
              </div>
            );
          })}
        </div>

        {/* Selected Customer Profile & History */}
        <div className="lg:col-span-2 space-y-6">
          {selectedCustomer ? (
            <>
              {/* Profile Card */}
              <div className="bg-white rounded-3xl border border-slate-100 shadow-sm p-8">
                <div className="flex flex-col md:flex-row gap-8 items-start">
                  <div className="text-center w-full md:w-1/3 md:border-r border-slate-100 pr-0 md:pr-8">
                    <div className="w-24 h-24 rounded-full bg-amber-100 text-amber-600 flex items-center justify-center text-4xl font-bold mx-auto mb-4">
                      {selectedCustomer.name.charAt(0)}
                    </div>
                    <h3 className="text-2xl font-bold text-slate-800">{selectedCustomer.name}</h3>
                    <p className="text-slate-400 text-sm mb-4">{selectedCustomer.email || 'No email provided'}</p>
                    <div className="flex flex-wrap justify-center gap-2">
                      <span className="px-3 py-1 bg-emerald-50 text-emerald-600 rounded-full text-[10px] font-black uppercase tracking-wider">Member</span>
                      {getCustomerStats(selectedCustomer.id).visitCount > 5 && (
                        <span className="px-3 py-1 bg-amber-50 text-amber-600 rounded-full text-[10px] font-black uppercase tracking-wider">VIP</span>
                      )}
                    </div>
                  </div>

                  <div className="flex-1 w-full space-y-6">
                    <div className="grid grid-cols-2 gap-4">
                      <div className="bg-slate-50 p-4 rounded-xl">
                        <p className="text-[10px] text-slate-400 uppercase font-black tracking-widest mb-1">Lifetime Spend</p>
                        <p className="text-xl font-black text-slate-800">{currency}{getCustomerStats(selectedCustomer.id).totalSpent.toFixed(2)}</p>
                      </div>
                      <div className="bg-slate-50 p-4 rounded-xl">
                        <p className="text-[10px] text-slate-400 uppercase font-black tracking-widest mb-1">Last Visit</p>
                        <p className="text-xl font-black text-slate-800">{getCustomerStats(selectedCustomer.id).lastVisit}</p>
                      </div>
                    </div>

                    <div>
                      <h5 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">Style Notes & Preferences</h5>
                      <div className="bg-amber-50/50 p-5 rounded-2xl border border-amber-100 text-amber-900 text-sm leading-relaxed italic">
                        {selectedCustomer.notes || 'No notes on file for this client.'}
                      </div>
                    </div>
                  </div>
                </div>
              </div>

              {/* Detailed Transaction History */}
              <div className="bg-white rounded-3xl border border-slate-100 shadow-sm overflow-hidden">
                <div className="px-8 py-6 border-b border-slate-50 bg-slate-50/30 flex justify-between items-center">
                  <h4 className="text-lg font-bold text-slate-800">Complete Purchase History</h4>
                  <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{customerTransactions.length} Transactions</span>
                </div>

                <div className="overflow-x-auto">
                  <table className="w-full text-left border-collapse">
                    <thead>
                      <tr className="bg-slate-50/50 border-b border-slate-100">
                        <th className="px-8 py-4 text-[10px] font-black text-slate-400 uppercase tracking-widest">Date & ID</th>
                        <th className="px-8 py-4 text-[10px] font-black text-slate-400 uppercase tracking-widest">Items Purchased</th>
                        <th className="px-8 py-4 text-[10px] font-black text-slate-400 uppercase tracking-widest text-right">Total Amount</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-50">
                      {customerTransactions.map((sale) => (
                        <tr key={sale.id} className="hover:bg-slate-50/50 transition-colors">
                          <td className="px-8 py-6">
