                      <svg className="w-12 h-12 mx-auto mb-4 opacity-10" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 00-2 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2"/></svg>
                      No purchases recorded for this customer yet.
                    </div>
                  )}
                </div>
              </div>
            </>
          ) : (
            <div className="bg-white rounded-3xl border border-slate-200 border-dashed h-[60vh] flex flex-col items-center justify-center text-slate-400">
              <svg className="w-20 h-20 mb-6 opacity-10" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M17 20h5v-2a3 3 0 00-5.356-1.857M17 20H7m10 0v-2c0-.656-.126-1.283-.356-1.857M7 20H2v-2a3 3 0 015.356-1.857M7 20v-2c0-.656.126-1.283.356-1.857m0 0a5.002 5.002 0 019.288 0M15 7a3 3 0 11-6 0 3 3 0 016 0zm6 3a2 2 0 11-4 0 2 2 0 014 0zM7 10a2 2 0 11-4 0 2 2 0 014 0z"/></svg>
              <h3 className="text-xl font-bold text-slate-500">Client Profile</h3>
              <p className="text-sm">Select a customer from the directory to view their details and history.</p>
            </div>
          )}
        </div>
      </div>

      {/* Modal for adding new customer */}
      {isAdding && (
        <div className="fixed inset-0 bg-slate-900/50 backdrop-blur-sm z-50 flex items-center justify-center p-4 no-print">
          <div className="bg-white rounded-3xl w-full max-w-md p-8 shadow-2xl">
            <h3 className="text-2xl font-bold text-slate-800 mb-6">Register New Client</h3>
            <div className="space-y-4">
              <div>
                <label className="text-xs font-bold text-slate-400 uppercase block mb-1">Full Name</label>
                <input 
                  type="text" 
                  value={newCust.name}
                  onChange={e => setNewCust({...newCust, name: e.target.value})}
                  className="w-full bg-slate-50 border-0 rounded-xl px-4 py-3 focus:ring-2 focus:ring-amber-400 outline-none" 
                />
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="text-xs font-bold text-slate-400 uppercase block mb-1">Phone</label>
                  <input 
                    type="tel" 
                    value={newCust.phone}
                    onChange={e => setNewCust({...newCust, phone: e.target.value})}
                    className="w-full bg-slate-50 border-0 rounded-xl px-4 py-3 focus:ring-2 focus:ring-amber-400 outline-none" 
                  />
                </div>
                <div>
                  <label className="text-xs font-bold text-slate-400 uppercase block mb-1">Email</label>
                  <input 
                    type="email" 
                    value={newCust.email}
                    onChange={e => setNewCust({...newCust, email: e.target.value})}
                    className="w-full bg-slate-50 border-0 rounded-xl px-4 py-3 focus:ring-2 focus:ring-amber-400 outline-none" 
                  />
                </div>
              </div>
              <div>
                <label className="text-xs font-bold text-slate-400 uppercase block mb-1">Hair/Style Notes</label>
                <textarea 
                  value={newCust.notes}
                  onChange={e => setNewCust({...newCust, notes: e.target.value})}
                  className="w-full bg-slate-50 border-0 rounded-xl px-4 py-3 focus:ring-2 focus:ring-amber-400 outline-none h-24 resize-none"
                />
              </div>
              <div className="flex gap-4 mt-6">
                <button 
                  onClick={() => setIsAdding(false)}
                  className="flex-1 px-4 py-3 border border-slate-200 rounded-xl font-bold text-slate-400 hover:bg-slate-50 transition-all"
                >
                  Cancel
                </button>
                <button 
                  onClick={() => {
                    if(!newCust.name) return;
                    onAddCustomer({
                      id: 'c' + (customers.length + 1),
                      name: newCust.name,
                      phone: newCust.phone,
                      email: newCust.email,
                      notes: newCust.notes,
                      createdAt: new Date().toISOString().split('T')[0]
                    });
                    setIsAdding(false);
                    setNewCust({ name: '', phone: '', email: '', notes: '' });
                  }}
                  className="flex-1 px-4 py-3 bg-slate-900 text-white rounded-xl font-bold hover:bg-slate-800 transition-all shadow-lg"
                >
                  Create Profile
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default Customers;

