import React, { useState, useMemo } from 'react';
import { Service, Product, Staff, Sale, SaleItem, Customer, ShopSettings } from '../types';
import { INITIAL_DISCOUNT_CODES } from '../constants';
import { jsPDF } from 'jspdf';

interface POSProps {
  services: Service[];
  products: Product[];
  staff: Staff[];
  customers: Customer[];
  settings: ShopSettings;
  onCompleteSale: (sale: Sale) => void;
  onAddCustomer: (customer: Customer) => void;
}

const POS: React.FC<POSProps> = ({ services, products, staff, customers, settings, onCompleteSale, onAddCustomer }) => {
  const [cart, setCart] = useState<SaleItem[]>([]);
  const [selectedStaff, setSelectedStaff] = useState<string>('');
  const [selectedCustomer, setSelectedCustomer] = useState<string>('');
  const [discountCode, setDiscountCode] = useState<string>('');
  const [activeTab, setActiveTab] = useState<'services' | 'products'>('services');
  const [lastSale, setLastSale] = useState<Sale | null>(null);

  const addToCart = (item: Service | Product, type: 'service' | 'product') => {
    setCart(prev => {
      const existing = prev.find(i => i.id === item.id && i.type === type);
      if (existing) {
        return prev.map(i => i.id === item.id && i.type === type ? { ...i, quantity: i.quantity + 1 } : i);
      }
      return [...prev, { id: item.id, name: item.name, price: item.price, type, quantity: 1 }];
    });
  };

  const removeFromCart = (id: string, type: 'service' | 'product') => {
    setCart(prev => prev.filter(i => !(i.id === id && i.type === type)));
  };

  const appliedDiscount = useMemo(() => {
    const code = INITIAL_DISCOUNT_CODES.find(c => c.code === discountCode.toUpperCase());
    return code || null;
  }, [discountCode]);

  const subtotal = cart.reduce((acc, item) => acc + (item.price * item.quantity), 0);
  const discountAmount = appliedDiscount 
    ? (appliedDiscount.type === 'percentage' ? (subtotal * appliedDiscount.value / 100) : appliedDiscount.value)
    : 0;
  const tax = (subtotal - discountAmount) * (settings.taxRate / 100);
  const total = subtotal - discountAmount + tax;

  const handleComplete = () => {
    if (!selectedStaff || cart.length === 0) return;

    const sale: Sale = {
      id: Math.random().toString(36).substr(2, 9).toUpperCase(),
      timestamp: new Date().toISOString(),
      items: [...cart],
      staffId: selectedStaff,
      customerId: selectedCustomer || undefined,
      total: total,
      tax: tax,
      discount: discountAmount,
      discountCode: appliedDiscount?.code,
      paymentMethod: 'card'
    };

    onCompleteSale(sale);
    setLastSale(sale);
    setCart([]);
    setSelectedStaff('');
    setSelectedCustomer('');
    setDiscountCode('');
  };

  const generatePDF = (sale: Sale) => {
    const doc = new jsPDF({
      unit: 'mm',
      format: [80, 200] // Thermal printer format
    });

    const barber = staff.find(s => s.id === sale.staffId)?.name || 'N/A';
    const client = customers.find(c => c.id === sale.customerId)?.name || 'Guest Walk-in';
    const dateStr = new Date(sale.timestamp).toLocaleString();

    // Receipt Styling
    doc.setFont('helvetica', 'bold');
    doc.setFontSize(16);
    doc.text(settings.shopName.toUpperCase(), 40, 15, { align: 'center' });

    doc.setFontSize(8);
    doc.setFont('helvetica', 'normal');
    doc.text('Professional Grooming & Care', 40, 20, { align: 'center' });

    doc.setLineWidth(0.5);
    doc.line(5, 25, 75, 25);

    doc.setFontSize(7);
    doc.text(`DATE: ${dateStr}`, 5, 32);
    doc.text(`ORDER: #${sale.id}`, 5, 36);
    doc.text(`BARBER: ${barber}`, 5, 40);
    doc.text(`CLIENT: ${client}`, 5, 44);

    doc.line(5, 48, 75, 48);

    let y = 55;
    doc.setFont('helvetica', 'bold');
    doc.text('ITEM', 5, y);
    doc.text('QTY', 55, y);
    doc.text('PRICE', 75, y, { align: 'right' });

    doc.setFont('helvetica', 'normal');
    y += 5;
    sale.items.forEach(item => {
      doc.text(item.name.substring(0, 25), 5, y);
      doc.text(item.quantity.toString(), 55, y);
      doc.text(`${settings.currency}${(item.price * item.quantity).toFixed(2)}`, 75, y, { align: 'right' });
      y += 5;
    });

    doc.line(5, y, 75, y);
    y += 7;

    doc.text('SUBTOTAL:', 5, y);
    doc.text(`${settings.currency}${subtotal.toFixed(2)}`, 75, y, { align: 'right' });
    y += 5;

    if (sale.discount > 0) {
      doc.text('DISCOUNT:', 5, y);
      doc.text(`-${settings.currency}${sale.discount.toFixed(2)}`, 75, y, { align: 'right' });
      y += 5;
    }

    doc.text(`TAX (${settings.taxRate}%):`, 5, y);
    doc.text(`${settings.currency}${sale.tax.toFixed(2)}`, 75, y, { align: 'right' });
    y += 7;

    doc.setFontSize(10);
    doc.setFont('helvetica', 'bold');
    doc.text('TOTAL:', 5, y);
    doc.text(`${settings.currency}${sale.total.toFixed(2)}`, 75, y, { align: 'right' });

    y += 15;
    doc.setFontSize(8);
    doc.setFont('helvetica', 'italic');
    doc.text(settings.receiptFooter, 40, y, { align: 'center' });

    return doc;
  };

  const handleDownloadPDF = () => {
    if (!lastSale) return;
    const doc = generatePDF(lastSale);
    doc.save(`Receipt-${lastSale.id}.pdf`);
  };

  const handleShareReceipt = async () => {
    if (!lastSale) return;
    const summary = `${settings.shopName} Receipt\nOrder #${lastSale.id}\nTotal: ${settings.currency}${lastSale.total.toFixed(2)}\nThank you!`;

    if (navigator.share) {
      try {
        await navigator.share({
          title: `${settings.shopName} Receipt`,
          text: summary,
          url: window.location.href,
        });
      } catch (err) {
        console.error('Share failed:', err);
      }
    } else {
      navigator.clipboard.writeText(summary);
      alert('Receipt summary copied to clipboard!');
    }
  };

  const sendWhatsAppReceipt = (sale: Sale) => {
    const customer = customers.find(c => c.id === sale.customerId);
    const customerPhone = customer?.phone?.replace(/\D/g, '') || '';

    let message = `*${settings.shopName} Receipt*\n`;
    message += `Date: ${new Date(sale.timestamp).toLocaleDateString()}\n`;
    message += `Order ID: #${sale.id}\n`;
    message += `--------------------------\n`;
    sale.items.forEach(item => {
        message += `${item.quantity}x ${item.name} - ${settings.currency}${(item.price * item.quantity).toFixed(2)}\n`;
    });
    message += `--------------------------\n`;
    if (sale.discount > 0) message += `Discount: -${settings.currency}${sale.discount.toFixed(2)}\n`;
    message += `*Total: ${settings.currency}${sale.total.toFixed(2)}*\n\n`;
    message += `${settings.receiptFooter}`;

    const encodedMessage = encodeURIComponent(message);
    const whatsappUrl = `https://wa.me/${customerPhone}?text=${encodedMessage}`;
    window.open(whatsappUrl, '_blank');
  };

  return (
    <div className="flex flex-col lg:flex-row gap-8 h-[calc(100vh-160px)] relative">
      {/* Success Modal */}
      {lastSale && (
        <div className="fixed inset-0 bg-slate-900/50 backdrop-blur-md z-[100] flex items-center justify-center p-4 no-print">
            <div className="bg-white rounded-[2.5rem] p-10 max-w-sm w-full shadow-2xl text-center space-y-6">
                <div className="w-20 h-20 bg-emerald-100 text-emerald-600 rounded-full flex items-center justify-center text-4xl mx-auto">✓</div>
                <div>
                    <h3 className="text-2xl font-black text-slate-800">Sale Confirmed</h3>
                    <p className="text-slate-400">Transaction #{lastSale.id} completed successfully.</p>
                </div>
                <div className="flex flex-col gap-3">
                    <button 
                        onClick={handleDownloadPDF}
                        className="w-full bg-slate-900 text-white py-4 rounded-2xl font-black flex items-center justify-center gap-2 hover:bg-slate-800 transition-all shadow-lg"
                    >
                        <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M7 21h10a2 2 0 002-2V9.414a1 1 0 00-.293-.707l-5.414-5.414A1 1 0 0012.586 3H7a2 2 0 00-2 2v14a2 2 0 002 2z"/></svg>
                        Download PDF Receipt
                    </button>

                    <button 
                        onClick={handleShareReceipt}
                        className="w-full bg-blue-500 text-white py-4 rounded-2xl font-black flex items-center justify-center gap-2 hover:bg-blue-600 transition-all"
                    >
                        <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M8.684 13.342C8.886 12.938 9 12.482 9 12c0-.482-.114-.938-.316-1.342m0 2.684a3 3 0 110-2.684m0 2.684l6.632 3.316m-6.632-6l6.632-3.316m0 0a3 3 0 105.367-2.684 3 3 0 00-5.367 2.684zm0 9.316a3 3 0 105.368 2.684 3 3 0 00-5.368-2.684z"/></svg>
                        Share Receipt
                    </button>

                    {settings.whatsappEnabled && (
                        <button 
                            onClick={() => sendWhatsAppReceipt(lastSale)}
                            className="w-full bg-emerald-500 text-white py-4 rounded-2xl font-black flex items-center justify-center gap-2 hover:bg-emerald-600 transition-all"
                        >
                            <svg className="w-5 h-5" fill="currentColor" viewBox="0 0 24 24"><path d="M.057 24l1.687-6.163c-1.041-1.804-1.588-3.849-1.587-5.946.003-6.556 5.338-11.891 11.893-11.891 3.181.001 6.167 1.24 8.413 3.488 2.246 2.248 3.484 5.232 3.484 8.412-.003 6.557-5.338 11.892-11.893 11.892-1.997-.001-3.951-.5-5.688-1.448l-6.309 1.656zm6.224-3.52c1.54.914 3.453 1.403 5.385 1.404h.005c5.632 0 10.211-4.579 10.214-10.211 0-2.729-1.063-5.295-2.993-7.225s-4.496-2.992-7.225-2.993c-5.633 0-10.213 4.58-10.214 10.214 0 2.022.529 3.996 1.531 5.74l-.991 3.618 3.707-.972zm11.233-5.62c-.301-.151-1.782-.879-2.057-.979-.275-.1-.475-.151-.675.151s-.777.979-.952 1.179-.35.225-.65.076c-.301-.151-1.268-.467-2.417-1.492-.892-.795-1.494-1.777-1.669-2.078-.175-.301-.019-.463.131-.613.135-.134.301-.351.451-.526s.201-.3.301-.5c.101-.201.05-.376-.025-.526s-.675-1.629-.925-2.229c-.244-.583-.491-.504-.675-.513-.175-.008-.376-.01-.576-.01s-.526.076-.801.376c-.275.301-1.051 1.028-1.051 2.508s1.076 2.908 1.226 3.109c.151.201 2.118 3.235 5.132 4.537.717.309 1.277.494 1.714.633.72.228 1.375.196 1.892.119.577-.085 1.782-.728 2.032-1.429s.25-.151.25-.376-.101-.351-.401-.502z"/></svg>
                            WhatsApp Receipt
                        </button>
                    )}

                    <button 
                        onClick={() => setLastSale(null)}
                        className="w-full bg-slate-100 text-slate-600 py-4 rounded-2xl font-bold hover:bg-slate-200 transition-all mt-4"
                    >
                        Close
                    </button>
                </div>
            </div>
        </div>
      )}

      {/* POS UI */}
      <div className="flex-1 flex flex-col min-w-0">
        <div className="flex items-center gap-4 mb-6">
          <button 
            onClick={() => setActiveTab('services')}
            className={`px-8 py-3 rounded-2xl font-bold transition-all ${activeTab === 'services' ? 'bg-amber-500 text-slate-900 shadow-md' : 'bg-white text-slate-400 border border-slate-100'}`}
          >
            Services
          </button>
          <button 
            onClick={() => setActiveTab('products')}
            className={`px-8 py-3 rounded-2xl font-bold transition-all ${activeTab === 'products' ? 'bg-amber-500 text-slate-900 shadow-md' : 'bg-white text-slate-400 border border-slate-100'}`}
          >
            Retail Products
          </button>
        </div>

        <div className="grid grid-cols-2 md:grid-cols-3 xl:grid-cols-4 gap-4 overflow-y-auto pr-2 pb-8">
          {activeTab === 'services' ? services.map(s => (
            <button key={s.id} onClick={() => addToCart(s, 'service')} className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm hover:border-amber-400 hover:shadow-md transition-all text-left group">
                <div className="w-10 h-10 bg-amber-50 rounded-xl flex items-center justify-center text-amber-500 mb-4 group-hover:bg-amber-500 group-hover:text-white transition-colors text-xs font-black">{s.category.charAt(0)}</div>
                <h4 className="font-bold text-slate-800 text-sm mb-1">{s.name}</h4>
                <p className="text-lg font-black text-slate-900">{settings.currency}{s.price}</p>
                <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest mt-2">{s.duration} min</p>
            </button>
          )) : products.map(p => (
            <button key={p.id} onClick={() => addToCart(p, 'product')} className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm hover:border-amber-400 hover:shadow-md transition-all text-left group">
                <div className="w-10 h-10 bg-blue-50 rounded-xl flex items-center justify-center text-blue-500 mb-4 group-hover:bg-blue-500 group-hover:text-white transition-colors text-xs font-black">P</div>
                <h4 className="font-bold text-slate-800 text-sm mb-1">{p.name}</h4>
                <p className="text-lg font-black text-slate-900">{settings.currency}{p.price}</p>
                <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest mt-2">{p.stock} in stock</p>
            </button>
          ))}
        </div>
      </div>

      <div className="w-full lg:w-[400px] bg-white rounded-[2.5rem] border border-slate-100 shadow-sm flex flex-col overflow-hidden">
        <div className="p-8 border-b border-slate-50">
          <h3 className="text-xl font-bold text-slate-800">Checkout Cart</h3>
        </div>

        <div className="flex-1 overflow-y-auto p-8 space-y-4">
          {cart.map(item => (
            <div key={`${item.id}-${item.type}`} className="flex justify-between items-center group">
              <div className="flex-1">
                <p className="text-sm font-bold text-slate-800">{item.name}</p>
                <p className="text-xs text-slate-400">{item.quantity}x {settings.currency}{item.price}</p>
              </div>
              <div className="flex items-center gap-3">
                <p className="font-bold text-slate-800">{settings.currency}{(item.price * item.quantity).toFixed(2)}</p>
                <button onClick={() => removeFromCart(item.id, item.type)} className="text-rose-400 hover:text-rose-600 opacity-0 group-hover:opacity-100 transition-opacity">
                  <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"/></svg>
                </button>
              </div>
            </div>
          ))}
          {cart.length === 0 && (
            <div className="flex flex-col items-center justify-center h-full text-slate-300 italic py-10">
              <p>Cart is empty</p>
            </div>
          )}
        </div>

        <div className="p-8 bg-slate-50 space-y-4">
          <div className="space-y-2">
            <select value={selectedStaff} onChange={e => setSelectedStaff(e.target.value)} className="w-full bg-white border-0 rounded-xl px-4 py-3 text-sm focus:ring-2 focus:ring-amber-400 outline-none">
                <option value="">Select Barber</option>
                {staff.map(s => <option key={s.id} value={s.id}>{s.name}</option>)}
            </select>
            <select value={selectedCustomer} onChange={e => setSelectedCustomer(e.target.value)} className="w-full bg-white border-0 rounded-xl px-4 py-3 text-sm focus:ring-2 focus:ring-amber-400 outline-none">
                <option value="">Select Customer (Optional)</option>
                {customers.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
            </select>
            <input type="text" placeholder="Discount Code" value={discountCode} onChange={e => setDiscountCode(e.target.value)} className="w-full bg-white border-0 rounded-xl px-4 py-3 text-sm focus:ring-2 focus:ring-amber-400 outline-none uppercase" />
          </div>

          <div className="space-y-1 pt-4 border-t border-slate-200">
            <div className="flex justify-between text-sm text-slate-500"><span>Subtotal</span><span>{settings.currency}{subtotal.toFixed(2)}</span></div>
            {discountAmount > 0 && <div className="flex justify-between text-sm text-emerald-600"><span>Discount</span><span>-{settings.currency}{discountAmount.toFixed(2)}</span></div>}
            <div className="flex justify-between text-sm text-slate-500"><span>Tax ({settings.taxRate}%)</span><span>{settings.currency}{tax.toFixed(2)}</span></div>
            <div className="flex justify-between text-xl font-black text-slate-900 pt-2"><span>Total</span><span>{settings.currency}{total.toFixed(2)}</span></div>
          </div>

          <button onClick={handleComplete} disabled={!selectedStaff || cart.length === 0} className="w-full bg-slate-900 text-white py-4 rounded-2xl font-black text-lg hover:bg-slate-800 transition-all shadow-xl disabled:opacity-50 mt-2">Complete Checkout</button>
        </div>
      </div>
    </div>
  );
};

