import React, { useState } from 'react';
import { Service, Product, ShopSettings } from '../types';

interface InventoryProps {
  services: Service[];
  products: Product[];
  settings: ShopSettings;
  onUpdateServices: (services: Service[]) => void;
  onUpdateProducts: (products: Product[]) => void;
}

const Inventory: React.FC<InventoryProps> = ({ services, products, settings, onUpdateServices, onUpdateProducts }) => {
  const [activeTab, setActiveTab] = useState<'services' | 'products'>('services');
  const [isEditing, setIsEditing] = useState<any>(null);

  const deleteItem = (id: string, type: 'service' | 'product') => {
    if (!confirm('Are you sure you want to remove this item?')) return;
    if (type === 'service') {
      onUpdateServices(services.filter(s => s.id !== id));
    } else {
      onUpdateProducts(products.filter(p => p.id !== id));
    }
  };

  const saveItem = (e: React.FormEvent) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget as HTMLFormElement);
    const itemData = Object.fromEntries(formData.entries());

    if (activeTab === 'services') {
      const newService: Service = {
        id: isEditing?.id || Math.random().toString(36).substr(2, 9),
        name: itemData.name as string,
        price: parseFloat(itemData.price as string),
        duration: parseInt(itemData.duration as string),
        category: itemData.category as string,
      };
      if (isEditing) {
        onUpdateServices(services.map(s => s.id === isEditing.id ? newService : s));
      } else {
        onUpdateServices([...services, newService]);
      }
    } else {
      const newProduct: Product = {
        id: isEditing?.id || Math.random().toString(36).substr(2, 9),
        name: itemData.name as string,
        price: parseFloat(itemData.price as string),
        cost: parseFloat(itemData.cost as string),
        stock: parseInt(itemData.stock as string),
      };
      if (isEditing) {
        onUpdateProducts(products.map(p => p.id === isEditing.id ? newProduct : p));
      } else {
        onUpdateProducts([...products, newProduct]);
      }
    }
    setIsEditing(null);
  };

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <div>
          <h2 className="text-3xl font-bold text-slate-800 font-brand">Shop Catalog</h2>
          <p className="text-slate-500">Manage your services and retail inventory.</p>
        </div>
        <button 
          onClick={() => setIsEditing({})}
          className="bg-slate-900 text-white px-6 py-3 rounded-xl font-bold flex items-center gap-2 hover:bg-slate-800 transition-all shadow-lg"
        >
          <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 6v6m0 0v6m0-6h6m-6 0H6"/></svg>
          Add {activeTab === 'services' ? 'Service' : 'Product'}
        </button>
      </div>

      <div className="flex gap-4">
        <button 
          onClick={() => setActiveTab('services')}
          className={`px-8 py-3 rounded-2xl font-bold transition-all ${activeTab === 'services' ? 'bg-amber-500 text-slate-900 shadow-md' : 'bg-white text-slate-400'}`}
        >
          Services
        </button>
        <button 
          onClick={() => setActiveTab('products')}
          className={`px-8 py-3 rounded-2xl font-bold transition-all ${activeTab === 'products' ? 'bg-amber-500 text-slate-900 shadow-md' : 'bg-white text-slate-400'}`}
        >
          Products
        </button>
      </div>

      <div className="bg-white rounded-3xl border border-slate-100 shadow-sm overflow-hidden">
        <table className="w-full text-left">
          <thead>
            <tr className="bg-slate-50/50 border-b border-slate-100">
              <th className="px-8 py-4 text-[10px] font-black text-slate-400 uppercase tracking-widest">Name</th>
              <th className="px-8 py-4 text-[10px] font-black text-slate-400 uppercase tracking-widest">{activeTab === 'services' ? 'Category / Duration' : 'Cost / Stock'}</th>
              <th className="px-8 py-4 text-[10px] font-black text-slate-400 uppercase tracking-widest">Price</th>
              <th className="px-8 py-4 text-[10px] font-black text-slate-400 uppercase tracking-widest text-right">Actions</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-50">
            {activeTab === 'services' ? (
              services.map(s => (
                <tr key={s.id} className="hover:bg-slate-50/30 transition-colors">
                  <td className="px-8 py-5">
                    <p className="font-bold text-slate-800">{s.name}</p>
                    <p className="text-xs text-slate-400">ID: {s.id}</p>
                  </td>
                  <td className="px-8 py-5">
                    <span className="px-2 py-1 bg-amber-50 text-amber-700 rounded text-[10px] font-black uppercase mr-2">{s.category}</span>
                    <span className="text-xs text-slate-400">{s.duration} min</span>
                  </td>
                  <td className="px-8 py-5 font-black text-slate-800">{settings.currency}{s.price}</td>
                  <td className="px-8 py-5 text-right space-x-2">
                    <button onClick={() => setIsEditing(s)} className="p-2 text-slate-300 hover:text-amber-500 transition-colors"><svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z"/></svg></button>
                    <button onClick={() => deleteItem(s.id, 'service')} className="p-2 text-slate-300 hover:text-rose-500 transition-colors">
                      <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"/></svg>
                    </button>
                  </td>
                </tr>
              ))
            ) : (
              products.map(p => (
                <tr key={p.id} className="hover:bg-slate-50/30 transition-colors">
                  <td className="px-8 py-5">
                    <p className="font-bold text-slate-800">{p.name}</p>
                    <p className="text-xs text-slate-400">ID: {p.id}</p>
                  </td>
                  <td className="px-8 py-5">
                    <p className="text-sm font-bold text-slate-800">Cost: {settings.currency}{p.cost}</p>
                    <p className={`text-xs font-bold ${p.stock < 10 ? 'text-rose-500' : 'text-slate-400'}`}>Stock: {p.stock}</p>
                  </td>
                  <td className="px-8 py-5 font-black text-slate-800">{settings.currency}{p.price}</td>
                  <td className="px-8 py-5 text-right space-x-2">
                    <button onClick={() => setIsEditing(p)} className="p-2 text-slate-300 hover:text-amber-500 transition-colors"><svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z"/></svg></button>
                    <button onClick={() => deleteItem(p.id, 'product')} className="p-2 text-slate-300 hover:text-rose-500 transition-colors">
                      <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"/></svg>
                    </button>
                  </td>
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>

      {isEditing && (
        <div className="fixed inset-0 bg-slate-900/50 backdrop-blur-sm z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-3xl w-full max-w-md p-8 shadow-2xl">
            <h3 className="text-2xl font-bold text-slate-800 mb-6">{isEditing.id ? 'Edit' : 'Add'} {activeTab === 'services' ? 'Service' : 'Product'}</h3>
            <form onSubmit={saveItem} className="space-y-4">
              <div>
                <label className="text-xs font-bold text-slate-400 uppercase block mb-1">Name</label>
                <input name="name" type="text" defaultValue={isEditing.name || ''} required className="w-full bg-slate-50 border-0 rounded-xl px-4 py-3 focus:ring-2 focus:ring-amber-400 outline-none" />
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="text-xs font-bold text-slate-400 uppercase block mb-1">Price</label>
                  <input name="price" type="number" step="0.01" defaultValue={isEditing.price || ''} required className="w-full bg-slate-50 border-0 rounded-xl px-4 py-3 focus:ring-2 focus:ring-amber-400 outline-none" />
                </div>
                {activeTab === 'services' ? (
                  <div>
                    <label className="text-xs font-bold text-slate-400 uppercase block mb-1">Duration (min)</label>
                    <input name="duration" type="number" defaultValue={isEditing.duration || 30} required className="w-full bg-slate-50 border-0 rounded-xl px-4 py-3 focus:ring-2 focus:ring-amber-400 outline-none" />
                  </div>
                ) : (
                  <div>
                    <label className="text-xs font-bold text-slate-400 uppercase block mb-1">Cost</label>
                    <input name="cost" type="number" step="0.01" defaultValue={isEditing.cost || ''} required className="w-full bg-slate-50 border-0 rounded-xl px-4 py-3 focus:ring-2 focus:ring-amber-400 outline-none" />
                  </div>
                )}
              </div>
              {activeTab === 'services' ? (
                <div>
                  <label className="text-xs font-bold text-slate-400 uppercase block mb-1">Category</label>
                  <input name="category" type="text" defaultValue={isEditing.category || ''} required className="w-full bg-slate-50 border-0 rounded-xl px-4 py-3 focus:ring-2 focus:ring-amber-400 outline-none" />
                </div>
              ) : (
                <div>
                  <label className="text-xs font-bold text-slate-400 uppercase block mb-1">Stock</label>
                  <input name="stock" type="number" defaultValue={isEditing.stock || 0} required className="w-full bg-slate-50 border-0 rounded-xl px-4 py-3 focus:ring-2 focus:ring-amber-400 outline-none" />
                </div>
              )}
              <div className="flex gap-4 mt-6">
                <button type="button" onClick={() => setIsEditing(null)} className="flex-1 px-4 py-3 border border-slate-200 rounded-xl font-bold text-slate-400">Cancel</button>
                <button type="submit" className="flex-1 px-4 py-3 bg-slate-900 text-white rounded-xl font-bold">Save</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

