          <h2 className="text-xl font-bold text-white mb-6">Staff Access</h2>

          <form onSubmit={handleLogin} className="space-y-4">
            <div>
              <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest block mb-2 ml-1">Username</label>
              <input 
