              />
            </div>

            <div>
              <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest block mb-2 ml-1">Password</label>
              <input 
                type="password" 
                value={password}
                onChange={e => setPassword(e.target.value)}
                placeholder="••••"
                className="w-full bg-slate-800/50 border border-slate-700 text-white rounded-2xl px-5 py-4 focus:ring-2 focus:ring-amber-500 outline-none transition-all placeholder:text-slate-600"
                required
              />
            </div>

            {error && (
              <div className="bg-rose-500/10 border border-rose-500/20 text-rose-500 text-xs py-3 px-4 rounded-xl font-medium animate-pulse">
                {error}
              </div>
            )}

            <button 
              type="submit" 
              className="w-full bg-amber-500 text-slate-950 font-black text-lg py-4 rounded-2xl hover:bg-amber-400 transition-all shadow-xl shadow-amber-500/10 active:scale-95 mt-2"
            >
              Unlock Terminal
            </button>
          </form>

          <p className="text-center text-slate-600 text-[10px] mt-8 uppercase tracking-widest font-bold">
            Authorized Personnel Only
          </p>
        </div>

        {/* Support Link */}
        <p className="text-center text-slate-500 text-sm mt-8">
          Forgot your credentials? <span className="text-amber-500 font-bold cursor-pointer hover:underline">Contact Manager</span>
        </p>
      </div>
    </div>
  );
