import React, { useState } from 'react';
import { Staff, UserRole } from '../types';

interface StaffManagementProps {
  staffList: Staff[];
  onUpdateStaff: (staff: Staff[]) => void;
  currentUser: Staff;
}

const StaffManagement: React.FC<StaffManagementProps> = ({ staffList, onUpdateStaff, currentUser }) => {
  const [isAdding, setIsAdding] = useState(false);
  const [editingStaff, setEditingStaff] = useState<Staff | null>(null);
  const [formData, setFormData] = useState({
    name: '',
    username: '',
    password: '',
    role: 'employee' as UserRole,
    commission: 30
  });

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (editingStaff) {
      const updatedList = staffList.map(s => s.id === editingStaff.id ? { ...editingStaff, ...formData } : s);
      onUpdateStaff(updatedList);
    } else {
      const newStaff: Staff = {
        id: Math.random().toString(36).substr(2, 9).toUpperCase(),
        ...formData
      };
      onUpdateStaff([...staffList, newStaff]);
    }
    resetForm();
  };

  const resetForm = () => {
    setIsAdding(false);
    setEditingStaff(null);
    setFormData({ name: '', username: '', password: '', role: 'employee', commission: 30 });
  };

  const deleteStaff = (id: string) => {
    if (id === currentUser.id) {
      alert("You cannot delete your own admin account.");
      return;
    }
    if (confirm('Permanently remove this staff member?')) {
      onUpdateStaff(staffList.filter(s => s.id !== id));
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <div>
          <h2 className="text-3xl font-bold text-slate-800 font-brand">Staff Management</h2>
          <p className="text-slate-500">Manage employee accounts and access levels.</p>
        </div>
        <button 
          onClick={() => setIsAdding(true)}
          className="bg-slate-900 text-white px-6 py-3 rounded-xl font-bold flex items-center gap-2 hover:bg-slate-800 transition-all shadow-lg"
        >
          <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M18 9v3m0 0v3m0-3h3m-3 0h-3m-2-5a4 4 0 11-8 0 4 4 0 018 0zM3 20a6 6 0 0112 0v1H3v-1z"/></svg>
          Add Staff Member
        </button>
      </div>

      <div className="bg-white rounded-[2.5rem] border border-slate-100 shadow-sm overflow-hidden">
        <table className="w-full text-left">
          <thead>
            <tr className="bg-slate-50/50 border-b border-slate-100">
              <th className="px-8 py-4 text-[10px] font-black text-slate-400 uppercase tracking-widest">Name & ID</th>
              <th className="px-8 py-4 text-[10px] font-black text-slate-400 uppercase tracking-widest">Login Username</th>
              <th className="px-8 py-4 text-[10px] font-black text-slate-400 uppercase tracking-widest">Role</th>
              <th className="px-8 py-4 text-[10px] font-black text-slate-400 uppercase tracking-widest">Commission</th>
              <th className="px-8 py-4 text-[10px] font-black text-slate-400 uppercase tracking-widest text-right">Actions</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-50">
            {staffList.map(staff => (
              <tr key={staff.id} className="hover:bg-slate-50/30 transition-colors">
                <td className="px-8 py-5">
                  <div className="flex items-center gap-3">
                    <div className="w-10 h-10 rounded-full bg-slate-100 flex items-center justify-center font-bold text-slate-500 uppercase">
                      {staff.name.charAt(0)}
                    </div>
                    <div>
                      <p className="font-bold text-slate-800">{staff.name}</p>
                      <p className="text-[10px] text-slate-400 font-mono">{staff.id}</p>
                    </div>
                  </div>
                </td>
                <td className="px-8 py-5 text-sm font-medium text-slate-600">{staff.username}</td>
                <td className="px-8 py-5">
                  <span className={`px-3 py-1 rounded-full text-[10px] font-black uppercase tracking-wider ${staff.role === 'admin' ? 'bg-amber-100 text-amber-600' : 'bg-blue-100 text-blue-600'}`}>
                    {staff.role}
                  </span>
                </td>
                <td className="px-8 py-5 font-bold text-slate-800">{staff.commission}%</td>
                <td className="px-8 py-5 text-right space-x-2">
                  <button 
                    onClick={() => {
                      setEditingStaff(staff);
                      setFormData({ 
                        name: staff.name, 
                        username: staff.username, 
                        password: staff.password || '', 
