};

export default StaffManagement;

import React, { useState, useEffect } from 'react';
import Sidebar from './components/Sidebar';
import Dashboard from './components/Dashboard';
import POS from './components/POS';
import Finance from './components/Finance';
import Customers from './components/Customers';
import Settings from './components/Settings';
import Inventory from './components/Inventory';
import StaffManagement from './components/StaffManagement';
import Login from './components/Login';
import { View, Sale, Expense, Service, Product, Staff, Customer, ShopSettings } from './types';
import { INITIAL_SERVICES, INITIAL_PRODUCTS, INITIAL_STAFF, INITIAL_EXPENSES, INITIAL_CUSTOMERS, DEFAULT_SETTINGS } from './constants';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<Staff | null>(() => {
    const saved = localStorage.getItem('trimtime_session');
    return saved ? JSON.parse(saved) : null;
  });

  const [currentView, setCurrentView] = useState<View>(View.DASHBOARD);
  const [sales, setSales] = useState<Sale[]>([]);
  const [expenses, setExpenses] = useState<Expense[]>(INITIAL_EXPENSES);
  const [customers, setCustomers] = useState<Customer[]>(INITIAL_CUSTOMERS);
  const [services, setServices] = useState<Service[]>(INITIAL_SERVICES);
  const [products, setProducts] = useState<Product[]>(INITIAL_PRODUCTS);
  const [staffList, setStaffList] = useState<Staff[]>(INITIAL_STAFF);
  const [settings, setSettings] = useState<ShopSettings>(DEFAULT_SETTINGS);

  useEffect(() => {
    if (currentUser) {
      localStorage.setItem('trimtime_session', JSON.stringify(currentUser));
    } else {
      localStorage.removeItem('trimtime_session');
    }
  }, [currentUser]);

  const handleLogin = (user: Staff) => {
    setCurrentUser(user);
    setCurrentView(View.DASHBOARD);
  };

  const handleLogout = () => {
    setCurrentUser(null);
  };

  const handleCompleteSale = (sale: Sale) => {
    setSales(prev => [...prev, sale]);

    // Update product stock if products were sold
    setProducts(prevProducts => prevProducts.map(p => {
        const cartItem = sale.items.find(item => item.id === p.id && item.type === 'product');
        if (cartItem) {
            return { ...p, stock: Math.max(0, p.stock - cartItem.quantity) };
        }
        return p;
    }));
  };

  const renderView = () => {
    if (!currentUser) return null;

    // Restriction Logic
    if (currentUser.role !== 'admin' && [View.FINANCE, View.SETTINGS, View.INVENTORY, View.STAFF].includes(currentView)) {
        setCurrentView(View.DASHBOARD);
        return null;
    }

    switch (currentView) {
      case View.DASHBOARD:
        return <Dashboard sales={sales} expenses={expenses} currency={settings.currency} />;
      case View.POS:
        return (
          <POS 
            services={services} 
            products={products} 
            staff={staffList} 
            customers={customers}
            settings={settings}
            onCompleteSale={handleCompleteSale} 
            onAddCustomer={(c) => setCustomers([...customers, c])}
          />
        );
      case View.FINANCE:
        return (
          <Finance 
            sales={sales} 
            expenses={expenses} 
            onAddExpense={(e) => setExpenses([...expenses, e])} 
            currency={settings.currency}
          />
        );
      case View.CUSTOMERS:
        return (
          <Customers 
            customers={customers}
            sales={sales}
            onAddCustomer={(c) => setCustomers([...customers, c])}
            currency={settings.currency}
          />
        );
      case View.INVENTORY:
        return (
          <Inventory 
            services={services}
            products={products}
            settings={settings}
            onUpdateServices={setServices}
            onUpdateProducts={setProducts}
          />
        );
      case View.STAFF:
        return (
          <StaffManagement 
            staffList={staffList}
            onUpdateStaff={setStaffList}
            currentUser={currentUser}
          />
        );
      case View.SETTINGS:
        return (
          <Settings 
            settings={settings}
            onUpdateSettings={setSettings}
          />
        );
      default:
        return null;
    }
  };

  if (!currentUser) {
    return <Login onLogin={handleLogin} staffList={staffList} />;
  }

  return (
    <div className="min-h-screen flex bg-slate-50">
      <Sidebar 
        currentView={currentView} 
        onViewChange={setCurrentView} 
        shopName={settings.shopName}
        userRole={currentUser.role}
      />

      <main className="flex-1 ml-64 p-8">
        <header className="mb-8 flex justify-between items-center no-print">
            <div className="bg-white px-4 py-2 rounded-xl shadow-sm border border-slate-100 flex items-center gap-2">
                <span className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse"></span>
                <span className="text-xs font-bold text-slate-500 uppercase tracking-widest">{settings.shopName} Terminal</span>
            </div>
            <div className="flex items-center gap-4">
                <div className="text-right mr-2">
                    <p className="text-xs font-black text-slate-800 uppercase tracking-tight">{currentUser.name}</p>
                    <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">{currentUser.role}</p>
                </div>
                <button 
                  onClick={handleLogout}
                  className="p-2 text-slate-400 hover:text-rose-500 transition-colors"
                  title="Logout"
                >
                  <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M17 16l4-4m0 0l-4-4m4 4H7m6 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h4a3 3 0 013 3v1"/></svg>
                </button>
                <div className="w-10 h-10 rounded-full bg-slate-200 border-2 border-white shadow-sm overflow-hidden">
                    <img src={`https://api.dicebear.com/7.x/avataaars/svg?seed=${currentUser.name}`} alt="Profile" />
                </div>
            </div>
        </header>

        {renderView()}
      </main>
    </div>
  );
};

export default App;

