  items: SaleItem[];
  staffId: string;
  customerId?: string;
  total: number;
  tax: number;
  discount: number;
  discountCode?: string;
  paymentMethod: 'cash' | 'card';
}

export interface HeldSale {
  id: string;
  timestamp: string;
  cart: SaleItem[];
  customerId?: string;
  staffId?: string;
}

export interface Expense {
