import React, { useState, useMemo, useEffect, useCallback } from 'react';
import { Service, Product, Staff, Sale, SaleItem, Customer, ShopSettings, HeldSale } from '../types';
import { INITIAL_DISCOUNT_CODES } from '../constants';
import { jsPDF } from 'jspdf';

interface POSProps {
  services: Service[];
  products: Product[];
  staff: Staff[];
  customers: Customer[];
  settings: ShopSettings;
  onCompleteSale: (sale: Sale) => void;
  onAddCustomer: (customer: Customer) => void;
}

const POS: React.FC<POSProps> = ({ services, products, staff, customers, settings, onCompleteSale, onAddCustomer }) => {
  const [cart, setCart] = useState<SaleItem[]>([]);
  const [selectedStaff, setSelectedStaff] = useState<string>('');
  const [selectedCustomer, setSelectedCustomer] = useState<string>('');
  const [discountCode, setDiscountCode] = useState<string>('');
  const [activeTab, setActiveTab] = useState<'services' | 'products'>('services');
  const [lastSale, setLastSale] = useState<Sale | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [heldSales, setHeldSales] = useState<HeldSale[]>([]);
  const [showScanner, setShowScanner] = useState(false);

  // Barcode Hardware Support (Keyboard Wedge)
  useEffect(() => {
    let barcodeBuffer = '';
    let lastKeyTime = Date.now();

    const handleKeyDown = (e: KeyboardEvent) => {
      const currentTime = Date.now();

      // Hardware scanners typically "type" very fast (< 30ms between keys)
      if (currentTime - lastKeyTime > 50) {
        barcodeBuffer = '';
      }

      if (e.key === 'Enter') {
        if (barcodeBuffer.length > 3) {
          const product = products.find(p => p.barcode === barcodeBuffer);
          if (product) {
            addToCart(product, 'product');
            // Visual feedback
            console.log('Barcode scanned:', barcodeBuffer);
          }
          barcodeBuffer = '';
        }
      } else if (e.key.length === 1) {
        barcodeBuffer += e.key;
      }

      lastKeyTime = currentTime;
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [products]);

  const addToCart = (item: Service | Product, type: 'service' | 'product') => {
    setCart(prev => {
      const existing = prev.find(i => i.id === item.id && i.type === type);
      if (existing) {
        return prev.map(i => i.id === item.id && i.type === type ? { ...i, quantity: i.quantity + 1 } : i);
      }
      return [...prev, { id: item.id, name: item.name, price: item.price, type, quantity: 1 }];
    });
  };

  const updateQuantity = (id: string, type: 'service' | 'product', delta: number) => {
    setCart(prev => prev.map(item => {
      if (item.id === id && item.type === type) {
        return { ...item, quantity: Math.max(1, item.quantity + delta) };
      }
      return item;
    }));
  };

  const removeFromCart = (id: string, type: 'service' | 'product') => {
    setCart(prev => prev.filter(i => !(i.id === id && i.type === type)));
  };

  const clearCart = () => setCart([]);

  const holdSale = () => {
    if (cart.length === 0) return;
    const newHeldSale: HeldSale = {
      id: Math.random().toString(36).substr(2, 5).toUpperCase(),
      timestamp: new Date().toISOString(),
      cart: [...cart],
      customerId: selectedCustomer,
      staffId: selectedStaff
    };
    setHeldSales([...heldSales, newHeldSale]);
    clearCart();
    setSelectedCustomer('');
    setSelectedStaff('');
  };

  const resumeSale = (held: HeldSale) => {
    setCart(held.cart);
    setSelectedCustomer(held.customerId || '');
    setSelectedStaff(held.staffId || '');
    setHeldSales(heldSales.filter(h => h.id !== held.id));
  };

  const appliedDiscount = useMemo(() => {
    const code = INITIAL_DISCOUNT_CODES.find(c => c.code === discountCode.toUpperCase());
    return code || null;
  }, [discountCode]);

  const subtotal = cart.reduce((acc, item) => acc + (item.price * item.quantity), 0);
  const discountAmount = appliedDiscount 
    ? (appliedDiscount.type === 'percentage' ? (subtotal * appliedDiscount.value / 100) : appliedDiscount.value)
    : 0;
  const tax = (subtotal - discountAmount) * (settings.taxRate / 100);
  const total = subtotal - discountAmount + tax;

  const handleComplete = (method: 'cash' | 'card') => {
    if (!selectedStaff || cart.length === 0) return;

    const sale: Sale = {
      id: Math.random().toString(36).substr(2, 9).toUpperCase(),
      timestamp: new Date().toISOString(),
      items: [...cart],
      staffId: selectedStaff,
      customerId: selectedCustomer || undefined,
      total: total,
      tax: tax,
      discount: discountAmount,
      discountCode: appliedDiscount?.code,
      paymentMethod: method
    };

    onCompleteSale(sale);
    setLastSale(sale);
    clearCart();
    setSelectedStaff('');
    setSelectedCustomer('');
    setDiscountCode('');
    setSearchTerm('');
  };

  const filteredItems = useMemo(() => {
    const term = searchTerm.toLowerCase();
    if (activeTab === 'services') {
      return services.filter(s => s.name.toLowerCase().includes(term) || s.category.toLowerCase().includes(term));
    } else {
      return products.filter(p => p.name.toLowerCase().includes(term) || p.barcode?.includes(term));
    }
  }, [searchTerm, activeTab, services, products]);

  const generatePDF = (sale: Sale) => {
    const doc = new jsPDF({ unit: 'mm', format: [80, 200] });
    const barber = staff.find(s => s.id === sale.staffId)?.name || 'N/A';
    const client = customers.find(c => c.id === sale.customerId)?.name || 'Guest Walk-in';
    const dateStr = new Date(sale.timestamp).toLocaleString();

    doc.setFont('helvetica', 'bold').setFontSize(16);
    doc.text(settings.shopName.toUpperCase(), 40, 15, { align: 'center' });
    doc.setFontSize(8).setFont('helvetica', 'normal').text('Professional Grooming & Care', 40, 20, { align: 'center' });
    doc.setLineWidth(0.5).line(5, 25, 75, 25);
    doc.setFontSize(7).text(`DATE: ${dateStr}`, 5, 32).text(`ORDER: #${sale.id}`, 5, 36).text(`BARBER: ${barber}`, 5, 40).text(`CLIENT: ${client}`, 5, 44);
    doc.line(5, 48, 75, 48);

    let y = 55;
    doc.setFont('helvetica', 'bold').text('ITEM', 5, y).text('QTY', 55, y).text('PRICE', 75, y, { align: 'right' });
    doc.setFont('helvetica', 'normal');
    y += 5;
    sale.items.forEach(item => {
      doc.text(item.name.substring(0, 25), 5, y);
      doc.text(item.quantity.toString(), 55, y);
      doc.text(`${settings.currency}${(item.price * item.quantity).toFixed(2)}`, 75, y, { align: 'right' });
      y += 5;
    });

    doc.line(5, y, 75, y); y += 7;
    doc.text('SUBTOTAL:', 5, y).text(`${settings.currency}${subtotal.toFixed(2)}`, 75, y, { align: 'right' }); y += 5;
    if (sale.discount > 0) { doc.text('DISCOUNT:', 5, y); doc.text(`-${settings.currency}${sale.discount.toFixed(2)}`, 75, y, { align: 'right' }); y += 5; }
    doc.text(`TAX (${settings.taxRate}%):`, 5, y).text(`${settings.currency}${sale.tax.toFixed(2)}`, 75, y, { align: 'right' }); y += 7;
    doc.setFontSize(10).setFont('helvetica', 'bold').text('TOTAL:', 5, y).text(`${settings.currency}${sale.total.toFixed(2)}`, 75, y, { align: 'right' });
    y += 15;
    doc.setFontSize(8).setFont('helvetica', 'italic').text(settings.receiptFooter, 40, y, { align: 'center' });
    return doc;
  };

  return (
    <div className="flex flex-col lg:flex-row gap-8 h-[calc(100vh-160px)] relative">
      {/* Success Modal */}
      {lastSale && (
        <div className="fixed inset-0 bg-slate-900/50 backdrop-blur-md z-[100] flex items-center justify-center p-4 no-print">
          <div className="bg-white rounded-[2.5rem] p-10 max-w-sm w-full shadow-2xl text-center space-y-6">
            <div className="w-20 h-20 bg-emerald-100 text-emerald-600 rounded-full flex items-center justify-center text-4xl mx-auto">✓</div>
            <div>
              <h3 className="text-2xl font-black text-slate-800">Sale Confirmed</h3>
              <p className="text-slate-400">Transaction #{lastSale.id} completed successfully.</p>
            </div>
            <div className="flex flex-col gap-3">
              <button onClick={() => generatePDF(lastSale).save(`Receipt-${lastSale.id}.pdf`)} className="w-full bg-slate-900 text-white py-4 rounded-2xl font-black flex items-center justify-center gap-2 hover:bg-slate-800 transition-all shadow-lg">
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M7 21h10a2 2 0 002-2V9.414a1 1 0 00-.293-.707l-5.414-5.414A1 1 0 0012.586 3H7a2 2 0 00-2 2v14a2 2 0 002 2z"/></svg>
                Download PDF Receipt
              </button>
              <button onClick={() => setLastSale(null)} className="w-full bg-slate-100 text-slate-600 py-4 rounded-2xl font-bold hover:bg-slate-200 transition-all">Close</button>
            </div>
          </div>
        </div>
      )}

      {/* Main Grid UI */}
      <div className="flex-1 flex flex-col min-w-0">
        <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-6">
          <div className="flex items-center gap-2">
            <button onClick={() => setActiveTab('services')} className={`px-6 py-3 rounded-2xl font-bold transition-all ${activeTab === 'services' ? 'bg-amber-500 text-slate-900 shadow-md' : 'bg-white text-slate-400 border border-slate-100'}`}>Services</button>
            <button onClick={() => setActiveTab('products')} className={`px-6 py-3 rounded-2xl font-bold transition-all ${activeTab === 'products' ? 'bg-amber-500 text-slate-900 shadow-md' : 'bg-white text-slate-400 border border-slate-100'}`}>Products</button>
          </div>

          <div className="flex-1 max-w-md relative group">
            <svg className="w-5 h-5 absolute left-4 top-1/2 -translate-y-1/2 text-slate-300 group-focus-within:text-amber-500 transition-colors" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z"/></svg>
            <input 
              type="text" 
              placeholder={`Search ${activeTab}...`} 
              value={searchTerm}
              onChange={e => setSearchTerm(e.target.value)}
              className="w-full bg-white border border-slate-100 rounded-2xl py-3 pl-12 pr-4 outline-none focus:ring-2 focus:ring-amber-400 transition-all shadow-sm"
            />
            {activeTab === 'products' && (
              <button 
                onClick={() => setShowScanner(true)}
                className="absolute right-2 top-1/2 -translate-y-1/2 p-2 bg-slate-50 text-slate-400 rounded-xl hover:text-amber-500 hover:bg-amber-50 transition-all"
                title="Scan with Camera"
              >
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z"/><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 13a3 3 0 11-6 0 3 3 0 016 0z"/></svg>
              </button>
            )}
          </div>
        </div>

        {/* Catalog Grid */}
        <div className="grid grid-cols-2 md:grid-cols-3 xl:grid-cols-4 gap-4 overflow-y-auto pr-2 pb-8">
          {filteredItems.map(item => (
            <button 
              key={item.id} 
              onClick={() => addToCart(item, activeTab === 'services' ? 'service' : 'product')} 
              className="bg-white p-6 rounded-[2rem] border border-slate-100 shadow-sm hover:border-amber-400 hover:shadow-md transition-all text-left group relative overflow-hidden"
            >
              <div className={`w-10 h-10 ${activeTab === 'services' ? 'bg-amber-50 text-amber-500' : 'bg-blue-50 text-blue-500'} rounded-xl flex items-center justify-center mb-4 group-hover:scale-110 transition-transform`}>
                <span className="text-xs font-black">{activeTab === 'services' ? (item as Service).category.charAt(0) : 'P'}</span>
              </div>
              <h4 className="font-bold text-slate-800 text-sm mb-1 leading-tight">{item.name}</h4>
              <p className="text-xl font-black text-slate-900">{settings.currency}{item.price}</p>
              <div className="flex justify-between items-center mt-3">
                 <span className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">{activeTab === 'services' ? `${(item as Service).duration} min` : `${(item as Product).stock} left`}</span>
                 {activeTab === 'products' && (item as Product).barcode && (
                   <span className="text-[9px] text-slate-300 font-mono tracking-tighter">{(item as Product).barcode}</span>
                 )}
              </div>
            </button>
          ))}
          {filteredItems.length === 0 && (
            <div className="col-span-full py-20 text-center text-slate-300">
              <p className="text-lg italic font-medium">No results found for "{searchTerm}"</p>
            </div>
          )}
        </div>

        {/* Held Sales Bar */}
        {heldSales.length > 0 && (
          <div className="mt-auto border-t border-slate-100 pt-4 mb-4">
             <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 px-2">Suspended Sales</p>
             <div className="flex gap-3 overflow-x-auto pb-2 scrollbar-hide">
               {heldSales.map(held => (
                 <button 
                  key={held.id} 
                  onClick={() => resumeSale(held)}
                  className="flex-shrink-0 bg-white border border-amber-100 px-4 py-2 rounded-xl flex items-center gap-3 hover:bg-amber-50 transition-colors shadow-sm"
                 >
                   <div className="w-8 h-8 rounded-full bg-amber-100 text-amber-600 flex items-center justify-center font-bold text-xs">{held.id}</div>
                   <div className="text-left">
                     <p className="text-xs font-bold text-slate-800">{held.cart.length} Items</p>
                     <p className="text-[9px] text-slate-400">{new Date(held.timestamp).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}</p>
                   </div>
                 </button>
               ))}
             </div>
          </div>
        )}
      </div>

      {/* Checkout Sidebar */}
      <div className="w-full lg:w-[420px] bg-white rounded-[2.5rem] border border-slate-100 shadow-sm flex flex-col overflow-hidden">
        <div className="p-8 border-b border-slate-50 flex justify-between items-center">
          <h3 className="text-xl font-bold text-slate-800">Checkout Cart</h3>
          {cart.length > 0 && (
            <button onClick={clearCart} className="text-[10px] font-black text-rose-400 hover:text-rose-600 uppercase tracking-widest">Clear</button>
          )}
        </div>

        <div className="flex-1 overflow-y-auto p-8 space-y-4">
          {cart.map(item => (
            <div key={`${item.id}-${item.type}`} className="flex justify-between items-start group animate-in fade-in slide-in-from-right-2">
              <div className="flex-1">
                <p className="text-sm font-bold text-slate-800 leading-tight">{item.name}</p>
                <div className="flex items-center gap-3 mt-1">
                  <div className="flex items-center bg-slate-50 rounded-lg p-0.5 border border-slate-100">
                    <button onClick={() => updateQuantity(item.id, item.type, -1)} className="w-6 h-6 flex items-center justify-center text-slate-400 hover:text-slate-600">-</button>
                    <span className="w-8 text-center text-xs font-black text-slate-700">{item.quantity}</span>
                    <button onClick={() => updateQuantity(item.id, item.type, 1)} className="w-6 h-6 flex items-center justify-center text-slate-400 hover:text-slate-600">+</button>
                  </div>
                  <span className="text-xs text-slate-400">@ {settings.currency}{item.price}</span>
                </div>
              </div>
              <div className="text-right pl-4">
                <p className="font-black text-slate-800">{settings.currency}{(item.price * item.quantity).toFixed(2)}</p>
                <button onClick={() => removeFromCart(item.id, item.type)} className="text-rose-400 hover:text-rose-600 text-[10px] font-bold uppercase tracking-tight mt-1 opacity-0 group-hover:opacity-100 transition-opacity">Remove</button>
              </div>
            </div>
          ))}
          {cart.length === 0 && (
            <div className="flex flex-col items-center justify-center h-full text-slate-300 italic py-10">
              <svg className="w-16 h-16 mb-4 opacity-10" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M16 11V7a4 4 0 00-8 0v4M5 9h14l1 12H4L5 9z"/></svg>
              <p>Your cart is empty</p>
            </div>
          )}
        </div>

        <div className="p-8 bg-slate-50/80 backdrop-blur-sm border-t border-slate-100 space-y-4">
          <div className="grid grid-cols-2 gap-2">
             <button 
              onClick={holdSale} 
              disabled={cart.length === 0}
              className="px-4 py-2 bg-white border border-slate-200 text-slate-600 rounded-xl text-xs font-bold hover:border-amber-400 hover:text-amber-600 transition-all disabled:opacity-50"
             >
               Suspend Sale
             </button>
             <button 
              onClick={() => handleComplete('cash')} 
              disabled={!selectedStaff || cart.length === 0}
              className="px-4 py-2 bg-emerald-50 text-emerald-600 border border-emerald-100 rounded-xl text-xs font-bold hover:bg-emerald-100 transition-all disabled:opacity-50"
             >
               Exact Cash
             </button>
          </div>

          <div className="space-y-2">
            <select value={selectedStaff} onChange={e => setSelectedStaff(e.target.value)} className="w-full bg-white border border-slate-100 rounded-xl px-4 py-3 text-sm focus:ring-2 focus:ring-amber-400 outline-none transition-shadow">
                <option value="">Select Barber</option>
                {staff.map(s => <option key={s.id} value={s.id}>{s.name}</option>)}
            </select>
            <select value={selectedCustomer} onChange={e => setSelectedCustomer(e.target.value)} className="w-full bg-white border border-slate-100 rounded-xl px-4 py-3 text-sm focus:ring-2 focus:ring-amber-400 outline-none transition-shadow">
                <option value="">Guest Walk-in</option>
                {customers.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
            </select>
          </div>

          <div className="pt-4 border-t border-slate-200 space-y-2">
            <div className="flex justify-between text-sm text-slate-500 font-medium"><span>Subtotal</span><span>{settings.currency}{subtotal.toFixed(2)}</span></div>
            <div className="flex justify-between text-sm text-slate-500 font-medium"><span>Tax ({settings.taxRate}%)</span><span>{settings.currency}{tax.toFixed(2)}</span></div>
            <div className="flex justify-between text-2xl font-black text-slate-900 pt-2"><span>Total</span><span>{settings.currency}{total.toFixed(2)}</span></div>
          </div>

          <div className="grid grid-cols-2 gap-3 pt-2">
            <button 
              onClick={() => handleComplete('card')} 
              disabled={!selectedStaff || cart.length === 0} 
              className="bg-slate-900 text-white py-4 rounded-2xl font-black text-lg hover:bg-slate-800 transition-all shadow-xl disabled:opacity-50 flex items-center justify-center gap-2"
            >
              <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M3 10h18M7 15h1m4 0h1m-7 4h12a3 3 0 003-3V8a3 3 0 00-3-3H6a3 3 0 00-3 3v8a3 3 0 003 3z"/></svg>
              Card
            </button>
            <button 
              onClick={() => handleComplete('cash')} 
              disabled={!selectedStaff || cart.length === 0} 
              className="bg-emerald-600 text-white py-4 rounded-2xl font-black text-lg hover:bg-emerald-700 transition-all shadow-xl disabled:opacity-50 flex items-center justify-center gap-2"
            >
              <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 8c-1.657 0-3 .895-3 2s1.343 2 3 2 3 .895 3 2-1.343 2-3 2m0-8c1.11 0 2.08.402 2.599 1M12 8V7m0 1v8m0 0v1m0-1c-1.11 0-2.08-.402-2.599-1M21 12a9 9 0 11-18 0 9 9 0 0118 0z"/></svg>
              Cash
            </button>
          </div>
        </div>
      </div>

      {/* Simulated Scanner Modal */}
      {showScanner && (
        <div className="fixed inset-0 bg-slate-950 z-[200] flex flex-col items-center justify-center p-6 animate-in fade-in duration-300">
           <div className="relative w-full max-w-sm aspect-square bg-slate-900 rounded-3xl border-4 border-slate-800 overflow-hidden">
              <div className="absolute inset-0 bg-gradient-to-b from-transparent via-amber-500/20 to-transparent animate-scanner-scan z-10 border-b-2 border-amber-500/50"></div>
              <div className="absolute inset-0 flex flex-col items-center justify-center text-slate-700">
                <svg className="w-24 h-24 mb-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="1" d="M12 4v1m6 11h2m-6 0h-2v4m0-11v3m0 0h.01M12 12h4.01M16 20h4M4 12h4m12 0h.01M5 8h2a1 1 0 001-1V5a1 1 0 00-1-1H5a1 1 0 00-1 1v2a1 1 0 001 1zm12 0h2a1 1 0 001-1V5a1 1 0 00-1-1h-2a1 1 0 00-1 1v2a1 1 0 001 1zM5 20h2a1 1 0 001-1v-2a1 1 0 00-1-1H5a1 1 0 00-1 1v2a1 1 0 001 1z"/></svg>
                <p className="text-xs uppercase font-black tracking-widest text-slate-500">Camera Active</p>
                <p className="text-[10px] text-slate-600 mt-2 px-10 text-center">Center the product barcode within the frame. (Simulated for Demo)</p>
              </div>
              {/* This is where a real stream would go. For demo, we auto-scan p1 after 2s */}
              {setTimeout(() => {
                if(showScanner) {
                  addToCart(products[0], 'product');
                  setShowScanner(false);
                }
              }, 2500)}
           </div>
           <button 
            onClick={() => setShowScanner(false)} 
            className="mt-12 bg-white/10 text-white px-10 py-4 rounded-2xl font-bold hover:bg-white/20 transition-all"
           >
             Cancel Scan
           </button>
        </div>
      )}

      <style>{`
        @keyframes scan {
          0% { top: 0; }
          100% { top: 100%; }
        }
        .animate-scanner-scan {
          position: absolute;
          width: 100%;
          height: 10%;
          animation: scan 2.5s infinite linear;
        }
        .scrollbar-hide::-webkit-scrollbar { display: none; }
        .scrollbar-hide { -ms-overflow-style: none; scrollbar-width: none; }
      `}</style>
    </div>
  );
};

