import React from 'react';
import { Sale, Expense } from '../types';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, LineChart, Line } from 'recharts';
import { motion } from 'framer-motion';

interface DashboardProps {
  sales: Sale[];
  expenses: Expense[];
  currency: string;
}

const Dashboard: React.FC<DashboardProps> = ({ sales, expenses, currency }) => {
  const totalRevenue = sales.reduce((acc, s) => acc + s.total, 0);
  const totalExpenses = expenses.reduce((acc, e) => acc + e.amount, 0);
  const netProfit = totalRevenue - totalExpenses;
  const averageTicket = sales.length > 0 ? totalRevenue / sales.length : 0;

  const last7Days = Array.from({ length: 7 }, (_, i) => {
    const d = new Date();
    d.setDate(d.getDate() - i);
    return d.toISOString().split('T')[0];
  }).reverse();

  const chartData = last7Days.map(date => ({
    date: date.split('-').slice(1).join('/'),
    revenue: sales
      .filter(s => s.timestamp.startsWith(date))
      .reduce((acc, s) => acc + s.total, 0)
  }));

  const stats = [
    { label: 'Revenue', value: `${currency}${totalRevenue.toLocaleString()}`, icon: '💰', color: 'bg-emerald-50 text-emerald-600', border: 'border-emerald-100' },
    { label: 'Expenses', value: `${currency}${totalExpenses.toLocaleString()}`, icon: '💸', color: 'bg-rose-50 text-rose-600', border: 'border-rose-100' },
    { label: 'Net Profit', value: `${currency}${netProfit.toLocaleString()}`, icon: '📈', color: 'bg-indigo-50 text-indigo-600', border: 'border-indigo-100' },
    { label: 'Avg Ticket', value: `${currency}${averageTicket.toFixed(2)}`, icon: '🎟️', color: 'bg-amber-50 text-amber-600', border: 'border-amber-100' },
  ];

  const container = {
    hidden: { opacity: 0 },
    show: {
      opacity: 1,
      transition: { staggerChildren: 0.1 }
    }
  };

  const item = {
    hidden: { opacity: 0, y: 20 },
    show: { opacity: 1, y: 0 }
  };

  return (
    <motion.div 
      variants={container}
      initial="hidden"
      animate="show"
      className="space-y-8 max-w-[1600px] mx-auto"
    >
      <header className="flex flex-col md:flex-row md:items-end justify-between gap-4">
        <div>
          <motion.h2 variants={item} className="text-4xl font-extrabold text-slate-900 font-brand tracking-tight">
            Performance Insights
          </motion.h2>
          <motion.p variants={item} className="text-slate-500 mt-2 font-medium">
            Welcome back! Here's what's happening in your shop.
          </motion.p>
        </div>
        <motion.div variants={item} className="bg-white px-5 py-3 rounded-2xl shadow-sm border border-slate-100 flex items-center gap-3">
            <span className="text-slate-300">
              <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v12a2 2 0 002 2z"/></svg>
            </span>
            <p className="text-slate-800 font-bold text-sm tracking-tight">{new Date().toLocaleDateString('en-US', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' })}</p>
        </motion.div>
      </header>

      <motion.div variants={container} className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        {stats.map((stat, idx) => (
          <motion.div 
            key={idx} 
            variants={item}
            whileHover={{ y: -5, scale: 1.02 }}
            className={`bg-white p-7 rounded-[2rem] shadow-sm border ${stat.border} flex flex-col gap-4 relative overflow-hidden group`}
          >
            <div className={`w-12 h-12 rounded-2xl flex items-center justify-center text-2xl ${stat.color} transition-transform group-hover:rotate-12`}>
              {stat.icon}
            </div>
            <div>
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mb-1">{stat.label}</p>
              <p className="text-3xl font-black text-slate-900 tracking-tight">{stat.value}</p>
            </div>
            <div className={`absolute -right-4 -bottom-4 w-24 h-24 opacity-[0.03] rotate-12 transition-transform group-hover:scale-125`}>
               {stat.icon}
            </div>
          </motion.div>
        ))}
      </motion.div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <motion.div variants={item} className="lg:col-span-2 bg-white p-8 rounded-[2.5rem] shadow-sm border border-slate-100">
          <div className="flex items-center justify-between mb-8">
            <h3 className="text-xl font-bold text-slate-900 flex items-center gap-3">
              <div className="w-2 h-8 bg-amber-500 rounded-full"></div>
              Revenue Trends
            </h3>
            <div className="flex gap-2">
               <span className="flex items-center gap-1.5 text-[10px] font-black text-slate-400 uppercase">
                 <span className="w-2 h-2 rounded-full bg-amber-500"></span> Last 7 Days
               </span>
            </div>
          </div>
          <div className="h-[320px]">
            <ResponsiveContainer width="100%" height="100%">
              <LineChart data={chartData}>
                <CartesianGrid strokeDasharray="6 6" vertical={false} stroke="#f8fafc" />
                <XAxis 
                  dataKey="date" 
                  axisLine={false} 
                  tickLine={false} 
                  tick={{fill: '#94a3b8', fontSize: 11, fontWeight: 700}} 
                  dy={15} 
                />
                <YAxis 
                  axisLine={false} 
                  tickLine={false} 
                  tick={{fill: '#94a3b8', fontSize: 11, fontWeight: 700}} 
                />
                <Tooltip 
                  contentStyle={{borderRadius: '20px', border: 'none', boxShadow: '0 20px 25px -5px rgb(0 0 0 / 0.1)', padding: '12px 16px'}}
                  cursor={{ stroke: '#f59e0b', strokeWidth: 1, strokeDasharray: '4 4' }}
                />
                <Line 
                  type="monotone" 
                  dataKey="revenue" 
                  stroke="#f59e0b" 
                  strokeWidth={4} 
                  dot={{fill: '#f59e0b', strokeWidth: 3, r: 5, stroke: '#fff'}} 
                  activeDot={{r: 8, strokeWidth: 0}} 
                />
              </LineChart>
            </ResponsiveContainer>
          </div>
        </motion.div>

        <motion.div variants={item} className="bg-white p-8 rounded-[2.5rem] shadow-sm border border-slate-100 flex flex-col">
          <h3 className="text-xl font-bold text-slate-900 mb-8">Recent Transactions</h3>
          <div className="space-y-5 flex-1 overflow-y-auto max-h-[320px] pr-2 scrollbar-hide">
            {sales.slice(-6).reverse().map((sale) => (
              <div key={sale.id} className="flex items-center justify-between group transition-all">
                <div className="flex items-center gap-4">
                  <div className={`w-12 h-12 rounded-2xl flex items-center justify-center text-xl transition-all ${sale.paymentMethod === 'card' ? 'bg-indigo-50 text-indigo-500 group-hover:bg-indigo-100' : 'bg-emerald-50 text-emerald-500 group-hover:bg-emerald-100'}`}>
                    {sale.paymentMethod === 'card' ? '💳' : '💵'}
                  </div>
                  <div>
                    <p className="text-sm font-bold text-slate-800">#{sale.id.slice(-4)}</p>
                    <p className="text-[10px] text-slate-400 font-bold uppercase tracking-wider">{new Date(sale.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</p>
                  </div>
                </div>
                <div className="text-right">
                  <p className="text-base font-black text-slate-900">{currency}{sale.total.toFixed(2)}</p>
                  <p className="text-[9px] text-amber-600 font-black uppercase tracking-widest">{sale.paymentMethod}</p>
                </div>
              </div>
            ))}
            {sales.length === 0 && (
                <div className="flex flex-col items-center justify-center h-full text-slate-300 py-10">
                    <svg className="w-12 h-12 mb-3 opacity-20" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z"/></svg>
                    <p className="text-sm italic font-medium">Waiting for first sale...</p>
                </div>
            )}
          </div>
        </motion.div>
      </div>
    </motion.div>
  );
};

export default Dashboard;

import React, { useState, useMemo, useEffect } from 'react';
import { Service, Product, Staff, Sale, SaleItem, Customer, ShopSettings, HeldSale } from '../types';
import { INITIAL_DISCOUNT_CODES } from '../constants';
import { jsPDF } from 'jspdf';
import { motion, AnimatePresence } from 'framer-motion';

interface POSProps {
  services: Service[];
  products: Product[];
  staff: Staff[];
  customers: Customer[];
  settings: ShopSettings;
  onCompleteSale: (sale: Sale) => void;
  onAddCustomer: (customer: Customer) => void;
}

const POS: React.FC<POSProps> = ({ services, products, staff, customers, settings, onCompleteSale, onAddCustomer }) => {
  const [cart, setCart] = useState<SaleItem[]>([]);
  const [selectedStaff, setSelectedStaff] = useState<string>('');
  const [selectedCustomer, setSelectedCustomer] = useState<string>('');
  const [discountCode, setDiscountCode] = useState<string>('');
  const [activeTab, setActiveTab] = useState<'services' | 'products'>('services');
  const [lastSale, setLastSale] = useState<Sale | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [heldSales, setHeldSales] = useState<HeldSale[]>([]);
  const [showScanner, setShowScanner] = useState(false);
  const [scanningFeedback, setScanningFeedback] = useState<string | null>(null);

  // Barcode Hardware Support
  useEffect(() => {
    let barcodeBuffer = '';
    let lastKeyTime = Date.now();
    const handleKeyDown = (e: KeyboardEvent) => {
      const currentTime = Date.now();
      if (currentTime - lastKeyTime > 50) barcodeBuffer = '';
      if (e.key === 'Enter') {
        if (barcodeBuffer.length > 3) {
          const product = products.find(p => p.barcode === barcodeBuffer);
          if (product) {
            addToCart(product, 'product');
            setScanningFeedback(product.name);
            setTimeout(() => setScanningFeedback(null), 2000);
          }
          barcodeBuffer = '';
        }
      } else if (e.key.length === 1) barcodeBuffer += e.key;
      lastKeyTime = currentTime;
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [products]);

  const addToCart = (item: Service | Product, type: 'service' | 'product') => {
    setCart(prev => {
      const existing = prev.find(i => i.id === item.id && i.type === type);
      if (existing) {
        return prev.map(i => i.id === item.id && i.type === type ? { ...i, quantity: i.quantity + 1 } : i);
      }
      return [...prev, { id: item.id, name: item.name, price: item.price, type, quantity: 1 }];
    });
  };

  const updateQuantity = (id: string, type: 'service' | 'product', delta: number) => {
    setCart(prev => prev.map(item => {
      if (item.id === id && item.type === type) {
        return { ...item, quantity: Math.max(1, item.quantity + delta) };
      }
      return item;
    }));
  };

  const removeFromCart = (id: string, type: 'service' | 'product') => {
    setCart(prev => prev.filter(i => !(i.id === id && i.type === type)));
  };

  const holdSale = () => {
    if (cart.length === 0) return;
    const newHeldSale: HeldSale = {
      id: Math.random().toString(36).substr(2, 5).toUpperCase(),
      timestamp: new Date().toISOString(),
      cart: [...cart],
      customerId: selectedCustomer,
      staffId: selectedStaff
    };
    setHeldSales([...heldSales, newHeldSale]);
    setCart([]);
    setSelectedCustomer('');
    setSelectedStaff('');
  };

  const resumeSale = (held: HeldSale) => {
    setCart(held.cart);
    setSelectedCustomer(held.customerId || '');
    setSelectedStaff(held.staffId || '');
    setHeldSales(heldSales.filter(h => h.id !== held.id));
  };

  const appliedDiscount = useMemo(() => {
    const code = INITIAL_DISCOUNT_CODES.find(c => c.code === discountCode.toUpperCase());
    return code || null;
  }, [discountCode]);

  const subtotal = cart.reduce((acc, item) => acc + (item.price * item.quantity), 0);
  const discountAmount = appliedDiscount 
    ? (appliedDiscount.type === 'percentage' ? (subtotal * appliedDiscount.value / 100) : appliedDiscount.value)
    : 0;
  const tax = (subtotal - discountAmount) * (settings.taxRate / 100);
  const total = subtotal - discountAmount + tax;

  const handleComplete = (method: 'cash' | 'card') => {
    if (!selectedStaff || cart.length === 0) return;
    const sale: Sale = {
      id: Math.random().toString(36).substr(2, 9).toUpperCase(),
      timestamp: new Date().toISOString(),
      items: [...cart],
      staffId: selectedStaff,
      customerId: selectedCustomer || undefined,
      total: total,
      tax: tax,
      discount: discountAmount,
      discountCode: appliedDiscount?.code,
      paymentMethod: method
    };
    onCompleteSale(sale);
    setLastSale(sale);
    setCart([]);
    setSelectedStaff('');
    setSelectedCustomer('');
    setDiscountCode('');
    setSearchTerm('');
  };

  const filteredItems = useMemo(() => {
    const term = searchTerm.toLowerCase();
    if (activeTab === 'services') {
      return services.filter(s => s.name.toLowerCase().includes(term) || s.category.toLowerCase().includes(term));
    } else {
      return products.filter(p => p.name.toLowerCase().includes(term) || p.barcode?.includes(term));
    }
  }, [searchTerm, activeTab, services, products]);

  const generatePDF = (sale: Sale) => {
    const doc = new jsPDF({ unit: 'mm', format: [80, 200] });
    const barber = staff.find(s => s.id === sale.staffId)?.name || 'N/A';
    const client = customers.find(c => c.id === sale.customerId)?.name || 'Guest Walk-in';
    const dateStr = new Date(sale.timestamp).toLocaleString();
    doc.setFont('helvetica', 'bold').setFontSize(16);
    doc.text(settings.shopName.toUpperCase(), 40, 15, { align: 'center' });
    doc.setFontSize(8).setFont('helvetica', 'normal').text('Premium Grooming Experience', 40, 20, { align: 'center' });
    doc.setLineWidth(0.5).line(5, 25, 75, 25);
    doc.setFontSize(7).text(`DATE: ${dateStr}`, 5, 32).text(`ORDER: #${sale.id}`, 5, 36).text(`BARBER: ${barber}`, 5, 40).text(`CLIENT: ${client}`, 5, 44);
    doc.line(5, 48, 75, 48);
    let y = 55;
    doc.setFont('helvetica', 'bold').text('ITEM', 5, y).text('QTY', 55, y).text('PRICE', 75, y, { align: 'right' });
    doc.setFont('helvetica', 'normal');
    y += 5;
    sale.items.forEach(item => {
      doc.text(item.name.substring(0, 25), 5, y);
      doc.text(item.quantity.toString(), 55, y);
      doc.text(`${settings.currency}${(item.price * item.quantity).toFixed(2)}`, 75, y, { align: 'right' });
      y += 5;
    });
    doc.line(5, y, 75, y); y += 7;
    doc.text('SUBTOTAL:', 5, y).text(`${settings.currency}${subtotal.toFixed(2)}`, 75, y, { align: 'right' }); y += 5;
    if (sale.discount > 0) { doc.text('DISCOUNT:', 5, y); doc.text(`-${settings.currency}${sale.discount.toFixed(2)}`, 75, y, { align: 'right' }); y += 5; }
    doc.text(`TAX (${settings.taxRate}%):`, 5, y).text(`${settings.currency}${sale.tax.toFixed(2)}`, 75, y, { align: 'right' }); y += 7;
    doc.setFontSize(10).setFont('helvetica', 'bold').text('TOTAL:', 5, y).text(`${settings.currency}${sale.total.toFixed(2)}`, 75, y, { align: 'right' });
    y += 15;
    doc.setFontSize(8).setFont('helvetica', 'italic').text(settings.receiptFooter, 40, y, { align: 'center' });
    return doc;
  };

  return (
    <div className="flex flex-col lg:flex-row gap-8 h-[calc(100vh-160px)] relative">
      {/* Scanning Notification */}
      <AnimatePresence>
        {scanningFeedback && (
          <motion.div 
            initial={{ opacity: 0, y: -20, scale: 0.9 }}
            animate={{ opacity: 1, y: 0, scale: 1 }}
            exit={{ opacity: 0, scale: 0.9 }}
            className="fixed top-10 left-1/2 -translate-x-1/2 z-[200] bg-slate-900 text-white px-8 py-4 rounded-[2rem] shadow-2xl flex items-center gap-4 border border-slate-800"
          >
            <div className="w-8 h-8 rounded-full bg-emerald-500 flex items-center justify-center">
              <svg className="w-5 h-5 text-slate-950" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M5 13l4 4L19 7"/></svg>
            </div>
            <p className="font-bold text-sm tracking-wide">Added: <span className="text-amber-400">{scanningFeedback}</span></p>
          </motion.div>
        )}
      </AnimatePresence>

      {/* Success Modal */}
      <AnimatePresence>
        {lastSale && (
          <motion.div 
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="fixed inset-0 bg-slate-950/80 backdrop-blur-xl z-[150] flex items-center justify-center p-6 no-print"
          >
            <motion.div 
              initial={{ scale: 0.8, opacity: 0, y: 20 }}
              animate={{ scale: 1, opacity: 1, y: 0 }}
              className="bg-white rounded-[3rem] p-12 max-w-md w-full shadow-2xl text-center space-y-8"
            >
              <div className="w-24 h-24 bg-emerald-50 text-emerald-500 rounded-full flex items-center justify-center text-5xl mx-auto shadow-inner">✓</div>
              <div className="space-y-2">
                <h3 className="text-3xl font-black text-slate-900 tracking-tight">Sale Completed</h3>
                <p className="text-slate-400 font-medium">Order #{lastSale.id} is finalized.</p>
              </div>
              <div className="flex flex-col gap-4">
                <button onClick={() => generatePDF(lastSale).save(`Receipt-${lastSale.id}.pdf`)} className="w-full bg-slate-950 text-white py-5 rounded-[1.5rem] font-black flex items-center justify-center gap-3 hover:bg-slate-800 transition-all active:scale-[0.98] shadow-xl">
                  <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M7 21h10a2 2 0 002-2V9.414a1 1 0 00-.293-.707l-5.414-5.414A1 1 0 0012.586 3H7a2 2 0 00-2 2v14a2 2 0 002 2z"/></svg>
                  Print Receipt
                </button>
                <button onClick={() => setLastSale(null)} className="w-full bg-slate-100 text-slate-500 py-5 rounded-[1.5rem] font-bold hover:bg-slate-200 transition-all">Back to Terminal</button>
              </div>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>

      <div className="flex-1 flex flex-col min-w-0">
        <div className="flex flex-col md:flex-row md:items-center justify-between gap-5 mb-8">
          <div className="flex items-center bg-white p-1.5 rounded-[1.5rem] shadow-sm border border-slate-100">
            <button 
              onClick={() => setActiveTab('services')} 
              className={`px-8 py-3 rounded-2xl font-bold transition-all ${activeTab === 'services' ? 'bg-amber-500 text-slate-950 shadow-md' : 'text-slate-400 hover:text-slate-600'}`}
            >
              Services
            </button>
            <button 
              onClick={() => setActiveTab('products')} 
              className={`px-8 py-3 rounded-2xl font-bold transition-all ${activeTab === 'products' ? 'bg-amber-500 text-slate-950 shadow-md' : 'text-slate-400 hover:text-slate-600'}`}
            >
              Retail
            </button>
          </div>

          <div className="flex-1 max-w-md relative group">
            <svg className="w-5 h-5 absolute left-5 top-1/2 -translate-y-1/2 text-slate-300 group-focus-within:text-amber-500 transition-colors" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z"/></svg>
            <input 
              type="text" 
              placeholder={`Quick lookup ${activeTab}...`} 
              value={searchTerm}
              onChange={e => setSearchTerm(e.target.value)}
              className="w-full bg-white border border-slate-200 rounded-[1.5rem] py-4 pl-14 pr-12 outline-none focus:ring-4 focus:ring-amber-500/10 focus:border-amber-500/30 transition-all shadow-sm font-medium"
            />
            {activeTab === 'products' && (
              <button 
                onClick={() => setShowScanner(true)}
                className="absolute right-3 top-1/2 -translate-y-1/2 p-2.5 bg-slate-50 text-slate-400 rounded-xl hover:text-amber-600 hover:bg-amber-50 transition-all"
              >
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z"/><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 13a3 3 0 11-6 0 3 3 0 016 0z"/></svg>
              </button>
            )}
          </div>
        </div>

        <div className="grid grid-cols-2 md:grid-cols-3 xl:grid-cols-4 gap-5 overflow-y-auto pr-2 pb-12 scrollbar-hide">
          <AnimatePresence mode="popLayout">
            {filteredItems.map(item => (
              <motion.button 
                layout
                initial={{ opacity: 0, scale: 0.95 }}
                animate={{ opacity: 1, scale: 1 }}
                key={item.id} 
                onClick={() => addToCart(item, activeTab === 'services' ? 'service' : 'product')} 
                className="bg-white p-7 rounded-[2.5rem] border border-slate-100 shadow-sm hover:border-amber-400 hover:shadow-xl hover:shadow-amber-500/5 transition-all text-left group relative overflow-hidden active:scale-95"
              >
                <div className={`w-12 h-12 ${activeTab === 'services' ? 'bg-amber-50 text-amber-600' : 'bg-indigo-50 text-indigo-600'} rounded-2xl flex items-center justify-center mb-6 transition-transform duration-300 group-hover:scale-110 group-hover:rotate-6`}>
                  <span className="text-sm font-black">{activeTab === 'services' ? (item as Service).category.substring(0,2).toUpperCase() : 'PR'}</span>
                </div>
                <h4 className="font-bold text-slate-800 text-sm mb-1.5 line-clamp-2 leading-tight h-10">{item.name}</h4>
                <p className="text-2xl font-black text-slate-950 tracking-tight">{settings.currency}{item.price}</p>
                <div className="flex justify-between items-center mt-4">
                   <span className="px-3 py-1 bg-slate-50 rounded-full text-[9px] text-slate-400 font-black uppercase tracking-widest">{activeTab === 'services' ? `${(item as Service).duration}M` : `${(item as Product).stock} STOCK`}</span>
                </div>
                <div className="absolute top-4 right-4 opacity-0 group-hover:opacity-100 transition-opacity">
                   <div className="bg-amber-500 text-slate-950 p-1.5 rounded-full shadow-lg">
                      <svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M12 4v16m8-8H4"/></svg>
                   </div>
                </div>
              </motion.button>
            ))}
          </AnimatePresence>
        </div>

        {heldSales.length > 0 && (
          <motion.div initial={{ y: 20, opacity: 0 }} animate={{ y: 0, opacity: 1 }} className="mt-auto border-t border-slate-200/50 pt-5 mb-4">
             <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mb-3 px-1">Active Suspensions</p>
