          </div>

          <div className="pt-6 border-t border-slate-200/50 space-y-3">
            <div className="flex justify-between text-[11px] text-slate-400 font-black uppercase tracking-[0.2em]"><span>Net Amount</span><span>{settings.currency}{subtotal.toFixed(2)}</span></div>
            <div className="flex justify-between text-[11px] text-slate-400 font-black uppercase tracking-[0.2em]"><span>Surcharge ({settings.taxRate}%)</span><span>{settings.currency}{tax.toFixed(2)}</span></div>
            <div className="flex justify-between items-baseline pt-4">
               <span className="text-lg font-black text-slate-400 uppercase tracking-tighter">Payable</span>
