      <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924-1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z"/><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z"/></svg>
    ), roles: ['admin'] },
  ];

  const visibleItems = allItems.filter(item => item.roles.includes(userRole));

  return (
    <motion.div 
      initial={{ x: -260 }}
      animate={{ x: isOpen || window.innerWidth >= 768 ? 0 : -260 }}
      transition={{ type: "spring", damping: 25, stiffness: 200 }}
      className={`w-64 bg-slate-900 h-screen fixed left-0 top-0 flex flex-col text-white no-print shadow-2xl z-[60]`}
    >
      <div className="p-8 border-b border-slate-800/50 flex items-center justify-between gap-4">
        <div className="flex items-center gap-4">
            <motion.div 
              whileHover={{ rotate: 15, scale: 1.1 }}
              className="w-10 h-10 bg-gradient-to-br from-amber-400 to-amber-600 rounded-xl flex items-center justify-center font-brand text-2xl text-slate-950 shadow-xl shadow-amber-500/20"
            >
              {shopName.charAt(0)}
            </motion.div>
            <h1 className="text-xl font-extrabold font-brand tracking-tight truncate bg-clip-text text-transparent bg-gradient-to-r from-white to-slate-400">
              {shopName}
            </h1>
        </div>
        <button onClick={onClose} className="md:hidden text-slate-500 hover:text-white">
          <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12"/></svg>
        </button>
      </div>

      <nav className="flex-1 p-5 space-y-1.5 overflow-y-auto scrollbar-hide">
        {visibleItems.map(item => {
          const isActive = currentView === item.id;
          return (
            <button
              key={item.id}
              onClick={() => {
                onViewChange(item.id);
                if (window.innerWidth < 768) onClose();
              }}
              className="w-full relative group outline-none"
            >
              <div className={`
                flex items-center gap-3 px-4 py-3.5 rounded-2xl transition-all duration-300 relative z-10
                ${isActive ? 'text-slate-900 font-bold' : 'hover:bg-slate-800/50 text-slate-400 font-medium'}
              `}>
                <span className={`transition-transform duration-300 ${isActive ? 'scale-110' : 'group-hover:scale-110'}`}>
                  {item.icon}
                </span>
                <span className="text-sm tracking-wide">{item.label}</span>
              </div>

              {isActive && (
                <motion.div 
                  layoutId="activeTab"
                  className="absolute inset-0 bg-amber-500 rounded-2xl shadow-lg shadow-amber-500/10"
                  transition={{ type: "spring", bounce: 0.25, duration: 0.5 }}
                />
              )}
            </button>
          );
        })}
      </nav>

      <div className="p-6 border-t border-slate-800/50">
        <div className="bg-slate-800/40 p-4 rounded-2xl border border-slate-700/30">
           <p className="text-[10px] text-slate-500 uppercase font-black tracking-widest mb-2 px-1 text-center md:text-left">Shop Status</p>
           <p className="text-xs font-bold text-emerald-400 flex items-center justify-center md:justify-start gap-2.5">
             <span className="relative flex h-2 w-2">
               <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-emerald-400 opacity-75"></span>
               <span className="relative inline-flex rounded-full h-2 w-2 bg-emerald-500"></span>
             </span>
             Terminal Live
           </p>
        </div>
      </div>
    </motion.div>
  );
};

export default Sidebar;

import React, { useState, useMemo, useEffect } from 'react';
import { Service, Product, Staff, Sale, SaleItem, Customer, ShopSettings, HeldSale } from '../types';
import { INITIAL_DISCOUNT_CODES } from '../constants';
import { jsPDF } from 'jspdf';
import { motion, AnimatePresence } from 'framer-motion';

interface POSProps {
  services: Service[];
  products: Product[];
  staff: Staff[];
  customers: Customer[];
  settings: ShopSettings;
  onCompleteSale: (sale: Sale) => void;
  onAddCustomer: (customer: Customer) => void;
}

const POS: React.FC<POSProps> = ({ services, products, staff, customers, settings, onCompleteSale, onAddCustomer }) => {
  const [cart, setCart] = useState<SaleItem[]>([]);
  const [selectedStaff, setSelectedStaff] = useState<string>('');
  const [selectedCustomer, setSelectedCustomer] = useState<string>('');
  const [discountCode, setDiscountCode] = useState<string>('');
  const [activeTab, setActiveTab] = useState<'services' | 'products'>('services');
  const [lastSale, setLastSale] = useState<Sale | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [heldSales, setHeldSales] = useState<HeldSale[]>([]);
  const [showScanner, setShowScanner] = useState(false);
  const [scanningFeedback, setScanningFeedback] = useState<string | null>(null);
  const [showMobileCart, setShowMobileCart] = useState(false);

  // Barcode Hardware Support
  useEffect(() => {
    let barcodeBuffer = '';
    let lastKeyTime = Date.now();
    const handleKeyDown = (e: KeyboardEvent) => {
      const currentTime = Date.now();
      if (currentTime - lastKeyTime > 50) barcodeBuffer = '';
      if (e.key === 'Enter') {
        if (barcodeBuffer.length > 3) {
          const product = products.find(p => p.barcode === barcodeBuffer);
          if (product) {
            addToCart(product, 'product');
            setScanningFeedback(product.name);
            setTimeout(() => setScanningFeedback(null), 2000);
          }
          barcodeBuffer = '';
        }
      } else if (e.key.length === 1) barcodeBuffer += e.key;
      lastKeyTime = currentTime;
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [products]);

  const addToCart = (item: Service | Product, type: 'service' | 'product') => {
    setCart(prev => {
      const existing = prev.find(i => i.id === item.id && i.type === type);
      if (existing) {
        return prev.map(i => i.id === item.id && i.type === type ? { ...i, quantity: i.quantity + 1 } : i);
      }
      return [...prev, { id: item.id, name: item.name, price: item.price, type, quantity: 1 }];
    });
  };

  const updateQuantity = (id: string, type: 'service' | 'product', delta: number) => {
    setCart(prev => prev.map(item => {
      if (item.id === id && item.type === type) {
        return { ...item, quantity: Math.max(1, item.quantity + delta) };
      }
      return item;
    }));
  };

  const removeFromCart = (id: string, type: 'service' | 'product') => {
    setCart(prev => prev.filter(i => !(i.id === id && i.type === type)));
  };

  const holdSale = () => {
    if (cart.length === 0) return;
    const newHeldSale: HeldSale = {
      id: Math.random().toString(36).substr(2, 5).toUpperCase(),
      timestamp: new Date().toISOString(),
      cart: [...cart],
      customerId: selectedCustomer,
      staffId: selectedStaff
    };
    setHeldSales([...heldSales, newHeldSale]);
    setCart([]);
    setSelectedCustomer('');
    setSelectedStaff('');
    setShowMobileCart(false);
  };

  const resumeSale = (held: HeldSale) => {
    setCart(held.cart);
    setSelectedCustomer(held.customerId || '');
    setSelectedStaff(held.staffId || '');
    setHeldSales(heldSales.filter(h => h.id !== held.id));
    setShowMobileCart(true);
  };

  const appliedDiscount = useMemo(() => {
    const code = INITIAL_DISCOUNT_CODES.find(c => c.code === discountCode.toUpperCase());
    return code || null;
  }, [discountCode]);

  const subtotal = cart.reduce((acc, item) => acc + (item.price * item.quantity), 0);
  const discountAmount = appliedDiscount 
    ? (appliedDiscount.type === 'percentage' ? (subtotal * appliedDiscount.value / 100) : appliedDiscount.value)
    : 0;
  const tax = (subtotal - discountAmount) * (settings.taxRate / 100);
  const total = subtotal - discountAmount + tax;

  const handleComplete = (method: 'cash' | 'card') => {
    if (!selectedStaff || cart.length === 0) return;
    const sale: Sale = {
      id: Math.random().toString(36).substr(2, 9).toUpperCase(),
      timestamp: new Date().toISOString(),
      items: [...cart],
      staffId: selectedStaff,
      customerId: selectedCustomer || undefined,
      total: total,
      tax: tax,
      discount: discountAmount,
      discountCode: appliedDiscount?.code,
      paymentMethod: method
    };
    onCompleteSale(sale);
    setLastSale(sale);
    setCart([]);
    setSelectedStaff('');
    setSelectedCustomer('');
    setDiscountCode('');
    setSearchTerm('');
    setShowMobileCart(false);
  };

  const filteredItems = useMemo(() => {
    const term = searchTerm.toLowerCase();
    if (activeTab === 'services') {
      return services.filter(s => s.name.toLowerCase().includes(term) || s.category.toLowerCase().includes(term));
    } else {
      return products.filter(p => p.name.toLowerCase().includes(term) || p.barcode?.includes(term));
    }
  }, [searchTerm, activeTab, services, products]);

  const generatePDF = (sale: Sale) => {
    const doc = new jsPDF({ unit: 'mm', format: [80, 200] });
    const barber = staff.find(s => s.id === sale.staffId)?.name || 'N/A';
    const client = customers.find(c => c.id === sale.customerId)?.name || 'Guest Walk-in';
    const dateStr = new Date(sale.timestamp).toLocaleString();
    doc.setFont('helvetica', 'bold').setFontSize(16);
    doc.text(settings.shopName.toUpperCase(), 40, 15, { align: 'center' });
    doc.setFontSize(8).setFont('helvetica', 'normal').text('Premium Grooming Experience', 40, 20, { align: 'center' });
    doc.setLineWidth(0.5).line(5, 25, 75, 25);
    doc.setFontSize(7).text(`DATE: ${dateStr}`, 5, 32).text(`ORDER: #${sale.id}`, 5, 36).text(`BARBER: ${barber}`, 5, 40).text(`CLIENT: ${client}`, 5, 44);
    doc.line(5, 48, 75, 48);
    let y = 55;
    doc.setFont('helvetica', 'bold').text('ITEM', 5, y).text('QTY', 55, y).text('PRICE', 75, y, { align: 'right' });
    doc.setFont('helvetica', 'normal');
    y += 5;
    sale.items.forEach(item => {
      doc.text(item.name.substring(0, 25), 5, y);
      doc.text(item.quantity.toString(), 55, y);
      doc.text(`${settings.currency}${(item.price * item.quantity).toFixed(2)}`, 75, y, { align: 'right' });
      y += 5;
    });
    doc.line(5, y, 75, y); y += 7;
    doc.text('SUBTOTAL:', 5, y).text(`${settings.currency}${subtotal.toFixed(2)}`, 75, y, { align: 'right' }); y += 5;
    if (sale.discount > 0) { doc.text('DISCOUNT:', 5, y); doc.text(`-${settings.currency}${sale.discount.toFixed(2)}`, 75, y, { align: 'right' }); y += 5; }
    doc.text(`TAX (${settings.taxRate}%):`, 5, y).text(`${settings.currency}${sale.tax.toFixed(2)}`, 75, y, { align: 'right' }); y += 7;
    doc.setFontSize(10).setFont('helvetica', 'bold').text('TOTAL:', 5, y).text(`${settings.currency}${sale.total.toFixed(2)}`, 75, y, { align: 'right' });
    y += 15;
    doc.setFontSize(8).setFont('helvetica', 'italic').text(settings.receiptFooter, 40, y, { align: 'center' });
    return doc;
  };

  return (
    <div className="flex flex-col lg:flex-row gap-8 h-auto lg:h-[calc(100vh-160px)] relative">
      {/* Scanning Notification */}
      <AnimatePresence>
        {scanningFeedback && (
          <motion.div 
            initial={{ opacity: 0, y: -20, scale: 0.9 }}
            animate={{ opacity: 1, y: 0, scale: 1 }}
            exit={{ opacity: 0, scale: 0.9 }}
            className="fixed top-10 left-1/2 -translate-x-1/2 z-[200] bg-slate-900 text-white px-8 py-4 rounded-[2rem] shadow-2xl flex items-center gap-4 border border-slate-800"
          >
            <div className="w-8 h-8 rounded-full bg-emerald-500 flex items-center justify-center">
              <svg className="w-5 h-5 text-slate-950" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M5 13l4 4L19 7"/></svg>
            </div>
            <p className="font-bold text-sm tracking-wide">Added: <span className="text-amber-400">{scanningFeedback}</span></p>
          </motion.div>
        )}
      </AnimatePresence>

      {/* Success Modal */}
      <AnimatePresence>
        {lastSale && (
          <motion.div 
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="fixed inset-0 bg-slate-950/80 backdrop-blur-xl z-[150] flex items-center justify-center p-6 no-print"
          >
            <motion.div 
              initial={{ scale: 0.8, opacity: 0, y: 20 }}
              animate={{ scale: 1, opacity: 1, y: 0 }}
              className="bg-white rounded-[2.5rem] md:rounded-[3rem] p-8 md:p-12 max-w-md w-full shadow-2xl text-center space-y-8"
            >
              <div className="w-20 h-20 md:w-24 md:h-24 bg-emerald-50 text-emerald-500 rounded-full flex items-center justify-center text-4xl md:text-5xl mx-auto shadow-inner">✓</div>
              <div className="space-y-2">
                <h3 className="text-2xl md:text-3xl font-black text-slate-900 tracking-tight">Sale Completed</h3>
                <p className="text-slate-400 font-medium">Order #{lastSale.id} is finalized.</p>
              </div>
              <div className="flex flex-col gap-4">
                <button onClick={() => generatePDF(lastSale).save(`Receipt-${lastSale.id}.pdf`)} className="w-full bg-slate-950 text-white py-4 md:py-5 rounded-[1.2rem] md:rounded-[1.5rem] font-black flex items-center justify-center gap-3 hover:bg-slate-800 transition-all active:scale-[0.98] shadow-xl">
                  <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M7 21h10a2 2 0 002-2V9.414a1 1 0 00-.293-.707l-5.414-5.414A1 1 0 0012.586 3H7a2 2 0 00-2 2v14a2 2 0 002 2z"/></svg>
                  Print Receipt
                </button>
                <button onClick={() => setLastSale(null)} className="w-full bg-slate-100 text-slate-500 py-4 md:py-5 rounded-[1.2rem] md:rounded-[1.5rem] font-bold hover:bg-slate-200 transition-all">Back to Terminal</button>
              </div>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* Catalog Main View */}
      <div className={`flex-1 flex flex-col min-w-0 ${showMobileCart ? 'hidden lg:flex' : 'flex'}`}>
        <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 md:gap-5 mb-6 md:mb-8">
          <div className="flex items-center bg-white p-1.5 rounded-[1.2rem] md:rounded-[1.5rem] shadow-sm border border-slate-100 self-start md:self-auto">
            <button 
              onClick={() => setActiveTab('services')} 
              className={`px-6 md:px-8 py-2 md:py-3 rounded-xl md:rounded-2xl font-bold transition-all text-sm md:text-base ${activeTab === 'services' ? 'bg-amber-500 text-slate-950 shadow-md' : 'text-slate-400 hover:text-slate-600'}`}
            >
              Services
            </button>
            <button 
              onClick={() => setActiveTab('products')} 
              className={`px-6 md:px-8 py-2 md:py-3 rounded-xl md:rounded-2xl font-bold transition-all text-sm md:text-base ${activeTab === 'products' ? 'bg-amber-500 text-slate-950 shadow-md' : 'text-slate-400 hover:text-slate-600'}`}
            >
              Retail
            </button>
          </div>

          <div className="flex-1 max-w-md relative group">
            <svg className="w-5 h-5 absolute left-5 top-1/2 -translate-y-1/2 text-slate-300 group-focus-within:text-amber-500 transition-colors" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z"/></svg>
            <input 
              type="text" 
              placeholder={`Quick lookup ${activeTab}...`} 
              value={searchTerm}
              onChange={e => setSearchTerm(e.target.value)}
              className="w-full bg-white border border-slate-200 rounded-[1.2rem] md:rounded-[1.5rem] py-3 md:py-4 pl-14 pr-12 outline-none focus:ring-4 focus:ring-amber-500/10 focus:border-amber-500/30 transition-all shadow-sm font-medium text-sm md:text-base"
            />
            {activeTab === 'products' && (
              <button 
                onClick={() => setShowScanner(true)}
                className="absolute right-3 top-1/2 -translate-y-1/2 p-2 bg-slate-50 text-slate-400 rounded-xl hover:text-amber-600 hover:bg-amber-50 transition-all"
              >
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z"/><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 13a3 3 0 11-6 0 3 3 0 016 0z"/></svg>
              </button>
            )}
          </div>
        </div>

        <div className="grid grid-cols-2 sm:grid-cols-2 md:grid-cols-3 xl:grid-cols-4 gap-3 md:gap-5 overflow-y-auto pr-1 pb-20 md:pb-12 scrollbar-hide flex-1">
          <AnimatePresence mode="popLayout">
            {filteredItems.map(item => (
              <motion.button 
                layout
                initial={{ opacity: 0, scale: 0.95 }}
                animate={{ opacity: 1, scale: 1 }}
                key={item.id} 
                onClick={() => addToCart(item, activeTab === 'services' ? 'service' : 'product')} 
                className="bg-white p-4 md:p-7 rounded-[1.8rem] md:rounded-[2.5rem] border border-slate-100 shadow-sm hover:border-amber-400 hover:shadow-xl hover:shadow-amber-500/5 transition-all text-left group relative overflow-hidden active:scale-95"
              >
                <div className={`w-10 h-10 md:w-12 md:h-12 ${activeTab === 'services' ? 'bg-amber-50 text-amber-600' : 'bg-indigo-50 text-indigo-600'} rounded-xl md:rounded-2xl flex items-center justify-center mb-4 md:mb-6 transition-transform duration-300 group-hover:scale-110 group-hover:rotate-6`}>
                  <span className="text-[10px] md:text-sm font-black">{activeTab === 'services' ? (item as Service).category.substring(0,2).toUpperCase() : 'PR'}</span>
                </div>
                <h4 className="font-bold text-slate-800 text-[11px] md:text-sm mb-1 md:mb-1.5 line-clamp-2 leading-tight h-8 md:h-10">{item.name}</h4>
                <p className="text-xl md:text-2xl font-black text-slate-950 tracking-tight">{settings.currency}{item.price}</p>
                <div className="flex justify-between items-center mt-3 md:mt-4">
                   <span className="px-2 md:px-3 py-0.5 md:py-1 bg-slate-50 rounded-full text-[8px] md:text-[9px] text-slate-400 font-black uppercase tracking-widest truncate">
                     {activeTab === 'services' ? `${(item as Service).duration}M` : `${(item as Product).stock} STK`}
                   </span>
                </div>
                <div className="absolute top-3 right-3 md:top-4 md:right-4 opacity-100 md:opacity-0 group-hover:opacity-100 transition-opacity">
                   <div className="bg-amber-500 text-slate-950 p-1 md:p-1.5 rounded-full shadow-lg scale-75 md:scale-100">
                      <svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M12 4v16m8-8H4"/></svg>
                   </div>
                </div>
              </motion.button>
            ))}
          </AnimatePresence>
        </div>

        {heldSales.length > 0 && !showMobileCart && (
          <motion.div initial={{ y: 20, opacity: 0 }} animate={{ y: 0, opacity: 1 }} className="mt-auto border-t border-slate-200/50 pt-4 md:pt-5 pb-4 mb-16 lg:mb-4">
             <p className="text-[9px] md:text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mb-3 px-1">Active Suspensions</p>
             <div className="flex gap-3 md:gap-4 overflow-x-auto pb-2 scrollbar-hide">
               {heldSales.map(held => (
                 <button 
                  key={held.id} 
                  onClick={() => resumeSale(held)}
                  className="flex-shrink-0 bg-white border border-amber-200/50 px-4 md:px-5 py-2 md:py-3 rounded-xl md:rounded-2xl flex items-center gap-3 md:gap-4 hover:bg-amber-50 hover:border-amber-400 transition-all shadow-sm active:scale-95"
                 >
                   <div className="w-8 h-8 md:w-10 md:h-10 rounded-lg md:rounded-xl bg-amber-100 text-amber-700 flex items-center justify-center font-black text-[10px] md:text-sm">{held.id}</div>
                   <div className="text-left">
                     <p className="text-[11px] md:text-sm font-extrabold text-slate-800">{held.cart.length} Items</p>
                     <p className="text-[8px] md:text-[10px] text-slate-400 font-bold uppercase">{new Date(held.timestamp).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}</p>
                   </div>
                 </button>
               ))}
             </div>
          </motion.div>
        )}
      </div>

      {/* Cart View (Responsive Toggle) */}
      <div className={`
        fixed inset-0 lg:relative lg:inset-auto z-[70] lg:z-10
        w-full lg:w-[440px] bg-white rounded-none lg:rounded-[3rem] border-none lg:border lg:border-slate-100 shadow-none lg:shadow-xl 
        flex-col overflow-hidden transition-transform duration-300
        ${showMobileCart ? 'translate-y-0 flex' : 'translate-y-full lg:translate-y-0 lg:flex'}
      `}>
        {/* Mobile Cart Header */}
        <div className="lg:hidden p-6 bg-slate-900 text-white flex justify-between items-center">
          <h3 className="text-xl font-bold tracking-tight">Checkout Cart</h3>
          <button onClick={() => setShowMobileCart(false)} className="p-2 hover:bg-white/10 rounded-full transition-colors">
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M6 18L18 6M6 6l12 12"/></svg>
          </button>
        </div>

        <div className="p-6 md:p-10 border-b border-slate-50 flex justify-between items-center bg-white">
          <div className="space-y-1">
            <h3 className="text-xl md:text-2xl font-black text-slate-900 tracking-tight">Review Cart</h3>
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{cart.length} items added</p>
          </div>
          {cart.length > 0 && (
