import React, { useState } from 'react';
import { Sale, Expense } from '../types';
import { getFinancialInsights } from '../services/geminiService';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer } from 'recharts';
import { motion } from 'framer-motion';

interface FinanceProps {
  sales: Sale[];
  expenses: Expense[];
  onAddExpense: (expense: Expense) => void;
  currency: string;
}

const Finance: React.FC<FinanceProps> = ({ sales, expenses, onAddExpense, currency }) => {
  const [loadingInsights, setLoadingInsights] = useState(false);
  const [insights, setInsights] = useState<string | null>(null);
  const [newExpense, setNewExpense] = useState({ category: '', amount: 0, description: '' });

  const totalRevenue = sales.reduce((acc, s) => acc + s.total, 0);
  const totalExpenses = expenses.reduce((acc, e) => acc + e.amount, 0);
  const profit = totalRevenue - totalExpenses;

  const handleGenerateInsights = async () => {
    setLoadingInsights(true);
    const result = await getFinancialInsights(sales, expenses);
    setInsights(result);
    setLoadingInsights(false);
  };

  const data = [
    { name: 'Summary', revenue: totalRevenue, expenses: totalExpenses, profit: profit }
  ];

  return (
    <div className="grid grid-cols-1 xl:grid-cols-3 gap-6 md:gap-8">
      {/* Financial Charts & AI */}
      <div className="xl:col-span-2 space-y-6">
        <div className="bg-white p-6 md:p-8 rounded-[2rem] md:rounded-3xl border border-slate-100 shadow-sm no-print">
          <h3 className="text-lg md:text-xl font-bold text-slate-800 mb-6 md:mb-8 flex items-center gap-3">
            <div className="w-10 h-10 bg-amber-50 rounded-xl flex items-center justify-center text-amber-500">
               <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M11 3.055A9.001 9.001 0 1020.945 13H11V3.055z"/><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M20.488 9H15V3.512A9.025 9.025 0 0120.488 9z"/></svg>
            </div>
            Shop Performance
          </h3>
          <div className="h-64 md:h-80 w-full">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={data} margin={{top: 20, right: 30, left: 0, bottom: 5}}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis dataKey="name" axisLine={false} tickLine={false} />
                <YAxis axisLine={false} tickLine={false} />
                <Tooltip cursor={{fill: 'transparent'}} contentStyle={{borderRadius: '12px', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)'}} />
                <Legend iconType="circle" />
                <Bar dataKey="revenue" fill="#10b981" radius={[8, 8, 0, 0]} />
                <Bar dataKey="expenses" fill="#f43f5e" radius={[8, 8, 0, 0]} />
                <Bar dataKey="profit" fill="#3b82f6" radius={[8, 8, 0, 0]} />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>

        {/* AI Insights Section */}
        <div className="bg-slate-900 text-white p-6 md:p-8 rounded-[2rem] md:rounded-3xl shadow-xl overflow-hidden relative no-print">
          <div className="absolute top-0 right-0 p-8 opacity-5">
             <svg className="w-24 h-24 md:w-32 md:h-32" fill="currentColor" viewBox="0 0 24 24"><path d="M12 2L2 7l10 5 10-5-10-5zM2 17l10 5 10-5-10-5-10 5z"/></svg>
          </div>
          <div className="relative z-10">
            <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 mb-6">
              <h3 className="text-lg md:text-xl font-bold flex items-center gap-2">
                <span className="text-amber-400 text-2xl">✨</span> Smart AI Insights
              </h3>
              <button
                onClick={handleGenerateInsights}
                disabled={loadingInsights}
                className="bg-amber-500 hover:bg-amber-600 text-slate-900 px-6 py-2.5 rounded-xl font-black text-sm transition-all disabled:opacity-50 shadow-lg shadow-amber-500/20 active:scale-95"
              >
                {loadingInsights ? 'Analyzing...' : 'Generate Advice'}
              </button>
            </div>
            <div className="bg-slate-800/50 rounded-2xl p-6 min-h-[150px] border border-slate-700/50">
                {insights ? (
                  <div className="prose prose-invert max-w-none">
                    <p className="whitespace-pre-wrap leading-relaxed text-slate-300 text-sm md:text-base">
                      {insights}
                    </p>
                  </div>
                ) : (
                  <div className="flex flex-col items-center justify-center h-full text-slate-500 py-6 md:py-8 text-center">
                    <p className="italic text-xs md:text-sm">Tap "Generate Advice" for a personalized business analysis based on your shop's recent activities.</p>
                  </div>
                )}
            </div>
          </div>
        </div>
      </div>

      {/* Expense Management Sidebar */}
      <div className="space-y-6 no-print">
        <div className="bg-white p-6 md:p-7 rounded-[2rem] border border-slate-100 shadow-sm">
          <h3 className="text-lg font-bold text-slate-800 mb-6 flex items-center gap-3">
            <div className="w-8 h-8 rounded-lg bg-rose-50 text-rose-500 flex items-center justify-center">
               <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M12 9v3m0 0v3m0-3h3m-3 0H9m12 0a9 9 0 11-18 0 9 9 0 0118 0z"/></svg>
            </div>
            New Expense
          </h3>
          <div className="space-y-4">
            <div>
              <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-2 ml-1">Category</label>
              <input
                type="text"
                value={newExpense.category}
                onChange={e => setNewExpense({...newExpense, category: e.target.value})}
                placeholder="Rent, Supplies, etc..."
                className="w-full bg-slate-50 border-0 rounded-xl px-4 py-3 focus:ring-2 focus:ring-amber-400 outline-none text-sm"
              />
            </div>
            <div>
              <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-2 ml-1">Amount ({currency})</label>
              <input
                type="number"
                value={newExpense.amount}
                onChange={e => setNewExpense({...newExpense, amount: Number(e.target.value)})}
                className="w-full bg-slate-50 border-0 rounded-xl px-4 py-3 focus:ring-2 focus:ring-amber-400 outline-none text-sm"
              />
            </div>
            <div>
              <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-2 ml-1">Details</label>
              <textarea
                value={newExpense.description}
                onChange={e => setNewExpense({...newExpense, description: e.target.value})}
                className="w-full bg-slate-50 border-0 rounded-xl px-4 py-3 focus:ring-2 focus:ring-amber-400 outline-none h-20 resize-none text-sm"
                placeholder="Note down any details..."
              />
            </div>
            <button
              onClick={() => {
                if (!newExpense.category || newExpense.amount <= 0) return;
                onAddExpense({
                  id: Math.random().toString(36).substr(2, 9),
                  date: new Date().toISOString().split('T')[0],
                  category: newExpense.category,
                  amount: newExpense.amount,
                  description: newExpense.description
                });
                setNewExpense({ category: '', amount: 0, description: '' });
              }}
              className="w-full bg-slate-900 text-white py-4 rounded-xl font-black text-sm hover:bg-slate-800 transition-all shadow-lg active:scale-95"
            >
              Add Expense
            </button>
          </div>
        </div>

        <div className="bg-white p-6 md:p-7 rounded-[2rem] border border-slate-100 shadow-sm overflow-hidden">
          <h3 className="text-lg font-bold text-slate-800 mb-5">History</h3>
          <div className="space-y-3 max-h-[300px] overflow-y-auto pr-2 scrollbar-hide">
            {expenses.slice().reverse().map(exp => (
              <div key={exp.id} className="flex justify-between items-center py-3 border-b border-slate-50 last:border-0 group">
                <div>
                  <p className="font-extrabold text-slate-800 text-sm">{exp.category}</p>
                  <p className="text-[10px] text-slate-400 font-bold uppercase">{new Date(exp.date).toLocaleDateString()}</p>
                </div>
                <div className="text-right">
                    <p className="font-black text-rose-500">{currency}{exp.amount.toLocaleString()}</p>
                </div>
              </div>
            ))}
            {expenses.length === 0 && (
                <p className="text-center py-8 text-slate-300 italic text-xs">No records found.</p>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default Finance;

import React, { useState } from 'react';
import { Customer, Sale } from '../types';
import { motion, AnimatePresence } from 'framer-motion';

interface CustomersProps {
  customers: Customer[];
  sales: Sale[];
  onAddCustomer: (customer: Customer) => void;
  currency: string;
}

const Customers: React.FC<CustomersProps> = ({ customers, sales, onAddCustomer, currency }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedCustomer, setSelectedCustomer] = useState<Customer | null>(null);
  const [isAdding, setIsAdding] = useState(false);
  const [newCust, setNewCust] = useState({ name: '', phone: '', email: '', notes: '' });

  const filteredCustomers = customers.filter(c => 
    c.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
    c.phone.includes(searchTerm)
  );

  const getCustomerStats = (id: string) => {
    const custSales = sales.filter(s => s.customerId === id);
    const totalSpent = custSales.reduce((acc, s) => acc + s.total, 0);
    const lastVisit = custSales.length > 0 
      ? new Date(custSales.sort((a,b) => b.timestamp.localeCompare(a.timestamp))[0].timestamp).toLocaleDateString()
      : 'Never';
    return { totalSpent, lastVisit, visitCount: custSales.length };
  };

  const customerTransactions = selectedCustomer 
    ? sales.filter(s => s.customerId === selectedCustomer.id).sort((a,b) => b.timestamp.localeCompare(a.timestamp))
    : [];

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 no-print">
        <div>
          <h2 className="text-2xl md:text-3xl font-bold text-slate-800 font-brand">Directory</h2>
          <p className="text-slate-500 text-sm">Client profiles and history.</p>
        </div>
        <button 
          onClick={() => setIsAdding(true)}
          className="bg-slate-900 text-white px-6 py-3 rounded-xl font-bold flex items-center gap-2 hover:bg-slate-800 transition-all shadow-lg text-sm w-full sm:w-auto justify-center"
        >
          <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M12 6v6m0 0v6m0-6h6m-6 0H6"/></svg>
          Add Client
        </button>
      </div>

      <div className="relative no-print">
        <svg className="w-5 h-5 absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z"/></svg>
        <input 
          type="text" 
          placeholder="Search clients..." 
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
          className="w-full bg-white border border-slate-200 rounded-2xl py-3.5 pl-12 pr-6 outline-none focus:ring-4 focus:ring-amber-500/10 shadow-sm text-sm"
        />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 md:gap-8">
        {/* List of Customers */}
        <div className={`lg:col-span-1 space-y-3 max-h-[50vh] lg:max-h-[70vh] overflow-y-auto pr-1 no-print scrollbar-hide ${selectedCustomer ? 'hidden lg:block' : 'block'}`}>
          {filteredCustomers.map(customer => {
            const stats = getCustomerStats(customer.id);
            return (
              <div 
                key={customer.id} 
                onClick={() => setSelectedCustomer(customer)}
                className={`bg-white p-4 rounded-2xl border transition-all cursor-pointer flex justify-between items-center ${selectedCustomer?.id === customer.id ? 'border-amber-400 ring-4 ring-amber-100/50 shadow-md' : 'border-slate-100 hover:border-slate-200 shadow-sm'}`}
              >
                <div className="flex items-center gap-3">
                  <div className="w-9 h-9 rounded-full bg-slate-100 flex items-center justify-center text-slate-500 text-sm font-black uppercase">
                    {customer.name.charAt(0)}
                  </div>
                  <div>
                    <h4 className="font-bold text-slate-800 text-xs truncate max-w-[120px]">{customer.name}</h4>
                    <p className="text-[9px] text-slate-400 font-bold uppercase tracking-tight">{customer.phone}</p>
                  </div>
                </div>
                <div className="text-right">
                    <p className="text-[8px] text-slate-400 uppercase font-black tracking-widest">Visits</p>
                    <p className="text-xs font-black text-amber-600">{stats.visitCount}</p>
                </div>
              </div>
            );
          })}
        </div>

        {/* Selected Customer Profile */}
        <div className={`lg:col-span-2 space-y-6 ${!selectedCustomer ? 'hidden lg:block' : 'block'}`}>
          {selectedCustomer ? (
