import React, { useState } from 'react';
import { Service, Product, ShopSettings } from '../types';
import { motion, AnimatePresence } from 'framer-motion';

interface InventoryProps {
  services: Service[];
  products: Product[];
  settings: ShopSettings;
  onUpdateServices: (services: Service[]) => void;
  onUpdateProducts: (products: Product[]) => void;
}

const Inventory: React.FC<InventoryProps> = ({ services, products, settings, onUpdateServices, onUpdateProducts }) => {
  const [activeTab, setActiveTab] = useState<'services' | 'products'>('services');
  const [isEditing, setIsEditing] = useState<any>(null);

  const deleteItem = (id: string, type: 'service' | 'product') => {
    if (!confirm('Permanently delete this entry?')) return;
    if (type === 'service') {
      onUpdateServices(services.filter(s => s.id !== id));
    } else {
      onUpdateProducts(products.filter(p => p.id !== id));
    }
  };

  const saveItem = (e: React.FormEvent) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget as HTMLFormElement);
    const itemData = Object.fromEntries(formData.entries());

    if (activeTab === 'services') {
      const newService: Service = {
        id: isEditing?.id || Math.random().toString(36).substr(2, 9).toUpperCase(),
        name: itemData.name as string,
        price: parseFloat(itemData.price as string),
        duration: parseInt(itemData.duration as string),
        category: itemData.category as string,
      };
      if (isEditing.id) {
        onUpdateServices(services.map(s => s.id === isEditing.id ? newService : s));
      } else {
        onUpdateServices([...services, newService]);
      }
    } else {
      const newProduct: Product = {
        id: isEditing?.id || Math.random().toString(36).substr(2, 9).toUpperCase(),
        name: itemData.name as string,
        price: parseFloat(itemData.price as string),
        cost: parseFloat(itemData.cost as string),
        stock: parseInt(itemData.stock as string),
        barcode: itemData.barcode as string || undefined,
      };
      if (isEditing.id) {
        onUpdateProducts(products.map(p => p.id === isEditing.id ? newProduct : p));
      } else {
        onUpdateProducts([...products, newProduct]);
      }
    }
    setIsEditing(null);
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
        <div>
          <h2 className="text-2xl md:text-3xl font-bold text-slate-800 font-brand">Shop Catalog</h2>
          <p className="text-slate-500 text-sm">Update prices and stock.</p>
        </div>
        <button 
          onClick={() => setIsEditing({})}
          className="bg-slate-950 text-white px-6 py-3 rounded-xl font-black flex items-center gap-2 hover:bg-slate-800 transition-all shadow-lg text-sm w-full sm:w-auto justify-center"
        >
          <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M12 6v6m0 0v6m0-6h6m-6 0H6"/></svg>
          New {activeTab === 'services' ? 'Service' : 'Product'}
        </button>
      </div>

      <div className="flex bg-white p-1 rounded-xl shadow-sm border border-slate-100 self-start w-full sm:w-auto">
        <button 
          onClick={() => setActiveTab('services')}
          className={`flex-1 sm:px-8 py-2.5 rounded-lg font-bold transition-all text-xs md:text-sm ${activeTab === 'services' ? 'bg-amber-500 text-slate-950 shadow-sm' : 'text-slate-400 hover:text-slate-600'}`}
        >
          Services
        </button>
        <button 
          onClick={() => setActiveTab('products')}
          className={`flex-1 sm:px-8 py-2.5 rounded-lg font-bold transition-all text-xs md:text-sm ${activeTab === 'products' ? 'bg-amber-500 text-slate-950 shadow-sm' : 'text-slate-400 hover:text-slate-600'}`}
        >
          Inventory
        </button>
      </div>

      <div className="bg-white rounded-[2rem] border border-slate-100 shadow-sm overflow-hidden">
        <div className="overflow-x-auto scrollbar-hide">
          <table className="w-full text-left min-w-[600px]">
            <thead>
              <tr className="bg-slate-50/50 border-b border-slate-100 text-[10px] font-black text-slate-400 uppercase tracking-widest">
                <th className="px-8 py-5">Item Details</th>
                <th className="px-8 py-5">{activeTab === 'services' ? 'Category' : 'Stock Status'}</th>
                <th className="px-8 py-5">Price</th>
                <th className="px-8 py-5 text-right">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-50">
              {activeTab === 'services' ? (
                services.map(s => (
                  <tr key={s.id} className="hover:bg-slate-50/30 transition-colors">
                    <td className="px-8 py-6">
                      <p className="font-bold text-slate-800 text-sm">{s.name}</p>
                      <p className="text-[10px] text-slate-400 font-mono tracking-tighter uppercase">{s.duration} minutes session</p>
                    </td>
                    <td className="px-8 py-6">
                      <span className="px-3 py-1 bg-amber-50 text-amber-700 rounded-full text-[9px] font-black uppercase tracking-widest border border-amber-100">{s.category}</span>
                    </td>
                    <td className="px-8 py-6 font-black text-slate-950">{settings.currency}{s.price}</td>
                    <td className="px-8 py-6 text-right space-x-2">
                      <button onClick={() => setIsEditing(s)} className="p-2 text-slate-300 hover:text-amber-500 transition-colors"><svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z"/></svg></button>
                      <button onClick={() => deleteItem(s.id, 'service')} className="p-2 text-slate-300 hover:text-rose-500 transition-colors"><svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"/></svg></button>
                    </td>
                  </tr>
                ))
              ) : (
                products.map(p => (
                  <tr key={p.id} className="hover:bg-slate-50/30 transition-colors">
                    <td className="px-8 py-6">
                      <p className="font-bold text-slate-800 text-sm">{p.name}</p>
                      <p className="text-[10px] text-slate-400 font-mono">Barcode: {p.barcode || 'NO BARCODE'}</p>
                    </td>
                    <td className="px-8 py-6">
                      <div className="flex flex-col gap-1">
                        <p className="text-xs font-bold text-slate-800">Cost: {settings.currency}{p.cost}</p>
                        <p className={`text-[10px] font-black uppercase tracking-widest ${p.stock < 10 ? 'text-rose-500' : 'text-emerald-500'}`}>
                           {p.stock} Units left
                        </p>
                      </div>
                    </td>
                    <td className="px-8 py-6 font-black text-slate-950">{settings.currency}{p.price}</td>
                    <td className="px-8 py-6 text-right space-x-2">
                      <button onClick={() => setIsEditing(p)} className="p-2 text-slate-300 hover:text-amber-500 transition-colors"><svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z"/></svg></button>
                      <button onClick={() => deleteItem(p.id, 'product')} className="p-2 text-slate-300 hover:text-rose-500 transition-colors"><svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"/></svg></button>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </div>

      <AnimatePresence>
        {isEditing && (
          <div className="fixed inset-0 bg-slate-950/40 backdrop-blur-sm z-[100] flex items-end sm:items-center justify-center p-0 sm:p-4">
            <motion.div 
              initial={{ y: "100%" }}
              animate={{ y: 0 }}
              exit={{ y: "100%" }}
              className="bg-white rounded-t-[2.5rem] sm:rounded-[2.5rem] w-full max-w-md p-8 md:p-10 shadow-2xl overflow-y-auto max-h-[90vh]"
            >
              <div className="flex justify-between items-center mb-8">
                <h3 className="text-2xl font-black text-slate-900 tracking-tight">{isEditing.id ? 'Edit Entry' : 'New Entry'}</h3>
                <button onClick={() => setIsEditing(null)} className="p-2 bg-slate-50 rounded-full text-slate-400">
                  <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M6 18L18 6M6 6l12 12"/></svg>
                </button>
              </div>
              <form onSubmit={saveItem} className="space-y-5">
                <div>
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-2 ml-1">Label Name</label>
                  <input name="name" type="text" defaultValue={isEditing.name || ''} required className="w-full bg-slate-50 border-0 rounded-2xl px-5 py-3.5 focus:ring-4 focus:ring-amber-500/10 outline-none text-sm font-bold" />
                </div>
                {activeTab === 'products' && (
                  <div>
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-2 ml-1">Barcode</label>
                    <input name="barcode" type="text" defaultValue={isEditing.barcode || ''} className="w-full bg-slate-50 border-0 rounded-2xl px-5 py-3.5 focus:ring-4 focus:ring-amber-500/10 outline-none text-sm font-bold" placeholder="EAN / UPC code..." />
                  </div>
                )}
                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-2 ml-1">Price ({settings.currency})</label>
                    <input name="price" type="number" step="0.01" defaultValue={isEditing.price || ''} required className="w-full bg-slate-50 border-0 rounded-2xl px-5 py-3.5 focus:ring-4 focus:ring-amber-500/10 outline-none text-sm font-bold" />
                  </div>
                  {activeTab === 'services' ? (
                    <div>
                      <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-2 ml-1">Mins</label>
                      <input name="duration" type="number" defaultValue={isEditing.duration || 30} required className="w-full bg-slate-50 border-0 rounded-2xl px-5 py-3.5 focus:ring-4 focus:ring-amber-500/10 outline-none text-sm font-bold" />
                    </div>
                  ) : (
                    <div>
                      <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-2 ml-1">Cost ({settings.currency})</label>
                      <input name="cost" type="number" step="0.01" defaultValue={isEditing.cost || ''} required className="w-full bg-slate-50 border-0 rounded-2xl px-5 py-3.5 focus:ring-4 focus:ring-amber-500/10 outline-none text-sm font-bold" />
                    </div>
                  )}
                </div>
                {activeTab === 'services' ? (
                  <div>
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-2 ml-1">Category</label>
                    <input name="category" type="text" defaultValue={isEditing.category || ''} required className="w-full bg-slate-50 border-0 rounded-2xl px-5 py-3.5 focus:ring-4 focus:ring-amber-500/10 outline-none text-sm font-bold" />
                  </div>
                ) : (
                  <div>
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-2 ml-1">Initial Stock</label>
                    <input name="stock" type="number" defaultValue={isEditing.stock || 0} required className="w-full bg-slate-50 border-0 rounded-2xl px-5 py-3.5 focus:ring-4 focus:ring-amber-500/10 outline-none text-sm font-bold" />
                  </div>
                )}
                <div className="flex gap-4 mt-8">
                  <button type="submit" className="flex-1 px-4 py-4 bg-slate-950 text-white rounded-2xl font-black text-base hover:bg-slate-800 transition-all shadow-xl">
                    Save Changes
                  </button>
                </div>
              </form>
            </motion.div>
          </div>
        )}
      </AnimatePresence>
    </div>
  );
};

