export default StaffManagement;

import React, { useState, useMemo, useEffect } from 'react';
import { Service, Product, Staff, Sale, SaleItem, Customer, ShopSettings, HeldSale } from '../types';
import { INITIAL_DISCOUNT_CODES } from '../constants';
import { jsPDF } from 'jspdf';
import { motion, AnimatePresence } from 'framer-motion';

interface POSProps {
  services: Service[];
  products: Product[];
  staff: Staff[];
  customers: Customer[];
  settings: ShopSettings;
  onCompleteSale: (sale: Sale) => void;
  onAddCustomer: (customer: Customer) => void;
}

const POS: React.FC<POSProps> = ({ services, products, staff, customers, settings, onCompleteSale, onAddCustomer }) => {
  const [cart, setCart] = useState<SaleItem[]>([]);
  const [selectedStaff, setSelectedStaff] = useState<string>('');
  const [selectedCustomer, setSelectedCustomer] = useState<string>('');
  const [discountCode, setDiscountCode] = useState<string>('');
  const [activeTab, setActiveTab] = useState<'services' | 'products'>('services');
  const [lastSale, setLastSale] = useState<Sale | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [heldSales, setHeldSales] = useState<HeldSale[]>([]);
  const [showScanner, setShowScanner] = useState(false);
  const [scanningFeedback, setScanningFeedback] = useState<string | null>(null);
  const [showMobileCart, setShowMobileCart] = useState(false);

  // Barcode Hardware Support
  useEffect(() => {
    let barcodeBuffer = '';
    let lastKeyTime = Date.now();
    const handleKeyDown = (e: KeyboardEvent) => {
      const currentTime = Date.now();
      if (currentTime - lastKeyTime > 50) barcodeBuffer = '';
      if (e.key === 'Enter') {
        if (barcodeBuffer.length > 3) {
          const product = products.find(p => p.barcode === barcodeBuffer);
          if (product) {
            addToCart(product, 'product');
            setScanningFeedback(product.name);
            setTimeout(() => setScanningFeedback(null), 2000);
          }
          barcodeBuffer = '';
        }
      } else if (e.key.length === 1) barcodeBuffer += e.key;
      lastKeyTime = currentTime;
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [products]);

  const addToCart = (item: Service | Product, type: 'service' | 'product') => {
    setCart(prev => {
      const existing = prev.find(i => i.id === item.id && i.type === type);
      if (existing) {
        return prev.map(i => i.id === item.id && i.type === type ? { ...i, quantity: i.quantity + 1 } : i);
      }
      return [...prev, { id: item.id, name: item.name, price: item.price, type, quantity: 1 }];
    });
  };

  const updateQuantity = (id: string, type: 'service' | 'product', delta: number) => {
    setCart(prev => prev.map(item => {
      if (item.id === id && item.type === type) {
        return { ...item, quantity: Math.max(1, item.quantity + delta) };
      }
      return item;
    }));
  };

  const removeFromCart = (id: string, type: 'service' | 'product') => {
    setCart(prev => prev.filter(i => !(i.id === id && i.type === type)));
  };

  const holdSale = () => {
    if (cart.length === 0) return;
    const newHeldSale: HeldSale = {
      id: Math.random().toString(36).substr(2, 5).toUpperCase(),
      timestamp: new Date().toISOString(),
      cart: [...cart],
      customerId: selectedCustomer,
      staffId: selectedStaff
    };
    setHeldSales([...heldSales, newHeldSale]);
    setCart([]);
    setSelectedCustomer('');
    setSelectedStaff('');
    setShowMobileCart(false);
  };

  const resumeSale = (held: HeldSale) => {
    setCart(held.cart);
    setSelectedCustomer(held.customerId || '');
    setSelectedStaff(held.staffId || '');
    setHeldSales(heldSales.filter(h => h.id !== held.id));
    setShowMobileCart(true);
  };

  const appliedDiscount = useMemo(() => {
    const code = INITIAL_DISCOUNT_CODES.find(c => c.code === discountCode.toUpperCase());
    return code || null;
  }, [discountCode]);

  const subtotal = cart.reduce((acc, item) => acc + (item.price * item.quantity), 0);
  const discountAmount = appliedDiscount 
    ? (appliedDiscount.type === 'percentage' ? (subtotal * appliedDiscount.value / 100) : appliedDiscount.value)
    : 0;
  const tax = (subtotal - discountAmount) * (settings.taxRate / 100);
  const total = subtotal - discountAmount + tax;

  const handleComplete = (method: 'cash' | 'card') => {
    if (!selectedStaff || cart.length === 0) return;
    const sale: Sale = {
      id: Math.random().toString(36).substr(2, 9).toUpperCase(),
      timestamp: new Date().toISOString(),
      items: [...cart],
      staffId: selectedStaff,
      customerId: selectedCustomer || undefined,
      total: total,
      tax: tax,
      discount: discountAmount,
      discountCode: appliedDiscount?.code,
      paymentMethod: method
    };
    onCompleteSale(sale);
    setLastSale(sale);
    setCart([]);
    setSelectedStaff('');
    setSelectedCustomer('');
    setDiscountCode('');
    setSearchTerm('');
    setShowMobileCart(false);
  };

  const filteredItems = useMemo(() => {
    const term = searchTerm.toLowerCase();
    if (activeTab === 'services') {
      return services.filter(s => s.name.toLowerCase().includes(term) || s.category.toLowerCase().includes(term));
    } else {
      return products.filter(p => p.name.toLowerCase().includes(term) || p.barcode?.includes(term));
    }
  }, [searchTerm, activeTab, services, products]);

  const generatePDF = (sale: Sale) => {
    const doc = new jsPDF({ unit: 'mm', format: [80, 200] });
    const barber = staff.find(s => s.id === sale.staffId)?.name || 'N/A';
    const client = customers.find(c => c.id === sale.customerId)?.name || 'Guest Walk-in';
    const dateStr = new Date(sale.timestamp).toLocaleString();
    const primaryColor = [15, 23, 42]; // Slate-900

    // Header Branding
    doc.setFillColor(15, 23, 42);
    doc.rect(0, 0, 80, 10, 'F');
    doc.setTextColor(245, 158, 11); // Amber-500
    doc.setFont('helvetica', 'bold').setFontSize(10);
    doc.text('OFFICIAL RECEIPT', 40, 7, { align: 'center' });

    doc.setTextColor(primaryColor[0], primaryColor[1], primaryColor[2]);
    doc.setFontSize(16).text(settings.shopName.toUpperCase(), 40, 25, { align: 'center' });
    doc.setFontSize(8).setFont('helvetica', 'normal').text('Professional Grooming & Care', 40, 30, { align: 'center' });

    doc.setDrawColor(226, 232, 240); // Slate-200
    doc.setLineWidth(0.3).line(5, 35, 75, 35);

    // Details Section
    doc.setFontSize(7).setTextColor(100, 116, 139); // Slate-400
    doc.text(`Transaction ID: #${sale.id}`, 5, 42);
    doc.text(`Date & Time: ${dateStr}`, 5, 46);
    doc.text(`Professional: ${barber}`, 5, 50);
    doc.text(`Client: ${client}`, 5, 54);
    doc.line(5, 58, 75, 58);

    // Items Section
    let y = 65;
    doc.setFont('helvetica', 'bold').setFontSize(8).setTextColor(primaryColor[0], primaryColor[1], primaryColor[2]);
    doc.text('DESCRIPTION', 5, y);
    doc.text('QTY', 52, y);
    doc.text('AMOUNT', 75, y, { align: 'right' });
    doc.line(5, y + 2, 75, y + 2);

    doc.setFont('helvetica', 'normal').setFontSize(7);
    y += 7;
    sale.items.forEach(item => {
      doc.text(item.name.substring(0, 25), 5, y);
      doc.text(item.quantity.toString(), 54, y, { align: 'center' });
      doc.text(`${settings.currency}${(item.price * item.quantity).toFixed(2)}`, 75, y, { align: 'right' });
      y += 5;
    });

    // Summary Section
    y += 5;
    doc.setDrawColor(primaryColor[0], primaryColor[1], primaryColor[2]);
    doc.line(5, y, 75, y);
    y += 7;
    doc.setFont('helvetica', 'normal').text('SUBTOTAL:', 5, y);
    doc.text(`${settings.currency}${subtotal.toFixed(2)}`, 75, y, { align: 'right' });
    y += 5;

    if (sale.discount > 0) {
      doc.text(`DISCOUNT (${sale.discountCode || 'Applied'}):`, 5, y);
      doc.text(`-${settings.currency}${sale.discount.toFixed(2)}`, 75, y, { align: 'right' });
      y += 5;
    }

    doc.text(`TAX (${settings.taxRate}%):`, 5, y);
    doc.text(`${settings.currency}${sale.tax.toFixed(2)}`, 75, y, { align: 'right' });
    y += 7;

    doc.setFillColor(248, 250, 252); // Slate-50
    doc.rect(5, y - 4, 70, 8, 'F');
    doc.setFontSize(10).setFont('helvetica', 'bold').text('TOTAL PAID:', 7, y + 1.5);
    doc.text(`${settings.currency}${sale.total.toFixed(2)}`, 73, y + 1.5, { align: 'right' });

    y += 15;
    doc.setFontSize(7).setFont('helvetica', 'italic').setTextColor(148, 163, 184); // Slate-400
    doc.text(settings.receiptFooter, 40, y, { align: 'center' });
    doc.text('Thank you for your visit!', 40, y + 4, { align: 'center' });

    // Bottom Border
    doc.setFillColor(15, 23, 42);
    doc.rect(0, 195, 80, 5, 'F');

    return doc;
  };

  const handleShareReceipt = async (sale: Sale) => {
    const doc = generatePDF(sale);
    const pdfBlob = doc.output('blob');
    const file = new File([pdfBlob], `Receipt-${sale.id}.pdf`, { type: 'application/pdf' });

    if (navigator.share && navigator.canShare && navigator.canShare({ files: [file] })) {
      try {
        await navigator.share({
          files: [file],
          title: 'TrimTime Receipt',
          text: `Here is your receipt for transaction #${sale.id}`,
        });
      } catch (error) {
        console.error('Error sharing receipt:', error);
        doc.save(`Receipt-${sale.id}.pdf`);
      }
    } else {
      doc.save(`Receipt-${sale.id}.pdf`);
    }
  };

  return (
    <div className="flex flex-col lg:flex-row gap-8 h-auto lg:h-[calc(100vh-160px)] relative">
      {/* Scanning Notification */}
      <AnimatePresence>
        {scanningFeedback && (
          <motion.div 
            initial={{ opacity: 0, y: -20, scale: 0.9 }}
            animate={{ opacity: 1, y: 0, scale: 1 }}
            exit={{ opacity: 0, scale: 0.9 }}
            className="fixed top-10 left-1/2 -translate-x-1/2 z-[200] bg-slate-900 text-white px-8 py-4 rounded-[2rem] shadow-2xl flex items-center gap-4 border border-slate-800"
          >
            <div className="w-8 h-8 rounded-full bg-emerald-500 flex items-center justify-center">
              <svg className="w-5 h-5 text-slate-950" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M5 13l4 4L19 7"/></svg>
            </div>
            <p className="font-bold text-sm tracking-wide">Added: <span className="text-amber-400">{scanningFeedback}</span></p>
          </motion.div>
        )}
      </AnimatePresence>

      {/* Success Modal */}
      <AnimatePresence>
        {lastSale && (
          <motion.div 
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="fixed inset-0 bg-slate-950/80 backdrop-blur-xl z-[150] flex items-center justify-center p-6 no-print"
          >
            <motion.div 
              initial={{ scale: 0.8, opacity: 0, y: 20 }}
              animate={{ scale: 1, opacity: 1, y: 0 }}
              className="bg-white rounded-[2.5rem] md:rounded-[3rem] p-8 md:p-12 max-w-md w-full shadow-2xl text-center space-y-8"
            >
              <div className="w-20 h-20 md:w-24 md:h-24 bg-emerald-50 text-emerald-500 rounded-full flex items-center justify-center text-4xl md:text-5xl mx-auto shadow-inner">✓</div>
              <div className="space-y-2">
                <h3 className="text-2xl md:text-3xl font-black text-slate-900 tracking-tight">Sale Completed</h3>
                <p className="text-slate-400 font-medium">Order #{lastSale.id} is finalized.</p>
              </div>
              <div className="flex flex-col gap-4">
                <button 
                  onClick={() => handleShareReceipt(lastSale)} 
                  className="w-full bg-slate-950 text-white py-4 md:py-5 rounded-[1.2rem] md:rounded-[1.5rem] font-black flex items-center justify-center gap-3 hover:bg-slate-800 transition-all active:scale-[0.98] shadow-xl"
                >
                  <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M8.684 13.342C8.886 12.938 9 12.482 9 12c0-.482-.114-.938-.316-1.342m0 2.684a3 3 0 110-2.684m0 2.684l6.632 3.316m-6.632-6l6.632-3.316m0 0a3 3 0 105.367-2.684 3 3 0 00-5.367 2.684zm0 9.316a3 3 0 105.368 2.684 3 3 0 00-5.368-2.684z"/></svg>
                  Share Receipt
                </button>
                <button 
                  onClick={() => generatePDF(lastSale).save(`Receipt-${lastSale.id}.pdf`)} 
                  className="w-full bg-slate-100 text-slate-600 py-4 md:py-5 rounded-[1.2rem] md:rounded-[1.5rem] font-black flex items-center justify-center gap-3 hover:bg-slate-200 transition-all"
                >
                  <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4"/></svg>
                  Download PDF
                </button>
                <button onClick={() => setLastSale(null)} className="w-full bg-white text-slate-400 py-4 md:py-5 rounded-[1.2rem] md:rounded-[1.5rem] font-bold hover:text-slate-600 transition-all">Dismiss</button>
              </div>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* Catalog Main View */}
      <div className={`flex-1 flex flex-col min-w-0 ${showMobileCart ? 'hidden lg:flex' : 'flex'}`}>
        <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 md:gap-5 mb-6 md:mb-8">
          <div className="flex items-center bg-white p-1.5 rounded-[1.2rem] md:rounded-[1.5rem] shadow-sm border border-slate-100 self-start md:self-auto">
            <button 
              onClick={() => setActiveTab('services')} 
              className={`px-6 md:px-8 py-2 md:py-3 rounded-xl md:rounded-2xl font-bold transition-all text-sm md:text-base ${activeTab === 'services' ? 'bg-amber-500 text-slate-950 shadow-md' : 'text-slate-400 hover:text-slate-600'}`}
            >
              Services
            </button>
            <button 
              onClick={() => setActiveTab('products')} 
              className={`px-6 md:px-8 py-2 md:py-3 rounded-xl md:rounded-2xl font-bold transition-all text-sm md:text-base ${activeTab === 'products' ? 'bg-amber-500 text-slate-950 shadow-md' : 'text-slate-400 hover:text-slate-600'}`}
            >
              Retail
            </button>
          </div>

          <div className="flex-1 max-w-md relative group">
            <svg className="w-5 h-5 absolute left-5 top-1/2 -translate-y-1/2 text-slate-300 group-focus-within:text-amber-500 transition-colors" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z"/></svg>
            <input 
              type="text" 
              placeholder={`Quick lookup ${activeTab}...`} 
              value={searchTerm}
              onChange={e => setSearchTerm(e.target.value)}
              className="w-full bg-white border border-slate-200 rounded-[1.2rem] md:rounded-[1.5rem] py-3 md:py-4 pl-14 pr-12 outline-none focus:ring-4 focus:ring-amber-500/10 focus:border-amber-500/30 transition-all shadow-sm font-medium text-sm md:text-base"
            />
            {activeTab === 'products' && (
              <button 
                onClick={() => setShowScanner(true)}
                className="absolute right-3 top-1/2 -translate-y-1/2 p-2 bg-slate-50 text-slate-400 rounded-xl hover:text-amber-600 hover:bg-amber-50 transition-all"
              >
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z"/><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 13a3 3 0 11-6 0 3 3 0 016 0z"/></svg>
              </button>
            )}
          </div>
        </div>

        <div className="grid grid-cols-2 sm:grid-cols-2 md:grid-cols-3 xl:grid-cols-4 gap-3 md:gap-5 overflow-y-auto pr-1 pb-20 md:pb-12 scrollbar-hide flex-1">
          <AnimatePresence mode="popLayout">
            {filteredItems.map(item => (
              <motion.button 
                layout
                initial={{ opacity: 0, scale: 0.95 }}
                animate={{ opacity: 1, scale: 1 }}
                key={item.id} 
                onClick={() => addToCart(item, activeTab === 'services' ? 'service' : 'product')} 
                className="bg-white p-4 md:p-7 rounded-[1.8rem] md:rounded-[2.5rem] border border-slate-100 shadow-sm hover:border-amber-400 hover:shadow-xl hover:shadow-amber-500/5 transition-all text-left group relative overflow-hidden active:scale-95"
              >
                <div className={`w-10 h-10 md:w-12 md:h-12 ${activeTab === 'services' ? 'bg-amber-50 text-amber-600' : 'bg-indigo-50 text-indigo-600'} rounded-xl md:rounded-2xl flex items-center justify-center mb-4 md:mb-6 transition-transform duration-300 group-hover:scale-110 group-hover:rotate-6`}>
                  <span className="text-[10px] md:text-sm font-black">{activeTab === 'services' ? (item as Service).category.substring(0,2).toUpperCase() : 'PR'}</span>
                </div>
                <h4 className="font-bold text-slate-800 text-[11px] md:text-sm mb-1 md:mb-1.5 line-clamp-2 leading-tight h-8 md:h-10">{item.name}</h4>
                <p className="text-xl md:text-2xl font-black text-slate-950 tracking-tight">{settings.currency}{item.price}</p>
                <div className="flex justify-between items-center mt-3 md:mt-4">
                   <span className="px-2 md:px-3 py-0.5 md:py-1 bg-slate-50 rounded-full text-[8px] md:text-[9px] text-slate-400 font-black uppercase tracking-widest truncate">
                     {activeTab === 'services' ? `${(item as Service).duration}M` : `${(item as Product).stock} STK`}
                   </span>
                </div>
