      <style>{`
        @keyframes scan {
          0% { top: 0; }
          100% { top: 100%; }
        }
        .animate-scanner-scan {
          position: absolute;
          width: 100%;
          height: 10%;
          animation: scan 2.5s infinite linear;
        }
