import React, { useState, useMemo, useEffect } from 'react';
import { Service, Product, Staff, Sale, SaleItem, Customer, ShopSettings, HeldSale } from '../types';
import { INITIAL_DISCOUNT_CODES } from '../constants';
import { motion, AnimatePresence } from 'framer-motion';

// Fixed missing default export and completed truncated logic
interface POSProps {
  services: Service[];
  products: Product[];
  staff: Staff[];
  customers: Customer[];
  settings: ShopSettings;
  onCompleteSale: (sale: Sale) => void;
  onAddCustomer: (customer: Customer) => void;
}

const POS: React.FC<POSProps> = ({ services, products, staff, customers, settings, onCompleteSale, onAddCustomer }) => {
  const [cart, setCart] = useState<SaleItem[]>([]);
  const [selectedStaff, setSelectedStaff] = useState<string>('');
  const [selectedCustomer, setSelectedCustomer] = useState<string>('');
  const [discountCode, setDiscountCode] = useState<string>('');
  const [activeTab, setActiveTab] = useState<'services' | 'products'>('services');
  const [searchTerm, setSearchTerm] = useState('');
  const [heldSales, setHeldSales] = useState<HeldSale[]>([]);
  const [scanningFeedback, setScanningFeedback] = useState<string | null>(null);
  const [showMobileCart, setShowMobileCart] = useState(false);

  // Barcode Hardware Support
  useEffect(() => {
    let barcodeBuffer = '';
    let lastKeyTime = Date.now();
    const handleKeyDown = (e: KeyboardEvent) => {
      const currentTime = Date.now();
      if (currentTime - lastKeyTime > 50) barcodeBuffer = '';
      if (e.key === 'Enter') {
        if (barcodeBuffer.length > 3) {
          const product = products.find(p => p.barcode === barcodeBuffer);
          if (product) {
            addToCart(product, 'product');
            setScanningFeedback(product.name);
            setTimeout(() => setScanningFeedback(null), 2000);
          }
          barcodeBuffer = '';
        }
      } else if (e.key.length === 1) barcodeBuffer += e.key;
      lastKeyTime = currentTime;
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [products]);

  const addToCart = (item: Service | Product, type: 'service' | 'product') => {
    setCart(prev => {
      const existing = prev.find(i => i.id === item.id && i.type === type);
      if (existing) {
        return prev.map(i => i.id === item.id && i.type === type ? { ...i, quantity: i.quantity + 1 } : i);
      }
      return [...prev, { id: item.id, name: item.name, price: item.price, type, quantity: 1 }];
    });
  };

  const updateQuantity = (id: string, type: 'service' | 'product', delta: number) => {
    setCart(prev => prev.map(item => {
      if (item.id === id && item.type === type) {
        return { ...item, quantity: Math.max(1, item.quantity + delta) };
      }
      return item;
    }));
  };

  const removeFromCart = (id: string, type: 'service' | 'product') => {
    setCart(prev => prev.filter(i => !(i.id === id && i.type === type)));
  };

  const totals = useMemo(() => {
    const subtotal = cart.reduce((acc, item) => acc + (item.price * item.quantity), 0);

    let discount = 0;
    const code = INITIAL_DISCOUNT_CODES.find(c => c.code === discountCode);
    if (code) {
      discount = code.type === 'percentage' ? (subtotal * code.value) / 100 : code.value;
    }

    const taxableAmount = settings.taxType === 'included' ? subtotal - discount : subtotal - discount;
    const tax = (taxableAmount * settings.taxRate) / 100;
    const total = settings.taxType === 'included' ? subtotal - discount : (subtotal - discount) + tax;

    return { subtotal, discount, tax, total };
  }, [cart, discountCode, settings]);

  const handleCheckout = (paymentMethod: 'cash' | 'card') => {
    if (cart.length === 0 || !selectedStaff) {
      alert('Please add items to cart and select a staff member.');
      return;
    }

    const sale: Sale = {
      id: Math.random().toString(36).substr(2, 9).toUpperCase(),
      timestamp: new Date().toISOString(),
      items: cart,
      staffId: selectedStaff,
      customerId: selectedCustomer || undefined,
      total: totals.total,
      tax: totals.tax,
      discount: totals.discount,
      discountCode: discountCode || undefined,
      paymentMethod,
      taxType: settings.taxType,
    };

    onCompleteSale(sale);
    setCart([]);
    setSelectedCustomer('');
    setDiscountCode('');
    setShowMobileCart(false);
    alert('Sale completed successfully!');
  };

  const handleHoldSale = () => {
    if (cart.length === 0) return;
    const newHold: HeldSale = {
      id: Math.random().toString(36).substr(2, 9).toUpperCase(),
      timestamp: new Date().toISOString(),
      cart: [...cart],
      customerId: selectedCustomer || undefined,
      staffId: selectedStaff || undefined,
    };
    setHeldSales([newHold, ...heldSales]);
    setCart([]);
    setSelectedCustomer('');
    alert('Sale held successfully.');
  };

  const retrieveSale = (held: HeldSale) => {
    setCart(held.cart);
    if (held.customerId) setSelectedCustomer(held.customerId);
    if (held.staffId) setSelectedStaff(held.staffId);
    setHeldSales(heldSales.filter(h => h.id !== held.id));
  };

  const filteredItems = useMemo(() => {
    const search = searchTerm.toLowerCase();
    if (activeTab === 'services') {
      return services.filter(s => 
        s.name.toLowerCase().includes(search) || 
        s.category.toLowerCase().includes(search)
      );
    }
    return products.filter(p => p.name.toLowerCase().includes(search));
  }, [activeTab, services, products, searchTerm]);

  return (
    <div className="flex flex-col lg:flex-row gap-6 h-[calc(100vh-12rem)]">
      {/* Left side: Catalog */}
      <div className="flex-1 flex flex-col min-h-0">
        <div className="mb-6 flex flex-col sm:flex-row gap-4">
          <div className="flex-1 relative">
            <svg className="w-5 h-5 absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z"/></svg>
            <input 
              type="text" 
              placeholder="Search services or products..." 
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="w-full bg-white border border-slate-200 rounded-2xl py-3 pl-12 pr-6 outline-none focus:ring-4 focus:ring-amber-500/10 shadow-sm text-sm font-medium"
            />
          </div>
          <div className="flex bg-white p-1 rounded-2xl border border-slate-100 shadow-sm">
            <button 
              onClick={() => setActiveTab('services')}
              className={`px-6 py-2 rounded-xl text-xs font-black uppercase tracking-widest transition-all ${activeTab === 'services' ? 'bg-amber-500 text-slate-900 shadow-md' : 'text-slate-400 hover:text-slate-600'}`}
            >
              Services
            </button>
            <button 
              onClick={() => setActiveTab('products')}
              className={`px-6 py-2 rounded-xl text-xs font-black uppercase tracking-widest transition-all ${activeTab === 'products' ? 'bg-amber-500 text-slate-900 shadow-md' : 'text-slate-400 hover:text-slate-600'}`}
            >
              Products
            </button>
          </div>
        </div>

        <div className="flex-1 overflow-y-auto grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-3 gap-4 pr-2 scrollbar-hide">
          <AnimatePresence mode='popLayout'>
            {filteredItems.map(item => (
              <motion.button
                layout
                key={item.id}
                whileHover={{ scale: 1.02 }}
                whileTap={{ scale: 0.98 }}
                onClick={() => addToCart(item, activeTab === 'services' ? 'service' : 'product')}
                className="bg-white p-5 rounded-[2rem] border border-slate-100 shadow-sm hover:shadow-md transition-all text-left flex flex-col justify-between group h-40 relative overflow-hidden"
              >
                <div className="relative z-10">
                  <span className={`text-[9px] font-black uppercase tracking-widest px-2 py-1 rounded-lg mb-2 inline-block ${activeTab === 'services' ? 'bg-amber-50 text-amber-600' : 'bg-indigo-50 text-indigo-600'}`}>
                    {activeTab === 'services' ? (item as Service).category : 'Inventory'}
                  </span>
                  <h4 className="font-bold text-slate-800 text-sm leading-tight group-hover:text-amber-600 transition-colors">{item.name}</h4>
                  {activeTab === 'services' && <p className="text-[10px] text-slate-400 font-bold mt-1">{(item as Service).duration} min</p>}
                </div>
                <div className="flex items-center justify-between relative z-10">
                  <p className="text-lg font-black text-slate-900">{settings.currency}{item.price}</p>
                  <div className="w-8 h-8 bg-slate-900 text-white rounded-full flex items-center justify-center opacity-0 group-hover:opacity-100 transition-all">
                    <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M12 6v6m0 0v6m0-6h6m-6 0H6"/></svg>
                  </div>
                </div>
                <div className="absolute -right-4 -bottom-4 w-20 h-20 bg-slate-50 rounded-full opacity-0 group-hover:opacity-100 transition-all -z-0"></div>
              </motion.button>
            ))}
          </AnimatePresence>
        </div>
      </div>

      {/* Right side: Cart */}
      <div className={`lg:w-96 flex flex-col bg-white rounded-[2.5rem] border border-slate-100 shadow-xl no-print overflow-hidden ${showMobileCart ? 'fixed inset-0 z-[70] m-0 rounded-none' : 'relative hidden lg:flex'}`}>
        <div className="p-6 border-b border-slate-50 bg-slate-50/50 flex justify-between items-center">
          <h3 className="text-xl font-black text-slate-800 flex items-center gap-2">
            <svg className="w-6 h-6 text-amber-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M16 11V7a4 4 0 00-8 0v4M5 9h14l1 12H4L5 9z"/></svg>
            Current Cart
          </h3>
          <button onClick={() => setShowMobileCart(false)} className="lg:hidden p-2 text-slate-400">
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12"/></svg>
          </button>
        </div>

        <div className="p-6 space-y-4">
          <div>
             <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-2 ml-1">Professional Assigned</label>
             <select 
               value={selectedStaff}
               onChange={(e) => setSelectedStaff(e.target.value)}
               className="w-full bg-slate-50 border-0 rounded-xl px-4 py-3 focus:ring-2 focus:ring-amber-400 outline-none text-sm font-bold"
             >
               <option value="">Select Barber...</option>
               {staff.map(s => <option key={s.id} value={s.id}>{s.name}</option>)}
             </select>
          </div>

          <div>
             <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-2 ml-1">Client (Optional)</label>
             <select 
               value={selectedCustomer}
               onChange={(e) => setSelectedCustomer(e.target.value)}
               className="w-full bg-slate-50 border-0 rounded-xl px-4 py-3 focus:ring-2 focus:ring-amber-400 outline-none text-sm font-bold"
             >
               <option value="">Walk-in Client</option>
               {customers.map(c => <option key={c.id} value={c.id}>{c.name} ({c.phone})</option>)}
             </select>
          </div>
        </div>

        <div className="flex-1 overflow-y-auto px-6 py-2 space-y-3 scrollbar-hide">
          {cart.map(item => (
            <div key={`${item.id}-${item.type}`} className="flex items-center justify-between group">
              <div className="flex-1 min-w-0">
                <p className="text-sm font-bold text-slate-800 truncate">{item.name}</p>
                <p className="text-[10px] text-slate-400 font-bold">{settings.currency}{item.price} each</p>
              </div>
              <div className="flex items-center gap-3">
                <div className="flex items-center bg-slate-100 rounded-lg p-1">
                  <button onClick={() => updateQuantity(item.id, item.type, -1)} className="w-6 h-6 flex items-center justify-center text-slate-500 hover:text-slate-900">-</button>
                  <span className="w-8 text-center text-xs font-black text-slate-800">{item.quantity}</span>
                  <button onClick={() => updateQuantity(item.id, item.type, 1)} className="w-6 h-6 flex items-center justify-center text-slate-500 hover:text-slate-900">+</button>
                </div>
                <button onClick={() => removeFromCart(item.id, item.type)} className="text-slate-300 hover:text-rose-500 transition-colors">
                  <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"/></svg>
                </button>
              </div>
            </div>
          ))}
          {cart.length === 0 && (
            <div className="flex flex-col items-center justify-center h-40 text-slate-300 opacity-50">
              <svg className="w-12 h-12 mb-2" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M3 3h2l.4 2M7 13h10l4-8H5.4M7 13L5.4 5M7 13l-2.293 2.293c-.63.63-.184 1.707.707 1.707H17m0 0a2 2 0 100 4 2 2 0 000-4zm-8 2a2 2 0 11-4 0 2 2 0 014 0z"/></svg>
              <p className="text-xs font-bold uppercase tracking-widest">Cart is empty</p>
            </div>
          )}
        </div>

        <div className="p-6 bg-slate-50/80 border-t border-slate-100 space-y-4">
          <div className="flex justify-between text-slate-500 font-bold text-xs uppercase tracking-tighter">
            <span>Subtotal</span>
            <span>{settings.currency}{totals.subtotal.toFixed(2)}</span>
          </div>
          <div className="flex justify-between items-center">
            <input 
              type="text" 
              placeholder="Promo Code" 
              value={discountCode}
              onChange={(e) => setDiscountCode(e.target.value.toUpperCase())}
              className="bg-transparent border-b border-slate-200 text-xs font-black p-1 outline-none w-24 focus:border-amber-500"
            />
            {totals.discount > 0 && (
              <span className="text-emerald-600 font-black text-xs">-{settings.currency}{totals.discount.toFixed(2)}</span>
            )}
          </div>
          <div className="flex justify-between text-slate-500 font-bold text-xs uppercase tracking-tighter">
            <span>Tax ({settings.taxRate}%)</span>
            <span>{settings.currency}{totals.tax.toFixed(2)}</span>
          </div>
          <div className="flex justify-between items-center pt-2">
            <span className="text-xl font-black text-slate-900 tracking-tight">Total Due</span>
            <span className="text-3xl font-black text-amber-600 tracking-tighter">{settings.currency}{totals.total.toFixed(2)}</span>
          </div>

          <div className="grid grid-cols-2 gap-3 pt-4">
             <button 
               onClick={() => handleCheckout('cash')}
               className="bg-slate-900 text-white py-4 rounded-2xl font-black text-sm hover:bg-slate-800 transition-all flex flex-col items-center gap-1 shadow-lg active:scale-95"
             >
               <span className="text-lg">💵</span> Cash
             </button>
             <button 
               onClick={() => handleCheckout('card')}
               className="bg-amber-500 text-slate-900 py-4 rounded-2xl font-black text-sm hover:bg-amber-600 transition-all flex flex-col items-center gap-1 shadow-lg shadow-amber-500/10 active:scale-95"
             >
               <span className="text-lg">💳</span> Card
             </button>
          </div>

          <button 
            onClick={handleHoldSale}
            className="w-full py-2.5 text-slate-400 hover:text-slate-600 font-bold text-[10px] uppercase tracking-[0.2em] transition-colors"
          >
            Hold Current Sale
          </button>
        </div>
      </div>

      <AnimatePresence>
        {heldSales.length > 0 && !showMobileCart && (
          <motion.div 
            initial={{ opacity: 0, x: 20 }}
            animate={{ opacity: 1, x: 0 }}
            className="fixed bottom-8 right-8 z-50 flex flex-col gap-2 max-w-xs"
          >
            <div className="bg-slate-900 text-white p-4 rounded-2xl shadow-2xl border border-white/5">
              <p className="text-[10px] font-black uppercase tracking-widest text-slate-500 mb-3">Held Transactions ({heldSales.length})</p>
              <div className="space-y-2 max-h-40 overflow-y-auto pr-2 scrollbar-hide">
                {heldSales.map(h => (
                  <div key={h.id} className="flex justify-between items-center bg-white/5 p-2 rounded-xl">
                    <div>
                      <p className="text-xs font-bold">#{h.id.slice(-4)}</p>
                      <p className="text-[9px] text-slate-400">{new Date(h.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</p>
                    </div>
                    <button onClick={() => retrieveSale(h)} className="text-[9px] font-black text-amber-400 uppercase tracking-widest px-2 py-1 bg-amber-400/10 rounded-lg">Resume</button>
                  </div>
                ))}
              </div>
            </div>
          </motion.div>
        )}
      </AnimatePresence>

      <button 
        onClick={() => setShowMobileCart(true)}
        className="lg:hidden fixed bottom-6 left-1/2 -translate-x-1/2 bg-slate-900 text-white px-8 py-4 rounded-full font-black flex items-center gap-3 shadow-2xl z-50 active:scale-95"
      >
        <svg className="w-5 h-5 text-amber-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M16 11V7a4 4 0 00-8 0v4M5 9h14l1 12H4L5 9z"/></svg>
        View Cart ({cart.length})
      </button>

      {scanningFeedback && (
        <div className="fixed top-20 left-1/2 -translate-x-1/2 bg-emerald-500 text-white px-6 py-3 rounded-full font-black text-sm shadow-2xl z-[100] animate-bounce">
          ✓ Scanned: {scanningFeedback}
        </div>
      )}
    </div>
  );
};

