            setTimeout(() => setScanningFeedback(null), 2000);
          }
          barcodeBuffer = '';
        }
      } else if (e.key.length === 1) barcodeBuffer += e.key;
      lastKeyTime = currentTime;
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [products]);

  const addToCart = (item: Service | Product, type: 'service' | 'product') => {
    setCart(prev => {
      const existing = prev.find(i => i.id === item.id && i.type === type);
      if (existing) {
        return prev.map(i => i.id === item.id && i.type === type ? { ...i, quantity: i.quantity + 1 } : i);
      }
      return [...prev, { id: item.id, name: item.name, price: item.price, type, quantity: 1 }];
    });
  };

  const updateQuantity = (id: string, type: 'service' | 'product', delta: number) => {
    setCart(prev => prev.map(item => {
      if (item.id === id && item.type === type) {
        return { ...item, quantity: Math.max(1, item.quantity + delta) };
      }
      return item;
    }));
  };

  const removeFromCart = (id: string, type: 'service' | 'product') => {
    setCart(prev => prev.filter(i => !(i.id === id && i.type === type)));
  };

  const totals = useMemo(() => {
    const rawSubtotal = cart.reduce((acc, item) => acc + (item.price * item.quantity), 0);

    let discount = 0;
    const code = INITIAL_DISCOUNT_CODES.find(c => c.code === discountCode);
    if (code) {
      discount = code.type === 'percentage' ? (rawSubtotal * code.value) / 100 : code.value;
    }

    const discountedAmount = rawSubtotal - discount;
    let tax = 0;
    let total = 0;

    if (settings.taxType === 'included') {
      total = discountedAmount;
      // Tax is already inside the total. Formula: Total - (Total / (1 + Rate))
      tax = total - (total / (1 + (settings.taxRate / 100)));
    } else {
      tax = discountedAmount * (settings.taxRate / 100);
      total = discountedAmount + tax;
    }

    return { subtotal: rawSubtotal, discount, tax, total };
  }, [cart, discountCode, settings]);

  const handleHoldSale = () => {
    if (cart.length === 0) return;
    const newHold: HeldSale = {
      id: Math.random().toString(36).substr(2, 9).toUpperCase(),
      timestamp: new Date().toISOString(),
      cart: [...cart],
      customerId: selectedCustomer || undefined,
      staffId: selectedStaff || undefined,
    };
    setHeldSales([newHold, ...heldSales]);
    setCart([]);
    setSelectedCustomer('');
    setSelectedStaff('');
  };

  const retrieveSale = (held: HeldSale) => {
    setCart(held.cart);
    if (held.customerId) setSelectedCustomer(held.customerId);
    if (held.staffId) setSelectedStaff(held.staffId);
    setHeldSales(heldSales.filter(h => h.id !== held.id));
  };

  const generatePDF = (sale: Sale) => {
    const doc = new jsPDF({ unit: 'mm', format: [80, 200] });
    const barber = staff.find(s => s.id === sale.staffId)?.name || 'N/A';
    const client = customers.find(c => c.id === sale.customerId)?.name || 'Guest Walk-in';
    const dateStr = new Date(sale.timestamp).toLocaleString();
    const primaryColor = [15, 23, 42]; // Slate-900

    // Header Branding
    doc.setFillColor(15, 23, 42);
    doc.rect(0, 0, 80, 10, 'F');
    doc.setTextColor(245, 158, 11); // Amber-500
    doc.setFont('helvetica', 'bold').setFontSize(10);
    doc.text('OFFICIAL RECEIPT', 40, 7, { align: 'center' });

    doc.setTextColor(primaryColor[0], primaryColor[1], primaryColor[2]);
    doc.setFontSize(16).text(settings.shopName.toUpperCase(), 40, 25, { align: 'center' });
    doc.setFontSize(8).setFont('helvetica', 'normal').text('Professional Grooming & Care', 40, 30, { align: 'center' });

    doc.setDrawColor(226, 232, 240); // Slate-200
    doc.setLineWidth(0.3).line(5, 35, 75, 35);

    // Details Section
    doc.setFontSize(7).setTextColor(100, 116, 139); // Slate-400
    doc.text(`Transaction ID: #${sale.id}`, 5, 42);
    doc.text(`Date & Time: ${dateStr}`, 5, 46);
    doc.text(`Professional: ${barber}`, 5, 50);
    doc.text(`Client: ${client}`, 5, 54);
    doc.line(5, 58, 75, 58);

    // Items Section
    let y = 65;
    doc.setFont('helvetica', 'bold').setFontSize(8).setTextColor(primaryColor[0], primaryColor[1], primaryColor[2]);
    doc.text('DESCRIPTION', 5, y);
    doc.text('QTY', 52, y);
    doc.text('AMOUNT', 75, y, { align: 'right' });
    doc.line(5, y + 2, 75, y + 2);

    doc.setFont('helvetica', 'normal').setFontSize(7);
    y += 7;
    sale.items.forEach(item => {
      doc.text(item.name.substring(0, 25), 5, y);
      doc.text(item.quantity.toString(), 54, y, { align: 'center' });
      doc.text(`${settings.currency}${(item.price * item.quantity).toFixed(2)}`, 75, y, { align: 'right' });
      y += 5;
    });

    // Summary Section
    y += 5;
    doc.setDrawColor(primaryColor[0], primaryColor[1], primaryColor[2]);
    doc.line(5, y, 75, y);
    y += 7;

    const subtotalValue = sale.items.reduce((acc, i) => acc + (i.price * i.quantity), 0);
    doc.setFont('helvetica', 'normal').text('SUBTOTAL:', 5, y);
    doc.text(`${settings.currency}${subtotalValue.toFixed(2)}`, 75, y, { align: 'right' });
    y += 5;

    if (sale.discount > 0) {
      doc.text(`DISCOUNT (${sale.discountCode || 'Applied'}):`, 5, y);
      doc.text(`-${settings.currency}${sale.discount.toFixed(2)}`, 75, y, { align: 'right' });
      y += 5;
    }

    if (sale.taxType === 'excluded') {
      doc.text(`TAX (${settings.taxRate}%):`, 5, y);
      doc.text(`${settings.currency}${sale.tax.toFixed(2)}`, 75, y, { align: 'right' });
      y += 5;
    } else {
      doc.setFontSize(6).setTextColor(148, 163, 184); // Slate-400
      doc.text(`Includes ${settings.taxRate}% tax of ${settings.currency}${sale.tax.toFixed(2)}`, 5, y);
      doc.setFontSize(7).setTextColor(primaryColor[0], primaryColor[1], primaryColor[2]);
      y += 5;
    }

    y += 2;
    doc.setFillColor(248, 250, 252); // Slate-50
    doc.rect(5, y - 4, 70, 8, 'F');
    doc.setFontSize(10).setFont('helvetica', 'bold').text('TOTAL PAID:', 7, y + 1.5);
    doc.text(`${settings.currency}${sale.total.toFixed(2)}`, 73, y + 1.5, { align: 'right' });

    y += 15;
    doc.setFontSize(7).setFont('helvetica', 'italic').setTextColor(148, 163, 184); // Slate-400
    doc.text(settings.receiptFooter, 40, y, { align: 'center' });
    doc.text('Thank you for your visit!', 40, y + 4, { align: 'center' });

    // Bottom Border
    doc.setFillColor(15, 23, 42);
    doc.rect(0, 195, 80, 5, 'F');

    return doc;
  };

  const handleShareReceipt = async (sale: Sale) => {
    const doc = generatePDF(sale);
    const pdfBlob = doc.output('blob');
    const file = new File([pdfBlob], `Receipt-${sale.id}.pdf`, { type: 'application/pdf' });

    if (navigator.share && navigator.canShare && navigator.canShare({ files: [file] })) {
      try {
        await navigator.share({
          files: [file],
          title: `${settings.shopName} Receipt`,
          text: `Your receipt for transaction #${sale.id}`,
        });
      } catch (error: any) {
        // Silently handle AbortError (user cancelled)
        if (error.name !== 'AbortError' && !error.message.includes('cancellation')) {
          console.error('Error sharing receipt:', error);
          doc.save(`Receipt-${sale.id}.pdf`);
        }
      }
    } else {
      doc.save(`Receipt-${sale.id}.pdf`);
    }
  };

  const handleCheckout = (paymentMethod: 'cash' | 'card') => {
    if (cart.length === 0 || !selectedStaff) {
      alert('Please add items and assign a professional.');
      return;
    }

    const sale: Sale = {
      id: Math.random().toString(36).substr(2, 9).toUpperCase(),
      timestamp: new Date().toISOString(),
      items: [...cart],
      staffId: selectedStaff,
      customerId: selectedCustomer || undefined,
      total: totals.total,
      tax: totals.tax,
      discount: totals.discount,
      discountCode: discountCode || undefined,
      paymentMethod,
      taxType: settings.taxType,
    };

    onCompleteSale(sale);
    setLastSale(sale);
    setCart([]);
    setSelectedCustomer('');
    setDiscountCode('');
    setShowMobileCart(false);
  };

  const filteredItems = useMemo(() => {
    const search = searchTerm.toLowerCase();
    if (activeTab === 'services') {
      return services.filter(s => 
        s.name.toLowerCase().includes(search) || 
        s.category.toLowerCase().includes(search)
      );
    }
    return products.filter(p => p.name.toLowerCase().includes(search));
  }, [activeTab, services, products, searchTerm]);

  return (
    <div className="flex flex-col lg:flex-row gap-6 h-[calc(100vh-12rem)] relative">

      {/* Success Modal */}
      <AnimatePresence>
        {lastSale && (
          <motion.div 
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="fixed inset-0 bg-slate-950/80 backdrop-blur-xl z-[150] flex items-center justify-center p-6 no-print"
          >
            <motion.div 
              initial={{ scale: 0.8, opacity: 0, y: 20 }}
              animate={{ scale: 1, opacity: 1, y: 0 }}
              className="bg-white rounded-[3rem] p-10 max-w-md w-full shadow-2xl text-center space-y-8"
            >
              <div className="w-20 h-20 bg-emerald-50 text-emerald-500 rounded-full flex items-center justify-center text-4xl mx-auto shadow-inner">✓</div>
              <div className="space-y-2">
                <h3 className="text-3xl font-black text-slate-900 tracking-tight">Sale Success</h3>
                <p className="text-slate-400 font-medium">Order #{lastSale.id} completed.</p>
              </div>
              <div className="flex flex-col gap-3">
                <button 
                  onClick={() => handleShareReceipt(lastSale)} 
                  className="w-full bg-slate-950 text-white py-4 rounded-2xl font-black flex items-center justify-center gap-3 hover:bg-slate-800 transition-all shadow-xl active:scale-95"
                >
                  <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M8.684 13.342C8.886 12.938 9 12.482 9 12c0-.482-.114-.938-.316-1.342m0 2.684a3 3 0 110-2.684m0 2.684l6.632 3.316m-6.632-6l6.632-3.316m0 0a3 3 0 105.367-2.684 3 3 0 00-5.367 2.684zm0 9.316a3 3 0 105.368 2.684 3 3 0 00-5.368-2.684z"/></svg>
                  Share Receipt
                </button>
                <button 
                  onClick={() => generatePDF(lastSale).save(`Receipt-${lastSale.id}.pdf`)} 
                  className="w-full bg-slate-100 text-slate-600 py-4 rounded-2xl font-black flex items-center justify-center gap-3 hover:bg-slate-200 transition-all active:scale-95"
                >
                  <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4"/></svg>
                  Download PDF
                </button>
                <button onClick={() => setLastSale(null)} className="w-full py-4 text-slate-400 font-bold hover:text-slate-600">Start New Bill</button>
              </div>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* Catalog */}
      <div className="flex-1 flex flex-col min-h-0">
        <div className="mb-6 flex flex-col sm:flex-row gap-4">
          <div className="flex-1 relative">
            <svg className="w-5 h-5 absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z"/></svg>
            <input 
              type="text" 
              placeholder="Search catalog..." 
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="w-full bg-white border border-slate-200 rounded-2xl py-3 pl-12 pr-6 outline-none focus:ring-4 focus:ring-amber-500/10 shadow-sm text-sm font-medium"
            />
          </div>
          <div className="flex bg-white p-1 rounded-2xl border border-slate-100 shadow-sm">
            <button 
              onClick={() => setActiveTab('services')}
              className={`px-6 py-2 rounded-xl text-xs font-black uppercase tracking-widest transition-all ${activeTab === 'services' ? 'bg-amber-500 text-slate-900 shadow-md' : 'text-slate-400 hover:text-slate-600'}`}
            >
              Services
            </button>
            <button 
              onClick={() => setActiveTab('products')}
              className={`px-6 py-2 rounded-xl text-xs font-black uppercase tracking-widest transition-all ${activeTab === 'products' ? 'bg-amber-500 text-slate-900 shadow-md' : 'text-slate-400 hover:text-slate-600'}`}
            >
              Products
            </button>
          </div>
        </div>

        <div className="flex-1 overflow-y-auto grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-3 gap-4 pr-2 scrollbar-hide">
          <AnimatePresence mode='popLayout'>
            {filteredItems.map(item => (
              <motion.button
                layout
                key={item.id}
                whileHover={{ scale: 1.02 }}
                whileTap={{ scale: 0.98 }}
                onClick={() => addToCart(item, activeTab === 'services' ? 'service' : 'product')}
                className="bg-white p-5 rounded-[2rem] border border-slate-100 shadow-sm hover:shadow-md transition-all text-left flex flex-col justify-between group h-40 relative overflow-hidden"
              >
                <div className="relative z-10">
                  <span className={`text-[9px] font-black uppercase tracking-widest px-2 py-1 rounded-lg mb-2 inline-block ${activeTab === 'services' ? 'bg-amber-50 text-amber-600' : 'bg-indigo-50 text-indigo-600'}`}>
                    {activeTab === 'services' ? (item as Service).category : 'Retail'}
                  </span>
                  <h4 className="font-bold text-slate-800 text-sm leading-tight group-hover:text-amber-600 transition-colors">{item.name}</h4>
                </div>
                <div className="flex items-center justify-between relative z-10">
                  <p className="text-lg font-black text-slate-900">{settings.currency}{item.price}</p>
                  <div className="w-8 h-8 bg-slate-900 text-white rounded-full flex items-center justify-center opacity-0 group-hover:opacity-100 transition-all">
                    <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M12 6v6m0 0v6m0-6h6m-6 0H6"/></svg>
                  </div>
                </div>
              </motion.button>
            ))}
          </AnimatePresence>
        </div>
      </div>

      {/* Cart Panel */}
      <div className={`lg:w-96 flex flex-col bg-white rounded-[2.5rem] border border-slate-100 shadow-xl overflow-hidden ${showMobileCart ? 'fixed inset-0 z-[70]' : 'relative hidden lg:flex'}`}>
        <div className="p-6 border-b border-slate-50 bg-slate-50/50 flex justify-between items-center">
          <h3 className="text-xl font-black text-slate-800 flex items-center gap-2">Cart</h3>
          <button onClick={() => setShowMobileCart(false)} className="lg:hidden p-2 text-slate-400">✕</button>
        </div>

        <div className="p-6 space-y-4">
          <select value={selectedStaff} onChange={(e) => setSelectedStaff(e.target.value)} className="w-full bg-slate-50 border-0 rounded-xl px-4 py-3 text-sm font-bold outline-none focus:ring-2 focus:ring-amber-400">
            <option value="">Choose Professional...</option>
            {staff.map(s => <option key={s.id} value={s.id}>{s.name}</option>)}
          </select>
          <select value={selectedCustomer} onChange={(e) => setSelectedCustomer(e.target.value)} className="w-full bg-slate-50 border-0 rounded-xl px-4 py-3 text-sm font-bold outline-none focus:ring-2 focus:ring-amber-400">
            <option value="">Walk-in Client</option>
            {customers.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
          </select>
        </div>

        <div className="flex-1 overflow-y-auto px-6 py-2 space-y-3 scrollbar-hide">
          {cart.map(item => (
            <div key={`${item.id}-${item.type}`} className="flex items-center justify-between group">
              <div className="flex-1">
                <p className="text-sm font-bold text-slate-800">{item.name}</p>
                <p className="text-[10px] text-slate-400 font-bold">{settings.currency}{item.price} x {item.quantity}</p>
              </div>
              <div className="flex items-center gap-2">
                <button onClick={() => updateQuantity(item.id, item.type, -1)} className="w-6 h-6 bg-slate-100 rounded flex items-center justify-center">-</button>
                <button onClick={() => updateQuantity(item.id, item.type, 1)} className="w-6 h-6 bg-slate-100 rounded flex items-center justify-center">+</button>
                <button onClick={() => removeFromCart(item.id, item.type)} className="text-rose-400 p-1">✕</button>
              </div>
            </div>
          ))}
        </div>

        <div className="p-6 bg-slate-50 border-t border-slate-100 space-y-3">
          <div className="flex justify-between text-xs font-bold text-slate-500 uppercase">
            <span>Subtotal</span>
            <span>{settings.currency}{totals.subtotal.toFixed(2)}</span>
          </div>
          {totals.discount > 0 && (
            <div className="flex justify-between text-xs font-bold text-emerald-600 uppercase">
              <span>Discount</span>
              <span>-{settings.currency}{totals.discount.toFixed(2)}</span>
            </div>
          )}
          <div className="flex justify-between text-xs font-bold text-slate-500 uppercase">
            <span>Tax ({settings.taxType})</span>
            <span>{settings.currency}{totals.tax.toFixed(2)}</span>
          </div>
          <div className="flex justify-between items-center pt-2">
            <span className="text-xl font-black text-slate-900">Total</span>
            <span className="text-3xl font-black text-amber-600">{settings.currency}{totals.total.toFixed(2)}</span>
          </div>
          <div className="grid grid-cols-2 gap-3 pt-4">
            <button onClick={() => handleCheckout('cash')} className="bg-slate-900 text-white py-4 rounded-2xl font-black active:scale-95">Cash</button>
            <button onClick={() => handleCheckout('card')} className="bg-amber-500 text-slate-900 py-4 rounded-2xl font-black active:scale-95">Card</button>
          </div>
          <button onClick={handleHoldSale} className="w-full text-[10px] font-black uppercase text-slate-400 py-2">Hold Bill</button>
        </div>
      </div>

      {/* Held Sales List */}
      <AnimatePresence>
        {heldSales.length > 0 && (
          <div className="fixed bottom-6 right-6 lg:right-96 lg:mr-8 z-40 max-w-xs w-full">
            <div className="bg-slate-900 text-white p-4 rounded-2xl shadow-2xl space-y-2">
              <p className="text-[10px] font-black uppercase text-slate-500">Held Bills ({heldSales.length})</p>
              {heldSales.map(h => (
                <div key={h.id} className="flex justify-between items-center bg-white/5 p-2 rounded-xl">
                  <span className="text-xs font-bold">#{h.id.slice(-4)}</span>
                  <button onClick={() => retrieveSale(h)} className="text-[10px] font-black text-amber-400 bg-amber-400/10 px-3 py-1 rounded-lg">Resume</button>
                </div>
              ))}
            </div>
          </div>
        )}
      </AnimatePresence>

      <button onClick={() => setShowMobileCart(true)} className="lg:hidden fixed bottom-6 left-1/2 -translate-x-1/2 bg-slate-900 text-white px-8 py-4 rounded-full font-black shadow-2xl z-50 active:scale-95 flex gap-2">
        Cart ({cart.length})
      </button>

      {scanningFeedback && (
        <div className="fixed top-24 left-1/2 -translate-x-1/2 bg-emerald-500 text-white px-6 py-3 rounded-full font-black text-sm shadow-2xl z-[100] animate-bounce">
          Added: {scanningFeedback}
        </div>
      )}
    </div>
  );
};

export default POS;

import React, { useState, useEffect } from 'react';
import Sidebar from './components/Sidebar';
import Dashboard from './components/Dashboard';
import POS from './components/POS';
import Finance from './components/Finance';
import Customers from './components/Customers';
import Settings from './components/Settings';
import Inventory from './components/Inventory';
import StaffManagement from './components/StaffManagement';
import Login from './components/Login';
import { View, Sale, Expense, Service, Product, Staff, Customer, ShopSettings } from './types';
import { INITIAL_SERVICES, INITIAL_PRODUCTS, INITIAL_STAFF, INITIAL_EXPENSES, INITIAL_CUSTOMERS, DEFAULT_SETTINGS } from './constants';
import { motion, AnimatePresence } from 'framer-motion';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<Staff | null>(() => {
    const saved = localStorage.getItem('trimtime_session');
    return saved ? JSON.parse(saved) : null;
  });

  const [isDarkMode, setIsDarkMode] = useState<boolean>(() => {
    const saved = localStorage.getItem('trimtime_darkmode');
    return saved === 'true';
  });

  const [currentView, setCurrentView] = useState<View>(View.DASHBOARD);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [sales, setSales] = useState<Sale[]>([]);
  const [expenses, setExpenses] = useState<Expense[]>(INITIAL_EXPENSES);
  const [customers, setCustomers] = useState<Customer[]>(INITIAL_CUSTOMERS);
  const [services, setServices] = useState<Service[]>(INITIAL_SERVICES);
  const [products, setProducts] = useState<Product[]>(INITIAL_PRODUCTS);
  const [staffList, setStaffList] = useState<Staff[]>(INITIAL_STAFF);
  const [settings, setSettings] = useState<ShopSettings>(DEFAULT_SETTINGS);

  // Persistence of dark mode
  useEffect(() => {
    if (isDarkMode) {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
    localStorage.setItem('trimtime_darkmode', String(isDarkMode));
  }, [isDarkMode]);

  useEffect(() => {
    if (currentUser) {
      localStorage.setItem('trimtime_session', JSON.stringify(currentUser));
    } else {
      localStorage.removeItem('trimtime_session');
    }
  }, [currentUser]);

  // Close sidebar on view change on mobile
  useEffect(() => {
    setIsSidebarOpen(false);
  }, [currentView]);

  const handleLogin = (user: Staff) => {
    setCurrentUser(user);
    // Employees go straight to POS for faster billing, admins stay on Dashboard
    if (user.role === 'employee') {
      setCurrentView(View.POS);
    } else {
      setCurrentView(View.DASHBOARD);
    }
  };

  const handleLogout = () => {
    setCurrentUser(null);
  };

  const handleCompleteSale = (sale: Sale) => {
    setSales(prev => [...prev, sale]);
    setProducts(prevProducts => prevProducts.map(p => {
        const cartItem = sale.items.find(item => item.id === p.id && item.type === 'product');
        if (cartItem) {
            return { ...p, stock: Math.max(0, p.stock - cartItem.quantity) };
        }
        return p;
    }));
  };

  const toggleDarkMode = () => setIsDarkMode(!isDarkMode);

  const renderView = () => {
    if (!currentUser) return null;

    if (currentUser.role !== 'admin' && [View.FINANCE, View.SETTINGS, View.INVENTORY, View.STAFF].includes(currentView)) {
        setCurrentView(View.DASHBOARD);
        return null;
    }

    switch (currentView) {
      case View.DASHBOARD:
        return <Dashboard sales={sales} expenses={expenses} currency={settings.currency} />;
      case View.POS:
        return (
          <POS 
            services={services} 
            products={products} 
            staff={staffList} 
            customers={customers}
            settings={settings}
            onCompleteSale={handleCompleteSale} 
            onAddCustomer={(c) => setCustomers([...customers, c])}
          />
        );
      case View.FINANCE:
        return (
          <Finance 
            sales={sales} 
            expenses={expenses} 
            staffList={staffList}
            onAddExpense={(e) => setExpenses([...expenses, e])} 
            currency={settings.currency}
          />
        );
      case View.CUSTOMERS:
        return (
          <Customers 
            customers={customers}
            sales={sales}
            onAddCustomer={(c) => setCustomers([...customers, c])}
            currency={settings.currency}
          />
        );
      case View.INVENTORY:
        return (
          <Inventory 
            services={services}
            products={products}
            settings={settings}
            onUpdateServices={setServices}
            onUpdateProducts={setProducts}
          />
        );
      case View.STAFF:
        return (
          <StaffManagement 
            staffList={staffList}
            onUpdateStaff={setStaffList}
            currentUser={currentUser}
          />
        );
      case View.SETTINGS:
        return (
          <Settings 
            settings={settings}
            onUpdateSettings={setSettings}
          />
        );
      default:
        return null;
    }
  };

  if (!currentUser) {
    return <Login onLogin={handleLogin} staffList={staffList} />;
  }

  return (
    <div className="min-h-screen flex bg-slate-50 dark:bg-slate-950 transition-colors duration-300 relative">
      <Sidebar 
        currentView={currentView} 
        onViewChange={setCurrentView} 
        shopName={settings.shopName}
        userRole={currentUser.role}
        isOpen={isSidebarOpen}
        onClose={() => setIsSidebarOpen(false)}
      />

      <main className={`flex-1 transition-all duration-300 ${isSidebarOpen ? 'blur-sm md:blur-0' : ''} md:ml-64 p-4 md:p-8 overflow-x-hidden`}>
        <header className="mb-6 md:mb-8 flex justify-between items-center no-print">
            <div className="flex items-center gap-4">
                <button 
                  onClick={() => setIsSidebarOpen(true)}
                  className="p-2 md:hidden bg-white dark:bg-slate-900 border border-slate-100 dark:border-slate-800 rounded-xl text-slate-500 dark:text-slate-400"
                >
                  <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 6h16M4 12h16M4 18h16"/></svg>
