            <span>Subtotal</span>
            <span>{settings.currency}{totals.subtotal.toFixed(2)}</span>
          </div>
          {totals.discount > 0 && (
            <div className="flex justify-between text-xs font-bold text-emerald-600 dark:text-emerald-400 uppercase">
              <span>Discount</span>
              <span>-{settings.currency}{totals.discount.toFixed(2)}</span>
            </div>
          )}
          <div className="flex justify-between text-xs font-bold text-slate-500 dark:text-slate-400 uppercase">
            <span>Tax ({settings.taxType})</span>
            <span>{settings.currency}{totals.tax.toFixed(2)}</span>
          </div>
          <div className="flex justify-between items-center pt-2">
            <span className="text-xl font-black text-slate-900 dark:text-white">Total</span>
            <span className="text-3xl font-black text-amber-600 dark:text-amber-500">{settings.currency}{totals.total.toFixed(2)}</span>
          </div>
          <div className="grid grid-cols-2 gap-3 pt-4">
            <button onClick={() => handleCheckout('cash')} className="bg-slate-900 dark:bg-slate-950 text-white py-4 rounded-2xl font-black active:scale-95 shadow-lg">Cash</button>
            <button onClick={() => handleCheckout('card')} className="bg-amber-500 text-slate-900 py-4 rounded-2xl font-black active:scale-95 shadow-lg shadow-amber-500/10">Card</button>
          </div>
          <button onClick={handleHoldSale} className="w-full text-[10px] font-black uppercase text-slate-400 dark:text-slate-600 py-2 hover:text-slate-600 dark:hover:text-slate-400">Hold Bill</button>
        </div>
      </div>

      {/* Held Sales List */}
      <AnimatePresence>
        {heldSales.length > 0 && (
          <div className="fixed bottom-6 right-6 lg:right-96 lg:mr-8 z-40 max-w-xs w-full">
            <div className="bg-slate-900 dark:bg-slate-950 text-white p-4 rounded-2xl shadow-2xl space-y-2 border border-white/5">
              <p className="text-[10px] font-black uppercase text-slate-500">Held Bills ({heldSales.length})</p>
              {heldSales.map(h => (
                <div key={h.id} className="flex justify-between items-center bg-white/5 p-2 rounded-xl">
                  <span className="text-xs font-bold">#{h.id.slice(-4)}</span>
                  <button onClick={() => retrieveSale(h)} className="text-[10px] font-black text-amber-400 bg-amber-400/10 px-3 py-1 rounded-lg">Resume</button>
                </div>
              ))}
            </div>
          </div>
        )}
      </AnimatePresence>

      <button onClick={() => setShowMobileCart(true)} className="lg:hidden fixed bottom-6 left-1/2 -translate-x-1/2 bg-slate-900 dark:bg-slate-800 text-white px-8 py-4 rounded-full font-black shadow-2xl z-50 active:scale-95 flex gap-2 border border-white/10">
        Cart ({cart.length})
      </button>

      {scanningFeedback && (
        <div className="fixed top-24 left-1/2 -translate-x-1/2 bg-emerald-500 text-white px-6 py-3 rounded-full font-black text-sm shadow-2xl z-[100] animate-bounce">
          Added: {scanningFeedback}
        </div>
      )}
    </div>
  );
};

