      // Roughly calculate commission (assuming percentage applies to total revenue for simplicity)
      const commissionEarned = (revenueGenerated * staff.commission) / 100;

      return {
        ...staff,
        salesCount: personalSales.length,
        revenue: revenueGenerated,
        commissionEarned
      };
    }).sort((a, b) => b.revenue - a.revenue);
  }, [sales, staffList]);

