                  setFormData(settings);
                  setIsCustomCurrency(!CURRENCY_OPTIONS.some(opt => opt.symbol === settings.currency));
                }}
                className="px-8 py-4 font-black text-slate-400 dark:text-slate-600 hover:text-slate-600 dark:hover:text-slate-400 transition-colors uppercase text-xs tracking-widest"
            >
                Reset Changes
            </button>
            <button 
                type="submit" 
                className="bg-slate-950 dark:bg-amber-500 text-white dark:text-slate-950 px-10 py-4 rounded-2xl font-black text-base hover:bg-slate-800 dark:hover:bg-amber-600 transition-all shadow-xl active:scale-95"
            >
                Save All Settings
            </button>
        </div>
      </form>
    </div>
  );
};

export default Settings;

import React, { useState } from 'react';
import { Staff, UserRole } from '../types';
import { motion, AnimatePresence } from 'framer-motion';

interface StaffManagementProps {
  staffList: Staff[];
  onUpdateStaff: (staff: Staff[]) => void;
  currentUser: Staff;
}

const StaffManagement: React.FC<StaffManagementProps> = ({ staffList, onUpdateStaff, currentUser }) => {
  const [isAdding, setIsAdding] = useState(false);
  const [editingStaff, setEditingStaff] = useState<Staff | null>(null);
  const [showPassword, setShowPassword] = useState(false);
  const [formData, setFormData] = useState({
    name: '',
    username: '',
    password: '',
    role: 'employee' as UserRole,
    commission: 30
  });

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (editingStaff) {
      const updatedList = staffList.map(s => s.id === editingStaff.id ? { ...editingStaff, ...formData } : s);
      onUpdateStaff(updatedList);
    } else {
      const newStaff: Staff = {
        id: Math.random().toString(36).substr(2, 9).toUpperCase(),
        ...formData
      };
      onUpdateStaff([...staffList, newStaff]);
    }
    resetForm();
  };

  const resetForm = () => {
    setIsAdding(false);
    setEditingStaff(null);
    setShowPassword(false);
    setFormData({ name: '', username: '', password: '', role: 'employee', commission: 30 });
  };

  const deleteStaff = (id: string) => {
    if (id === currentUser.id) {
      alert("You cannot delete your own admin account.");
      return;
    }
    if (confirm('Permanently remove this team member?')) {
      onUpdateStaff(staffList.filter(s => s.id !== id));
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
        <div>
          <h2 className="text-2xl md:text-3xl font-bold text-slate-800 dark:text-white font-brand">Team Hub</h2>
          <p className="text-slate-500 dark:text-slate-400 text-sm">Manage access and earnings.</p>
        </div>
        <button 
          onClick={() => setIsAdding(true)}
          className="bg-slate-950 dark:bg-slate-800 text-white px-6 py-3 rounded-xl font-black flex items-center gap-2 hover:bg-slate-800 transition-all shadow-lg text-sm w-full sm:w-auto justify-center"
        >
          <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M18 9v3m0 0v3m0-3h3m-3 0h-3m-2-5a4 4 0 11-8 0 4 4 0 018 0zM3 20a6 6 0 0112 0v1H3v-1z"/></svg>
          Add Staff
        </button>
      </div>

      <div className="bg-white dark:bg-slate-900 rounded-[2rem] border border-slate-100 dark:border-slate-800 shadow-sm overflow-hidden">
        <div className="overflow-x-auto scrollbar-hide">
          <table className="w-full text-left min-w-[650px]">
            <thead>
