import React, { useState, useEffect } from 'react';
import Sidebar from './components/Sidebar';
import Dashboard from './components/Dashboard';
import POS from './components/POS';
import Finance from './components/Finance';
import Customers from './components/Customers';
import Settings from './components/Settings';
import Inventory from './components/Inventory';
import StaffManagement from './components/StaffManagement';
import Login from './components/Login';
import { View, Sale, Expense, Service, Product, Staff, Customer, ShopSettings } from './types';
import { INITIAL_SERVICES, INITIAL_PRODUCTS, INITIAL_STAFF, INITIAL_EXPENSES, INITIAL_CUSTOMERS, DEFAULT_SETTINGS } from './constants';
import { motion, AnimatePresence } from 'framer-motion';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<Staff | null>(() => {
    const saved = localStorage.getItem('trimtime_session');
    return saved ? JSON.parse(saved) : null;
  });

  const [isDarkMode, setIsDarkMode] = useState<boolean>(() => {
    const saved = localStorage.getItem('trimtime_darkmode');
    return saved === 'true';
  });

  const [currentView, setCurrentView] = useState<View>(View.DASHBOARD);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isProfileOpen, setIsProfileOpen] = useState(false);
  const [sales, setSales] = useState<Sale[]>([]);
  const [expenses, setExpenses] = useState<Expense[]>(INITIAL_EXPENSES);
  const [customers, setCustomers] = useState<Customer[]>(INITIAL_CUSTOMERS);
  const [services, setServices] = useState<Service[]>(INITIAL_SERVICES);
  const [products, setProducts] = useState<Product[]>(INITIAL_PRODUCTS);
  const [staffList, setStaffList] = useState<Staff[]>(INITIAL_STAFF);
  const [settings, setSettings] = useState<ShopSettings>(DEFAULT_SETTINGS);

  // Persistence of dark mode
  useEffect(() => {
    if (isDarkMode) {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
    localStorage.setItem('trimtime_darkmode', String(isDarkMode));
  }, [isDarkMode]);

  useEffect(() => {
    if (currentUser) {
      localStorage.setItem('trimtime_session', JSON.stringify(currentUser));
    } else {
      localStorage.removeItem('trimtime_session');
    }
  }, [currentUser]);

  // Close sidebar on view change on mobile
  useEffect(() => {
    setIsSidebarOpen(false);
  }, [currentView]);

  const handleLogin = (user: Staff) => {
    setCurrentUser(user);
    // Employees go straight to POS for faster billing, admins stay on Dashboard
    if (user.role === 'employee') {
      setCurrentView(View.POS);
    } else {
      setCurrentView(View.DASHBOARD);
    }
  };

  const handleLogout = () => {
    setCurrentUser(null);
    setIsProfileOpen(false);
  };

  const handleCompleteSale = (sale: Sale) => {
    setSales(prev => [...prev, sale]);
    setProducts(prevProducts => prevProducts.map(p => {
        const cartItem = sale.items.find(item => item.id === p.id && item.type === 'product');
        if (cartItem) {
            return { ...p, stock: Math.max(0, p.stock - cartItem.quantity) };
        }
        return p;
    }));
  };

  const toggleDarkMode = () => setIsDarkMode(!isDarkMode);

  const renderView = () => {
    if (!currentUser) return null;

    if (currentUser.role !== 'admin' && [View.FINANCE, View.SETTINGS, View.INVENTORY, View.STAFF].includes(currentView)) {
        setCurrentView(View.DASHBOARD);
        return null;
    }

    switch (currentView) {
      case View.DASHBOARD:
        return <Dashboard sales={sales} expenses={expenses} currency={settings.currency} />;
      case View.POS:
        return (
          <POS 
            services={services} 
            products={products} 
            staff={staffList} 
            customers={customers}
            settings={settings}
            onCompleteSale={handleCompleteSale} 
            onAddCustomer={(c) => setCustomers([...customers, c])}
          />
        );
      case View.FINANCE:
        return (
          <Finance 
            sales={sales} 
            expenses={expenses} 
            staffList={staffList}
            onAddExpense={(e) => setExpenses([...expenses, e])} 
            currency={settings.currency}
          />
        );
      case View.CUSTOMERS:
        return (
          <Customers 
            customers={customers}
            sales={sales}
            onAddCustomer={(c) => setCustomers([...customers, c])}
            currency={settings.currency}
          />
        );
      case View.INVENTORY:
        return (
          <Inventory 
            services={services}
            products={products}
            settings={settings}
            onUpdateServices={setServices}
            onUpdateProducts={setProducts}
          />
        );
      case View.STAFF:
        return (
          <StaffManagement 
            staffList={staffList}
            onUpdateStaff={setStaffList}
            currentUser={currentUser}
          />
        );
      case View.SETTINGS:
        return (
          <Settings 
            settings={settings}
            onUpdateSettings={setSettings}
          />
        );
      default:
        return null;
    }
  };

  if (!currentUser) {
    return <Login onLogin={handleLogin} staffList={staffList} />;
  }

  return (
    <div className="min-h-screen flex bg-slate-50 dark:bg-slate-950 transition-colors duration-300 relative">
      <Sidebar 
        currentView={currentView} 
        onViewChange={setCurrentView} 
        shopName={settings.shopName}
        userRole={currentUser.role}
        isOpen={isSidebarOpen}
        onClose={() => setIsSidebarOpen(false)}
      />

      <main className={`flex-1 transition-all duration-300 ${isSidebarOpen ? 'blur-sm md:blur-0' : ''} md:ml-64 p-4 md:p-8 overflow-x-hidden`}>
        <header className="mb-6 md:mb-8 flex justify-between items-center no-print">
            <div className="flex items-center gap-4">
                <button 
                  onClick={() => setIsSidebarOpen(true)}
                  className="p-2 md:hidden bg-white dark:bg-slate-900 border border-slate-100 dark:border-slate-800 rounded-xl text-slate-500 dark:text-slate-400"
                >
                  <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 6h16M4 12h16M4 18h16"/></svg>
                </button>
                <div className="bg-white dark:bg-slate-900 px-3 md:px-4 py-2 rounded-xl shadow-sm border border-slate-100 dark:border-slate-800 flex items-center gap-2">
                    <span className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse"></span>
                    <span className="text-[10px] md:text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-widest truncate max-w-[100px] md:max-w-none">
                      {settings.shopName} Terminal
                    </span>
                </div>
            </div>

            <div className="flex items-center gap-2 md:gap-4">
                <button 
                  onClick={toggleDarkMode}
                  className="p-2.5 rounded-xl bg-white dark:bg-slate-900 border border-slate-100 dark:border-slate-800 text-slate-500 dark:text-amber-400 hover:scale-105 active:scale-95 transition-all shadow-sm"
                  title="Toggle Dark Mode"
                >
                  {isDarkMode ? (
                    <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 3v1m0 16v1m9-9h-1M4 12H3m15.364-6.364l-.707.707M6.343 17.657l-.707.707M16.95 16.95l.707.707M7.05 7.05l.707-.707M12 8a4 4 0 100 8 4 4 0 000-8z"/></svg>
                  ) : (
                    <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M20.354 15.354A9 9 0 018.646 3.646 9.003 9.003 0 0012 21a9.003 9.003 0 008.354-5.646z"/></svg>
                  )}
                </button>

                <div className="text-right mr-1 md:mr-2 hidden sm:block">
                    <p className="text-[10px] md:text-xs font-black text-slate-800 dark:text-slate-200 uppercase tracking-tight">{currentUser.name}</p>
                    <p className="text-[8px] md:text-[10px] font-bold text-slate-400 dark:text-slate-500 uppercase tracking-widest">{currentUser.role}</p>
                </div>
                <button 
                  onClick={() => setIsProfileOpen(true)}
                  className="w-8 h-8 md:w-10 md:h-10 rounded-full bg-slate-200 dark:bg-slate-800 border-2 border-white dark:border-slate-800 shadow-sm overflow-hidden flex-shrink-0 cursor-pointer hover:scale-105 active:scale-95 transition-transform"
                >
                    <img src={`https://api.dicebear.com/7.x/avataaars/svg?seed=${currentUser.name}`} alt="Profile" />
                </button>
                <button 
                  onClick={handleLogout}
                  className="p-1.5 md:p-2 text-slate-400 hover:text-rose-500 transition-colors"
                  title="Logout"
                >
                  <svg className="w-5 h-5 md:w-6 md:h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M17 16l4-4m0 0l-4-4m4 4H7m6 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h4a3 3 0 013 3v1"/></svg>
                </button>
            </div>
        </header>

        {renderView()}
      </main>

      {/* Mobile Sidebar Overlay */}
      <AnimatePresence>
        {isSidebarOpen && (
          <motion.div 
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            onClick={() => setIsSidebarOpen(false)}
            className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[55] md:hidden"
          />
        )}
      </AnimatePresence>

      {/* Profile Modal */}
      <AnimatePresence>
        {isProfileOpen && (
          <motion.div 
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            onClick={() => setIsProfileOpen(false)}
            className="fixed inset-0 bg-slate-950/60 backdrop-blur-sm z-[100] flex items-center justify-center p-4"
          >
            <motion.div 
              initial={{ scale: 0.9, opacity: 0, y: 20 }}
              animate={{ scale: 1, opacity: 1, y: 0 }}
              exit={{ scale: 0.9, opacity: 0, y: 20 }}
              onClick={(e) => e.stopPropagation()}
              className="bg-white dark:bg-slate-900 w-full max-w-sm rounded-[2.5rem] p-8 shadow-2xl border border-slate-100 dark:border-slate-800 relative overflow-hidden"
            >
              {/* Background Decoration */}
              <div className="absolute top-0 left-0 w-full h-32 bg-gradient-to-br from-amber-400/20 to-amber-600/20 dark:from-amber-400/10 dark:to-amber-600/10"></div>

              <div className="relative z-10 flex flex-col items-center text-center">
                <div className="w-24 h-24 rounded-full bg-white dark:bg-slate-800 p-1.5 shadow-xl mb-4">
