                  <textarea 
                    value={newCust.notes}
                    onChange={e => setNewCust({...newCust, notes: e.target.value})}
                    placeholder=""
                    className="w-full bg-slate-50 dark:bg-slate-800 border-0 rounded-2xl px-5 py-4 focus:ring-4 focus:ring-amber-500/10 outline-none h-28 resize-none text-sm font-medium dark:text-slate-300"
                  />
                </div>
                <div className="flex gap-4 mt-6">
                  <button 
                    onClick={() => {
                      if(!newCust.name) return;
                      onAddCustomer({
                        id: 'c' + (customers.length + 1) + Math.random().toString(36).substr(2, 4),
                        name: newCust.name,
                        phone: newCust.phone,
                        email: newCust.email,
                        notes: newCust.notes,
                        createdAt: new Date().toISOString().split('T')[0]
