                  <td className="px-8 py-6 font-black text-slate-900 dark:text-white">{staff.commission}%</td>
                  <td className="px-8 py-6 text-right space-x-2">
                    <button 
                      onClick={() => {
                        setEditingStaff(staff);
                        setFormData({ 
                          name: staff.name, 
                          username: staff.username, 
                          password: staff.password || '', 
                          email: staff.email || '',
                          role: staff.role, 
                          commission: staff.commission 
                        });
                        setIsAdding(true);
                      }}
                      className="p-2 text-slate-300 dark:text-slate-600 hover:text-amber-500 transition-colors"
                    >
                      <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z"/></svg>
                    </button>
                    <button onClick={() => deleteStaff(staff.id)} className="p-2 text-slate-300 dark:text-slate-600 hover:text-rose-500 transition-colors">
                      <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"/></svg>
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      <AnimatePresence>
        {isAdding && (
          <div className="fixed inset-0 bg-slate-950/40 backdrop-blur-sm z-[100] flex items-end sm:items-center justify-center p-0 sm:p-4">
            <motion.div 
              initial={{ y: "100%" }}
              animate={{ y: 0 }}
              exit={{ y: "100%" }}
              className="bg-white dark:bg-slate-900 rounded-t-[2.5rem] sm:rounded-[2.5rem] w-full max-w-md p-8 md:p-10 shadow-2xl overflow-y-auto max-h-[90vh]"
            >
              <div className="flex justify-between items-center mb-8">
                <h3 className="text-2xl font-black text-slate-900 dark:text-white tracking-tight">{editingStaff ? t.editProfessional : t.addToTeam}</h3>
                <button onClick={resetForm} className="p-2 bg-slate-50 dark:bg-slate-800 rounded-full text-slate-400">
                  <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M6 18L18 6M6 6l12 12"/></svg>
                </button>
              </div>
              <form onSubmit={handleSubmit} className="space-y-5">
                <div>
                  <label className="text-[10px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest block mb-2 ml-1">{t.fullName}</label>
                  <input 
                    name="name" 
                    type="text" 
                    value={formData.name} 
                    onChange={e => setFormData({...formData, name: e.target.value})} 
                    required 
                    className="w-full bg-slate-50 dark:bg-slate-800 border-0 rounded-2xl px-5 py-3.5 focus:ring-4 focus:ring-amber-500/10 outline-none text-sm font-bold dark:text-slate-200" 
                  />
                </div>
                <div>
                  <label className="text-[10px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest block mb-2 ml-1">{t.email} ({t.optional})</label>
                  <input 
                    name="email" 
                    type="email" 
                    value={formData.email} 
                    onChange={e => setFormData({...formData, email: e.target.value})} 
                    className="w-full bg-slate-50 dark:bg-slate-800 border-0 rounded-2xl px-5 py-3.5 focus:ring-4 focus:ring-amber-500/10 outline-none text-sm font-bold dark:text-slate-200" 
                  />
                </div>
                <div>
                  <label className="text-[10px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest block mb-2 ml-1">{t.username}</label>
                  <input 
                    name="username" 
                    type="text" 
                    value={formData.username} 
                    onChange={e => setFormData({...formData, username: e.target.value})} 
                    required 
                    className="w-full bg-slate-50 dark:bg-slate-800 border-0 rounded-2xl px-5 py-3.5 focus:ring-4 focus:ring-amber-500/10 outline-none text-sm font-bold dark:text-slate-200" 
                  />
                </div>
                <div>
                  <label className="text-[10px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest block mb-2 ml-1">{t.password}</label>
                  <div className="relative">
                    <input 
                      name="password" 
                      type={showPassword ? "text" : "password"} 
                      value={formData.password} 
                      onChange={e => setFormData({...formData, password: e.target.value})} 
                      required 
                      className="w-full bg-slate-50 dark:bg-slate-800 border-0 rounded-2xl px-5 py-3.5 pr-12 focus:ring-4 focus:ring-amber-500/10 outline-none text-sm font-bold dark:text-slate-200" 
                    />
                    <button
                      type="button"
                      onClick={() => setShowPassword(!showPassword)}
                      className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-400 hover:text-slate-600 transition-colors"
                    >
                      {showPassword ? (
                        <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z"/><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z"/></svg>
                      ) : (
                        <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13.875 18.825A10.05 10.05 0 0112 19c-4.478 0-8.268-2.943-9.543-7a9.97 9.97 0 011.563-3.029m5.858.908a3 3 0 114.243 4.243M9.878 9.878l4.242 4.242M9.88 9.88l-3.29-3.29m7.532 7.532l3.29 3.29M3 3l18 18"/></svg>
                      )}
                    </button>
                  </div>
                </div>
                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="text-[10px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest block mb-2 ml-1">{t.role}</label>
                    <select 
                      value={formData.role} 
                      onChange={e => setFormData({...formData, role: e.target.value as UserRole})} 
                      className="w-full bg-slate-50 dark:bg-slate-800 border-0 rounded-2xl px-5 py-3.5 focus:ring-4 focus:ring-amber-500/10 outline-none text-sm font-bold dark:text-slate-200"
                    >
                      <option value="employee">{t.employee}</option>
                      <option value="admin">{t.admin}</option>
                    </select>
                  </div>
                  <div>
                    <label className="text-[10px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest block mb-2 ml-1">{t.commission} (%)</label>
                    <input 
                      name="commission" 
                      type="number" 
                      value={formData.commission} 
                      onChange={e => setFormData({...formData, commission: parseInt(e.target.value) || 0})} 
                      required 
                      className="w-full bg-slate-50 dark:bg-slate-800 border-0 rounded-2xl px-5 py-3.5 focus:ring-4 focus:ring-amber-500/10 outline-none text-sm font-bold dark:text-slate-200" 
                    />
                  </div>
                </div>
                <div className="flex gap-4 mt-8">
                  <button type="submit" className="flex-1 px-4 py-4 bg-slate-950 dark:bg-amber-500 text-white dark:text-slate-950 rounded-2xl font-black text-base hover:bg-slate-800 dark:hover:bg-amber-600 transition-all shadow-xl">
                    {editingStaff ? t.updateProfessional : t.saveProfessional}
                  </button>
                </div>
              </form>
            </motion.div>
          </div>
        )}
      </AnimatePresence>
    </div>
  );
};

export default StaffManagement;

import React, { useState, useEffect } from 'react';
import Sidebar from './components/Sidebar';
import Dashboard from './components/Dashboard';
import POS from './components/POS';
import Finance from './components/Finance';
import Customers from './components/Customers';
import Settings from './components/Settings';
import Inventory from './components/Inventory';
import StaffManagement from './components/StaffManagement';
import Login from './components/Login';
import { View, Sale, Expense, Service, Product, Staff, Customer, ShopSettings } from './types';
import { INITIAL_SERVICES, INITIAL_PRODUCTS, INITIAL_STAFF, INITIAL_EXPENSES, INITIAL_CUSTOMERS, DEFAULT_SETTINGS } from './constants';
import { motion, AnimatePresence } from 'framer-motion';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<Staff | null>(() => {
    const saved = localStorage.getItem('trimtime_session');
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        // Check for expiry (legacy sessions without expiry are treated as valid for now or could force logout)
        if (parsed.user && parsed.expiry) {
           if (Date.now() < parsed.expiry) return parsed.user;
           return null;
        }
        // Fallback for old session format (optional: force logout to migrate)
        return parsed.user || parsed;
      } catch (e) {
        return null;
      }
    }
    return null;
  });

  const [currentView, setCurrentView] = useState<View>(View.DASHBOARD);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [services, setServices] = useState<Service[]>(() => {
    const saved = localStorage.getItem('trimtime_services');
    return saved ? JSON.parse(saved) : INITIAL_SERVICES;
  });
  const [products, setProducts] = useState<Product[]>(() => {
    const saved = localStorage.getItem('trimtime_products');
    return saved ? JSON.parse(saved) : INITIAL_PRODUCTS;
  });
  const [staff, setStaff] = useState<Staff[]>(() => {
    const saved = localStorage.getItem('trimtime_staff');
    return saved ? JSON.parse(saved) : INITIAL_STAFF;
  });
  const [expenses, setExpenses] = useState<Expense[]>(() => {
    const saved = localStorage.getItem('trimtime_expenses');
    return saved ? JSON.parse(saved) : INITIAL_EXPENSES;
  });
  const [customers, setCustomers] = useState<Customer[]>(() => {
    const saved = localStorage.getItem('trimtime_customers');
    return saved ? JSON.parse(saved) : INITIAL_CUSTOMERS;
  });
  const [sales, setSales] = useState<Sale[]>(() => {
    const saved = localStorage.getItem('trimtime_sales');
    return saved ? JSON.parse(saved) : [];
  });
  const [settings, setSettings] = useState<ShopSettings>(() => {
    const saved = localStorage.getItem('trimtime_settings');
    return saved ? JSON.parse(saved) : DEFAULT_SETTINGS;
  });

  // Profile Modal State
  const [isProfileOpen, setIsProfileOpen] = useState(false);
  const [profileForm, setProfileForm] = useState({
    name: '',
    username: '',
    email: '',
    password: ''
  });
  const [showProfilePassword, setShowProfilePassword] = useState(false);

  // Dark Mode State
  const [isDarkMode, setIsDarkMode] = useState(() => {
    const saved = localStorage.getItem('trimtime_theme');
    if (saved) return saved === 'dark';
    return window.matchMedia('(prefers-color-scheme: dark)').matches;
  });

  // Effects for persistence
  useEffect(() => localStorage.setItem('trimtime_services', JSON.stringify(services)), [services]);
  useEffect(() => localStorage.setItem('trimtime_products', JSON.stringify(products)), [products]);
  useEffect(() => localStorage.setItem('trimtime_staff', JSON.stringify(staff)), [staff]);
  useEffect(() => localStorage.setItem('trimtime_expenses', JSON.stringify(expenses)), [expenses]);
  useEffect(() => localStorage.setItem('trimtime_customers', JSON.stringify(customers)), [customers]);
  useEffect(() => localStorage.setItem('trimtime_sales', JSON.stringify(sales)), [sales]);
  useEffect(() => localStorage.setItem('trimtime_settings', JSON.stringify(settings)), [settings]);

  // Dark Mode Effect
  useEffect(() => {
    if (isDarkMode) {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
    localStorage.setItem('trimtime_theme', isDarkMode ? 'dark' : 'light');
  }, [isDarkMode]);

  const toggleTheme = () => setIsDarkMode(!isDarkMode);

  // Check for session expiry on mount and periodically
  useEffect(() => {
    const checkSession = () => {
      const saved = localStorage.getItem('trimtime_session');
      if (saved) {
        try {
          const parsed = JSON.parse(saved);
          if (parsed.expiry && Date.now() > parsed.expiry) {
            handleLogout();
          }
        } catch (e) {
          // invalid session
        }
      }
    };
    checkSession();
    const interval = setInterval(checkSession, 60000); // Check every minute
    return () => clearInterval(interval);
  }, []);

  const handleLogin = (user: Staff, rememberMe: boolean) => {
    // 30 days if remember me is checked, otherwise 1 hour
    const sessionDuration = rememberMe ? 30 * 24 * 60 * 60 * 1000 : 60 * 60 * 1000;
    const expiry = Date.now() + sessionDuration;

    localStorage.setItem('trimtime_session', JSON.stringify({ user, expiry }));
    setCurrentUser(user);
  };

  const handleLogout = () => {
    localStorage.removeItem('trimtime_session');
    setCurrentUser(null);
    setCurrentView(View.DASHBOARD);
  };

  const openProfile = () => {
    if (currentUser) {
      setProfileForm({
        name: currentUser.name,
        username: currentUser.username,
        email: currentUser.email || '',
        password: currentUser.password || ''
      });
      setIsProfileOpen(true);
    }
  };

  const updateProfile = (e: React.FormEvent) => {
    e.preventDefault();
    if (!currentUser) return;

    const updatedUser: Staff = {
      ...currentUser,
      name: profileForm.name,
      username: profileForm.username,
      email: profileForm.email,
      password: profileForm.password
    };

    // Update in staff list
    const updatedStaffList = staff.map(s => s.id === currentUser.id ? updatedUser : s);
    setStaff(updatedStaffList);

    // Update current user state
    setCurrentUser(updatedUser);

    // Update session in local storage to prevent logout on refresh/expiry issues with old data
    const savedSession = localStorage.getItem('trimtime_session');
    if (savedSession) {
      const parsed = JSON.parse(savedSession);
      localStorage.setItem('trimtime_session', JSON.stringify({ ...parsed, user: updatedUser }));
    }

    setIsProfileOpen(false);
    alert('Profile updated successfully.');
  };

  const updateLanguage = (lang: string) => {
    document.documentElement.lang = lang;
    document.dir = lang === 'ur' || lang === 'fa' ? 'rtl' : 'ltr';
  };

  useEffect(() => {
    updateLanguage(settings.language);
  }, [settings.language]);

  if (!currentUser) {
    return <Login onLogin={handleLogin} staffList={staff} />;
  }

  return (
    <div className="flex h-screen bg-slate-50 dark:bg-slate-950 overflow-hidden relative transition-colors duration-300">
      <Sidebar 
        currentView={currentView}
        onViewChange={setCurrentView}
        shopName={settings.shopName}
        userRole={currentUser.role}
        isOpen={isSidebarOpen}
        onClose={() => setIsSidebarOpen(false)}
        language={settings.language}
      />

      <main className="flex-1 flex flex-col h-full relative md:pl-64 transition-all duration-300">
        {/* Mobile Header */}
        <div className="md:hidden flex items-center justify-between p-4 bg-white dark:bg-slate-900 border-b border-slate-100 dark:border-slate-800 z-50">
          <div className="flex items-center gap-3">
             <div className="w-8 h-8 bg-gradient-to-br from-amber-400 to-amber-600 rounded-lg flex items-center justify-center font-brand text-xl text-slate-950 shadow-lg">
                {settings.shopName.charAt(0)}
             </div>
             <span className="font-bold text-slate-900 dark:text-white truncate max-w-[150px]">{settings.shopName}</span>
          </div>
          <div className="flex items-center gap-2">
            <button 
              onClick={toggleTheme}
              className="p-2 text-slate-500 dark:text-slate-400 bg-slate-100 dark:bg-slate-800 rounded-lg"
            >
              {isDarkMode ? (
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 3v1m0 16v1m9-9h-1M4 12H3m15.364 6.364l-.707-.707M6.343 6.343l-.707-.707m12.728 0l-.707.707M6.343 17.657l-.707.707M16 12a4 4 0 11-8 0 4 4 0 018 0z"/></svg>
              ) : (
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M20.354 15.354A9 9 0 018.646 3.646 9.003 9.003 0 0012 21a9.003 9.003 0 008.354-5.646z"/></svg>
              )}
            </button>
            <button onClick={() => setIsSidebarOpen(true)} className="p-2 text-slate-500">
              <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 6h16M4 12h16m-7 6h7"/></svg>
            </button>
          </div>
        </div>

        {/* Top Bar (Desktop) */}
        <div className="hidden md:flex justify-between items-center py-6 px-8 no-print">
            <h1 className="text-2xl font-black text-slate-900 dark:text-white font-brand tracking-tight">
               {currentView === View.DASHBOARD && 'Dashboard'}
               {currentView === View.POS && 'Point of Sale'}
               {currentView === View.INVENTORY && 'Inventory Management'}
               {currentView === View.CUSTOMERS && 'Client Directory'}
               {currentView === View.FINANCE && 'Financial Overview'}
               {currentView === View.STAFF && 'Team Management'}
               {currentView === View.SETTINGS && 'Configuration'}
            </h1>
            <div className="flex items-center gap-4">
               <button 
                onClick={toggleTheme}
                className="bg-white dark:bg-slate-900 text-slate-400 dark:text-slate-500 hover:text-amber-500 dark:hover:text-amber-400 p-2.5 rounded-xl border border-slate-200 dark:border-slate-800 transition-colors shadow-sm"
                title={isDarkMode ? "Switch to Light Mode" : "Switch to Dark Mode"}
               >
                 {isDarkMode ? (
                   <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 3v1m0 16v1m9-9h-1M4 12H3m15.364 6.364l-.707-.707M6.343 6.343l-.707-.707m12.728 0l-.707.707M6.343 17.657l-.707.707M16 12a4 4 0 11-8 0 4 4 0 018 0z"/></svg>
                 ) : (
                   <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M20.354 15.354A9 9 0 018.646 3.646 9.003 9.003 0 0012 21a9.003 9.003 0 008.354-5.646z"/></svg>
                 )}
               </button>

               <div 
                  onClick={openProfile}
                  className="flex items-center gap-3 cursor-pointer hover:bg-slate-200 dark:hover:bg-slate-800/50 p-2 rounded-xl transition-colors -mr-2"
                  title="Edit Profile"
               >
                 <div className="flex flex-col items-end">
                    <span className="font-bold text-sm text-slate-900 dark:text-white">{currentUser.name}</span>
                    <span className="text-[10px] font-black uppercase text-slate-400 dark:text-slate-500 tracking-widest">{currentUser.role}</span>
                 </div>
                 <div className="w-10 h-10 rounded-full bg-slate-200 dark:bg-slate-800 flex items-center justify-center text-slate-500 dark:text-slate-400 font-black shadow-inner">
                    {currentUser.name.charAt(0)}
                 </div>
               </div>
               <button 
                onClick={handleLogout}
                className="bg-slate-100 dark:bg-slate-800 text-slate-500 dark:text-slate-400 hover:text-rose-500 dark:hover:text-rose-500 p-2.5 rounded-xl transition-colors"
                title="Logout"
               >
                 <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M17 16l4-4m0 0l-4-4m4 4H7m6 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h4a3 3 0 013 3v1"/></svg>
               </button>
            </div>
        </div>

        <div className="flex-1 overflow-y-auto overflow-x-hidden p-4 md:p-8 scroll-smooth" id="main-content">
          <AnimatePresence mode='wait'>
            <motion.div
              key={currentView}
              initial={{ opacity: 0, y: 10 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0, y: -10 }}
              transition={{ duration: 0.2 }}
              className="h-full"
            >
              {currentView === View.DASHBOARD && <Dashboard sales={sales} expenses={expenses} currency={settings.currency} language={settings.language} />}
              {currentView === View.POS && (
                <POS 
                  services={services} 
                  products={products} 
                  staff={staff} 
                  customers={customers}
                  settings={settings}
                  currentUser={currentUser}
                  onCompleteSale={(sale) => setSales([...sales, sale])}
                  onAddCustomer={(customer) => setCustomers([...customers, customer])}
                />
              )}
              {currentView === View.FINANCE && (
                <Finance 
                  sales={sales} 
                  expenses={expenses} 
                  staffList={staff}
                  onAddExpense={(expense) => setExpenses([...expenses, expense])}
                  currency={settings.currency}
                  language={settings.language}
                />
              )}
              {currentView === View.CUSTOMERS && (
                <Customers 
                  customers={customers} 
                  sales={sales} 
                  onAddCustomer={(customer) => setCustomers([...customers, customer])}
                  currency={settings.currency}
                  language={settings.language}
                />
              )}
