                </div>
                <div>
                  <label className="text-[10px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest block mb-2 ml-1">Full Name</label>
                  <input 
                    type="text" 
                    value={profileForm.name} 
                    onChange={e => setProfileForm({...profileForm, name: e.target.value})} 
                    required 
                    className="w-full bg-slate-50 dark:bg-slate-800 border-0 rounded-2xl px-5 py-3.5 focus:ring-4 focus:ring-amber-500/10 outline-none text-sm font-bold dark:text-slate-200" 
                  />
                </div>
                <div>
                  <label className="text-[10px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest block mb-2 ml-1">Email</label>
                  <input 
                    type="email" 
                    value={profileForm.email} 
                    onChange={e => setProfileForm({...profileForm, email: e.target.value})} 
                    className="w-full bg-slate-50 dark:bg-slate-800 border-0 rounded-2xl px-5 py-3.5 focus:ring-4 focus:ring-amber-500/10 outline-none text-sm font-bold dark:text-slate-200" 
                  />
                </div>
                <div>
                  <label className="text-[10px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest block mb-2 ml-1">Username (Login ID)</label>
                  <input 
                    type="text" 
                    value={profileForm.username} 
                    onChange={e => setProfileForm({...profileForm, username: e.target.value})} 
                    required 
                    className="w-full bg-slate-50 dark:bg-slate-800 border-0 rounded-2xl px-5 py-3.5 focus:ring-4 focus:ring-amber-500/10 outline-none text-sm font-bold dark:text-slate-200" 
                  />
                </div>
                <div>
                  <label className="text-[10px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest block mb-2 ml-1">Password</label>
                  <div className="relative">
                    <input 
                      type={showProfilePassword ? "text" : "password"} 
                      value={profileForm.password} 
                      onChange={e => setProfileForm({...profileForm, password: e.target.value})} 
                      required 
                      className="w-full bg-slate-50 dark:bg-slate-800 border-0 rounded-2xl px-5 py-3.5 pr-12 focus:ring-4 focus:ring-amber-500/10 outline-none text-sm font-bold dark:text-slate-200" 
                    />
                    <button
                      type="button"
                      onClick={() => setShowProfilePassword(!showProfilePassword)}
                      className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-400 hover:text-slate-600 transition-colors"
                    >
                      {showProfilePassword ? (
                        <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z"/><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z"/></svg>
                      ) : (
                        <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13.875 18.825A10.05 10.05 0 0112 19c-4.478 0-8.268-2.943-9.543-7a9.97 9.97 0 011.563-3.029m5.858.908a3 3 0 114.243 4.243M9.878 9.878l4.242 4.242M9.88 9.88l-3.29-3.29m7.532 7.532l3.29 3.29M3 3l18 18"/></svg>
                      )}
                    </button>
                  </div>
                </div>
                <div className="flex gap-4 mt-8">
                  <button type="submit" className="flex-1 px-4 py-4 bg-slate-950 dark:bg-amber-500 text-white dark:text-slate-950 rounded-2xl font-black text-base hover:bg-slate-800 dark:hover:bg-amber-600 transition-all shadow-xl">
                    Save Changes
                  </button>
                </div>
              </form>
            </motion.div>
          </div>
        )}
      </AnimatePresence>
    </div>
  );
};

export default App;

payload.text:
I will connect your TrimTime POS application to your Supabase backend.

Here is the plan:
1.  **Add the Supabase SDK** to your project via the import map.
2.  **Create a `supabaseClient.ts`** file to initialize the connection with your specific credentials.
3.  **Create a SQL Schema file** that you can copy and paste into your Supabase SQL Editor to create the necessary tables.
4.  **Update `App.tsx`** to fetch data from Supabase on load and save data to Supabase when you perform actions (like making a sale, adding staff, etc.), replacing the `localStorage` system.

### **IMPORTANT: Database Setup**
Before the app will work, you **must** run the following SQL in your Supabase Dashboard (Go to **SQL Editor** -> **New Query** -> Paste & Run):

```sql
-- Enable UUID extension
create extension if not exists "uuid-ossp";

-- Create Tables
create table if not exists staff (
  id text primary key,
  name text,
  role text,
  commission numeric,
  username text,
  password text,
  email text
);

create table if not exists services (
  id text primary key,
  name text,
  price numeric,
  duration numeric,
  category text
);

create table if not exists products (
  id text primary key,
  name text,
  price numeric,
  cost numeric,
  stock numeric,
  barcode text
);

create table if not exists customers (
  id text primary key,
  name text,
  phone text,
  email text,
  notes text,
  created_at text
);

create table if not exists sales (
  id text primary key,
  timestamp text,
  items jsonb, -- Stores the array of items sold
  staff_id text,
  customer_id text,
  total numeric,
  tax numeric,
  discount numeric,
  discount_code text,
  payment_method text,
  tax_type text
);

create table if not exists expenses (
  id text primary key,
  date text,
  category text,
  amount numeric,
  description text
);

create table if not exists settings (
  id int primary key default 1,
  data jsonb -- Stores the entire settings object
);

-- Insert default settings row if not exists
insert into settings (id, data) values (1, '{}'::jsonb) on conflict do nothing;

-- DISABLE RLS FOR POS FUNCTIONALITY (Since we are using custom auth logic)
alter table staff enable row level security;
create policy "Enable all access" on staff for all using (true) with check (true);

alter table services enable row level security;
create policy "Enable all access" on services for all using (true) with check (true);

alter table products enable row level security;
create policy "Enable all access" on products for all using (true) with check (true);

alter table customers enable row level security;
create policy "Enable all access" on customers for all using (true) with check (true);

alter table sales enable row level security;
create policy "Enable all access" on sales for all using (true) with check (true);

alter table expenses enable row level security;
create policy "Enable all access" on expenses for all using (true) with check (true);

alter table settings enable row level security;
create policy "Enable all access" on settings for all using (true) with check (true);
```

