            </table>
          </div>
        </div>

        {/* AI Insights Section */}
        <div className="bg-slate-900 dark:bg-slate-900 text-white p-6 md:p-8 rounded-[2rem] md:rounded-3xl shadow-xl relative no-print border border-slate-800/50 overflow-hidden">
