                    <p className="whitespace-pre-wrap break-words leading-relaxed text-slate-300 text-sm md:text-base w-full">
                      {insights}
                    </p>
                  </div>
                ) : (
                  <div className="flex flex-col items-center justify-center h-full text-slate-500 py-6 md:py-8 text-center">
                    <p className="italic text-xs md:text-sm">{t.aiPrompt}</p>
                  </div>
                )}
            </div>
          </div>
        </div>
      </div>

      {/* Expense Management Sidebar */}
      <div className="space-y-6 no-print">
        <div className="bg-white dark:bg-slate-900 p-6 md:p-7 rounded-[2rem] border border-slate-100 dark:border-slate-800 shadow-sm">
          <h3 className="text-lg font-bold text-slate-800 dark:text-white mb-6 flex items-center gap-3">
            <div className="w-8 h-8 rounded-lg bg-rose-50 dark:bg-rose-900/20 text-rose-500 dark:text-rose-400 flex items-center justify-center">
               <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M12 9v3m0 0v3m0-3h3m-3 0H9m12 0a9 9 0 11-18 0 9 9 0 0118 0z"/></svg>
            </div>
            {t.newExpense}
          </h3>
          <div className="space-y-4">
            <div>
              <label className="text-[10px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest block mb-2 ml-1">{t.category}</label>
              <input
                type="text"
                value={newExpense.category}
                onChange={e => setNewExpense({...newExpense, category: e.target.value})}
                placeholder=""
                className="w-full bg-slate-50 dark:bg-slate-800 border-0 rounded-xl px-4 py-3 focus:ring-2 focus:ring-amber-400 outline-none text-sm font-bold dark:text-slate-200"
              />
            </div>
            <div>
              <label className="text-[10px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest block mb-2 ml-1">{t.amount} ({currency})</label>
              <input
                type="number"
                value={newExpense.amount}
                onChange={e => setNewExpense({...newExpense, amount: Number(e.target.value)})}
                className="w-full bg-slate-50 dark:bg-slate-800 border-0 rounded-xl px-4 py-3 focus:ring-2 focus:ring-amber-400 outline-none text-sm font-bold dark:text-slate-200"
              />
            </div>
            <div>
              <label className="text-[10px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest block mb-2 ml-1">{t.details}</label>
              <textarea
                value={newExpense.description}
                onChange={e => setNewExpense({...newExpense, description: e.target.value})}
                className="w-full bg-slate-50 dark:bg-slate-800 border-0 rounded-xl px-4 py-3 focus:ring-2 focus:ring-amber-400 outline-none h-20 resize-none text-sm font-medium dark:text-slate-300"
                placeholder={t.noteDetails}
              />
            </div>
            <button
              onClick={() => {
                if (!newExpense.category || newExpense.amount <= 0) return;
                onAddExpense({
                  id: Math.random().toString(36).substr(2, 9),
                  date: new Date().toISOString().split('T')[0],
                  category: newExpense.category,
                  amount: newExpense.amount,
                  description: newExpense.description
                });
                setNewExpense({ category: '', amount: 0, description: '' });
              }}
              className="w-full bg-slate-900 dark:bg-slate-950 text-white py-4 rounded-xl font-black text-sm hover:bg-slate-800 dark:hover:bg-slate-950/80 transition-all shadow-lg active:scale-95"
            >
              {t.addExpense}
            </button>
          </div>
        </div>

        <div className="bg-white dark:bg-slate-900 p-6 md:p-7 rounded-[2rem] border border-slate-100 dark:border-slate-800 shadow-sm overflow-hidden">
          <h3 className="text-lg font-bold text-slate-800 dark:text-white mb-5">{t.history}</h3>
          <div className="space-y-3 max-h-[300px] overflow-y-auto pr-2 scrollbar-hide">
            {expenses.slice().reverse().map(exp => (
              <div key={exp.id} className="flex justify-between items-center py-3 border-b border-slate-50 dark:border-slate-800 last:border-0 group">
                <div>
                  <p className="font-extrabold text-slate-800 dark:text-slate-200 text-sm">{exp.category}</p>
                  <p className="text-[10px] text-slate-400 dark:text-slate-500 font-bold uppercase">{new Date(exp.date).toLocaleDateString()}</p>
                </div>
                <div className="flex items-center gap-3">
                    <p className="font-black text-rose-500 dark:text-rose-400">{currency}{exp.amount.toLocaleString()}</p>
                    {onDeleteExpense && (
                        <button 
                            onClick={() => {
                                if(confirm('Remove this expense record?')) onDeleteExpense(exp.id);
                            }}
                            className="text-slate-300 hover:text-rose-500 transition-colors p-1"
                        >
                            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12"/></svg>
                        </button>
                    )}
                </div>
              </div>
            ))}
            {expenses.length === 0 && (
                <p className="text-center py-8 text-slate-300 dark:text-slate-700 italic text-xs font-bold">{t.noRecords}</p>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default Finance;

import React, { useState } from 'react';
import { Customer, Sale, Language } from '../types';
import { TRANSLATIONS } from '../constants';
import { motion, AnimatePresence } from 'framer-motion';

interface CustomersProps {
  customers: Customer[];
  sales: Sale[];
  onUpdateCustomers: (customers: Customer[]) => void;
  currency: string;
  language: Language;
}

const Customers: React.FC<CustomersProps> = ({ customers, sales, onUpdateCustomers, currency, language }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedCustomer, setSelectedCustomer] = useState<Customer | null>(null);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [formData, setFormData] = useState({ name: '', phone: '', email: '', notes: '' });

  const t = TRANSLATIONS[language];

  const filteredCustomers = customers.filter(c => 
    c.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
    c.phone.includes(searchTerm)
  );

  const getCustomerStats = (id: string) => {
    const custSales = sales.filter(s => s.customerId === id);
    const totalSpent = custSales.reduce((acc, s) => acc + s.total, 0);
    const lastVisit = custSales.length > 0 
      ? new Date(custSales.sort((a,b) => b.timestamp.localeCompare(a.timestamp))[0].timestamp).toLocaleDateString()
      : 'Never';
    return { totalSpent, lastVisit, visitCount: custSales.length };
  };

  const customerTransactions = selectedCustomer 
    ? sales.filter(s => s.customerId === selectedCustomer.id).sort((a,b) => b.timestamp.localeCompare(a.timestamp))
    : [];

  const handleOpenAdd = () => {
    setIsEditing(false);
    setFormData({ name: '', phone: '', email: '', notes: '' });
    setIsModalOpen(true);
  };

  const handleOpenEdit = (customer: Customer) => {
    setIsEditing(true);
    setFormData({ name: customer.name, phone: customer.phone, email: customer.email, notes: customer.notes });
    setIsModalOpen(true);
  };

  const handleDelete = (id: string) => {
    if (confirm('Permanently delete this client profile?')) {
        onUpdateCustomers(customers.filter(c => c.id !== id));
        setSelectedCustomer(null);
    }
  };

  const handleSave = () => {
     if (!formData.name) return;

     if (isEditing && selectedCustomer) {
        const updatedList = customers.map(c => c.id === selectedCustomer.id ? { ...c, ...formData } : c);
        onUpdateCustomers(updatedList);
        setSelectedCustomer({ ...selectedCustomer, ...formData });
     } else {
        const newCustomer: Customer = {
           id: 'c' + Date.now().toString(36),
           ...formData,
           createdAt: new Date().toISOString().split('T')[0]
        };
        onUpdateCustomers([...customers, newCustomer]);
     }
     setIsModalOpen(false);
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 no-print">
        <div>
          <h2 className="text-2xl md:text-3xl font-bold text-slate-800 dark:text-white font-brand">{t.directory}</h2>
          <p className="text-slate-500 dark:text-slate-400 text-sm">{t.clientProfiles}</p>
        </div>
        <button 
          onClick={handleOpenAdd}
          className="bg-slate-900 dark:bg-slate-800 text-white px-6 py-3 rounded-xl font-bold flex items-center gap-2 hover:bg-slate-800 transition-all shadow-lg text-sm w-full sm:w-auto justify-center"
        >
          <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M12 6v6m0 0v6m0-6h6m-6 0H6"/></svg>
          {t.addClient}
        </button>
      </div>

      <div className="relative no-print">
        <svg className="w-5 h-5 absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 dark:text-slate-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z"/></svg>
        <input 
          type="text" 
          placeholder={t.searchClients}
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
          className="w-full bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-2xl py-3.5 pl-12 pr-6 outline-none focus:ring-4 focus:ring-amber-500/10 shadow-sm text-sm dark:text-slate-200"
        />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 md:gap-8">
        {/* List of Customers */}
        <div className={`lg:col-span-1 space-y-3 max-h-[50vh] lg:max-h-[70vh] overflow-y-auto pr-1 no-print scrollbar-hide ${selectedCustomer ? 'hidden lg:block' : 'block'}`}>
          {filteredCustomers.map(customer => {
            const stats = getCustomerStats(customer.id);
            return (
              <div 
                key={customer.id} 
                onClick={() => setSelectedCustomer(customer)}
                className={`bg-white dark:bg-slate-900 p-4 rounded-2xl border transition-all cursor-pointer flex justify-between items-center ${selectedCustomer?.id === customer.id ? 'border-amber-400 ring-4 ring-amber-100/50 dark:ring-amber-900/20 shadow-md' : 'border-slate-100 dark:border-slate-800 hover:border-slate-200 dark:hover:border-slate-700 shadow-sm'}`}
              >
                <div className="flex items-center gap-3">
                  <div className="w-9 h-9 rounded-full bg-slate-100 dark:bg-slate-800 flex items-center justify-center text-slate-500 dark:text-slate-400 text-sm font-black uppercase">
                    {customer.name.charAt(0)}
                  </div>
                  <div>
                    <h4 className="font-bold text-slate-800 dark:text-slate-200 text-xs truncate max-w-[120px]">{customer.name}</h4>
                    <p className="text-[9px] text-slate-400 dark:text-slate-500 font-bold uppercase tracking-tight">{customer.phone}</p>
                  </div>
                </div>
                <div className="text-right">
                    <p className="text-[8px] text-slate-400 dark:text-slate-600 uppercase font-black tracking-widest">{t.visits}</p>
                    <p className="text-xs font-black text-amber-600 dark:text-amber-500">{stats.visitCount}</p>
                </div>
              </div>
            );
          })}
        </div>

        {/* Selected Customer Profile */}
        <div className={`lg:col-span-2 space-y-6 ${!selectedCustomer ? 'hidden lg:block' : 'block'}`}>
          {selectedCustomer ? (
            <>
              <div className="lg:hidden mb-4">
                 <button onClick={() => setSelectedCustomer(null)} className="text-xs font-black text-slate-400 dark:text-slate-600 uppercase flex items-center gap-2">
                    <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M15 19l-7-7 7-7"/></svg>
                    Back to directory
                 </button>
              </div>

              {/* Profile Card */}
              <div className="bg-white dark:bg-slate-900 rounded-[2rem] border border-slate-100 dark:border-slate-800 shadow-sm p-6 md:p-8 relative">
                <div className="absolute top-6 right-6 flex gap-2">
                    <button 
                        onClick={() => handleOpenEdit(selectedCustomer)} 
                        className="p-2 text-slate-400 hover:text-amber-500 transition-colors bg-slate-50 dark:bg-slate-800 rounded-lg"
                        title="Edit Profile"
                    >
                        <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15.232 5.232l3.536 3.536m-2.036-5.036a2.5 2.5 0 113.536 3.536L6.5 21.036H3v-3.572L16.732 3.732z"/></svg>
                    </button>
                    <button 
                        onClick={() => handleDelete(selectedCustomer.id)} 
                        className="p-2 text-slate-400 hover:text-rose-500 transition-colors bg-slate-50 dark:bg-slate-800 rounded-lg"
                        title="Delete Profile"
                    >
                        <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"/></svg>
                    </button>
                </div>

                <div className="flex flex-col md:flex-row gap-6 md:gap-8 items-center md:items-start text-center md:text-left">
                  <div className="w-full md:w-1/3 md:border-r border-slate-100 dark:border-slate-800 md:pr-8 flex flex-col items-center md:items-start">
                    <div className="w-20 h-20 md:w-24 md:h-24 rounded-full bg-amber-100 dark:bg-amber-900/20 text-amber-600 dark:text-amber-500 flex items-center justify-center text-3xl md:text-4xl font-black mx-auto md:mx-0 mb-4 shadow-inner">
                      {selectedCustomer.name.charAt(0)}
                    </div>
                    <h3 className="text-xl md:text-2xl font-black text-slate-800 dark:text-white truncate w-full">{selectedCustomer.name}</h3>
                    <p className="text-slate-400 dark:text-slate-500 text-xs md:text-sm mb-4 truncate w-full">{selectedCustomer.email || 'No email'}</p>
                    <div className="flex flex-wrap justify-center md:justify-start gap-2">
                      <span className="px-2.5 py-1 bg-emerald-50 dark:bg-emerald-900/20 text-emerald-600 dark:text-emerald-400 rounded-full text-[9px] font-black uppercase tracking-wider">{t.member}</span>
                      {getCustomerStats(selectedCustomer.id).visitCount > 5 && (
                        <span className="px-2.5 py-1 bg-amber-50 dark:bg-amber-900/20 text-amber-600 dark:text-amber-500 rounded-full text-[9px] font-black uppercase tracking-wider">{t.vip}</span>
                      )}
                    </div>
                  </div>

                  <div className="flex-1 w-full space-y-6">
                    <div className="grid grid-cols-2 gap-3">
                      <div className="bg-slate-50 dark:bg-slate-800 p-4 rounded-2xl border border-slate-100 dark:border-slate-700">
                        <p className="text-[9px] text-slate-400 dark:text-slate-500 uppercase font-black tracking-widest mb-1">{t.lifetime}</p>
                        <p className="text-lg md:text-xl font-black text-slate-900 dark:text-white">{currency}{getCustomerStats(selectedCustomer.id).totalSpent.toFixed(2)}</p>
                      </div>
                      <div className="bg-slate-50 dark:bg-slate-800 p-4 rounded-2xl border border-slate-100 dark:border-slate-700">
                        <p className="text-[9px] text-slate-400 dark:text-slate-500 uppercase font-black tracking-widest mb-1">{t.lastSeen}</p>
                        <p className="text-lg md:text-xl font-black text-slate-900 dark:text-white">{getCustomerStats(selectedCustomer.id).lastVisit}</p>
                      </div>
                    </div>

                    <div className="text-left">
                      <h5 className="text-[9px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest mb-2 px-1">{t.stylePreferences}</h5>
                      <div className="bg-amber-50/40 dark:bg-amber-900/10 p-5 rounded-2xl border border-amber-100/50 dark:border-amber-900/20 text-amber-900 dark:text-amber-200 text-sm leading-relaxed italic">
                        {selectedCustomer.notes || t.noNotes}
                      </div>
                    </div>
                  </div>
                </div>
              </div>

              {/* Transaction History Table */}
              <div className="bg-white dark:bg-slate-900 rounded-[2rem] border border-slate-100 dark:border-slate-800 shadow-sm overflow-hidden">
                <div className="px-6 py-5 border-b border-slate-50 dark:border-slate-800 flex justify-between items-center bg-slate-50/30 dark:bg-slate-800/30">
                  <h4 className="font-bold text-slate-800 dark:text-white">{t.history}</h4>
                  <span className="text-[9px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest">{customerTransactions.length} {t.total}</span>
                </div>

                {/* Mobile Cards for Transactions */}
                <div className="md:hidden">
                    {customerTransactions.map((sale) => (
                      <div key={sale.id} className="p-4 border-b border-slate-50 dark:border-slate-800 last:border-0">
                         <div className="flex justify-between items-center mb-2">
                            <div>
                                <p className="font-bold text-slate-800 dark:text-slate-200 text-xs">{new Date(sale.timestamp).toLocaleDateString()}</p>
                                <p className="text-[9px] text-slate-400 dark:text-slate-600 font-mono">#{sale.id.slice(0,6)}</p>
                            </div>
                            <div className="text-right">
