                          <td className="px-6 py-5">
                            <p className="font-bold text-slate-800 dark:text-slate-200 text-xs">{new Date(sale.timestamp).toLocaleDateString()}</p>
                            <p className="text-[9px] text-slate-400 dark:text-slate-600 font-mono">#{sale.id.slice(0,6)}</p>
