                    <button onClick={() => handleLanguageSwitch('ur')} className="w-full text-left px-4 py-3 hover:bg-slate-50 dark:hover:bg-slate-800 text-xs font-bold text-slate-600 dark:text-slate-300 flex justify-between">
                       Urdu <span>🇵🇰</span>
                    </button>
                    <button onClick={() => handleLanguageSwitch('fa')} className="w-full text-left px-4 py-3 hover:bg-slate-50 dark:hover:bg-slate-800 text-xs font-bold text-slate-600 dark:text-slate-300 flex justify-between">
