              </form>
            </motion.div>
          </div>
        )}
      </AnimatePresence>
    </div>
  );
};

export default App;

import React, { useState, useMemo } from 'react';
import { Sale, Expense, Staff, Language, Customer } from '../types';
import { getFinancialInsights } from '../services/geminiService';
import { TRANSLATIONS } from '../constants';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer } from 'recharts';
import { motion, AnimatePresence } from 'framer-motion';

interface FinanceProps {
  sales: Sale[];
  expenses: Expense[];
  staffList: Staff[];
  onAddExpense: (expense: Expense) => void;
  onDeleteExpense?: (id: string) => void;
  onDeleteSale?: (id: string) => void;
  onDeleteSales?: (ids: string[]) => void;
  currentUser: Staff;
  customers: Customer[];
  currency: string;
  language: Language;
  billingCycleDay?: number;
}

const Finance: React.FC<FinanceProps> = ({ sales, expenses, staffList, onAddExpense, onDeleteExpense, onDeleteSale, onDeleteSales, currentUser, customers, currency, language, billingCycleDay = 1 }) => {
  const [activeTab, setActiveTab] = useState<'overview' | 'transactions' | 'expenses'>('overview');
  const [loadingInsights, setLoadingInsights] = useState(false);
  const [insights, setInsights] = useState<string | null>(null);
  const [newExpense, setNewExpense] = useState({ category: '', amount: 0, description: '' });
  const [transactionSearch, setTransactionSearch] = useState('');
  const [viewingSale, setViewingSale] = useState<Sale | null>(null);
  const [selectedTransactions, setSelectedTransactions] = useState<Set<string>>(new Set());

  const t = TRANSLATIONS[language];

  // Date Range State for Commission Report (Smart Billing Cycle Default)
  const [startDate, setStartDate] = useState(() => {
    const today = new Date();
    const currentDay = today.getDate();
    let start = new Date(today.getFullYear(), today.getMonth(), billingCycleDay);

    // If today is before the cycle start day, go back to previous month
    if (currentDay < billingCycleDay) {
        start = new Date(today.getFullYear(), today.getMonth() - 1, billingCycleDay);
    }
    return start.toISOString().split('T')[0];
  });

  const [endDate, setEndDate] = useState(() => {
    return new Date().toISOString().split('T')[0];
  });

  const totalRevenue = sales.reduce((acc, s) => acc + s.total, 0);
  const totalExpenses = expenses.reduce((acc, e) => acc + e.amount, 0);
  const profit = totalRevenue - totalExpenses;

  // Filtered Sales for Report
  const reportData = useMemo(() => {
    const filteredSales = sales.filter(s => {
      const date = s.timestamp.split('T')[0];
      return date >= startDate && date <= endDate;
    });

    const staffStats = staffList.map(staff => {
      const personalSales = filteredSales.filter(s => s.staffId === staff.id);
      const revenue = personalSales.reduce((acc, s) => acc + s.total, 0);
      const commissionEarned = (revenue * staff.commission) / 100;

      return {
        ...staff,
        salesCount: personalSales.length,
        revenue,
        commissionEarned
      };
    }).sort((a, b) => b.revenue - a.revenue);

    const periodRevenue = filteredSales.reduce((acc, s) => acc + s.total, 0);
    const periodCommission = staffStats.reduce((acc, s) => acc + s.commissionEarned, 0);

    return { staffStats, periodRevenue, periodCommission, salesCount: filteredSales.length };
  }, [sales, staffList, startDate, endDate]);

  // Filtered Sales for Transactions Table
  const filteredTransactions = useMemo(() => {
    const term = transactionSearch.toLowerCase();
    return sales.filter(s => {
      const customerName = customers.find(c => c.id === s.customerId)?.name.toLowerCase() || '';
      const staffName = staffList.find(st => st.id === s.staffId)?.name.toLowerCase() || '';
      return (
        s.id.toLowerCase().includes(term) ||
        customerName.includes(term) ||
        staffName.includes(term)
      );
    }).sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime());
  }, [sales, transactionSearch, customers, staffList]);

  const handleGenerateInsights = async () => {
    setLoadingInsights(true);
    const result = await getFinancialInsights(sales, expenses);
    setInsights(result);
    setLoadingInsights(false);
  };

  const data = [
    { name: t.total, revenue: totalRevenue, expenses: totalExpenses, profit: profit }
  ];

  const handleDelete = (id: string) => {
    if (confirm('Are you sure you want to delete this bill? Inventory stock will be restored.')) {
        if (onDeleteSale) onDeleteSale(id);
    }
  };

  // Selection Logic
  const toggleSelection = (id: string) => {
    const newSelection = new Set(selectedTransactions);
    if (newSelection.has(id)) {
      newSelection.delete(id);
    } else {
      newSelection.add(id);
    }
    setSelectedTransactions(newSelection);
  };

  const toggleSelectAll = () => {
    if (selectedTransactions.size === filteredTransactions.length && filteredTransactions.length > 0) {
      setSelectedTransactions(new Set());
    } else {
      setSelectedTransactions(new Set(filteredTransactions.map(s => s.id)));
    }
  };

  const handleBulkDelete = () => {
    if (currentUser.role !== 'admin') {
      alert("Only admins can perform bulk deletion.");
      return;
    }
    const count = selectedTransactions.size;
    if (confirm(`Are you sure you want to delete ${count} selected records? Inventory stock will be restored for all items.`)) {
        if (onDeleteSales) onDeleteSales(Array.from(selectedTransactions));
        setSelectedTransactions(new Set());
    }
  };

  // CSV Report Generator (Supports Bulk Export)
  const downloadReport = (period: 'daily' | 'weekly' | 'monthly' | 'custom') => {
    let salesForReport: Sale[] = [];

    if (period === 'custom') {
        // Export selected items only
        if (selectedTransactions.size === 0) return;
        salesForReport = sales.filter(s => selectedTransactions.has(s.id));
    } else {
        // ... existing logic ...
        const today = new Date();
        let startFilterDate = new Date();

        if (period === 'daily') {
            startFilterDate = new Date(today.getFullYear(), today.getMonth(), today.getDate());
        } else if (period === 'weekly') {
            startFilterDate.setDate(today.getDate() - 7);
        } else if (period === 'monthly') {
            // Use billing cycle day logic
            const currentDay = today.getDate();
            if (currentDay < billingCycleDay) {
                startFilterDate = new Date(today.getFullYear(), today.getMonth() - 1, billingCycleDay);
            } else {
                startFilterDate = new Date(today.getFullYear(), today.getMonth(), billingCycleDay);
            }
        }
        const startFilterStr = startFilterDate.toISOString().split('T')[0];
        salesForReport = sales.filter(s => s.timestamp >= startFilterStr);
    }

    if (salesForReport.length === 0) {
        alert('No data to export.');
        return;
    }

    // CSV Header
    const csvRows = [];
    csvRows.push(['Transaction ID', 'Date', 'Time', 'Staff', 'Customer', 'Items', 'Total', 'Payment Method']);

    // CSV Rows
    salesForReport.forEach(sale => {
        const date = new Date(sale.timestamp);
        const staffName = staffList.find(s => s.id === sale.staffId)?.name || 'Unknown';
        const customerName = customers.find(c => c.id === sale.customerId)?.name || 'Walk-in';
        const itemsStr = sale.items.map(i => `${i.quantity}x ${i.name}`).join('; ');

        csvRows.push([
            sale.id,
            date.toLocaleDateString(),
            date.toLocaleTimeString(),
            staffName,
            customerName,
            itemsStr,
            sale.total.toFixed(2),
            sale.paymentMethod
        ]);
    });

    // Create File
    const csvContent = "data:text/csv;charset=utf-8," + csvRows.map(e => e.join(",")).join("\n");
    const encodedUri = encodeURI(csvContent);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", `sales_report_${new Date().toISOString().split('T')[0]}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
          {/* Tabs */}
          <div className="flex overflow-x-auto scrollbar-hide gap-2 pb-2 w-full md:w-auto">
            <button 
              onClick={() => setActiveTab('overview')}
              className={`px-6 py-3 rounded-xl font-black text-sm uppercase tracking-wider transition-all whitespace-nowrap ${activeTab === 'overview' ? 'bg-amber-500 text-slate-950 shadow-lg' : 'bg-white dark:bg-slate-900 text-slate-400 hover:text-slate-600 dark:hover:text-slate-300'}`}
            >
              {t.performanceInsights}
            </button>
            <button 
              onClick={() => setActiveTab('transactions')}
              className={`px-6 py-3 rounded-xl font-black text-sm uppercase tracking-wider transition-all whitespace-nowrap ${activeTab === 'transactions' ? 'bg-amber-500 text-slate-950 shadow-lg' : 'bg-white dark:bg-slate-900 text-slate-400 hover:text-slate-600 dark:hover:text-slate-300'}`}
            >
              {t.history}
            </button>
            <button 
              onClick={() => setActiveTab('expenses')}
              className={`px-6 py-3 rounded-xl font-black text-sm uppercase tracking-wider transition-all whitespace-nowrap ${activeTab === 'expenses' ? 'bg-amber-500 text-slate-950 shadow-lg' : 'bg-white dark:bg-slate-900 text-slate-400 hover:text-slate-600 dark:hover:text-slate-300'}`}
            >
              {t.expenses}
            </button>
          </div>

          {/* Export Controls - Only for Admin */}
          {currentUser.role === 'admin' && activeTab === 'overview' && (
             <div className="relative group self-end md:self-auto">
                <button className="flex items-center gap-2 bg-slate-900 dark:bg-slate-800 text-white px-5 py-3 rounded-xl font-bold text-xs uppercase shadow-lg hover:bg-slate-800 dark:hover:bg-slate-700 transition-all">
                   <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4"/></svg>
                   {t.exportReports}
                </button>
                <div className="absolute top-full right-0 mt-2 w-48 bg-white dark:bg-slate-900 border border-slate-100 dark:border-slate-800 rounded-xl shadow-xl overflow-hidden hidden group-hover:block z-50">
                   <button onClick={() => downloadReport('daily')} className="w-full text-left px-4 py-3 hover:bg-slate-50 dark:hover:bg-slate-800 text-xs font-bold text-slate-600 dark:text-slate-300">
                      {t.downloadDaily}
                   </button>
                   <button onClick={() => downloadReport('weekly')} className="w-full text-left px-4 py-3 hover:bg-slate-50 dark:hover:bg-slate-800 text-xs font-bold text-slate-600 dark:text-slate-300 border-t border-slate-50 dark:border-slate-800">
                      {t.downloadWeekly}
                   </button>
                   <button onClick={() => downloadReport('monthly')} className="w-full text-left px-4 py-3 hover:bg-slate-50 dark:hover:bg-slate-800 text-xs font-bold text-slate-600 dark:text-slate-300 border-t border-slate-50 dark:border-slate-800">
                      {t.downloadMonthly}
                   </button>
                </div>
             </div>
          )}
      </div>

      <AnimatePresence mode='wait'>
        {activeTab === 'overview' && (
          <motion.div 
            key="overview"
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -10 }}
            className="grid grid-cols-1 xl:grid-cols-2 gap-6 md:gap-8"
          >
            {/* General Shop Performance (All Time) */}
            <div className="bg-white dark:bg-slate-900 p-6 md:p-8 rounded-[2rem] border border-slate-100 dark:border-slate-800 shadow-sm no-print">
              <h3 className="text-lg md:text-xl font-bold text-slate-800 dark:text-white mb-6 md:mb-8 flex items-center gap-3">
                <div className="w-10 h-10 bg-amber-50 dark:bg-amber-900/20 rounded-xl flex items-center justify-center text-amber-500">
                  <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M11 3.055A9.001 9.001 0 1020.945 13H11V3.055z"/><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M20.488 9H15V3.512A9.025 9.025 0 0120.488 9z"/></svg>
                </div>
                {t.shopPerformance}
              </h3>
              <div className="h-64 md:h-80 w-full">
                <ResponsiveContainer width="100%" height="100%">
                  <BarChart data={data} margin={{top: 20, right: 30, left: 0, bottom: 5}}>
                    <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" className="dark:opacity-5" />
                    <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fill: '#94a3b8'}} />
                    <YAxis axisLine={false} tickLine={false} tick={{fill: '#94a3b8'}} />
                    <Tooltip cursor={{fill: 'transparent'}} contentStyle={{borderRadius: '12px', border: 'none', backgroundColor: '#0f172a', color: '#fff', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)'}} />
                    <Legend iconType="circle" />
                    <Bar dataKey="revenue" name={t.revenue} fill="#10b981" radius={[8, 8, 0, 0]} />
                    <Bar dataKey="expenses" name={t.expenses} fill="#f43f5e" radius={[8, 8, 0, 0]} />
                    <Bar dataKey="profit" name={t.netProfit} fill="#3b82f6" radius={[8, 8, 0, 0]} />
                  </BarChart>
                </ResponsiveContainer>
              </div>
            </div>

            {/* Detailed Commission Report Section */}
            <div className="bg-white dark:bg-slate-900 p-6 md:p-8 rounded-[2rem] border border-slate-100 dark:border-slate-800 shadow-sm no-print">
              <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-6 mb-8">
                <div>
                    <h3 className="text-lg md:text-xl font-bold text-slate-800 dark:text-white flex items-center gap-3">
                    <div className="w-10 h-10 bg-indigo-50 dark:bg-indigo-900/20 rounded-xl flex items-center justify-center text-indigo-500">
                        <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 7h6m0 10v-3m-3 3h.01M9 17h.01M9 14h.01M12 14h.01M15 11h.01M12 11h.01M9 11h.01M7 21h10a2 2 0 002-2V5a2 2 0 00-2-2H7a2 2 0 00-2 2v14a2 2 0 002 2z"/></svg>
                    </div>
                    {t.commissionReport}
                    </h3>
                    <p className="text-xs text-slate-400 dark:text-slate-500 mt-1 ml-14">{t.payrollReport}</p>
                </div>

                <div className="flex flex-col sm:flex-row gap-3 bg-slate-50 dark:bg-slate-800/50 p-1.5 rounded-2xl border border-slate-100 dark:border-slate-700">
                    <div className="flex flex-col px-2">
                        <input 
                            type="date" 
                            value={startDate}
                            onChange={(e) => setStartDate(e.target.value)}
                            className="bg-transparent border-none p-0 text-sm font-bold text-slate-700 dark:text-slate-200 focus:ring-0 outline-none"
                        />
                    </div>
                    <div className="w-px bg-slate-200 dark:bg-slate-700 hidden sm:block"></div>
                    <div className="flex flex-col px-2">
                        <input 
                            type="date" 
                            value={endDate}
                            onChange={(e) => setEndDate(e.target.value)}
                            className="bg-transparent border-none p-0 text-sm font-bold text-slate-700 dark:text-slate-200 focus:ring-0 outline-none"
                        />
                    </div>
                </div>
              </div>

              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 mb-8">
                <div className="p-4 rounded-2xl bg-indigo-50 dark:bg-indigo-900/10 border border-indigo-100 dark:border-indigo-900/20">
                    <p className="text-[10px] font-black text-indigo-400 uppercase tracking-widest mb-1">{t.periodRevenue}</p>
                    <p className="text-2xl font-black text-indigo-900 dark:text-indigo-100">{currency}{reportData.periodRevenue.toFixed(2)}</p>
                </div>
                <div className="p-4 rounded-2xl bg-emerald-50 dark:bg-emerald-900/10 border border-emerald-100 dark:border-emerald-900/20">
                    <p className="text-[10px] font-black text-emerald-400 uppercase tracking-widest mb-1">{t.totalPayout}</p>
                    <p className="text-2xl font-black text-emerald-900 dark:text-emerald-100">{currency}{reportData.periodCommission.toFixed(2)}</p>
                </div>
              </div>

              {/* Mobile View (Cards) */}
              <div className="md:hidden space-y-4">
                {reportData.staffStats.map(perf => (
                  <div key={perf.id} className="bg-slate-50 dark:bg-slate-800/50 p-5 rounded-2xl border border-slate-100 dark:border-slate-800">
                      <div className="flex justify-between items-start mb-4">
                        <div className="flex items-center gap-3">
                            <div className="w-10 h-10 rounded-full bg-white dark:bg-slate-800 flex items-center justify-center font-black text-slate-500 dark:text-slate-400 uppercase shadow-sm text-sm">
                              {perf.name.charAt(0)}
                            </div>
                            <div>
                              <p className="text-sm font-bold text-slate-800 dark:text-slate-200">{perf.name}</p>
                              <p className="text-[9px] font-black text-amber-600 dark:text-amber-500 uppercase tracking-tighter">{perf.role === 'admin' ? t.admin : t.employee}</p>
                            </div>
                        </div>
                        <span className="text-xs font-black text-slate-900 dark:text-white bg-white dark:bg-slate-800 px-3 py-1 rounded-lg border border-slate-200 dark:border-slate-700">
                          {perf.salesCount} {t.salesCount}
                        </span>
                      </div>
                      <div className="grid grid-cols-2 gap-4">
                        <div>
                            <p className="text-[9px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest mb-1">{t.totalSales}</p>
                            <p className="text-sm font-bold text-slate-700 dark:text-slate-300">{currency}{perf.revenue.toLocaleString()}</p>
                        </div>
                        <div>
                            <p className="text-[9px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest mb-1">{t.payout}</p>
                            <div className="flex flex-col">
                              <p className="text-lg font-black text-emerald-600 dark:text-emerald-400">{currency}{perf.commissionEarned.toFixed(2)}</p>
                              <p className="text-[8px] font-bold text-slate-400 dark:text-slate-500 uppercase">@ {perf.commission}%</p>
                            </div>
                        </div>
                      </div>
                  </div>
                ))}
              </div>

              {/* Desktop View (Table) */}
              <div className="hidden md:block overflow-x-auto scrollbar-hide -mx-6 md:mx-0">
                <table className="w-full text-left min-w-[600px]">
                  <thead>
