import { supabase } from './supabaseClient';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<Staff | null>(() => {
    const saved = localStorage.getItem('trimtime_session');
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        if (parsed.user && parsed.expiry) {
           if (Date.now() < parsed.expiry) return parsed.user;
           return null;
        }
        return parsed.user || parsed;
      } catch (e) {
        return null;
      }
    }
    return null;
  });

  // Initialize view based on user role (Employees -> POS, Admin -> Dashboard)
  const [currentView, setCurrentView] = useState<View>(
    currentUser?.role === 'employee' ? View.POS : View.DASHBOARD
  );

  const [isSidebarOpen, setIsSidebarOpen] = useState(false);

  // Initialize state empty, will load from Supabase
  const [services, setServices] = useState<Service[]>([]);
  const [products, setProducts] = useState<Product[]>([]);
  const [staff, setStaff] = useState<Staff[]>([]);
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [sales, setSales] = useState<Sale[]>([]);
  const [settings, setSettings] = useState<ShopSettings>(DEFAULT_SETTINGS);
  const [loading, setLoading] = useState(true);

  // Language State (Session based, separate from Global Shop Default)
  const [sessionLanguage, setSessionLanguage] = useState<Language>(() => {
    const local = localStorage.getItem('trimtime_lang');
    return (local as Language) || 'en';
  });

  // Profile Modal State
  const [isProfileOpen, setIsProfileOpen] = useState(false);
  const [profileForm, setProfileForm] = useState({
    name: '',
    username: '',
    email: '',
    password: ''
  });
  const [showProfilePassword, setShowProfilePassword] = useState(false);

  // Dark Mode State
  const [isDarkMode, setIsDarkMode] = useState(() => {
    const saved = localStorage.getItem('trimtime_theme');
    if (saved) return saved === 'dark';
    return window.matchMedia('(prefers-color-scheme: dark)').matches;
  });

  // --- SUPABASE FETCHING ---
  const fetchData = async () => {
    setLoading(true);
    try {
        const results = await Promise.all([
            supabase.from('services').select('*'),
            supabase.from('products').select('*'),
            supabase.from('staff').select('*'),
            supabase.from('expenses').select('*'),
            supabase.from('customers').select('*'),
            supabase.from('sales').select('*'),
            supabase.from('settings').select('*').single()
        ]);

        if (results[0].data) setServices(results[0].data);
        else setServices(INITIAL_SERVICES); 

        if (results[1].data) setProducts(results[1].data);
        else setProducts(INITIAL_PRODUCTS);

        if (results[2].data && results[2].data.length > 0) setStaff(results[2].data);
        else setStaff(INITIAL_STAFF);

        if (results[3].data) setExpenses(results[3].data);
        else setExpenses(INITIAL_EXPENSES);

        if (results[4].data) {
          // Map created_at to createdAt
          const mappedCustomers = results[4].data.map((c: any) => ({
             ...c,
             createdAt: c.created_at
          }));
          setCustomers(mappedCustomers);
        } else {
          setCustomers(INITIAL_CUSTOMERS);
        }

        if (results[5].data) {
            // Map snake_case DB columns to camelCase application properties
            const mappedSales = results[5].data.map((s: any) => ({
                id: s.id,
                timestamp: s.timestamp,
                items: typeof s.items === 'string' ? JSON.parse(s.items) : s.items,
                staffId: s.staff_id,
                customerId: s.customer_id,
                total: s.total,
                tax: s.tax,
                discount: s.discount,
                discountCode: s.discount_code,
                paymentMethod: s.payment_method,
                taxType: s.tax_type
            }));
            setSales(mappedSales);
        }

        // Merge defaults with fetched data to ensure all fields exist
        if (results[6].data && results[6].data.data) {
            const fetchedSettings = { ...DEFAULT_SETTINGS, ...results[6].data.data };
            setSettings(fetchedSettings);

            // If no local preference exists, use the shop default
            if (!localStorage.getItem('trimtime_lang')) {
                setSessionLanguage(fetchedSettings.language);
            }
        }
    } catch (error) {
        console.error("Error fetching data from Supabase:", error);
    } finally {
        setLoading(false);
    }
  };

  useEffect(() => {
    fetchData();
  }, []);

  // --- PERSISTENCE HANDLERS ---

  const smartUpdateServices = async (updatedList: Service[]) => {
      const idsInNewList = new Set(updatedList.map(i => i.id));
      const deletedIds = services.filter(s => !idsInNewList.has(s.id)).map(s => s.id);

      setServices(updatedList);

      if (deletedIds.length > 0) {
          await supabase.from('services').delete().in('id', deletedIds);
      }
      if (updatedList.length > 0) {
          await supabase.from('services').upsert(updatedList);
      }
  };

  const smartUpdateProducts = async (updatedList: Product[]) => {
      const idsInNewList = new Set(updatedList.map(i => i.id));
      const deletedIds = products.filter(p => !idsInNewList.has(p.id)).map(p => p.id);

      setProducts(updatedList);

      if (deletedIds.length > 0) {
          await supabase.from('products').delete().in('id', deletedIds);
      }
      if (updatedList.length > 0) {
          await supabase.from('products').upsert(updatedList);
      }
  };

  const smartUpdateStaff = async (updatedList: Staff[]) => {
      const idsInNewList = new Set(updatedList.map(i => i.id));
      const deletedIds = staff.filter(s => !idsInNewList.has(s.id)).map(s => s.id);

      setStaff(updatedList);

      // Sync with currentUser if the logged-in user is updated
      if (currentUser) {
        const updatedSelf = updatedList.find(s => s.id === currentUser.id);
        if (updatedSelf) {
            // Update state
            setCurrentUser(updatedSelf);
            // Update session storage
            const savedSession = localStorage.getItem('trimtime_session');
            if (savedSession) {
                try {
                    const parsed = JSON.parse(savedSession);
                    localStorage.setItem('trimtime_session', JSON.stringify({ ...parsed, user: updatedSelf }));
                } catch (e) {
                    console.error("Error updating session storage", e);
                }
            }
        }
      }

      if (deletedIds.length > 0) {
          await supabase.from('staff').delete().in('id', deletedIds);
      }
      if (updatedList.length > 0) {
          await supabase.from('staff').upsert(updatedList);
      }
  };

  // Customers: Update, Delete, Insert
  const smartUpdateCustomers = async (updatedList: Customer[]) => {
      const idsInNewList = new Set(updatedList.map(i => i.id));
      const deletedIds = customers.filter(c => !idsInNewList.has(c.id)).map(c => c.id);

      setCustomers(updatedList);

      if (deletedIds.length > 0) {
          await supabase.from('customers').delete().in('id', deletedIds);
      }

      // Map back to snake_case for DB
      const recordsToUpsert = updatedList.map(c => ({
          id: c.id,
          name: c.name,
          phone: c.phone,
          email: c.email,
          notes: c.notes,
          created_at: c.createdAt
      }));

      if (recordsToUpsert.length > 0) {
          await supabase.from('customers').upsert(recordsToUpsert);
      }
  };

  const handleCompleteSale = async (newSale: Sale) => {
      const updatedSales = [...sales, newSale];
      setSales(updatedSales);

      const { error } = await supabase.from('sales').insert({
          id: newSale.id,
          timestamp: newSale.timestamp,
          items: newSale.items, 
          staff_id: newSale.staffId,
          customer_id: newSale.customerId,
          total: newSale.total,
          tax: newSale.tax,
          discount: newSale.discount,
          discount_code: newSale.discountCode,
          payment_method: newSale.paymentMethod,
          tax_type: newSale.taxType
      });

      if (error) console.error("Error saving sale:", error);

      // Update product stock
      newSale.items.forEach(async (item) => {
          if (item.type === 'product') {
              const product = products.find(p => p.id === item.id);
              if (product) {
                  const newStock = product.stock - item.quantity;
                  setProducts(prev => prev.map(p => p.id === product.id ? { ...p, stock: newStock } : p));
                  await supabase.from('products').update({ stock: newStock }).eq('id', product.id);
              }
          }
      });
  };

  // Delete a sale and restore stock
  const handleDeleteSale = async (saleId: string) => {
    const saleToDelete = sales.find(s => s.id === saleId);
    if (!saleToDelete) return;

    // 1. Remove from Sales List
    setSales(prev => prev.filter(s => s.id !== saleId));

    // 2. Remove from DB
    await supabase.from('sales').delete().eq('id', saleId);

    // 3. Restore Stock for products involved
    let productsUpdated = false;
    const updatedProductList = [...products];

    saleToDelete.items.forEach(item => {
        if (item.type === 'product') {
            const productIndex = updatedProductList.findIndex(p => p.id === item.id);
            if (productIndex > -1) {
                updatedProductList[productIndex] = {
                    ...updatedProductList[productIndex],
                    stock: updatedProductList[productIndex].stock + item.quantity
                };
                productsUpdated = true;
            }
        }
    });

    if (productsUpdated) {
        setProducts(updatedProductList);
        await smartUpdateProducts(updatedProductList);
    }
  };

  // Bulk Delete Sales and Restore Stock
  const handleBulkDeleteSales = async (saleIds: string[]) => {
    const salesToDelete = sales.filter(s => saleIds.includes(s.id));
    if (salesToDelete.length === 0) return;

    // 1. Remove from Sales List
    setSales(prev => prev.filter(s => !saleIds.includes(s.id)));

    // 2. Remove from DB
    await supabase.from('sales').delete().in('id', saleIds);

    // 3. Restore Stock
    const updatedProductList = [...products];
    let productsUpdated = false;

    salesToDelete.forEach(sale => {
        sale.items.forEach(item => {
            if (item.type === 'product') {
                const productIndex = updatedProductList.findIndex(p => p.id === item.id);
                if (productIndex > -1) {
                    updatedProductList[productIndex] = {
                        ...updatedProductList[productIndex],
                        stock: updatedProductList[productIndex].stock + item.quantity
                    };
                    productsUpdated = true;
                }
            }
        });
    });

    if (productsUpdated) {
        setProducts(updatedProductList);
        await smartUpdateProducts(updatedProductList);
    }
  };

  // Danger: Wipe all sales
  const handlePurgeSales = async () => {
    setSales([]);
    const { error } = await supabase.from('sales').delete().neq('id', '0'); // Delete all rows
    if (error) console.error("Error purging sales:", error);
  };

  // Helper used by POS to quickly add customer without full list
  const handleAddCustomer = (newCustomer: Customer) => {
     smartUpdateCustomers([...customers, newCustomer]);
  };

  const handleAddExpense = async (newExpense: Expense) => {
      setExpenses([...expenses, newExpense]);
      await supabase.from('expenses').insert(newExpense);
  };

  const handleDeleteExpense = async (id: string) => {
      setExpenses(expenses.filter(e => e.id !== id));
      await supabase.from('expenses').delete().eq('id', id);
  };

  const handleUpdateSettings = async (newSettings: ShopSettings) => {
      setSettings(newSettings);
      await supabase.from('settings').upsert({ id: 1, data: newSettings });
  };


  // Dark Mode Effect
  useEffect(() => {
    if (isDarkMode) {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
    localStorage.setItem('trimtime_theme', isDarkMode ? 'dark' : 'light');
  }, [isDarkMode]);

  const toggleTheme = () => setIsDarkMode(!isDarkMode);

  // Dynamic Branding Effect (Title & Favicon)
  useEffect(() => {
    // 1. Update Document Title
    document.title = `${settings.shopName} | POS Manager`;

    // 2. Update Favicon with dynamic SVG based on first letter
    const updateFavicon = () => {
      const letter = (settings.shopName.charAt(0) || 'T').toUpperCase();
      const svg = `
        <svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 100 100'>
          <rect width='100' height='100' rx='25' fill='%23f59e0b'/>
          <text x='50' y='72' font-family='serif' font-weight='bold' font-size='65' text-anchor='middle' fill='white'>${letter}</text>
        </svg>
      `;

      let link = document.querySelector("link[rel~='icon']") as HTMLLinkElement;
      if (!link) {
        link = document.createElement('link');
        link.rel = 'icon';
        document.head.appendChild(link);
      }
      link.href = `data:image/svg+xml,${encodeURIComponent(svg)}`;
    };

    updateFavicon();
  }, [settings.shopName]);

  // Check for session expiry
  useEffect(() => {
    const checkSession = () => {
      const saved = localStorage.getItem('trimtime_session');
      if (saved) {
        try {
          const parsed = JSON.parse(saved);
          if (parsed.expiry && Date.now() > parsed.expiry) {
            handleLogout();
          }
        } catch (e) {
          // invalid session
        }
      }
    };
    checkSession();
    const interval = setInterval(checkSession, 60000); 
    return () => clearInterval(interval);
  }, []);

  const handleLogin = (user: Staff, rememberMe: boolean) => {
    const sessionDuration = rememberMe ? 30 * 24 * 60 * 60 * 1000 : 60 * 60 * 1000;
    const expiry = Date.now() + sessionDuration;
    localStorage.setItem('trimtime_session', JSON.stringify({ user, expiry }));
    setCurrentUser(user);

    // Employee Role Redirect Logic
    if (user.role === 'employee') {
      setCurrentView(View.POS);
    } else {
      setCurrentView(View.DASHBOARD);
    }
  };

  const handleLogout = () => {
    localStorage.removeItem('trimtime_session');
    setCurrentUser(null);
    setCurrentView(View.DASHBOARD);
  };

  const openProfile = () => {
    if (currentUser) {
      setProfileForm({
        name: currentUser.name,
        username: currentUser.username,
        email: currentUser.email || '',
        password: currentUser.password || ''
      });
      setIsProfileOpen(true);
    }
  };

  const updateProfile = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!currentUser) return;

    const updatedUser: Staff = {
      ...currentUser,
      name: profileForm.name,
      username: profileForm.username,
      email: profileForm.email,
      password: profileForm.password
    };

    const updatedStaffList = staff.map(s => s.id === currentUser.id ? updatedUser : s);
    setStaff(updatedStaffList);
    setCurrentUser(updatedUser);

    await supabase.from('staff').update({
        name: updatedUser.name,
        username: updatedUser.username,
        email: updatedUser.email,
        password: updatedUser.password
    }).eq('id', currentUser.id);

    const savedSession = localStorage.getItem('trimtime_session');
    if (savedSession) {
      const parsed = JSON.parse(savedSession);
      localStorage.setItem('trimtime_session', JSON.stringify({ ...parsed, user: updatedUser }));
    }

    setIsProfileOpen(false);
    alert('Profile updated successfully.');
  };

  const handleLanguageSwitch = (lang: Language) => {
    setSessionLanguage(lang);
    localStorage.setItem('trimtime_lang', lang);
  };

  // Update DOM when session language changes
  useEffect(() => {
    document.documentElement.lang = sessionLanguage;
    document.dir = sessionLanguage === 'ur' || sessionLanguage === 'fa' ? 'rtl' : 'ltr';
  }, [sessionLanguage]);

  if (loading) {
      return (
          <div className="flex h-screen items-center justify-center bg-slate-50 dark:bg-slate-950">
              <div className="animate-spin rounded-full h-12 w-12 border-t-2 border-b-2 border-amber-500"></div>
          </div>
      );
  }

  if (!currentUser) {
    return <Login onLogin={handleLogin} staffList={staff} shopName={settings.shopName} />;
  }

  return (
    <div className="flex h-screen bg-slate-50 dark:bg-slate-950 overflow-hidden relative transition-colors duration-300">
      <Sidebar 
        currentView={currentView}
        onViewChange={setCurrentView}
        shopName={settings.shopName}
        userRole={currentUser.role}
        isOpen={isSidebarOpen}
        onClose={() => setIsSidebarOpen(false)}
        language={sessionLanguage}
        onLanguageChange={handleLanguageSwitch}
      />

      <main className="flex-1 flex flex-col h-full relative md:pl-64 transition-all duration-300">
        {/* Mobile Header */}
        <div className="md:hidden flex items-center justify-between p-4 bg-white dark:bg-slate-900 border-b border-slate-100 dark:border-slate-800 z-50">
          <div className="flex items-center gap-3">
             <div className="w-8 h-8 bg-gradient-to-br from-amber-400 to-amber-600 rounded-lg flex items-center justify-center font-brand text-xl text-slate-950 shadow-lg">
                {settings.shopName.charAt(0)}
             </div>
             <span className="font-bold text-slate-900 dark:text-white truncate max-w-[150px]">{settings.shopName}</span>
          </div>
          <div className="flex items-center gap-2">
            <button 
              onClick={() => handleLanguageSwitch(sessionLanguage === 'en' ? 'ur' : sessionLanguage === 'ur' ? 'fa' : 'en')}
              className="p-2 text-slate-500 dark:text-slate-400 bg-slate-100 dark:bg-slate-800 rounded-lg font-black text-xs uppercase"
            >
              {sessionLanguage}
            </button>
            <button 
              onClick={toggleTheme}
              className="p-2 text-slate-500 dark:text-slate-400 bg-slate-100 dark:bg-slate-800 rounded-lg"
            >
              {isDarkMode ? (
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 3v1m0 16v1m9-9h-1M4 12H3m15.364 6.364l-.707-.707M6.343 6.343l-.707-.707m12.728 0l-.707.707M6.343 17.657l-.707.707M16 12a4 4 0 11-8 0 4 4 0 018 0z"/></svg>
              ) : (
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M20.354 15.354A9 9 0 018.646 3.646 9.003 9.003 0 0012 21a9.003 9.003 0 008.354-5.646z"/></svg>
              )}
            </button>
            <button onClick={() => setIsSidebarOpen(true)} className="p-2 text-slate-500">
              <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 6h16M4 12h16m-7 6h7"/></svg>
            </button>
          </div>
        </div>

        {/* Top Bar (Desktop) */}
        <div className="hidden md:flex justify-between items-center py-6 px-8 no-print">
            <h1 className="text-2xl font-black text-slate-900 dark:text-white font-brand tracking-tight">
               {currentView === View.DASHBOARD && (sessionLanguage === 'en' ? 'Dashboard' : sessionLanguage === 'ur' ? 'ڈیش بورڈ' : 'داشبورد')}
               {currentView === View.POS && (sessionLanguage === 'en' ? 'Point of Sale' : sessionLanguage === 'ur' ? 'پوائنٹ آف سیل' : 'پایانه فروش')}
               {currentView === View.INVENTORY && (sessionLanguage === 'en' ? 'Inventory Management' : sessionLanguage === 'ur' ? 'انوینٹری' : 'مدیریت موجودی')}
               {currentView === View.CUSTOMERS && (sessionLanguage === 'en' ? 'Client Directory' : sessionLanguage === 'ur' ? 'صارفین کی فہرست' : 'فهرست مشتریان')}
               {currentView === View.FINANCE && (sessionLanguage === 'en' ? 'Financial Overview' : sessionLanguage === 'ur' ? 'مالیاتی جائزہ' : 'بررسی مالی')}
               {currentView === View.STAFF && (sessionLanguage === 'en' ? 'Team Management' : sessionLanguage === 'ur' ? 'ٹیم مینجمنٹ' : 'مدیریت تیم')}
               {currentView === View.SETTINGS && (sessionLanguage === 'en' ? 'Configuration' : sessionLanguage === 'ur' ? 'ترتیبات' : 'پیکربندی')}
            </h1>
            <div className="flex items-center gap-4">

               {/* Language Switcher */}
               <div className="relative group">
                 <button className="flex items-center gap-2 bg-white dark:bg-slate-900 text-slate-600 dark:text-slate-300 p-2.5 rounded-xl border border-slate-200 dark:border-slate-800 transition-colors shadow-sm font-bold text-xs uppercase">
                    <span>{sessionLanguage === 'en' ? '🇺🇸 EN' : sessionLanguage === 'ur' ? '🇵🇰 UR' : '🇮🇷 FA'}</span>
                    <svg className="w-3 h-3 text-slate-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 9l-7 7-7-7" /></svg>
                 </button>
                 <div className="absolute top-full right-0 mt-2 w-32 bg-white dark:bg-slate-900 border border-slate-100 dark:border-slate-800 rounded-xl shadow-xl overflow-hidden hidden group-hover:block z-50">
                    <button onClick={() => handleLanguageSwitch('en')} className="w-full text-left px-4 py-3 hover:bg-slate-50 dark:hover:bg-slate-800 text-xs font-bold text-slate-600 dark:text-slate-300 flex justify-between">
                       English <span>🇺🇸</span>
                    </button>
                    <button onClick={() => handleLanguageSwitch('ur')} className="w-full text-left px-4 py-3 hover:bg-slate-50 dark:hover:bg-slate-800 text-xs font-bold text-slate-600 dark:text-slate-300 flex justify-between">
                       Urdu <span>🇵🇰</span>
                    </button>
                    <button onClick={() => handleLanguageSwitch('fa')} className="w-full text-left px-4 py-3 hover:bg-slate-50 dark:hover:bg-slate-800 text-xs font-bold text-slate-600 dark:text-slate-300 flex justify-between">
                       Persian <span>🇮🇷</span>
                    </button>
                 </div>
               </div>

               <button 
                onClick={toggleTheme}
                className="bg-white dark:bg-slate-900 text-slate-400 dark:text-slate-500 hover:text-amber-500 dark:hover:text-amber-400 p-2.5 rounded-xl border border-slate-200 dark:border-slate-800 transition-colors shadow-sm"
                title={isDarkMode ? "Switch to Light Mode" : "Switch to Dark Mode"}
               >
                 {isDarkMode ? (
                   <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 3v1m0 16v1m9-9h-1M4 12H3m15.364 6.364l-.707-.707M6.343 6.343l-.707-.707m12.728 0l-.707.707M6.343 17.657l-.707.707M16 12a4 4 0 11-8 0 4 4 0 018 0z"/></svg>
                 ) : (
                   <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M20.354 15.354A9 9 0 018.646 3.646 9.003 9.003 0 0012 21a9.003 9.003 0 008.354-5.646z"/></svg>
                 )}
               </button>

               <div 
                  onClick={openProfile}
                  className="flex items-center gap-3 cursor-pointer hover:bg-slate-200 dark:hover:bg-slate-800/50 p-2 rounded-xl transition-colors -mr-2"
                  title="Edit Profile"
               >
                 <div className="flex flex-col items-end">
                    <span className="font-bold text-sm text-slate-900 dark:text-white">{currentUser.name}</span>
                    <span className="text-[10px] font-black uppercase text-slate-400 dark:text-slate-500 tracking-widest">{currentUser.role}</span>
                 </div>
                 <div className="w-10 h-10 rounded-full bg-slate-200 dark:bg-slate-800 flex items-center justify-center text-slate-500 dark:text-slate-400 font-black shadow-inner">
                    {currentUser.name.charAt(0)}
                 </div>
               </div>
               <button 
                onClick={handleLogout}
                className="bg-slate-100 dark:bg-slate-800 text-slate-500 dark:text-slate-400 hover:text-rose-500 dark:hover:text-rose-500 p-2.5 rounded-xl transition-colors"
                title="Logout"
               >
                 <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M17 16l4-4m0 0l-4-4m4 4H7m6 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h4a3 3 0 013 3v1"/></svg>
               </button>
            </div>
        </div>

        <div className="flex-1 overflow-y-auto overflow-x-hidden p-4 md:p-8 scroll-smooth" id="main-content">
          <AnimatePresence mode='wait'>
            <motion.div
              key={currentView}
              initial={{ opacity: 0, y: 10 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0, y: -10 }}
              transition={{ duration: 0.2 }}
              className="h-full"
            >
              {currentView === View.DASHBOARD && <Dashboard sales={sales} expenses={expenses} currency={settings.currency} language={sessionLanguage} />}
              {currentView === View.POS && (
                <POS 
                  services={services} 
                  products={products} 
                  staff={staff} 
                  customers={customers}
                  settings={settings}
                  currentUser={currentUser}
                  onCompleteSale={handleCompleteSale}
                  onAddCustomer={handleAddCustomer}
                />
              )}
              {currentView === View.FINANCE && (
                <Finance 
                  sales={sales} 
                  expenses={expenses} 
                  staffList={staff}
                  onAddExpense={handleAddExpense}
                  onDeleteExpense={handleDeleteExpense}
                  onDeleteSale={handleDeleteSale}
                  onDeleteSales={handleBulkDeleteSales}
                  currentUser={currentUser}
                  customers={customers}
                  currency={settings.currency}
                  language={sessionLanguage}
                  billingCycleDay={settings.billingCycleDay || 1}
                />
              )}
              {currentView === View.CUSTOMERS && (
                <Customers 
                  customers={customers} 
                  sales={sales} 
                  onUpdateCustomers={smartUpdateCustomers}
                  currency={settings.currency}
                  language={sessionLanguage}
                />
              )}
              {currentView === View.INVENTORY && (
                <Inventory 
                  services={services} 
                  products={products} 
                  settings={{...settings, language: sessionLanguage}}
                  onUpdateServices={smartUpdateServices}
                  onUpdateProducts={smartUpdateProducts}
                />
              )}
              {currentView === View.STAFF && (
                <StaffManagement 
                  staffList={staff} 
                  onUpdateStaff={smartUpdateStaff} 
                  currentUser={currentUser}
                  language={sessionLanguage}
                />
              )}
              {currentView === View.SETTINGS && (
                <Settings 
                  settings={{...settings, language: sessionLanguage}} 
                  onUpdateSettings={handleUpdateSettings} 
                  currentUser={currentUser}
                  onPurgeSales={handlePurgeSales}
                />
              )}
            </motion.div>
          </AnimatePresence>
        </div>
      </main>

      {/* Profile Modal */}
      <AnimatePresence>
        {isProfileOpen && (
          <div className="fixed inset-0 bg-slate-950/40 backdrop-blur-sm z-[100] flex items-center justify-center p-4">
            <motion.div 
              initial={{ scale: 0.9, opacity: 0 }}
              animate={{ scale: 1, opacity: 1 }}
              exit={{ scale: 0.9, opacity: 0 }}
              className="bg-white dark:bg-slate-900 w-full max-w-md rounded-[2.5rem] p-8 shadow-2xl border border-slate-100 dark:border-slate-800"
            >
              <div className="flex justify-between items-center mb-8">
                <h3 className="text-2xl font-black text-slate-900 dark:text-white tracking-tight">My Profile</h3>
                <button onClick={() => setIsProfileOpen(false)} className="p-2 bg-slate-50 dark:bg-slate-800 rounded-full text-slate-400">
                  <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M6 18L18 6M6 6l12 12"/></svg>
                </button>
              </div>
              <form onSubmit={updateProfile} className="space-y-5">
                <div className="flex justify-center mb-6">
                   <div className="w-24 h-24 rounded-full bg-slate-100 dark:bg-slate-800 flex items-center justify-center text-4xl font-black text-slate-500 dark:text-slate-400 uppercase shadow-inner">
                      {currentUser?.name.charAt(0)}
                   </div>
                </div>
                <div>
                  <label className="text-[10px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest block mb-2 ml-1">Full Name</label>
                  <input 
                    type="text" 
                    value={profileForm.name} 
                    onChange={e => setProfileForm({...profileForm, name: e.target.value})} 
                    required 
                    className="w-full bg-slate-50 dark:bg-slate-800 border-0 rounded-2xl px-5 py-3.5 focus:ring-4 focus:ring-amber-500/10 outline-none text-sm font-bold dark:text-slate-200" 
                  />
                </div>
                <div>
                  <label className="text-[10px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest block mb-2 ml-1">Email</label>
                  <input 
                    type="email" 
                    value={profileForm.email} 
                    onChange={e => setProfileForm({...profileForm, email: e.target.value})} 
                    className="w-full bg-slate-50 dark:bg-slate-800 border-0 rounded-2xl px-5 py-3.5 focus:ring-4 focus:ring-amber-500/10 outline-none text-sm font-bold dark:text-slate-200" 
                  />
                </div>
                <div>
                  <label className="text-[10px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest block mb-2 ml-1">Username (Login ID)</label>
                  <input 
                    type="text" 
                    value={profileForm.username} 
                    onChange={e => setProfileForm({...profileForm, username: e.target.value})} 
                    required 
                    className="w-full bg-slate-50 dark:bg-slate-800 border-0 rounded-2xl px-5 py-3.5 focus:ring-4 focus:ring-amber-500/10 outline-none text-sm font-bold dark:text-slate-200" 
                  />
                </div>
                <div>
                  <label className="text-[10px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest block mb-2 ml-1">Password</label>
                  <div className="relative">
                    <input 
                      type={showProfilePassword ? "text" : "password"} 
                      value={profileForm.password} 
                      onChange={e => setProfileForm({...profileForm, password: e.target.value})} 
                      required 
                      className="w-full bg-slate-50 dark:bg-slate-800 border-0 rounded-2xl px-5 py-3.5 pr-12 focus:ring-4 focus:ring-amber-500/10 outline-none text-sm font-bold dark:text-slate-200" 
                    />
                    <button
                      type="button"
                      onClick={() => setShowProfilePassword(!showProfilePassword)}
                      className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-400 hover:text-slate-600 transition-colors"
                    >
                      {showProfilePassword ? (
                        <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z"/><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z"/></svg>
                      ) : (
                        <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13.875 18.825A10.05 10.05 0 0112 19c-4.478 0-8.268-2.943-9.543-7a9.97 9.97 0 011.563-3.029m5.858.908a3 3 0 114.243 4.243M9.878 9.878l4.242 4.242M9.88 9.88l-3.29-3.29m7.532 7.532l3.29 3.29M3 3l18 18"/></svg>
                      )}
                    </button>
                  </div>
                </div>
                <div className="flex gap-4 mt-8">
                  <button type="submit" className="flex-1 px-4 py-4 bg-slate-950 dark:bg-amber-500 text-white dark:text-slate-950 rounded-2xl font-black text-base hover:bg-slate-800 dark:hover:bg-amber-600 transition-all shadow-xl">
                    Save Changes
                  </button>
                </div>
              </form>
            </motion.div>
          </div>
        )}
      </AnimatePresence>
    </div>
  );
};

export default App;

import React, { useState, useMemo, useEffect, useRef } from 'react';
import { Service, Product, Staff, Sale, SaleItem, Customer, ShopSettings, HeldSale } from '../types';
import { INITIAL_DISCOUNT_CODES, TRANSLATIONS } from '../constants';
import { jsPDF } from 'jspdf';
import { motion, AnimatePresence } from 'framer-motion';
import { Html5Qrcode } from 'html5-qrcode';

interface POSProps {
  services: Service[];
  products: Product[];
  staff: Staff[];
  customers: Customer[];
  settings: ShopSettings;
  currentUser: Staff;
  onCompleteSale: (sale: Sale) => void;
  onAddCustomer: (customer: Customer) => void;
}

const POS: React.FC<POSProps> = ({ services, products, staff, customers, settings, currentUser, onCompleteSale, onAddCustomer }) => {
  const [cart, setCart] = useState<SaleItem[]>([]);
  const [selectedStaff, setSelectedStaff] = useState<string>(currentUser.role === 'employee' ? currentUser.id : '');
  const [selectedCustomer, setSelectedCustomer] = useState<string>('');
  const [discountCode, setDiscountCode] = useState<string>('');
  const [activeTab, setActiveTab] = useState<'services' | 'products'>('services');
  const [searchTerm, setSearchTerm] = useState('');
  const [heldSales, setHeldSales] = useState<HeldSale[]>([]);
  const [lastSale, setLastSale] = useState<Sale | null>(null);
  const [autoWhatsapp, setAutoWhatsapp] = useState(false);

  const [scanningFeedback, setScanningFeedback] = useState<string | null>(null);
  const [feedbackType, setFeedbackType] = useState<'success' | 'error'>('success');

  const [showMobileCart, setShowMobileCart] = useState(false);
  const [isAddingCustomer, setIsAddingCustomer] = useState(false);
  const [newCustomerData, setNewCustomerData] = useState({ name: '', phone: '', email: '' });
  const [isScanning, setIsScanning] = useState(false);

  const feedbackTimeoutRef = useRef<number | null>(null);
  const html5QrCodeRef = useRef<Html5Qrcode | null>(null);
  const isScannerActiveRef = useRef(false);
  const processingScanRef = useRef(false);

  const t = TRANSLATIONS[settings.language];

  // Helper to get Customer Details for last sale or active cart
  const activeCustomer = useMemo(() => customers.find(c => c.id === selectedCustomer), [selectedCustomer, customers]);
  const lastCustomer = useMemo(() => lastSale?.customerId ? customers.find(c => c.id === lastSale.customerId) : null, [lastSale, customers]);

  // WhatsApp Message Generator
  const sendWhatsappReceipt = (sale: Sale, customer: Customer) => {
    if (!customer.phone) return;

    const itemsList = sale.items.map(i => `• *${i.name}* (${settings.currency}${i.price} x ${i.quantity})`).join('%0A');
    const message = `✨ *${settings.shopName} Receipt* ✨%0A%0A` +
      `👤 *Customer:* ${customer.name}%0A` +
      `📅 *Date:* ${new Date(sale.timestamp).toLocaleDateString()}%0A` +
      `🧾 *ID:* #${sale.id.slice(0, 8)}%0A` +
      `--------------------------%0A` +
      `${itemsList}%0A` +
      `--------------------------%0A` +
      `💰 *Total:* ${settings.currency}${sale.total.toFixed(2)}%0A` +
      `💳 *Method:* ${sale.paymentMethod.toUpperCase()}%0A%0A` +
      `${settings.receiptFooter}%0A%0A` +
      `_Thank you for your visit!_`;

    const cleanPhone = customer.phone.replace(/\D/g, '');
    window.open(`https://wa.me/${cleanPhone}?text=${message}`, '_blank');
  };

  useEffect(() => {
    let isMounted = true;
    if (isScanning) {
        const startScanner = async () => {
            await new Promise(resolve => setTimeout(resolve, 300));
            if (!isMounted || !isScanning) return;
            if (html5QrCodeRef.current) return;
            try {
                const html5QrCode = new Html5Qrcode("reader");
                html5QrCodeRef.current = html5QrCode;
                await html5QrCode.start(
                    { facingMode: "environment" }, 
                    { fps: 10, qrbox: { width: 250, height: 150 }, aspectRatio: 1.0 }, 
                    (decodedText) => { if (isMounted) handleScan(decodedText); },
                    (errorMessage) => {}
                );
                if (isMounted) isScannerActiveRef.current = true;
            } catch (err: any) {
                if (isMounted) setIsScanning(false);
                html5QrCodeRef.current = null;
                isScannerActiveRef.current = false;
            }
        };
        startScanner();
    }
    return () => {
        isMounted = false;
        if (html5QrCodeRef.current) {
            const scanner = html5QrCodeRef.current;
            html5QrCodeRef.current = null;
            if (isScannerActiveRef.current) {
                scanner.stop().catch(() => {}).finally(() => {
                    try { scanner.clear(); } catch(e) {}
                    isScannerActiveRef.current = false;
                });
            } else {
                try { scanner.clear(); } catch(e) {}
            }
        }
    };
  }, [isScanning]);

  const handleScan = (barcode: string) => {
    if (processingScanRef.current) return;
    processingScanRef.current = true;
    setTimeout(() => { processingScanRef.current = false; }, 1500);
    const product = products.find(p => p.barcode === barcode);
    if (product) {
        addToCart(product, 'product');
        setScanningFeedback(product.name);
        setFeedbackType('success');
    } else {
        setScanningFeedback(`Not Found: ${barcode}`);
        setFeedbackType('error');
    }
    if (feedbackTimeoutRef.current) window.clearTimeout(feedbackTimeoutRef.current);
    feedbackTimeoutRef.current = window.setTimeout(() => { setScanningFeedback(null); }, 2500);
  };

  const toggleScanner = () => setIsScanning(!isScanning);

  const addToCart = (item: Service | Product, type: 'service' | 'product') => {
    setCart(prev => {
      const existing = prev.find(i => i.id === item.id && i.type === type);
      if (existing) {
        return prev.map(i => i.id === item.id && i.type === type ? { ...i, quantity: i.quantity + 1 } : i);
      }
      return [...prev, { id: item.id, name: item.name, price: item.price, type, quantity: 1 }];
    });
  };

  const updateQuantity = (id: string, type: 'service' | 'product', delta: number) => {
    setCart(prev => prev.map(item => {
      if (item.id === id && item.type === type) return { ...item, quantity: Math.max(1, item.quantity + delta) };
      return item;
    }));
  };

  const removeFromCart = (id: string, type: 'service' | 'product') => {
    setCart(prev => prev.filter(i => !(i.id === id && i.type === type)));
  };

  const totals = useMemo(() => {
    const rawSubtotal = cart.reduce((acc, item) => acc + (item.price * item.quantity), 0);
    let discount = 0;
    const code = INITIAL_DISCOUNT_CODES.find(c => c.code === discountCode);
    if (code) discount = code.type === 'percentage' ? (rawSubtotal * code.value) / 100 : code.value;
    const discountedAmount = rawSubtotal - discount;
    let tax = 0;
    let total = 0;
    if (settings.taxType === 'included') {
      total = discountedAmount;
      tax = total - (total / (1 + (settings.taxRate / 100)));
    } else {
      tax = discountedAmount * (settings.taxRate / 100);
      total = discountedAmount + tax;
    }
    return { subtotal: rawSubtotal, discount, tax, total };
  }, [cart, discountCode, settings]);

  const handleHoldSale = () => {
    if (cart.length === 0) return;
    const newHold: HeldSale = {
      id: Math.random().toString(36).substr(2, 9).toUpperCase(),
      timestamp: new Date().toISOString(),
      cart: [...cart],
      customerId: selectedCustomer || undefined,
      staffId: selectedStaff || undefined,
    };
    setHeldSales([newHold, ...heldSales]);
    setCart([]);
    setSelectedCustomer('');
    if (currentUser.role !== 'employee') setSelectedStaff('');
  };

  const retrieveSale = (held: HeldSale) => {
    setCart(held.cart);
    if (held.customerId) setSelectedCustomer(held.customerId);
    if (held.staffId) setSelectedStaff(held.staffId);
    setHeldSales(heldSales.filter(h => h.id !== held.id));
  };

  const generatePDF = (sale: Sale) => {
    const doc = new jsPDF({ unit: 'mm', format: [80, 200] });
    const barber = staff.find(s => s.id === sale.staffId)?.name || 'N/A';
    const client = customers.find(c => c.id === sale.customerId)?.name || 'Guest Walk-in';
    const dateStr = new Date(sale.timestamp).toLocaleString();
    doc.setFillColor(15, 23, 42);
    doc.rect(0, 0, 80, 10, 'F');
    doc.setTextColor(245, 158, 11);
    doc.setFont('helvetica', 'bold').setFontSize(10);
    doc.text('OFFICIAL RECEIPT', 40, 7, { align: 'center' });
    doc.setTextColor(15, 23, 42);
    doc.setFontSize(16).text(settings.shopName.toUpperCase(), 40, 25, { align: 'center' });
    doc.setFontSize(8).setFont('helvetica', 'normal').text('Professional Grooming & Care', 40, 30, { align: 'center' });
    doc.setDrawColor(226, 232, 240);
    doc.setLineWidth(0.3).line(5, 35, 75, 35);
    doc.setFontSize(7).setTextColor(100, 116, 139);
    doc.text(`Transaction ID: #${sale.id}`, 5, 42);
    doc.text(`Date & Time: ${dateStr}`, 5, 46);
    doc.text(`Professional: ${barber}`, 5, 50);
    doc.text(`Client: ${client}`, 5, 54);
    doc.line(5, 58, 75, 58);
    let y = 65;
    doc.setFont('helvetica', 'bold').setFontSize(8).setTextColor(15, 23, 42);
    doc.text('DESCRIPTION', 5, y);
    doc.text('QTY', 52, y);
    doc.text('AMOUNT', 75, y, { align: 'right' });
    doc.line(5, y + 2, 75, y + 2);
    doc.setFont('helvetica', 'normal').setFontSize(7);
    y += 7;
    sale.items.forEach(item => {
      doc.text(item.name.substring(0, 25), 5, y);
      doc.text(item.quantity.toString(), 54, y, { align: 'center' });
      doc.text(`${settings.currency}${(item.price * item.quantity).toFixed(2)}`, 75, y, { align: 'right' });
      y += 5;
    });
    y += 5;
    doc.setDrawColor(15, 23, 42);
    doc.line(5, y, 75, y);
    y += 7;
    const subtotalValue = sale.items.reduce((acc, i) => acc + (i.price * i.quantity), 0);
    doc.setFont('helvetica', 'normal').text('SUBTOTAL:', 5, y);
    doc.text(`${settings.currency}${subtotalValue.toFixed(2)}`, 75, y, { align: 'right' });
    y += 5;
    if (sale.discount > 0) {
      doc.text(`DISCOUNT (${sale.discountCode || 'Applied'}):`, 5, y);
      doc.text(`-${settings.currency}${sale.discount.toFixed(2)}`, 75, y, { align: 'right' });
      y += 5;
    }
    if (sale.taxType === 'excluded') {
      doc.text(`TAX (${settings.taxRate}%):`, 5, y);
      doc.text(`${settings.currency}${sale.tax.toFixed(2)}`, 75, y, { align: 'right' });
      y += 5;
    } else {
      doc.setFontSize(6).setTextColor(148, 163, 184);
      doc.text(`Includes ${settings.taxRate}% tax of ${settings.currency}${sale.tax.toFixed(2)}`, 5, y);
      doc.setFontSize(7).setTextColor(15, 23, 42);
      y += 5;
    }
    y += 2;
    doc.setFillColor(248, 250, 252);
    doc.rect(5, y - 4, 70, 8, 'F');
    doc.setFontSize(10).setFont('helvetica', 'bold').text('TOTAL PAID:', 7, y + 1.5);
    doc.text(`${settings.currency}${sale.total.toFixed(2)}`, 73, y + 1.5, { align: 'right' });
    y += 15;
    doc.setFontSize(7).setFont('helvetica', 'italic').setTextColor(148, 163, 184);
    doc.text(settings.receiptFooter, 40, y, { align: 'center' });
    doc.text('Thank you for your visit!', 40, y + 4, { align: 'center' });
    doc.setFillColor(15, 23, 42);
    doc.rect(0, 195, 80, 5, 'F');
    return doc;
  };

  const handleShareReceipt = async (sale: Sale) => {
    const doc = generatePDF(sale);
    const pdfBlob = doc.output('blob');
    const file = new File([pdfBlob], `Receipt-${sale.id}.pdf`, { type: 'application/pdf' });
    if (navigator.share && navigator.canShare && navigator.canShare({ files: [file] })) {
      try {
        await navigator.share({ files: [file], title: `${settings.shopName} Receipt`, text: `Your receipt for transaction #${sale.id}` });
      } catch (error: any) {
        if (error.name !== 'AbortError' && !error.message.includes('cancellation')) doc.save(`Receipt-${sale.id}.pdf`);
      }
    } else doc.save(`Receipt-${sale.id}.pdf`);
  };

  const handleCheckout = (paymentMethod: 'cash' | 'card') => {
    if (cart.length === 0 || !selectedStaff) {
      alert('Please add items and assign a professional.');
      return;
    }
    const sale: Sale = {
      id: Math.random().toString(36).substr(2, 9).toUpperCase(),
      timestamp: new Date().toISOString(),
      items: [...cart],
      staffId: selectedStaff,
      customerId: selectedCustomer || undefined,
      total: totals.total,
      tax: totals.tax,
      discount: totals.discount,
      discountCode: discountCode || undefined,
      paymentMethod,
      taxType: settings.taxType,
    };

    onCompleteSale(sale);
    setLastSale(sale);

    // Auto-Send Logic
    if (autoWhatsapp && selectedCustomer) {
      const cust = customers.find(c => c.id === selectedCustomer);
      if (cust && cust.phone) {
        setTimeout(() => sendWhatsappReceipt(sale, cust), 1200);
      }
    }

    setCart([]);
    setSelectedCustomer('');
    setDiscountCode('');
    if (currentUser.role !== 'employee') setSelectedStaff('');
    setShowMobileCart(false);
  };

  const handleQuickAddCustomer = () => {
    if (!newCustomerData.name) return;
    const newCust: Customer = {
      id: 'c' + Date.now().toString(36) + Math.random().toString(36).substr(2, 4),
      name: newCustomerData.name,
      phone: newCustomerData.phone,
      email: newCustomerData.email,
      notes: '',
      createdAt: new Date().toISOString().split('T')[0]
    };
    onAddCustomer(newCust);
    setSelectedCustomer(newCust.id);
    setIsAddingCustomer(false);
    setNewCustomerData({ name: '', phone: '', email: '' });
  };

  const filteredItems = useMemo(() => {
    const search = searchTerm.toLowerCase();
    if (activeTab === 'services') return services.filter(s => s.name.toLowerCase().includes(search) || s.category.toLowerCase().includes(search));
    return products.filter(p => p.name.toLowerCase().includes(search));
  }, [activeTab, services, products, searchTerm]);

  return (
    <div className="flex flex-col lg:flex-row gap-6 h-[calc(100vh-12rem)] relative">
      <AnimatePresence>
        {lastSale && (
          <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="fixed inset-0 bg-slate-950/80 backdrop-blur-xl z-[150] flex items-center justify-center p-6 no-print">
            <motion.div initial={{ scale: 0.8, opacity: 0, y: 20 }} animate={{ scale: 1, opacity: 1, y: 0 }} className="bg-white dark:bg-slate-900 rounded-[3rem] p-10 max-w-md w-full shadow-2xl text-center space-y-8">
              <div className="w-20 h-20 bg-emerald-50 dark:bg-emerald-900/20 text-emerald-500 rounded-full flex items-center justify-center text-4xl mx-auto shadow-inner">✓</div>
              <div className="space-y-2">
                <h3 className="text-3xl font-black text-slate-900 dark:text-white tracking-tight">{t.saleSuccess}</h3>
                <p className="text-slate-400 dark:text-slate-500 font-medium">{t.orderCompleted}</p>
              </div>
              <div className="flex flex-col gap-3">
                {lastCustomer && lastCustomer.phone && (
                  <button onClick={() => sendWhatsappReceipt(lastSale, lastCustomer)} className="w-full bg-emerald-500 text-white py-4 rounded-2xl font-black flex items-center justify-center gap-3 hover:bg-emerald-600 transition-all shadow-xl shadow-emerald-500/20 active:scale-95">
