import React, { useState, useMemo } from 'react';
import { Sale, Expense, Staff, Language, Customer } from '../types';
import { getFinancialInsights } from '../services/geminiService';
import { TRANSLATIONS } from '../constants';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer } from 'recharts';
import { motion, AnimatePresence } from 'framer-motion';

interface FinanceProps {
  sales: Sale[];
  expenses: Expense[];
  staffList: Staff[];
  onAddExpense: (expense: Expense) => void;
  onDeleteExpense?: (id: string) => void;
  onDeleteSale?: (id: string) => void;
  onDeleteSales?: (ids: string[]) => void;
  currentUser: Staff;
  customers: Customer[];
  currency: string;
  language: Language;
  billingCycleDay?: number;
}

const Finance: React.FC<FinanceProps> = ({ sales, expenses, staffList, onAddExpense, onDeleteExpense, onDeleteSale, onDeleteSales, currentUser, customers, currency, language, billingCycleDay = 1 }) => {
  const [activeTab, setActiveTab] = useState<'overview' | 'transactions' | 'expenses'>('overview');
  const [loadingInsights, setLoadingInsights] = useState(false);
  const [insights, setInsights] = useState<string | null>(null);
  const [newExpense, setNewExpense] = useState({ category: '', amount: 0, description: '' });
  const [transactionSearch, setTransactionSearch] = useState('');
  const [viewingSale, setViewingSale] = useState<Sale | null>(null);
  const [selectedTransactions, setSelectedTransactions] = useState<Set<string>>(new Set());

  const t = TRANSLATIONS[language];

  const [startDate, setStartDate] = useState(() => {
    const today = new Date();
    const currentDay = today.getDate();
    let start = new Date(today.getFullYear(), today.getMonth(), billingCycleDay);
    if (currentDay < billingCycleDay) start = new Date(today.getFullYear(), today.getMonth() - 1, billingCycleDay);
    return start.toISOString().split('T')[0];
  });

  const [endDate, setEndDate] = useState(() => new Date().toISOString().split('T')[0]);

  const totalRevenue = useMemo(() => sales.reduce((acc, s) => acc + s.total, 0), [sales]);
  const totalExpenses = useMemo(() => expenses.reduce((acc, e) => acc + e.amount, 0), [expenses]);
  const profit = totalRevenue - totalExpenses;

  const reportData = useMemo(() => {
    const filteredSales = sales.filter(s => {
      const date = s.timestamp.split('T')[0];
      return date >= startDate && date <= endDate;
    });

    const staffStats = staffList.map(staff => {
      const personalSales = filteredSales.filter(s => s.staffId === staff.id);
      const revenue = personalSales.reduce((acc, s) => acc + s.total, 0);
      const commissionEarned = (revenue * staff.commission) / 100;
      return { ...staff, salesCount: personalSales.length, revenue, commissionEarned };
    }).sort((a, b) => b.revenue - a.revenue);

    const periodRevenue = filteredSales.reduce((acc, s) => acc + s.total, 0);
    const periodCommission = staffStats.reduce((acc, s) => acc + s.commissionEarned, 0);

    return { staffStats, periodRevenue, periodCommission, salesCount: filteredSales.length };
  }, [sales, staffList, startDate, endDate]);

  const filteredTransactions = useMemo(() => {
    const term = transactionSearch.toLowerCase();
    return sales.filter(s => {
      const customerName = customers.find(c => c.id === s.customerId)?.name.toLowerCase() || '';
      const staffName = staffList.find(st => st.id === s.staffId)?.name.toLowerCase() || '';
      return s.id.toLowerCase().includes(term) || customerName.includes(term) || staffName.includes(term);
    }).sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime());
  }, [sales, transactionSearch, customers, staffList]);

  const handleGenerateInsights = async () => {
    setLoadingInsights(true);
    const result = await getFinancialInsights(sales, expenses);
    setInsights(result);
    setLoadingInsights(false);
