            <div className="xl:col-span-2 bg-slate-900 text-white p-8 rounded-[2.5rem] border border-slate-800">
               <div className="flex justify-between items-center mb-6">
                 <h3 className="text-xl font-bold">✨ {t.smartInsights}</h3>
                 <button onClick={handleGenerateInsights} disabled={loadingInsights} className="bg-amber-500 text-slate-950 px-6 py-2 rounded-xl font-black text-sm">{loadingInsights ? t.analyzing : t.generateAdvice}</button>
               </div>
               <div className="bg-white/5 p-6 rounded-2xl min-h-[120px] text-slate-300 text-sm italic">{insights || t.aiPrompt}</div>
            </div>
          </motion.div>
        )}

        {activeTab === 'transactions' && (
          <motion.div key="transactions" initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: -10 }} className="bg-white dark:bg-slate-900 rounded-[2.5rem] border border-slate-100 dark:border-slate-800 shadow-sm overflow-hidden">
             <div className="p-6 border-b border-slate-50 dark:border-slate-800 flex justify-between items-center">
                {selectedTransactions.size > 0 ? (
                  <div className="flex items-center gap-4">
                    <span className="bg-slate-950 text-white px-3 py-1 rounded-lg text-xs font-bold">{selectedTransactions.size} Selected</span>
                    {currentUser.role === 'admin' && (
                      <button onClick={handleBulkDelete} className="bg-rose-500 text-white px-4 py-2 rounded-xl text-xs font-bold uppercase">Delete</button>
                    )}
                    <button onClick={() => downloadReport('custom')} className="bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-400 px-4 py-2 rounded-xl text-xs font-bold uppercase">Export CSV</button>
                  </div>
                ) : (
                  <div className="flex items-center gap-4">
                    <input type="text" placeholder="Search history..." value={transactionSearch} onChange={e => setTransactionSearch(e.target.value)} className="bg-slate-50 dark:bg-slate-800 border-none rounded-xl px-4 py-2 text-sm w-64 focus:ring-2 focus:ring-amber-500/20" />
                  </div>
                )}
             </div>
             <div className="overflow-x-auto">
               <table className="w-full text-left">
                  <thead className="bg-slate-50 dark:bg-slate-800/50 text-[10px] font-black text-slate-400 uppercase tracking-widest">
                    <tr>
                      <th className="px-6 py-4 w-12"><input type="checkbox" checked={selectedTransactions.size === filteredTransactions.length && filteredTransactions.length > 0} onChange={toggleSelectAll} className="rounded border-slate-300 text-amber-500 focus:ring-amber-500" /></th>
                      <th className="px-6 py-4">Date</th>
                      <th className="px-6 py-4">Professional</th>
                      <th className="px-6 py-4">Client</th>
                      <th className="px-6 py-4 text-right">Total</th>
                      <th className="px-6 py-4 text-center">Action</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-50 dark:divide-slate-800">
                    {filteredTransactions.map(sale => (
                      <tr key={sale.id} className={`hover:bg-slate-50/50 dark:hover:bg-slate-800/50 transition-colors ${selectedTransactions.has(sale.id) ? 'bg-amber-50 dark:bg-amber-900/10' : ''}`}>
                        <td className="px-6 py-4"><input type="checkbox" checked={selectedTransactions.has(sale.id)} onChange={() => toggleSelection(sale.id)} className="rounded border-slate-300 text-amber-500 focus:ring-amber-500" /></td>
                        <td className="px-6 py-4 text-xs font-bold text-slate-600 dark:text-slate-400">{new Date(sale.timestamp).toLocaleDateString()}</td>
                        <td className="px-6 py-4 text-xs font-bold">{staffList.find(s => s.id === sale.staffId)?.name || 'N/A'}</td>
                        <td className="px-6 py-4 text-xs font-bold">{customers.find(c => c.id === sale.customerId)?.name || 'Walk-in'}</td>
                        <td className="px-6 py-4 text-right font-black">{currency}{sale.total.toFixed(2)}</td>
                        <td className="px-6 py-4 text-center"><button onClick={() => setViewingSale(sale)} className="text-amber-500 font-black text-[10px] uppercase hover:underline">View</button></td>
                      </tr>
                    ))}
                  </tbody>
               </table>
             </div>
          </motion.div>
        )}

        {activeTab === 'expenses' && (
           <motion.div key="expenses" initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: -10 }} className="space-y-6">
              <div className="bg-white dark:bg-slate-900 p-8 rounded-[2.5rem] border border-slate-100 dark:border-slate-800 shadow-sm">
                <h3 className="text-xl font-bold text-slate-800 dark:text-white mb-6">{t.newExpense}</h3>
                <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
                  <input 
                    type="text" 
                    placeholder={t.category} 
                    value={newExpense.category} 
                    onChange={e => setNewExpense({...newExpense, category: e.target.value})}
                    className="bg-slate-50 dark:bg-slate-800 border-none rounded-xl px-4 py-3 text-sm font-bold dark:text-white"
                  />
                  <input 
                    type="number" 
                    placeholder={t.amount} 
                    value={newExpense.amount || ''} 
                    onChange={e => setNewExpense({...newExpense, amount: parseFloat(e.target.value) || 0})}
                    className="bg-slate-50 dark:bg-slate-800 border-none rounded-xl px-4 py-3 text-sm font-bold dark:text-white"
                  />
                  <button 
                    onClick={() => {
                      if (!newExpense.category || !newExpense.amount) return;
                      onAddExpense({
                        id: 'e' + Date.now(),
                        date: new Date().toISOString().split('T')[0],
                        ...newExpense
                      });
                      setNewExpense({ category: '', amount: 0, description: '' });
                    }}
                    className="bg-amber-500 text-slate-950 rounded-xl font-black text-xs uppercase tracking-widest py-3 px-6 shadow-lg shadow-amber-500/20"
                  >
                    {t.addExpense}
                  </button>
                </div>
              </div>

              <div className="bg-white dark:bg-slate-900 rounded-[2.5rem] border border-slate-100 dark:border-slate-800 shadow-sm overflow-hidden">
                 <div className="p-6 border-b border-slate-50 dark:border-slate-800">
                    <h3 className="font-bold text-slate-800 dark:text-white">{t.history}</h3>
                 </div>
                 <div className="overflow-x-auto">
                    <table className="w-full text-left">
                      <thead className="bg-slate-50 dark:bg-slate-800/50 text-[10px] font-black text-slate-400 uppercase tracking-widest">
                        <tr>
                          <th className="px-6 py-4">{t.date}</th>
                          <th className="px-6 py-4">{t.category}</th>
                          <th className="px-6 py-4 text-right">{t.amount}</th>
                          <th className="px-6 py-4 text-center">{t.actions}</th>
                        </tr>
                      </thead>
                      <tbody className="divide-y divide-slate-50 dark:divide-slate-800">
                        {expenses.sort((a,b) => b.date.localeCompare(a.date)).map(exp => (
                          <tr key={exp.id}>
                            <td className="px-6 py-4 text-xs font-bold">{exp.date}</td>
                            <td className="px-6 py-4 text-xs font-bold">{exp.category}</td>
                            <td className="px-6 py-4 text-right font-black text-rose-500">{currency}{exp.amount.toFixed(2)}</td>
                            <td className="px-6 py-4 text-center">
                              <button onClick={() => onDeleteExpense && onDeleteExpense(exp.id)} className="text-slate-300 hover:text-rose-500 transition-colors">
                                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" strokeLinecap="round" strokeLinejoin="round" strokeWidth="2"/></svg>
                              </button>
                            </td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                 </div>
              </div>
           </motion.div>
        )}
      </AnimatePresence>

      {/* Sale Details Modal */}
      <AnimatePresence>
        {viewingSale && (
          <div className="fixed inset-0 bg-slate-950/40 backdrop-blur-sm z-[100] flex items-center justify-center p-4">
            <motion.div initial={{ scale: 0.9, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} exit={{ scale: 0.9, opacity: 0 }} className="bg-white dark:bg-slate-900 w-full max-w-md rounded-[2.5rem] p-8 shadow-2xl overflow-hidden border border-slate-100 dark:border-slate-800">
               <div className="flex justify-between items-center mb-8 border-b border-slate-50 dark:border-slate-800 pb-4">
                 <div>
                    <h3 className="text-xl font-black text-slate-900 dark:text-white">Transaction Details</h3>
                    <p className="text-[10px] font-mono text-slate-400 mt-1">ID: #{viewingSale.id}</p>
                 </div>
                 <button onClick={() => setViewingSale(null)} className="p-2 bg-slate-50 dark:bg-slate-800 rounded-full text-slate-400 hover:text-rose-500">
                    <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M6 18L18 6M6 6l12 12" strokeLinecap="round" strokeLinejoin="round" strokeWidth="3"/></svg>
                 </button>
               </div>
               <div className="space-y-4">
                 <div className="max-h-60 overflow-y-auto pr-2 scrollbar-hide space-y-3">
                   {viewingSale.items.map((item, idx) => (
                     <div key={idx} className="flex justify-between items-center p-3 bg-slate-50 dark:bg-slate-800/50 rounded-xl">
                        <div>
                          <p className="font-bold text-slate-800 dark:text-slate-200 text-xs">{item.name}</p>
                          <p className="text-[10px] text-slate-400">{item.quantity} x {currency}{item.price}</p>
                        </div>
                        <span className="font-mono font-black text-slate-900 dark:text-white">{currency}{(item.price * item.quantity).toFixed(2)}</span>
                     </div>
                   ))}
                 </div>
                 <div className="pt-6 space-y-2 border-t border-slate-100 dark:border-slate-800">
                    <div className="flex justify-between text-[10px] font-bold text-slate-400 uppercase">
                       <span>Subtotal</span>
                       <span>{currency}{(viewingSale.total - viewingSale.tax + viewingSale.discount).toFixed(2)}</span>
                    </div>
                    {viewingSale.discount > 0 && (
                      <div className="flex justify-between text-[10px] font-bold text-emerald-500 uppercase">
                         <span>Discount ({viewingSale.discountCode || 'Applied'})</span>
                         <span>-{currency}{viewingSale.discount.toFixed(2)}</span>
                      </div>
                    )}
                    <div className="flex justify-between text-[10px] font-bold text-slate-400 uppercase">
                       <span>Tax ({viewingSale.taxType === 'included' ? 'Incl.' : ''})</span>
                       <span>{currency}{viewingSale.tax.toFixed(2)}</span>
                    </div>
                    <div className="flex justify-between items-center pt-2">
                       <span className="text-lg font-black text-slate-900 dark:text-white">Total Paid</span>
                       <span className="text-2xl font-black text-amber-500">{currency}{viewingSale.total.toFixed(2)}</span>
                    </div>
                 </div>
                 <div className="mt-6 flex flex-wrap gap-2">
                    <div className="px-3 py-1.5 bg-slate-100 dark:bg-slate-800 rounded-lg text-[10px] font-black uppercase text-slate-500 tracking-widest">{viewingSale.paymentMethod}</div>
                    <div className="px-3 py-1.5 bg-slate-100 dark:bg-slate-800 rounded-lg text-[10px] font-black uppercase text-slate-500 tracking-widest">{new Date(viewingSale.timestamp).toLocaleDateString()}</div>
                 </div>
               </div>
            </motion.div>
          </div>
        )}
      </AnimatePresence>
    </div>
  );
};

export default Finance;

import React, { useState, useMemo } from 'react';
import { Sale, Expense, Staff, Language, Customer } from '../types';
import { getFinancialInsights } from '../services/geminiService';
import { TRANSLATIONS } from '../constants';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer } from 'recharts';
import { motion, AnimatePresence } from 'framer-motion';

interface FinanceProps {
  sales: Sale[];
  expenses: Expense[];
  staffList: Staff[];
  onAddExpense: (expense: Expense) => void;
  onDeleteExpense?: (id: string) => void;
  onDeleteSale?: (id: string) => void;
  onDeleteSales?: (ids: string[]) => void;
  currentUser: Staff;
  customers: Customer[];
  currency: string;
  language: Language;
  billingCycleDay?: number;
}

const Finance: React.FC<FinanceProps> = ({ sales, expenses, staffList, onAddExpense, onDeleteExpense, onDeleteSale, onDeleteSales, currentUser, customers, currency, language, billingCycleDay = 1 }) => {
  const [activeTab, setActiveTab] = useState<'overview' | 'transactions' | 'expenses'>('overview');
  const [loadingInsights, setLoadingInsights] = useState(false);
  const [insights, setInsights] = useState<string | null>(null);
  const [newExpense, setNewExpense] = useState({ category: '', amount: 0, description: '' });
  const [transactionSearch, setTransactionSearch] = useState('');
  const [viewingSale, setViewingSale] = useState<Sale | null>(null);
  const [selectedTransactions, setSelectedTransactions] = useState<Set<string>>(new Set());

  const t = TRANSLATIONS[language];

  const [startDate, setStartDate] = useState(() => {
    const today = new Date();
    const currentDay = today.getDate();
    let start = new Date(today.getFullYear(), today.getMonth(), billingCycleDay);
    if (currentDay < billingCycleDay) start = new Date(today.getFullYear(), today.getMonth() - 1, billingCycleDay);
    return start.toISOString().split('T')[0];
  });

  const [endDate, setEndDate] = useState(() => new Date().toISOString().split('T')[0]);

  const totalRevenue = useMemo(() => sales.reduce((acc, s) => acc + s.total, 0), [sales]);
  const totalExpenses = useMemo(() => expenses.reduce((acc, e) => acc + e.amount, 0), [expenses]);
  const profit = totalRevenue - totalExpenses;

  const reportData = useMemo(() => {
    const filteredSales = sales.filter(s => {
      const date = s.timestamp.split('T')[0];
      return date >= startDate && date <= endDate;
    });

    const staffStats = staffList.map(staff => {
      const personalSales = filteredSales.filter(s => s.staffId === staff.id);
      const revenue = personalSales.reduce((acc, s) => acc + s.total, 0);
      const commissionEarned = (revenue * staff.commission) / 100;
      return { ...staff, salesCount: personalSales.length, revenue, commissionEarned };
    }).sort((a, b) => b.revenue - a.revenue);

    const periodRevenue = filteredSales.reduce((acc, s) => acc + s.total, 0);
    const periodCommission = staffStats.reduce((acc, s) => acc + s.commissionEarned, 0);

    return { staffStats, periodRevenue, periodCommission, salesCount: filteredSales.length };
  }, [sales, staffList, startDate, endDate]);

  const filteredTransactions = useMemo(() => {
    const term = transactionSearch.toLowerCase();
    return sales.filter(s => {
      const customerName = customers.find(c => c.id === s.customerId)?.name.toLowerCase() || '';
      const staffName = staffList.find(st => st.id === s.staffId)?.name.toLowerCase() || '';
      return s.id.toLowerCase().includes(term) || customerName.includes(term) || staffName.includes(term);
    }).sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime());
  }, [sales, transactionSearch, customers, staffList]);

  const handleGenerateInsights = async () => {
    setLoadingInsights(true);
    const result = await getFinancialInsights(sales, expenses);
    setInsights(result);
    setLoadingInsights(false);
  };

  const toggleSelection = (id: string) => {
    const newSelection = new Set(selectedTransactions);
    if (newSelection.has(id)) newSelection.delete(id);
    else newSelection.add(id);
    setSelectedTransactions(newSelection);
  };

  const toggleSelectAll = () => {
    if (selectedTransactions.size === filteredTransactions.length && filteredTransactions.length > 0) setSelectedTransactions(new Set());
    else setSelectedTransactions(new Set(filteredTransactions.map(s => s.id)));
  };

  const handleBulkDelete = () => {
    if (currentUser.role !== 'admin') return;
    if (confirm(`Delete ${selectedTransactions.size} records? Inventory will be restored.`)) {
        if (onDeleteSales) onDeleteSales(Array.from(selectedTransactions));
        setSelectedTransactions(new Set());
    }
  };

  const downloadReport = (period: 'daily' | 'weekly' | 'monthly' | 'custom' | 'range') => {
    let salesForReport: Sale[] = [];
    if (period === 'custom') {
        if (selectedTransactions.size === 0) return;
        salesForReport = sales.filter(s => selectedTransactions.has(s.id));
    } else if (period === 'range') {
        salesForReport = sales.filter(s => {
            const date = s.timestamp.split('T')[0];
            return date >= startDate && date <= endDate;
        });
    } else {
        const today = new Date();
        let startFilterDate = new Date();
        if (period === 'daily') startFilterDate = new Date(today.getFullYear(), today.getMonth(), today.getDate());
        else if (period === 'weekly') startFilterDate.setDate(today.getDate() - 7);
        else if (period === 'monthly') {
          const currentDay = today.getDate();
          if (currentDay < billingCycleDay) startFilterDate = new Date(today.getFullYear(), today.getMonth() - 1, billingCycleDay);
          else startFilterDate = new Date(today.getFullYear(), today.getMonth(), billingCycleDay);
        }
        const startFilterStr = startFilterDate.toISOString().split('T')[0];
        salesForReport = sales.filter(s => s.timestamp.split('T')[0] >= startFilterStr);
    }

    if (salesForReport.length === 0) {
        alert("No sales found for the selected criteria.");
        return;
    }

    const headers = ['Transaction ID', 'Date', 'Staff', 'Customer', 'Items', 'Subtotal', 'Tax', 'Discount', 'Total', 'Payment Method'];
    const csvRows = [headers.join(",")];

    salesForReport.forEach(sale => {
        const staffName = staffList.find(s => s.id === sale.staffId)?.name || 'N/A';
        const customerName = customers.find(c => c.id === sale.customerId)?.name || 'Walk-in';
        const itemsSummary = sale.items.map(i => `${i.quantity}x ${i.name}`).join('; ');

        const row = [
            sale.id,
            new Date(sale.timestamp).toLocaleDateString(),
            staffName,
            customerName,
            itemsSummary,
            (sale.total - sale.tax + sale.discount).toFixed(2),
            sale.tax.toFixed(2),
            sale.discount.toFixed(2),
            sale.total.toFixed(2),
            sale.paymentMethod
        ];

        // Quote and escape fields to prevent CSV breaking
        const formattedRow = row.map(field => {
            const stringified = String(field);
            const escaped = stringified.replace(/"/g, '""');
            return `"${escaped}"`;
        });

        csvRows.push(formattedRow.join(","));
    });

    const csvContent = csvRows.join("\n");
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);

    const link = document.createElement("a");
    link.setAttribute("href", url);
    link.setAttribute("download", `TrimTime_Report_${period}_${startDate}_to_${endDate}.csv`);
    link.style.visibility = 'hidden';
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
          <div className="flex overflow-x-auto scrollbar-hide gap-2 pb-2">
            {['overview', 'transactions', 'expenses'].map(tab => (
              <button key={tab} onClick={() => setActiveTab(tab as any)} className={`px-6 py-3 rounded-xl font-black text-sm uppercase tracking-wider transition-all whitespace-nowrap ${activeTab === tab ? 'bg-amber-500 text-slate-950' : 'bg-white dark:bg-slate-900 text-slate-400'}`}>
                {t[tab as keyof typeof t] || tab}
              </button>
            ))}
          </div>
          {currentUser.role === 'admin' && activeTab === 'overview' && (
             <button onClick={() => downloadReport('monthly')} className="flex items-center gap-2 bg-slate-900 text-white px-5 py-3 rounded-xl font-bold text-xs uppercase shadow-lg">
                <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4"/></svg>
                {t.exportReports}
             </button>
          )}
      </div>

      <AnimatePresence mode='wait'>
        {activeTab === 'overview' && (
          <motion.div key="overview" initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: -10 }} className="grid grid-cols-1 xl:grid-cols-2 gap-8">
            <div className="bg-white dark:bg-slate-900 p-8 rounded-[2.5rem] border border-slate-100 dark:border-slate-800 shadow-sm">
              <h3 className="text-xl font-bold text-slate-800 dark:text-white mb-8 flex items-center gap-3">
                <div className="w-10 h-10 bg-amber-50 rounded-xl flex items-center justify-center text-amber-500">📊</div>
                {t.shopPerformance}
              </h3>
              <div className="h-80 w-full">
                <ResponsiveContainer width="100%" height="100%">
                  <BarChart data={[{ name: 'Summary', rev: totalRevenue, exp: totalExpenses, prf: profit }]}>
                    <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" className="dark:opacity-5" />
                    <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fill: '#94a3b8'}} />
                    <YAxis axisLine={false} tickLine={false} tick={{fill: '#94a3b8'}} />
                    <Tooltip cursor={{fill: 'transparent'}} contentStyle={{borderRadius: '12px', border: 'none', backgroundColor: '#0f172a', color: '#fff'}} />
                    <Legend iconType="circle" />
                    <Bar dataKey="rev" name={t.revenue} fill="#10b981" radius={[8, 8, 0, 0]} />
                    <Bar dataKey="exp" name={t.expenses} fill="#f43f5e" radius={[8, 8, 0, 0]} />
                    <Bar dataKey="prf" name={t.netProfit} fill="#3b82f6" radius={[8, 8, 0, 0]} />
                  </BarChart>
                </ResponsiveContainer>
              </div>
            </div>

            <div className="bg-white dark:bg-slate-900 p-8 rounded-[2.5rem] border border-slate-100 dark:border-slate-800 shadow-sm">
              <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center mb-8 gap-4">
                 <h3 className="text-xl font-bold text-slate-800 dark:text-white">{t.commissionReport}</h3>
                 <div className="flex flex-wrap items-center gap-2 bg-slate-50 dark:bg-slate-800 p-2 rounded-xl border border-slate-100 dark:border-slate-700">
                    <div className="flex items-center gap-2">
                      <input type="date" value={startDate} onChange={e => setStartDate(e.target.value)} className="bg-transparent border-none p-0 text-[10px] font-black uppercase dark:text-white focus:ring-0" />
                      <span className="text-slate-300">→</span>
                      <input type="date" value={endDate} onChange={e => setEndDate(e.target.value)} className="bg-transparent border-none p-0 text-[10px] font-black uppercase dark:text-white focus:ring-0" />
                    </div>
                    <button 
                      onClick={() => downloadReport('range')}
                      className="bg-slate-900 dark:bg-amber-500 text-white dark:text-slate-950 px-3 py-1.5 rounded-lg text-[9px] font-black uppercase tracking-widest hover:opacity-90 transition-opacity"
                    >
                      Export CSV
                    </button>
                 </div>
              </div>
              <div className="space-y-4">
                {reportData.staffStats.map(perf => (
                  <div key={perf.id} className="flex justify-between items-center p-4 bg-slate-50 dark:bg-slate-800/50 rounded-2xl">
                    <div>
                      <p className="font-bold text-slate-800 dark:text-slate-200 text-sm">{perf.name}</p>
                      <p className="text-[10px] text-slate-400 font-bold uppercase">{perf.salesCount} Sales</p>
                    </div>
                    <div className="text-right">
                      <p className="font-black text-emerald-600 dark:text-emerald-400">{currency}{perf.commissionEarned.toFixed(2)}</p>
                      <p className="text-[9px] text-slate-400 uppercase font-black">@{perf.commission}%</p>
                    </div>
                  </div>
                ))}
              </div>
            </div>

            <div className="xl:col-span-2 bg-slate-900 text-white p-8 rounded-[2.5rem] border border-slate-800">
               <div className="flex justify-between items-center mb-6">
                 <h3 className="text-xl font-bold">✨ {t.smartInsights}</h3>
                 <button onClick={handleGenerateInsights} disabled={loadingInsights} className="bg-amber-500 text-slate-950 px-6 py-2 rounded-xl font-black text-sm">{loadingInsights ? t.analyzing : t.generateAdvice}</button>
