                      <button onClick={() => setIsAddingCustomer(false)} className="flex-1 py-4 text-slate-400 font-bold text-sm uppercase tracking-widest">{t.logout}</button>
                      <button onClick={handleQuickAddCustomer} className="flex-1 bg-amber-500 text-slate-950 py-4 rounded-xl font-black text-xs uppercase tracking-widest shadow-lg shadow-amber-500/20">{t.addSelectClient}</button>
                   </div>
                </div>
             </motion.div>
          </div>
        )}
      </AnimatePresence>
    </div>
  );
};

