          >
             <div className="flex items-center gap-4 mb-2">
                <div className="w-10 h-10 bg-rose-100 dark:bg-rose-900/40 rounded-xl flex items-center justify-center text-rose-500">
                    <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z"/></svg>
                </div>
                <div>
                    <h3 className="text-lg md:text-xl font-bold text-rose-600 dark:text-rose-400">{t.dangerZone}</h3>
                    <p className="text-xs text-rose-400 dark:text-rose-500/70 mt-1">{t.resetSalesDesc}</p>
                </div>
             </div>
             <div className="flex justify-end">
                <button 
                    type="button"
                    onClick={handleResetSales}
                    className="bg-rose-500 text-white px-6 py-3 rounded-xl font-bold text-sm hover:bg-rose-600 transition-colors shadow-lg shadow-rose-500/20"
                >
                    {t.resetSales}
                </button>
             </div>
          </motion.div>
        )}

        <div className="flex flex-col sm:flex-row justify-end gap-3 md:gap-4 pt-4">
            <button 
                type="button" 
                onClick={() => {
                  setFormData(settings);
                  setIsCustomCurrency(!CURRENCY_OPTIONS.some(opt => opt.symbol === settings.currency));
                }}
                className="px-8 py-4 font-black text-slate-400 dark:text-slate-600 hover:text-slate-600 dark:hover:text-slate-400 transition-colors uppercase text-xs tracking-widest"
            >
                {t.resetChanges}
            </button>
            <button 
                type="submit" 
                className="bg-slate-950 dark:bg-amber-500 text-white dark:text-slate-950 px-10 py-4 rounded-2xl font-black text-base hover:bg-slate-800 dark:hover:bg-amber-600 transition-all shadow-xl active:scale-95"
            >
                {t.saveSettings}
            </button>
        </div>
      </form>
    </div>
  );
};

export default Settings;

import React, { useState, useMemo, useEffect, useRef } from 'react';
import { Service, Product, Staff, Sale, SaleItem, Customer, ShopSettings, HeldSale } from '../types';
import { TRANSLATIONS } from '../constants';
import { jsPDF } from 'jspdf';
import { motion, AnimatePresence } from 'framer-motion';
import { Html5Qrcode } from 'html5-qrcode';

interface POSProps {
  services: Service[];
  products: Product[];
  staff: Staff[];
  customers: Customer[];
  settings: ShopSettings;
  currentUser: Staff;
  onCompleteSale: (sale: Sale) => void;
  onAddCustomer: (customer: Customer) => void;
}

const POS: React.FC<POSProps> = ({ services, products, staff, customers, settings, currentUser, onCompleteSale, onAddCustomer }) => {
  const [cart, setCart] = useState<SaleItem[]>([]);
  const [selectedStaff, setSelectedStaff] = useState<string>(currentUser.role === 'employee' ? currentUser.id : '');
  const [selectedCustomer, setSelectedCustomer] = useState<string>('');
  const [discountCode, setDiscountCode] = useState<string>('');
  const [activeTab, setActiveTab] = useState<'services' | 'products'>('services');
  const [searchTerm, setSearchTerm] = useState('');
  const [heldSales, setHeldSales] = useState<HeldSale[]>([]);
  const [lastSale, setLastSale] = useState<Sale | null>(null);
  const [autoWhatsapp, setAutoWhatsapp] = useState(false);

  const [scanningFeedback, setScanningFeedback] = useState<string | null>(null);
  const [feedbackType, setFeedbackType] = useState<'success' | 'error'>('success');

  const [showMobileCart, setShowMobileCart] = useState(false);
  const [isAddingCustomer, setIsAddingCustomer] = useState(false);
  const [newCustomerData, setNewCustomerData] = useState({ name: '', phone: '', email: '' });
  const [isScanning, setIsScanning] = useState(false);

  const feedbackTimeoutRef = useRef<number | null>(null);
  const html5QrCodeRef = useRef<Html5Qrcode | null>(null);
  const isScannerActiveRef = useRef(false);
  const processingScanRef = useRef(false);

  const t = TRANSLATIONS[settings.language];

  // Helper to get Customer Details for last sale or active cart
  const activeCustomer = useMemo(() => customers.find(c => c.id === selectedCustomer), [selectedCustomer, customers]);
  const lastCustomer = useMemo(() => lastSale?.customerId ? customers.find(c => c.id === lastSale.customerId) : null, [lastSale, customers]);

  // WhatsApp Message Generator
  const sendWhatsappReceipt = (sale: Sale, customer: Customer) => {
    if (!customer.phone) return;

    const itemsList = sale.items.map(i => `• *${i.name}* (${settings.currency}${i.price} x ${i.quantity})`).join('%0A');
    const message = `✨ *${settings.shopName} Receipt* ✨%0A%0A` +
      `👤 *Customer:* ${customer.name}%0A` +
      `📅 *Date:* ${new Date(sale.timestamp).toLocaleDateString()}%0A` +
      `🧾 *ID:* #${sale.id.slice(0, 8)}%0A` +
      `--------------------------%0A` +
      `${itemsList}%0A` +
      `--------------------------%0A` +
      `💰 *Total:* ${settings.currency}${sale.total.toFixed(2)}%0A` +
      `💳 *Method:* ${sale.paymentMethod.toUpperCase()}%0A%0A` +
      `${settings.receiptFooter}%0A%0A` +
      `_Thank you for your visit!_`;

    const cleanPhone = customer.phone.replace(/\D/g, '');
    window.open(`https://wa.me/${cleanPhone}?text=${message}`, '_blank');
  };

  useEffect(() => {
    let isMounted = true;
    if (isScanning) {
        const startScanner = async () => {
            await new Promise(resolve => setTimeout(resolve, 300));
            if (!isMounted || !isScanning) return;
            if (html5QrCodeRef.current) return;
            try {
                const html5QrCode = new Html5Qrcode("reader");
                html5QrCodeRef.current = html5QrCode;
                await html5QrCode.start(
                    { facingMode: "environment" }, 
                    { fps: 10, qrbox: { width: 250, height: 150 }, aspectRatio: 1.0 }, 
                    (decodedText) => { if (isMounted) handleScan(decodedText); },
                    (errorMessage) => {}
                );
                if (isMounted) isScannerActiveRef.current = true;
            } catch (err: any) {
                if (isMounted) setIsScanning(false);
                html5QrCodeRef.current = null;
                isScannerActiveRef.current = false;
            }
        };
        startScanner();
    }
    return () => {
        isMounted = false;
        if (html5QrCodeRef.current) {
            const scanner = html5QrCodeRef.current;
            html5QrCodeRef.current = null;
            if (isScannerActiveRef.current) {
                scanner.stop().catch(() => {}).finally(() => {
                    try { scanner.clear(); } catch(e) {}
                    isScannerActiveRef.current = false;
                });
            } else {
                try { scanner.clear(); } catch(e) {}
            }
        }
    };
  }, [isScanning]);

  const handleScan = (barcode: string) => {
    if (processingScanRef.current) return;
    processingScanRef.current = true;
    setTimeout(() => { processingScanRef.current = false; }, 1500);
    const product = products.find(p => p.barcode === barcode);
    if (product) {
        addToCart(product, 'product');
        setScanningFeedback(product.name);
        setFeedbackType('success');
    } else {
        setScanningFeedback(`Not Found: ${barcode}`);
        setFeedbackType('error');
    }
    if (feedbackTimeoutRef.current) window.clearTimeout(feedbackTimeoutRef.current);
    feedbackTimeoutRef.current = window.setTimeout(() => { setScanningFeedback(null); }, 2500);
  };

  const toggleScanner = () => setIsScanning(!isScanning);

  const addToCart = (item: Service | Product, type: 'service' | 'product') => {
    setCart(prev => {
      const existing = prev.find(i => i.id === item.id && i.type === type);
      if (existing) {
        return prev.map(i => i.id === item.id && i.type === type ? { ...i, quantity: i.quantity + 1 } : i);
      }
      return [...prev, { id: item.id, name: item.name, price: item.price, type, quantity: 1 }];
    });
  };

  const updateQuantity = (id: string, type: 'service' | 'product', delta: number) => {
    setCart(prev => prev.map(item => {
      if (item.id === id && item.type === type) return { ...item, quantity: Math.max(1, item.quantity + delta) };
      return item;
    }));
  };

  const removeFromCart = (id: string, type: 'service' | 'product') => {
    setCart(prev => prev.filter(i => !(i.id === id && i.type === type)));
  };

  const totals = useMemo(() => {
    const rawSubtotal = cart.reduce((acc, item) => acc + (item.price * item.quantity), 0);
    let discount = 0;

    // Use dynamic promo codes from settings
    const code = (settings.promoCodes || []).find(c => c.code === discountCode);

    if (code) discount = code.type === 'percentage' ? (rawSubtotal * code.value) / 100 : code.value;
    const discountedAmount = rawSubtotal - discount;
    let tax = 0;
    let total = 0;
    if (settings.taxType === 'included') {
      total = discountedAmount;
      tax = total - (total / (1 + (settings.taxRate / 100)));
    } else {
      tax = discountedAmount * (settings.taxRate / 100);
      total = discountedAmount + tax;
    }
    return { subtotal: rawSubtotal, discount, tax, total };
  }, [cart, discountCode, settings]);

  const handleHoldSale = () => {
    if (cart.length === 0) return;
    const newHold: HeldSale = {
      id: Math.random().toString(36).substr(2, 9).toUpperCase(),
      timestamp: new Date().toISOString(),
      cart: [...cart],
      customerId: selectedCustomer || undefined,
      staffId: selectedStaff || undefined,
    };
    setHeldSales([newHold, ...heldSales]);
    setCart([]);
    setSelectedCustomer('');
    if (currentUser.role !== 'employee') setSelectedStaff('');
  };

  const retrieveSale = (held: HeldSale) => {
    setCart(held.cart);
    if (held.customerId) setSelectedCustomer(held.customerId);
    if (held.staffId) setSelectedStaff(held.staffId);
    setHeldSales(heldSales.filter(h => h.id !== held.id));
  };

  const generatePDF = (sale: Sale) => {
    const doc = new jsPDF({ unit: 'mm', format: [80, 200] });
    const barber = staff.find(s => s.id === sale.staffId)?.name || 'N/A';
    const client = customers.find(c => c.id === sale.customerId)?.name || 'Guest Walk-in';
    const dateStr = new Date(sale.timestamp).toLocaleString();
    doc.setFillColor(15, 23, 42);
    doc.rect(0, 0, 80, 10, 'F');
    doc.setTextColor(245, 158, 11);
    doc.setFont('helvetica', 'bold').setFontSize(10);
    doc.text('OFFICIAL RECEIPT', 40, 7, { align: 'center' });
    doc.setTextColor(15, 23, 42);
    doc.setFontSize(16).text(settings.shopName.toUpperCase(), 40, 25, { align: 'center' });
    doc.setFontSize(8).setFont('helvetica', 'normal').text('Professional Grooming & Care', 40, 30, { align: 'center' });
    doc.setDrawColor(226, 232, 240);
    doc.setLineWidth(0.3).line(5, 35, 75, 35);
    doc.setFontSize(7).setTextColor(100, 116, 139);
    doc.text(`Transaction ID: #${sale.id}`, 5, 42);
    doc.text(`Date & Time: ${dateStr}`, 5, 46);
    doc.text(`Professional: ${barber}`, 5, 50);
    doc.text(`Client: ${client}`, 5, 54);
    doc.line(5, 58, 75, 58);
    let y = 65;
    doc.setFont('helvetica', 'bold').setFontSize(8).setTextColor(15, 23, 42);
    doc.text('DESCRIPTION', 5, y);
    doc.text('QTY', 52, y);
    doc.text('AMOUNT', 75, y, { align: 'right' });
    doc.line(5, y + 2, 75, y + 2);
    doc.setFont('helvetica', 'normal').setFontSize(7);
    y += 7;
    sale.items.forEach(item => {
      doc.text(item.name.substring(0, 25), 5, y);
      doc.text(item.quantity.toString(), 54, y, { align: 'center' });
      doc.text(`${settings.currency}${(item.price * item.quantity).toFixed(2)}`, 75, y, { align: 'right' });
      y += 5;
    });
    y += 5;
    doc.setDrawColor(15, 23, 42);
    doc.line(5, y, 75, y);
    y += 7;
    const subtotalValue = sale.items.reduce((acc, i) => acc + (i.price * i.quantity), 0);
    doc.setFont('helvetica', 'normal').text('SUBTOTAL:', 5, y);
    doc.text(`${settings.currency}${subtotalValue.toFixed(2)}`, 75, y, { align: 'right' });
    y += 5;
    if (sale.discount > 0) {
      doc.text(`DISCOUNT (${sale.discountCode || 'Applied'}):`, 5, y);
      doc.text(`-${settings.currency}${sale.discount.toFixed(2)}`, 75, y, { align: 'right' });
      y += 5;
    }
    if (sale.taxType === 'excluded') {
      doc.text(`TAX (${settings.taxRate}%):`, 5, y);
      doc.text(`${settings.currency}${sale.tax.toFixed(2)}`, 75, y, { align: 'right' });
      y += 5;
    } else {
      doc.setFontSize(6).setTextColor(148, 163, 184);
      doc.text(`Includes ${settings.taxRate}% tax of ${settings.currency}${sale.tax.toFixed(2)}`, 5, y);
      doc.setFontSize(7).setTextColor(15, 23, 42);
      y += 5;
    }
    y += 2;
    doc.setFillColor(248, 250, 252);
    doc.rect(5, y - 4, 70, 8, 'F');
    doc.setFontSize(10).setFont('helvetica', 'bold').text('TOTAL PAID:', 7, y + 1.5);
    doc.text(`${settings.currency}${sale.total.toFixed(2)}`, 73, y + 1.5, { align: 'right' });
    y += 15;
    doc.setFontSize(7).setFont('helvetica', 'italic').setTextColor(148, 163, 184);
    doc.text(settings.receiptFooter, 40, y, { align: 'center' });
    doc.text('Thank you for your visit!', 40, y + 4, { align: 'center' });
    doc.setFillColor(15, 23, 42);
    doc.rect(0, 195, 80, 5, 'F');
    return doc;
  };

  const handleShareReceipt = async (sale: Sale) => {
    const doc = generatePDF(sale);
    const pdfBlob = doc.output('blob');
    const file = new File([pdfBlob], `Receipt-${sale.id}.pdf`, { type: 'application/pdf' });
    if (navigator.share && navigator.canShare && navigator.canShare({ files: [file] })) {
      try {
        await navigator.share({ files: [file], title: `${settings.shopName} Receipt`, text: `Your receipt for transaction #${sale.id}` });
      } catch (error: any) {
        if (error.name !== 'AbortError' && !error.message.includes('cancellation')) doc.save(`Receipt-${sale.id}.pdf`);
      }
    } else doc.save(`Receipt-${sale.id}.pdf`);
  };

  const handleCheckout = (paymentMethod: 'cash' | 'card') => {
    if (cart.length === 0 || !selectedStaff) {
      alert('Please add items and assign a professional.');
      return;
    }
    const sale: Sale = {
      id: Math.random().toString(36).substr(2, 9).toUpperCase(),
      timestamp: new Date().toISOString(),
      items: [...cart],
      staffId: selectedStaff,
      customerId: selectedCustomer || undefined,
      total: totals.total,
      tax: totals.tax,
      discount: totals.discount,
      discountCode: discountCode || undefined,
      paymentMethod,
      taxType: settings.taxType,
    };

    onCompleteSale(sale);
    setLastSale(sale);

    // Auto-Send Logic
    if (autoWhatsapp && selectedCustomer) {
      const cust = customers.find(c => c.id === selectedCustomer);
      if (cust && cust.phone) {
        setTimeout(() => sendWhatsappReceipt(sale, cust), 1200);
      }
    }

    setCart([]);
    setSelectedCustomer('');
    setDiscountCode('');
    if (currentUser.role !== 'employee') setSelectedStaff('');
    setShowMobileCart(false);
  };

  const handleQuickAddCustomer = () => {
    if (!newCustomerData.name) return;
    const newCust: Customer = {
      id: 'c' + Date.now().toString(36) + Math.random().toString(36).substr(2, 4),
      name: newCustomerData.name,
      phone: newCustomerData.phone,
      email: newCustomerData.email,
      notes: '',
      createdAt: new Date().toISOString().split('T')[0]
    };
    onAddCustomer(newCust);
    setSelectedCustomer(newCust.id);
    setIsAddingCustomer(false);
    setNewCustomerData({ name: '', phone: '', email: '' });
  };

  const filteredItems = useMemo(() => {
    const search = searchTerm.toLowerCase();
    if (activeTab === 'services') return services.filter(s => s.name.toLowerCase().includes(search) || s.category.toLowerCase().includes(search));
    return products.filter(p => p.name.toLowerCase().includes(search));
  }, [activeTab, services, products, searchTerm]);

  return (
    <div className="flex flex-col lg:flex-row gap-6 h-[calc(100vh-12rem)] relative">
      <AnimatePresence>
        {lastSale && (
          <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="fixed inset-0 bg-slate-950/80 backdrop-blur-xl z-[150] flex items-center justify-center p-6 no-print">
            <motion.div initial={{ scale: 0.8, opacity: 0, y: 20 }} animate={{ scale: 1, opacity: 1, y: 0 }} className="bg-white dark:bg-slate-900 rounded-[3rem] p-10 max-w-md w-full shadow-2xl text-center space-y-8">
              <div className="w-20 h-20 bg-emerald-50 dark:bg-emerald-900/20 text-emerald-500 rounded-full flex items-center justify-center text-4xl mx-auto shadow-inner">✓</div>
              <div className="space-y-2">
                <h3 className="text-3xl font-black text-slate-900 dark:text-white tracking-tight">{t.saleSuccess}</h3>
                <p className="text-slate-400 dark:text-slate-500 font-medium">{t.orderCompleted}</p>
              </div>
              <div className="flex flex-col gap-3">
                {lastCustomer && lastCustomer.phone && (
                  <button onClick={() => sendWhatsappReceipt(lastSale, lastCustomer)} className="w-full bg-emerald-500 text-white py-4 rounded-2xl font-black flex items-center justify-center gap-3 hover:bg-emerald-600 transition-all shadow-xl shadow-emerald-500/20 active:scale-95">
                    <svg className="w-5 h-5" fill="currentColor" viewBox="0 0 24 24"><path d="M.057 24l1.687-6.163c-1.041-1.804-1.588-3.849-1.587-5.946.003-6.556 5.338-11.891 11.893-11.891 3.181.001 6.167 1.24 8.413 3.488 2.246 2.248 3.484 5.232 3.484 8.412-.003 6.557-5.338 11.892-11.893 11.892-1.997-.001-3.951-.5-5.688-1.448l-6.309 1.656zm6.224-3.52c1.54.914 3.453 1.403 5.385 1.404h.005c5.632 0 10.211-4.579 10.214-10.211 0-2.729-1.063-5.295-2.993-7.225s-4.496-2.992-7.225-2.993c-5.633 0-10.213 4.58-10.214 10.214 0 2.022.529 3.996 1.531 5.74l-.991 3.618 3.707-.972zm11.233-5.62c-.301-.151-1.782-.879-2.057-.979-.275-.1-.475-.151-.675.151s-.777.979-.952 1.179-.35.225-.65.076c-.301-.151-1.268-.467-2.417-1.492-.892-.795-1.494-1.777-1.669-2.078-.175-.301-.019-.463.131-.613.135-.134.301-.351.451-.526s.201-.3.301-.5c.101-.201.05-.376-.025-.526s-.675-1.629-.925-2.229c-.244-.583-.491-.504-.675-.513-.175-.008-.376-.01-.576-.01s-.526.076-.801.376c-.275.301-1.051 1.028-1.051 2.508s1.076 2.908 1.226 3.109c.151.201 2.118 3.235 5.132 4.537.717.309 1.277.494 1.714.633.72.228 1.375.196 1.892.119.577-.085 1.782-.728 2.032-1.429s.25-.151.25-.376-.101-.351-.401-.502z"/></svg>
                    Send WhatsApp Receipt
                  </button>
                )}
                <button onClick={() => handleShareReceipt(lastSale)} className="w-full bg-slate-950 dark:bg-amber-500 dark:text-slate-950 text-white py-4 rounded-2xl font-black flex items-center justify-center gap-3 hover:bg-slate-800 dark:hover:bg-amber-600 transition-all shadow-xl active:scale-95">
                  <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M8.684 13.342C8.886 12.938 9 12.482 9 12c0-.482-.114-.938-.316-1.342m0 2.684a3 3 0 110-2.684m0 2.684l6.632 3.316m-6.632-6l6.632-3.316m0 0a3 3 0 105.367-2.684 3 3 0 00-5.367 2.684zm0 9.316a3 3 0 105.368 2.684 3 3 0 00-5.368-2.684z"/></svg>
                  {t.shareReceipt}
                </button>
                <button onClick={() => setLastSale(null)} className="w-full py-4 text-slate-400 dark:text-slate-600 font-bold hover:text-slate-600 dark:hover:text-slate-400">{t.startNewBill}</button>
              </div>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>

      <div className="flex-1 flex flex-col min-h-0">
        <div className="mb-6 flex flex-col sm:flex-row gap-4">
          <div className="flex-1 flex gap-2">
            <div className="flex-1 relative">
                <svg className="w-5 h-5 absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 dark:text-slate-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z"/></svg>
                <input type="text" placeholder={t.searchCatalog} value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} className="w-full bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-2xl py-3.5 pl-12 pr-6 outline-none focus:ring-4 focus:ring-amber-500/10 shadow-sm text-sm font-medium dark:text-slate-200" />
            </div>
            <button onClick={toggleScanner} className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-2xl px-4 flex items-center justify-center text-slate-500 dark:text-slate-400 hover:text-amber-500 dark:hover:text-amber-400 transition-all shadow-sm"><svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 4v1m6 11h2m-6 0h-2v4m0-11v3m0 0h.01M12 12h4.01M16 20h4M4 12h4m12 0h.01M5 8h2a1 1 0 001-1V5a1 1 0 00-1-1H5a1 1 0 00-1 1v2a1 1 0 001 1zm12 0h2a1 1 0 001-1V5a1 1 0 00-1-1h-2a1 1 0 00-1 1v2a1 1 0 001 1zM5 20h2a1 1 0 001-1v-2a1 1 0 00-1-1H5a1 1 0 00-1 1v2a1 1 0 001 1z"/></svg></button>
          </div>
          <div className="flex bg-white dark:bg-slate-900 p-1 rounded-2xl border border-slate-100 dark:border-slate-800 shadow-sm">
            <button onClick={() => setActiveTab('services')} className={`px-6 py-2 rounded-xl text-xs font-black uppercase tracking-widest transition-all ${activeTab === 'services' ? 'bg-amber-500 text-slate-900 shadow-md' : 'text-slate-400 hover:text-slate-600'}`}>{t.services}</button>
            <button onClick={() => setActiveTab('products')} className={`px-6 py-2 rounded-xl text-xs font-black uppercase tracking-widest transition-all ${activeTab === 'products' ? 'bg-amber-500 text-slate-900 shadow-md' : 'text-slate-400 hover:text-slate-600'}`}>{t.products}</button>
          </div>
        </div>
        <div className="flex-1 overflow-y-auto grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-3 gap-4 pr-2 scrollbar-hide">
          {filteredItems.map(item => (
