      "purpose": "maskable"
    }
  ],
  "share_target": {
    "action": "/share-target-receipt",
    "method": "POST",
    "enctype": "multipart/form-data",
    "params": {
      "title": "title",
      "text": "text",
      "files": [
        {
          "name": "receipt",
          "accept": ["image/*", ".jpg", ".jpeg", ".png", ".webp"]
        }
      ]
    }
  }
}

const CACHE_NAME = 'trimtime-v2';
const SHARE_CACHE = 'trimtime-share';
const urlsToCache = [
  '/',
  '/index.html',
  '/manifest.json'
];

// Install event - cache core assets
self.addEventListener('install', event => {
  event.waitUntil(
    caches.open(CACHE_NAME)
      .then(cache => {
        return cache.addAll(urlsToCache);
      })
  );
  self.skipWaiting();
});

// Activate event - cleanup old caches
self.addEventListener('activate', event => {
  event.waitUntil(
    caches.keys().then(cacheNames => {
      return Promise.all(
        cacheNames.map(cacheName => {
          if (cacheName !== CACHE_NAME && cacheName !== SHARE_CACHE) {
            return caches.delete(cacheName);
          }
        })
      );
    })
  );
  self.clients.claim();
});

// Fetch event - Network first, falling back to cache, AND handle Share Target
self.addEventListener('fetch', event => {
  const url = new URL(event.request.url);

  // Handle Receipt Share POST request
  if (url.pathname === '/share-target-receipt' && event.request.method === 'POST') {
    event.respondWith(
      (async () => {
        try {
          const formData = await event.request.formData();
          const mediaFile = formData.get('receipt');

          if (mediaFile) {
            const cache = await caches.open(SHARE_CACHE);
            // We store the file with a specific key
            await cache.put('shared-receipt-image', new Response(mediaFile));
          }

          // Redirect to the main app with a query param triggering the popup
          return Response.redirect('/?action=add-expense&source=share', 303);
        } catch (err) {
          console.error('Share target failed', err);
          return Response.redirect('/', 303);
        }
      })()
    );
    return;
  }

  // Standard caching logic
  event.respondWith(
    fetch(event.request)
      .then(response => {
        if (!response || response.status !== 200 || response.type !== 'basic') {
          return response;
        }
        const responseToCache = response.clone();
        caches.open(CACHE_NAME)
          .then(cache => {
            if (event.request.method === 'GET') {
                cache.put(event.request, responseToCache);
            }
          });
        return response;
      })
      .catch(() => {
        return caches.match(event.request);
      })
  );
});

