export default Finance;

import React, { useState, useEffect } from 'react';
import Sidebar from './components/Sidebar';
import Dashboard from './components/Dashboard';
import POS from './components/POS';
import Finance from './components/Finance';
import Customers from './components/Customers';
import Settings from './components/Settings';
import Inventory from './components/Inventory';
import StaffManagement from './components/StaffManagement';
import Login from './components/Login';
import { View, Sale, Expense, Service, Product, Staff, Customer, ShopSettings, Language } from './types';
import { INITIAL_SERVICES, INITIAL_PRODUCTS, INITIAL_STAFF, INITIAL_EXPENSES, INITIAL_CUSTOMERS, DEFAULT_SETTINGS } from './constants';
import { motion, AnimatePresence } from 'framer-motion';
import { supabase } from './supabaseClient';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<Staff | null>(() => {
    const saved = localStorage.getItem('trimtime_session');
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        if (parsed.user && parsed.expiry) {
           if (Date.now() < parsed.expiry) return parsed.user;
           return null;
        }
        return parsed.user || parsed;
      } catch (e) {
        return null;
      }
    }
    return null;
  });

  // Initialize view based on user role (Employees -> POS, Admin -> Dashboard)
  const [currentView, setCurrentView] = useState<View>(
    currentUser?.role === 'employee' ? View.POS : View.DASHBOARD
  );

  const [isSidebarOpen, setIsSidebarOpen] = useState(false);

  // Initialize state empty, will load from Supabase
  const [services, setServices] = useState<Service[]>([]);
  const [products, setProducts] = useState<Product[]>([]);
  const [staff, setStaff] = useState<Staff[]>([]);
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [sales, setSales] = useState<Sale[]>([]);
  const [settings, setSettings] = useState<ShopSettings>(DEFAULT_SETTINGS);
  const [loading, setLoading] = useState(true);

  // Shared Receipt Logic
  const [pendingSharedExpense, setPendingSharedExpense] = useState<{ image: string } | null>(null);

  // Language State (Session based, separate from Global Shop Default)
  const [sessionLanguage, setSessionLanguage] = useState<Language>(() => {
    const local = localStorage.getItem('trimtime_lang');
    return (local as Language) || 'en';
  });

  // Profile Modal State
  const [isProfileOpen, setIsProfileOpen] = useState(false);
  const [profileForm, setProfileForm] = useState({
    name: '',
    username: '',
    email: '',
    password: ''
  });
  const [showProfilePassword, setShowProfilePassword] = useState(false);

  // Dark Mode State
  const [isDarkMode, setIsDarkMode] = useState(() => {
    const saved = localStorage.getItem('trimtime_theme');
    if (saved) return saved === 'dark';
    return window.matchMedia('(prefers-color-scheme: dark)').matches;
  });

  // --- HANDLE PWA SHARE TARGET ---
  useEffect(() => {
    const checkSharedFile = async () => {
        const urlParams = new URLSearchParams(window.location.search);
        if (urlParams.get('action') === 'add-expense' && urlParams.get('source') === 'share') {
            // Retrieve image from cache
            if ('caches' in window) {
                try {
                    const cache = await caches.open('trimtime-share');
                    const response = await cache.match('shared-receipt-image');
                    if (response) {
                        const blob = await response.blob();
                        // Convert blob to base64 for display/storage
                        const reader = new FileReader();
                        reader.onloadend = () => {
                            setPendingSharedExpense({ image: reader.result as string });
                            // Force view to finance to show modal
                            setCurrentView(View.FINANCE);
                            // Clean up cache
                            cache.delete('shared-receipt-image');
                            // Clean URL
                            window.history.replaceState({}, '', '/');
                        };
                        reader.readAsDataURL(blob);
                    }
                } catch (e) {
                    console.error("Error retrieving shared receipt", e);
                }
            }
        }
    };
    checkSharedFile();
  }, []);

  // --- SUPABASE FETCHING ---
  const fetchData = async () => {
    setLoading(true);
    try {
        const results = await Promise.all([
            supabase.from('services').select('*'),
            supabase.from('products').select('*'),
            supabase.from('staff').select('*'),
            supabase.from('expenses').select('*'),
            supabase.from('customers').select('*'),
            supabase.from('sales').select('*'),
            supabase.from('settings').select('*').single()
        ]);

        if (results[0].data) setServices(results[0].data);
        else setServices(INITIAL_SERVICES); 

        if (results[1].data) setProducts(results[1].data);
        else setProducts(INITIAL_PRODUCTS);

        if (results[2].data && results[2].data.length > 0) setStaff(results[2].data);
        else setStaff(INITIAL_STAFF);

        if (results[3].data) {
            // Map DB columns to type if receiptImage is stored in description or separately
            // Assuming for now receiptImage might be added to description JSON or new column. 
            // If new column 'receipt_image' exists in DB:
            const mappedExpenses = results[3].data.map((e: any) => ({
                ...e,
                receiptImage: e.receipt_image // Assuming column name matches logic
            }));
            setExpenses(mappedExpenses);
        }
        else setExpenses(INITIAL_EXPENSES);

        if (results[4].data) {
          // Map created_at to createdAt
          const mappedCustomers = results[4].data.map((c: any) => ({
             ...c,
             createdAt: c.created_at
          }));
          setCustomers(mappedCustomers);
        } else {
          setCustomers(INITIAL_CUSTOMERS);
        }

        if (results[5].data) {
            // Map snake_case DB columns to camelCase application properties
            const mappedSales = results[5].data.map((s: any) => ({
                id: s.id,
                timestamp: s.timestamp,
                items: typeof s.items === 'string' ? JSON.parse(s.items) : s.items,
                staffId: s.staff_id,
                customerId: s.customer_id,
                total: s.total,
                tax: s.tax,
                discount: s.discount,
                discountCode: s.discount_code,
                paymentMethod: s.payment_method,
                taxType: s.tax_type
            }));
            setSales(mappedSales);
        }

        // Merge defaults with fetched data to ensure all fields exist
        if (results[6].data && results[6].data.data) {
            const fetchedSettings = { ...DEFAULT_SETTINGS, ...results[6].data.data };
            setSettings(fetchedSettings);

            // If no local preference exists, use the shop default
            if (!localStorage.getItem('trimtime_lang')) {
                setSessionLanguage(fetchedSettings.language);
            }
        }
    } catch (error) {
        console.error("Error fetching data from Supabase:", error);
    } finally {
        setLoading(false);
    }
  };

  useEffect(() => {
    fetchData();
  }, []);

  // --- PERSISTENCE HANDLERS ---

  const smartUpdateServices = async (updatedList: Service[]) => {
      const idsInNewList = new Set(updatedList.map(i => i.id));
      const deletedIds = services.filter(s => !idsInNewList.has(s.id)).map(s => s.id);

      setServices(updatedList);

      if (deletedIds.length > 0) {
          await supabase.from('services').delete().in('id', deletedIds);
      }
      if (updatedList.length > 0) {
          await supabase.from('services').upsert(updatedList);
      }
  };

  const smartUpdateProducts = async (updatedList: Product[]) => {
      const idsInNewList = new Set(updatedList.map(i => i.id));
      const deletedIds = products.filter(p => !idsInNewList.has(p.id)).map(p => p.id);

      setProducts(updatedList);

      if (deletedIds.length > 0) {
          await supabase.from('products').delete().in('id', deletedIds);
      }
      if (updatedList.length > 0) {
          await supabase.from('products').upsert(updatedList);
      }
  };

  const smartUpdateStaff = async (updatedList: Staff[]) => {
      const idsInNewList = new Set(updatedList.map(i => i.id));
      const deletedIds = staff.filter(s => !idsInNewList.has(s.id)).map(s => s.id);

      setStaff(updatedList);

      // Sync with currentUser if the logged-in user is updated
      if (currentUser) {
        const updatedSelf = updatedList.find(s => s.id === currentUser.id);
        if (updatedSelf) {
            // Update state
            setCurrentUser(updatedSelf);
            // Update session storage
            const savedSession = localStorage.getItem('trimtime_session');
            if (savedSession) {
                try {
                    const parsed = JSON.parse(savedSession);
                    localStorage.setItem('trimtime_session', JSON.stringify({ ...parsed, user: updatedSelf }));
                } catch (e) {
                    console.error("Error updating session storage", e);
                }
            }
        }
      }

      if (deletedIds.length > 0) {
          await supabase.from('staff').delete().in('id', deletedIds);
      }
      if (updatedList.length > 0) {
          await supabase.from('staff').upsert(updatedList);
      }
  };

  // Customers: Update, Delete, Insert
  const smartUpdateCustomers = async (updatedList: Customer[]) => {
      const idsInNewList = new Set(updatedList.map(i => i.id));
      const deletedIds = customers.filter(c => !idsInNewList.has(c.id)).map(c => c.id);

      setCustomers(updatedList);

      if (deletedIds.length > 0) {
          await supabase.from('customers').delete().in('id', deletedIds);
      }

      // Map back to snake_case for DB
      const recordsToUpsert = updatedList.map(c => ({
          id: c.id,
          name: c.name,
          phone: c.phone,
          email: c.email,
          notes: c.notes,
          created_at: c.createdAt
      }));

      if (recordsToUpsert.length > 0) {
          await supabase.from('customers').upsert(recordsToUpsert);
      }
  };

  const handleCompleteSale = async (newSale: Sale) => {
      const updatedSales = [...sales, newSale];
      setSales(updatedSales);

      const { error } = await supabase.from('sales').insert({
          id: newSale.id,
          timestamp: newSale.timestamp,
          items: newSale.items, 
          staff_id: newSale.staffId,
          customer_id: newSale.customerId,
          total: newSale.total,
          tax: newSale.tax,
          discount: newSale.discount,
          discount_code: newSale.discountCode,
          payment_method: newSale.paymentMethod,
          tax_type: newSale.taxType
      });

      if (error) console.error("Error saving sale:", error);

      // Update product stock
      newSale.items.forEach(async (item) => {
          if (item.type === 'product') {
              const product = products.find(p => p.id === item.id);
              if (product) {
                  const newStock = product.stock - item.quantity;
                  setProducts(prev => prev.map(p => p.id === product.id ? { ...p, stock: newStock } : p));
                  await supabase.from('products').update({ stock: newStock }).eq('id', product.id);
              }
          }
      });
  };

  // Delete a sale and restore stock
  const handleDeleteSale = async (saleId: string) => {
    const saleToDelete = sales.find(s => s.id === saleId);
    if (!saleToDelete) return;

    // 1. Remove from Sales List
    setSales(prev => prev.filter(s => s.id !== saleId));

    // 2. Remove from DB
    await supabase.from('sales').delete().eq('id', saleId);

    // 3. Restore Stock for products involved
    let productsUpdated = false;
    const updatedProductList = [...products];

    saleToDelete.items.forEach(item => {
        if (item.type === 'product') {
            const productIndex = updatedProductList.findIndex(p => p.id === item.id);
            if (productIndex > -1) {
                updatedProductList[productIndex] = {
                    ...updatedProductList[productIndex],
                    stock: updatedProductList[productIndex].stock + item.quantity
                };
                productsUpdated = true;
            }
        }
    });

    if (productsUpdated) {
        setProducts(updatedProductList);
        await smartUpdateProducts(updatedProductList);
    }
  };

  // Bulk Delete Sales and Restore Stock
  const handleBulkDeleteSales = async (saleIds: string[]) => {
    const salesToDelete = sales.filter(s => saleIds.includes(s.id));
    if (salesToDelete.length === 0) return;

    // 1. Remove from Sales List
    setSales(prev => prev.filter(s => !saleIds.includes(s.id)));

    // 2. Remove from DB
    await supabase.from('sales').delete().in('id', saleIds);

    // 3. Restore Stock
    const updatedProductList = [...products];
    let productsUpdated = false;

    salesToDelete.forEach(sale => {
        sale.items.forEach(item => {
            if (item.type === 'product') {
                const productIndex = updatedProductList.findIndex(p => p.id === item.id);
                if (productIndex > -1) {
                    updatedProductList[productIndex] = {
                        ...updatedProductList[productIndex],
                        stock: updatedProductList[productIndex].stock + item.quantity
                    };
                    productsUpdated = true;
                }
            }
        });
    });

    if (productsUpdated) {
        setProducts(updatedProductList);
        await smartUpdateProducts(updatedProductList);
    }
  };

  // Danger: Wipe all sales
  const handlePurgeSales = async () => {
    setSales([]);
    const { error } = await supabase.from('sales').delete().neq('id', '0'); // Delete all rows
    if (error) console.error("Error purging sales:", error);
  };

  // Helper used by POS to quickly add customer without full list
  const handleAddCustomer = (newCustomer: Customer) => {
     smartUpdateCustomers([...customers, newCustomer]);
  };

  const handleAddExpense = async (newExpense: Expense) => {
      setExpenses([...expenses, newExpense]);
      // Assuming 'receipt_image' column exists in Supabase
      await supabase.from('expenses').insert({
          id: newExpense.id,
          date: newExpense.date,
          category: newExpense.category,
          amount: newExpense.amount,
          description: newExpense.description,
          receipt_image: newExpense.receiptImage
      });
  };

  const handleDeleteExpense = async (id: string) => {
      setExpenses(expenses.filter(e => e.id !== id));
      await supabase.from('expenses').delete().eq('id', id);
  };

  const handleUpdateSettings = async (newSettings: ShopSettings) => {
      setSettings(newSettings);
      await supabase.from('settings').upsert({ id: 1, data: newSettings });
  };


  // Dark Mode Effect
  useEffect(() => {
    if (isDarkMode) {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
    localStorage.setItem('trimtime_theme', isDarkMode ? 'dark' : 'light');
  }, [isDarkMode]);

  const toggleTheme = () => setIsDarkMode(!isDarkMode);

  // Dynamic Branding Effect (Title & Favicon)
  useEffect(() => {
    // 1. Update Document Title
    document.title = `${settings.shopName} | POS Manager`;

    // 2. Update Favicon with dynamic SVG based on first letter
    const updateFavicon = () => {
      const letter = (settings.shopName.charAt(0) || 'T').toUpperCase();
      const svg = `
        <svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 100 100'>
          <rect width='100' height='100' rx='25' fill='%23f59e0b'/>
          <text x='50' y='72' font-family='serif' font-weight='bold' font-size='65' text-anchor='middle' fill='white'>${letter}</text>
        </svg>
      `;

      let link = document.querySelector("link[rel~='icon']") as HTMLLinkElement;
      if (!link) {
        link = document.createElement('link');
        link.rel = 'icon';
        document.head.appendChild(link);
      }
      link.href = `data:image/svg+xml,${encodeURIComponent(svg)}`;
    };

    updateFavicon();
  }, [settings.shopName]);

  // Check for session expiry
  useEffect(() => {
    const checkSession = () => {
      const saved = localStorage.getItem('trimtime_session');
      if (saved) {
        try {
          const parsed = JSON.parse(saved);
          if (parsed.expiry && Date.now() > parsed.expiry) {
            handleLogout();
          }
        } catch (e) {
          // invalid session
        }
      }
    };
    checkSession();
    const interval = setInterval(checkSession, 60000); 
    return () => clearInterval(interval);
  }, []);

  const handleLogin = (user: Staff, rememberMe: boolean) => {
    const sessionDuration = rememberMe ? 30 * 24 * 60 * 60 * 1000 : 60 * 60 * 1000;
    const expiry = Date.now() + sessionDuration;
    localStorage.setItem('trimtime_session', JSON.stringify({ user, expiry }));
    setCurrentUser(user);

    // Employee Role Redirect Logic
    if (user.role === 'employee') {
      setCurrentView(View.POS);
    } else {
      setCurrentView(View.DASHBOARD);
    }
  };

  const handleLogout = () => {
    localStorage.removeItem('trimtime_session');
    setCurrentUser(null);
    setCurrentView(View.DASHBOARD);
  };

  const openProfile = () => {
    if (currentUser) {
      setProfileForm({
        name: currentUser.name,
        username: currentUser.username,
        email: currentUser.email || '',
        password: currentUser.password || ''
      });
      setIsProfileOpen(true);
    }
  };

  const updateProfile = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!currentUser) return;

    const updatedUser: Staff = {
      ...currentUser,
      name: profileForm.name,
      username: profileForm.username,
      email: profileForm.email,
      password: profileForm.password
    };

    const updatedStaffList = staff.map(s => s.id === currentUser.id ? updatedUser : s);
    setStaff(updatedStaffList);
    setCurrentUser(updatedUser);

    await supabase.from('staff').update({
        name: updatedUser.name,
        username: updatedUser.username,
        email: updatedUser.email,
        password: updatedUser.password
    }).eq('id', currentUser.id);

    const savedSession = localStorage.getItem('trimtime_session');
    if (savedSession) {
      const parsed = JSON.parse(savedSession);
      localStorage.setItem('trimtime_session', JSON.stringify({ ...parsed, user: updatedUser }));
    }

    setIsProfileOpen(false);
    alert('Profile updated successfully.');
  };

  const handleLanguageSwitch = (lang: Language) => {
    setSessionLanguage(lang);
    localStorage.setItem('trimtime_lang', lang);
  };

  // Update DOM when session language changes
  useEffect(() => {
    document.documentElement.lang = sessionLanguage;
    document.dir = sessionLanguage === 'ur' || sessionLanguage === 'fa' ? 'rtl' : 'ltr';
  }, [sessionLanguage]);

  if (loading) {
      return (
          <div className="flex h-screen items-center justify-center bg-slate-50 dark:bg-slate-950">
              <div className="animate-spin rounded-full h-12 w-12 border-t-2 border-b-2 border-amber-500"></div>
          </div>
      );
  }

  if (!currentUser) {
    return <Login onLogin={handleLogin} staffList={staff} shopName={settings.shopName} />;
  }

  return (
    <div className="flex h-screen bg-slate-50 dark:bg-slate-950 overflow-hidden relative transition-colors duration-300">
      <Sidebar 
        currentView={currentView}
        onViewChange={setCurrentView}
        shopName={settings.shopName}
        userRole={currentUser.role}
        isOpen={isSidebarOpen}
        onClose={() => setIsSidebarOpen(false)}
        language={sessionLanguage}
        onLanguageChange={handleLanguageSwitch}
      />

      <main className="flex-1 flex flex-col h-full relative md:pl-64 transition-all duration-300">
        {/* Mobile Header */}
        <div className="md:hidden flex items-center justify-between p-4 bg-white dark:bg-slate-900 border-b border-slate-100 dark:border-slate-800 z-50">
          <div className="flex items-center gap-3">
             <div className="w-8 h-8 bg-gradient-to-br from-amber-400 to-amber-600 rounded-lg flex items-center justify-center font-brand text-xl text-slate-950 shadow-lg">
                {settings.shopName.charAt(0)}
             </div>
             <span className="font-bold text-slate-900 dark:text-white truncate max-w-[150px]">{settings.shopName}</span>
          </div>
          <div className="flex items-center gap-2">
            <button 
              onClick={() => handleLanguageSwitch(sessionLanguage === 'en' ? 'ur' : sessionLanguage === 'ur' ? 'fa' : 'en')}
              className="p-2 text-slate-500 dark:text-slate-400 bg-slate-100 dark:bg-slate-800 rounded-lg font-black text-xs uppercase"
            >
              {sessionLanguage}
            </button>
            <button 
              onClick={toggleTheme}
              className="p-2 text-slate-500 dark:text-slate-400 bg-slate-100 dark:bg-slate-800 rounded-lg"
            >
              {isDarkMode ? (
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 3v1m0 16v1m9-9h-1M4 12H3m15.364 6.364l-.707-.707M6.343 6.343l-.707-.707m12.728 0l-.707.707M6.343 17.657l-.707.707M16 12a4 4 0 11-8 0 4 4 0 018 0z"/></svg>
              ) : (
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M20.354 15.354A9 9 0 018.646 3.646 9.003 9.003 0 0012 21a9.003 9.003 0 008.354-5.646z"/></svg>
              )}
            </button>
            <button onClick={() => setIsSidebarOpen(true)} className="p-2 text-slate-500">
              <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 6h16M4 12h16m-7 6h7"/></svg>
            </button>
          </div>
        </div>

        {/* Top Bar (Desktop) */}
        <div className="hidden md:flex justify-between items-center py-6 px-8 no-print">
            <h1 className="text-2xl font-black text-slate-900 dark:text-white font-brand tracking-tight">
               {currentView === View.DASHBOARD && (sessionLanguage === 'en' ? 'Dashboard' : sessionLanguage === 'ur' ? 'ڈیش بورڈ' : 'داشبورد')}
               {currentView === View.POS && (sessionLanguage === 'en' ? 'Point of Sale' : sessionLanguage === 'ur' ? 'پوائنٹ آف سیل' : 'پایانه فروش')}
               {currentView === View.INVENTORY && (sessionLanguage === 'en' ? 'Inventory Management' : sessionLanguage === 'ur' ? 'انوینٹری' : 'مدیریت موجودی')}
               {currentView === View.CUSTOMERS && (sessionLanguage === 'en' ? 'Client Directory' : sessionLanguage === 'ur' ? 'صارفین کی فہرست' : 'فهرست مشتریان')}
               {currentView === View.FINANCE && (sessionLanguage === 'en' ? 'Financial Overview' : sessionLanguage === 'ur' ? 'مالیاتی جائزہ' : 'بررسی مالی')}
               {currentView === View.STAFF && (sessionLanguage === 'en' ? 'Team Management' : sessionLanguage === 'ur' ? 'ٹیم مینجمنٹ' : 'مدیریت تیم')}
               {currentView === View.SETTINGS && (sessionLanguage === 'en' ? 'Configuration' : sessionLanguage === 'ur' ? 'ترتیبات' : 'پیکربندی')}
            </h1>
            <div className="flex items-center gap-4">

               {/* Language Switcher */}
               <div className="relative group">
                 <button className="flex items-center gap-2 bg-white dark:bg-slate-900 text-slate-600 dark:text-slate-300 p-2.5 rounded-xl border border-slate-200 dark:border-slate-800 transition-colors shadow-sm font-bold text-xs uppercase">
                    <span>{sessionLanguage === 'en' ? '🇺🇸 EN' : sessionLanguage === 'ur' ? '🇵🇰 UR' : '🇮🇷 FA'}</span>
                    <svg className="w-3 h-3 text-slate-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 9l-7 7-7-7" /></svg>
                 </button>
                 <div className="absolute top-full right-0 mt-2 w-32 bg-white dark:bg-slate-900 border border-slate-100 dark:border-slate-800 rounded-xl shadow-xl overflow-hidden hidden group-hover:block z-50">
                    <button onClick={() => handleLanguageSwitch('en')} className="w-full text-left px-4 py-3 hover:bg-slate-50 dark:hover:bg-slate-800 text-xs font-bold text-slate-600 dark:text-slate-300 flex justify-between">
                       English <span>🇺🇸</span>
                    </button>
                    <button onClick={() => handleLanguageSwitch('ur')} className="w-full text-left px-4 py-3 hover:bg-slate-50 dark:hover:bg-slate-800 text-xs font-bold text-slate-600 dark:text-slate-300 flex justify-between">
                       Urdu <span>🇵🇰</span>
                    </button>
                    <button onClick={() => handleLanguageSwitch('fa')} className="w-full text-left px-4 py-3 hover:bg-slate-50 dark:hover:bg-slate-800 text-xs font-bold text-slate-600 dark:text-slate-300 flex justify-between">
                       Persian <span>🇮🇷</span>
                    </button>
                 </div>
               </div>

               <button 
                onClick={toggleTheme}
                className="bg-white dark:bg-slate-900 text-slate-400 dark:text-slate-500 hover:text-amber-500 dark:hover:text-amber-400 p-2.5 rounded-xl border border-slate-200 dark:border-slate-800 transition-colors shadow-sm"
                title={isDarkMode ? "Switch to Light Mode" : "Switch to Dark Mode"}
               >
                 {isDarkMode ? (
                   <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 3v1m0 16v1m9-9h-1M4 12H3m15.364 6.364l-.707-.707M6.343 6.343l-.707-.707m12.728 0l-.707.707M6.343 17.657l-.707.707M16 12a4 4 0 11-8 0 4 4 0 018 0z"/></svg>
                 ) : (
                   <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M20.354 15.354A9 9 0 018.646 3.646 9.003 9.003 0 0012 21a9.003 9.003 0 008.354-5.646z"/></svg>
                 )}
               </button>

               <div 
                  onClick={openProfile}
                  className="flex items-center gap-3 cursor-pointer hover:bg-slate-200 dark:hover:bg-slate-800/50 p-2 rounded-xl transition-colors -mr-2"
                  title="Edit Profile"
               >
                 <div className="flex flex-col items-end">
                    <span className="font-bold text-sm text-slate-900 dark:text-white">{currentUser.name}</span>
                    <span className="text-[10px] font-black uppercase text-slate-400 dark:text-slate-500 tracking-widest">{currentUser.role}</span>
                 </div>
                 <div className="w-10 h-10 rounded-full bg-slate-200 dark:bg-slate-800 flex items-center justify-center text-slate-500 dark:text-slate-400 font-black shadow-inner">
                    {currentUser.name.charAt(0)}
                 </div>
               </div>
               <button 
                onClick={handleLogout}
                className="bg-slate-100 dark:bg-slate-800 text-slate-500 dark:text-slate-400 hover:text-rose-500 dark:hover:text-rose-500 p-2.5 rounded-xl transition-colors"
                title="Logout"
               >
                 <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M17 16l4-4m0 0l-4-4m4 4H7m6 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h4a3 3 0 013 3v1"/></svg>
               </button>
            </div>
        </div>

        <div className="flex-1 overflow-y-auto overflow-x-hidden p-4 md:p-8 scroll-smooth" id="main-content">
          <AnimatePresence mode='wait'>
            <motion.div
              key={currentView}
              initial={{ opacity: 0, y: 10 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0, y: -10 }}
              transition={{ duration: 0.2 }}
              className="h-full"
            >
              {currentView === View.DASHBOARD && <Dashboard sales={sales} expenses={expenses} currency={settings.currency} language={sessionLanguage} />}
              {currentView === View.POS && (
                <POS 
                  services={services} 
                  products={products} 
                  staff={staff} 
                  customers={customers}
                  settings={settings}
                  currentUser={currentUser}
                  onCompleteSale={handleCompleteSale}
                  onAddCustomer={handleAddCustomer}
                />
              )}
              {currentView === View.FINANCE && (
                <Finance 
                  sales={sales} 
                  expenses={expenses} 
                  staffList={staff}
                  onAddExpense={handleAddExpense}
                  onDeleteExpense={handleDeleteExpense}
                  onDeleteSale={handleDeleteSale}
                  onDeleteSales={handleBulkDeleteSales}
                  currentUser={currentUser}
                  customers={customers}
                  currency={settings.currency}
                  language={sessionLanguage}
                  billingCycleDay={settings.billingCycleDay || 1}
                  pendingSharedExpense={pendingSharedExpense}
                  onClearSharedExpense={() => setPendingSharedExpense(null)}
                />
              )}
              {currentView === View.CUSTOMERS && (
                <Customers 
                  customers={customers} 
                  sales={sales} 
                  onUpdateCustomers={smartUpdateCustomers}
                  currency={settings.currency}
                  language={sessionLanguage}
                />
              )}
              {currentView === View.INVENTORY && (
                <Inventory 
                  services={services} 
                  products={products} 
                  settings={{...settings, language: sessionLanguage}}
                  onUpdateServices={smartUpdateServices}
                  onUpdateProducts={smartUpdateProducts}
                />
              )}
              {currentView === View.STAFF && (
                <StaffManagement 
                  staffList={staff} 
                  onUpdateStaff={smartUpdateStaff} 
                  currentUser={currentUser}
                  language={sessionLanguage}
                />
              )}
              {currentView === View.SETTINGS && (
                <Settings 
                  settings={{...settings, language: sessionLanguage}} 
                  onUpdateSettings={handleUpdateSettings} 
                  currentUser={currentUser}
                  onPurgeSales={handlePurgeSales}
                />
              )}
            </motion.div>
          </AnimatePresence>
        </div>
      </main>

      {/* Profile Modal */}
      <AnimatePresence>
        {isProfileOpen && (
          <div className="fixed inset-0 bg-slate-950/40 backdrop-blur-sm z-[100] flex items-center justify-center p-4">
            <motion.div 
              initial={{ scale: 0.9, opacity: 0 }}
              animate={{ scale: 1, opacity: 1 }}
              exit={{ scale: 0.9, opacity: 0 }}
              className="bg-white dark:bg-slate-900 w-full max-w-md rounded-[2.5rem] p-8 shadow-2xl border border-slate-100 dark:border-slate-800"
            >
              <div className="flex justify-between items-center mb-8">
                <h3 className="text-2xl font-black text-slate-900 dark:text-white tracking-tight">My Profile</h3>
                <button onClick={() => setIsProfileOpen(false)} className="p-2 bg-slate-50 dark:bg-slate-800 rounded-full text-slate-400">
                  <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M6 18L18 6M6 6l12 12"/></svg>
                </button>
              </div>
              <form onSubmit={updateProfile} className="space-y-5">
                <div className="flex justify-center mb-6">
                   <div className="w-24 h-24 rounded-full bg-slate-100 dark:bg-slate-800 flex items-center justify-center text-4xl font-black text-slate-500 dark:text-slate-400 uppercase shadow-inner">
                      {currentUser?.name.charAt(0)}
                   </div>
                </div>
                <div>
                  <label className="text-[10px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest block mb-2 ml-1">Full Name</label>
                  <input 
                    type="text" 
                    value={profileForm.name} 
                    onChange={e => setProfileForm({...profileForm, name: e.target.value})} 
                    required 
                    className="w-full bg-slate-50 dark:bg-slate-800 border-0 rounded-2xl px-5 py-3.5 focus:ring-4 focus:ring-amber-500/10 outline-none text-sm font-bold dark:text-slate-200" 
                  />
                </div>
                <div>
                  <label className="text-[10px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest block mb-2 ml-1">Email</label>
                  <input 
                    type="email" 
                    value={profileForm.email} 
                    onChange={e => setProfileForm({...profileForm, email: e.target.value})} 
                    className="w-full bg-slate-50 dark:bg-slate-800 border-0 rounded-2xl px-5 py-3.5 focus:ring-4 focus:ring-amber-500/10 outline-none text-sm font-bold dark:text-slate-200" 
                  />
                </div>
                <div>
                  <label className="text-[10px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest block mb-2 ml-1">Username (Login ID)</label>
                  <input 
                    type="text" 
                    value={profileForm.username} 
                    onChange={e => setProfileForm({...profileForm, username: e.target.value})} 
                    required 
                    className="w-full bg-slate-50 dark:bg-slate-800 border-0 rounded-2xl px-5 py-3.5 focus:ring-4 focus:ring-amber-500/10 outline-none text-sm font-bold dark:text-slate-200" 
                  />
                </div>
                <div>
                  <label className="text-[10px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest block mb-2 ml-1">Password</label>
                  <div className="relative">
                    <input 
                      type={showProfilePassword ? "text" : "password"} 
                      value={profileForm.password} 
                      onChange={e => setProfileForm({...profileForm, password: e.target.value})} 
                      required 
                      className="w-full bg-slate-50 dark:bg-slate-800 border-0 rounded-2xl px-5 py-3.5 pr-12 focus:ring-4 focus:ring-amber-500/10 outline-none text-sm font-bold dark:text-slate-200" 
                    />
                    <button
                      type="button"
                      onClick={() => setShowProfilePassword(!showProfilePassword)}
                      className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-400 hover:text-slate-600 transition-colors"
                    >
                      {showProfilePassword ? (
                        <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z"/><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z"/></svg>
                      ) : (
                        <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13.875 18.825A10.05 10.05 0 0112 19c-4.478 0-8.268-2.943-9.543-7a9.97 9.97 0 011.563-3.029m5.858.908a3 3 0 114.243 4.243M9.878 9.878l4.242 4.242M9.88 9.88l-3.29-3.29m7.532 7.532l3.29 3.29M3 3l18 18"/></svg>
                      )}
                    </button>
                  </div>
                </div>
                <div className="flex gap-4 mt-8">
                  <button type="submit" className="flex-1 px-4 py-4 bg-slate-950 dark:bg-amber-500 text-white dark:text-slate-950 rounded-2xl font-black text-base hover:bg-slate-800 dark:hover:bg-amber-600 transition-all shadow-xl">
                    Save Changes
                  </button>
                </div>
              </form>
            </motion.div>
          </div>
        )}
      </AnimatePresence>
    </div>
  );
};

export default App;

export enum View {
  DASHBOARD = 'DASHBOARD',
  POS = 'POS',
  FINANCE = 'FINANCE',
  INVENTORY = 'INVENTORY',
  STAFF = 'STAFF',
  CUSTOMERS = 'CUSTOMERS',
  SETTINGS = 'SETTINGS'
}

export type UserRole = 'admin' | 'employee';

export interface User {
  id: string;
  name: string;
  username: string;
  role: UserRole;
}

export type Language = 'en' | 'ur' | 'fa';

export interface ShopSettings {
  shopName: string;
  currency: string;
  language: Language;
  whatsappEnabled: boolean;
  whatsappNumber: string;
  receiptFooter: string;
  taxRate: number;
  taxType: 'included' | 'excluded';
  billingCycleDay: number; // 1-31
  promoCodes: DiscountCode[];
}

export interface Service {
  id: string;
  name: string;
  price: number;
  duration: number; // minutes
  category: string;
}

export interface Product {
  id: string;
  name: string;
  price: number;
  cost: number;
  stock: number;
  barcode?: string;
  lowStockThreshold?: number; // Custom threshold for notifications
}

export interface Staff {
  id: string;
  name: string;
  role: UserRole;
  commission: number; // percentage
  username: string;
  password?: string;
  email?: string;
}

export interface Customer {
  id: string;
  name: string;
  phone: string;
  email: string;
  notes: string;
  createdAt: string;
}

export interface DiscountCode {
  code: string;
  type: 'percentage' | 'fixed';
  value: number;
  description: string;
}

export interface SaleItem {
  id: string;
  name: string;
  price: number;
  type: 'service' | 'product';
  quantity: number;
}

export interface Sale {
  id: string;
  timestamp: string;
  items: SaleItem[];
  staffId: string;
  customerId?: string;
  total: number;
  tax: number;
  discount: number;
  discountCode?: string;
  paymentMethod: 'cash' | 'card';
  taxType: 'included' | 'excluded';
}

export interface HeldSale {
  id: string;
  timestamp: string;
  cart: SaleItem[];
  customerId?: string;
  staffId?: string;
}

export interface Expense {
  id: string;
  date: string;
  category: string;
  amount: number;
  description: string;
  receiptImage?: string; // Base64 string of the receipt
}

import React, { useState, useRef, useEffect } from 'react';
import { Service, Product, ShopSettings } from '../types';
import { TRANSLATIONS } from '../constants';
import { motion, AnimatePresence } from 'framer-motion';
import { Html5Qrcode } from 'html5-qrcode';

interface InventoryProps {
  services: Service[];
  products: Product[];
  settings: ShopSettings;
  onUpdateServices: (services: Service[]) => void;
  onUpdateProducts: (products: Product[]) => void;
}

const Inventory: React.FC<InventoryProps> = ({ services, products, settings, onUpdateServices, onUpdateProducts }) => {
  const [activeTab, setActiveTab] = useState<'services' | 'products'>('services');
  const [isEditing, setIsEditing] = useState<any>(null);

  // Scanner state
  const [isScanning, setIsScanning] = useState(false);
  const html5QrCodeRef = useRef<Html5Qrcode | null>(null);
  const isScannerActiveRef = useRef(false);
  const barcodeInputRef = useRef<HTMLInputElement>(null);

  const t = TRANSLATIONS[settings.language];

  // Scanner Logic
  useEffect(() => {
    let isMounted = true;
    if (isScanning) {
        const startScanner = async () => {
            await new Promise(resolve => setTimeout(resolve, 300));
            if (!isMounted || !isScanning) return;
            if (html5QrCodeRef.current) return;

            try {
                const html5QrCode = new Html5Qrcode("reader-inventory");
                html5QrCodeRef.current = html5QrCode;

                await html5QrCode.start(
                    { facingMode: "environment" }, 
                    { 
                        fps: 10, 
                        qrbox: { width: 250, height: 150 },
                        aspectRatio: 1.0
                    }, 
                    (decodedText) => {
                        if (isMounted) {
                            if (barcodeInputRef.current) {
                                barcodeInputRef.current.value = decodedText;
                            }
                            setIsScanning(false);
                        }
                    },
                    (errorMessage) => {}
                );

                if (isMounted) {
                    isScannerActiveRef.current = true;
                } else {
                    if (html5QrCode.isScanning) {
                       await html5QrCode.stop();
                    }
                    html5QrCode.clear();
                    isScannerActiveRef.current = false;
                }
            } catch (err) {
                 console.error("Error starting scanner", err);
                 setIsScanning(false);
            }
        };
        startScanner();
    }
    return () => {
        isMounted = false;
        if (html5QrCodeRef.current) {
            const scanner = html5QrCodeRef.current;
            html5QrCodeRef.current = null;
            if (isScannerActiveRef.current) {
                scanner.stop().catch(console.warn).finally(() => {
                    try { scanner.clear(); } catch(e) {}
                    isScannerActiveRef.current = false;
                });
            } else {
                try { scanner.clear(); } catch(e) {}
            }
        }
    };
  }, [isScanning]);

  const deleteItem = (id: string, type: 'service' | 'product') => {
    if (!confirm('Permanently delete this entry?')) return;
    if (type === 'service') {
      onUpdateServices(services.filter(s => s.id !== id));
    } else {
      onUpdateProducts(products.filter(p => p.id !== id));
    }
  };

  const saveItem = (e: React.FormEvent) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget as HTMLFormElement);
    const itemData = Object.fromEntries(formData.entries());

    if (activeTab === 'services') {
      const newService: Service = {
        id: isEditing?.id || Math.random().toString(36).substr(2, 9).toUpperCase(),
        name: itemData.name as string,
        price: parseFloat(itemData.price as string),
        duration: parseInt(itemData.duration as string),
        category: itemData.category as string,
      };
      if (isEditing.id) {
        onUpdateServices(services.map(s => s.id === isEditing.id ? newService : s));
      } else {
        onUpdateServices([...services, newService]);
      }
    } else {
      const newProduct: Product = {
        id: isEditing?.id || Math.random().toString(36).substr(2, 9).toUpperCase(),
        name: itemData.name as string,
        price: parseFloat(itemData.price as string),
        cost: parseFloat(itemData.cost as string),
        stock: parseInt(itemData.stock as string),
        barcode: itemData.barcode as string || undefined,
        lowStockThreshold: parseInt(itemData.lowStockThreshold as string) || 15
      };
      if (isEditing.id) {
        onUpdateProducts(products.map(p => p.id === isEditing.id ? newProduct : p));
      } else {
        onUpdateProducts([...products, newProduct]);
      }
    }
    setIsEditing(null);
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
        <div>
          <h2 className="text-2xl md:text-3xl font-bold text-slate-800 dark:text-white font-brand">{t.shopCatalog}</h2>
          <p className="text-slate-500 dark:text-slate-400 text-sm">{t.updatePrices}</p>
        </div>
        <button 
          onClick={() => setIsEditing({})}
          className="bg-slate-950 dark:bg-slate-800 text-white px-6 py-3 rounded-xl font-black flex items-center gap-2 hover:bg-slate-800 transition-all shadow-lg text-sm w-full sm:w-auto justify-center"
        >
          <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M12 6v6m0 0v6m0-6h6m-6 0H6"/></svg>
          {activeTab === 'services' ? t.newService : t.newProduct}
        </button>
      </div>

      <div className="flex bg-white dark:bg-slate-900 p-1 rounded-xl shadow-sm border border-slate-100 dark:border-slate-800 self-start w-full sm:w-auto">
        <button 
          onClick={() => setActiveTab('services')}
          className={`flex-1 sm:px-8 py-2.5 rounded-lg font-bold transition-all text-xs md:text-sm ${activeTab === 'services' ? 'bg-amber-500 text-slate-950 shadow-sm' : 'text-slate-400 dark:text-slate-500 hover:text-slate-600 dark:hover:text-slate-400'}`}
        >
          {t.services}
        </button>
        <button 
          onClick={() => setActiveTab('products')}
          className={`flex-1 sm:px-8 py-2.5 rounded-lg font-bold transition-all text-xs md:text-sm ${activeTab === 'products' ? 'bg-amber-500 text-slate-950 shadow-sm' : 'text-slate-400 dark:text-slate-500 hover:text-slate-600 dark:hover:text-slate-400'}`}
        >
          {t.inventory}
        </button>
      </div>

      {/* Mobile View (Cards) */}
      <div className="md:hidden space-y-4">
        {activeTab === 'services' ? (
           services.map(s => (
             <div key={s.id} className="bg-white dark:bg-slate-900 p-5 rounded-2xl border border-slate-100 dark:border-slate-800 shadow-sm relative">
                <div className="flex justify-between items-start mb-4">
                   <div>
                     <h4 className="font-bold text-slate-800 dark:text-slate-200 text-lg">{s.name}</h4>
                     <p className="text-[10px] text-slate-400 dark:text-slate-600 font-mono tracking-tighter uppercase mt-1">{s.duration} {t.mins} {t.session}</p>
                   </div>
                   <span className="px-3 py-1 bg-amber-50 dark:bg-amber-900/20 text-amber-700 dark:text-amber-400 rounded-full text-[9px] font-black uppercase tracking-widest border border-amber-100 dark:border-amber-900/30">
                     {s.category}
                   </span>
                </div>
                <div className="flex justify-between items-center bg-slate-50 dark:bg-slate-800/50 p-3 rounded-xl">
                   <span className="text-xs font-bold text-slate-500 dark:text-slate-400 uppercase">{t.price}</span>
                   <span className="text-xl font-black text-slate-900 dark:text-white">{settings.currency}{s.price}</span>
                </div>
                <div className="grid grid-cols-2 gap-3 mt-4">
                    <button onClick={() => setIsEditing(s)} className="py-2.5 rounded-xl bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-300 font-bold text-sm hover:bg-slate-200 dark:hover:bg-slate-700 transition-colors">
                        Edit
                    </button>
                    <button onClick={() => deleteItem(s.id, 'service')} className="py-2.5 rounded-xl bg-rose-50 dark:bg-rose-900/20 text-rose-500 hover:bg-rose-100 dark:hover:bg-rose-900/40 transition-colors font-bold text-sm">
                        Delete
                    </button>
                </div>
             </div>
           ))
        ) : (
           products.map(p => {
            const isLowStock = p.stock <= (p.lowStockThreshold || 15);
            return (
            <div key={p.id} className={`bg-white dark:bg-slate-900 p-5 rounded-2xl border shadow-sm relative ${isLowStock ? 'border-rose-300 dark:border-rose-900/50 shadow-rose-100 dark:shadow-rose-900/10' : 'border-slate-100 dark:border-slate-800'}`}>
                <div className="flex justify-between items-start mb-4">
                   <div>
                     <h4 className="font-bold text-slate-800 dark:text-slate-200 text-lg flex items-center gap-2">
                        {p.name}
                        {isLowStock && <span className="text-rose-500 animate-pulse text-xs">⚠️</span>}
                     </h4>
                     <p className="text-[10px] text-slate-400 dark:text-slate-600 font-mono mt-1">{t.barcode}: {p.barcode || '---'}</p>
                   </div>
                   <span className={`px-2 py-1 rounded-lg text-[9px] font-black uppercase tracking-widest ${isLowStock ? 'bg-rose-50 dark:bg-rose-900/20 text-rose-500' : 'bg-emerald-50 dark:bg-emerald-900/20 text-emerald-500'}`}>
                      {p.stock} {t.unitsLeft}
                   </span>
                </div>
                <div className="grid grid-cols-2 gap-3 mb-4">
                    <div className="bg-slate-50 dark:bg-slate-800/50 p-3 rounded-xl">
                        <p className="text-[9px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest mb-1">{t.cost}</p>
                        <p className="font-bold text-slate-700 dark:text-slate-300">{settings.currency}{p.cost}</p>
                    </div>
                    <div className="bg-slate-50 dark:bg-slate-800/50 p-3 rounded-xl">
                        <p className="text-[9px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest mb-1">{t.price}</p>
                        <p className="font-black text-slate-900 dark:text-white">{settings.currency}{p.price}</p>
                    </div>
                </div>
                <div className="grid grid-cols-2 gap-3">
                    <button onClick={() => setIsEditing(p)} className="py-2.5 rounded-xl bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-300 font-bold text-sm hover:bg-slate-200 dark:hover:bg-slate-700 transition-colors">
                        Edit
                    </button>
                    <button onClick={() => deleteItem(p.id, 'product')} className="py-2.5 rounded-xl bg-rose-50 dark:bg-rose-900/20 text-rose-500 hover:bg-rose-100 dark:hover:bg-rose-900/40 transition-colors font-bold text-sm">
                        Delete
                    </button>
                </div>
            </div>
           )})
        )}
      </div>

      {/* Desktop View (Table) */}
      <div className="hidden md:block bg-white dark:bg-slate-900 rounded-[2rem] border border-slate-100 dark:border-slate-800 shadow-sm overflow-hidden">
        <div className="overflow-x-auto scrollbar-hide">
          <table className="w-full text-left min-w-[600px]">
            <thead>
              <tr className="bg-slate-50/50 dark:bg-slate-800/50 border-b border-slate-100 dark:border-slate-800 text-[10px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest">
                <th className="px-8 py-5">{t.itemDetails}</th>
                <th className="px-8 py-5">{activeTab === 'services' ? t.category : t.stockStatus}</th>
                <th className="px-8 py-5">{t.price}</th>
                <th className="px-8 py-5 text-right">{t.actions}</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-50 dark:divide-slate-800">
              {activeTab === 'services' ? (
                services.map(s => (
                  <tr key={s.id} className="hover:bg-slate-50/30 dark:hover:bg-slate-800/30 transition-colors">
                    <td className="px-8 py-6">
                      <p className="font-bold text-slate-800 dark:text-slate-200 text-sm">{s.name}</p>
                      <p className="text-[10px] text-slate-400 dark:text-slate-600 font-mono tracking-tighter uppercase">{s.duration} {t.mins} {t.session}</p>
                    </td>
                    <td className="px-8 py-6">
                      <span className="px-3 py-1 bg-amber-50 dark:bg-amber-900/20 text-amber-700 dark:text-amber-400 rounded-full text-[9px] font-black uppercase tracking-widest border border-amber-100 dark:border-amber-900/30">{s.category}</span>
                    </td>
                    <td className="px-8 py-6 font-black text-slate-950 dark:text-white">{settings.currency}{s.price}</td>
                    <td className="px-8 py-6 text-right space-x-2">
                      <button onClick={() => setIsEditing(s)} className="p-2 text-slate-300 dark:text-slate-600 hover:text-amber-500 transition-colors"><svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z"/></svg></button>
                      <button onClick={() => deleteItem(s.id, 'service')} className="p-2 text-slate-300 dark:text-slate-600 hover:text-rose-500 transition-colors"><svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"/></svg></button>
                    </td>
                  </tr>
                ))
              ) : (
                products.map(p => {
                  const isLowStock = p.stock <= (p.lowStockThreshold || 15);
                  return (
                  <tr key={p.id} className="hover:bg-slate-50/30 dark:hover:bg-slate-800/30 transition-colors">
                    <td className="px-8 py-6">
                      <div className="flex items-center gap-2">
                        <div>
                            <p className="font-bold text-slate-800 dark:text-slate-200 text-sm">{p.name}</p>
                            <p className="text-[10px] text-slate-400 dark:text-slate-600 font-mono">{t.barcode}: {p.barcode || '---'}</p>
                        </div>
                        {isLowStock && (
                            <span className="bg-rose-100 text-rose-500 text-[10px] font-bold px-2 py-0.5 rounded-full animate-pulse">Low Stock</span>
                        )}
                      </div>
                    </td>
                    <td className="px-8 py-6">
                      <div className="flex flex-col gap-1">
                        <p className="text-xs font-bold text-slate-800 dark:text-slate-300">{t.cost}: {settings.currency}{p.cost}</p>
                        <p className={`text-[10px] font-black uppercase tracking-widest ${isLowStock ? 'text-rose-500 dark:text-rose-400' : 'text-emerald-500 dark:text-emerald-400'}`}>
                           {p.stock} {t.unitsLeft} (Threshold: {p.lowStockThreshold || 15})
                        </p>
                      </div>
                    </td>
                    <td className="px-8 py-6 font-black text-slate-950 dark:text-white">{settings.currency}{p.price}</td>
                    <td className="px-8 py-6 text-right space-x-2">
                      <button onClick={() => setIsEditing(p)} className="p-2 text-slate-300 dark:text-slate-600 hover:text-amber-500 transition-colors"><svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z"/></svg></button>
                      <button onClick={() => deleteItem(p.id, 'product')} className="p-2 text-slate-300 dark:text-slate-600 hover:text-rose-500 transition-colors"><svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"/></svg></button>
                    </td>
                  </tr>
                )})
              )}
            </tbody>
          </table>
        </div>
      </div>

      <AnimatePresence>
        {isEditing && (
          <div className="fixed inset-0 bg-slate-950/40 backdrop-blur-sm z-[100] flex items-end sm:items-center justify-center p-0 sm:p-4">
            <motion.div 
              initial={{ y: "100%" }}
              animate={{ y: 0 }}
              exit={{ y: "100%" }}
              className="bg-white dark:bg-slate-900 rounded-t-[2.5rem] sm:rounded-[2.5rem] w-full max-w-md p-8 md:p-10 shadow-2xl overflow-y-auto max-h-[90vh]"
            >
              <div className="flex justify-between items-center mb-8">
                <h3 className="text-2xl font-black text-slate-900 dark:text-white tracking-tight">{isEditing.id ? t.editEntry : t.newEntry}</h3>
                <button onClick={() => setIsEditing(null)} className="p-2 bg-slate-50 dark:bg-slate-800 rounded-full text-slate-400">
                  <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M6 18L18 6M6 6l12 12"/></svg>
                </button>
              </div>
              <form onSubmit={saveItem} className="space-y-5">
                <div>
                  <label className="text-[10px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest block mb-2 ml-1">{t.labelName}</label>
                  <input name="name" type="text" defaultValue={isEditing.name || ''} required className="w-full bg-slate-50 dark:bg-slate-800 border-0 rounded-2xl px-5 py-3.5 focus:ring-4 focus:ring-amber-500/10 outline-none text-sm font-bold dark:text-slate-200" />
                </div>
                {activeTab === 'products' && (
                  <div>
                    <label className="text-[10px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest block mb-2 ml-1">{t.barcode}</label>
                    <div className="flex gap-2">
                        <input ref={barcodeInputRef} name="barcode" type="text" defaultValue={isEditing.barcode || ''} className="w-full bg-slate-50 dark:bg-slate-800 border-0 rounded-2xl px-5 py-3.5 focus:ring-4 focus:ring-amber-500/10 outline-none text-sm font-bold dark:text-slate-200" placeholder="" />
                        <button 
                            type="button"
                            onClick={() => setIsScanning(true)}
                            className="bg-slate-900 dark:bg-slate-800 text-white p-3.5 rounded-2xl hover:bg-slate-800 dark:hover:bg-slate-700 transition-colors"
                            title={t.scanBarcode}
                        >
                            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 4v1m6 11h2m-6 0h-2v4m0-11v3m0 0h.01M12 12h4.01M16 20h4M4 12h4m12 0h.01M5 8h2a1 1 0 001-1V5a1 1 0 00-1-1H5a1 1 0 00-1 1v2a1 1 0 001 1zm12 0h2a1 1 0 001-1V5a1 1 0 00-1-1h-2a1 1 0 00-1 1v2a1 1 0 001 1zM5 20h2a1 1 0 001-1v-2a1 1 0 00-1-1H5a1 1 0 00-1 1v2a1 1 0 001 1z"/></svg>
                        </button>
                    </div>
                  </div>
                )}
                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="text-[10px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest block mb-2 ml-1">{t.price} ({settings.currency})</label>
                    <input name="price" type="number" step="0.01" defaultValue={isEditing.price || ''} required className="w-full bg-slate-50 dark:bg-slate-800 border-0 rounded-2xl px-5 py-3.5 focus:ring-4 focus:ring-amber-500/10 outline-none text-sm font-bold dark:text-slate-200" />
                  </div>
                  {activeTab === 'services' ? (
                    <div>
                      <label className="text-[10px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest block mb-2 ml-1">{t.mins}</label>
                      <input name="duration" type="number" defaultValue={isEditing.duration || 30} required className="w-full bg-slate-50 dark:bg-slate-800 border-0 rounded-2xl px-5 py-3.5 focus:ring-4 focus:ring-amber-500/10 outline-none text-sm font-bold dark:text-slate-200" />
                    </div>
                  ) : (
                    <div>
                      <label className="text-[10px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest block mb-2 ml-1">{t.cost} ({settings.currency})</label>
                      <input name="cost" type="number" step="0.01" defaultValue={isEditing.cost || ''} required className="w-full bg-slate-50 dark:bg-slate-800 border-0 rounded-2xl px-5 py-3.5 focus:ring-4 focus:ring-amber-500/10 outline-none text-sm font-bold dark:text-slate-200" />
                    </div>
                  )}
                </div>
                {activeTab === 'services' ? (
                  <div>
                    <label className="text-[10px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest block mb-2 ml-1">{t.category}</label>
                    <input name="category" type="text" defaultValue={isEditing.category || ''} required className="w-full bg-slate-50 dark:bg-slate-800 border-0 rounded-2xl px-5 py-3.5 focus:ring-4 focus:ring-amber-500/10 outline-none text-sm font-bold dark:text-slate-200" />
                  </div>
                ) : (
                  <div className="grid grid-cols-2 gap-4">
                    <div>
                      <label className="text-[10px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest block mb-2 ml-1">{t.initialStock}</label>
                      <input name="stock" type="number" defaultValue={isEditing.stock || 0} required className="w-full bg-slate-50 dark:bg-slate-800 border-0 rounded-2xl px-5 py-3.5 focus:ring-4 focus:ring-amber-500/10 outline-none text-sm font-bold dark:text-slate-200" />
                    </div>
                    <div>
                      <label className="text-[10px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest block mb-2 ml-1">{t.alertQty}</label>
                      <input name="lowStockThreshold" type="number" defaultValue={isEditing.lowStockThreshold || 15} required className="w-full bg-slate-50 dark:bg-slate-800 border-0 rounded-2xl px-5 py-3.5 focus:ring-4 focus:ring-amber-500/10 outline-none text-sm font-bold dark:text-slate-200" />
                    </div>
                  </div>
                )}
                <div className="flex gap-4 mt-8">
                  <button type="submit" className="flex-1 px-4 py-4 bg-slate-950 dark:bg-amber-500 text-white dark:text-slate-950 rounded-2xl font-black text-base hover:bg-slate-800 dark:hover:bg-amber-600 transition-all shadow-xl">
                    {t.saveChanges}
                  </button>
                </div>
              </form>
            </motion.div>
          </div>
        )}
      </AnimatePresence>

