import React, { useState, useEffect } from 'react';
import Sidebar from './components/Sidebar';
import Dashboard from './components/Dashboard';
import POS from './components/POS';
import Finance from './components/Finance';
import Customers from './components/Customers';
import Settings from './components/Settings';
import Inventory from './components/Inventory';
import StaffManagement from './components/StaffManagement';
import Login from './components/Login';
import { View, Sale, Expense, Service, Product, Staff, Customer, ShopSettings, Language } from './types';
import { INITIAL_SERVICES, INITIAL_PRODUCTS, INITIAL_STAFF, INITIAL_EXPENSES, INITIAL_CUSTOMERS, DEFAULT_SETTINGS } from './constants';
import { motion, AnimatePresence } from 'framer-motion';
import { supabase } from './supabaseClient';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<Staff | null>(() => {
    const saved = localStorage.getItem('trimtime_session');
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        if (parsed.user && parsed.expiry) {
           if (Date.now() < parsed.expiry) return parsed.user;
           return null;
        }
        return parsed.user || parsed;
      } catch (e) {
        return null;
      }
    }
    return null;
  });

  // Initialize view based on user role (Employees -> POS, Admin -> Dashboard)
  const [currentView, setCurrentView] = useState<View>(
    currentUser?.role === 'employee' ? View.POS : View.DASHBOARD
  );

  const [isSidebarOpen, setIsSidebarOpen] = useState(false);

  // Initialize state empty, will load from Supabase
  const [services, setServices] = useState<Service[]>([]);
  const [products, setProducts] = useState<Product[]>([]);
  const [staff, setStaff] = useState<Staff[]>([]);
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [sales, setSales] = useState<Sale[]>([]);
  const [settings, setSettings] = useState<ShopSettings>(DEFAULT_SETTINGS);
  const [loading, setLoading] = useState(true);

  // Shared Receipt Logic
  const [pendingSharedExpense, setPendingSharedExpense] = useState<{ image: string } | null>(null);

  // Language State (Session based, separate from Global Shop Default)
  const [sessionLanguage, setSessionLanguage] = useState<Language>(() => {
    const local = localStorage.getItem('trimtime_lang');
    return (local as Language) || 'en';
  });

  // Profile Modal State
  const [isProfileOpen, setIsProfileOpen] = useState(false);
  const [profileForm, setProfileForm] = useState({
    name: '',
    username: '',
    email: '',
    password: ''
  });
  const [showProfilePassword, setShowProfilePassword] = useState(false);

  // Dark Mode State
  const [isDarkMode, setIsDarkMode] = useState(() => {
    const saved = localStorage.getItem('trimtime_theme');
    if (saved) return saved === 'dark';
    return window.matchMedia('(prefers-color-scheme: dark)').matches;
  });

  // Request Notification Permission
  useEffect(() => {
    if ('Notification' in window && Notification.permission !== 'granted') {
      Notification.requestPermission();
    }
  }, []);

  // --- HANDLE PWA SHARE TARGET ---
  useEffect(() => {
    const checkSharedFile = async () => {
        const urlParams = new URLSearchParams(window.location.search);
        if (urlParams.get('action') === 'add-expense' && urlParams.get('source') === 'share') {
            // Retrieve image from cache
            if ('caches' in window) {
                try {
                    const cache = await caches.open('trimtime-share');
                    const response = await cache.match('shared-receipt-image');
                    if (response) {
                        const blob = await response.blob();
                        // Convert blob to base64 for display/storage
                        const reader = new FileReader();
                        reader.onloadend = () => {
                            setPendingSharedExpense({ image: reader.result as string });
                            // Force view to finance to show modal
                            setCurrentView(View.FINANCE);
                            // Clean up cache
                            cache.delete('shared-receipt-image');
                            // Clean URL
                            window.history.replaceState({}, '', '/');
                        };
                        reader.readAsDataURL(blob);
                    }
                } catch (e) {
                    console.error("Error retrieving shared receipt", e);
                }
            }
        }
    };
    checkSharedFile();
  }, []);

  // --- SUPABASE FETCHING ---
  const fetchData = async () => {
    setLoading(true);
    try {
        const results = await Promise.all([
            supabase.from('services').select('*'),
            supabase.from('products').select('*'),
            supabase.from('staff').select('*'),
            supabase.from('expenses').select('*'),
            supabase.from('customers').select('*'),
            supabase.from('sales').select('*'),
            supabase.from('settings').select('*').single()
        ]);

        if (results[0].data) setServices(results[0].data);
        else setServices(INITIAL_SERVICES); 

        if (results[1].data) {
            const mappedProducts = results[1].data.map((p: any) => ({
                ...p,
                lowStockThreshold: p.low_stock_threshold // Map DB column to app property
            }));
            setProducts(mappedProducts);
        }
        else setProducts(INITIAL_PRODUCTS);

        if (results[2].data && results[2].data.length > 0) setStaff(results[2].data);
        else setStaff(INITIAL_STAFF);

        if (results[3].data) {
            // Map DB columns to type if receiptImage is stored in description or separately
            // Assuming for now receiptImage might be added to description JSON or new column. 
            // If new column 'receipt_image' exists in DB:
            const mappedExpenses = results[3].data.map((e: any) => ({
                ...e,
                receiptImage: e.receipt_image // Assuming column name matches logic
            }));
            setExpenses(mappedExpenses);
        }
        else setExpenses(INITIAL_EXPENSES);

        if (results[4].data) {
          // Map created_at to createdAt
          const mappedCustomers = results[4].data.map((c: any) => ({
             ...c,
             createdAt: c.created_at
          }));
          setCustomers(mappedCustomers);
        } else {
          setCustomers(INITIAL_CUSTOMERS);
        }

        if (results[5].data) {
            // Map snake_case DB columns to camelCase application properties
            const mappedSales = results[5].data.map((s: any) => ({
                id: s.id,
                timestamp: s.timestamp,
                items: typeof s.items === 'string' ? JSON.parse(s.items) : s.items,
                staffId: s.staff_id,
                customerId: s.customer_id,
                total: s.total,
                tax: s.tax,
                discount: s.discount,
                discountCode: s.discount_code,
                paymentMethod: s.payment_method,
                taxType: s.tax_type
            }));
            setSales(mappedSales);
        }

        // Merge defaults with fetched data to ensure all fields exist
        if (results[6].data && results[6].data.data) {
            const fetchedSettings = { ...DEFAULT_SETTINGS, ...results[6].data.data };
            setSettings(fetchedSettings);

            // If no local preference exists, use the shop default
            if (!localStorage.getItem('trimtime_lang')) {
                setSessionLanguage(fetchedSettings.language);
            }
        }
    } catch (error) {
        console.error("Error fetching data from Supabase:", error);
    } finally {
        setLoading(false);
    }
  };

  useEffect(() => {
    fetchData();
  }, []);

  // --- PERSISTENCE HANDLERS ---

  const smartUpdateServices = async (updatedList: Service[]) => {
      const idsInNewList = new Set(updatedList.map(i => i.id));
      const deletedIds = services.filter(s => !idsInNewList.has(s.id)).map(s => s.id);

      setServices(updatedList);

      if (deletedIds.length > 0) {
          await supabase.from('services').delete().in('id', deletedIds);
      }
      if (updatedList.length > 0) {
          await supabase.from('services').upsert(updatedList);
      }
  };

  const smartUpdateProducts = async (updatedList: Product[]) => {
      const idsInNewList = new Set(updatedList.map(i => i.id));
      const deletedIds = products.filter(p => !idsInNewList.has(p.id)).map(p => p.id);

      setProducts(updatedList);

      if (deletedIds.length > 0) {
          await supabase.from('products').delete().in('id', deletedIds);
      }
      // Upsert needs to map camelCase to snake_case if using direct object, or rely on supabase to handle matching if keys differ
      // Better to map explicitly to avoid errors if RLS or column mapping is strict
      const recordsToUpsert = updatedList.map(p => ({
          id: p.id,
          name: p.name,
          price: p.price,
          cost: p.cost,
          stock: p.stock,
          barcode: p.barcode,
          low_stock_threshold: p.lowStockThreshold
      }));

      if (recordsToUpsert.length > 0) {
          await supabase.from('products').upsert(recordsToUpsert);
      }
  };

  const smartUpdateStaff = async (updatedList: Staff[]) => {
      const idsInNewList = new Set(updatedList.map(i => i.id));
      const deletedIds = staff.filter(s => !idsInNewList.has(s.id)).map(s => s.id);

      setStaff(updatedList);

      // Sync with currentUser if the logged-in user is updated
      if (currentUser) {
        const updatedSelf = updatedList.find(s => s.id === currentUser.id);
        if (updatedSelf) {
            // Update state
            setCurrentUser(updatedSelf);
            // Update session storage
            const savedSession = localStorage.getItem('trimtime_session');
            if (savedSession) {
                try {
                    const parsed = JSON.parse(savedSession);
                    localStorage.setItem('trimtime_session', JSON.stringify({ ...parsed, user: updatedSelf }));
                } catch (e) {
                    console.error("Error updating session storage", e);
                }
            }
        }
      }

      if (deletedIds.length > 0) {
          await supabase.from('staff').delete().in('id', deletedIds);
      }
      if (updatedList.length > 0) {
          await supabase.from('staff').upsert(updatedList);
      }
  };

  // Customers: Update, Delete, Insert
  const smartUpdateCustomers = async (updatedList: Customer[]) => {
      const idsInNewList = new Set(updatedList.map(i => i.id));
      const deletedIds = customers.filter(c => !idsInNewList.has(c.id)).map(c => c.id);

      setCustomers(updatedList);

      if (deletedIds.length > 0) {
          await supabase.from('customers').delete().in('id', deletedIds);
      }

      // Map back to snake_case for DB
      const recordsToUpsert = updatedList.map(c => ({
          id: c.id,
          name: c.name,
          phone: c.phone,
          email: c.email,
          notes: c.notes,
          created_at: c.createdAt
      }));

      if (recordsToUpsert.length > 0) {
          await supabase.from('customers').upsert(recordsToUpsert);
      }
  };

  const handleCompleteSale = async (newSale: Sale) => {
      const updatedSales = [...sales, newSale];
      setSales(updatedSales);

      const { error } = await supabase.from('sales').insert({
          id: newSale.id,
          timestamp: newSale.timestamp,
          items: newSale.items, 
          staff_id: newSale.staffId,
          customer_id: newSale.customerId,
          total: newSale.total,
          tax: newSale.tax,
          discount: newSale.discount,
          discount_code: newSale.discountCode,
          payment_method: newSale.paymentMethod,
          tax_type: newSale.taxType
      });

      if (error) console.error("Error saving sale:", error);

      // Update product stock and Check for Notification
      newSale.items.forEach(async (item) => {
          if (item.type === 'product') {
              const product = products.find(p => p.id === item.id);
              if (product) {
                  const newStock = product.stock - item.quantity;
                  setProducts(prev => prev.map(p => p.id === product.id ? { ...p, stock: newStock } : p));
                  await supabase.from('products').update({ stock: newStock }).eq('id', product.id);

                  // Trigger Notification if stock drops below threshold
                  const threshold = product.lowStockThreshold || 15;
                  if (newStock <= threshold) {
                      if (Notification.permission === 'granted') {
                          new Notification('TrimTime Stock Alert', {
                              body: `⚠️ Low Stock: ${product.name} is down to ${newStock} units.`,
                              icon: 'https://placehold.co/192x192/f59e0b/ffffff?text=!'
                          });
                      }
                  }
              }
          }
      });
  };

  // Delete a sale and restore stock
  const handleDeleteSale = async (saleId: string) => {
    const saleToDelete = sales.find(s => s.id === saleId);
    if (!saleToDelete) return;

    // 1. Remove from Sales List
    setSales(prev => prev.filter(s => s.id !== saleId));

    // 2. Remove from DB
    await supabase.from('sales').delete().eq('id', saleId);

    // 3. Restore Stock for products involved
    let productsUpdated = false;
    const updatedProductList = [...products];

    saleToDelete.items.forEach(item => {
        if (item.type === 'product') {
            const productIndex = updatedProductList.findIndex(p => p.id === item.id);
            if (productIndex > -1) {
                updatedProductList[productIndex] = {
                    ...updatedProductList[productIndex],
                    stock: updatedProductList[productIndex].stock + item.quantity
                };
                productsUpdated = true;
            }
        }
    });

    if (productsUpdated) {
        setProducts(updatedProductList);
        await smartUpdateProducts(updatedProductList);
    }
  };

  // Bulk Delete Sales and Restore Stock
  const handleBulkDeleteSales = async (saleIds: string[]) => {
    const salesToDelete = sales.filter(s => saleIds.includes(s.id));
    if (salesToDelete.length === 0) return;

    // 1. Remove from Sales List
    setSales(prev => prev.filter(s => !saleIds.includes(s.id)));

    // 2. Remove from DB
    await supabase.from('sales').delete().in('id', saleIds);

    // 3. Restore Stock
    const updatedProductList = [...products];
    let productsUpdated = false;

    salesToDelete.forEach(sale => {
        sale.items.forEach(item => {
            if (item.type === 'product') {
                const productIndex = updatedProductList.findIndex(p => p.id === item.id);
                if (productIndex > -1) {
                    updatedProductList[productIndex] = {
                        ...updatedProductList[productIndex],
                        stock: updatedProductList[productIndex].stock + item.quantity
                    };
                    productsUpdated = true;
                }
            }
        });
    });

    if (productsUpdated) {
        setProducts(updatedProductList);
        await smartUpdateProducts(updatedProductList);
    }
  };

  // Danger: Wipe all sales
  const handlePurgeSales = async () => {
    setSales([]);
    const { error } = await supabase.from('sales').delete().neq('id', '0'); // Delete all rows
    if (error) console.error("Error purging sales:", error);
  };

  // Helper used by POS to quickly add customer without full list
  const handleAddCustomer = (newCustomer: Customer) => {
     smartUpdateCustomers([...customers, newCustomer]);
  };

  const handleAddExpense = async (newExpense: Expense) => {
      setExpenses([...expenses, newExpense]);
      // Assuming 'receipt_image' column exists in Supabase
      await supabase.from('expenses').insert({
          id: newExpense.id,
          date: newExpense.date,
          category: newExpense.category,
          amount: newExpense.amount,
          description: newExpense.description,
          receipt_image: newExpense.receiptImage
      });
  };

  const handleDeleteExpense = async (id: string) => {
      setExpenses(expenses.filter(e => e.id !== id));
      await supabase.from('expenses').delete().eq('id', id);
  };

  const handleUpdateSettings = async (newSettings: ShopSettings) => {
      setSettings(newSettings);
      await supabase.from('settings').upsert({ id: 1, data: newSettings });
  };


  // Dark Mode Effect
  useEffect(() => {
    if (isDarkMode) {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
    localStorage.setItem('trimtime_theme', isDarkMode ? 'dark' : 'light');
  }, [isDarkMode]);

  const toggleTheme = () => setIsDarkMode(!isDarkMode);

  // Dynamic Branding Effect (Title & Favicon)
  useEffect(() => {
    // 1. Update Document Title
    document.title = `${settings.shopName} | POS Manager`;

    // 2. Update Favicon with dynamic SVG based on first letter
    const updateFavicon = () => {
      const letter = (settings.shopName.charAt(0) || 'T').toUpperCase();
      const svg = `
        <svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 100 100'>
          <rect width='100' height='100' rx='25' fill='%23f59e0b'/>
          <text x='50' y='72' font-family='serif' font-weight='bold' font-size='65' text-anchor='middle' fill='white'>${letter}</text>
        </svg>
      `;

      let link = document.querySelector("link[rel~='icon']") as HTMLLinkElement;
      if (!link) {
        link = document.createElement('link');
        link.rel = 'icon';
        document.head.appendChild(link);
      }
      link.href = `data:image/svg+xml,${encodeURIComponent(svg)}`;
    };

    updateFavicon();
  }, [settings.shopName]);

  // Check for session expiry
  useEffect(() => {
    const checkSession = () => {
      const saved = localStorage.getItem('trimtime_session');
      if (saved) {
        try {
          const parsed = JSON.parse(saved);
          if (parsed.expiry && Date.now() > parsed.expiry) {
            handleLogout();
          }
        } catch (e) {
          // invalid session
        }
      }
    };
    checkSession();
    const interval = setInterval(checkSession, 60000); 
    return () => clearInterval(interval);
  }, []);

  const handleLogin = (user: Staff, rememberMe: boolean) => {
    const sessionDuration = rememberMe ? 30 * 24 * 60 * 60 * 1000 : 60 * 60 * 1000;
    const expiry = Date.now() + sessionDuration;
    localStorage.setItem('trimtime_session', JSON.stringify({ user, expiry }));
    setCurrentUser(user);

    // Employee Role Redirect Logic
    if (user.role === 'employee') {
      setCurrentView(View.POS);
    } else {
      setCurrentView(View.DASHBOARD);
    }
  };

  const handleLogout = () => {
    localStorage.removeItem('trimtime_session');
    setCurrentUser(null);
    setCurrentView(View.DASHBOARD);
  };

  const openProfile = () => {
    if (currentUser) {
      setProfileForm({
        name: currentUser.name,
        username: currentUser.username,
        email: currentUser.email || '',
        password: currentUser.password || ''
