               {currentView === View.POS && (sessionLanguage === 'en' ? 'Point of Sale' : sessionLanguage === 'ur' ? 'پوائنٹ آف سیل' : 'پایانه فروش')}
               {currentView === View.INVENTORY && (sessionLanguage === 'en' ? 'Inventory Management' : sessionLanguage === 'ur' ? 'انوینٹری' : 'مدیریت موجودی')}
               {currentView === View.CUSTOMERS && (sessionLanguage === 'en' ? 'Client Directory' : sessionLanguage === 'ur' ? 'صارفین کی فہرست' : 'فهرست مشتریان')}
               {currentView === View.FINANCE && (sessionLanguage === 'en' ? 'Financial Overview' : sessionLanguage === 'ur' ? 'مالیاتی جائزہ' : 'بررسی مالی')}
               {currentView === View.STAFF && (sessionLanguage === 'en' ? 'Team Management' : sessionLanguage === 'ur' ? 'ٹیم مینجمنٹ' : 'مدیریت تیم')}
               {currentView === View.SETTINGS && (sessionLanguage === 'en' ? 'Configuration' : sessionLanguage === 'ur' ? 'ترتیبات' : 'پیکربندی')}
            </h1>
            <div className="flex items-center gap-4">

               {/* Language Switcher */}
               <div className="relative group">
                 <button className="flex items-center gap-2 bg-white dark:bg-slate-900 text-slate-600 dark:text-slate-300 p-2.5 rounded-xl border border-slate-200 dark:border-slate-800 transition-colors shadow-sm font-bold text-xs uppercase">
                    <span>{sessionLanguage === 'en' ? '🇺🇸 EN' : sessionLanguage === 'ur' ? '🇵🇰 UR' : '🇮🇷 FA'}</span>
                    <svg className="w-3 h-3 text-slate-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 9l-7 7-7-7" /></svg>
                 </button>
                 <div className="absolute top-full right-0 mt-2 w-32 bg-white dark:bg-slate-900 border border-slate-100 dark:border-slate-800 rounded-xl shadow-xl overflow-hidden hidden group-hover:block z-50">
                    <button onClick={() => handleLanguageSwitch('en')} className="w-full text-left px-4 py-3 hover:bg-slate-50 dark:hover:bg-slate-800 text-xs font-bold text-slate-600 dark:text-slate-300 flex justify-between">
                       English <span>🇺🇸</span>
                    </button>
                    <button onClick={() => handleLanguageSwitch('ur')} className="w-full text-left px-4 py-3 hover:bg-slate-50 dark:hover:bg-slate-800 text-xs font-bold text-slate-600 dark:text-slate-300 flex justify-between">
                       Urdu <span>🇵🇰</span>
                    </button>
                    <button onClick={() => handleLanguageSwitch('fa')} className="w-full text-left px-4 py-3 hover:bg-slate-50 dark:hover:bg-slate-800 text-xs font-bold text-slate-600 dark:text-slate-300 flex justify-between">
                       Persian <span>🇮🇷</span>
                    </button>
                 </div>
               </div>

               <button 
                onClick={toggleTheme}
                className="bg-white dark:bg-slate-900 text-slate-400 dark:text-slate-500 hover:text-amber-500 dark:hover:text-amber-400 p-2.5 rounded-xl border border-slate-200 dark:border-slate-800 transition-colors shadow-sm"
                title={isDarkMode ? "Switch to Light Mode" : "Switch to Dark Mode"}
               >
                 {isDarkMode ? (
                   <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 3v1m0 16v1m9-9h-1M4 12H3m15.364 6.364l-.707-.707M6.343 6.343l-.707-.707m12.728 0l-.707.707M6.343 17.657l-.707.707M16 12a4 4 0 11-8 0 4 4 0 018 0z"/></svg>
                 ) : (
                   <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M20.354 15.354A9 9 0 018.646 3.646 9.003 9.003 0 0012 21a9.003 9.003 0 008.354-5.646z"/></svg>
                 )}
               </button>

               <div 
                  onClick={openProfile}
                  className="flex items-center gap-3 cursor-pointer hover:bg-slate-200 dark:hover:bg-slate-800/50 p-2 rounded-xl transition-colors -mr-2"
                  title="Edit Profile"
               >
                 <div className="flex flex-col items-end">
                    <span className="font-bold text-sm text-slate-900 dark:text-white">{currentUser.name}</span>
                    <span className="text-[10px] font-black uppercase text-slate-400 dark:text-slate-500 tracking-widest">{currentUser.role}</span>
