        {activeTab === 'expenses' && (
           <motion.div key="expenses" initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: -10 }} className="space-y-6">
              {/* Trigger for Expense Modal */}
              <div onClick={() => setIsExpenseModalOpen(true)} className="bg-white dark:bg-slate-900 p-8 rounded-[2.5rem] border border-slate-100 dark:border-slate-800 shadow-sm cursor-pointer hover:border-amber-200 dark:hover:border-amber-900 transition-colors group">
                 <div className="flex items-center justify-between">
                    <div className="flex items-center gap-4">
                        <div className="w-12 h-12 bg-amber-100 dark:bg-amber-900/20 text-amber-600 dark:text-amber-500 rounded-2xl flex items-center justify-center text-2xl group-hover:scale-110 transition-transform">
                            +
                        </div>
                        <div>
                            <h3 className="text-xl font-bold text-slate-800 dark:text-white">{t.addExpense}</h3>
                            <p className="text-sm text-slate-400">Record a new shop expense or upload a receipt.</p>
                        </div>
                    </div>
                    <div className="bg-slate-100 dark:bg-slate-800 px-4 py-2 rounded-xl text-xs font-black uppercase text-slate-500">
                        {t.newExpense}
