                      <tbody className="divide-y divide-slate-50 dark:divide-slate-800">
                        {expenses.sort((a,b) => b.date.localeCompare(a.date)).map(exp => (
                          <tr key={exp.id}>
                            <td className="px-6 py-4 text-xs font-bold flex items-center gap-2">
                                {exp.date}
                                {exp.receiptImage && (
                                    <span className="text-[10px] bg-indigo-50 dark:bg-indigo-900/20 text-indigo-600 px-1.5 py-0.5 rounded">Receipt</span>
                                )}
                            </td>
                            <td className="px-6 py-4 text-xs font-bold">{exp.category}</td>
                            <td className="px-6 py-4 text-right font-black text-rose-500">{currency}{exp.amount.toFixed(2)}</td>
                            <td className="px-6 py-4 text-center">
                              <button onClick={() => onDeleteExpense && onDeleteExpense(exp.id)} className="text-slate-300 hover:text-rose-500 transition-colors">
                                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" strokeLinecap="round" strokeLinejoin="round" strokeWidth="2"/></svg>
                              </button>
                            </td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                 </div>
              </div>
           </motion.div>
        )}
      </AnimatePresence>

      {/* Add/Edit Expense Modal */}
      <AnimatePresence>
        {isExpenseModalOpen && (
            <div className="fixed inset-0 bg-slate-950/60 backdrop-blur-sm z-[120] flex items-center justify-center p-4">
                <motion.div 
                    initial={{ scale: 0.9, opacity: 0 }} 
                    animate={{ scale: 1, opacity: 1 }} 
                    exit={{ scale: 0.9, opacity: 0 }} 
                    className="bg-white dark:bg-slate-900 w-full max-w-lg rounded-[2.5rem] p-8 shadow-2xl border border-slate-100 dark:border-slate-800 overflow-hidden"
                >
                    <div className="flex justify-between items-center mb-6">
                        <h3 className="text-xl font-black text-slate-900 dark:text-white">{newExpense.receiptImage ? 'Review Receipt Expense' : t.newExpense}</h3>
                        <button onClick={closeExpenseModal} className="p-2 bg-slate-50 dark:bg-slate-800 rounded-full text-slate-400">
                            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M6 18L18 6M6 6l12 12"/></svg>
                        </button>
                    </div>

                    <div className="space-y-5">
                        {newExpense.receiptImage && (
                            <div className="w-full h-48 bg-slate-100 dark:bg-slate-800 rounded-2xl overflow-hidden relative group">
                                <img src={newExpense.receiptImage} alt="Receipt" className="w-full h-full object-cover" />
                                <div className="absolute inset-0 bg-black/50 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity">
