import React, { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';

interface InstallBannerProps {
  deferredPrompt: any;
  onClose: () => void;
}

const InstallBanner: React.FC<InstallBannerProps> = ({ deferredPrompt, onClose }) => {
  const [isVisible, setIsVisible] = useState(false);
  const [isIOS, setIsIOS] = useState(false);

  useEffect(() => {
    // Check if already installed
    const isStandalone = window.matchMedia('(display-mode: standalone)').matches 
                         || (window.navigator as any).standalone 
                         || document.referrer.includes('android-app://');

    if (isStandalone) return;

    // Detect iOS
    const ios = /iPad|iPhone|iPod/.test(navigator.userAgent) && !(window as any).MSStream;
    setIsIOS(ios);

    // Show after 3 seconds
    const showTimer = setTimeout(() => setIsVisible(true), 3000);
    // Auto hide after 10 seconds total (7 seconds of visibility)
    const hideTimer = setTimeout(() => setIsVisible(false), 10000);

    return () => {
      clearTimeout(showTimer);
      clearTimeout(hideTimer);
    };
  }, []);

  const handleInstall = async () => {
    if (!deferredPrompt) return;
    deferredPrompt.prompt();
    const { outcome } = await deferredPrompt.userChoice;
    if (outcome === 'accepted') {
      setIsVisible(false);
    }
  };

  return (
    <AnimatePresence>
      {isVisible && (
        <motion.div
          initial={{ y: 100, opacity: 0 }}
          animate={{ y: 0, opacity: 1 }}
          exit={{ y: 100, opacity: 0 }}
          className="fixed bottom-6 left-4 right-4 md:left-auto md:right-8 md:w-96 z-[200]"
        >
          <div className="bg-slate-900 dark:bg-amber-500 text-white dark:text-slate-950 p-5 rounded-[2rem] shadow-2xl border border-white/10 flex items-center gap-4 relative overflow-hidden">
            {/* App Icon */}
            <div className="w-12 h-12 bg-amber-500 dark:bg-slate-900 rounded-2xl flex items-center justify-center text-slate-950 dark:text-amber-500 font-brand text-2xl font-black shrink-0 shadow-lg">
              T
            </div>

            <div className="flex-1 min-w-0">
              <h4 className="font-black text-sm tracking-tight">Install TrimTime</h4>
              <p className="text-[10px] opacity-80 font-medium leading-tight">
                {isIOS 
                  ? 'Tap Share then "Add to Home Screen"' 
                  : 'Add to your home screen for a faster, app-like experience.'}
              </p>
            </div>

            <div className="flex items-center gap-2">
              {!isIOS && deferredPrompt && (
                <button 
                  onClick={handleInstall}
                  className="bg-white dark:bg-slate-900 text-slate-900 dark:text-white px-4 py-2 rounded-xl text-[10px] font-black uppercase tracking-wider shadow-sm active:scale-95 transition-transform"
                >
                  Install
                </button>
              )}
              <button 
                onClick={() => setIsVisible(false)}
                className="p-2 hover:bg-white/10 rounded-full transition-colors"
              >
                <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M6 18L18 6M6 6l12 12" />
                </svg>
              </button>
            </div>

            {/* iOS Indicator Arrow (Optional Visual Aid) */}
            {isIOS && (
               <div className="absolute -bottom-1 left-1/2 -translate-x-1/2 text-white dark:text-slate-900 animate-bounce">
                  <svg className="w-4 h-4" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M5.293 7.293a1 1 0 011.414 0L10 10.586l3.293-3.293a1 1 0 111.414 1.414l-4 4a1 1 0 01-1.414 0l-4-4a1 1 0 010-1.414z" clipRule="evenodd" /></svg>
               </div>
            )}
          </div>
        </motion.div>
      )}
    </AnimatePresence>
  );
};

export default InstallBanner;

import React, { useState, useEffect } from 'react';
import Sidebar from './components/Sidebar';
import Dashboard from './components/Dashboard';
import POS from './components/POS';
import Finance from './components/Finance';
import Customers from './components/Customers';
import Settings from './components/Settings';
import Inventory from './components/Inventory';
import StaffManagement from './components/StaffManagement';
import Login from './components/Login';
import InstallBanner from './components/InstallBanner';
import { View, Sale, Expense, Service, Product, Staff, Customer, ShopSettings, Language } from './types';
import { INITIAL_SERVICES, INITIAL_PRODUCTS, INITIAL_STAFF, INITIAL_EXPENSES, INITIAL_CUSTOMERS, DEFAULT_SETTINGS } from './constants';
import { motion, AnimatePresence } from 'framer-motion';
import { supabase } from './supabaseClient';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<Staff | null>(() => {
    const saved = localStorage.getItem('trimtime_session');
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        if (parsed.user && parsed.expiry && Date.now() < parsed.expiry) return parsed.user;
      } catch (e) {}
    }
    return null;
  });

  const [currentView, setCurrentView] = useState<View>(
    currentUser?.role === 'employee' ? View.POS : View.DASHBOARD
  );

  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [loading, setLoading] = useState(true);
  const [services, setServices] = useState<Service[]>([]);
  const [products, setProducts] = useState<Product[]>([]);
  const [staff, setStaff] = useState<Staff[]>([]);
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [sales, setSales] = useState<Sale[]>([]);
  const [settings, setSettings] = useState<ShopSettings>(DEFAULT_SETTINGS);
  const [sessionLanguage, setSessionLanguage] = useState<Language>(() => (localStorage.getItem('trimtime_lang') as Language) || 'en');
  const [isDarkMode, setIsDarkMode] = useState(() => localStorage.getItem('trimtime_theme') === 'dark');

  // PWA Install States
  const [deferredPrompt, setDeferredPrompt] = useState<any>(null);

  useEffect(() => {
    const handleBeforeInstallPrompt = (e: Event) => {
      // Prevent Chrome 67 and earlier from automatically showing the prompt
      e.preventDefault();
      // Stash the event so it can be triggered later.
      setDeferredPrompt(e);
    };

    window.addEventListener('beforeinstallprompt', handleBeforeInstallPrompt);

    return () => {
      window.removeEventListener('beforeinstallprompt', handleBeforeInstallPrompt);
    };
  }, []);

  useEffect(() => {
    const fetchData = async () => {
      try {
        const [sv, pr, st, ex, cu, sa, se] = await Promise.all([
          supabase.from('services').select('*'),
          supabase.from('products').select('*'),
          supabase.from('staff').select('*'),
          supabase.from('expenses').select('*'),
          supabase.from('customers').select('*'),
          supabase.from('sales').select('*'),
          supabase.from('settings').select('*').single()
        ]);

        setServices(sv.data || INITIAL_SERVICES);
        setProducts((pr.data || INITIAL_PRODUCTS).map((p: any) => ({ ...p, lowStockThreshold: p.low_stock_threshold })));
        setStaff(st.data || INITIAL_STAFF);
        setExpenses((ex.data || INITIAL_EXPENSES).map((e: any) => ({ ...e, receiptImage: e.receipt_image })));
        setCustomers((cu.data || INITIAL_CUSTOMERS).map((c: any) => ({ ...c, createdAt: c.created_at })));
        setSales((sa.data || []).map((s: any) => ({ ...s, items: typeof s.items === 'string' ? JSON.parse(s.items) : s.items })));
        if (se.data?.data) setSettings({ ...DEFAULT_SETTINGS, ...se.data.data });
      } catch (e) { console.error(e); }
      finally { setLoading(false); }
    };
    fetchData();
  }, []);

  useEffect(() => {
    document.documentElement.classList.toggle('dark', isDarkMode);
    localStorage.setItem('trimtime_theme', isDarkMode ? 'dark' : 'light');
  }, [isDarkMode]);

  useEffect(() => {
    document.documentElement.lang = sessionLanguage;
    document.dir = ['ur', 'fa'].includes(sessionLanguage) ? 'rtl' : 'ltr';
    localStorage.setItem('trimtime_lang', sessionLanguage);
  }, [sessionLanguage]);

  const handleLogin = (user: Staff, remember: boolean) => {
    const expiry = Date.now() + (remember ? 30 : 1) * 24 * 60 * 60 * 1000;
    localStorage.setItem('trimtime_session', JSON.stringify({ user, expiry }));
    setCurrentUser(user);
    setCurrentView(user.role === 'employee' ? View.POS : View.DASHBOARD);
  };

  const handleLogout = () => {
    localStorage.removeItem('trimtime_session');
    setCurrentUser(null);
  };

  if (loading) return <div className="h-screen w-full flex items-center justify-center bg-slate-950"><div className="animate-spin rounded-full h-12 w-12 border-t-2 border-amber-500"></div></div>;
  if (!currentUser) return <Login onLogin={handleLogin} staffList={staff} shopName={settings.shopName} />;

  return (
    <div className="flex h-screen bg-slate-50 dark:bg-slate-950 overflow-hidden font-sans transition-colors duration-300">
      <Sidebar 
        currentView={currentView} onViewChange={setCurrentView} 
        shopName={settings.shopName} userRole={currentUser.role} 
        isOpen={isSidebarOpen} onClose={() => setIsSidebarOpen(false)}
        language={sessionLanguage} onLanguageChange={setSessionLanguage}
      />

      <div className="flex-1 flex flex-col min-w-0 md:pl-64 overflow-hidden relative">
        {/* Responsive Header */}
        <header className="flex md:hidden items-center justify-between p-4 bg-white dark:bg-slate-900 border-b border-slate-100 dark:border-slate-800 z-50 sticky top-0 shadow-sm">
          <div className="flex items-center gap-2">
             <div className="w-8 h-8 bg-amber-500 rounded-lg flex items-center justify-center font-brand text-lg text-slate-950">{settings.shopName.charAt(0)}</div>
             <span className="font-bold text-slate-900 dark:text-white truncate max-w-[120px]">{settings.shopName}</span>
          </div>
          <div className="flex gap-2">
            <button onClick={() => setIsDarkMode(!isDarkMode)} className="p-2 text-slate-400 bg-slate-50 dark:bg-slate-800 rounded-lg">
              {isDarkMode ? '🌞' : '🌙'}
            </button>
            <button onClick={() => setIsSidebarOpen(true)} className="p-2 text-slate-900 dark:text-white bg-amber-500 rounded-lg">
              <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M4 6h16M4 12h16m-7 6h7"/></svg>
            </button>
          </div>
        </header>

        {/* Desktop Header */}
        <header className="hidden md:flex justify-between items-center px-8 py-6 no-print">
            <h1 className="text-2xl font-black text-slate-900 dark:text-white font-brand">{tView(currentView, sessionLanguage)}</h1>
            <div className="flex items-center gap-4">
               <button onClick={() => setIsDarkMode(!isDarkMode)} className="p-2.5 bg-white dark:bg-slate-900 text-slate-400 rounded-xl border border-slate-200 dark:border-slate-800">
                 {isDarkMode ? '🌞' : '🌙'}
               </button>
               <div className="flex items-center gap-3 bg-white dark:bg-slate-900 p-1.5 pr-4 rounded-full border border-slate-100 dark:border-slate-800 shadow-sm">
                  <div className="w-8 h-8 rounded-full bg-amber-500 flex items-center justify-center font-black text-slate-950 text-xs">{currentUser.name.charAt(0)}</div>
                  <div className="flex flex-col"><span className="text-xs font-bold dark:text-white">{currentUser.name}</span><span className="text-[9px] uppercase font-black text-slate-400">{currentUser.role}</span></div>
               </div>
               <button onClick={handleLogout} className="p-2.5 bg-slate-100 dark:bg-slate-800 text-slate-500 rounded-xl">🚪</button>
            </div>
        </header>

        <main className="flex-1 overflow-y-auto p-4 md:p-8 relative scrollbar-hide">
          <AnimatePresence mode='wait'>
            <motion.div key={currentView} initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: -10 }} className="h-full">
              {renderView(currentView, { 
                sales, expenses, products, services, staff, customers, settings, 
                currentUser, sessionLanguage, isDarkMode, setSales, setProducts, setExpenses, 
                setCustomers, setServices, setStaff, setCurrentView, handleLogout
              })}
            </motion.div>
          </AnimatePresence>
        </main>
      </div>

      <InstallBanner 
        deferredPrompt={deferredPrompt} 
        onClose={() => setDeferredPrompt(null)} 
      />
    </div>
  );
};

const tView = (v: View, l: Language) => {
  const map: any = { 
    en: { [View.DASHBOARD]: 'Dashboard', [View.POS]: 'Terminal', [View.FINANCE]: 'Finances', [View.INVENTORY]: 'Catalog', [View.STAFF]: 'Staff', [View.CUSTOMERS]: 'Clients', [View.SETTINGS]: 'Settings' },
    ur: { [View.DASHBOARD]: 'ڈیش بورڈ', [View.POS]: 'ٹرمینل', [View.FINANCE]: 'مالیات', [View.INVENTORY]: 'کیٹلاگ', [View.STAFF]: 'عملہ', [View.CUSTOMERS]: 'صارفین', [View.SETTINGS]: 'ترتیبات' }
  };
  return map[l]?.[v] || map['en'][v];
};

const renderView = (v: View, props: any) => {
  const { sales, expenses, products, services, staff, customers, settings, currentUser, sessionLanguage, setCurrentView, setSales, setExpenses, setCustomers, setProducts, setServices, setStaff } = props;
  switch (v) {
    case View.DASHBOARD: return <Dashboard sales={sales} expenses={expenses} products={products} currency={settings.currency} language={sessionLanguage} onNavigate={setCurrentView} />;
    case View.POS: return <POS services={services} products={products} staff={staff} customers={customers} settings={settings} currentUser={currentUser} onCompleteSale={s => setSales([...sales, s])} onAddCustomer={c => setCustomers([...customers, c])} />;
    case View.FINANCE: return <Finance sales={sales} expenses={expenses} staffList={staff} customers={customers} currency={settings.currency} language={sessionLanguage} currentUser={currentUser} onAddExpense={e => setExpenses([...expenses, e])} onDeleteExpense={id => setExpenses(expenses.filter(x => x.id !== id))} />;
    case View.CUSTOMERS: return <Customers customers={customers} sales={sales} onUpdateCustomers={setCustomers} currency={settings.currency} language={sessionLanguage} />;
    case View.INVENTORY: return <Inventory services={services} products={products} settings={{...settings, language: sessionLanguage}} onUpdateServices={setServices} onUpdateProducts={setProducts} />;
    case View.STAFF: return <StaffManagement staffList={staff} onUpdateStaff={setStaff} currentUser={currentUser} language={sessionLanguage} />;
    case View.SETTINGS: return <Settings settings={{...settings, language: sessionLanguage}} onUpdateSettings={s => props.setSettings(s)} currentUser={currentUser} />;
    default: return null;
  }
};

export default App;

