const CACHE_NAME = 'trimtime-v3';
const urlsToCache = [
  '/',
  '/index.html',
  '/manifest.json'
];

self.addEventListener('install', event => {
  event.waitUntil(
    caches.open(CACHE_NAME).then(cache => cache.addAll(urlsToCache))
  );
  self.skipWaiting();
});

self.addEventListener('activate', event => {
  event.waitUntil(
    caches.keys().then(keys => Promise.all(
      keys.filter(key => key !== CACHE_NAME).map(key => caches.delete(key))
    ))
  );
  self.clients.claim();
});

self.addEventListener('fetch', event => {
  if (event.request.method !== 'GET') return;

  event.respondWith(
    caches.match(event.request).then(cachedResponse => {
      if (cachedResponse) return cachedResponse;

      return fetch(event.request).then(response => {
        if (!response || response.status !== 200 || response.type !== 'basic') {
          return response;
        }
        const responseToCache = response.clone();
        caches.open(CACHE_NAME).then(cache => {
          cache.put(event.request, responseToCache);
        });
        return response;
      }).catch(() => {
        // Fallback for navigation requests
        if (event.request.mode === 'navigate') {
          return caches.match('/');
        }
      });
    })
  );
});

import React, { useState, useEffect } from 'react';
import Sidebar from './components/Sidebar';
import Dashboard from './components/Dashboard';
import POS from './components/POS';
import Finance from './components/Finance';
import Customers from './components/Customers';
import Settings from './components/Settings';
import Inventory from './components/Inventory';
import StaffManagement from './components/StaffManagement';
import Login from './components/Login';
import InstallBanner from './components/InstallBanner';
import { View, Sale, Expense, Service, Product, Staff, Customer, ShopSettings, Language } from './types';
import { INITIAL_SERVICES, INITIAL_PRODUCTS, INITIAL_STAFF, INITIAL_EXPENSES, INITIAL_CUSTOMERS, DEFAULT_SETTINGS } from './constants';
import { motion, AnimatePresence } from 'framer-motion';
import { supabase } from './supabaseClient';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<Staff | null>(() => {
    const saved = localStorage.getItem('trimtime_session');
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        if (parsed.user && parsed.expiry && Date.now() < parsed.expiry) return parsed.user;
      } catch (e) {}
    }
    return null;
  });

  const [currentView, setCurrentView] = useState<View>(
    currentUser?.role === 'employee' ? View.POS : View.DASHBOARD
  );

  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [loading, setLoading] = useState(true);
  const [services, setServices] = useState<Service[]>([]);
  const [products, setProducts] = useState<Product[]>([]);
  const [staff, setStaff] = useState<Staff[]>([]);
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [sales, setSales] = useState<Sale[]>([]);
  const [settings, setSettings] = useState<ShopSettings>(DEFAULT_SETTINGS);
  const [sessionLanguage, setSessionLanguage] = useState<Language>(() => (localStorage.getItem('trimtime_lang') as Language) || 'en');
  const [isDarkMode, setIsDarkMode] = useState(() => localStorage.getItem('trimtime_theme') === 'dark');

  // PWA Install States
  const [deferredPrompt, setDeferredPrompt] = useState<any>(null);

  useEffect(() => {
    const handleBeforeInstallPrompt = (e: Event) => {
      e.preventDefault();
      setDeferredPrompt(e);
    };
    window.addEventListener('beforeinstallprompt', handleBeforeInstallPrompt);
    return () => window.removeEventListener('beforeinstallprompt', handleBeforeInstallPrompt);
  }, []);

  useEffect(() => {
    const fetchData = async () => {
      try {
        const [sv, pr, st, ex, cu, sa, se] = await Promise.all([
          supabase.from('services').select('*'),
          supabase.from('products').select('*'),
          supabase.from('staff').select('*'),
          supabase.from('expenses').select('*'),
          supabase.from('customers').select('*'),
          supabase.from('sales').select('*'),
          supabase.from('settings').select('*').single()
        ]);

        if (sv.data) setServices(sv.data);
        else setServices(INITIAL_SERVICES);

        if (pr.data) setProducts(pr.data.map((p: any) => ({ ...p, lowStockThreshold: p.low_stock_threshold })));
        else setProducts(INITIAL_PRODUCTS);

        if (st.data) setStaff(st.data);
        else setStaff(INITIAL_STAFF);

        if (ex.data) setExpenses(ex.data.map((e: any) => ({ ...e, receiptImage: e.receipt_image })));
        else setExpenses(INITIAL_EXPENSES);

        if (cu.data) setCustomers(cu.data.map((c: any) => ({ ...c, createdAt: c.created_at })));
        else setCustomers(INITIAL_CUSTOMERS);

        if (sa.data) setSales(sa.data.map((s: any) => ({ ...s, items: typeof s.items === 'string' ? JSON.parse(s.items) : s.items })));

        if (se.data?.data) setSettings({ ...DEFAULT_SETTINGS, ...se.data.data });
      } catch (e) { console.error(e); }
      finally { setLoading(false); }
    };
    fetchData();
  }, []);

  useEffect(() => {
    document.documentElement.classList.toggle('dark', isDarkMode);
    localStorage.setItem('trimtime_theme', isDarkMode ? 'dark' : 'light');
  }, [isDarkMode]);

  useEffect(() => {
    document.documentElement.lang = sessionLanguage;
    document.dir = ['ur', 'fa'].includes(sessionLanguage) ? 'rtl' : 'ltr';
    localStorage.setItem('trimtime_lang', sessionLanguage);
  }, [sessionLanguage]);

  // --- DATA PERSISTENCE HANDLERS ---

  const handleUpdateServices = async (updated: Service[]) => {
    const current = services;
    setServices(updated);

    const keepIds = new Set(updated.map(i => i.id));
    const toDelete = current.filter(i => !keepIds.has(i.id)).map(i => i.id);

    if (toDelete.length) await supabase.from('services').delete().in('id', toDelete);
    if (updated.length) await supabase.from('services').upsert(updated);
  };

  const handleUpdateProducts = async (updated: Product[]) => {
    const current = products;
    setProducts(updated);

    const keepIds = new Set(updated.map(i => i.id));
    const toDelete = current.filter(i => !keepIds.has(i.id)).map(i => i.id);

    const dbRows = updated.map(p => ({
        id: p.id,
        name: p.name,
        price: p.price,
        cost: p.cost,
        stock: p.stock,
        barcode: p.barcode,
        low_stock_threshold: p.lowStockThreshold
    }));

    if (toDelete.length) await supabase.from('products').delete().in('id', toDelete);
    if (dbRows.length) await supabase.from('products').upsert(dbRows);
  };

  const handleUpdateStaff = async (updated: Staff[]) => {
    const current = staff;
    setStaff(updated);

    const keepIds = new Set(updated.map(i => i.id));
    const toDelete = current.filter(i => !keepIds.has(i.id)).map(i => i.id);

    if (toDelete.length) await supabase.from('staff').delete().in('id', toDelete);
    if (updated.length) await supabase.from('staff').upsert(updated);
  };

  const handleUpdateCustomers = async (updated: Customer[]) => {
    const current = customers;
    setCustomers(updated);

    const keepIds = new Set(updated.map(i => i.id));
    const toDelete = current.filter(i => !keepIds.has(i.id)).map(i => i.id);

    const dbRows = updated.map(c => ({
        id: c.id,
        name: c.name,
        phone: c.phone,
        email: c.email,
        notes: c.notes,
        created_at: c.createdAt
    }));

    if (toDelete.length) await supabase.from('customers').delete().in('id', toDelete);
    if (dbRows.length) await supabase.from('customers').upsert(dbRows);
  };

  const handleUpdateSettings = async (updated: ShopSettings) => {
    setSettings(updated);
    await supabase.from('settings').upsert({ id: 1, data: updated });
  };

  const handleCompleteSale = async (sale: Sale) => {
    setSales([...sales, sale]);

    const dbSale = {
        id: sale.id,
        timestamp: sale.timestamp,
        items: sale.items, 
        staff_id: sale.staffId,
        customer_id: sale.customerId,
        total: sale.total,
        tax: sale.tax,
        discount: sale.discount,
        discount_code: sale.discountCode,
        payment_method: sale.paymentMethod,
        tax_type: sale.taxType
    };
    await supabase.from('sales').insert(dbSale);

    // Update product stock
    let productsUpdated = false;
    const newProducts = [...products];
    sale.items.forEach(item => {
        if (item.type === 'product') {
            const idx = newProducts.findIndex(p => p.id === item.id);
            if (idx > -1) {
                newProducts[idx] = { ...newProducts[idx], stock: newProducts[idx].stock - item.quantity };
                productsUpdated = true;
            }
        }
    });
    if (productsUpdated) handleUpdateProducts(newProducts);
  };

  const handleAddExpense = async (expense: Expense) => {
      setExpenses([...expenses, expense]);
      const dbExpense = {
          id: expense.id,
          date: expense.date,
          category: expense.category,
          amount: expense.amount,
          description: expense.description,
          receipt_image: expense.receiptImage
      };
      await supabase.from('expenses').insert(dbExpense);
  };

  const handleDeleteExpense = async (id: string) => {
      setExpenses(expenses.filter(e => e.id !== id));
      await supabase.from('expenses').delete().eq('id', id);
  };

  const handleLogin = (user: Staff, remember: boolean) => {
    const expiry = Date.now() + (remember ? 30 : 1) * 24 * 60 * 60 * 1000;
    localStorage.setItem('trimtime_session', JSON.stringify({ user, expiry }));
    setCurrentUser(user);
    setCurrentView(user.role === 'employee' ? View.POS : View.DASHBOARD);
  };

  const handleLogout = () => {
    localStorage.removeItem('trimtime_session');
    setCurrentUser(null);
  };

  if (loading) return <div className="h-screen w-full flex items-center justify-center bg-slate-950"><div className="animate-spin rounded-full h-12 w-12 border-t-2 border-amber-500"></div></div>;
  if (!currentUser) return <Login onLogin={handleLogin} staffList={staff} shopName={settings.shopName} />;

  return (
    <div className="flex h-screen bg-slate-50 dark:bg-slate-950 overflow-hidden font-sans transition-colors duration-300">
      <Sidebar 
        currentView={currentView} onViewChange={setCurrentView} 
        shopName={settings.shopName} userRole={currentUser.role} 
        isOpen={isSidebarOpen} onClose={() => setIsSidebarOpen(false)}
        language={sessionLanguage} onLanguageChange={setSessionLanguage}
      />

      <div className="flex-1 flex flex-col min-w-0 md:pl-64 overflow-hidden relative">
        {/* Responsive Header */}
        <header className="flex md:hidden items-center justify-between p-4 bg-white dark:bg-slate-900 border-b border-slate-100 dark:border-slate-800 z-50 sticky top-0 shadow-sm">
          <div className="flex items-center gap-2">
             <div className="w-8 h-8 bg-amber-500 rounded-lg flex items-center justify-center font-brand text-lg text-slate-950">{settings.shopName.charAt(0)}</div>
             <span className="font-bold text-slate-900 dark:text-white truncate max-w-[120px]">{settings.shopName}</span>
          </div>
          <div className="flex gap-2">
            <button onClick={() => setIsDarkMode(!isDarkMode)} className="p-2 text-slate-400 bg-slate-50 dark:bg-slate-800 rounded-lg">
              {isDarkMode ? '🌞' : '🌙'}
            </button>
            <button onClick={() => setIsSidebarOpen(true)} className="p-2 text-slate-900 dark:text-white bg-amber-500 rounded-lg">
              <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M4 6h16M4 12h16m-7 6h7"/></svg>
            </button>
          </div>
        </header>

        {/* Desktop Header */}
        <header className="hidden md:flex justify-between items-center px-8 py-6 no-print">
            <h1 className="text-2xl font-black text-slate-900 dark:text-white font-brand">{tView(currentView, sessionLanguage)}</h1>
            <div className="flex items-center gap-4">
               <button onClick={() => setIsDarkMode(!isDarkMode)} className="p-2.5 bg-white dark:bg-slate-900 text-slate-400 rounded-xl border border-slate-200 dark:border-slate-800">
                 {isDarkMode ? '🌞' : '🌙'}
               </button>
               <div className="flex items-center gap-3 bg-white dark:bg-slate-900 p-1.5 pr-4 rounded-full border border-slate-100 dark:border-slate-800 shadow-sm">
                  <div className="w-8 h-8 rounded-full bg-amber-500 flex items-center justify-center font-black text-slate-950 text-xs">{currentUser.name.charAt(0)}</div>
                  <div className="flex flex-col"><span className="text-xs font-bold dark:text-white">{currentUser.name}</span><span className="text-[9px] uppercase font-black text-slate-400">{currentUser.role}</span></div>
               </div>
               <button onClick={handleLogout} className="p-2.5 bg-slate-100 dark:bg-slate-800 text-slate-500 rounded-xl">🚪</button>
            </div>
        </header>

        <main className="flex-1 overflow-y-auto p-4 md:p-8 relative scrollbar-hide">
          <AnimatePresence mode='wait'>
            <motion.div key={currentView} initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: -10 }} className="h-full">
              {renderView(currentView, { 
                sales, expenses, products, services, staff, customers, settings, 
                currentUser, sessionLanguage, isDarkMode, 
                // DB Handlers
                onUpdateServices: handleUpdateServices,
                onUpdateProducts: handleUpdateProducts,
                onUpdateStaff: handleUpdateStaff,
                onUpdateCustomers: handleUpdateCustomers,
                onUpdateSettings: handleUpdateSettings,
                onCompleteSale: handleCompleteSale,
                onAddExpense: handleAddExpense,
                onDeleteExpense: handleDeleteExpense,

                setCurrentView, handleLogout
              })}
            </motion.div>
          </AnimatePresence>
        </main>
      </div>

      <InstallBanner 
        deferredPrompt={deferredPrompt} 
        onClose={() => setDeferredPrompt(null)} 
      />
    </div>
  );
};

const tView = (v: View, l: Language) => {
  const map: any = { 
    en: { [View.DASHBOARD]: 'Dashboard', [View.POS]: 'Terminal', [View.FINANCE]: 'Finances', [View.INVENTORY]: 'Catalog', [View.STAFF]: 'Staff', [View.CUSTOMERS]: 'Clients', [View.SETTINGS]: 'Settings' },
    ur: { [View.DASHBOARD]: 'ڈیش بورڈ', [View.POS]: 'ٹرمینل', [View.FINANCE]: 'مالیات', [View.INVENTORY]: 'کیٹلاگ', [View.STAFF]: 'عملہ', [View.CUSTOMERS]: 'صارفین', [View.SETTINGS]: 'ترتیبات' }
  };
  return map[l]?.[v] || map['en'][v];
};

const renderView = (v: View, props: any) => {
  const { sales, expenses, products, services, staff, customers, settings, currentUser, sessionLanguage, onUpdateServices, onUpdateProducts, onUpdateStaff, onUpdateCustomers, onUpdateSettings, onCompleteSale, onAddExpense, onDeleteExpense, setCurrentView } = props;
  switch (v) {
    case View.DASHBOARD: return <Dashboard sales={sales} expenses={expenses} products={products} currency={settings.currency} language={sessionLanguage} onNavigate={setCurrentView} />;
    case View.POS: return <POS services={services} products={products} staff={staff} customers={customers} settings={settings} currentUser={currentUser} onCompleteSale={onCompleteSale} onAddCustomer={c => onUpdateCustomers([...customers, c])} />;
    case View.FINANCE: return <Finance sales={sales} expenses={expenses} staffList={staff} customers={customers} currency={settings.currency} language={sessionLanguage} currentUser={currentUser} onAddExpense={onAddExpense} onDeleteExpense={onDeleteExpense} />;
    case View.CUSTOMERS: return <Customers customers={customers} sales={sales} onUpdateCustomers={onUpdateCustomers} currency={settings.currency} language={sessionLanguage} />;
    case View.INVENTORY: return <Inventory services={services} products={products} settings={{...settings, language: sessionLanguage}} onUpdateServices={onUpdateServices} onUpdateProducts={onUpdateProducts} />;
    case View.STAFF: return <StaffManagement staffList={staff} onUpdateStaff={onUpdateStaff} currentUser={currentUser} language={sessionLanguage} />;
    case View.SETTINGS: return <Settings settings={{...settings, language: sessionLanguage}} onUpdateSettings={onUpdateSettings} currentUser={currentUser} />;
    default: return null;
  }
};

export default App;

import React, { useState, useEffect } from 'react';
import Sidebar from './components/Sidebar';
import Dashboard from './components/Dashboard';
import POS from './components/POS';
import Finance from './components/Finance';
import Customers from './components/Customers';
import Settings from './components/Settings';
import Inventory from './components/Inventory';
import StaffManagement from './components/StaffManagement';
import Login from './components/Login';
import InstallBanner from './components/InstallBanner';
import { View, Sale, Expense, Service, Product, Staff, Customer, ShopSettings, Language } from './types';
import { INITIAL_SERVICES, INITIAL_PRODUCTS, INITIAL_STAFF, INITIAL_EXPENSES, INITIAL_CUSTOMERS, DEFAULT_SETTINGS } from './constants';
import { motion, AnimatePresence } from 'framer-motion';
import { supabase } from './supabaseClient';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<Staff | null>(() => {
    const saved = localStorage.getItem('trimtime_session');
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        if (parsed.user && parsed.expiry && Date.now() < parsed.expiry) return parsed.user;
      } catch (e) {}
    }
    return null;
  });

  const [currentView, setCurrentView] = useState<View>(
    currentUser?.role === 'employee' ? View.POS : View.DASHBOARD
  );

  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [loading, setLoading] = useState(true);
  const [services, setServices] = useState<Service[]>([]);
  const [products, setProducts] = useState<Product[]>([]);
  const [staff, setStaff] = useState<Staff[]>([]);
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [sales, setSales] = useState<Sale[]>([]);
  const [settings, setSettings] = useState<ShopSettings>(DEFAULT_SETTINGS);
  const [sessionLanguage, setSessionLanguage] = useState<Language>(() => (localStorage.getItem('trimtime_lang') as Language) || 'en');
  const [isDarkMode, setIsDarkMode] = useState(() => localStorage.getItem('trimtime_theme') === 'dark');

  // PWA Install States
  const [deferredPrompt, setDeferredPrompt] = useState<any>(null);

  useEffect(() => {
    const handleBeforeInstallPrompt = (e: Event) => {
      e.preventDefault();
      setDeferredPrompt(e);
    };
    window.addEventListener('beforeinstallprompt', handleBeforeInstallPrompt);
    return () => window.removeEventListener('beforeinstallprompt', handleBeforeInstallPrompt);
  }, []);

  useEffect(() => {
    const fetchData = async () => {
      try {
        const [sv, pr, st, ex, cu, sa, se] = await Promise.all([
          supabase.from('services').select('*'),
          supabase.from('products').select('*'),
          supabase.from('staff').select('*'),
          supabase.from('expenses').select('*'),
          supabase.from('customers').select('*'),
          supabase.from('sales').select('*'),
          supabase.from('settings').select('*').single()
        ]);

        if (sv.data) setServices(sv.data);
        else setServices(INITIAL_SERVICES);

        if (pr.data) setProducts(pr.data.map((p: any) => ({ ...p, lowStockThreshold: p.low_stock_threshold })));
        else setProducts(INITIAL_PRODUCTS);

        if (st.data) setStaff(st.data);
        else setStaff(INITIAL_STAFF);

        if (ex.data) setExpenses(ex.data.map((e: any) => ({ ...e, receiptImage: e.receipt_image })));
        else setExpenses(INITIAL_EXPENSES);

        if (cu.data) setCustomers(cu.data.map((c: any) => ({ ...c, createdAt: c.created_at })));
        else setCustomers(INITIAL_CUSTOMERS);

        if (sa.data) setSales(sa.data.map((s: any) => ({ ...s, items: typeof s.items === 'string' ? JSON.parse(s.items) : s.items })));

        if (se.data?.data) setSettings({ ...DEFAULT_SETTINGS, ...se.data.data });
      } catch (e) { console.error("Error loading data:", e); }
      finally { setLoading(false); }
    };
    fetchData();
  }, []);

  useEffect(() => {
    document.documentElement.classList.toggle('dark', isDarkMode);
    localStorage.setItem('trimtime_theme', isDarkMode ? 'dark' : 'light');
  }, [isDarkMode]);

  useEffect(() => {
    document.documentElement.lang = sessionLanguage;
    document.dir = ['ur', 'fa'].includes(sessionLanguage) ? 'rtl' : 'ltr';
    localStorage.setItem('trimtime_lang', sessionLanguage);
  }, [sessionLanguage]);

  // --- DATA PERSISTENCE HANDLERS ---

  const handleUpdateServices = async (updated: Service[]) => {
    // 1. Identify items to delete (present in current state but missing in updated)
    const currentIds = new Set(services.map(i => i.id));
    const newIds = new Set(updated.map(i => i.id));
    const toDelete = [...currentIds].filter(id => !newIds.has(id));

    // 2. Update Local State
    setServices(updated);

    // 3. Sync with DB
    try {
      if (toDelete.length) await supabase.from('services').delete().in('id', toDelete);
      if (updated.length) await supabase.from('services').upsert(updated);
    } catch (err) { console.error("DB Sync Error (Services):", err); }
  };

  const handleUpdateProducts = async (updated: Product[]) => {
    const currentIds = new Set(products.map(i => i.id));
    const newIds = new Set(updated.map(i => i.id));
    const toDelete = [...currentIds].filter(id => !newIds.has(id));

    setProducts(updated);

    // Map to snake_case for DB
    const dbRows = updated.map(p => ({
        id: p.id,
        name: p.name,
        price: p.price,
        cost: p.cost,
        stock: p.stock,
        barcode: p.barcode,
        low_stock_threshold: p.lowStockThreshold
    }));

    try {
      if (toDelete.length) await supabase.from('products').delete().in('id', toDelete);
      if (dbRows.length) await supabase.from('products').upsert(dbRows);
    } catch (err) { console.error("DB Sync Error (Products):", err); }
  };

  const handleUpdateStaff = async (updated: Staff[]) => {
    const currentIds = new Set(staff.map(i => i.id));
    const newIds = new Set(updated.map(i => i.id));
    const toDelete = [...currentIds].filter(id => !newIds.has(id));

    setStaff(updated);

    try {
      if (toDelete.length) await supabase.from('staff').delete().in('id', toDelete);
      if (updated.length) await supabase.from('staff').upsert(updated);
    } catch (err) { console.error("DB Sync Error (Staff):", err); }
  };

  const handleUpdateCustomers = async (updated: Customer[]) => {
    const currentIds = new Set(customers.map(i => i.id));
    const newIds = new Set(updated.map(i => i.id));
    const toDelete = [...currentIds].filter(id => !newIds.has(id));

    setCustomers(updated);

    const dbRows = updated.map(c => ({
        id: c.id,
        name: c.name,
        phone: c.phone,
        email: c.email,
        notes: c.notes,
        created_at: c.createdAt
    }));

    try {
      if (toDelete.length) await supabase.from('customers').delete().in('id', toDelete);
      if (dbRows.length) await supabase.from('customers').upsert(dbRows);
    } catch (err) { console.error("DB Sync Error (Customers):", err); }
  };

  const handleUpdateSettings = async (updated: ShopSettings) => {
    setSettings(updated);
    try {
      await supabase.from('settings').upsert({ id: 1, data: updated });
    } catch (err) { console.error("DB Sync Error (Settings):", err); }
  };

  const handleCompleteSale = async (sale: Sale) => {
    setSales(prev => [...prev, sale]);

    try {
      // Save Sale
      const dbSale = {
          id: sale.id,
          timestamp: sale.timestamp,
          items: sale.items, 
          staff_id: sale.staffId,
          customer_id: sale.customerId,
          total: sale.total,
          tax: sale.tax,
          discount: sale.discount,
          discount_code: sale.discountCode,
          payment_method: sale.paymentMethod,
          tax_type: sale.taxType
      };
      await supabase.from('sales').insert(dbSale);

      // Update Product Stock
      let productsUpdated = false;
      const newProducts = [...products];
      sale.items.forEach(item => {
          if (item.type === 'product') {
              const idx = newProducts.findIndex(p => p.id === item.id);
              if (idx > -1) {
                  newProducts[idx] = { ...newProducts[idx], stock: newProducts[idx].stock - item.quantity };
                  productsUpdated = true;
              }
          }
      });
      if (productsUpdated) handleUpdateProducts(newProducts);
    } catch (err) { console.error("DB Sync Error (Sale):", err); }
  };

  const handleAddExpense = async (expense: Expense) => {
      setExpenses(prev => [...prev, expense]);
      const dbExpense = {
          id: expense.id,
          date: expense.date,
          category: expense.category,
          amount: expense.amount,
          description: expense.description,
          receipt_image: expense.receiptImage
      };
      try {
        await supabase.from('expenses').insert(dbExpense);
      } catch (err) { console.error("DB Sync Error (Expense):", err); }
  };

  const handleDeleteExpense = async (id: string) => {
      setExpenses(prev => prev.filter(e => e.id !== id));
      try {
        await supabase.from('expenses').delete().eq('id', id);
      } catch (err) { console.error("DB Sync Error (Delete Expense):", err); }
  };

  const handleLogin = (user: Staff, remember: boolean) => {
    const expiry = Date.now() + (remember ? 30 : 1) * 24 * 60 * 60 * 1000;
    localStorage.setItem('trimtime_session', JSON.stringify({ user, expiry }));
    setCurrentUser(user);
    setCurrentView(user.role === 'employee' ? View.POS : View.DASHBOARD);
  };

  const handleLogout = () => {
    localStorage.removeItem('trimtime_session');
    setCurrentUser(null);
  };

  if (loading) return <div className="h-screen w-full flex items-center justify-center bg-slate-950"><div className="animate-spin rounded-full h-12 w-12 border-t-2 border-amber-500"></div></div>;
  if (!currentUser) return <Login onLogin={handleLogin} staffList={staff} shopName={settings.shopName} />;

  return (
    <div className="flex h-screen bg-slate-50 dark:bg-slate-950 overflow-hidden font-sans transition-colors duration-300">
      <Sidebar 
        currentView={currentView} onViewChange={setCurrentView} 
        shopName={settings.shopName} userRole={currentUser.role} 
        isOpen={isSidebarOpen} onClose={() => setIsSidebarOpen(false)}
        language={sessionLanguage} onLanguageChange={setSessionLanguage}
      />

      <div className="flex-1 flex flex-col min-w-0 md:pl-64 overflow-hidden relative">
        {/* Responsive Header */}
        <header className="flex md:hidden items-center justify-between p-4 bg-white dark:bg-slate-900 border-b border-slate-100 dark:border-slate-800 z-50 sticky top-0 shadow-sm">
          <div className="flex items-center gap-2">
             <div className="w-8 h-8 bg-amber-500 rounded-lg flex items-center justify-center font-brand text-lg text-slate-950">{settings.shopName.charAt(0)}</div>
             <span className="font-bold text-slate-900 dark:text-white truncate max-w-[120px]">{settings.shopName}</span>
          </div>
          <div className="flex gap-2">
            <button onClick={() => setIsDarkMode(!isDarkMode)} className="p-2 text-slate-400 bg-slate-50 dark:bg-slate-800 rounded-lg">
              {isDarkMode ? '🌞' : '🌙'}
            </button>
            <button onClick={() => setIsSidebarOpen(true)} className="p-2 text-slate-900 dark:text-white bg-amber-500 rounded-lg">
              <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M4 6h16M4 12h16m-7 6h7"/></svg>
            </button>
          </div>
        </header>

        {/* Desktop Header */}
        <header className="hidden md:flex justify-between items-center px-8 py-6 no-print">
            <h1 className="text-2xl font-black text-slate-900 dark:text-white font-brand">{tView(currentView, sessionLanguage)}</h1>
            <div className="flex items-center gap-4">
               <button onClick={() => setIsDarkMode(!isDarkMode)} className="p-2.5 bg-white dark:bg-slate-900 text-slate-400 rounded-xl border border-slate-200 dark:border-slate-800">
                 {isDarkMode ? '🌞' : '🌙'}
               </button>
               <div className="flex items-center gap-3 bg-white dark:bg-slate-900 p-1.5 pr-4 rounded-full border border-slate-100 dark:border-slate-800 shadow-sm">
                  <div className="w-8 h-8 rounded-full bg-amber-500 flex items-center justify-center font-black text-slate-950 text-xs">{currentUser.name.charAt(0)}</div>
                  <div className="flex flex-col"><span className="text-xs font-bold dark:text-white">{currentUser.name}</span><span className="text-[9px] uppercase font-black text-slate-400">{currentUser.role}</span></div>
               </div>
               <button onClick={handleLogout} className="p-2.5 bg-slate-100 dark:bg-slate-800 text-slate-500 rounded-xl">🚪</button>
            </div>
        </header>

        <main className="flex-1 overflow-y-auto p-4 md:p-8 relative scrollbar-hide">
          <AnimatePresence mode='wait'>
            <motion.div key={currentView} initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: -10 }} className="h-full">
              {renderView(currentView, { 
                sales, expenses, products, services, staff, customers, settings, 
                currentUser, sessionLanguage, isDarkMode, 
                // DB Handlers passed to children
                onUpdateServices: handleUpdateServices,
                onUpdateProducts: handleUpdateProducts,
                onUpdateStaff: handleUpdateStaff,
                onUpdateCustomers: handleUpdateCustomers,
                onUpdateSettings: handleUpdateSettings,
                onCompleteSale: handleCompleteSale,
                onAddExpense: handleAddExpense,
                onDeleteExpense: handleDeleteExpense,

                setCurrentView, handleLogout
              })}
            </motion.div>
          </AnimatePresence>
        </main>
      </div>

      <InstallBanner 
        deferredPrompt={deferredPrompt} 
        onClose={() => setDeferredPrompt(null)} 
      />
    </div>
  );
};

const tView = (v: View, l: Language) => {
  const map: any = { 
    en: { [View.DASHBOARD]: 'Dashboard', [View.POS]: 'Terminal', [View.FINANCE]: 'Finances', [View.INVENTORY]: 'Catalog', [View.STAFF]: 'Staff', [View.CUSTOMERS]: 'Clients', [View.SETTINGS]: 'Settings' },
    ur: { [View.DASHBOARD]: 'ڈیش بورڈ', [View.POS]: 'ٹرمینل', [View.FINANCE]: 'مالیات', [View.INVENTORY]: 'کیٹلاگ', [View.STAFF]: 'عملہ', [View.CUSTOMERS]: 'صارفین', [View.SETTINGS]: 'ترتیبات' }
  };
  return map[l]?.[v] || map['en'][v];
};

const renderView = (v: View, props: any) => {
  const { sales, expenses, products, services, staff, customers, settings, currentUser, sessionLanguage, onUpdateServices, onUpdateProducts, onUpdateStaff, onUpdateCustomers, onUpdateSettings, onCompleteSale, onAddExpense, onDeleteExpense, setCurrentView } = props;
  switch (v) {
    case View.DASHBOARD: return <Dashboard sales={sales} expenses={expenses} products={products} currency={settings.currency} language={sessionLanguage} onNavigate={setCurrentView} />;
    case View.POS: return <POS services={services} products={products} staff={staff} customers={customers} settings={settings} currentUser={currentUser} onCompleteSale={onCompleteSale} onAddCustomer={c => onUpdateCustomers([...customers, c])} />;
    case View.FINANCE: return <Finance sales={sales} expenses={expenses} staffList={staff} customers={customers} currency={settings.currency} language={sessionLanguage} currentUser={currentUser} onAddExpense={onAddExpense} onDeleteExpense={onDeleteExpense} />;
    case View.CUSTOMERS: return <Customers customers={customers} sales={sales} onUpdateCustomers={onUpdateCustomers} currency={settings.currency} language={sessionLanguage} />;
    case View.INVENTORY: return <Inventory services={services} products={products} settings={{...settings, language: sessionLanguage}} onUpdateServices={onUpdateServices} onUpdateProducts={onUpdateProducts} />;
    case View.STAFF: return <StaffManagement staffList={staff} onUpdateStaff={onUpdateStaff} currentUser={currentUser} language={sessionLanguage} />;
    case View.SETTINGS: return <Settings settings={{...settings, language: sessionLanguage}} onUpdateSettings={onUpdateSettings} currentUser={currentUser} />;
    default: return null;
  }
};

export default App;

import React, { useState, useRef, useEffect } from 'react';
import { Service, Product, ShopSettings } from '../types';
import { TRANSLATIONS } from '../constants';
import { motion, AnimatePresence } from 'framer-motion';
import { Html5Qrcode } from 'html5-qrcode';

interface InventoryProps {
  services: Service[];
  products: Product[];
  settings: ShopSettings;
  onUpdateServices: (services: Service[]) => void;
  onUpdateProducts: (products: Product[]) => void;
}

const Inventory: React.FC<InventoryProps> = ({ services, products, settings, onUpdateServices, onUpdateProducts }) => {
  const [activeTab, setActiveTab] = useState<'services' | 'products'>('services');
  const [isEditing, setIsEditing] = useState<any>(null);
  const [searchTerm, setSearchTerm] = useState('');

  // Scanner state
  const [isScanning, setIsScanning] = useState(false);
  const html5QrCodeRef = useRef<Html5Qrcode | null>(null);
  const isScannerActiveRef = useRef(false);
  const barcodeInputRef = useRef<HTMLInputElement>(null);

  const t = TRANSLATIONS[settings.language];

  // Filter Logic
  const filteredServices = services.filter(s => 
    s.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
    s.category.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const filteredProducts = products.filter(p => 
    p.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
    (p.barcode && p.barcode.includes(searchTerm))
  );

  // Scanner Logic
  useEffect(() => {
    let isMounted = true;
    if (isScanning) {
        const startScanner = async () => {
            await new Promise(resolve => setTimeout(resolve, 300));
            if (!isMounted || !isScanning) return;
            if (html5QrCodeRef.current) return;

            try {
                const html5QrCode = new Html5Qrcode("reader-inventory");
                html5QrCodeRef.current = html5QrCode;

                await html5QrCode.start(
                    { facingMode: "environment" }, 
                    { 
                        fps: 10, 
                        qrbox: { width: 250, height: 150 },
                        aspectRatio: 1.0
                    }, 
                    (decodedText) => {
                        if (isMounted) {
                            if (barcodeInputRef.current) {
                                barcodeInputRef.current.value = decodedText;
                            }
                            setIsScanning(false);
                        }
                    },
                    (errorMessage) => {}
                );

                if (isMounted) {
                    isScannerActiveRef.current = true;
                } else {
                    if (html5QrCode.isScanning) {
                       await html5QrCode.stop();
                    }
                    html5QrCode.clear();
                    isScannerActiveRef.current = false;
                }
            } catch (err) {
                 console.error("Error starting scanner", err);
                 setIsScanning(false);
            }
        };
        startScanner();
    }
    return () => {
        isMounted = false;
        if (html5QrCodeRef.current) {
            const scanner = html5QrCodeRef.current;
            html5QrCodeRef.current = null;
            if (isScannerActiveRef.current) {
                scanner.stop().catch(console.warn).finally(() => {
                    try { scanner.clear(); } catch(e) {}
                    isScannerActiveRef.current = false;
                });
            } else {
                try { scanner.clear(); } catch(e) {}
            }
        }
    };
  }, [isScanning]);

  const deleteItem = (id: string, type: 'service' | 'product') => {
    if (!confirm('Permanently delete this entry?')) return;
    if (type === 'service') {
      onUpdateServices(services.filter(s => s.id !== id));
    } else {
      onUpdateProducts(products.filter(p => p.id !== id));
    }
  };

  const saveItem = (e: React.FormEvent) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget as HTMLFormElement);
    const itemData = Object.fromEntries(formData.entries());

    if (activeTab === 'services') {
      const newService: Service = {
        id: isEditing?.id || Math.random().toString(36).substr(2, 9).toUpperCase(),
        name: itemData.name as string,
        price: parseFloat(itemData.price as string) || 0,
        duration: parseInt(itemData.duration as string) || 30,
        category: itemData.category as string,
      };
      if (isEditing.id) {
        onUpdateServices(services.map(s => s.id === isEditing.id ? newService : s));
      } else {
        onUpdateServices([...services, newService]);
      }
    } else {
      const newProduct: Product = {
        id: isEditing?.id || Math.random().toString(36).substr(2, 9).toUpperCase(),
        name: itemData.name as string,
        price: parseFloat(itemData.price as string) || 0,
        cost: parseFloat(itemData.cost as string) || 0,
        stock: parseInt(itemData.stock as string) || 0,
        barcode: (itemData.barcode as string) || undefined,
        lowStockThreshold: parseInt(itemData.lowStockThreshold as string) || 15
      };
      if (isEditing.id) {
        onUpdateProducts(products.map(p => p.id === isEditing.id ? newProduct : p));
      } else {
        onUpdateProducts([...products, newProduct]);
      }
    }
    setIsEditing(null);
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
        <div>
          <h2 className="text-2xl md:text-3xl font-bold text-slate-800 dark:text-white font-brand">{t.shopCatalog}</h2>
          <p className="text-slate-500 dark:text-slate-400 text-sm">{t.updatePrices}</p>
        </div>
        <button 
          onClick={() => setIsEditing({})}
          className="bg-slate-950 dark:bg-slate-800 text-white px-6 py-3 rounded-xl font-black flex items-center gap-2 hover:bg-slate-800 transition-all shadow-lg text-sm w-full sm:w-auto justify-center"
        >
          <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M12 6v6m0 0v6m0-6h6m-6 0H6"/></svg>
          {activeTab === 'services' ? t.newService : t.newProduct}
        </button>
      </div>

      {/* Search Bar */}
      <div className="relative">
        <svg className="w-5 h-5 absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 dark:text-slate-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z"/></svg>
        <input 
          type="text" 
          placeholder={t.searchCatalog}
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
          className="w-full bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-2xl py-3.5 pl-12 pr-6 outline-none focus:ring-4 focus:ring-amber-500/10 shadow-sm text-sm dark:text-slate-200 transition-all"
        />
      </div>

      <div className="flex bg-white dark:bg-slate-900 p-1 rounded-xl shadow-sm border border-slate-100 dark:border-slate-800 self-start w-full sm:w-auto">
        <button 
          onClick={() => setActiveTab('services')}
          className={`flex-1 sm:px-8 py-2.5 rounded-lg font-bold transition-all text-xs md:text-sm ${activeTab === 'services' ? 'bg-amber-500 text-slate-950 shadow-sm' : 'text-slate-400 dark:text-slate-500 hover:text-slate-600 dark:hover:text-slate-400'}`}
        >
          {t.services}
        </button>
        <button 
          onClick={() => setActiveTab('products')}
          className={`flex-1 sm:px-8 py-2.5 rounded-lg font-bold transition-all text-xs md:text-sm ${activeTab === 'products' ? 'bg-amber-500 text-slate-950 shadow-sm' : 'text-slate-400 dark:text-slate-500 hover:text-slate-600 dark:hover:text-slate-400'}`}
        >
          {t.inventory}
        </button>
      </div>

      {/* Mobile View (Cards) */}
      <div className="md:hidden space-y-4">
        {activeTab === 'services' ? (
           filteredServices.map(s => (
             <div key={s.id} className="bg-white dark:bg-slate-900 p-5 rounded-2xl border border-slate-100 dark:border-slate-800 shadow-sm relative">
                <div className="flex justify-between items-start mb-4">
                   <div>
                     <h4 className="font-bold text-slate-800 dark:text-slate-200 text-lg">{s.name}</h4>
                     <p className="text-[10px] text-slate-400 dark:text-slate-600 font-mono tracking-tighter uppercase mt-1">{s.duration} {t.mins} {t.session}</p>
                   </div>
                   <span className="px-3 py-1 bg-amber-50 dark:bg-amber-900/20 text-amber-700 dark:text-amber-400 rounded-full text-[9px] font-black uppercase tracking-widest border border-amber-100 dark:border-amber-900/30">
                     {s.category}
                   </span>
                </div>
                <div className="flex justify-between items-center bg-slate-50 dark:bg-slate-800/50 p-3 rounded-xl">
                   <span className="text-xs font-bold text-slate-500 dark:text-slate-400 uppercase">{t.price}</span>
                   <span className="text-xl font-black text-slate-900 dark:text-white">{settings.currency}{s.price}</span>
                </div>
                <div className="grid grid-cols-2 gap-3 mt-4">
                    <button onClick={() => setIsEditing(s)} className="py-2.5 rounded-xl bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-300 font-bold text-sm hover:bg-slate-200 dark:hover:bg-slate-700 transition-colors">
                        Edit
                    </button>
                    <button onClick={() => deleteItem(s.id, 'service')} className="py-2.5 rounded-xl bg-rose-50 dark:bg-rose-900/20 text-rose-500 hover:bg-rose-100 dark:hover:bg-rose-900/40 transition-colors font-bold text-sm">
                        Delete
                    </button>
                </div>
             </div>
           ))
        ) : (
           filteredProducts.map(p => {
            const isLowStock = p.stock <= (p.lowStockThreshold || 15);
            return (
            <div key={p.id} className={`bg-white dark:bg-slate-900 p-5 rounded-2xl border shadow-sm relative ${isLowStock ? 'border-rose-300 dark:border-rose-900/50 shadow-rose-100 dark:shadow-rose-900/10' : 'border-slate-100 dark:border-slate-800'}`}>
                <div className="flex justify-between items-start mb-4">
                   <div>
                     <h4 className="font-bold text-slate-800 dark:text-slate-200 text-lg flex items-center gap-2">
                        {p.name}
                        {isLowStock && <span className="text-rose-500 animate-pulse text-xs">⚠️</span>}
                     </h4>
                     <p className="text-[10px] text-slate-400 dark:text-slate-600 font-mono mt-1">{t.barcode}: {p.barcode || '---'}</p>
                   </div>
                   <span className={`px-2 py-1 rounded-lg text-[9px] font-black uppercase tracking-widest ${isLowStock ? 'bg-rose-50 dark:bg-rose-900/20 text-rose-500' : 'bg-emerald-50 dark:bg-emerald-900/20 text-emerald-500'}`}>
                      {p.stock} {t.unitsLeft}
                   </span>
                </div>
                <div className="grid grid-cols-2 gap-3 mb-4">
                    <div className="bg-slate-50 dark:bg-slate-800/50 p-3 rounded-xl">
                        <p className="text-[9px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest mb-1">{t.cost}</p>
                        <p className="font-bold text-slate-700 dark:text-slate-300">{settings.currency}{p.cost}</p>
                    </div>
                    <div className="bg-slate-50 dark:bg-slate-800/50 p-3 rounded-xl">
                        <p className="text-[9px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest mb-1">{t.price}</p>
                        <p className="font-black text-slate-900 dark:text-white">{settings.currency}{p.price}</p>
                    </div>
                </div>
                <div className="grid grid-cols-2 gap-3">
                    <button onClick={() => setIsEditing(p)} className="py-2.5 rounded-xl bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-300 font-bold text-sm hover:bg-slate-200 dark:hover:bg-slate-700 transition-colors">
                        Edit
                    </button>
                    <button onClick={() => deleteItem(p.id, 'product')} className="py-2.5 rounded-xl bg-rose-50 dark:bg-rose-900/20 text-rose-500 hover:bg-rose-100 dark:hover:bg-rose-900/40 transition-colors font-bold text-sm">
                        Delete
                    </button>
                </div>
            </div>
           )})
        )}
      </div>

      {/* Desktop View (Table) */}
      <div className="hidden md:block bg-white dark:bg-slate-900 rounded-[2rem] border border-slate-100 dark:border-slate-800 shadow-sm overflow-hidden">
        <div className="overflow-x-auto scrollbar-hide">
          <table className="w-full text-left min-w-[600px]">
            <thead>
              <tr className="bg-slate-50/50 dark:bg-slate-800/50 border-b border-slate-100 dark:border-slate-800 text-[10px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest">
                <th className="px-8 py-5">{t.itemDetails}</th>
                <th className="px-8 py-5">{activeTab === 'services' ? t.category : t.stockStatus}</th>
                <th className="px-8 py-5">{t.price}</th>
                <th className="px-8 py-5 text-right">{t.actions}</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-50 dark:divide-slate-800">
              {activeTab === 'services' ? (
                filteredServices.map(s => (
                  <tr key={s.id} className="hover:bg-slate-50/30 dark:hover:bg-slate-800/30 transition-colors">
                    <td className="px-8 py-6">
                      <p className="font-bold text-slate-800 dark:text-slate-200 text-sm">{s.name}</p>
                      <p className="text-[10px] text-slate-400 dark:text-slate-600 font-mono tracking-tighter uppercase">{s.duration} {t.mins} {t.session}</p>
                    </td>
                    <td className="px-8 py-6">
