  const [services, setServices] = useState<Service[]>([]);
  const [products, setProducts] = useState<Product[]>([]);
  const [staff, setStaff] = useState<Staff[]>([]);
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [sales, setSales] = useState<Sale[]>([]);
  const [settings, setSettings] = useState<ShopSettings>(DEFAULT_SETTINGS);
  const [sessionLanguage, setSessionLanguage] = useState<Language>(() => (localStorage.getItem('trimtime_lang') as Language) || 'en');
  const [isDarkMode, setIsDarkMode] = useState(() => localStorage.getItem('trimtime_theme') === 'dark');

  // PWA Install States
  const [deferredPrompt, setDeferredPrompt] = useState<any>(null);

  useEffect(() => {
    const handleBeforeInstallPrompt = (e: Event) => {
      e.preventDefault();
      setDeferredPrompt(e);
    };
    window.addEventListener('beforeinstallprompt', handleBeforeInstallPrompt);
    return () => window.removeEventListener('beforeinstallprompt', handleBeforeInstallPrompt);
  }, []);

  useEffect(() => {
    const fetchData = async () => {
      try {
        const [sv, pr, st, ex, cu, sa, se] = await Promise.all([
          supabase.from('services').select('*'),
          supabase.from('products').select('*'),
          supabase.from('staff').select('*'),
          supabase.from('expenses').select('*'),
          supabase.from('customers').select('*'),
          supabase.from('sales').select('*'),
          supabase.from('settings').select('*').single()
        ]);

        // Only load defaults if data is null (error) or empty array, AND we haven't loaded before
        // Ideally we only load defaults if the table is truly empty to seed it, 
        // but for now we fallback to initials if fetch fails or is empty to show the demo.

        if (sv.data && sv.data.length > 0) setServices(sv.data);
        else setServices(INITIAL_SERVICES);

        if (pr.data && pr.data.length > 0) setProducts(pr.data.map((p: any) => ({ ...p, lowStockThreshold: p.low_stock_threshold })));
        else setProducts(INITIAL_PRODUCTS);

        if (st.data && st.data.length > 0) setStaff(st.data);
        else setStaff(INITIAL_STAFF);

        if (ex.data && ex.data.length > 0) setExpenses(ex.data.map((e: any) => ({ ...e, receiptImage: e.receipt_image })));
        else setExpenses(INITIAL_EXPENSES);

        if (cu.data && cu.data.length > 0) setCustomers(cu.data.map((c: any) => ({ ...c, createdAt: c.created_at })));
        else setCustomers(INITIAL_CUSTOMERS);

        if (sa.data) setSales(sa.data.map((s: any) => ({ ...s, items: typeof s.items === 'string' ? JSON.parse(s.items) : s.items })));

        if (se.data?.data) setSettings({ ...DEFAULT_SETTINGS, ...se.data.data });

        // Log errors if any occurred during fetch
        if (sv.error) console.error("Services Fetch Error:", sv.error);
        if (pr.error) console.error("Products Fetch Error:", pr.error);
      } catch (e) { console.error("Error loading data:", e); }
      finally { setLoading(false); }
    };
    fetchData();
  }, []);

  useEffect(() => {
    document.documentElement.classList.toggle('dark', isDarkMode);
    localStorage.setItem('trimtime_theme', isDarkMode ? 'dark' : 'light');
  }, [isDarkMode]);

  useEffect(() => {
    document.documentElement.lang = sessionLanguage;
    document.dir = ['ur', 'fa'].includes(sessionLanguage) ? 'rtl' : 'ltr';
    localStorage.setItem('trimtime_lang', sessionLanguage);
  }, [sessionLanguage]);

  // --- DATA PERSISTENCE HANDLERS ---

  const handleUpdateServices = async (updated: Service[]) => {
    const currentIds = new Set(services.map(i => i.id));
    const newIds = new Set(updated.map(i => i.id));
    const toDelete = [...currentIds].filter(id => !newIds.has(id));

    setServices(updated);

    try {
      if (toDelete.length) await supabase.from('services').delete().in('id', toDelete);
      if (updated.length) {
          const { error } = await supabase.from('services').upsert(updated);
          if (error) throw error;
      }
