    const dbRows = updated.map(p => ({
        id: p.id,
        name: p.name,
        price: p.price,
        cost: p.cost,
        stock: p.stock,
        barcode: p.barcode || null, // Ensure null is sent if undefined
        low_stock_threshold: p.lowStockThreshold || 15
