        else setServices(INITIAL_SERVICES);

        if (pr.data && pr.data.length > 0) setProducts(pr.data.map((p: any) => ({ ...p, lowStockThreshold: p.low_stock_threshold })));
        else setProducts(INITIAL_PRODUCTS);

        if (st.data && st.data.length > 0) setStaff(st.data);
        else setStaff(INITIAL_STAFF);

        if (ex.data && ex.data.length > 0) setExpenses(ex.data.map((e: any) => ({ ...e, receiptImage: e.receipt_image })));
        else setExpenses(INITIAL_EXPENSES);

        if (cu.data && cu.data.length > 0) setCustomers(cu.data.map((c: any) => ({ ...c, createdAt: c.created_at })));
        else setCustomers(INITIAL_CUSTOMERS);

        if (sa.data) setSales(sa.data.map((s: any) => ({ ...s, items: typeof s.items === 'string' ? JSON.parse(s.items) : s.items })));

