        else if (pr.error) setProducts(INITIAL_PRODUCTS);
        else setProducts([]);

        if (st.data && st.data.length > 0) setStaff(st.data);
        else if (st.error) setStaff(INITIAL_STAFF);
        // Note: For staff, we might want to keep at least one admin if empty, but assuming DB handles it.
        else if (st.data && st.data.length === 0) setStaff(INITIAL_STAFF); // Fallback for staff to ensure login

        if (ex.data && ex.data.length > 0) setExpenses(ex.data.map((e: any) => ({ ...e, receiptImage: e.receipt_image })));
        else if (ex.error) setExpenses(INITIAL_EXPENSES);
        else setExpenses([]); // Don't show demo expenses if DB is connected but empty

        if (cu.data && cu.data.length > 0) setCustomers(cu.data.map((c: any) => ({ ...c, createdAt: c.created_at })));
        else if (cu.error) setCustomers(INITIAL_CUSTOMERS);
        else setCustomers([]);

        if (sa.data) setSales(sa.data.map((s: any) => ({ ...s, items: typeof s.items === 'string' ? JSON.parse(s.items) : s.items })));

        if (se.data?.data) setSettings({ ...DEFAULT_SETTINGS, ...se.data.data });

        if (sv.error) console.error("Services Fetch Error:", sv.error);
        if (pr.error) console.error("Products Fetch Error:", pr.error);
      } catch (e) { console.error("Error loading data:", e); }
      finally { setLoading(false); }
    };
    fetchData();
  }, []);

  useEffect(() => {
    document.documentElement.classList.toggle('dark', isDarkMode);
    localStorage.setItem('trimtime_theme', isDarkMode ? 'dark' : 'light');
  }, [isDarkMode]);

  useEffect(() => {
    document.documentElement.lang = sessionLanguage;
    document.dir = ['ur', 'fa'].includes(sessionLanguage) ? 'rtl' : 'ltr';
    localStorage.setItem('trimtime_lang', sessionLanguage);
  }, [sessionLanguage]);

  // --- DATA PERSISTENCE HANDLERS ---

  const handleUpdateServices = async (updated: Service[]) => {
    const currentIds = new Set(services.map(i => i.id));
    const newIds = new Set(updated.map(i => i.id));
    const toDelete = [...currentIds].filter(id => !newIds.has(id));

    setServices(updated);

    try {
      if (toDelete.length) await supabase.from('services').delete().in('id', toDelete);
      if (updated.length) {
          const { error } = await supabase.from('services').upsert(updated);
          if (error) throw error;
      }
    } catch (error) { 
        const err = error as any;
        console.error("DB Sync Error (Services):", err);
        alert("Failed to save services. Check database connection.");
    }
  };

  const handleUpdateProducts = async (updated: Product[]) => {
    const currentIds = new Set(products.map(i => i.id));
    const newIds = new Set(updated.map(i => i.id));
    const toDelete = [...currentIds].filter(id => !newIds.has(id));

    setProducts(updated);

    const dbRowsFull = updated.map(p => ({
        id: p.id,
        name: p.name,
        price: p.price,
        cost: p.cost,
        stock: p.stock,
        barcode: p.barcode || null,
        low_stock_threshold: p.lowStockThreshold || 15
    }));

    const dbRowsSafe = updated.map(p => ({
        id: p.id,
        name: p.name,
        price: p.price,
        cost: p.cost,
        stock: p.stock
    }));

    try {
      if (toDelete.length) await supabase.from('products').delete().in('id', toDelete);

      if (dbRowsFull.length) {
          const { error } = await supabase.from('products').upsert(dbRowsFull);
          if (error) {
            if (error.code === 'PGRST204' || error.message.includes('column')) {
                console.warn("DB Schema mismatch detected. Retrying with core fields only...");
                const { error: retryError } = await supabase.from('products').upsert(dbRowsSafe);
                if (retryError) throw retryError;
            } else {
                throw error;
            }
          }
      }
    } catch (error) { 
        const err = error as any;
        console.error("DB Sync Error (Products):", err); 
        alert(`Failed to save products: ${err.message}`);
    }
  };

  const handleUpdateStaff = async (updated: Staff[]) => {
    const currentIds = new Set(staff.map(i => i.id));
    const newIds = new Set(updated.map(i => i.id));
    const toDelete = [...currentIds].filter(id => !newIds.has(id));

    setStaff(updated);

    try {
      if (toDelete.length) await supabase.from('staff').delete().in('id', toDelete);
      if (updated.length) {
          const { error } = await supabase.from('staff').upsert(updated);
          if (error) throw error;
      }
    } catch (error) { 
        const err = error as any;
        console.error("DB Sync Error (Staff):", err);
        alert("Failed to save staff. Check database connection.");
    }
  };

  const handleUpdateCustomers = async (updated: Customer[]) => {
    const currentIds = new Set(customers.map(i => i.id));
    const newIds = new Set(updated.map(i => i.id));
    const toDelete = [...currentIds].filter(id => !newIds.has(id));

    setCustomers(updated);

    const dbRows = updated.map(c => ({
        id: c.id,
        name: c.name,
        phone: c.phone,
        email: c.email,
        notes: c.notes,
        created_at: c.createdAt
    }));

    try {
      if (toDelete.length) await supabase.from('customers').delete().in('id', toDelete);
      if (dbRows.length) {
          const { error } = await supabase.from('customers').upsert(dbRows);
          if (error) throw error;
      }
    } catch (error) { 
        const err = error as any;
        console.error("DB Sync Error (Customers):", err);
        alert("Failed to save customers. Check database connection.");
    }
  };

  const handleUpdateSettings = async (updated: ShopSettings) => {
    setSettings(updated);
    try {
      const { error } = await supabase.from('settings').upsert({ id: 1, data: updated });
      if (error) throw error;
    } catch (error) { 
        const err = error as any;
        console.error("DB Sync Error (Settings):", err);
        alert("Failed to save settings.");
    }
  };

  const handleCompleteSale = async (sale: Sale) => {
    setSales(prev => [...prev, sale]);
    try {
      const dbSale = {
          id: sale.id,
          timestamp: sale.timestamp,
          items: sale.items, 
          staff_id: sale.staffId,
          customer_id: sale.customerId,
          total: sale.total,
          tax: sale.tax,
          discount: sale.discount,
          discount_code: sale.discountCode,
          payment_method: sale.paymentMethod,
          tax_type: sale.taxType
      };
      const { error } = await supabase.from('sales').insert(dbSale);
      if (error) throw error;

      let productsUpdated = false;
      const newProducts = [...products];
      sale.items.forEach(item => {
          if (item.type === 'product') {
              const idx = newProducts.findIndex(p => p.id === item.id);
              if (idx > -1) {
                  newProducts[idx] = { ...newProducts[idx], stock: newProducts[idx].stock - item.quantity };
                  productsUpdated = true;
              }
          }
      });
      if (productsUpdated) handleUpdateProducts(newProducts);
    } catch (error) { 
        const err = error as any;
        console.error("DB Sync Error (Sale):", err);
        alert("Sale saved locally but failed to sync to DB.");
    }
  };

  const handleDeleteSales = async (ids: string[]) => {
    setSales(prev => prev.filter(s => !ids.includes(s.id)));
    try {
      const { error } = await supabase.from('sales').delete().in('id', ids);
      if (error) throw error;
    } catch (error) {
       const err = error as any;
       console.error("DB Sync Error (Delete Sales):", err);
       alert("Failed to delete sales from DB.");
    }
  };

  const handleAddExpense = async (expense: Expense) => {
      setExpenses(prev => [...prev, expense]);
      const dbExpense = {
          id: expense.id,
          date: expense.date,
          category: expense.category,
          amount: expense.amount,
          description: expense.description || '', // Ensure fallback
          receipt_image: expense.receiptImage || null // Ensure null if undefined
      };
      try {
        const { error } = await supabase.from('expenses').insert(dbExpense);
        if (error) throw error;
      } catch (error) { 
          const err = error as any;
          console.error("DB Sync Error (Expense):", err);
          alert("Failed to save expense to DB: " + err.message);
      }
  };

  const handleDeleteExpense = async (id: string) => {
      setExpenses(prev => prev.filter(e => e.id !== id));
      try {
        const { error } = await supabase.from('expenses').delete().eq('id', id);
        if (error) throw error;
      } catch (error) { 
          const err = error as any;
          console.error("DB Sync Error (Delete Expense):", err);
          alert("Failed to delete expense from DB: " + err.message);
      }
  };

  const handlePurgeSales = async () => {
    setSales([]);
    try {
       const { error } = await supabase.from('sales').delete().neq('id', '0'); 
       if (error) throw error;
    } catch (error) { 
        const err = error as any;
        console.error("DB Sync Error (Purge Sales):", err);
        alert("Failed to purge sales from DB.");
    }
  };

  const handleLogin = (user: Staff, remember: boolean) => {
    const expiry = Date.now() + (remember ? 30 : 1) * 24 * 60 * 60 * 1000;
    localStorage.setItem('trimtime_session', JSON.stringify({ user, expiry }));
    setCurrentUser(user);
    setCurrentView(user.role === 'employee' ? View.POS : View.DASHBOARD);
  };

  const handleLogout = () => {
    localStorage.removeItem('trimtime_session');
    setCurrentUser(null);
  };

  if (loading) return <div className="h-screen w-full flex items-center justify-center bg-slate-950"><div className="animate-spin rounded-full h-12 w-12 border-t-2 border-amber-500"></div></div>;
  if (!currentUser) return <Login onLogin={handleLogin} staffList={staff} shopName={settings.shopName} />;

  return (
    <div className="flex h-screen bg-slate-50 dark:bg-slate-950 overflow-hidden font-sans transition-colors duration-300">
      <Sidebar 
        currentView={currentView} onViewChange={setCurrentView} 
        shopName={settings.shopName} userRole={currentUser.role} 
        isOpen={isSidebarOpen} onClose={() => setIsSidebarOpen(false)}
        language={sessionLanguage} onLanguageChange={setSessionLanguage}
      />

      <div className="flex-1 flex flex-col min-w-0 md:pl-64 overflow-hidden relative">
        {/* Responsive Header */}
        <header className="flex md:hidden items-center justify-between p-4 bg-white dark:bg-slate-900 border-b border-slate-100 dark:border-slate-800 z-50 sticky top-0 shadow-sm">
          <div className="flex items-center gap-2">
             <div className="w-8 h-8 bg-amber-500 rounded-lg flex items-center justify-center font-brand text-lg text-slate-950">{settings.shopName.charAt(0)}</div>
             <span className="font-bold text-slate-900 dark:text-white truncate max-w-[120px]">{settings.shopName}</span>
          </div>
          <div className="flex gap-2">
            <button onClick={() => setIsDarkMode(!isDarkMode)} className="p-2 text-slate-400 bg-slate-50 dark:bg-slate-800 rounded-lg">
              {isDarkMode ? '🌞' : '🌙'}
            </button>
            <button onClick={() => setIsSidebarOpen(true)} className="p-2 text-slate-900 dark:text-white bg-amber-500 rounded-lg">
              <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M4 6h16M4 12h16m-7 6h7"/></svg>
            </button>
          </div>
        </header>

        {/* Desktop Header */}
        <header className="hidden md:flex justify-between items-center px-8 py-6 no-print">
            <h1 className="text-2xl font-black text-slate-900 dark:text-white font-brand">{tView(currentView, sessionLanguage)}</h1>
            <div className="flex items-center gap-4">
               <button onClick={() => setIsDarkMode(!isDarkMode)} className="p-2.5 bg-white dark:bg-slate-900 text-slate-400 rounded-xl border border-slate-200 dark:border-slate-800">
                 {isDarkMode ? '🌞' : '🌙'}
               </button>
               <div className="flex items-center gap-3 bg-white dark:bg-slate-900 p-1.5 pr-4 rounded-full border border-slate-100 dark:border-slate-800 shadow-sm">
                  <div className="w-8 h-8 rounded-full bg-amber-500 flex items-center justify-center font-black text-slate-950 text-xs">{currentUser.name.charAt(0)}</div>
                  <div className="flex flex-col"><span className="text-xs font-bold dark:text-white">{currentUser.name}</span><span className="text-[9px] uppercase font-black text-slate-400">{currentUser.role}</span></div>
               </div>
               <button onClick={handleLogout} className="p-2.5 bg-slate-100 dark:bg-slate-800 text-slate-500 rounded-xl">🚪</button>
            </div>
        </header>

        <main className="flex-1 overflow-y-auto p-4 md:p-8 relative scrollbar-hide">
          <AnimatePresence mode='wait'>
            <motion.div key={currentView} initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: -10 }} className="h-full">
              {renderView(currentView, { 
                sales, expenses, products, services, staff, customers, settings, 
                currentUser, sessionLanguage, isDarkMode, 
                // DB Handlers passed to children
                onUpdateServices: handleUpdateServices,
                onUpdateProducts: handleUpdateProducts,
                onUpdateStaff: handleUpdateStaff,
                onUpdateCustomers: handleUpdateCustomers,
                onUpdateSettings: handleUpdateSettings,
                onCompleteSale: handleCompleteSale,
                onAddExpense: handleAddExpense,
                onDeleteExpense: handleDeleteExpense,
                onLogout: handleLogout,
                onPurgeSales: handlePurgeSales,
                onDeleteSales: handleDeleteSales,

                setCurrentView, handleLogout
              })}
            </motion.div>
          </AnimatePresence>
        </main>
      </div>

      <InstallBanner 
        deferredPrompt={deferredPrompt} 
        onClose={() => setDeferredPrompt(null)} 
      />
    </div>
  );
};

const tView = (v: View, l: Language) => {
  const map: any = { 
    en: { [View.DASHBOARD]: 'Dashboard', [View.POS]: 'Terminal', [View.FINANCE]: 'Finances', [View.INVENTORY]: 'Catalog', [View.STAFF]: 'Staff', [View.CUSTOMERS]: 'Clients', [View.SETTINGS]: 'Settings' },
    ur: { [View.DASHBOARD]: 'ڈیش بورڈ', [View.POS]: 'ٹرمینل', [View.FINANCE]: 'مالیات', [View.INVENTORY]: 'کیٹلاگ', [View.STAFF]: 'عملہ', [View.CUSTOMERS]: 'صارفین', [View.SETTINGS]: 'ترتیبات' }
  };
  return map[l]?.[v] || map['en'][v];
};

const renderView = (v: View, props: any) => {
  const { sales, expenses, products, services, staff, customers, settings, currentUser, sessionLanguage, onUpdateServices, onUpdateProducts, onUpdateStaff, onUpdateCustomers, onUpdateSettings, onCompleteSale, onAddExpense, onDeleteExpense, onLogout, onPurgeSales, onDeleteSales, setCurrentView } = props;
  switch (v) {
    case View.DASHBOARD: return <Dashboard sales={sales} expenses={expenses} products={products} currency={settings.currency} language={sessionLanguage} onNavigate={setCurrentView} />;
    case View.POS: return <POS services={services} products={products} staff={staff} customers={customers} settings={settings} currentUser={currentUser} onCompleteSale={onCompleteSale} onAddCustomer={c => onUpdateCustomers([...customers, c])} />;
    case View.FINANCE: return <Finance sales={sales} expenses={expenses} staffList={staff} customers={customers} currency={settings.currency} language={sessionLanguage} currentUser={currentUser} onAddExpense={onAddExpense} onDeleteExpense={onDeleteExpense} onDeleteSales={onDeleteSales} />;
    case View.CUSTOMERS: return <Customers customers={customers} sales={sales} onUpdateCustomers={onUpdateCustomers} currency={settings.currency} language={sessionLanguage} />;
    case View.INVENTORY: return <Inventory services={services} products={products} settings={{...settings, language: sessionLanguage}} onUpdateServices={onUpdateServices} onUpdateProducts={onUpdateProducts} />;
    case View.STAFF: return <StaffManagement staffList={staff} onUpdateStaff={onUpdateStaff} currentUser={currentUser} language={sessionLanguage} />;
    case View.SETTINGS: return <Settings settings={{...settings, language: sessionLanguage}} onUpdateSettings={onUpdateSettings} currentUser={currentUser} onLogout={onLogout} onPurgeSales={onPurgeSales} />;
    default: return null;
  }
};

export default App;

import React, { useState, useRef } from 'react';
import { Sale, Expense, Staff, Language, Customer } from '../types';
import { TRANSLATIONS } from '../constants';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';
import { motion, AnimatePresence } from 'framer-motion';

interface FinanceProps {
  sales: Sale[];
  expenses: Expense[];
  staffList: Staff[];
  customers: Customer[];
  currency: string;
  language: Language;
  currentUser: Staff;
  onAddExpense: (expense: Expense) => void;
  onDeleteExpense: (id: string) => void;
  onDeleteSales: (ids: string[]) => void;
}

const Finance: React.FC<FinanceProps> = ({ sales, expenses, staffList, customers, currency, language, currentUser, onAddExpense, onDeleteExpense, onDeleteSales }) => {
  const [activeTab, setActiveTab] = useState<'overview' | 'transactions' | 'expenses'>(currentUser.role === 'admin' ? 'overview' : 'expenses');
  const [newExp, setNewExp] = useState<{ category: string; amount: number; description: string; receiptImage: string | null }>({ 
    category: '', 
    amount: 0, 
    description: '',
    receiptImage: null 
  });
  const [viewingReceipt, setViewingReceipt] = useState<string | null>(null);
  const [selectedTransactions, setSelectedTransactions] = useState<Set<string>>(new Set());

  const fileInputRef = useRef<HTMLInputElement>(null);
  const t = TRANSLATIONS[language];

  const totalRevenue = sales.reduce((a, b) => a + b.total, 0);
  const totalExpenses = expenses.reduce((a, b) => a + b.amount, 0);

  const toggleSelection = (id: string) => {
    const newSet = new Set(selectedTransactions);
    if (newSet.has(id)) newSet.delete(id);
    else newSet.add(id);
    setSelectedTransactions(newSet);
  };

  const toggleAll = () => {
    if (selectedTransactions.size === sales.length) {
      setSelectedTransactions(new Set());
    } else {
      setSelectedTransactions(new Set(sales.map(s => s.id)));
    }
  };

  const handleDeleteSelected = () => {
     if (confirm(`Are you sure you want to delete ${selectedTransactions.size} selected transactions? This cannot be undone.`)) {
       onDeleteSales(Array.from(selectedTransactions));
       setSelectedTransactions(new Set());
     }
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      const img = new Image();
      img.onload = () => {
        // Resize image to max 800px width/height to save space
        const canvas = document.createElement('canvas');
        let width = img.width;
        let height = img.height;
        const MAX_SIZE = 800;

        if (width > height) {
          if (width > MAX_SIZE) {
            height *= MAX_SIZE / width;
            width = MAX_SIZE;
          }
        } else {
          if (height > MAX_SIZE) {
            width *= MAX_SIZE / height;
            height = MAX_SIZE;
          }
        }

        canvas.width = width;
        canvas.height = height;
        const ctx = canvas.getContext('2d');
        ctx?.drawImage(img, 0, 0, width, height);

        // Compress to JPEG 0.7 quality
        const dataUrl = canvas.toDataURL('image/jpeg', 0.7);
        setNewExp(prev => ({ ...prev, receiptImage: dataUrl }));
      };
      if (event.target?.result) {
        img.src = event.target.result as string;
      }
    };
    reader.readAsDataURL(file);
  };

  return (
    <div className="space-y-6 max-w-6xl mx-auto pb-24 md:pb-10">
      <div className="flex bg-white dark:bg-slate-900 p-1.5 rounded-2xl shadow-sm border border-slate-100 dark:border-slate-800 overflow-x-auto no-scrollbar sticky top-0 z-20">
        <div className="flex gap-1 min-w-max w-full">
           {currentUser.role === 'admin' && (
             <>
               <button onClick={() => setActiveTab('overview')} className={`flex-1 md:flex-none px-6 py-2.5 rounded-xl text-xs font-black uppercase tracking-widest transition-all ${activeTab === 'overview' ? 'bg-amber-500 text-slate-950' : 'text-slate-400'}`}>Overview</button>
               <button onClick={() => setActiveTab('transactions')} className={`flex-1 md:flex-none px-6 py-2.5 rounded-xl text-xs font-black uppercase tracking-widest transition-all ${activeTab === 'transactions' ? 'bg-amber-500 text-slate-950' : 'text-slate-400'}`}>Transactions</button>
             </>
           )}
           <button onClick={() => setActiveTab('expenses')} className={`flex-1 md:flex-none px-6 py-2.5 rounded-xl text-xs font-black uppercase tracking-widest transition-all ${activeTab === 'expenses' ? 'bg-amber-500 text-slate-950' : 'text-slate-400'}`}>Expenses</button>
        </div>
      </div>

      <AnimatePresence mode="wait">
        {activeTab === 'overview' && (
          <motion.div key="ov" initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="space-y-8">
            <div className="bg-white dark:bg-slate-900 p-6 md:p-8 rounded-[2rem] border border-slate-100 dark:border-slate-800">
               <h3 className="text-xl font-bold mb-8 flex items-center gap-3"><span className="text-2xl">📊</span> {t.shopPerformance}</h3>
               <div className="h-72 w-full">
                  <ResponsiveContainer width="100%" height="100%">
                    <BarChart data={[{ name: 'Shop Summary', rev: totalRevenue, exp: totalExpenses, prf: totalRevenue - totalExpenses }]}>
                      <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" className="dark:opacity-5" />
                      <XAxis dataKey="name" axisLine={false} tickLine={false} />
                      <YAxis axisLine={false} tickLine={false} />
                      <Tooltip 
                        contentStyle={{ backgroundColor: '#0f172a', border: 'none', borderRadius: '12px', color: 'white' }}
                        cursor={{fill: 'transparent'}}
                      />
                      <Bar dataKey="rev" name="Revenue" fill="#10b981" radius={[8, 8, 0, 0]} />
                      <Bar dataKey="exp" name="Expenses" fill="#f43f5e" radius={[8, 8, 0, 0]} />
                    </BarChart>
                  </ResponsiveContainer>
               </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
               <div className="bg-white dark:bg-slate-900 p-6 rounded-[2rem] border border-slate-100 dark:border-slate-800">
                  <h3 className="font-bold mb-4">Commission Distribution</h3>
                  <div className="space-y-3">
                     {staffList.filter(s => s.role === 'employee').map(s => {
                        const sRev = sales.filter(x => x.staffId === s.id).reduce((a,b) => a+b.total, 0);
                        const comm = (sRev * s.commission) / 100;
                        return (
                          <div key={s.id} className="flex justify-between items-center p-4 bg-slate-50 dark:bg-slate-800/50 rounded-2xl">
                             <span className="text-sm font-bold">{s.name}</span>
                             <span className="font-black text-emerald-600">{currency}{comm.toFixed(2)}</span>
                          </div>
                        );
                     })}
                  </div>
               </div>
            </div>
          </motion.div>
        )}

        {activeTab === 'transactions' && (
          <motion.div key="tr" initial={{ opacity: 0 }} animate={{ opacity: 1 }}>
             {/* Toolbar for Multi-select */}
             {selectedTransactions.size > 0 && (
               <motion.div initial={{ y: -10, opacity: 0 }} animate={{ y: 0, opacity: 1 }} className="mb-4 bg-slate-900 text-white p-4 rounded-xl flex items-center justify-between shadow-lg z-10 sticky top-16">
                 <span className="font-bold text-sm">{selectedTransactions.size} selected</span>
                 <button onClick={handleDeleteSelected} className="bg-rose-500 hover:bg-rose-600 text-white px-4 py-2 rounded-lg text-xs font-black uppercase tracking-wider transition-colors">
                   Delete
                 </button>
               </motion.div>
             )}

             {/* Mobile Card View */}
             <div className="md:hidden space-y-3">
                {sales.length > 0 && (
                   <div className="mb-2 flex items-center gap-2 px-1">
                      <input 
                        type="checkbox" 
                        checked={selectedTransactions.size === sales.length && sales.length > 0} 
                        onChange={toggleAll}
                        className="w-5 h-5 rounded border-slate-300 text-amber-500 focus:ring-amber-500"
                      />
                      <span className="text-xs font-bold text-slate-500">Select All</span>
                   </div>
                )}
                {sales.slice().reverse().map(s => (
