      </AnimatePresence>
    </div>
  );
};

export default POS;

import React, { useState, useRef } from 'react';
import { Sale, Expense, Staff, Language, Customer, ShopSettings } from '../types';
import { TRANSLATIONS } from '../constants';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';
import { motion, AnimatePresence } from 'framer-motion';

interface FinanceProps {
  sales: Sale[];
  expenses: Expense[];
  staffList: Staff[];
  customers: Customer[];
  currency: string;
  language: Language;
  currentUser: Staff;
  onAddExpense: (expense: Expense) => void;
  onDeleteExpense: (id: string) => void;
  onDeleteSales: (ids: string[]) => void;
  settings: ShopSettings;
}

const Finance: React.FC<FinanceProps> = ({ sales, expenses, staffList, customers, currency, language, currentUser, onAddExpense, onDeleteExpense, onDeleteSales, settings }) => {
  const [activeTab, setActiveTab] = useState<'overview' | 'transactions' | 'expenses'>(currentUser.role === 'admin' ? 'overview' : 'expenses');
  const [newExp, setNewExp] = useState<{ category: string; amount: number; description: string; receiptImage: string | null }>({ 
    category: '', 
    amount: 0, 
    description: '',
    receiptImage: null 
  });
  const [viewingReceipt, setViewingReceipt] = useState<string | null>(null);
  const [viewingSale, setViewingSale] = useState<Sale | null>(null);
  const [selectedTransactions, setSelectedTransactions] = useState<Set<string>>(new Set());

  const fileInputRef = useRef<HTMLInputElement>(null);
  const t = TRANSLATIONS[language];

  const totalRevenue = sales.reduce((a, b) => a + b.total, 0);
  const totalExpenses = expenses.reduce((a, b) => a + b.amount, 0);

  const toggleSelection = (id: string) => {
    const newSet = new Set(selectedTransactions);
    if (newSet.has(id)) newSet.delete(id);
    else newSet.add(id);
    setSelectedTransactions(newSet);
  };

  const toggleAll = () => {
    if (selectedTransactions.size === sales.length) {
      setSelectedTransactions(new Set());
    } else {
      setSelectedTransactions(new Set(sales.map(s => s.id)));
    }
  };

  const handleDeleteSelected = () => {
     if (confirm(`Are you sure you want to delete ${selectedTransactions.size} selected transactions? This cannot be undone.`)) {
       onDeleteSales(Array.from(selectedTransactions));
       setSelectedTransactions(new Set());
     }
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      const img = new Image();
      img.onload = () => {
        // Resize image to max 800px width/height to save space
        const canvas = document.createElement('canvas');
        let width = img.width;
        let height = img.height;
        const MAX_SIZE = 800;

        if (width > height) {
          if (width > MAX_SIZE) {
            height *= MAX_SIZE / width;
            width = MAX_SIZE;
          }
        } else {
          if (height > MAX_SIZE) {
            width *= MAX_SIZE / height;
            height = MAX_SIZE;
          }
        }

        canvas.width = width;
        canvas.height = height;
        const ctx = canvas.getContext('2d');
        ctx?.drawImage(img, 0, 0, width, height);

        // Compress to JPEG 0.7 quality
        const dataUrl = canvas.toDataURL('image/jpeg', 0.7);
        setNewExp(prev => ({ ...prev, receiptImage: dataUrl }));
      };
      if (event.target?.result) {
        img.src = event.target.result as string;
      }
    };
    reader.readAsDataURL(file);
  };

  const renderReceiptModal = () => {
    if (!viewingSale) return null;
    const customer = customers.find(c => c.id === viewingSale.customerId);
    const staff = staffList.find(s => s.id === viewingSale.staffId);

    return (
      <motion.div 
        initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}
        className="fixed inset-0 bg-slate-950/80 backdrop-blur-sm z-[200] flex items-center justify-center p-4"
        onClick={() => setViewingSale(null)}
      >
        <motion.div 
          initial={{ scale: 0.9, y: 20 }} animate={{ scale: 1, y: 0 }}
          className="bg-white text-slate-900 w-full max-w-sm rounded-3xl overflow-hidden shadow-2xl relative"
          onClick={e => e.stopPropagation()}
        >
           <div className="bg-slate-900 text-white p-6 text-center relative">
              <h2 className="font-brand text-2xl font-bold">{settings.shopName}</h2>
              <p className="text-xs text-slate-400 uppercase tracking-widest mt-1">Transaction Details</p>
              <button onClick={() => setViewingSale(null)} className="absolute top-4 right-4 text-slate-400 hover:text-white">
                <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12"/></svg>
              </button>
           </div>
           <div className="p-6 space-y-4">
              <div className="flex justify-between text-xs text-slate-500 font-medium border-b border-slate-100 pb-4">
                 <div className="space-y-1">
                    <p>Date: {new Date(viewingSale.timestamp).toLocaleDateString()}</p>
                    <p>ID: #{viewingSale.id.slice(0,8)}</p>
                 </div>
                 <div className="space-y-1 text-right">
                    <p>Pro: {staff?.name || 'N/A'}</p>
                    <p>Client: {customer?.name || 'Walk-in'}</p>
                 </div>
              </div>

              <div className="space-y-2">
                 {viewingSale.items.map((item, idx) => (
                   <div key={idx} className="flex justify-between text-sm">
                      <span className="font-bold text-slate-800">{item.quantity}x {item.name}</span>
                      <span className="font-medium text-slate-600">{currency}{(item.price * item.quantity).toFixed(2)}</span>
                   </div>
                 ))}
              </div>

              <div className="border-t border-slate-100 pt-4 space-y-2">
                 <div className="flex justify-between text-xs text-slate-500">
                    <span>Subtotal</span>
                    <span>{currency}{(viewingSale.total - viewingSale.tax + viewingSale.discount).toFixed(2)}</span>
                 </div>
                 {viewingSale.discount > 0 && (
                   <div className="flex justify-between text-xs text-emerald-600">
                      <span>Discount</span>
                      <span>-{currency}{viewingSale.discount.toFixed(2)}</span>
                   </div>
                 )}
                 <div className="flex justify-between text-xs text-slate-500">
                    <span>Tax</span>
                    <span>{currency}{viewingSale.tax.toFixed(2)}</span>
                 </div>
                 <div className="flex justify-between text-xl font-black text-slate-900 pt-2">
                    <span>Total</span>
                    <span>{currency}{viewingSale.total.toFixed(2)}</span>
                 </div>
                 <div className="text-center pt-2">
                    <span className="bg-slate-100 text-slate-500 px-3 py-1 rounded-full text-[10px] font-black uppercase tracking-widest">{viewingSale.paymentMethod}</span>
                 </div>
              </div>
           </div>
           <div className="bg-slate-50 p-4 text-center">
              <p className="text-[10px] text-slate-400 italic">{settings.receiptFooter}</p>
           </div>
        </motion.div>
      </motion.div>
    );
  };

  return (
    <div className="space-y-6 max-w-6xl mx-auto pb-24 md:pb-10">
      <div className="flex bg-white dark:bg-slate-900 p-1.5 rounded-2xl shadow-sm border border-slate-100 dark:border-slate-800 overflow-x-auto no-scrollbar sticky top-0 z-20">
        <div className="flex gap-1 min-w-max w-full">
           {currentUser.role === 'admin' && (
             <>
               <button onClick={() => setActiveTab('overview')} className={`flex-1 md:flex-none px-6 py-2.5 rounded-xl text-xs font-black uppercase tracking-widest transition-all ${activeTab === 'overview' ? 'bg-amber-500 text-slate-950' : 'text-slate-400'}`}>Overview</button>
               <button onClick={() => setActiveTab('transactions')} className={`flex-1 md:flex-none px-6 py-2.5 rounded-xl text-xs font-black uppercase tracking-widest transition-all ${activeTab === 'transactions' ? 'bg-amber-500 text-slate-950' : 'text-slate-400'}`}>Transactions</button>
             </>
           )}
           <button onClick={() => setActiveTab('expenses')} className={`flex-1 md:flex-none px-6 py-2.5 rounded-xl text-xs font-black uppercase tracking-widest transition-all ${activeTab === 'expenses' ? 'bg-amber-500 text-slate-950' : 'text-slate-400'}`}>Expenses</button>
        </div>
      </div>

      <AnimatePresence mode="wait">
        {activeTab === 'overview' && (
          <motion.div key="ov" initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="space-y-8">
            <div className="bg-white dark:bg-slate-900 p-6 md:p-8 rounded-[2rem] border border-slate-100 dark:border-slate-800">
               <h3 className="text-xl font-bold mb-8 flex items-center gap-3"><span className="text-2xl">📊</span> {t.shopPerformance}</h3>
               <div className="h-72 w-full">
                  <ResponsiveContainer width="100%" height="100%">
                    <BarChart data={[{ name: 'Shop Summary', rev: totalRevenue, exp: totalExpenses, prf: totalRevenue - totalExpenses }]}>
                      <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" className="dark:opacity-5" />
                      <XAxis dataKey="name" axisLine={false} tickLine={false} />
                      <YAxis axisLine={false} tickLine={false} />
                      <Tooltip 
                        contentStyle={{ backgroundColor: '#0f172a', border: 'none', borderRadius: '12px', color: 'white' }}
                        cursor={{fill: 'transparent'}}
                      />
                      <Bar dataKey="rev" name="Revenue" fill="#10b981" radius={[8, 8, 0, 0]} />
                      <Bar dataKey="exp" name="Expenses" fill="#f43f5e" radius={[8, 8, 0, 0]} />
                    </BarChart>
                  </ResponsiveContainer>
               </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
               <div className="bg-white dark:bg-slate-900 p-6 rounded-[2rem] border border-slate-100 dark:border-slate-800">
                  <h3 className="font-bold mb-4">Commission Distribution</h3>
                  <div className="space-y-3">
                     {staffList.filter(s => s.role === 'employee').map(s => {
                        const sRev = sales.filter(x => x.staffId === s.id).reduce((a,b) => a+b.total, 0);
                        const comm = (sRev * s.commission) / 100;
                        return (
                          <div key={s.id} className="flex justify-between items-center p-4 bg-slate-50 dark:bg-slate-800/50 rounded-2xl">
                             <span className="text-sm font-bold">{s.name}</span>
                             <span className="font-black text-emerald-600">{currency}{comm.toFixed(2)}</span>
                          </div>
                        );
                     })}
                  </div>
               </div>
            </div>
          </motion.div>
        )}

        {activeTab === 'transactions' && (
          <motion.div key="tr" initial={{ opacity: 0 }} animate={{ opacity: 1 }}>
             {/* Toolbar for Multi-select */}
             {selectedTransactions.size > 0 && (
               <motion.div initial={{ y: -10, opacity: 0 }} animate={{ y: 0, opacity: 1 }} className="mb-4 bg-slate-900 text-white p-4 rounded-xl flex items-center justify-between shadow-lg z-10 sticky top-16">
                 <span className="font-bold text-sm">{selectedTransactions.size} selected</span>
                 <button onClick={handleDeleteSelected} className="bg-rose-500 hover:bg-rose-600 text-white px-4 py-2 rounded-lg text-xs font-black uppercase tracking-wider transition-colors">
                   Delete
                 </button>
               </motion.div>
             )}

             {/* Mobile Card View */}
             <div className="md:hidden space-y-3">
                {sales.length > 0 && (
                   <div className="mb-2 flex items-center gap-2 px-1">
                      <input 
                        type="checkbox" 
                        checked={selectedTransactions.size === sales.length && sales.length > 0} 
                        onChange={toggleAll}
                        className="w-5 h-5 rounded border-slate-300 text-amber-500 focus:ring-amber-500"
                      />
                      <span className="text-xs font-bold text-slate-500">Select All</span>
                   </div>
                )}
                {sales.slice().reverse().map(s => (
                    <div key={s.id} className={`bg-white dark:bg-slate-900 p-4 rounded-2xl border flex gap-3 items-center shadow-sm transition-all ${selectedTransactions.has(s.id) ? 'border-amber-500 ring-1 ring-amber-500' : 'border-slate-100 dark:border-slate-800'}`}>
                        <div className="flex flex-col gap-4 h-full justify-between py-1">
                           <input 
                             type="checkbox" 
                             checked={selectedTransactions.has(s.id)}
                             onChange={() => toggleSelection(s.id)}
                             className="w-5 h-5 rounded border-slate-300 text-amber-500 focus:ring-amber-500"
                           />
                        </div>

                        <div className="flex-1 flex justify-between items-center" onClick={() => setViewingSale(s)}>
                            <div>
                               <div className="flex items-center gap-2">
                                   <span className="text-sm font-bold text-slate-800 dark:text-slate-200">#{s.id.slice(-4)}</span>
                                   <span className="text-[10px] bg-slate-100 dark:bg-slate-800 text-slate-500 px-2 py-0.5 rounded-md">{new Date(s.timestamp).toLocaleDateString()}</span>
                               </div>
                               <p className="text-xs text-slate-500 dark:text-slate-400 mt-1">{staffList.find(x => x.id === s.staffId)?.name || 'Unknown'}</p>
                            </div>
                            <div className="text-right">
                                <p className="font-black text-slate-900 dark:text-white">{currency}{s.total.toFixed(2)}</p>
                                <div className="flex items-center gap-2 justify-end">
                                   <span className={`text-[9px] font-black uppercase tracking-widest ${s.paymentMethod === 'card' ? 'text-indigo-500' : 'text-emerald-500'}`}>{s.paymentMethod}</span>
                                   <svg className="w-4 h-4 text-slate-300" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z"/><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z"/></svg>
                                </div>
                            </div>
                        </div>
                    </div>
                ))}
                {sales.length === 0 && <p className="text-center text-slate-400 text-sm py-10">No transactions recorded.</p>}
             </div>

             {/* Desktop Table View */}
             <div className="hidden md:block bg-white dark:bg-slate-900 rounded-[2rem] border border-slate-100 dark:border-slate-800 overflow-hidden">
                 <div className="overflow-x-auto">
                    <table className="w-full text-left min-w-[600px]">
                       <thead className="bg-slate-50 dark:bg-slate-800/50 text-[10px] font-black uppercase tracking-widest text-slate-400">
                          <tr>
                            <th className="p-6 w-16 text-center">
                              <input 
                                type="checkbox" 
                                checked={selectedTransactions.size === sales.length && sales.length > 0} 
                                onChange={toggleAll}
                                className="w-4 h-4 rounded border-slate-300 text-amber-500 focus:ring-amber-500"
                              />
                            </th>
                            <th className="p-6">Date</th>
                            <th className="p-6">Professional</th>
                            <th className="p-6">Total</th>
                            <th className="p-6">Method</th>
                            <th className="p-6 text-right">View</th>
                          </tr>
                       </thead>
                       <tbody className="divide-y divide-slate-50 dark:divide-slate-800">
                          {sales.slice().reverse().map(s => (
                            <tr key={s.id} className={`text-sm transition-colors ${selectedTransactions.has(s.id) ? 'bg-amber-50 dark:bg-amber-900/10' : ''}`}>
                               <td className="p-6 text-center">
                                  <input 
                                    type="checkbox" 
                                    checked={selectedTransactions.has(s.id)}
                                    onChange={() => toggleSelection(s.id)}
                                    className="w-4 h-4 rounded border-slate-300 text-amber-500 focus:ring-amber-500"
                                  />
                               </td>
                               <td className="p-6 font-medium">{new Date(s.timestamp).toLocaleDateString()}</td>
                               <td className="p-6 font-bold">{staffList.find(x => x.id === s.staffId)?.name}</td>
