                      <input placeholder="Rent" value={newExp.category} onChange={e => setNewExp({...newExp, category: e.target.value})} className="w-full bg-slate-50 dark:bg-slate-800 rounded-xl px-4 py-3 text-sm focus:ring-2 focus:ring-amber-500/20 border-none outline-none dark:text-white" />
                   </div>
                   <div className="col-span-1 md:col-span-3">
                      <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1 mb-2 block">{t.amount}</label>
