                   </div>
                </div>
             </div>

             <div className="bg-white dark:bg-slate-900 rounded-[2rem] border border-slate-100 dark:border-slate-800 overflow-hidden">
                <div className="p-6 border-b border-slate-50 dark:border-slate-800 flex justify-between items-center"><h3 className="font-bold">{t.history}</h3><span className="text-[10px] font-black text-rose-500 uppercase tracking-widest">{currency}{totalExpenses.toFixed(2)} Total</span></div>

                {/* Mobile Expense List */}
                <div className="md:hidden">
                    {expenses.slice().reverse().map(e => (
                      <div key={e.id} className="p-4 border-b border-slate-50 dark:border-slate-800 flex justify-between items-start last:border-0">
                          <div className="flex gap-3">
                               <button 
                                  onClick={() => e.receiptImage && setViewingReceipt(e.receiptImage)}
                                  className={`w-12 h-12 rounded-xl flex items-center justify-center shrink-0 ${e.receiptImage ? 'border border-slate-200 dark:border-slate-700 overflow-hidden' : 'bg-slate-100 dark:bg-slate-800 text-slate-300'}`}
