          </motion.div>
        )}

        {activeTab === 'expenses' && (
          <motion.div key="ex" initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="space-y-6">
             <div className="bg-white dark:bg-slate-900 p-5 md:p-8 rounded-[2rem] border border-slate-100 dark:border-slate-800 shadow-sm">
                <h3 className="text-lg font-bold mb-6">{t.newExpense}</h3>

                {/* Updated Grid for Mobile Optimization */}
                <div className="grid grid-cols-2 md:grid-cols-12 gap-3 md:gap-4 items-end">
