                             <button 
                                onClick={() => setNewExp(prev => ({ ...prev, receiptImage: null }))}
                                className="absolute -top-2 -right-2 bg-rose-500 text-white rounded-full p-1 hover:bg-rose-600 shadow-md"
                             >
                                <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M6 18L18 6M6 6l12 12"/></svg>
                             </button>
                          </div>
                       ) : (
                          <button 
                            onClick={() => fileInputRef.current?.click()}
                            className="w-full h-[46px] bg-slate-100 dark:bg-slate-800 text-slate-500 dark:text-slate-400 rounded-xl flex items-center justify-center hover:bg-slate-200 dark:hover:bg-slate-700 transition-colors"
                            title="Attach Receipt"
                          >
                             <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z"/><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 13a3 3 0 11-6 0 3 3 0 016 0z"/></svg>
                          </button>
                       )}

                      <button 
                        onClick={() => { 
                          if (!newExp.category || !newExp.amount) return;
                          onAddExpense({
                            id: 'e' + Date.now(), 
                            date: new Date().toISOString().split('T')[0], 
                            category: newExp.category,
                            amount: newExp.amount,
                            description: newExp.description || '',
                            receiptImage: newExp.receiptImage || undefined
                          }); 
                          setNewExp({category: '', amount: 0, description: '', receiptImage: null}); 
                        }} 
                        className="bg-slate-950 dark:bg-amber-500 text-white dark:text-slate-950 p-3 rounded-xl font-black shadow-lg hover:opacity-90 transition-opacity flex items-center justify-center"
                        title={t.addExpense}
                      >
                        <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M12 4v1m8-8H4"/></svg>
                      </button>
                   </div>
                </div>
             </div>

             <div className="bg-white dark:bg-slate-900 rounded-[2rem] border border-slate-100 dark:border-slate-800 overflow-hidden">
                <div className="p-6 border-b border-slate-50 dark:border-slate-800 flex justify-between items-center"><h3 className="font-bold">{t.history}</h3><span className="text-[10px] font-black text-rose-500 uppercase tracking-widest">{currency}{totalExpenses.toFixed(2)} Total</span></div>

                {/* Mobile Expense List */}
                <div className="md:hidden">
