                               >
                                  {e.receiptImage ? <img src={e.receiptImage} alt="Receipt" className="w-full h-full object-cover" /> : <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 13h6m-3-3v6m-9 1V7a2 2 0 012-2h6l2 2h6a2 2 0 012 2v8a2 2 0 01-2 2H5a2 2 0 01-2-2z"/></svg>}
                               </button>
                               <div>
                                  <p className="font-bold text-sm text-slate-800 dark:text-white">{e.category}</p>
                                  <p className="text-xs text-slate-500 dark:text-slate-400 line-clamp-1">{e.description || 'No details'}</p>
                                  <p className="text-[10px] text-slate-400 font-medium mt-1">{e.date}</p>
                               </div>
                          </div>
                          <div className="flex flex-col items-end gap-2">
                              <span className="font-black text-rose-500 text-sm">{currency}{e.amount.toFixed(2)}</span>
                              <button onClick={() => onDeleteExpense(e.id)} className="text-slate-300 hover:text-rose-500">
                                  <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"/></svg>
                              </button>
                          </div>
                      </div>
                    ))}
                    {expenses.length === 0 && <p className="text-center text-slate-400 text-sm py-8 italic">No expenses recorded.</p>}
                </div>

                {/* Desktop Expense Table */}
                <div className="hidden md:block overflow-x-auto">
                   <table className="w-full text-left min-w-[600px]">
                      <thead className="bg-slate-50 dark:bg-slate-800/50 text-[10px] font-black uppercase tracking-widest text-slate-400">
                         <tr>
                           <th className="p-6">Date</th>
                           <th className="p-6">Category</th>
                           <th className="p-6">Description</th>
                           <th className="p-6">Receipt</th>
                           <th className="p-6 text-right">Amount</th>
                           <th className="p-6 text-center">Action</th>
                         </tr>
                      </thead>
                      <tbody className="divide-y divide-slate-50 dark:divide-slate-800">
                         {expenses.slice().reverse().map(e => (
                           <tr key={e.id} className="text-sm hover:bg-slate-50/50 dark:hover:bg-slate-800/50 transition-colors">
                              <td className="p-6 font-medium">{e.date}</td>
                              <td className="p-6 font-bold">{e.category}</td>
                              <td className="p-6 text-slate-500 dark:text-slate-400 max-w-xs truncate">{e.description || '-'}</td>
                              <td className="p-6">
                                {e.receiptImage ? (
                                  <button 
                                    onClick={() => setViewingReceipt(e.receiptImage || null)}
                                    className="w-10 h-10 rounded-lg overflow-hidden border border-slate-200 dark:border-slate-700 hover:ring-2 hover:ring-amber-500 transition-all"
                                  >
                                    <img src={e.receiptImage} alt="Receipt" className="w-full h-full object-cover" />
                                  </button>
                                ) : (
                                  <span className="text-slate-300 text-xs">No img</span>
                                )}
                              </td>
                              <td className="p-6 text-right font-black text-rose-500">{currency}{e.amount.toFixed(2)}</td>
                              <td className="p-6 text-center"><button onClick={() => onDeleteExpense(e.id)} className="text-slate-300 hover:text-rose-500 transition-colors p-2"><svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"/></svg></button></td>
                           </tr>
                         ))}
                         {expenses.length === 0 && (
                            <tr>
                               <td colSpan={6} className="p-8 text-center text-slate-400 italic">No expenses recorded.</td>
                            </tr>
                         )}
                      </tbody>
                   </table>
                </div>
             </div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* Full Screen Receipt Modal */}
      <AnimatePresence>
        {viewingReceipt && (
          <motion.div 
            initial={{ opacity: 0 }} 
            animate={{ opacity: 1 }} 
            exit={{ opacity: 0 }}
            className="fixed inset-0 bg-slate-950/90 backdrop-blur-sm z-[200] flex items-center justify-center p-4"
            onClick={() => setViewingReceipt(null)}
          >
             <div className="relative max-w-2xl w-full max-h-[90vh]">
               <button 
                 onClick={() => setViewingReceipt(null)}
                 className="absolute -top-12 right-0 text-white hover:text-amber-500 p-2"
               >
                 <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12"/></svg>
               </button>
               <img src={viewingReceipt} alt="Receipt Full" className="w-full h-full object-contain rounded-2xl shadow-2xl" />
             </div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* Sale Detail Receipt Modal */}
      <AnimatePresence>
        {renderReceiptModal()}
      </AnimatePresence>
    </div>
  );
};

export default Finance;

import React, { useState, useRef, useMemo } from 'react';
import { Sale, Expense, Staff, Language, Customer, ShopSettings } from '../types';
import { TRANSLATIONS } from '../constants';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';
import { motion, AnimatePresence } from 'framer-motion';

interface FinanceProps {
  sales: Sale[];
  expenses: Expense[];
  staffList: Staff[];
  customers: Customer[];
  currency: string;
  language: Language;
  currentUser: Staff;
  onAddExpense: (expense: Expense) => void;
  onDeleteExpense: (id: string) => void;
  onDeleteSales: (ids: string[]) => void;
  settings: ShopSettings;
}

const Finance: React.FC<FinanceProps> = ({ sales, expenses, staffList, customers, currency, language, currentUser, onAddExpense, onDeleteExpense, onDeleteSales, settings }) => {
  const [activeTab, setActiveTab] = useState<'overview' | 'transactions' | 'expenses'>(currentUser.role === 'admin' ? 'overview' : 'expenses');
  const [newExp, setNewExp] = useState<{ category: string; amount: number; description: string; receiptImage: string | null }>({ 
    category: '', 
    amount: 0, 
    description: '',
    receiptImage: null 
  });
  const [viewingReceipt, setViewingReceipt] = useState<string | null>(null);
  const [viewingSale, setViewingSale] = useState<Sale | null>(null);
  const [selectedTransactions, setSelectedTransactions] = useState<Set<string>>(new Set());

  const fileInputRef = useRef<HTMLInputElement>(null);
  const t = TRANSLATIONS[language];

  // --- DATA CONNECTION LOGIC ---
  // This automatically links Sales IDs to actual Names from the database lists.
  // It effectively replicates a database JOIN on the client side for instant updates.
  const enrichedSales = useMemo(() => {
    return sales.map(sale => {
      const staffMember = staffList.find(s => s.id === sale.staffId);
      const customer = customers.find(c => c.id === sale.customerId);
      return {
        ...sale,
        // Fallback to ID or 'Unknown' if not found
        staffName: staffMember ? staffMember.name : (sale.staffName || 'Unknown Staff'),
        customerName: customer ? customer.name : (sale.customerName || 'Walk-in Client')
      };
    });
  }, [sales, staffList, customers]);

  const totalRevenue = sales.reduce((a, b) => a + b.total, 0);
  const totalExpenses = expenses.reduce((a, b) => a + b.amount, 0);

  const toggleSelection = (id: string) => {
    const newSet = new Set(selectedTransactions);
    if (newSet.has(id)) newSet.delete(id);
    else newSet.add(id);
    setSelectedTransactions(newSet);
  };

  const toggleAll = () => {
    if (selectedTransactions.size === enrichedSales.length) {
      setSelectedTransactions(new Set());
    } else {
      setSelectedTransactions(new Set(enrichedSales.map(s => s.id)));
    }
  };

  const handleDeleteSelected = () => {
     if (selectedTransactions.size === 0) return;

     if (confirm(`⚠️ PERMANENT DELETE\n\nAre you sure you want to delete ${selectedTransactions.size} transactions?\nThis will remove them from the database and cannot be undone.`)) {
       onDeleteSales(Array.from(selectedTransactions));
       setSelectedTransactions(new Set());
     }
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      const img = new Image();
      img.onload = () => {
        const canvas = document.createElement('canvas');
        let width = img.width;
        let height = img.height;
        const MAX_SIZE = 800;

        if (width > height) {
          if (width > MAX_SIZE) {
            height *= MAX_SIZE / width;
            width = MAX_SIZE;
          }
        } else {
          if (height > MAX_SIZE) {
            width *= MAX_SIZE / height;
            height = MAX_SIZE;
          }
        }

        canvas.width = width;
        canvas.height = height;
        const ctx = canvas.getContext('2d');
        ctx?.drawImage(img, 0, 0, width, height);

        const dataUrl = canvas.toDataURL('image/jpeg', 0.7);
        setNewExp(prev => ({ ...prev, receiptImage: dataUrl }));
      };
      if (event.target?.result) {
        img.src = event.target.result as string;
      }
    };
    reader.readAsDataURL(file);
  };

  const renderReceiptModal = () => {
    if (!viewingSale) return null;

    // Ensure we have the names, even if looking at raw sale object
    const staffName = viewingSale.staffName || staffList.find(s => s.id === viewingSale.staffId)?.name || 'Unknown';
    const customerName = viewingSale.customerName || customers.find(c => c.id === viewingSale.customerId)?.name || 'Walk-in';

    return (
      <motion.div 
        initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}
        className="fixed inset-0 bg-slate-950/80 backdrop-blur-sm z-[200] flex items-center justify-center p-4"
        onClick={() => setViewingSale(null)}
      >
        <motion.div 
          initial={{ scale: 0.9, y: 20 }} animate={{ scale: 1, y: 0 }}
          className="bg-white text-slate-900 w-full max-w-sm rounded-3xl overflow-hidden shadow-2xl relative"
          onClick={e => e.stopPropagation()}
        >
           <div className="bg-slate-900 text-white p-6 text-center relative">
              <h2 className="font-brand text-2xl font-bold">{settings.shopName}</h2>
              <p className="text-xs text-slate-400 uppercase tracking-widest mt-1">Official Receipt</p>
              <button onClick={() => setViewingSale(null)} className="absolute top-4 right-4 text-slate-400 hover:text-white">
                <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12"/></svg>
              </button>
           </div>
           <div className="p-6 space-y-4">
              <div className="flex justify-between text-xs text-slate-500 font-medium border-b border-slate-100 pb-4">
                 <div className="space-y-1">
                    <p className="flex items-center gap-1"><span className="opacity-50">Date:</span> {new Date(viewingSale.timestamp).toLocaleDateString()}</p>
                    <p className="flex items-center gap-1"><span className="opacity-50">Time:</span> {new Date(viewingSale.timestamp).toLocaleTimeString()}</p>
                    <p className="font-mono text-[10px] opacity-70">ID: #{viewingSale.id.slice(0,8)}</p>
                 </div>
                 <div className="space-y-1 text-right">
                    <p className="font-bold text-slate-800">{staffName}</p>
                    <p className="text-slate-400">{customerName}</p>
                 </div>
              </div>

              <div className="space-y-3 py-2 max-h-60 overflow-y-auto scrollbar-hide">
                 {viewingSale.items.map((item, idx) => (
                   <div key={idx} className="flex justify-between text-sm items-start">
                      <div className="flex gap-2">
                        <span className="font-black text-slate-300 text-xs mt-0.5">{item.quantity}x</span>
                        <span className="font-bold text-slate-800 leading-tight">{item.name}</span>
                      </div>
                      <span className="font-medium text-slate-600 whitespace-nowrap">{currency}{(item.price * item.quantity).toFixed(2)}</span>
                   </div>
                 ))}
              </div>

              <div className="border-t border-slate-100 pt-4 space-y-2">
                 <div className="flex justify-between text-xs text-slate-500">
                    <span>Subtotal</span>
                    <span>{currency}{(viewingSale.total - viewingSale.tax + viewingSale.discount).toFixed(2)}</span>
                 </div>

                 {viewingSale.discount > 0 && (
                   <div className="flex justify-between text-xs text-emerald-600">
                      <span>Discount {viewingSale.discountCode ? `(${viewingSale.discountCode})` : ''}</span>
                      <span>-{currency}{viewingSale.discount.toFixed(2)}</span>
                   </div>
                 )}

                 <div className="flex justify-between text-xs text-slate-500">
                    <span>Tax {settings.taxType === 'included' ? '(Inc.)' : ''}</span>
                    <span>{currency}{viewingSale.tax.toFixed(2)}</span>
                 </div>

                 <div className="flex justify-between text-xl font-black text-slate-900 pt-2 border-t border-dashed border-slate-200 mt-2">
                    <span>Total</span>
                    <span>{currency}{viewingSale.total.toFixed(2)}</span>
                 </div>

                 <div className="text-center pt-4">
                    <span className={`px-4 py-1.5 rounded-lg text-[10px] font-black uppercase tracking-widest ${viewingSale.paymentMethod === 'card' ? 'bg-indigo-100 text-indigo-600' : 'bg-emerald-100 text-emerald-600'}`}>
                        Paid via {viewingSale.paymentMethod}
                    </span>
                 </div>
              </div>
           </div>
           <div className="bg-slate-50 p-4 text-center">
              <p className="text-[10px] text-slate-400 italic">{settings.receiptFooter}</p>
           </div>
        </motion.div>
      </motion.div>
    );
  };

  return (
    <div className="space-y-6 max-w-6xl mx-auto pb-24 md:pb-10">
      <div className="flex bg-white dark:bg-slate-900 p-1.5 rounded-2xl shadow-sm border border-slate-100 dark:border-slate-800 overflow-x-auto no-scrollbar sticky top-0 z-20">
        <div className="flex gap-1 min-w-max w-full">
           {currentUser.role === 'admin' && (
             <>
               <button onClick={() => setActiveTab('overview')} className={`flex-1 md:flex-none px-6 py-2.5 rounded-xl text-xs font-black uppercase tracking-widest transition-all ${activeTab === 'overview' ? 'bg-amber-500 text-slate-950' : 'text-slate-400'}`}>Overview</button>
               <button onClick={() => setActiveTab('transactions')} className={`flex-1 md:flex-none px-6 py-2.5 rounded-xl text-xs font-black uppercase tracking-widest transition-all ${activeTab === 'transactions' ? 'bg-amber-500 text-slate-950' : 'text-slate-400'}`}>Transactions</button>
             </>
           )}
           <button onClick={() => setActiveTab('expenses')} className={`flex-1 md:flex-none px-6 py-2.5 rounded-xl text-xs font-black uppercase tracking-widest transition-all ${activeTab === 'expenses' ? 'bg-amber-500 text-slate-950' : 'text-slate-400'}`}>Expenses</button>
        </div>
      </div>

      <AnimatePresence mode="wait">
        {activeTab === 'overview' && (
          <motion.div key="ov" initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="space-y-8">
            <div className="bg-white dark:bg-slate-900 p-6 md:p-8 rounded-[2rem] border border-slate-100 dark:border-slate-800">
