                                  >
                                    <img src={e.receiptImage} alt="Receipt" className="w-full h-full object-cover" />
                                  </button>
                                ) : (
                                  <span className="text-slate-300 text-xs">No img</span>
                                )}
                              </td>
                              <td className="p-6 text-right font-black text-rose-500">{currency}{e.amount.toFixed(2)}</td>
                              <td className="p-6 text-center"><button onClick={() => onDeleteExpense(e.id)} className="text-slate-300 hover:text-rose-500 transition-colors p-2"><svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"/></svg></button></td>
                           </tr>
                         ))}
                         {expenses.length === 0 && (
                            <tr>
                               <td colSpan={6} className="p-8 text-center text-slate-400 italic">No expenses recorded.</td>
                            </tr>
                         )}
                      </tbody>
                   </table>
                </div>
             </div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* Full Screen Receipt Modal */}
      <AnimatePresence>
        {viewingReceipt && (
          <motion.div 
            initial={{ opacity: 0 }} 
            animate={{ opacity: 1 }} 
            exit={{ opacity: 0 }}
            className="fixed inset-0 bg-slate-950/90 backdrop-blur-sm z-[200] flex items-center justify-center p-4"
            onClick={() => setViewingReceipt(null)}
          >
             <div className="relative max-w-2xl w-full max-h-[90vh]">
               <button 
                 onClick={() => setViewingReceipt(null)}
