              className={`fixed bottom-0 left-0 right-0 lg:static lg:w-96 flex flex-col bg-white dark:bg-slate-900 rounded-t-[2.5rem] lg:rounded-[2.5rem] border border-slate-100 dark:border-slate-800 shadow-2xl lg:shadow-xl overflow-hidden z-[80] h-[90vh] lg:h-auto`}
            >
              <div className="p-5 md:p-6 border-b border-slate-50 dark:border-slate-800 bg-slate-50/50 dark:bg-slate-800/20 flex justify-between items-center">
                <h3 className="text-lg md:text-xl font-black text-slate-800 dark:text-white flex items-center gap-2">{t.cart}</h3>
                <button onClick={() => setShowMobileCart(false)} className="lg:hidden p-2 text-slate-400 bg-slate-100 dark:bg-slate-800 rounded-full"><svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M6 18L18 6M6 6l12 12"/></svg></button>
              </div>
              <div className="flex-1 overflow-y-auto p-5 md:p-6 space-y-5 scrollbar-hide">
                <div>
                  <label className="text-[9px] md:text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-2 ml-1">{t.professional}</label>
                  <select value={selectedStaff} onChange={e => setSelectedStaff(e.target.value)} disabled={currentUser.role === 'employee'} className="w-full bg-slate-50 dark:bg-slate-800 border-none rounded-2xl px-4 py-3 text-sm font-bold dark:text-white disabled:opacity-50">
                    <option value="">{t.chooseProfessional}</option>
                    {staff.map(s => <option key={s.id} value={s.id}>{s.name}</option>)}
                  </select>
                </div>
                <div className="space-y-3">
                   <div className="flex justify-between items-end">
                      <label className="text-[9px] md:text-[10px] font-black text-slate-400 uppercase tracking-widest block">{t.customers}</label>
                      <button onClick={() => setIsAddingCustomer(true)} className="text-[9px] md:text-[10px] font-black text-amber-600 uppercase tracking-widest hover:text-amber-500 transition-colors">{t.quickAddClient}</button>
                   </div>
                   <select value={selectedCustomer} onChange={e => setSelectedCustomer(e.target.value)} className="w-full bg-slate-50 dark:bg-slate-800 border-none rounded-2xl px-4 py-3 text-sm font-bold dark:text-white">
                     <option value="">{t.walkInClient}</option>
                     {customers.map(c => <option key={c.id} value={c.id}>{c.name} ({c.phone})</option>)}
                   </select>
                </div>
                <div className="h-px bg-slate-50 dark:bg-slate-800 my-2"></div>
                {cart.map((item, idx) => (
                  <div key={idx} className="flex justify-between items-center group py-1">
                    <div className="flex-1">
                      <p className="font-bold text-slate-800 dark:text-slate-200 text-xs md:text-sm leading-tight">{item.name}</p>
                      <div className="flex items-center gap-1 mt-0.5">
                          <p className="text-[10px] text-slate-400 font-medium">{settings.currency}{item.price}</p>
                          {item.quantity > 1 && (
                              <p className="text-[10px] font-bold text-slate-600 dark:text-slate-300 bg-slate-100 dark:bg-slate-800 px-1.5 rounded-md">
                                  = {settings.currency}{(item.price * item.quantity).toFixed(2)}
                              </p>
                          )}
                      </div>
                    </div>
                    <div className="flex items-center gap-2 md:gap-3">
                      <div className="flex items-center bg-slate-100 dark:bg-slate-800 rounded-xl px-1.5 md:px-2">
                         <button onClick={() => updateQuantity(item.id, item.type, -1)} className="p-1.5 text-slate-400 hover:text-amber-500 transition-colors">-</button>
                         <span className="w-6 text-center text-xs font-black dark:text-white">{item.quantity}</span>
                         <button onClick={() => updateQuantity(item.id, item.type, 1)} className="p-1.5 text-slate-400 hover:text-amber-500 transition-colors">+</button>
                      </div>
                      <button onClick={() => removeFromCart(item.id, item.type)} className="text-slate-300 hover:text-rose-500 p-1 md:opacity-0 lg:group-hover:opacity-100 transition-all">
                        <svg className="w-4 h-4 md:w-5 md:h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"/></svg>
                      </button>
                    </div>
                  </div>
                ))}
                {cart.length === 0 && <p className="text-center py-10 text-slate-300 italic text-sm">{t.emptyCart}</p>}
              </div>
              <div className="p-6 md:p-8 bg-slate-50/50 dark:bg-slate-800/20 border-t border-slate-100 dark:border-slate-800 space-y-4">
                <div className="space-y-2 text-xs font-bold text-slate-500">
                  <div className="flex justify-between">
                      <span>{t.subtotal}</span>
                      <motion.span key={totals.subtotal} className="text-slate-900 dark:text-white">
                          {settings.currency}{totals.subtotal.toFixed(2)}
                      </motion.span>
                  </div>
                  {totals.discount > 0 && <div className="flex justify-between text-emerald-500"><span>{t.discount}</span><span>-{settings.currency}{totals.discount.toFixed(2)}</span></div>}
                  <div className="flex justify-between text-xl md:text-2xl font-black text-slate-900 dark:text-white pt-2 border-t border-slate-100 dark:border-slate-800">
                      <span>{t.total}</span>
                      <motion.span key={totals.total} className="text-amber-500">
                          {settings.currency}{totals.total.toFixed(2)}
                      </motion.span>
                  </div>
                </div>
                <div className="flex gap-2">
                   <input value={discountCode} onChange={e => setDiscountCode(e.target.value.toUpperCase())} placeholder="PROMO" className="flex-1 bg-white dark:bg-slate-900 border-none rounded-xl px-4 py-3 text-xs font-black uppercase tracking-widest dark:text-white shadow-sm" />
                   <button onClick={handleHoldSale} className="bg-slate-200 dark:bg-slate-800 text-slate-600 dark:text-slate-400 px-4 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all active:scale-95">{t.holdBill}</button>
                </div>
                <div className="grid grid-cols-2 gap-3 pb-4">
                   <button onClick={() => handleCheckout('cash')} className="bg-slate-900 dark:bg-slate-950 text-white py-4 md:py-5 rounded-2xl font-black text-xs md:text-sm uppercase tracking-widest hover:bg-slate-800 transition-all shadow-xl active:scale-95">{t.cash}</button>
                   <button onClick={() => handleCheckout('card')} className="bg-amber-500 text-slate-950 py-4 md:py-5 rounded-2xl font-black text-xs md:text-sm uppercase tracking-widest hover:bg-amber-400 transition-all shadow-xl active:scale-95">{t.card}</button>
                </div>
              </div>
            </motion.div>
          </>
        )}
      </AnimatePresence>

      <AnimatePresence>
        {isScanning && (
          <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="fixed inset-0 bg-slate-950/90 backdrop-blur-md z-[200] flex items-center justify-center p-4">
            <div className="w-full max-w-md bg-white dark:bg-slate-900 rounded-[2rem] overflow-hidden shadow-2xl relative">
                <div className="p-6 border-b border-slate-100 dark:border-slate-800 flex justify-between items-center">
                    <h3 className="font-black text-slate-900 dark:text-white text-lg flex items-center gap-2">
                        <svg className="w-5 h-5 text-amber-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 4v1m6 11h2m-6 0h-2v4m0-11v3m0 0h.01M12 12h4.01M16 20h4M4 12h4m12 0h.01M5 8h2a1 1 0 001-1V5a1 1 0 00-1-1H5a1 1 0 00-1 1v2a1 1 0 001 1zm12 0h2a1 1 0 001-1V5a1 1 0 00-1-1h-2a1 1 0 00-1 1v2a1 1 0 001 1zM5 20h2a1 1 0 001-1v-2a1 1 0 00-1-1H5a1 1 0 00-1 1v2a1 1 0 001 1z"/></svg>
                        {t.scanBarcode}
                    </h3>
                    <button onClick={() => setIsScanning(false)} className="p-2 bg-slate-100 dark:bg-slate-800 rounded-full text-slate-500 hover:text-rose-500 transition-colors">
                        <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12"/></svg>
                    </button>
                </div>
                <div className="bg-black relative aspect-square w-full overflow-hidden">
                    {/* Simplified scanner UI: The library creates its own rendering container */}
                    <div id="reader" className="w-full h-full"></div>

                    {/* Visual guide to match physical placement */}
                    <div className="absolute inset-0 pointer-events-none flex items-center justify-center">
                        <div className="w-48 h-48 border-2 border-amber-500/50 rounded-2xl shadow-[0_0_0_9999px_rgba(0,0,0,0.5)]"></div>
                    </div>

                    <AnimatePresence>
                        {scanningFeedback && (
                            <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0 }} className={`absolute bottom-4 left-4 right-4 p-3 rounded-xl text-center font-bold text-sm shadow-lg z-20 ${feedbackType === 'success' ? 'bg-emerald-500 text-white' : 'bg-rose-500 text-white'}`}>
                                {scanningFeedback}
                            </motion.div>
                        )}
                    </AnimatePresence>
                </div>
                <div className="p-4 text-center bg-slate-50 dark:bg-slate-800 text-xs text-slate-500">
                    <p>Align barcode within the center square</p>
                </div>
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
};

export default POS;

import React, { useState, useRef, useEffect } from 'react';
import { Service, Product, ShopSettings } from '../types';
import { TRANSLATIONS } from '../constants';
import { motion, AnimatePresence } from 'framer-motion';
import { Html5Qrcode } from 'html5-qrcode';

interface InventoryProps {
  services: Service[];
  products: Product[];
  settings: ShopSettings;
  onUpdateServices: (services: Service[]) => void;
  onUpdateProducts: (products: Product[]) => void;
}

const Inventory: React.FC<InventoryProps> = ({ services, products, settings, onUpdateServices, onUpdateProducts }) => {
  const [activeTab, setActiveTab] = useState<'services' | 'products'>('services');
  const [isEditing, setIsEditing] = useState<any>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [isScanning, setIsScanning] = useState(false);
  const html5QrCodeRef = useRef<Html5Qrcode | null>(null);
  const isScannerActiveRef = useRef(false);
  const barcodeInputRef = useRef<HTMLInputElement>(null);

  const t = TRANSLATIONS[settings.language];

  useEffect(() => {
    let isMounted = true;
    if (isScanning) {
        const startScanner = async () => {
            await new Promise(resolve => setTimeout(resolve, 800));
            if (!isMounted || !isScanning) return;
            try {
                if (!html5QrCodeRef.current) {
                  html5QrCodeRef.current = new Html5Qrcode("reader-inventory");
                }

                await html5QrCodeRef.current.start(
                    { facingMode: "environment" }, 
                    { 
                        fps: 15, 
                        qrbox: (w, h) => {
                            const size = Math.min(w, h) * 0.7;
                            return { width: size, height: size };
                        },
                        aspectRatio: 1.0,
                        disableFlip: true
                    }, 
                    (decodedText) => {
                        if (isMounted) {
                            if (barcodeInputRef.current) barcodeInputRef.current.value = decodedText;
                            setIsScanning(false);
                        }
                    },
                    () => {}
                );
                if (isMounted) isScannerActiveRef.current = true;
            } catch (err) {
                 console.error("Inventory scanner start error", err);
                 if (isMounted) setIsScanning(false);
            }
        };
        startScanner();
    }
    return () => {
        isMounted = false;
        if (html5QrCodeRef.current) {
            const scanner = html5QrCodeRef.current;
            if (isScannerActiveRef.current) {
                scanner.stop().catch(() => {}).finally(() => {
                    try { scanner.clear(); } catch(e) {}
                    isScannerActiveRef.current = false;
                });
            } else {
                try { scanner.clear(); } catch(e) {}
            }
        }
    };
  }, [isScanning]);

  const filteredServices = services.filter(s => s.name.toLowerCase().includes(searchTerm.toLowerCase()) || s.category.toLowerCase().includes(searchTerm.toLowerCase()));
  const filteredProducts = products.filter(p => p.name.toLowerCase().includes(searchTerm.toLowerCase()) || (p.barcode && p.barcode.includes(searchTerm)));

  const deleteItem = (id: string, type: 'service' | 'product') => {
    if (!confirm('Permanently delete this entry?')) return;
    if (type === 'service') onUpdateServices(services.filter(s => s.id !== id));
    else onUpdateProducts(products.filter(p => p.id !== id));
  };

  const saveItem = (e: React.FormEvent) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget as HTMLFormElement);
    const itemData = Object.fromEntries(formData.entries());
    if (activeTab === 'services') {
      const newService: Service = {
        id: isEditing?.id || Math.random().toString(36).substr(2, 9).toUpperCase(),
        name: itemData.name as string,
        price: parseFloat(itemData.price as string) || 0,
        duration: parseInt(itemData.duration as string) || 30,
        category: itemData.category as string,
      };
      if (isEditing.id) onUpdateServices(services.map(s => s.id === isEditing.id ? newService : s));
      else onUpdateServices([...services, newService]);
    } else {
      const newProduct: Product = {
        id: isEditing?.id || Math.random().toString(36).substr(2, 9).toUpperCase(),
        name: itemData.name as string,
        price: parseFloat(itemData.price as string) || 0,
        cost: parseFloat(itemData.cost as string) || 0,
        stock: parseInt(itemData.stock as string) || 0,
        barcode: (itemData.barcode as string) || undefined,
        lowStockThreshold: parseInt(itemData.lowStockThreshold as string) || 15
      };
      if (isEditing.id) onUpdateProducts(products.map(p => p.id === isEditing.id ? newProduct : p));
      else onUpdateProducts([...products, newProduct]);
    }
    setIsEditing(null);
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
        <div>
          <h2 className="text-2xl md:text-3xl font-bold text-slate-800 dark:text-white font-brand">{t.shopCatalog}</h2>
          <p className="text-slate-500 dark:text-slate-400 text-sm">{t.updatePrices}</p>
        </div>
        <button onClick={() => setIsEditing({})} className="bg-slate-950 dark:bg-slate-800 text-white px-6 py-3 rounded-xl font-black flex items-center gap-2 hover:bg-slate-800 transition-all shadow-lg text-sm w-full sm:w-auto justify-center">
          <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M12 6v6m0 0v6m0-6h6m-6 0H6"/></svg>
          {activeTab === 'services' ? t.newService : t.newProduct}
        </button>
      </div>
      <div className="relative">
        <svg className="w-5 h-5 absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 dark:text-slate-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z"/></svg>
        <input type="text" placeholder={t.searchCatalog} value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} className="w-full bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-2xl py-3.5 pl-12 pr-6 outline-none focus:ring-4 focus:ring-amber-500/10 shadow-sm text-sm dark:text-slate-200" />
      </div>
      <div className="flex bg-white dark:bg-slate-900 p-1 rounded-xl shadow-sm border border-slate-100 dark:border-slate-800 self-start w-full sm:w-auto">
        <button onClick={() => setActiveTab('services')} className={`flex-1 sm:px-8 py-2.5 rounded-lg font-bold transition-all text-xs md:text-sm ${activeTab === 'services' ? 'bg-amber-500 text-slate-950 shadow-sm' : 'text-slate-400 dark:text-slate-500 hover:text-slate-600'}`}>{t.services}</button>
        <button onClick={() => setActiveTab('products')} className={`flex-1 sm:px-8 py-2.5 rounded-lg font-bold transition-all text-xs md:text-sm ${activeTab === 'products' ? 'bg-amber-500 text-slate-950 shadow-sm' : 'text-slate-400 dark:text-slate-500 hover:text-slate-600'}`}>{t.inventory}</button>
      </div>
      <div className="md:hidden space-y-4">
        {(activeTab === 'services' ? filteredServices : filteredProducts).map((item: any) => (
           <div key={item.id} className="bg-white dark:bg-slate-900 p-5 rounded-2xl border border-slate-100 dark:border-slate-800 shadow-sm">
              <div className="flex justify-between items-start mb-2">
                 <h4 className="font-bold text-slate-800 dark:text-slate-200">{item.name}</h4>
                 <span className="text-xl font-black text-amber-500">{settings.currency}{item.price}</span>
              </div>
              <div className="flex gap-2 mt-4">
                  <button onClick={() => setIsEditing(item)} className="flex-1 py-2 rounded-lg bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-300 font-bold text-xs uppercase tracking-wider">Edit</button>
                  <button onClick={() => deleteItem(item.id, activeTab === 'services' ? 'service' : 'product')} className="px-3 py-2 rounded-lg bg-rose-50 dark:bg-rose-900/20 text-rose-500"><svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"/></svg></button>
              </div>
           </div>
        ))}
      </div>
      <div className="hidden md:block bg-white dark:bg-slate-900 rounded-[2rem] border border-slate-100 dark:border-slate-800 shadow-sm overflow-hidden">
        <table className="w-full text-left">
          <thead className="bg-slate-50 dark:bg-slate-800/50 border-b border-slate-100 dark:border-slate-800 text-[10px] font-black text-slate-400 uppercase tracking-widest">
            <tr><th className="px-8 py-5">Item</th><th className="px-8 py-5">Status</th><th className="px-8 py-5">Price</th><th className="px-8 py-5 text-right">Actions</th></tr>
          </thead>
          <tbody className="divide-y divide-slate-50 dark:divide-slate-800">
            {(activeTab === 'services' ? filteredServices : filteredProducts).map((item: any) => (
              <tr key={item.id} className="hover:bg-slate-50/30 dark:hover:bg-slate-800/30">
                <td className="px-8 py-6 font-bold text-slate-800 dark:text-slate-200 text-sm">{item.name}</td>
                <td className="px-8 py-6 text-xs text-slate-500">{activeTab === 'services' ? item.category : `${item.stock} left`}</td>
                <td className="px-8 py-6 font-black text-slate-950 dark:text-white">{settings.currency}{item.price}</td>
                <td className="px-8 py-6 text-right space-x-2">
                  <button onClick={() => setIsEditing(item)} className="p-2 text-slate-300 hover:text-amber-500"><svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z"/></svg></button>
                  <button onClick={() => deleteItem(item.id, activeTab === 'services' ? 'service' : 'product')} className="p-2 text-slate-300 hover:text-rose-500"><svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"/></svg></button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
      <AnimatePresence>
        {isEditing && (
          <div className="fixed inset-0 bg-slate-950/40 backdrop-blur-sm z-[100] flex items-end sm:items-center justify-center p-0 sm:p-4">
            <motion.div initial={{ y: "100%" }} animate={{ y: 0 }} exit={{ y: "100%" }} className="bg-white dark:bg-slate-900 rounded-t-[2.5rem] sm:rounded-[2.5rem] w-full max-w-md p-8 md:p-10 shadow-2xl overflow-y-auto max-h-[90vh]">
              <div className="flex justify-between items-center mb-8"><h3 className="text-2xl font-black text-slate-900 dark:text-white tracking-tight">{isEditing.id ? t.editEntry : t.newEntry}</h3><button onClick={() => setIsEditing(null)} className="p-2 bg-slate-50 dark:bg-slate-800 rounded-full text-slate-400"><svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M6 18L18 6M6 6l12 12"/></svg></button></div>
              <form onSubmit={saveItem} className="space-y-5">
                <div><label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-2 ml-1">Name</label><input name="name" type="text" defaultValue={isEditing.name || ''} required className="w-full bg-slate-50 dark:bg-slate-800 border-0 rounded-2xl px-5 py-3.5 focus:ring-4 focus:ring-amber-500/10 outline-none text-sm font-bold dark:text-slate-200" /></div>
                {activeTab === 'products' && (
                  <div><label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-2 ml-1">Barcode</label><div className="flex gap-2"><input ref={barcodeInputRef} name="barcode" type="text" defaultValue={isEditing.barcode || ''} className="w-full bg-slate-50 dark:bg-slate-800 border-0 rounded-2xl px-5 py-3.5 focus:ring-4 focus:ring-amber-500/10 outline-none text-sm font-bold dark:text-slate-200" /><button type="button" onClick={() => setIsScanning(true)} className="bg-slate-900 text-white p-3.5 rounded-2xl"><svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 4v1m6 11h2m-6 0h-2v4m0-11v3m0 0h.01M12 12h4.01M16 20h4M4 12h4m12 0h.01M5 8h2a1 1 0 001-1V5a1 1 0 00-1-1H5a1 1 0 00-1 1v2a1 1 0 001 1zm12 0h2a1 1 0 001-1V5a1 1 0 00-1-1h-2a1 1 0 00-1 1v2a1 1 0 001 1zM5 20h2a1 1 0 001-1v-2a1 1 0 00-1-1H5a1 1 0 00-1 1v2a1 1 0 001 1z"/></svg></button></div></div>
                )}
                <div className="grid grid-cols-2 gap-4">
                  <div><label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-2 ml-1">Price</label><input name="price" type="number" step="0.01" defaultValue={isEditing.price || ''} required className="w-full bg-slate-50 dark:bg-slate-800 border-0 rounded-2xl px-5 py-3.5 focus:ring-4 focus:ring-amber-500/10 outline-none text-sm font-bold dark:text-slate-200" /></div>
                  {activeTab === 'services' ? <div><label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-2 ml-1">Mins</label><input name="duration" type="number" defaultValue={isEditing.duration || 30} className="w-full bg-slate-50 dark:bg-slate-800 border-0 rounded-2xl px-5 py-3.5 focus:ring-4 focus:ring-amber-500/10 outline-none text-sm font-bold dark:text-slate-200" /></div> : <div><label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-2 ml-1">Stock</label><input name="stock" type="number" defaultValue={isEditing.stock || 0} className="w-full bg-slate-50 dark:bg-slate-800 border-0 rounded-2xl px-5 py-3.5 focus:ring-4 focus:ring-amber-500/10 outline-none text-sm font-bold dark:text-slate-200" /></div>}
                </div>
                {activeTab === 'services' && (
                  <div><label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-2 ml-1">Category</label><input name="category" type="text" defaultValue={isEditing.category || ''} required className="w-full bg-slate-50 dark:bg-slate-800 border-0 rounded-2xl px-5 py-3.5 focus:ring-4 focus:ring-amber-500/10 outline-none text-sm font-bold dark:text-slate-200" /></div>
                )}
                <button type="submit" className="w-full py-4 bg-amber-500 text-slate-950 rounded-2xl font-black text-base shadow-xl mt-4">Save Changes</button>
              </form>
            </motion.div>
          </div>
        )}
      </AnimatePresence>
      <AnimatePresence>
        {isScanning && (
          <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="fixed inset-0 bg-slate-950/90 backdrop-blur-md z-[200] flex items-center justify-center p-4">
            <div className="w-full max-w-md bg-white dark:bg-slate-900 rounded-[2rem] overflow-hidden shadow-2xl relative">
                <div className="p-6 border-b border-slate-100 dark:border-slate-800 flex justify-between items-center"><h3 className="font-black text-slate-900 dark:text-white text-lg flex items-center gap-2">Scanner</h3><button onClick={() => setIsScanning(false)} className="p-2 bg-slate-100 dark:bg-slate-800 rounded-full text-slate-500"><svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12"/></svg></button></div>
                <div className="bg-black relative aspect-square w-full overflow-hidden">
                    <div id="reader-inventory" className="w-full h-full"></div>
                    <div className="absolute inset-0 pointer-events-none flex items-center justify-center">
                        <div className="w-48 h-48 border-2 border-amber-500/50 rounded-2xl shadow-[0_0_0_9999px_rgba(0,0,0,0.5)]"></div>
                    </div>
                </div>
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
};

export default Inventory;

import React, { useState, useRef, useMemo, useEffect } from 'react';
import { Sale, Expense, Staff, Language, Customer, ShopSettings } from '../types';
import { TRANSLATIONS } from '../constants';
import { getFinancialInsights } from '../services/geminiService';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';
import { motion, AnimatePresence } from 'framer-motion';
import ReactMarkdown from 'react-markdown';

interface FinanceProps {
  sales: Sale[];
  expenses: Expense[];
  staffList: Staff[];
  customers: Customer[];
  currency: string;
  language: Language;
  currentUser: Staff;
  onAddExpense: (expense: Expense) => void;
  onDeleteExpense: (id: string) => void;
  onDeleteSales: (ids: string[]) => void;
  settings: ShopSettings;
}

const Finance: React.FC<FinanceProps> = ({ sales, expenses, staffList, customers, currency, language, currentUser, onAddExpense, onDeleteExpense, onDeleteSales, settings }) => {
  const [activeTab, setActiveTab] = useState<'overview' | 'transactions' | 'expenses'>(currentUser.role === 'admin' ? 'overview' : 'expenses');
  const [newExp, setNewExp] = useState<{ category: string; amount: string; description: string; receiptImage: string | null }>({ 
    category: '', 
    amount: '', 
    description: '',
    receiptImage: null 
  });
  const [viewingSale, setViewingSale] = useState<Sale | null>(null);
  const [selectedTransactions, setSelectedTransactions] = useState<Set<string>>(new Set());
  const [aiAdvice, setAiAdvice] = useState<string>('');
  const [generatingAdvice, setGeneratingAdvice] = useState(false);

  // Hide tab bar on scroll logic
  const [isTabBarVisible, setIsTabBarVisible] = useState(true);
  const lastScrollY = useRef(0);

  useEffect(() => {
    const mainContainer = document.querySelector('main');
    if (!mainContainer) return;
    const handleScroll = () => {
      const currentScrollY = mainContainer.scrollTop;
      // Threshold to avoid flicker on small scrolls
      if (currentScrollY > lastScrollY.current && currentScrollY > 60) {
        setIsTabBarVisible(false);
      } else {
        setIsTabBarVisible(true);
      }
      lastScrollY.current = currentScrollY;
    };
    mainContainer.addEventListener('scroll', handleScroll);
    return () => mainContainer.removeEventListener('scroll', handleScroll);
  }, []);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const t = TRANSLATIONS[language];

  const enrichedSales = useMemo(() => {
    return sales.map(sale => {
      const staffMember = staffList.find(s => s.id === sale.staffId);
      const customer = customers.find(c => c.id === sale.customerId);
      return {
        ...sale,
        staffName: sale.staffName || (staffMember ? staffMember.name : 'Unknown Staff'),
        customerName: sale.customerName || (customer ? customer.name : 'Walk-in Client')
      };
    });
  }, [sales, staffList, customers]);

  const totalRevenue = sales.reduce((a, b) => a + b.total, 0);
  const totalExpenses = expenses.reduce((a, b) => a + b.amount, 0);

  const toggleSelection = (id: string) => {
    const newSet = new Set(selectedTransactions);
    if (newSet.has(id)) newSet.delete(id);
    else newSet.add(id);
    setSelectedTransactions(newSet);
  };

  const toggleAll = () => {
    if (selectedTransactions.size === enrichedSales.length) {
      setSelectedTransactions(new Set());
    } else {
      setSelectedTransactions(new Set(enrichedSales.map(s => s.id)));
    }
  };

  const handleDeleteSelected = () => {
     if (selectedTransactions.size === 0) return;
     if (confirm(`⚠️ DELETE DATA\n\nAre you sure you want to delete ${selectedTransactions.size} transactions?\nThis action cannot be undone.`)) {
       onDeleteSales(Array.from(selectedTransactions));
       setSelectedTransactions(new Set());
     }
  };

  const handleGenerateAdvice = async () => {
    setGeneratingAdvice(true);
    try {
      const advice = await getFinancialInsights(sales, expenses);
      setAiAdvice(advice);
    } catch (e) {
      setAiAdvice("Insight generation failed.");
    } finally {
      setGeneratingAdvice(false);
    }
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      const img = new Image();
      img.onload = () => {
        const canvas = document.createElement('canvas');
        let width = img.width;
        let height = img.height;
        const MAX_SIZE = 800;
        if (width > height) { if (width > MAX_SIZE) { height *= MAX_SIZE / width; width = MAX_SIZE; } } 
        else { if (height > MAX_SIZE) { width *= MAX_SIZE / height; height = MAX_SIZE; } }
        canvas.width = width; canvas.height = height;
        const ctx = canvas.getContext('2d');
        ctx?.drawImage(img, 0, 0, width, height);
        setNewExp(prev => ({ ...prev, receiptImage: canvas.toDataURL('image/jpeg', 0.7) }));
      };
      if (event.target?.result) img.src = event.target.result as string;
    };
    reader.readAsDataURL(file);
  };

  const handleAddExpenseSubmit = (e: React.FormEvent) => {
      e.preventDefault();
      if (!newExp.category || !newExp.amount) return;
      onAddExpense({
          id: Math.random().toString(36).substr(2, 9),
          date: new Date().toISOString().split('T')[0],
          category: newExp.category,
          amount: parseFloat(newExp.amount),
          description: newExp.description,
          receiptImage: newExp.receiptImage || undefined
      });
      setNewExp({ category: '', amount: '', description: '', receiptImage: null });
      if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const renderReceiptModal = () => {
    if (!viewingSale) return null;
    return (
        <motion.div 
            initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}
            className="fixed inset-0 bg-slate-950/80 backdrop-blur-sm z-[200] flex items-center justify-center p-4"
            onClick={() => setViewingSale(null)}
        >
            <motion.div 
                initial={{ scale: 0.9, y: 20 }} animate={{ scale: 1, y: 0 }}
                className="bg-white text-slate-900 w-full max-w-sm rounded-3xl overflow-hidden shadow-2xl relative"
                onClick={e => e.stopPropagation()}
            >
                 <div className="bg-slate-900 text-white p-6 text-center">
                    <h2 className="font-brand text-2xl font-bold">{settings.shopName}</h2>
                    <p className="text-xs text-slate-400 mt-1 uppercase tracking-widest">Transaction Receipt</p>
                 </div>
                 <div className="p-6 space-y-4">
                    <div className="flex justify-between text-xs border-b pb-4">
                        <div>
                            <p className="font-bold">{new Date(viewingSale.timestamp).toLocaleDateString()}</p>
                            <p className="opacity-50 font-mono">#{viewingSale.id.slice(0,8)}</p>
                        </div>
                        <div className="text-right">
                            <p className="font-bold">{viewingSale.staffName}</p>
                            <p className="opacity-50">{viewingSale.customerName}</p>
                        </div>
                    </div>
                    <div className="space-y-2 py-2 max-h-48 overflow-y-auto">
                        {viewingSale.items.map((item, idx) => (
                            <div key={idx} className="flex justify-between text-sm">
                                <span>{item.quantity}x {item.name}</span>
                                <span className="font-bold">{currency}{(item.price * item.quantity).toFixed(2)}</span>
                            </div>
                        ))}
                    </div>
                    <div className="border-t pt-4 space-y-1">
                        <div className="flex justify-between text-sm"><span>Total</span><span className="text-xl font-black">{currency}{viewingSale.total.toFixed(2)}</span></div>
                    </div>
                 </div>
            </motion.div>
        </motion.div>
    );
  };

  return (
    <div className="space-y-6 max-w-6xl mx-auto pb-24">
      <motion.div 
        animate={{ y: isTabBarVisible ? 0 : -80, opacity: isTabBarVisible ? 1 : 0 }}
        transition={{ duration: 0.25 }}
        className="flex bg-white dark:bg-slate-900 p-1.5 rounded-2xl shadow-sm border border-slate-100 dark:border-slate-800 overflow-x-auto no-scrollbar sticky top-0 z-40"
      >
        <div className="flex gap-1 min-w-max w-full">
           {currentUser.role === 'admin' && (
             <>
               <button onClick={() => setActiveTab('overview')} className={`flex-1 md:flex-none px-6 py-2.5 rounded-xl text-xs font-black uppercase tracking-widest transition-all ${activeTab === 'overview' ? 'bg-amber-500 text-slate-950' : 'text-slate-400'}`}>Overview</button>
               <button onClick={() => setActiveTab('transactions')} className={`flex-1 md:flex-none px-6 py-2.5 rounded-xl text-xs font-black uppercase tracking-widest transition-all ${activeTab === 'transactions' ? 'bg-amber-500 text-slate-950' : 'text-slate-400'}`}>Transactions</button>
             </>
           )}
           <button onClick={() => setActiveTab('expenses')} className={`flex-1 md:flex-none px-6 py-2.5 rounded-xl text-xs font-black uppercase tracking-widest transition-all ${activeTab === 'expenses' ? 'bg-amber-500 text-slate-950' : 'text-slate-400'}`}>Expenses</button>
        </div>
      </motion.div>

      <AnimatePresence mode="wait">
        {activeTab === 'overview' && (
          <motion.div key="ov" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="space-y-8">
            <div className="bg-white dark:bg-slate-900 p-6 rounded-[2rem] border dark:border-slate-800">
               <h3 className="text-xl font-bold mb-8 flex items-center gap-3">📊 {t.shopPerformance}</h3>
               <div className="h-64 w-full">
                  <ResponsiveContainer width="100%" height="100%">
                    <BarChart data={[{ name: 'Summary', rev: totalRevenue, exp: totalExpenses }]}>
                      <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" className="dark:opacity-5" />
                      <XAxis dataKey="name" axisLine={false} tickLine={false} />
                      <YAxis axisLine={false} tickLine={false} />
                      <Tooltip contentStyle={{ borderRadius: '12px', border: 'none' }} />
                      <Bar dataKey="rev" name="Revenue" fill="#10b981" radius={[8, 8, 0, 0]} />
                      <Bar dataKey="exp" name="Expenses" fill="#f43f5e" radius={[8, 8, 0, 0]} />
                    </BarChart>
                  </ResponsiveContainer>
               </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
               <div className="bg-white dark:bg-slate-900 p-6 rounded-[2rem] border dark:border-slate-800">
                  <h3 className="font-bold mb-4">{t.commissionReport}</h3>
                  <div className="space-y-3">
                     {staffList.filter(s => s.role === 'employee').map(s => {
                        const sRev = sales.filter(x => x.staffId === s.id).reduce((a,b) => a+b.total, 0);
                        return (
                          <div key={s.id} className="flex justify-between items-center p-4 bg-slate-50 dark:bg-slate-800/50 rounded-2xl">
                             <span className="text-sm font-bold">{s.name}</span>
                             <span className="font-black text-emerald-600">{currency}{((sRev * s.commission) / 100).toFixed(2)}</span>
                          </div>
                        );
                     })}
                  </div>
               </div>

               <div className="bg-gradient-to-br from-indigo-600 to-violet-700 p-6 rounded-[2rem] text-white">
                  <h3 className="font-bold text-lg mb-2 flex items-center gap-2">✨ {t.smartInsights}</h3>
                  <p className="text-indigo-100 text-xs mb-6">{t.aiPrompt}</p>
                  {aiAdvice ? (
                      <div className="bg-white/10 p-4 rounded-xl text-sm max-h-48 overflow-y-auto"><ReactMarkdown>{aiAdvice}</ReactMarkdown></div>
                  ) : (
                      <button onClick={handleGenerateAdvice} disabled={generatingAdvice} className="bg-white text-indigo-600 px-6 py-2 rounded-xl font-black text-xs uppercase disabled:opacity-50">{generatingAdvice ? '...' : t.generateAdvice}</button>
                  )}
               </div>
            </div>
          </motion.div>
        )}

        {activeTab === 'transactions' && (
          <motion.div key="tr" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="bg-white dark:bg-slate-900 rounded-[2rem] border dark:border-slate-800 overflow-hidden">
             <div className="p-4 border-b dark:border-slate-800 flex justify-between items-center">
                <div className="flex items-center gap-2">
                   <input type="checkbox" onChange={toggleAll} checked={selectedTransactions.size === enrichedSales.length && enrichedSales.length > 0} className="w-5 h-5 rounded text-amber-500" />
                   <span className="text-xs font-bold">{selectedTransactions.size} Selected</span>
                </div>
                {selectedTransactions.size > 0 && <button onClick={handleDeleteSelected} className="text-rose-500 text-xs font-black uppercase">Delete Selected</button>}
             </div>
             <div className="overflow-x-auto">
                <table className="w-full text-left">
                   <thead className="bg-slate-50 dark:bg-slate-800/50 text-[10px] font-black uppercase text-slate-400">
                      <tr><th className="p-4 w-10"></th><th className="p-4">Time</th><th className="p-4">Details</th><th className="p-4">Total</th><th className="p-4">Action</th></tr>
                   </thead>
                   <tbody className="divide-y dark:divide-slate-800">
                      {enrichedSales.slice().reverse().map(sale => (
                          <tr key={sale.id} className="hover:bg-slate-50/50 dark:hover:bg-slate-800/30">
                             <td className="p-4"><input type="checkbox" checked={selectedTransactions.has(sale.id)} onChange={() => toggleSelection(sale.id)} className="w-5 h-5 rounded text-amber-500" /></td>
                             <td className="p-4 text-xs font-bold">{new Date(sale.timestamp).toLocaleDateString()}</td>
                             <td className="p-4"><p className="text-sm font-bold">{sale.staffName}</p><p className="text-xs text-slate-400">{sale.customerName}</p></td>
                             <td className="p-4 font-black">{currency}{sale.total.toFixed(2)}</td>
                             <td className="p-4"><button onClick={() => setViewingSale(sale)} className="text-amber-500 font-bold text-xs">View</button></td>
                          </tr>
                      ))}
                   </tbody>
                </table>
             </div>
          </motion.div>
        )}

        {activeTab === 'expenses' && (
          <motion.div key="ex" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="space-y-6">
             <div className="bg-white dark:bg-slate-900 p-6 rounded-[2rem] border dark:border-slate-800">
                <form onSubmit={handleAddExpenseSubmit} className="space-y-4">
                   <div className="grid grid-cols-2 gap-4">
                      <input type="text" placeholder={t.category} value={newExp.category} onChange={e => setNewExp({...newExp, category: e.target.value})} className="bg-slate-50 dark:bg-slate-800 rounded-xl px-4 py-3 text-sm" required />
                      <input type="number" placeholder={t.amount} value={newExp.amount} onChange={e => setNewExp({...newExp, amount: e.target.value})} className="bg-slate-50 dark:bg-slate-800 rounded-xl px-4 py-3 text-sm" required />
                   </div>
                   <input type="text" placeholder={t.description} value={newExp.description} onChange={e => setNewExp({...newExp, description: e.target.value})} className="w-full bg-slate-50 dark:bg-slate-800 rounded-xl px-4 py-3 text-sm" />
                   <div className="flex gap-4">
                      <label className="flex-1 cursor-pointer bg-slate-50 dark:bg-slate-800 border-2 border-dashed rounded-xl p-3 text-center text-slate-400 text-xs font-bold">
                          {newExp.receiptImage ? '✅ Attached' : '📸 Image'}
                          <input type="file" accept="image/*" ref={fileInputRef} onChange={handleImageUpload} className="hidden" />
                      </label>
                      <button type="submit" className="flex-1 bg-amber-500 text-slate-950 py-3 rounded-xl font-black uppercase text-xs">Save</button>
                   </div>
                </form>
             </div>
             <div className="space-y-3">
                {expenses.slice().reverse().map(exp => (
                   <div key={exp.id} className="bg-white dark:bg-slate-900 p-4 rounded-2xl border dark:border-slate-800 flex justify-between items-center">
                      <div className="flex items-center gap-4">
                         <div className="w-10 h-10 rounded-lg bg-slate-100 dark:bg-slate-800 flex items-center justify-center">🧾</div>
                         <div><p className="font-bold">{exp.category}</p><p className="text-[10px] opacity-50">{exp.date}</p></div>
                      </div>
                      <div className="text-right">
                         <p className="font-black text-rose-500">{currency}{exp.amount.toFixed(2)}</p>
                         <button onClick={() => onDeleteExpense(exp.id)} className="text-[10px] text-slate-400">Delete</button>
                      </div>
                   </div>
                ))}
             </div>
          </motion.div>
        )}
      </AnimatePresence>
      <AnimatePresence>{viewingSale && renderReceiptModal()}</AnimatePresence>
    </div>
  );
};

export default Finance;

import React, { useState, useEffect } from 'react';
import Sidebar from './components/Sidebar';
import Dashboard from './components/Dashboard';
import POS from './components/POS';
import Finance from './components/Finance';
import Customers from './components/Customers';
import Settings from './components/Settings';
import Inventory from './components/Inventory';
import StaffManagement from './components/StaffManagement';
import Login from './components/Login';
import InstallBanner from './components/InstallBanner';
import { View, Sale, Expense, Service, Product, Staff, Customer, ShopSettings, Language } from './types';
import { INITIAL_SERVICES, INITIAL_PRODUCTS, INITIAL_STAFF, INITIAL_EXPENSES, INITIAL_CUSTOMERS, DEFAULT_SETTINGS } from './constants';
import { motion, AnimatePresence } from 'framer-motion';
import { supabase } from './supabaseClient';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<Staff | null>(() => {
    const saved = localStorage.getItem('trimtime_session');
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        if (parsed.user && parsed.expiry && Date.now() < parsed.expiry) return parsed.user;
      } catch (e) {}
    }
    return null;
  });

  const [currentView, setCurrentView] = useState<View>(
    currentUser?.role === 'employee' ? View.POS : View.DASHBOARD
  );

  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [loading, setLoading] = useState(true);
  const [services, setServices] = useState<Service[]>([]);
  const [products, setProducts] = useState<Product[]>([]);
  const [staff, setStaff] = useState<Staff[]>([]);
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [sales, setSales] = useState<Sale[]>([]);
  const [settings, setSettings] = useState<ShopSettings>(DEFAULT_SETTINGS);
  const [sessionLanguage, setSessionLanguage] = useState<Language>(() => (localStorage.getItem('trimtime_lang') as Language) || 'en');
  const [isDarkMode, setIsDarkMode] = useState(() => localStorage.getItem('trimtime_theme') === 'dark');

  // PWA Install States
  const [deferredPrompt, setDeferredPrompt] = useState<any>(null);

  useEffect(() => {
    const handleBeforeInstallPrompt = (e: Event) => {
      e.preventDefault();
      setDeferredPrompt(e);
    };
    window.addEventListener('beforeinstallprompt', handleBeforeInstallPrompt);
    return () => window.removeEventListener('beforeinstallprompt', handleBeforeInstallPrompt);
  }, []);

  useEffect(() => {
    const fetchData = async () => {
      try {
        const [sv, pr, st, ex, cu, sa, se] = await Promise.all([
          supabase.from('services').select('*'),
          supabase.from('products').select('*'),
          supabase.from('staff').select('*'),
          supabase.from('expenses').select('*'),
          supabase.from('customers').select('*'),
          supabase.from('sales').select('*'),
          supabase.from('settings').select('*').single()
        ]);

        if (sv.data && sv.data.length > 0) setServices(sv.data);
        else if (sv.error) setServices(INITIAL_SERVICES); 
        else setServices([]); // Empty DB = Empty List

        if (pr.data && pr.data.length > 0) setProducts(pr.data.map((p: any) => ({ ...p, lowStockThreshold: p.low_stock_threshold })));
        else if (pr.error) setProducts(INITIAL_PRODUCTS);
        else setProducts([]);

        if (st.data && st.data.length > 0) setStaff(st.data);
        else if (st.error) setStaff(INITIAL_STAFF);
        // Note: For staff, we might want to keep at least one admin if empty, but assuming DB handles it.
        else if (st.data && st.data.length === 0) setStaff(INITIAL_STAFF); // Fallback for staff to ensure login

        if (ex.data && ex.data.length > 0) setExpenses(ex.data.map((e: any) => ({ ...e, receiptImage: e.receipt_image })));
        else if (ex.error) setExpenses(INITIAL_EXPENSES);
        else setExpenses([]); // Don't show demo expenses if DB is connected but empty

        if (cu.data && cu.data.length > 0) setCustomers(cu.data.map((c: any) => ({ ...c, createdAt: c.created_at })));
        else if (cu.error) setCustomers(INITIAL_CUSTOMERS);
        else setCustomers([]);

        if (sa.data) {
          setSales(sa.data.map((s: any) => ({ 
            ...s, 
            items: typeof s.items === 'string' ? JSON.parse(s.items) : s.items,
            staffName: s.professional_name,
            customerName: s.customer_name
          })));
        }

        if (se.data?.data) setSettings({ ...DEFAULT_SETTINGS, ...se.data.data });

        if (sv.error) console.error("Services Fetch Error:", sv.error);
        if (pr.error) console.error("Products Fetch Error:", pr.error);
      } catch (e) { console.error("Error loading data:", e); }
      finally { setLoading(false); }
    };
    fetchData();
  }, []);

  useEffect(() => {
    document.documentElement.classList.toggle('dark', isDarkMode);
    localStorage.setItem('trimtime_theme', isDarkMode ? 'dark' : 'light');
  }, [isDarkMode]);

  useEffect(() => {
    document.documentElement.lang = sessionLanguage;
    document.dir = ['ur', 'fa'].includes(sessionLanguage) ? 'rtl' : 'ltr';
    localStorage.setItem('trimtime_lang', sessionLanguage);
  }, [sessionLanguage]);

  // --- DATA PERSISTENCE HANDLERS ---

  const handleUpdateServices = async (updated: Service[]) => {
    // Fixed: Explicitly type Sets to string to avoid 'unknown' inference when spreading/converting
    const currentIds = new Set<string>(services.map(i => i.id));
    const newIds = new Set<string>(updated.map(i => i.id));
    const toDelete: string[] = Array.from(currentIds).filter(id => !newIds.has(id));

    setServices(updated);

    try {
      if (toDelete.length) await supabase.from('services').delete().in('id', toDelete);
      if (updated.length) {
          const { error } = await supabase.from('services').upsert(updated);
          if (error) throw error;
      }
    } catch (error) { 
        const err = error as any;
        console.error("DB Sync Error (Services):", err);
        alert("Failed to save services. Check database connection.");
    }
  };

  const handleUpdateProducts = async (updated: Product[]) => {
    // Fixed: Explicitly type Sets to string to avoid 'unknown' inference when spreading/converting
    const currentIds = new Set<string>(products.map(i => i.id));
    const newIds = new Set<string>(updated.map(i => i.id));
    const toDelete: string[] = Array.from(currentIds).filter(id => !newIds.has(id));

    setProducts(updated);

    const dbRowsFull = updated.map(p => ({
        id: p.id,
        name: p.name,
        price: p.price,
        cost: p.cost,
        stock: p.stock,
        barcode: p.barcode || null,
        low_stock_threshold: p.lowStockThreshold || 15
    }));

    const dbRowsSafe = updated.map(p => ({
        id: p.id,
        name: p.name,
        price: p.price,
        cost: p.cost,
        stock: p.stock
    }));

    try {
      if (toDelete.length) await supabase.from('products').delete().in('id', toDelete);

      if (dbRowsFull.length) {
          const { error } = await supabase.from('products').upsert(dbRowsFull);
          if (error) {
            if (error.code === 'PGRST204' || error.message.includes('column')) {
                console.warn("DB Schema mismatch detected. Retrying with core fields only...");
                const { error: retryError } = await supabase.from('products').upsert(dbRowsSafe);
                if (retryError) throw retryError;
            } else {
                throw error;
            }
          }
      }
    } catch (error) { 
        const err = error as any;
        console.error("DB Sync Error (Products):", err); 
        alert(`Failed to save products: ${err.message}`);
    }
  };

  const handleUpdateStaff = async (updated: Staff[]) => {
    // Fixed: Explicitly type Sets to string to avoid 'unknown' inference when spreading/converting
    const currentIds = new Set<string>(staff.map(i => i.id));
    const newIds = new Set<string>(updated.map(i => i.id));
    const toDelete: string[] = Array.from(currentIds).filter(id => !newIds.has(id));

    setStaff(updated);

    try {
      if (toDelete.length) await supabase.from('staff').delete().in('id', toDelete);
      if (updated.length) {
          const { error } = await supabase.from('staff').upsert(updated);
          if (error) throw error;
      }
    } catch (error) { 
        const err = error as any;
        console.error("DB Sync Error (Staff):", err);
        alert("Failed to save staff. Check database connection.");
    }
  };

  const handleUpdateCustomers = async (updated: Customer[]) => {
    // Fixed: Explicitly type Sets to string to avoid 'unknown' inference when spreading/converting
    const currentIds = new Set<string>(customers.map(i => i.id));
    const newIds = new Set<string>(updated.map(i => i.id));
    const toDelete: string[] = Array.from(currentIds).filter(id => !newIds.has(id));

    setCustomers(updated);

    const dbRows = updated.map(c => ({
        id: c.id,
        name: c.name,
        phone: c.phone,
        email: c.email,
        notes: c.notes,
        created_at: c.createdAt
    }));

    try {
      if (toDelete.length) await supabase.from('customers').delete().in('id', toDelete);
      if (dbRows.length) {
          const { error } = await supabase.from('customers').upsert(dbRows);
          if (error) throw error;
      }
    } catch (error) { 
        const err = error as any;
        console.error("DB Sync Error (Customers):", err);
        alert("Failed to save customers. Check database connection.");
    }
  };

  const handleUpdateSettings = async (updated: ShopSettings) => {
    setSettings(updated);
    try {
      const { error } = await supabase.from('settings').upsert({ id: 1, data: updated });
      if (error) throw error;
    } catch (error) { 
        const err = error as any;
        console.error("DB Sync Error (Settings):", err);
        alert("Failed to save settings.");
    }
  };

  const handleCompleteSale = async (sale: Sale) => {
    setSales(prev => [...prev, sale]);
    try {
      const dbSale = {
          id: sale.id,
          timestamp: sale.timestamp,
          items: sale.items, 
          staff_id: sale.staffId,
          customer_id: sale.customerId,
          total: sale.total,
          tax: sale.tax,
          discount: sale.discount,
          discount_code: sale.discountCode,
          payment_method: sale.paymentMethod,
          tax_type: sale.taxType,
          customer_name: sale.customerName,
          professional_name: sale.staffName
      };
      const { error } = await supabase.from('sales').insert(dbSale);
      if (error) throw error;

      let productsUpdated = false;
      const newProducts = [...products];
      sale.items.forEach(item => {
          if (item.type === 'product') {
              const idx = newProducts.findIndex(p => p.id === item.id);
              if (idx > -1) {
                  newProducts[idx] = { ...newProducts[idx], stock: newProducts[idx].stock - item.quantity };
                  productsUpdated = true;
              }
          }
      });
      if (productsUpdated) handleUpdateProducts(newProducts);
    } catch (error) { 
        const err = error as any;
        console.error("DB Sync Error (Sale):", err);
        alert("Sale saved locally but failed to sync to DB.");
    }
  };

  const handleDeleteSales = async (ids: string[]) => {
    setSales(prev => prev.filter(s => !ids.includes(s.id)));
    try {
      const { error } = await supabase.from('sales').delete().in('id', ids);
      if (error) throw error;
    } catch (error) {
       const err = error as any;
       console.error("DB Sync Error (Delete Sales):", err);
       alert("Failed to delete sales from DB.");
    }
  };

  const handleAddExpense = async (expense: Expense) => {
      setExpenses(prev => [...prev, expense]);
      const dbExpense = {
          id: expense.id,
          date: expense.date,
          category: expense.category,
          amount: expense.amount,
          description: expense.description || '', // Ensure fallback
          receipt_image: expense.receiptImage || null // Ensure null if undefined
      };
      try {
        const { error } = await supabase.from('expenses').insert(dbExpense);
        if (error) throw error;
      } catch (error) { 
          const err = error as any;
          console.error("DB Sync Error (Expense):", err);
          alert("Failed to save expense to DB: " + err.message);
      }
  };

  const handleDeleteExpense = async (id: string) => {
      setExpenses(prev => prev.filter(e => e.id !== id));
      try {
        const { error } = await supabase.from('expenses').delete().eq('id', id);
        if (error) throw error;
      } catch (error) { 
          const err = error as any;
          console.error("DB Sync Error (Delete Expense):", err);
          alert("Failed to delete expense from DB: " + err.message);
      }
  };

  const handlePurgeSales = async () => {
    setSales([]);
    try {
       const { error } = await supabase.from('sales').delete().neq('id', '0'); 
       if (error) throw error;
    } catch (error) { 
        const err = error as any;
        console.error("DB Sync Error (Purge Sales):", err);
        alert("Failed to purge sales from DB.");
    }
  };

  const handleLogin = (user: Staff, remember: boolean) => {
    const expiry = Date.now() + (remember ? 30 : 1) * 24 * 60 * 60 * 1000;
    localStorage.setItem('trimtime_session', JSON.stringify({ user, expiry }));
    setCurrentUser(user);
    setCurrentView(user.role === 'employee' ? View.POS : View.DASHBOARD);
  };

  const handleLogout = () => {
    localStorage.removeItem('trimtime_session');
    setCurrentUser(null);
  };

  if (loading) return <div className="h-screen w-full flex items-center justify-center bg-slate-950"><div className="animate-spin rounded-full h-12 w-12 border-t-2 border-amber-500"></div></div>;
  if (!currentUser) return <Login onLogin={handleLogin} staffList={staff} shopName={settings.shopName} />;

  return (
    <div className="flex h-screen bg-slate-50 dark:bg-slate-950 overflow-hidden font-sans transition-colors duration-300">
      <Sidebar 
        currentView={currentView} onViewChange={setCurrentView} 
        shopName={settings.shopName} userRole={currentUser.role} 
        isOpen={isSidebarOpen} onClose={() => setIsSidebarOpen(false)}
        language={sessionLanguage} onLanguageChange={setSessionLanguage}
      />

      <div className="flex-1 flex flex-col min-w-0 md:pl-64 overflow-hidden relative">
        {/* Responsive Header */}
        <header className="flex md:hidden items-center justify-between p-4 bg-white dark:bg-slate-900 border-b border-slate-100 dark:border-slate-800 z-50 sticky top-0 shadow-sm">
          <div className="flex items-center gap-2">
             <div className="w-8 h-8 bg-amber-500 rounded-lg flex items-center justify-center font-brand text-lg text-slate-950">{settings.shopName.charAt(0)}</div>
             <span className="font-bold text-slate-900 dark:text-white truncate max-w-[120px]">{settings.shopName}</span>
          </div>
          <div className="flex gap-2">
            <button onClick={() => setIsDarkMode(!isDarkMode)} className="p-2 text-slate-400 bg-slate-50 dark:bg-slate-800 rounded-lg">
              {isDarkMode ? '🌞' : '🌙'}
            </button>
            <button onClick={() => setIsSidebarOpen(true)} className="p-2 text-slate-900 dark:text-white bg-amber-500 rounded-lg">
              <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M4 6h16M4 12h16m-7 6h7"/></svg>
            </button>
          </div>
        </header>

        {/* Desktop Header */}
        <header className="hidden md:flex justify-between items-center px-8 py-6 no-print">
            <h1 className="text-2xl font-black text-slate-900 dark:text-white font-brand">{tView(currentView, sessionLanguage)}</h1>
            <div className="flex items-center gap-4">
               <button onClick={() => setIsDarkMode(!isDarkMode)} className="p-2.5 bg-white dark:bg-slate-900 text-slate-400 rounded-xl border border-slate-200 dark:border-slate-800">
                 {isDarkMode ? '🌞' : '🌙'}
               </button>
               <div className="flex items-center gap-3 bg-white dark:bg-slate-900 p-1.5 pr-4 rounded-full border border-slate-100 dark:border-slate-800 shadow-sm">
                  <div className="w-8 h-8 rounded-full bg-amber-500 flex items-center justify-center font-black text-slate-950 text-xs">{currentUser.name.charAt(0)}</div>
                  <div className="flex flex-col"><span className="text-xs font-bold dark:text-white">{currentUser.name}</span><span className="text-[9px] uppercase font-black text-slate-400">{currentUser.role}</span></div>
               </div>
               <button onClick={handleLogout} className="p-2.5 bg-slate-100 dark:bg-slate-800 text-slate-500 rounded-xl">🚪</button>
            </div>
        </header>

        <main className="flex-1 overflow-y-auto p-4 md:p-8 relative scrollbar-hide">
          <AnimatePresence mode='wait'>
            <motion.div key={currentView} initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: -10 }} className="h-full">
              {renderView(currentView, { 
                sales, expenses, products, services, staff, customers, settings, 
                currentUser, sessionLanguage, isDarkMode, 
                // DB Handlers passed to children
                onUpdateServices: handleUpdateServices,
                onUpdateProducts: handleUpdateProducts,
                onUpdateStaff: handleUpdateStaff,
                onUpdateCustomers: handleUpdateCustomers,
                onUpdateSettings: handleUpdateSettings,
                onCompleteSale: handleCompleteSale,
                onAddExpense: handleAddExpense,
                onDeleteExpense: handleDeleteExpense,
                onLogout: handleLogout,
                onPurgeSales: handlePurgeSales,
                onDeleteSales: handleDeleteSales,

                setCurrentView, handleLogout
              })}
            </motion.div>
          </AnimatePresence>
        </main>
      </div>

      <InstallBanner 
        deferredPrompt={deferredPrompt} 
        onClose={() => setDeferredPrompt(null)} 
      />
    </div>
  );
};

const tView = (v: View, l: Language) => {
  const map: any = { 
    en: { [View.DASHBOARD]: 'Dashboard', [View.POS]: 'Terminal', [View.FINANCE]: 'Finances', [View.INVENTORY]: 'Catalog', [View.STAFF]: 'Staff', [View.CUSTOMERS]: 'Clients', [View.SETTINGS]: 'Settings' },
    ur: { [View.DASHBOARD]: 'ڈیش بورڈ', [View.POS]: 'ٹرمینل', [View.FINANCE]: 'مالیات', [View.INVENTORY]: 'کیٹلاگ', [View.STAFF]: 'عملہ', [View.CUSTOMERS]: 'صارفین', [View.SETTINGS]: 'ترتیبات' }
  };
  return map[l]?.[v] || map['en'][v];
};

const renderView = (v: View, props: any) => {
  const { sales, expenses, products, services, staff, customers, settings, currentUser, sessionLanguage, onUpdateServices, onUpdateProducts, onUpdateStaff, onUpdateCustomers, onUpdateSettings, onCompleteSale, onAddExpense, onDeleteExpense, onLogout, onPurgeSales, onDeleteSales, setCurrentView } = props;
  switch (v) {
    case View.DASHBOARD: return <Dashboard sales={sales} expenses={expenses} products={products} currency={settings.currency} language={sessionLanguage} onNavigate={setCurrentView} />;
    case View.POS: return <POS services={services} products={products} staff={staff} customers={customers} settings={settings} currentUser={currentUser} onCompleteSale={onCompleteSale} onAddCustomer={c => onUpdateCustomers([...customers, c])} />;
    case View.FINANCE: return <Finance sales={sales} expenses={expenses} staffList={staff} customers={customers} currency={settings.currency} language={sessionLanguage} currentUser={currentUser} onAddExpense={onAddExpense} onDeleteExpense={onDeleteExpense} onDeleteSales={onDeleteSales} settings={settings} />;
    case View.CUSTOMERS: return <Customers customers={customers} sales={sales} onUpdateCustomers={onUpdateCustomers} currency={settings.currency} language={sessionLanguage} />;
    case View.INVENTORY: return <Inventory services={services} products={products} settings={{...settings, language: sessionLanguage}} onUpdateServices={onUpdateServices} onUpdateProducts={onUpdateProducts} />;
    case View.STAFF: return <StaffManagement staffList={staff} onUpdateStaff={onUpdateStaff} currentUser={currentUser} language={sessionLanguage} />;
    case View.SETTINGS: return <Settings settings={{...settings, language: sessionLanguage}} onUpdateSettings={onUpdateSettings} currentUser={currentUser} onLogout={onLogout} onPurgeSales={onPurgeSales} />;
    default: return null;
  }
};

export default App;

import React, { useState, useMemo, useEffect, useRef } from 'react';
import { Service, Product, Staff, Sale, SaleItem, Customer, ShopSettings, HeldSale } from '../types';
import { TRANSLATIONS } from '../constants';
import { jsPDF } from 'jspdf';
import { motion, AnimatePresence } from 'framer-motion';
import { Html5Qrcode } from 'html5-qrcode';

interface POSProps {
  services: Service[];
  products: Product[];
  staff: Staff[];
  customers: Customer[];
  settings: ShopSettings;
  currentUser: Staff;
  onCompleteSale: (sale: Sale) => void;
  onAddCustomer: (customer: Customer) => void;
}

const POS: React.FC<POSProps> = ({ services, products, staff, customers, settings, currentUser, onCompleteSale, onAddCustomer }) => {
  const [cart, setCart] = useState<SaleItem[]>([]);
  const [selectedStaff, setSelectedStaff] = useState<string>(currentUser.role === 'employee' ? currentUser.id : '');
  const [selectedCustomer, setSelectedCustomer] = useState<string>('');
  const [discountCode, setDiscountCode] = useState<string>('');
  const [activeTab, setActiveTab] = useState<'services' | 'products'>('services');
  const [searchTerm, setSearchTerm] = useState('');
  const [heldSales, setHeldSales] = useState<HeldSale[]>([]);
  const [lastSale, setLastSale] = useState<Sale | null>(null);
  const [autoWhatsapp, setAutoWhatsapp] = useState(false);

  const [scanningFeedback, setScanningFeedback] = useState<string | null>(null);
  const [feedbackType, setFeedbackType] = useState<'success' | 'error'>('success');

  const [showMobileCart, setShowMobileCart] = useState(false);
  const [isAddingCustomer, setIsAddingCustomer] = useState(false);
  const [newCustomerData, setNewCustomerData] = useState({ name: '', phone: '', email: '' });
  const [isScanning, setIsScanning] = useState(false);

  const feedbackTimeoutRef = useRef<number | null>(null);
  const html5QrCodeRef = useRef<Html5Qrcode | null>(null);
  const isScannerActiveRef = useRef(false);
  const processingScanRef = useRef(false);

  const t = TRANSLATIONS[settings.language];

  const activeCustomer = useMemo(() => customers.find(c => c.id === selectedCustomer), [selectedCustomer, customers]);
  const lastCustomer = useMemo(() => lastSale?.customerId ? customers.find(c => c.id === lastSale.customerId) : null, [lastSale, customers]);

  const sendWhatsappReceipt = (sale: Sale, customer: Customer) => {
    if (!customer.phone) return;
    const itemsList = sale.items.map(i => `• *${i.name}* (${settings.currency}${i.price} x ${i.quantity})`).join('\n');
    const message = `✨ *${settings.shopName} Receipt* ✨\n\n` +
      `👤 *Customer:* ${customer.name}\n` +
      `📅 *Date:* ${new Date(sale.timestamp).toLocaleDateString()}\n` +
      `🧾 *ID:* #${sale.id.slice(0, 8)}\n` +
      `--------------------------\n` +
      `${itemsList}\n` +
      `--------------------------\n` +
      `💰 *Total:* ${settings.currency}${sale.total.toFixed(2)}\n` +
      `💳 *Method:* ${sale.paymentMethod.toUpperCase()}\n\n` +
      `${settings.receiptFooter}\n\n` +
      `_Thank you for your visit!_`;
    const cleanPhone = customer.phone.replace(/\D/g, '');
    window.open(`https://wa.me/${cleanPhone}?text=${encodeURIComponent(message)}`, '_blank');
  };

  useEffect(() => {
    let isMounted = true;
    if (isScanning) {
        const startScanner = async () => {
            // Give DOM time to settle
            await new Promise(resolve => setTimeout(resolve, 500));
            if (!isMounted || !isScanning) return;

            try {
                if (!html5QrCodeRef.current) {
                  html5QrCodeRef.current = new Html5Qrcode("reader");
                }

                await html5QrCodeRef.current.start(
                    { facingMode: "environment" }, 
                    { 
                        fps: 15, 
                        // Barcode-optimized box (wide rectangle)
                        qrbox: (viewfinderWidth, viewfinderHeight) => {
                            const width = Math.floor(viewfinderWidth * 0.8);
                            const height = Math.floor(viewfinderHeight * 0.4);
                            return { width, height };
                        },
                        experimentalFeatures: {
                            useBarCodeDetectorIfSupported: true
                        }
                    }, 
                    (decodedText) => { if (isMounted) handleScan(decodedText); },
                    () => {} // Quiet logs
                );
                if (isMounted) isScannerActiveRef.current = true;
            } catch (err: any) {
                console.error("Scanner failed", err);
                if (isMounted) {
                  setScanningFeedback("Camera Error");
                  setFeedbackType("error");
                  setTimeout(() => setIsScanning(false), 2000);
                }
            }
        };
        startScanner();
    }
    return () => {
        isMounted = false;
        if (html5QrCodeRef.current) {
            const scanner = html5QrCodeRef.current;
            if (isScannerActiveRef.current) {
                scanner.stop().catch(() => {}).finally(() => {
                    try { scanner.clear(); } catch(e) {}
                    isScannerActiveRef.current = false;
                });
            } else {
                try { scanner.clear(); } catch(e) {}
            }
        }
    };
  }, [isScanning]);

  const handleScan = (barcode: string) => {
    if (processingScanRef.current) return;
    processingScanRef.current = true;
    setTimeout(() => { processingScanRef.current = false; }, 2000);

    const product = products.find(p => p.barcode === barcode);
    if (product) {
        addToCart(product, 'product');
        setScanningFeedback(product.name);
        setFeedbackType('success');
    } else {
        setScanningFeedback(`Unknown Barcode: ${barcode}`);
        setFeedbackType('error');
    }

    if (feedbackTimeoutRef.current) window.clearTimeout(feedbackTimeoutRef.current);
    feedbackTimeoutRef.current = window.setTimeout(() => { setScanningFeedback(null); }, 2000);
  };

  const toggleScanner = () => setIsScanning(!isScanning);

  const addToCart = (item: Service | Product, type: 'service' | 'product') => {
    setCart(prev => {
      const existing = prev.find(i => i.id === item.id && i.type === type);
      if (existing) {
        return prev.map(i => i.id === item.id && i.type === type ? { ...i, quantity: i.quantity + 1 } : i);
      }
      return [...prev, { id: item.id, name: item.name, price: item.price, type, quantity: 1 }];
    });
  };

  const updateQuantity = (id: string, type: 'service' | 'product', delta: number) => {
    setCart(prev => prev.map(item => {
      if (item.id === id && item.type === type) return { ...item, quantity: Math.max(1, item.quantity + delta) };
      return item;
    }));
  };

  const removeFromCart = (id: string, type: 'service' | 'product') => {
    setCart(prev => prev.filter(i => !(i.id === id && i.type === type)));
  };

  const totals = useMemo(() => {
    const rawSubtotal = cart.reduce((acc, item) => acc + (item.price * item.quantity), 0);
    let discount = 0;
    const code = (settings.promoCodes || []).find(c => c.code === discountCode);
    if (code) discount = code.type === 'percentage' ? (rawSubtotal * code.value) / 100 : code.value;
    const discountedAmount = rawSubtotal - discount;
    let tax = 0;
    let total = 0;
    if (settings.taxType === 'included') {
      total = discountedAmount;
      tax = total - (total / (1 + (settings.taxRate / 100)));
    } else {
      tax = discountedAmount * (settings.taxRate / 100);
      total = discountedAmount + tax;
    }
    return { subtotal: rawSubtotal, discount, tax, total };
  }, [cart, discountCode, settings]);

  const handleHoldSale = () => {
    if (cart.length === 0) return;
    const newHold: HeldSale = {
      id: Math.random().toString(36).substr(2, 9).toUpperCase(),
      timestamp: new Date().toISOString(),
      cart: [...cart],
      customerId: selectedCustomer || undefined,
      staffId: selectedStaff || undefined,
    };
    setHeldSales([newHold, ...heldSales]);
    setCart([]);
    setSelectedCustomer('');
    if (currentUser.role !== 'employee') setSelectedStaff('');
  };

  const retrieveSale = (held: HeldSale) => {
    setCart(held.cart);
    if (held.customerId) setSelectedCustomer(held.customerId);
    if (held.staffId) setSelectedStaff(held.staffId);
    setHeldSales(heldSales.filter(h => h.id !== held.id));
  };

  const handleShareReceipt = async (sale: Sale) => {
    const { jsPDF } = await import('jspdf');
    const doc = new jsPDF({ unit: 'mm', format: [80, 200] });
    const barber = sale.staffName || staff.find(s => s.id === sale.staffId)?.name || 'N/A';
    const client = sale.customerName || customers.find(c => c.id === sale.customerId)?.name || 'Guest Walk-in';
    doc.setFontSize(14).text(settings.shopName, 40, 15, { align: 'center' });
    doc.setFontSize(8).text(`Date: ${new Date(sale.timestamp).toLocaleString()}`, 10, 25);
    doc.text(`Staff: ${barber}`, 10, 30);
    doc.text(`Client: ${client}`, 10, 35);
    let y = 45;
    sale.items.forEach(item => {
      doc.text(`${item.quantity}x ${item.name}`, 10, y);
      doc.text(`${settings.currency}${(item.price * item.quantity).toFixed(2)}`, 70, y, { align: 'right' });
      y += 5;
    });
    doc.text(`Total: ${settings.currency}${sale.total.toFixed(2)}`, 70, y + 5, { align: 'right' });
    doc.save(`Receipt-${sale.id}.pdf`);
  };

  const handleCheckout = (paymentMethod: 'cash' | 'card') => {
    if (cart.length === 0 || !selectedStaff) {
      alert('Please add items and assign a professional.');
      return;
    }
    const staffMember = staff.find(s => s.id === selectedStaff);
    const customerMember = customers.find(c => c.id === selectedCustomer);
    const sale: Sale = {
      id: Math.random().toString(36).substr(2, 9).toUpperCase(),
      timestamp: new Date().toISOString(),
      items: [...cart],
      staffId: selectedStaff,
      customerId: selectedCustomer || undefined,
      total: totals.total,
      tax: totals.tax,
      discount: totals.discount,
      discountCode: discountCode || undefined,
      paymentMethod,
      taxType: settings.taxType,
      staffName: staffMember?.name || 'Unknown',
      customerName: customerMember?.name || (selectedCustomer ? 'Unknown' : undefined)
    };
    onCompleteSale(sale);
    setLastSale(sale);
    if (autoWhatsapp && selectedCustomer) {
      const cust = customers.find(c => c.id === selectedCustomer);
      if (cust && cust.phone) setTimeout(() => sendWhatsappReceipt(sale, cust), 1200);
    }
    setCart([]);
    setSelectedCustomer('');
    setDiscountCode('');
    if (currentUser.role !== 'employee') setSelectedStaff('');
    setShowMobileCart(false);
  };

  const filteredItems = useMemo(() => {
    const search = searchTerm.toLowerCase();
    if (activeTab === 'services') return services.filter(s => s.name.toLowerCase().includes(search) || s.category.toLowerCase().includes(search));
    return products.filter(p => p.name.toLowerCase().includes(search));
  }, [activeTab, services, products, searchTerm]);

  return (
    <div className="flex flex-col lg:flex-row gap-6 h-full relative">
      <AnimatePresence>
        {lastSale && (
          <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="fixed inset-0 bg-slate-950/80 backdrop-blur-xl z-[150] flex items-center justify-center p-6 no-print">
            <motion.div initial={{ scale: 0.8, opacity: 0, y: 20 }} animate={{ scale: 1, opacity: 1, y: 0 }} className="bg-white dark:bg-slate-900 rounded-[2.5rem] p-8 md:p-10 max-w-md w-full shadow-2xl text-center space-y-8">
              <div className="w-16 h-16 md:w-20 md:h-20 bg-emerald-50 dark:bg-emerald-900/20 text-emerald-500 rounded-full flex items-center justify-center text-3xl md:text-4xl mx-auto shadow-inner">✓</div>
              <div className="space-y-2">
                <h3 className="text-2xl md:text-3xl font-black text-slate-900 dark:text-white tracking-tight">{t.saleSuccess}</h3>
                <p className="text-slate-400 dark:text-slate-500 font-medium">{t.orderCompleted}</p>
              </div>
              <div className="flex flex-col gap-3">
                {lastCustomer && lastCustomer.phone && (
                  <button onClick={() => sendWhatsappReceipt(lastSale, lastCustomer)} className="w-full bg-emerald-500 text-white py-4 rounded-2xl font-black flex items-center justify-center gap-3 hover:bg-emerald-600 transition-all shadow-xl shadow-emerald-500/20 active:scale-95 text-sm md:text-base">
                    <svg className="w-5 h-5" fill="currentColor" viewBox="0 0 24 24"><path d="M.057 24l1.687-6.163c-1.041-1.804-1.588-3.849-1.587-5.946.003-6.556 5.338-11.891 11.893-11.891 3.181.001 6.167 1.24 8.413 3.488 2.246 2.248 3.484 5.232 3.484 8.412-.003 6.557-5.338 11.892-11.893 11.892-1.997-.001-3.951-.5-5.688-1.448l-6.309 1.656zm6.224-3.52c1.54.914 3.453 1.403 5.385 1.404h.005c5.632 0 10.211-4.579 10.214-10.211 0-2.729-1.063-5.295-2.993-7.225s-4.496-2.992-7.225-2.993c-5.633 0-10.213 4.58-10.214 10.214 0 2.022.529 3.996 1.531 5.74l-.991 3.618 3.707-.972zm11.233-5.62c-.301-.151-1.782-.879-2.057-.979-.275-.1-.475-.151-.675.151s-.777.979-.952 1.179-.35.225-.65.076c-.301-.151-1.268-.467-2.417-1.492-.892-.795-1.494-1.777-1.669-2.078-.175-.301-.019-.463.131-.613.135-.134.301-.351.451-.526s.201-.3.301-.5.101-.201.05-.376-.025-.526s-.675-1.629-.925-2.229c-.244-.583-.491-.504-.675-.513-.175-.008-.376-.01-.576-.01s-.526.076-.801.376c-.275.301-1.051 1.028-1.051 2.508s1.076 2.908 1.226 3.109c.151.201 2.118 3.235 5.132 4.537.717.309 1.277.494 1.714.633.72.228 1.375.196 1.892.119.577-.085 1.782-.728 2.032-1.429s.25-.151.25-.376-.101-.351-.401-.502z"/></svg>
                    WhatsApp Receipt
                  </button>
                )}
                <button onClick={() => handleShareReceipt(lastSale)} className="w-full bg-slate-950 dark:bg-amber-500 dark:text-slate-950 text-white py-4 rounded-2xl font-black flex items-center justify-center gap-3 hover:bg-slate-800 dark:hover:bg-amber-600 transition-all shadow-xl active:scale-95 text-sm md:text-base">
                  <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M8.684 13.342C8.886 12.938 9 12.482 9 12c0-.482-.114-.938-.316-1.342m0 2.684a3 3 0 110-2.684m0 2.684l6.632 3.316m-6.632-6l6.632-3.316m0 0a3 3 0 105.367-2.684 3 3 0 00-5.367 2.684zm0 9.316a3 3 0 105.368 2.684 3 3 0 00-5.368-2.684z"/></svg>
                  {t.shareReceipt}
                </button>
                <button onClick={() => setLastSale(null)} className="w-full py-4 text-slate-400 dark:text-slate-600 font-bold hover:text-slate-600 dark:hover:text-slate-400 text-sm">{t.startNewBill}</button>
              </div>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>

      <div className="flex-1 flex flex-col min-h-0">
        <div className="mb-4 md:mb-6 flex flex-col sm:flex-row gap-3 md:gap-4">
          <div className="flex-1 flex gap-2">
            <div className="flex-1 relative">
                <svg className="w-5 h-5 absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 dark:text-slate-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z"/></svg>
                <input type="text" placeholder={t.searchCatalog} value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} className="w-full bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-2xl py-3 md:py-3.5 pl-11 pr-4 md:pl-12 md:pr-6 outline-none focus:ring-4 focus:ring-amber-500/10 shadow-sm text-sm font-medium dark:text-slate-200" />
            </div>
            <button onClick={toggleScanner} className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-2xl px-4 flex items-center justify-center text-slate-500 dark:text-slate-400 hover:text-amber-500 transition-all shadow-sm"><svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 4v1m6 11h2m-6 0h-2v4m0-11v3m0 0h.01M12 12h4.01M16 20h4M4 12h4m12 0h.01M5 8h2a1 1 0 001-1V5a1 1 0 00-1-1H5a1 1 0 00-1 1v2a1 1 0 001 1zm12 0h2a1 1 0 001-1V5a1 1 0 00-1-1H5a1 1 0 00-1 1v2a1 1 0 001 1zM5 20h2a1 1 0 001-1v-2a1 1 0 00-1-1H5a1 1 0 00-1 1v2a1 1 0 001 1z"/></svg></button>
          </div>
          <div className="flex bg-white dark:bg-slate-900 p-1 rounded-2xl border border-slate-100 dark:border-slate-800 shadow-sm self-start sm:self-auto">
            <button onClick={() => setActiveTab('services')} className={`px-4 md:px-6 py-2 rounded-xl text-[10px] md:text-xs font-black uppercase tracking-widest transition-all ${activeTab === 'services' ? 'bg-amber-500 text-slate-900 shadow-md' : 'text-slate-400 hover:text-slate-600'}`}>{t.services}</button>
            <button onClick={() => setActiveTab('products')} className={`px-4 md:px-6 py-2 rounded-xl text-[10px] md:text-xs font-black uppercase tracking-widest transition-all ${activeTab === 'products' ? 'bg-amber-500 text-slate-900 shadow-md' : 'text-slate-400 hover:text-slate-600'}`}>{t.products}</button>
          </div>
        </div>
        <div className="flex-1 overflow-y-auto grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-3 md:gap-4 pr-1 scrollbar-hide pb-24 lg:pb-0">
          {filteredItems.map(item => (
            <motion.button layout key={item.id} whileHover={{ scale: 1.02 }} whileTap={{ scale: 0.98 }} onClick={() => addToCart(item, activeTab === 'services' ? 'service' : 'product')} className="bg-white dark:bg-slate-900 p-4 md:p-5 rounded-[2rem] border border-slate-100 dark:border-slate-800 shadow-sm hover:shadow-md transition-all text-left flex flex-col justify-between group h-32 md:h-40 relative overflow-hidden">
              <div className="relative z-10">
                <span className={`text-[8px] md:text-[9px] font-black uppercase tracking-widest px-2 py-0.5 md:py-1 rounded-lg mb-1 md:mb-2 inline-block ${activeTab === 'services' ? 'bg-amber-50 dark:bg-amber-900/20 text-amber-600 dark:text-amber-400' : 'bg-indigo-50 dark:bg-indigo-900/20 text-indigo-600 dark:text-indigo-400'}`}>
                  {activeTab === 'services' ? (item as Service).category : 'Retail'}
                </span>
                <h4 className="font-bold text-slate-800 dark:text-slate-200 text-xs md:text-sm leading-tight line-clamp-2">{item.name}</h4>
              </div>
              <div className="flex items-center justify-between relative z-10">
                <p className="text-base md:text-lg font-black text-slate-900 dark:text-white">{settings.currency}{item.price}</p>
                <div className="w-7 h-7 md:w-8 md:h-8 bg-slate-900 dark:bg-slate-800 text-white rounded-full flex items-center justify-center opacity-100 lg:opacity-0 group-hover:opacity-100 transition-all">
                  <svg className="w-3.5 h-3.5 md:w-4 md:h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M12 6v6m0 0v6m0-6h6m-6 0H6"/></svg>
                </div>
              </div>
            </motion.button>
          ))}
        </div>
      </div>

      <AnimatePresence>
        {(showMobileCart || window.innerWidth >= 1024) && (
          <>
            {showMobileCart && (
              <motion.div 
                initial={{ opacity: 0 }} 
                animate={{ opacity: 1 }} 
                exit={{ opacity: 0 }} 
                onClick={() => setShowMobileCart(false)}
                className="fixed inset-0 bg-slate-950/60 backdrop-blur-sm z-[70] lg:hidden"
              />
            )}
            <motion.div 
              initial={window.innerWidth < 1024 ? { y: '100%' } : { x: 400 }}
              animate={window.innerWidth < 1024 ? { y: 0 } : { x: 0 }}
              exit={window.innerWidth < 1024 ? { y: '100%' } : { x: 400 }}
              transition={{ type: 'spring', damping: 25, stiffness: 200 }}
              className={`fixed bottom-0 left-0 right-0 lg:static lg:w-96 flex flex-col bg-white dark:bg-slate-900 rounded-t-[2.5rem] lg:rounded-[2.5rem] border border-slate-100 dark:border-slate-800 shadow-2xl lg:shadow-xl overflow-hidden z-[80] h-[90vh] lg:h-auto`}
            >
              <div className="p-5 md:p-6 border-b border-slate-50 dark:border-slate-800 bg-slate-50/50 dark:bg-slate-800/20 flex justify-between items-center">
                <h3 className="text-lg md:text-xl font-black text-slate-800 dark:text-white flex items-center gap-2">{t.cart}</h3>
                <button onClick={() => setShowMobileCart(false)} className="lg:hidden p-2 text-slate-400 bg-slate-100 dark:bg-slate-800 rounded-full"><svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M6 18L18 6M6 6l12 12"/></svg></button>
              </div>
              <div className="flex-1 overflow-y-auto p-5 md:p-6 space-y-5 scrollbar-hide">
                <div>
                  <label className="text-[9px] md:text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-2 ml-1">{t.professional}</label>
                  <select value={selectedStaff} onChange={e => setSelectedStaff(e.target.value)} disabled={currentUser.role === 'employee'} className="w-full bg-slate-50 dark:bg-slate-800 border-none rounded-2xl px-4 py-3 text-sm font-bold dark:text-white disabled:opacity-50">
                    <option value="">{t.chooseProfessional}</option>
                    {staff.map(s => <option key={s.id} value={s.id}>{s.name}</option>)}
                  </select>
                </div>
                <div className="space-y-3">
                   <div className="flex justify-between items-end">
                      <label className="text-[9px] md:text-[10px] font-black text-slate-400 uppercase tracking-widest block">{t.customers}</label>
                      <button onClick={() => setIsAddingCustomer(true)} className="text-[9px] md:text-[10px] font-black text-amber-600 uppercase tracking-widest hover:text-amber-500 transition-colors">{t.quickAddClient}</button>
                   </div>
                   <select value={selectedCustomer} onChange={e => setSelectedCustomer(e.target.value)} className="w-full bg-slate-50 dark:bg-slate-800 border-none rounded-2xl px-4 py-3 text-sm font-bold dark:text-white">
                     <option value="">{t.walkInClient}</option>
                     {customers.map(c => <option key={c.id} value={c.id}>{c.name} ({c.phone})</option>)}
                   </select>
                </div>
                <div className="h-px bg-slate-50 dark:bg-slate-800 my-2"></div>
                {cart.map((item, idx) => (
                  <div key={idx} className="flex justify-between items-center group py-1">
                    <div className="flex-1">
                      <p className="font-bold text-slate-800 dark:text-slate-200 text-xs md:text-sm leading-tight">{item.name}</p>
                      <div className="flex items-center gap-1 mt-0.5">
                          <p className="text-[10px] text-slate-400 font-medium">{settings.currency}{item.price}</p>
                          {item.quantity > 1 && (
                              <p className="text-[10px] font-bold text-slate-600 dark:text-slate-300 bg-slate-100 dark:bg-slate-800 px-1.5 rounded-md">
                                  = {settings.currency}{(item.price * item.quantity).toFixed(2)}
                              </p>
                          )}
                      </div>
                    </div>
                    <div className="flex items-center gap-2 md:gap-3">
                      <div className="flex items-center bg-slate-100 dark:bg-slate-800 rounded-xl px-1.5 md:px-2">
                         <button onClick={() => updateQuantity(item.id, item.type, -1)} className="p-1.5 text-slate-400 hover:text-amber-500 transition-colors">-</button>
                         <span className="w-6 text-center text-xs font-black dark:text-white">{item.quantity}</span>
                         <button onClick={() => updateQuantity(item.id, item.type, 1)} className="p-1.5 text-slate-400 hover:text-amber-500 transition-colors">+</button>
                      </div>
                      <button onClick={() => removeFromCart(item.id, item.type)} className="text-slate-300 hover:text-rose-500 p-1 md:opacity-0 lg:group-hover:opacity-100 transition-all">
                        <svg className="w-4 h-4 md:w-5 md:h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"/></svg>
                      </button>
                    </div>
                  </div>
                ))}
                {cart.length === 0 && <p className="text-center py-10 text-slate-300 italic text-sm">{t.emptyCart}</p>}
              </div>
              <div className="p-6 md:p-8 bg-slate-50/50 dark:bg-slate-800/20 border-t border-slate-100 dark:border-slate-800 space-y-4">
                <div className="space-y-2 text-xs font-bold text-slate-500">
                  <div className="flex justify-between">
                      <span>{t.subtotal}</span>
                      <motion.span key={totals.subtotal} className="text-slate-900 dark:text-white">
                          {settings.currency}{totals.subtotal.toFixed(2)}
                      </motion.span>
                  </div>
                  {totals.discount > 0 && <div className="flex justify-between text-emerald-500"><span>{t.discount}</span><span>-{settings.currency}{totals.discount.toFixed(2)}</span></div>}
                  <div className="flex justify-between text-xl md:text-2xl font-black text-slate-900 dark:text-white pt-2 border-t border-slate-100 dark:border-slate-800">
                      <span>{t.total}</span>
                      <motion.span key={totals.total} className="text-amber-500">
                          {settings.currency}{totals.total.toFixed(2)}
                      </motion.span>
                  </div>
                </div>
                <div className="flex gap-2">
                   <input value={discountCode} onChange={e => setDiscountCode(e.target.value.toUpperCase())} placeholder="PROMO" className="flex-1 bg-white dark:bg-slate-900 border-none rounded-xl px-4 py-3 text-xs font-black uppercase tracking-widest dark:text-white shadow-sm" />
                   <button onClick={handleHoldSale} className="bg-slate-200 dark:bg-slate-800 text-slate-600 dark:text-slate-400 px-4 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all active:scale-95">{t.holdBill}</button>
                </div>
                <div className="grid grid-cols-2 gap-3 pb-4">
                   <button onClick={() => handleCheckout('cash')} className="bg-slate-900 dark:bg-slate-950 text-white py-4 md:py-5 rounded-2xl font-black text-xs md:text-sm uppercase tracking-widest hover:bg-slate-800 transition-all shadow-xl active:scale-95">{t.cash}</button>
                   <button onClick={() => handleCheckout('card')} className="bg-amber-500 text-slate-950 py-4 md:py-5 rounded-2xl font-black text-xs md:text-sm uppercase tracking-widest hover:bg-amber-400 transition-all shadow-xl active:scale-95">{t.card}</button>
                </div>
              </div>
            </motion.div>
          </>
        )}
      </AnimatePresence>

      <AnimatePresence>
        {isScanning && (
          <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="fixed inset-0 bg-slate-950/90 backdrop-blur-md z-[200] flex items-center justify-center p-4">
            <div className="w-full max-w-md bg-white dark:bg-slate-900 rounded-[2rem] overflow-hidden shadow-2xl relative">
