import React, { useState, useRef, useEffect } from 'react';
import { Service, Product, ShopSettings } from '../types';
import { TRANSLATIONS } from '../constants';
import { motion, AnimatePresence } from 'framer-motion';
import { Html5Qrcode } from 'html5-qrcode';

interface InventoryProps {
  services: Service[];
  products: Product[];
  settings: ShopSettings;
  onUpdateServices: (services: Service[]) => void;
  onUpdateProducts: (products: Product[]) => void;
}

const Inventory: React.FC<InventoryProps> = ({ services, products, settings, onUpdateServices, onUpdateProducts }) => {
  const [activeTab, setActiveTab] = useState<'services' | 'products'>('services');
  const [isEditing, setIsEditing] = useState<any>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [isScanning, setIsScanning] = useState(false);
  const html5QrCodeRef = useRef<Html5Qrcode | null>(null);
  const isScannerActiveRef = useRef(false);
  const barcodeInputRef = useRef<HTMLInputElement>(null);

  const t = TRANSLATIONS[settings.language];

  useEffect(() => {
    let isMounted = true;
    if (isScanning) {
        const startScanner = async () => {
            await new Promise(resolve => setTimeout(resolve, 500));
            if (!isMounted || !isScanning) return;
            try {
                if (!html5QrCodeRef.current) {
                  html5QrCodeRef.current = new Html5Qrcode("reader-inventory");
                }

                await html5QrCodeRef.current.start(
                    { facingMode: "environment" }, 
                    { 
                        fps: 15, 
                        qrbox: (viewfinderWidth, viewfinderHeight) => {
                            const width = Math.floor(viewfinderWidth * 0.8);
                            const height = Math.floor(viewfinderHeight * 0.4);
                            return { width, height };
                        },
                        experimentalFeatures: {
                            useBarCodeDetectorIfSupported: true
                        }
                    }, 
                    (decodedText) => {
                        if (isMounted) {
                            if (barcodeInputRef.current) barcodeInputRef.current.value = decodedText;
                            setIsScanning(false);
                        }
                    },
                    () => {}
                );
                if (isMounted) isScannerActiveRef.current = true;
            } catch (err) {
                 console.error("Inventory scanner failed", err);
                 if (isMounted) setIsScanning(false);
            }
        };
        startScanner();
    }
    return () => {
        isMounted = false;
        if (html5QrCodeRef.current) {
            const scanner = html5QrCodeRef.current;
            if (isScannerActiveRef.current) {
                scanner.stop().catch(() => {}).finally(() => {
                    try { scanner.clear(); } catch(e) {}
                    isScannerActiveRef.current = false;
                });
            } else {
                try { scanner.clear(); } catch(e) {}
            }
        }
    };
