          <tbody className="divide-y divide-slate-50 dark:divide-slate-800">
            {(activeTab === 'services' ? filteredServices : filteredProducts).map((item: any) => (
              <tr key={item.id} className="hover:bg-slate-50/30 dark:hover:bg-slate-800/30">
                <td className="px-8 py-6 font-bold text-slate-800 dark:text-slate-200 text-sm">{item.name}</td>
                <td className="px-8 py-6 text-xs text-slate-500">{activeTab === 'services' ? item.category : `${item.stock} left`}</td>
                <td className="px-8 py-6 font-black text-slate-950 dark:text-white">{settings.currency}{item.price}</td>
                <td className="px-8 py-6 text-right space-x-2">
                  <button onClick={() => setIsEditing(item)} className="p-2 text-slate-300 hover:text-amber-500"><svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z"/></svg></button>
                  <button onClick={() => deleteItem(item.id, activeTab === 'services' ? 'service' : 'product')} className="p-2 text-slate-300 hover:text-rose-500"><svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"/></svg></button>
