                <div className="bg-black relative min-h-[300px] w-full overflow-hidden">
                    {/* Visual Glow Effect for Feedback */}
                    <AnimatePresence>
                        {scanningFeedback && (
                            <motion.div 
                                initial={{ opacity: 0 }} 
                                animate={{ opacity: 1 }} 
                                exit={{ opacity: 0 }}
                                className={`absolute inset-0 z-10 pointer-events-none transition-colors duration-300 ${feedbackType === 'success' ? 'bg-emerald-500/10 shadow-[inset_0_0_100px_rgba(16,185,129,0.3)]' : 'bg-rose-500/20 shadow-[inset_0_0_100px_rgba(244,63,94,0.4)]'}`}
                            />
                        )}
                    </AnimatePresence>

                    <div id="reader" className="w-full h-full"></div>

                    <AnimatePresence>
                        {scanningFeedback && (
                            <motion.div 
                                initial={{ opacity: 0, scale: 0.9, y: 20 }} 
                                animate={{ opacity: 1, scale: 1, y: 0 }} 
                                exit={{ opacity: 0, scale: 0.9 }} 
                                className={`absolute bottom-6 left-6 right-6 p-4 rounded-2xl flex items-center gap-3 shadow-2xl z-20 border ${feedbackType === 'success' ? 'bg-emerald-600 border-emerald-400/50 text-white' : 'bg-rose-600 border-rose-400/50 text-white'}`}
                            >
                                <div className={`w-8 h-8 rounded-full flex items-center justify-center shrink-0 ${feedbackType === 'success' ? 'bg-white/20' : 'bg-white/20'}`}>
                                    {feedbackType === 'success' ? (
                                        <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M5 13l4 4L19 7"/></svg>
                                    ) : (
                                        <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z"/></svg>
                                    )}
                                </div>
                                <div className="flex-1">
                                    <p className="font-black text-sm">{scanningFeedback}</p>
                                    {feedbackType === 'error' && <p className="text-[10px] opacity-80 font-bold uppercase tracking-wider mt-0.5">Item not in catalog. Try manual search.</p>}
                                </div>
                            </motion.div>
                        )}
                    </AnimatePresence>
                </div>
                <div className="p-4 text-center bg-slate-50 dark:bg-slate-800 text-[10px] font-black uppercase tracking-widest text-slate-500">
                    <p>Align barcode horizontally</p>
                </div>
            </div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* Quick Add Customer Modal */}
      <AnimatePresence>
          {isAddingCustomer && (
              <div className="fixed inset-0 bg-slate-950/60 backdrop-blur-md z-[100] flex items-end sm:items-center justify-center p-0 sm:p-4">
                  <motion.div 
                      initial={{ y: "100%" }}
                      animate={{ y: 0 }}
                      exit={{ y: "100%" }}
                      className="bg-white dark:bg-slate-900 rounded-t-[2.5rem] sm:rounded-[2.5rem] w-full max-w-md p-8 md:p-10 shadow-2xl"
                  >
                      <div className="flex justify-between items-center mb-6">
                          <h3 className="text-xl font-black text-slate-900 dark:text-white">{t.quickAddClient}</h3>
                          <button onClick={() => setIsAddingCustomer(false)} className="p-2 bg-slate-100 dark:bg-slate-800 rounded-full text-slate-400">
                              <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M6 18L18 6M6 6l12 12"/></svg>
                          </button>
                      </div>
                      <div className="space-y-4">
                          <div>
                              <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-1.5 ml-1">{t.name}</label>
                              <input 
                                  value={newCustomerData.name} 
                                  onChange={e => setNewCustomerData({...newCustomerData, name: e.target.value})}
                                  className="w-full bg-slate-50 dark:bg-slate-800 border-0 rounded-2xl px-5 py-3 focus:ring-4 focus:ring-amber-500/10 outline-none font-bold dark:text-white"
                                  placeholder="John Doe"
                              />
                          </div>
                          <div>
                              <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-1.5 ml-1">{t.mobile}</label>
                              <input 
                                  value={newCustomerData.phone} 
                                  onChange={e => setNewCustomerData({...newCustomerData, phone: e.target.value})}
                                  className="w-full bg-slate-50 dark:bg-slate-800 border-0 rounded-2xl px-5 py-3 focus:ring-4 focus:ring-amber-500/10 outline-none font-bold dark:text-white"
                                  placeholder="+1..."
                              />
                          </div>
                          <div>
                              <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-1.5 ml-1">{t.email} ({t.optional})</label>
                              <input 
                                  value={newCustomerData.email} 
                                  onChange={e => setNewCustomerData({...newCustomerData, email: e.target.value})}
                                  className="w-full bg-slate-50 dark:bg-slate-800 border-0 rounded-2xl px-5 py-3 focus:ring-4 focus:ring-amber-500/10 outline-none font-bold dark:text-white"
                                  placeholder="john@example.com"
                              />
                          </div>
                          <button 
                              onClick={saveNewCustomer}
                              disabled={!newCustomerData.name}
                              className="w-full bg-amber-500 text-slate-950 py-4 rounded-2xl font-black uppercase tracking-widest mt-4 disabled:opacity-50 disabled:cursor-not-allowed"
                          >
                              Save & Select
                          </button>
                      </div>
                  </motion.div>
              </div>
          )}
      </AnimatePresence>
    </div>
  );
};

export default POS;

import React, { useState, useRef, useEffect } from 'react';
import { Service, Product, ShopSettings } from '../types';
import { TRANSLATIONS } from '../constants';
import { motion, AnimatePresence } from 'framer-motion';
import { Html5Qrcode, Html5QrcodeSupportedFormats } from 'html5-qrcode';

interface InventoryProps {
  services: Service[];
  products: Product[];
  settings: ShopSettings;
  onUpdateServices: (services: Service[]) => void;
  onUpdateProducts: (products: Product[]) => void;
}

const Inventory: React.FC<InventoryProps> = ({ services, products, settings, onUpdateServices, onUpdateProducts }) => {
  const [activeTab, setActiveTab] = useState<'services' | 'products'>('services');
  const [isEditing, setIsEditing] = useState<any>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [isScanning, setIsScanning] = useState(false);
  const html5QrCodeRef = useRef<Html5Qrcode | null>(null);
  const barcodeInputRef = useRef<HTMLInputElement>(null);
  const isScannerActiveRef = useRef(false);

  const t = TRANSLATIONS[settings.language];

  useEffect(() => {
    let isMounted = true;

    if (isScanning) {
        const startScanner = async () => {
            await new Promise(resolve => setTimeout(resolve, 500));
            if (!isMounted || !isScanning) return;

            if (!document.getElementById("reader-inventory")) return;

            // Cleanup previous
            if (html5QrCodeRef.current) {
                try { await html5QrCodeRef.current.stop(); } catch(e) {}
                html5QrCodeRef.current = null;
            }

            try {
                const html5QrCode = new Html5Qrcode("reader-inventory", {
                  formatsToSupport: [
                    Html5QrcodeSupportedFormats.EAN_13,
                    Html5QrcodeSupportedFormats.EAN_8,
                    Html5QrcodeSupportedFormats.CODE_128,
                    Html5QrcodeSupportedFormats.UPC_A,
                    Html5QrcodeSupportedFormats.UPC_E
                  ],
                  verbose: false
                });

                html5QrCodeRef.current = html5QrCode;

                await html5QrCode.start(
                    { facingMode: "environment" }, 
                    { 
                        fps: 15, 
                        qrbox: (viewfinderWidth, viewfinderHeight) => {
                            const width = Math.floor(viewfinderWidth * 0.85);
                            const height = Math.floor(viewfinderHeight * 0.35);
                            return { width, height };
                        },
                        aspectRatio: 1.777778,
                    }, 
                    (decodedText) => {
                        if (isMounted) {
                            if (barcodeInputRef.current) barcodeInputRef.current.value = decodedText;
                            if ("vibrate" in navigator) navigator.vibrate(100);
                            stopScanner();
                        }
                    },
                    () => {}
                );
                if (isMounted) isScannerActiveRef.current = true;
            } catch (err) {
                 console.error("Inventory scanner failed", err);
                 if (isMounted) setIsScanning(false);
            }
        };
        startScanner();
    }

    const stopScanner = () => {
        setIsScanning(false);
        const scanner = html5QrCodeRef.current;
        if (scanner && isScannerActiveRef.current) {
             scanner.stop().catch(() => {}).finally(() => {
                 try { scanner.clear(); } catch(e) {}
                 isScannerActiveRef.current = false;
             });
        }
    };

    return () => {
        isMounted = false;
        if (html5QrCodeRef.current) {
             const scanner = html5QrCodeRef.current;
             scanner.stop().catch(() => {}).finally(() => {
                 try { scanner.clear(); } catch(e) {}
                 isScannerActiveRef.current = false;
             });
        }
    };
  }, [isScanning]);

  const filteredServices = services.filter(s => s.name.toLowerCase().includes(searchTerm.toLowerCase()) || s.category.toLowerCase().includes(searchTerm.toLowerCase()));
  const filteredProducts = products.filter(p => p.name.toLowerCase().includes(searchTerm.toLowerCase()) || (p.barcode && p.barcode.includes(searchTerm)));

  const deleteItem = (id: string, type: 'service' | 'product') => {
    if (!confirm('Permanently delete this entry?')) return;
    if (type === 'service') onUpdateServices(services.filter(s => s.id !== id));
    else onUpdateProducts(products.filter(p => p.id !== id));
  };

  const saveItem = (e: React.FormEvent) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget as HTMLFormElement);
    const itemData = Object.fromEntries(formData.entries());

    if (activeTab === 'services') {
      const newService: Service = {
        id: isEditing?.id || Math.random().toString(36).substr(2, 9).toUpperCase(),
        name: itemData.name as string,
        price: parseFloat(itemData.price as string) || 0,
        duration: parseInt(itemData.duration as string) || 30,
        category: itemData.category as string,
      };
      if (isEditing.id) onUpdateServices(services.map(s => s.id === isEditing.id ? newService : s));
      else onUpdateServices([...services, newService]);
    } else {
      const newProduct: Product = {
        id: isEditing?.id || Math.random().toString(36).substr(2, 9).toUpperCase(),
        name: itemData.name as string,
        price: parseFloat(itemData.price as string) || 0,
        cost: parseFloat(itemData.cost as string) || 0,
        stock: parseInt(itemData.stock as string) || 0,
        barcode: (itemData.barcode as string) || undefined,
        lowStockThreshold: parseInt(itemData.lowStockThreshold as string) || 15
      };
      if (isEditing.id) onUpdateProducts(products.map(p => p.id === isEditing.id ? newProduct : p));
      else onUpdateProducts([...products, newProduct]);
    }
    setIsEditing(null);
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
        <div>
          <h2 className="text-2xl md:text-3xl font-bold text-slate-800 dark:text-white font-brand">{t.shopCatalog}</h2>
          <p className="text-slate-500 dark:text-slate-400 text-sm">{t.updatePrices}</p>
        </div>
        <button onClick={() => setIsEditing({})} className="bg-slate-950 dark:bg-slate-800 text-white px-6 py-3 rounded-xl font-black flex items-center gap-2 hover:bg-slate-800 transition-all shadow-lg text-sm w-full sm:w-auto justify-center">
          <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M12 6v6m0 0v6m0-6h6m-6 0H6"/></svg>
          {activeTab === 'services' ? t.newService : t.newProduct}
        </button>
      </div>
      <div className="relative">
        <svg className="w-5 h-5 absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 dark:text-slate-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z"/></svg>
        <input type="text" placeholder={t.searchCatalog} value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} className="w-full bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-2xl py-3.5 pl-12 pr-6 outline-none focus:ring-4 focus:ring-amber-500/10 shadow-sm text-sm dark:text-slate-200" />
      </div>
      <div className="flex bg-white dark:bg-slate-900 p-1 rounded-xl shadow-sm border border-slate-100 dark:border-slate-800 self-start w-full sm:w-auto">
        <button onClick={() => setActiveTab('services')} className={`flex-1 sm:px-8 py-2.5 rounded-lg font-bold transition-all text-xs md:text-sm ${activeTab === 'services' ? 'bg-amber-500 text-slate-950 shadow-sm' : 'text-slate-400 dark:text-slate-500 hover:text-slate-600'}`}>{t.services}</button>
        <button onClick={() => setActiveTab('products')} className={`flex-1 sm:px-8 py-2.5 rounded-lg font-bold transition-all text-xs md:text-sm ${activeTab === 'products' ? 'bg-amber-500 text-slate-950 shadow-sm' : 'text-slate-400 dark:text-slate-500 hover:text-slate-600'}`}>{t.inventory}</button>
      </div>
      <div className="md:hidden space-y-4">
        {(activeTab === 'services' ? filteredServices : filteredProducts).map((item: any) => (
           <div key={item.id} className="bg-white dark:bg-slate-900 p-5 rounded-2xl border border-slate-100 dark:border-slate-800 shadow-sm">
              <div className="flex justify-between items-start mb-2">
                 <h4 className="font-bold text-slate-800 dark:text-slate-200">{item.name}</h4>
                 <span className="text-xl font-black text-amber-500">{settings.currency}{item.price}</span>
              </div>
              <div className="flex gap-2 mt-4">
                  <button onClick={() => setIsEditing(item)} className="flex-1 py-2 rounded-lg bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-300 font-bold text-xs uppercase tracking-wider">Edit</button>
                  <button onClick={() => deleteItem(item.id, activeTab === 'services' ? 'service' : 'product')} className="px-3 py-2 rounded-lg bg-rose-50 dark:bg-rose-900/20 text-rose-500"><svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"/></svg></button>
              </div>
           </div>
        ))}
      </div>
      <div className="hidden md:block bg-white dark:bg-slate-900 rounded-[2rem] border border-slate-100 dark:border-slate-800 shadow-sm overflow-hidden">
        <table className="w-full text-left">
          <thead className="bg-slate-50 dark:bg-slate-800/50 border-b border-slate-100 dark:border-slate-800 text-[10px] font-black text-slate-400 uppercase tracking-widest">
            <tr><th className="px-8 py-5">Item</th><th className="px-8 py-5">Status</th><th className="px-8 py-5">Price</th><th className="px-8 py-5 text-right">Actions</th></tr>
          </thead>
          <tbody className="divide-y divide-slate-50 dark:divide-slate-800">
            {(activeTab === 'services' ? filteredServices : filteredProducts).map((item: any) => (
              <tr key={item.id} className="hover:bg-slate-50/30 dark:hover:bg-slate-800/30">
                <td className="px-8 py-6 font-bold text-slate-800 dark:text-slate-200 text-sm">{item.name}</td>
                <td className="px-8 py-6 text-xs text-slate-500">{activeTab === 'services' ? item.category : `${item.stock} left`}</td>
                <td className="px-8 py-6 font-black text-slate-950 dark:text-white">{settings.currency}{item.price}</td>
                <td className="px-8 py-6 text-right space-x-2">
                  <button onClick={() => setIsEditing(item)} className="p-2 text-slate-300 dark:text-slate-600 hover:text-amber-500 transition-colors"><svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z"/></svg></button>
                  <button onClick={() => deleteItem(item.id, activeTab === 'services' ? 'service' : 'product')} className="p-2 text-slate-300 dark:text-slate-600 hover:text-rose-500 transition-colors"><svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"/></svg></button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
      <AnimatePresence>
        {isEditing && (
          <div className="fixed inset-0 bg-slate-950/40 backdrop-blur-sm z-[100] flex items-end sm:items-center justify-center p-0 sm:p-4">
            <motion.div initial={{ y: "100%" }} animate={{ y: 0 }} exit={{ y: "100%" }} className="bg-white dark:bg-slate-900 rounded-t-[2.5rem] sm:rounded-[2.5rem] w-full max-w-md p-8 md:p-10 shadow-2xl overflow-y-auto max-h-[90vh]">
              <div className="flex justify-between items-center mb-8"><h3 className="text-2xl font-black text-slate-900 dark:text-white tracking-tight">{isEditing.id ? t.editEntry : t.newEntry}</h3><button onClick={() => setIsEditing(null)} className="p-2 bg-slate-50 dark:bg-slate-800 rounded-full text-slate-400"><svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M6 18L18 6M6 6l12 12"/></svg></button></div>
              <form onSubmit={saveItem} className="space-y-5">
                <div>
                    <label className="text-[10px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest block mb-2 ml-1">Name</label>
                    <input name="name" type="text" defaultValue={isEditing.name || ''} required className="w-full bg-slate-50 dark:bg-slate-800 border-0 rounded-2xl px-5 py-3.5 focus:ring-4 focus:ring-amber-500/10 outline-none text-sm font-bold dark:text-slate-200" />
                </div>

                {activeTab === 'products' && (
                  <div>
                    <label className="text-[10px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest block mb-2 ml-1">Barcode</label>
                    <div className="flex gap-2">
                        <input ref={barcodeInputRef} name="barcode" type="text" defaultValue={isEditing.barcode || ''} className="w-full bg-slate-50 dark:bg-slate-800 border-0 rounded-2xl px-5 py-3.5 focus:ring-4 focus:ring-amber-500/10 outline-none text-sm font-bold dark:text-slate-200" />
                        <button type="button" onClick={() => setIsScanning(true)} className="bg-slate-900 text-white p-3.5 rounded-2xl hover:bg-slate-800 transition-colors">
                            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 4v1m6 11h2m-6 0h-2v4m0-11v3m0 0h.01M12 12h4.01M16 20h4M4 12h4m12 0h.01M5 8h2a1 1 0 001-1V5a1 1 0 00-1-1H5a1 1 0 00-1 1v2a1 1 0 001 1zm12 0h2a1 1 0 001-1V5a1 1 0 00-1-1h-2a1 1 0 00-1 1v2a1 1 0 001 1zM5 20h2a1 1 0 001-1v-2a1 1 0 00-1-1H5a1 1 0 00-1 1v2a1 1 0 001 1z"/></svg>
                        </button>
                    </div>
                  </div>
                )}

                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="text-[10px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest block mb-2 ml-1">Price</label>
                    <input name="price" type="number" step="0.01" defaultValue={isEditing.price || ''} required className="w-full bg-slate-50 dark:bg-slate-800 border-0 rounded-2xl px-5 py-3.5 focus:ring-4 focus:ring-amber-500/10 outline-none text-sm font-bold dark:text-slate-200" />
                  </div>
                  {activeTab === 'products' ? (
                      <div>
                        <label className="text-[10px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest block mb-2 ml-1">Cost</label>
                        <input name="cost" type="number" step="0.01" defaultValue={isEditing.cost || ''} className="w-full bg-slate-50 dark:bg-slate-800 border-0 rounded-2xl px-5 py-3.5 focus:ring-4 focus:ring-amber-500/10 outline-none text-sm font-bold dark:text-slate-200" />
                      </div>
                  ) : (
                      <div>
                        <label className="text-[10px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest block mb-2 ml-1">Mins</label>
                        <input name="duration" type="number" defaultValue={isEditing.duration || 30} className="w-full bg-slate-50 dark:bg-slate-800 border-0 rounded-2xl px-5 py-3.5 focus:ring-4 focus:ring-amber-500/10 outline-none text-sm font-bold dark:text-slate-200" />
                      </div>
                  )}
                </div>

                {activeTab === 'products' ? (
                  <div className="grid grid-cols-2 gap-4">
                      <div>
                        <label className="text-[10px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest block mb-2 ml-1">Stock</label>
                        <input name="stock" type="number" defaultValue={isEditing.stock || 0} className="w-full bg-slate-50 dark:bg-slate-800 border-0 rounded-2xl px-5 py-3.5 focus:ring-4 focus:ring-amber-500/10 outline-none text-sm font-bold dark:text-slate-200" />
                      </div>
                      <div>
                        <label className="text-[10px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest block mb-2 ml-1">Low Stock Alert</label>
                        <input name="lowStockThreshold" type="number" defaultValue={isEditing.lowStockThreshold || 15} className="w-full bg-slate-50 dark:bg-slate-800 border-0 rounded-2xl px-5 py-3.5 focus:ring-4 focus:ring-amber-500/10 outline-none text-sm font-bold dark:text-slate-200" />
                      </div>
                  </div>
                ) : (
                   <div>
                    <label className="text-[10px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest block mb-2 ml-1">Category</label>
                    <input name="category" type="text" defaultValue={isEditing.category || ''} required className="w-full bg-slate-50 dark:bg-slate-800 border-0 rounded-2xl px-5 py-3.5 focus:ring-4 focus:ring-amber-500/10 outline-none text-sm font-bold dark:text-slate-200" />
                   </div>
                )}

                <button type="submit" className="w-full py-4 bg-amber-500 text-slate-950 rounded-2xl font-black text-base shadow-xl mt-4">Save Changes</button>
              </form>
            </motion.div>
          </div>
        )}
      </AnimatePresence>
      <AnimatePresence>
        {isScanning && (
          <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="fixed inset-0 bg-slate-950/90 backdrop-blur-md z-[200] flex items-center justify-center p-4">
            <div className="w-full max-w-md bg-white dark:bg-slate-900 rounded-[2rem] overflow-hidden shadow-2xl relative">
                <div className="p-6 border-b border-slate-100 dark:border-slate-800 flex justify-between items-center"><h3 className="font-black text-slate-900 dark:text-white text-lg flex items-center gap-2">Scanner</h3><button onClick={() => setIsScanning(false)} className="p-2 bg-slate-100 dark:bg-slate-800 rounded-full text-slate-500"><svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12"/></svg></button></div>
                <div className="bg-black relative min-h-[300px] w-full overflow-hidden">
                    <div id="reader-inventory" className="w-full h-full"></div>
                </div>
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
};

export default Inventory;

import React, { useState, useEffect, ReactNode, ErrorInfo } from 'react';
import Sidebar from './components/Sidebar';
import Dashboard from './components/Dashboard';
import POS from './components/POS';
import Finance from './components/Finance';
import Customers from './components/Customers';
import Settings from './components/Settings';
import Inventory from './components/Inventory';
import StaffManagement from './components/StaffManagement';
import Login from './components/Login';
import InstallBanner from './components/InstallBanner';
import { View, Sale, Expense, Service, Product, Staff, Customer, ShopSettings, Language } from './types';
import { INITIAL_SERVICES, INITIAL_PRODUCTS, INITIAL_STAFF, INITIAL_EXPENSES, INITIAL_CUSTOMERS, DEFAULT_SETTINGS } from './constants';
import { motion, AnimatePresence } from 'framer-motion';
import { supabase } from './supabaseClient';

interface ErrorBoundaryProps {
  children: ReactNode;
}

interface ErrorBoundaryState {
  hasError: boolean;
}

// Error Boundary to prevent white screens
class ErrorBoundary extends React.Component<ErrorBoundaryProps, ErrorBoundaryState> {
  constructor(props: ErrorBoundaryProps) {
    super(props);
    this.state = { hasError: false };
  }

  static getDerivedStateFromError(error: Error): ErrorBoundaryState {
    return { hasError: true };
  }

  componentDidCatch(error: Error, errorInfo: ErrorInfo) {
    console.error("Application Error:", error, errorInfo);
  }

  render() {
    if (this.state.hasError) {
      return (
        <div className="h-full w-full flex flex-col items-center justify-center p-8 text-center">
          <div className="w-16 h-16 bg-rose-100 dark:bg-rose-900/20 text-rose-500 rounded-full flex items-center justify-center text-3xl mb-4">
            ⚠️
          </div>
          <h2 className="text-xl font-black text-slate-800 dark:text-white mb-2">Something went wrong</h2>
          <p className="text-slate-500 dark:text-slate-400 mb-6 text-sm">We encountered an unexpected error loading this section.</p>
          <button 
            onClick={() => {
              this.setState({ hasError: false });
              window.location.reload();
            }}
            className="bg-slate-900 dark:bg-white text-white dark:text-slate-900 px-6 py-3 rounded-xl font-bold uppercase tracking-wider text-xs shadow-lg active:scale-95 transition-transform"
          >
            Reload App
          </button>
        </div>
      );
    }

    return this.props.children;
  }
}

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<Staff | null>(() => {
    const saved = localStorage.getItem('trimtime_session');
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        if (parsed.user && parsed.expiry && Date.now() < parsed.expiry) return parsed.user;
      } catch (e) {}
    }
    return null;
  });

  const [currentView, setCurrentView] = useState<View>(
    currentUser?.role === 'employee' ? View.POS : View.DASHBOARD
  );

  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [loading, setLoading] = useState(true);
  const [services, setServices] = useState<Service[]>([]);
  const [products, setProducts] = useState<Product[]>([]);
  const [staff, setStaff] = useState<Staff[]>([]);
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [sales, setSales] = useState<Sale[]>([]);
  const [settings, setSettings] = useState<ShopSettings>(DEFAULT_SETTINGS);
  const [sessionLanguage, setSessionLanguage] = useState<Language>(() => (localStorage.getItem('trimtime_lang') as Language) || 'en');
  const [isDarkMode, setIsDarkMode] = useState(() => localStorage.getItem('trimtime_theme') === 'dark');

  // PWA Install States
  const [deferredPrompt, setDeferredPrompt] = useState<any>(null);

  useEffect(() => {
    const handleBeforeInstallPrompt = (e: Event) => {
      e.preventDefault();
      setDeferredPrompt(e);
    };
    window.addEventListener('beforeinstallprompt', handleBeforeInstallPrompt);
    return () => window.removeEventListener('beforeinstallprompt', handleBeforeInstallPrompt);
  }, []);

  useEffect(() => {
    const fetchData = async () => {
      try {
        const [sv, pr, st, ex, cu, sa, se] = await Promise.all([
          supabase.from('services').select('*'),
          supabase.from('products').select('*'),
          supabase.from('staff').select('*'),
          supabase.from('expenses').select('*'),
          supabase.from('customers').select('*'),
          supabase.from('sales').select('*'),
          supabase.from('settings').select('*').single()
        ]);

        if (sv.data && sv.data.length > 0) setServices(sv.data);
        else if (sv.error) setServices(INITIAL_SERVICES); 
        else setServices([]); // Empty DB = Empty List

        if (pr.data && pr.data.length > 0) setProducts(pr.data.map((p: any) => ({ ...p, lowStockThreshold: p.low_stock_threshold })));
        else if (pr.error) setProducts(INITIAL_PRODUCTS);
        else setProducts([]);

        if (st.data && st.data.length > 0) setStaff(st.data);
        else if (st.error) setStaff(INITIAL_STAFF);
        // Note: For staff, we might want to keep at least one admin if empty, but assuming DB handles it.
        else if (st.data && st.data.length === 0) setStaff(INITIAL_STAFF); // Fallback for staff to ensure login

        if (ex.data && ex.data.length > 0) setExpenses(ex.data.map((e: any) => ({ ...e, receiptImage: e.receipt_image })));
        else if (ex.error) setExpenses(INITIAL_EXPENSES);
        else setExpenses([]); // Don't show demo expenses if DB is connected but empty

        if (cu.data && cu.data.length > 0) setCustomers(cu.data.map((c: any) => ({ ...c, createdAt: c.created_at })));
        else if (cu.error) setCustomers(INITIAL_CUSTOMERS);
        else setCustomers([]);

        if (sa.data) {
          setSales(sa.data.map((s: any) => ({ 
            ...s, 
            // Ensure items is always an array, even if DB has null/invalid json
            items: (typeof s.items === 'string' ? JSON.parse(s.items) : s.items) || [],
            staffName: s.professional_name,
            customerName: s.customer_name
          })));
        }

        if (se.data?.data) setSettings({ ...DEFAULT_SETTINGS, ...se.data.data });

        if (sv.error) console.error("Services Fetch Error:", sv.error);
        if (pr.error) console.error("Products Fetch Error:", pr.error);
      } catch (e) { console.error("Error loading data:", e); }
      finally { setLoading(false); }
    };
    fetchData();
  }, []);

  useEffect(() => {
    document.documentElement.classList.toggle('dark', isDarkMode);
    localStorage.setItem('trimtime_theme', isDarkMode ? 'dark' : 'light');
  }, [isDarkMode]);

  useEffect(() => {
    document.documentElement.lang = sessionLanguage;
    document.dir = ['ur', 'fa'].includes(sessionLanguage) ? 'rtl' : 'ltr';
    localStorage.setItem('trimtime_lang', sessionLanguage);
  }, [sessionLanguage]);

  // --- DATA PERSISTENCE HANDLERS ---

  const handleUpdateServices = async (updated: Service[]) => {
    const currentIds = new Set<string>(services.map(i => i.id));
    const newIds = new Set<string>(updated.map(i => i.id));
    const toDelete: string[] = Array.from(currentIds).filter(id => !newIds.has(id));

    setServices(updated);

    try {
      if (toDelete.length) await supabase.from('services').delete().in('id', toDelete);
      if (updated.length) {
          const { error } = await supabase.from('services').upsert(updated);
          if (error) throw error;
      }
    } catch (error) { 
        const err = error as any;
        console.error("DB Sync Error (Services):", err);
        alert("Failed to save services. Check database connection.");
    }
  };

  const handleUpdateProducts = async (updated: Product[]) => {
    const currentIds = new Set<string>(products.map(i => i.id));
    const newIds = new Set<string>(updated.map(i => i.id));
    const toDelete: string[] = Array.from(currentIds).filter(id => !newIds.has(id));

    setProducts(updated);

    // Attempt to save full product details including new fields
    const dbRowsFull = updated.map(p => ({
        id: p.id,
        name: p.name,
        price: p.price,
        cost: p.cost,
        stock: p.stock,
        barcode: p.barcode || null,
        low_stock_threshold: p.lowStockThreshold || 15
    }));

    // Fallback if DB schema is outdated (missing barcode/low_stock_threshold columns)
    const dbRowsSafe = updated.map(p => ({
        id: p.id,
        name: p.name,
        price: p.price,
        // Exclude cost from safe fallback as it might be missing in very old schemas
        stock: p.stock
    }));

    try {
      if (toDelete.length) await supabase.from('products').delete().in('id', toDelete);

      if (dbRowsFull.length) {
          const { error } = await supabase.from('products').upsert(dbRowsFull);
          if (error) {
            // Check for schema mismatch errors
            if (error.code === 'PGRST204' || error.message.includes('column') || error.message.includes('does not exist')) {
                console.warn("DB Schema mismatch detected. Retrying with core fields only...");

                // Alert the user that advanced fields aren't saving
                alert("NOTICE: Your database schema appears outdated. 'Barcode', 'Cost', and 'Low Stock' fields are saved locally but could not be synced to the cloud. Please update your Supabase 'products' table.");

                const { error: retryError } = await supabase.from('products').upsert(dbRowsSafe);
                if (retryError) throw retryError;
            } else {
                throw error;
            }
          }
      }
    } catch (error) { 
        const err = error as any;
        console.error("DB Sync Error (Products):", err); 
        alert(`Failed to save products: ${err.message}`);
    }
  };

  const handleUpdateStaff = async (updated: Staff[]) => {
    const currentIds = new Set<string>(staff.map(i => i.id));
    const newIds = new Set<string>(updated.map(i => i.id));
    const toDelete: string[] = Array.from(currentIds).filter(id => !newIds.has(id));

    setStaff(updated);

    try {
      if (toDelete.length) await supabase.from('staff').delete().in('id', toDelete);
      if (updated.length) {
          const { error } = await supabase.from('staff').upsert(updated);
          if (error) throw error;
      }
    } catch (error) { 
        const err = error as any;
        console.error("DB Sync Error (Staff):", err);
        alert("Failed to save staff. Check database connection.");
    }
  };

  const handleUpdateCustomers = async (updated: Customer[]) => {
    const currentIds = new Set<string>(customers.map(i => i.id));
    const newIds = new Set<string>(updated.map(i => i.id));
    const toDelete: string[] = Array.from(currentIds).filter(id => !newIds.has(id));

    setCustomers(updated);

    const dbRows = updated.map(c => ({
        id: c.id,
        name: c.name,
        phone: c.phone,
        email: c.email,
        notes: c.notes,
        created_at: c.createdAt
    }));

    try {
      if (toDelete.length) await supabase.from('customers').delete().in('id', toDelete);
      if (dbRows.length) {
          const { error } = await supabase.from('customers').upsert(dbRows);
          if (error) throw error;
      }
    } catch (error) { 
        const err = error as any;
        console.error("DB Sync Error (Customers):", err);
        alert("Failed to save customers. Check database connection.");
    }
  };

  const handleUpdateSettings = async (updated: ShopSettings) => {
    setSettings(updated);
    try {
      const { error } = await supabase.from('settings').upsert({ id: 1, data: updated });
      if (error) throw error;
    } catch (error) { 
        const err = error as any;
        console.error("DB Sync Error (Settings):", err);
        alert("Failed to save settings.");
    }
  };

  const handleCompleteSale = async (sale: Sale) => {
    setSales(prev => [...prev, sale]);
    try {
      const dbSale = {
          id: sale.id,
          timestamp: sale.timestamp,
          items: sale.items, 
          staff_id: sale.staffId,
          customer_id: sale.customerId,
          total: sale.total,
          tax: sale.tax,
          discount: sale.discount,
          discount_code: sale.discountCode,
          payment_method: sale.paymentMethod,
          tax_type: sale.taxType,
          customer_name: sale.customerName,
          professional_name: sale.staffName
      };
      const { error } = await supabase.from('sales').insert(dbSale);
      if (error) throw error;

      let productsUpdated = false;
      const newProducts = [...products];
      sale.items.forEach(item => {
          if (item.type === 'product') {
              const idx = newProducts.findIndex(p => p.id === item.id);
              if (idx > -1) {
                  newProducts[idx] = { ...newProducts[idx], stock: newProducts[idx].stock - item.quantity };
                  productsUpdated = true;
              }
          }
      });
      if (productsUpdated) handleUpdateProducts(newProducts);
    } catch (error) { 
        const err = error as any;
        console.error("DB Sync Error (Sale):", err);
        alert("Sale saved locally but failed to sync to DB.");
    }
  };

  const handleDeleteSales = async (ids: string[]) => {
    setSales(prev => prev.filter(s => !ids.includes(s.id)));
    try {
      const { error } = await supabase.from('sales').delete().in('id', ids);
      if (error) throw error;
    } catch (error) {
       const err = error as any;
       console.error("DB Sync Error (Delete Sales):", err);
       alert("Failed to delete sales from DB.");
    }
  };

  const handleAddExpense = async (expense: Expense) => {
      setExpenses(prev => [...prev, expense]);
      const dbExpense = {
          id: expense.id,
          date: expense.date,
          category: expense.category,
          amount: expense.amount,
          description: expense.description || '', // Ensure fallback
          receipt_image: expense.receiptImage || null // Ensure null if undefined
      };
      try {
        const { error } = await supabase.from('expenses').insert(dbExpense);
        if (error) throw error;
      } catch (error) { 
          const err = error as any;
          console.error("DB Sync Error (Expense):", err);
          alert("Failed to save expense to DB: " + err.message);
      }
  };

  const handleDeleteExpense = async (id: string) => {
      setExpenses(prev => prev.filter(e => e.id !== id));
      try {
        const { error } = await supabase.from('expenses').delete().eq('id', id);
        if (error) throw error;
      } catch (error) { 
          const err = error as any;
          console.error("DB Sync Error (Delete Expense):", err);
          alert("Failed to delete expense from DB: " + err.message);
      }
  };

  const handlePurgeSales = async () => {
    setSales([]);
    try {
       const { error } = await supabase.from('sales').delete().neq('id', '0'); 
       if (error) throw error;
    } catch (error) { 
        const err = error as any;
        console.error("DB Sync Error (Purge Sales):", err);
        alert("Failed to purge sales from DB.");
    }
  };

  const handleLogin = (user: Staff, remember: boolean) => {
    const expiry = Date.now() + (remember ? 30 : 1) * 24 * 60 * 60 * 1000;
    localStorage.setItem('trimtime_session', JSON.stringify({ user, expiry }));
    setCurrentUser(user);
    setCurrentView(user.role === 'employee' ? View.POS : View.DASHBOARD);
  };

  const handleLogout = () => {
    localStorage.removeItem('trimtime_session');
    setCurrentUser(null);
  };

  if (loading) return <div className="h-screen w-full flex items-center justify-center bg-slate-950"><div className="animate-spin rounded-full h-12 w-12 border-t-2 border-amber-500"></div></div>;
  if (!currentUser) return <Login onLogin={handleLogin} staffList={staff} shopName={settings.shopName} />;

  return (
    <div className="flex h-screen bg-slate-50 dark:bg-slate-950 overflow-hidden font-sans transition-colors duration-300">
      <Sidebar 
        currentView={currentView} onViewChange={setCurrentView} 
        shopName={settings.shopName} userRole={currentUser.role} 
        isOpen={isSidebarOpen} onClose={() => setIsSidebarOpen(false)}
        language={sessionLanguage} onLanguageChange={setSessionLanguage}
      />

      <div className="flex-1 flex flex-col min-w-0 md:pl-64 overflow-hidden relative">
        {/* Responsive Header */}
        <header className="flex md:hidden items-center justify-between p-4 bg-white dark:bg-slate-900 border-b border-slate-100 dark:border-slate-800 z-50 sticky top-0 shadow-sm">
          <div className="flex items-center gap-2">
             <div className="w-8 h-8 bg-amber-500 rounded-lg flex items-center justify-center font-brand text-lg text-slate-950">{settings.shopName.charAt(0)}</div>
             <span className="font-bold text-slate-900 dark:text-white truncate max-w-[120px]">{settings.shopName}</span>
          </div>
          <div className="flex gap-2">
            <button onClick={() => setIsDarkMode(!isDarkMode)} className="p-2 text-slate-400 bg-slate-50 dark:bg-slate-800 rounded-lg">
              {isDarkMode ? '🌞' : '🌙'}
            </button>
            <button onClick={() => setIsSidebarOpen(true)} className="p-2 text-slate-900 dark:text-white bg-amber-500 rounded-lg">
              <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M4 6h16M4 12h16m-7 6h7"/></svg>
            </button>
          </div>
        </header>

        {/* Desktop Header */}
        <header className="hidden md:flex justify-between items-center px-8 py-6 no-print">
            <h1 className="text-2xl font-black text-slate-900 dark:text-white font-brand">{tView(currentView, sessionLanguage)}</h1>
            <div className="flex items-center gap-4">
               <button onClick={() => setIsDarkMode(!isDarkMode)} className="p-2.5 bg-white dark:bg-slate-900 text-slate-400 rounded-xl border border-slate-200 dark:border-slate-800">
                 {isDarkMode ? '🌞' : '🌙'}
               </button>
               <div className="flex items-center gap-3 bg-white dark:bg-slate-900 p-1.5 pr-4 rounded-full border border-slate-100 dark:border-slate-800 shadow-sm">
                  <div className="w-8 h-8 rounded-full bg-amber-500 flex items-center justify-center font-black text-slate-950 text-xs">{currentUser.name.charAt(0)}</div>
                  <div className="flex flex-col"><span className="text-xs font-bold dark:text-white">{currentUser.name}</span><span className="text-[9px] uppercase font-black text-slate-400">{currentUser.role}</span></div>
               </div>
               <button onClick={handleLogout} className="p-2.5 bg-slate-100 dark:bg-slate-800 text-slate-500 rounded-xl">🚪</button>
            </div>
        </header>

        <main className="flex-1 overflow-y-auto p-4 md:p-8 relative scrollbar-hide">
          <AnimatePresence mode='wait'>
            <motion.div key={currentView} initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: -10 }} className="h-full">
              <ErrorBoundary key={currentView}>
                {renderView(currentView, { 
                  sales, expenses, products, services, staff, customers, settings, 
                  currentUser, sessionLanguage, isDarkMode, 
                  // DB Handlers passed to children
                  onUpdateServices: handleUpdateServices,
                  onUpdateProducts: handleUpdateProducts,
                  onUpdateStaff: handleUpdateStaff,
                  onUpdateCustomers: handleUpdateCustomers,
                  onUpdateSettings: handleUpdateSettings,
                  onCompleteSale: handleCompleteSale,
                  onAddExpense: handleAddExpense,
                  onDeleteExpense: handleDeleteExpense,
                  onLogout: handleLogout,
                  onPurgeSales: handlePurgeSales,
                  onDeleteSales: handleDeleteSales,

                  setCurrentView, handleLogout
                })}
              </ErrorBoundary>
            </motion.div>
          </AnimatePresence>
        </main>
      </div>

      <InstallBanner 
        deferredPrompt={deferredPrompt} 
        onClose={() => setDeferredPrompt(null)} 
      />
    </div>
  );
};

const tView = (v: View, l: Language) => {
  const map: any = { 
    en: { [View.DASHBOARD]: 'Dashboard', [View.POS]: 'Terminal', [View.FINANCE]: 'Finances', [View.INVENTORY]: 'Catalog', [View.STAFF]: 'Staff', [View.CUSTOMERS]: 'Clients', [View.SETTINGS]: 'Settings' },
    ur: { [View.DASHBOARD]: 'ڈیش بورڈ', [View.POS]: 'ٹرمینل', [View.FINANCE]: 'مالیات', [View.INVENTORY]: 'کیٹلاگ', [View.STAFF]: 'عملہ', [View.CUSTOMERS]: 'صارفین', [View.SETTINGS]: 'ترتیبات' }
  };
  return map[l]?.[v] || map['en'][v];
};

const renderView = (v: View, props: any) => {
  const { sales, expenses, products, services, staff, customers, settings, currentUser, sessionLanguage, onUpdateServices, onUpdateProducts, onUpdateStaff, onUpdateCustomers, onUpdateSettings, onCompleteSale, onAddExpense, onDeleteExpense, onLogout, onPurgeSales, onDeleteSales, setCurrentView } = props;
  switch (v) {
    case View.DASHBOARD: return <Dashboard sales={sales} expenses={expenses} products={products} currency={settings.currency} language={sessionLanguage} onNavigate={setCurrentView} />;
    case View.POS: return <POS services={services} products={products} staff={staff} customers={customers} settings={settings} currentUser={currentUser} onCompleteSale={onCompleteSale} onAddCustomer={c => onUpdateCustomers([...customers, c])} />;
    case View.FINANCE: return <Finance sales={sales} expenses={expenses} staffList={staff} customers={customers} currency={settings.currency} language={sessionLanguage} currentUser={currentUser} onAddExpense={onAddExpense} onDeleteExpense={onDeleteExpense} onDeleteSales={onDeleteSales} settings={settings} />;
    case View.CUSTOMERS: return <Customers customers={customers} sales={sales} onUpdateCustomers={onUpdateCustomers} currency={settings.currency} language={sessionLanguage} />;
    case View.INVENTORY: return <Inventory services={services} products={products} settings={{...settings, language: sessionLanguage}} onUpdateServices={onUpdateServices} onUpdateProducts={onUpdateProducts} />;
    case View.STAFF: return <StaffManagement staffList={staff} onUpdateStaff={onUpdateStaff} currentUser={currentUser} language={sessionLanguage} />;
    case View.SETTINGS: return <Settings settings={{...settings, language: sessionLanguage}} onUpdateSettings={onUpdateSettings} currentUser={currentUser} onLogout={onLogout} onPurgeSales={onPurgeSales} />;
    default: return null;
  }
};

export default App;

import React, { useState, useEffect, ReactNode, ErrorInfo, Component } from 'react';
import Sidebar from './components/Sidebar';
import Dashboard from './components/Dashboard';
import POS from './components/POS';
import Finance from './components/Finance';
import Customers from './components/Customers';
import Settings from './components/Settings';
import Inventory from './components/Inventory';
import StaffManagement from './components/StaffManagement';
import Login from './components/Login';
import InstallBanner from './components/InstallBanner';
import { View, Sale, Expense, Service, Product, Staff, Customer, ShopSettings, Language } from './types';
import { INITIAL_SERVICES, INITIAL_PRODUCTS, INITIAL_STAFF, INITIAL_EXPENSES, INITIAL_CUSTOMERS, DEFAULT_SETTINGS } from './constants';
import { motion, AnimatePresence } from 'framer-motion';
import { supabase } from './supabaseClient';

interface ErrorBoundaryProps {
  children: ReactNode;
}

interface ErrorBoundaryState {
  hasError: boolean;
}

// Error Boundary to prevent white screens
class ErrorBoundary extends Component<ErrorBoundaryProps, ErrorBoundaryState> {
  constructor(props: ErrorBoundaryProps) {
    super(props);
    this.state = { hasError: false };
  }

  static getDerivedStateFromError(error: Error): ErrorBoundaryState {
    return { hasError: true };
  }

  componentDidCatch(error: Error, errorInfo: ErrorInfo) {
    console.error("Application Error:", error, errorInfo);
  }

  render() {
    if (this.state.hasError) {
      return (
        <div className="h-full w-full flex flex-col items-center justify-center p-8 text-center">
          <div className="w-16 h-16 bg-rose-100 dark:bg-rose-900/20 text-rose-500 rounded-full flex items-center justify-center text-3xl mb-4">
            ⚠️
          </div>
          <h2 className="text-xl font-black text-slate-800 dark:text-white mb-2">Something went wrong</h2>
          <p className="text-slate-500 dark:text-slate-400 mb-6 text-sm">We encountered an unexpected error loading this section.</p>
          <button 
            onClick={() => {
              this.setState({ hasError: false });
              window.location.reload();
            }}
            className="bg-slate-900 dark:bg-white text-white dark:text-slate-900 px-6 py-3 rounded-xl font-bold uppercase tracking-wider text-xs shadow-lg active:scale-95 transition-transform"
          >
            Reload App
          </button>
        </div>
      );
    }

    return this.props.children;
  }
}

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<Staff | null>(() => {
    const saved = localStorage.getItem('trimtime_session');
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        if (parsed.user && parsed.expiry && Date.now() < parsed.expiry) return parsed.user;
      } catch (e) {}
    }
    return null;
  });

  const [currentView, setCurrentView] = useState<View>(
    currentUser?.role === 'employee' ? View.POS : View.DASHBOARD
  );

  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [loading, setLoading] = useState(true);
  const [services, setServices] = useState<Service[]>([]);
  const [products, setProducts] = useState<Product[]>([]);
  const [staff, setStaff] = useState<Staff[]>([]);
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [sales, setSales] = useState<Sale[]>([]);
  const [settings, setSettings] = useState<ShopSettings>(DEFAULT_SETTINGS);
  const [sessionLanguage, setSessionLanguage] = useState<Language>(() => (localStorage.getItem('trimtime_lang') as Language) || 'en');
  const [isDarkMode, setIsDarkMode] = useState(() => localStorage.getItem('trimtime_theme') === 'dark');

  // PWA Install States
  const [deferredPrompt, setDeferredPrompt] = useState<any>(null);

  useEffect(() => {
    const handleBeforeInstallPrompt = (e: Event) => {
      e.preventDefault();
      setDeferredPrompt(e);
    };
    window.addEventListener('beforeinstallprompt', handleBeforeInstallPrompt);
    return () => window.removeEventListener('beforeinstallprompt', handleBeforeInstallPrompt);
  }, []);

  useEffect(() => {
    const fetchData = async () => {
      try {
        const [sv, pr, st, ex, cu, sa, se] = await Promise.all([
          supabase.from('services').select('*'),
          supabase.from('products').select('*'),
          supabase.from('staff').select('*'),
          supabase.from('expenses').select('*'),
          supabase.from('customers').select('*'),
          supabase.from('sales').select('*'),
          supabase.from('settings').select('*').single()
        ]);

        if (sv.data && sv.data.length > 0) setServices(sv.data);
        else if (sv.error) setServices(INITIAL_SERVICES); 
        else setServices([]); // Empty DB = Empty List

        if (pr.data && pr.data.length > 0) setProducts(pr.data.map((p: any) => ({ ...p, lowStockThreshold: p.low_stock_threshold })));
        else if (pr.error) setProducts(INITIAL_PRODUCTS);
        else setProducts([]);

        if (st.data && st.data.length > 0) setStaff(st.data);
        else if (st.error) setStaff(INITIAL_STAFF);
        // Note: For staff, we might want to keep at least one admin if empty, but assuming DB handles it.
        else if (st.data && st.data.length === 0) setStaff(INITIAL_STAFF); // Fallback for staff to ensure login

        if (ex.data && ex.data.length > 0) setExpenses(ex.data.map((e: any) => ({ ...e, receiptImage: e.receipt_image })));
        else if (ex.error) setExpenses(INITIAL_EXPENSES);
        else setExpenses([]); // Don't show demo expenses if DB is connected but empty

        if (cu.data && cu.data.length > 0) setCustomers(cu.data.map((c: any) => ({ ...c, createdAt: c.created_at })));
        else if (cu.error) setCustomers(INITIAL_CUSTOMERS);
        else setCustomers([]);

        if (sa.data) {
          setSales(sa.data.map((s: any) => ({ 
            ...s, 
            // Ensure items is always an array, even if DB has null/invalid json
            items: (typeof s.items === 'string' ? JSON.parse(s.items) : s.items) || [],
            staffName: s.professional_name,
            customerName: s.customer_name
          })));
        }

        if (se.data?.data) setSettings({ ...DEFAULT_SETTINGS, ...se.data.data });

        if (sv.error) console.error("Services Fetch Error:", sv.error);
        if (pr.error) console.error("Products Fetch Error:", pr.error);
      } catch (e) { console.error("Error loading data:", e); }
      finally { setLoading(false); }
    };
    fetchData();
  }, []);

  useEffect(() => {
    document.documentElement.classList.toggle('dark', isDarkMode);
    localStorage.setItem('trimtime_theme', isDarkMode ? 'dark' : 'light');
  }, [isDarkMode]);

  useEffect(() => {
    document.documentElement.lang = sessionLanguage;
    document.dir = ['ur', 'fa'].includes(sessionLanguage) ? 'rtl' : 'ltr';
    localStorage.setItem('trimtime_lang', sessionLanguage);
  }, [sessionLanguage]);

  // --- DATA PERSISTENCE HANDLERS ---

  const handleUpdateServices = async (updated: Service[]) => {
    const currentIds = new Set<string>(services.map(i => i.id));
    const newIds = new Set<string>(updated.map(i => i.id));
    const toDelete: string[] = Array.from(currentIds).filter(id => !newIds.has(id));

    setServices(updated);

    try {
      if (toDelete.length) await supabase.from('services').delete().in('id', toDelete);
      if (updated.length) {
          const { error } = await supabase.from('services').upsert(updated);
          if (error) throw error;
      }
    } catch (error) { 
        const err = error as any;
        console.error("DB Sync Error (Services):", err);
        alert("Failed to save services. Check database connection.");
    }
  };

  const handleUpdateProducts = async (updated: Product[]) => {
    const currentIds = new Set<string>(products.map(i => i.id));
    const newIds = new Set<string>(updated.map(i => i.id));
    const toDelete: string[] = Array.from(currentIds).filter(id => !newIds.has(id));

    setProducts(updated);

    // Attempt to save full product details including new fields
    const dbRowsFull = updated.map(p => ({
        id: p.id,
        name: p.name,
        price: p.price,
        cost: p.cost,
        stock: p.stock,
        barcode: p.barcode || null,
        low_stock_threshold: p.lowStockThreshold || 15
    }));

    // Fallback if DB schema is outdated (missing barcode/low_stock_threshold columns)
    const dbRowsSafe = updated.map(p => ({
        id: p.id,
        name: p.name,
        price: p.price,
        // Exclude cost from safe fallback as it might be missing in very old schemas
        stock: p.stock
    }));

    try {
      if (toDelete.length) await supabase.from('products').delete().in('id', toDelete);

      if (dbRowsFull.length) {
          const { error } = await supabase.from('products').upsert(dbRowsFull);
          if (error) {
            // Check for schema mismatch errors
            if (error.code === 'PGRST204' || error.message.includes('column') || error.message.includes('does not exist')) {
                console.warn("DB Schema mismatch detected. Retrying with core fields only...");

                // Alert the user that advanced fields aren't saving
                alert("NOTICE: Your database schema appears outdated. 'Barcode', 'Cost', and 'Low Stock' fields are saved locally but could not be synced to the cloud. Please update your Supabase 'products' table.");

                const { error: retryError } = await supabase.from('products').upsert(dbRowsSafe);
                if (retryError) throw retryError;
            } else {
                throw error;
            }
          }
      }
    } catch (error) { 
        const err = error as any;
        console.error("DB Sync Error (Products):", err); 
        alert(`Failed to save products: ${err.message}`);
    }
  };

  const handleUpdateStaff = async (updated: Staff[]) => {
    const currentIds = new Set<string>(staff.map(i => i.id));
    const newIds = new Set<string>(updated.map(i => i.id));
    const toDelete: string[] = Array.from(currentIds).filter(id => !newIds.has(id));

    setStaff(updated);

    try {
      if (toDelete.length) await supabase.from('staff').delete().in('id', toDelete);
      if (updated.length) {
          const { error } = await supabase.from('staff').upsert(updated);
          if (error) throw error;
      }
    } catch (error) { 
        const err = error as any;
        console.error("DB Sync Error (Staff):", err);
        alert("Failed to save staff. Check database connection.");
    }
  };

  const handleUpdateCustomers = async (updated: Customer[]) => {
    const currentIds = new Set<string>(customers.map(i => i.id));
    const newIds = new Set<string>(updated.map(i => i.id));
    const toDelete: string[] = Array.from(currentIds).filter(id => !newIds.has(id));

    setCustomers(updated);

    const dbRows = updated.map(c => ({
        id: c.id,
        name: c.name,
        phone: c.phone,
        email: c.email,
        notes: c.notes,
        created_at: c.createdAt
    }));

    try {
      if (toDelete.length) await supabase.from('customers').delete().in('id', toDelete);
      if (dbRows.length) {
          const { error } = await supabase.from('customers').upsert(dbRows);
          if (error) throw error;
      }
    } catch (error) { 
        const err = error as any;
        console.error("DB Sync Error (Customers):", err);
        alert("Failed to save customers. Check database connection.");
    }
  };

  const handleUpdateSettings = async (updated: ShopSettings) => {
    setSettings(updated);
    try {
      const { error } = await supabase.from('settings').upsert({ id: 1, data: updated });
      if (error) throw error;
    } catch (error) { 
        const err = error as any;
        console.error("DB Sync Error (Settings):", err);
        alert("Failed to save settings.");
    }
  };

  const handleCompleteSale = async (sale: Sale) => {
    setSales(prev => [...prev, sale]);
    try {
      const dbSale = {
          id: sale.id,
          timestamp: sale.timestamp,
          items: sale.items, 
          staff_id: sale.staffId,
          customer_id: sale.customerId,
          total: sale.total,
          tax: sale.tax,
          discount: sale.discount,
          discount_code: sale.discountCode,
          payment_method: sale.paymentMethod,
          tax_type: sale.taxType,
          customer_name: sale.customerName,
          professional_name: sale.staffName
      };
      const { error } = await supabase.from('sales').insert(dbSale);
      if (error) throw error;

      let productsUpdated = false;
      const newProducts = [...products];
      sale.items.forEach(item => {
          if (item.type === 'product') {
              const idx = newProducts.findIndex(p => p.id === item.id);
              if (idx > -1) {
                  newProducts[idx] = { ...newProducts[idx], stock: newProducts[idx].stock - item.quantity };
                  productsUpdated = true;
              }
          }
      });
      if (productsUpdated) handleUpdateProducts(newProducts);
    } catch (error) { 
        const err = error as any;
        console.error("DB Sync Error (Sale):", err);
        alert("Sale saved locally but failed to sync to DB.");
    }
  };

  const handleDeleteSales = async (ids: string[]) => {
    setSales(prev => prev.filter(s => !ids.includes(s.id)));
    try {
      const { error } = await supabase.from('sales').delete().in('id', ids);
      if (error) throw error;
    } catch (error) {
       const err = error as any;
       console.error("DB Sync Error (Delete Sales):", err);
       alert("Failed to delete sales from DB.");
    }
  };

  const handleAddExpense = async (expense: Expense) => {
      setExpenses(prev => [...prev, expense]);
      const dbExpense = {
          id: expense.id,
          date: expense.date,
          category: expense.category,
          amount: expense.amount,
          description: expense.description || '', // Ensure fallback
          receipt_image: expense.receiptImage || null // Ensure null if undefined
      };
      try {
        const { error } = await supabase.from('expenses').insert(dbExpense);
        if (error) throw error;
      } catch (error) { 
          const err = error as any;
          console.error("DB Sync Error (Expense):", err);
          alert("Failed to save expense to DB: " + err.message);
      }
  };

  const handleDeleteExpense = async (id: string) => {
      setExpenses(prev => prev.filter(e => e.id !== id));
      try {
        const { error } = await supabase.from('expenses').delete().eq('id', id);
        if (error) throw error;
      } catch (error) { 
          const err = error as any;
          console.error("DB Sync Error (Delete Expense):", err);
          alert("Failed to delete expense from DB: " + err.message);
      }
  };

  const handlePurgeSales = async () => {
    setSales([]);
    try {
       const { error } = await supabase.from('sales').delete().neq('id', '0'); 
       if (error) throw error;
    } catch (error) { 
        const err = error as any;
        console.error("DB Sync Error (Purge Sales):", err);
        alert("Failed to purge sales from DB.");
    }
  };

  const handleLogin = (user: Staff, remember: boolean) => {
    const expiry = Date.now() + (remember ? 30 : 1) * 24 * 60 * 60 * 1000;
    localStorage.setItem('trimtime_session', JSON.stringify({ user, expiry }));
    setCurrentUser(user);
    setCurrentView(user.role === 'employee' ? View.POS : View.DASHBOARD);
  };

  const handleLogout = () => {
    localStorage.removeItem('trimtime_session');
    setCurrentUser(null);
  };

  if (loading) return <div className="h-screen w-full flex items-center justify-center bg-slate-950"><div className="animate-spin rounded-full h-12 w-12 border-t-2 border-amber-500"></div></div>;
  if (!currentUser) return <Login onLogin={handleLogin} staffList={staff} shopName={settings.shopName} />;

  return (
    <div className="flex h-screen bg-slate-50 dark:bg-slate-950 overflow-hidden font-sans transition-colors duration-300">
      <Sidebar 
        currentView={currentView} onViewChange={setCurrentView} 
        shopName={settings.shopName} userRole={currentUser.role} 
        isOpen={isSidebarOpen} onClose={() => setIsSidebarOpen(false)}
        language={sessionLanguage} onLanguageChange={setSessionLanguage}
      />

      <div className="flex-1 flex flex-col min-w-0 md:pl-64 overflow-hidden relative">
        {/* Responsive Header */}
        <header className="flex md:hidden items-center justify-between p-4 bg-white dark:bg-slate-900 border-b border-slate-100 dark:border-slate-800 z-50 sticky top-0 shadow-sm">
          <div className="flex items-center gap-2">
             <div className="w-8 h-8 bg-amber-500 rounded-lg flex items-center justify-center font-brand text-lg text-slate-950">{settings.shopName.charAt(0)}</div>
             <span className="font-bold text-slate-900 dark:text-white truncate max-w-[120px]">{settings.shopName}</span>
          </div>
          <div className="flex gap-2">
            <button onClick={() => setIsDarkMode(!isDarkMode)} className="p-2 text-slate-400 bg-slate-50 dark:bg-slate-800 rounded-lg">
              {isDarkMode ? '🌞' : '🌙'}
            </button>
            <button onClick={() => setIsSidebarOpen(true)} className="p-2 text-slate-900 dark:text-white bg-amber-500 rounded-lg">
              <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M4 6h16M4 12h16m-7 6h7"/></svg>
            </button>
          </div>
        </header>

        {/* Desktop Header */}
        <header className="hidden md:flex justify-between items-center px-8 py-6 no-print">
            <h1 className="text-2xl font-black text-slate-900 dark:text-white font-brand">{tView(currentView, sessionLanguage)}</h1>
            <div className="flex items-center gap-4">
               <button onClick={() => setIsDarkMode(!isDarkMode)} className="p-2.5 bg-white dark:bg-slate-900 text-slate-400 rounded-xl border border-slate-200 dark:border-slate-800">
                 {isDarkMode ? '🌞' : '🌙'}
               </button>
               <div className="flex items-center gap-3 bg-white dark:bg-slate-900 p-1.5 pr-4 rounded-full border border-slate-100 dark:border-slate-800 shadow-sm">
                  <div className="w-8 h-8 rounded-full bg-amber-500 flex items-center justify-center font-black text-slate-950 text-xs">{currentUser.name.charAt(0)}</div>
                  <div className="flex flex-col"><span className="text-xs font-bold dark:text-white">{currentUser.name}</span><span className="text-[9px] uppercase font-black text-slate-400">{currentUser.role}</span></div>
               </div>
               <button onClick={handleLogout} className="p-2.5 bg-slate-100 dark:bg-slate-800 text-slate-500 rounded-xl">🚪</button>
            </div>
        </header>

        <main className="flex-1 overflow-y-auto p-4 md:p-8 relative scrollbar-hide">
          <AnimatePresence mode='wait'>
            <motion.div key={currentView} initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: -10 }} className="h-full">
              <ErrorBoundary key={currentView}>
                {renderView(currentView, { 
                  sales, expenses, products, services, staff, customers, settings, 
                  currentUser, sessionLanguage, isDarkMode, 
                  // DB Handlers passed to children
                  onUpdateServices: handleUpdateServices,
                  onUpdateProducts: handleUpdateProducts,
                  onUpdateStaff: handleUpdateStaff,
                  onUpdateCustomers: handleUpdateCustomers,
                  onUpdateSettings: handleUpdateSettings,
                  onCompleteSale: handleCompleteSale,
                  onAddExpense: handleAddExpense,
                  onDeleteExpense: handleDeleteExpense,
                  onLogout: handleLogout,
                  onPurgeSales: handlePurgeSales,
                  onDeleteSales: handleDeleteSales,

                  setCurrentView, handleLogout
                })}
              </ErrorBoundary>
            </motion.div>
          </AnimatePresence>
        </main>
      </div>

      <InstallBanner 
        deferredPrompt={deferredPrompt} 
        onClose={() => setDeferredPrompt(null)} 
      />
    </div>
  );
};

const tView = (v: View, l: Language) => {
  const map: any = { 
    en: { [View.DASHBOARD]: 'Dashboard', [View.POS]: 'Terminal', [View.FINANCE]: 'Finances', [View.INVENTORY]: 'Catalog', [View.STAFF]: 'Staff', [View.CUSTOMERS]: 'Clients', [View.SETTINGS]: 'Settings' },
    ur: { [View.DASHBOARD]: 'ڈیش بورڈ', [View.POS]: 'ٹرمینل', [View.FINANCE]: 'مالیات', [View.INVENTORY]: 'کیٹلاگ', [View.STAFF]: 'عملہ', [View.CUSTOMERS]: 'صارفین', [View.SETTINGS]: 'ترتیبات' }
  };
  return map[l]?.[v] || map['en'][v];
};

const renderView = (v: View, props: any) => {
  const { sales, expenses, products, services, staff, customers, settings, currentUser, sessionLanguage, onUpdateServices, onUpdateProducts, onUpdateStaff, onUpdateCustomers, onUpdateSettings, onCompleteSale, onAddExpense, onDeleteExpense, onLogout, onPurgeSales, onDeleteSales, setCurrentView } = props;
  switch (v) {
    case View.DASHBOARD: return <Dashboard sales={sales} expenses={expenses} products={products} currency={settings.currency} language={sessionLanguage} onNavigate={setCurrentView} />;
    case View.POS: return <POS services={services} products={products} staff={staff} customers={customers} settings={settings} currentUser={currentUser} onCompleteSale={onCompleteSale} onAddCustomer={c => onUpdateCustomers([...customers, c])} />;
    case View.FINANCE: return <Finance sales={sales} expenses={expenses} staffList={staff} customers={customers} currency={settings.currency} language={sessionLanguage} currentUser={currentUser} onAddExpense={onAddExpense} onDeleteExpense={onDeleteExpense} onDeleteSales={onDeleteSales} settings={settings} />;
    case View.CUSTOMERS: return <Customers customers={customers} sales={sales} onUpdateCustomers={onUpdateCustomers} currency={settings.currency} language={sessionLanguage} />;
    case View.INVENTORY: return <Inventory services={services} products={products} settings={{...settings, language: sessionLanguage}} onUpdateServices={onUpdateServices} onUpdateProducts={onUpdateProducts} />;
    case View.STAFF: return <StaffManagement staffList={staff} onUpdateStaff={onUpdateStaff} currentUser={currentUser} language={sessionLanguage} />;
    case View.SETTINGS: return <Settings settings={{...settings, language: sessionLanguage}} onUpdateSettings={onUpdateSettings} currentUser={currentUser} onLogout={onLogout} onPurgeSales={onPurgeSales} />;
    default: return null;
  }
};

export default App;

import React, { useState, useRef, useEffect } from 'react';
import { Service, Product, ShopSettings } from '../types';
import { TRANSLATIONS } from '../constants';
import { motion, AnimatePresence } from 'framer-motion';
import { Html5Qrcode, Html5QrcodeSupportedFormats } from 'html5-qrcode';

interface InventoryProps {
  services: Service[];
  products: Product[];
  settings: ShopSettings;
  onUpdateServices: (services: Service[]) => void;
  onUpdateProducts: (products: Product[]) => void;
}

const Inventory: React.FC<InventoryProps> = ({ services, products, settings, onUpdateServices, onUpdateProducts }) => {
  const [activeTab, setActiveTab] = useState<'services' | 'products'>('services');
  const [isEditing, setIsEditing] = useState<any>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [isScanning, setIsScanning] = useState(false);
  const html5QrCodeRef = useRef<Html5Qrcode | null>(null);
  const barcodeInputRef = useRef<HTMLInputElement>(null);
  const isScannerActiveRef = useRef(false);

  const t = TRANSLATIONS[settings.language];

  useEffect(() => {
    let isMounted = true;

    const cleanupScanner = async () => {
        if (!html5QrCodeRef.current) return;

        try {
            if (isScannerActiveRef.current) {
                await html5QrCodeRef.current.stop();
            }
        } catch (error) {
            console.warn("Scanner stop warning:", error);
        } finally {
            isScannerActiveRef.current = false;
            try {
                await html5QrCodeRef.current.clear();
            } catch (e) {
                // Ignore clear errors
            }
            html5QrCodeRef.current = null;
        }
    };

    if (isScanning) {
        const startScanner = async () => {
            // Give modal animation time to finish and DOM to render
            await new Promise(resolve => setTimeout(resolve, 300));

            if (!isMounted || !isScanning) return;

            const elementId = "reader-inventory";
            if (!document.getElementById(elementId)) return;

            // Ensure previous instance is cleaned up
            await cleanupScanner();

            try {
                const html5QrCode = new Html5Qrcode(elementId, {
                  formatsToSupport: [
                    Html5QrcodeSupportedFormats.EAN_13,
                    Html5QrcodeSupportedFormats.EAN_8,
                    Html5QrcodeSupportedFormats.CODE_128,
                    Html5QrcodeSupportedFormats.UPC_A,
                    Html5QrcodeSupportedFormats.UPC_E
                  ],
                  verbose: false
                });

                html5QrCodeRef.current = html5QrCode;

                await html5QrCode.start(
                    { facingMode: "environment" }, 
                    { 
                        fps: 10, 
                        qrbox: (viewfinderWidth, viewfinderHeight) => {
                            const width = Math.floor(viewfinderWidth * 0.85);
                            const height = Math.floor(viewfinderHeight * 0.35);
                            return { width, height };
                        },
                        aspectRatio: 1.777778,
                    }, 
                    (decodedText) => {
                        if (isMounted) {
                            if (barcodeInputRef.current) barcodeInputRef.current.value = decodedText;
                            if ("vibrate" in navigator) navigator.vibrate(100);
                            setIsScanning(false); // Clean exit
                        }
                    },
                    () => {}
                );

                if (isMounted) {
                    isScannerActiveRef.current = true;
                } else {
                    // Component unmounted while starting
                    await cleanupScanner();
                }
            } catch (err: any) {
                 console.error("Inventory scanner failed", err);
                 if (isMounted) {
                     setIsScanning(false);
                     if (err.name === 'NotAllowedError' || err.message?.includes('Permission')) {
                         alert("Camera access denied. Please enable camera permissions in your browser settings to scan barcodes.");
                     } else {
                         alert("Unable to start scanner. Please try again or type manually.");
                     }
                 }
                 await cleanupScanner();
            }
        };
        startScanner();
    }

    return () => {
        isMounted = false;
        // cleanupScanner is async, but we can't await in unmount. 
        // We trigger it and let it handle the promise internally.
        if (html5QrCodeRef.current) {
            const scanner = html5QrCodeRef.current;
            const wasActive = isScannerActiveRef.current;
            const stopPromise = wasActive ? scanner.stop() : Promise.resolve();

            stopPromise
                .catch(() => {})
                .finally(() => {
                    try { scanner.clear(); } catch(e) {}
                    isScannerActiveRef.current = false;
                });
        }
    };
  }, [isScanning]);

  const filteredServices = services.filter(s => s.name.toLowerCase().includes(searchTerm.toLowerCase()) || s.category.toLowerCase().includes(searchTerm.toLowerCase()));
  const filteredProducts = products.filter(p => p.name.toLowerCase().includes(searchTerm.toLowerCase()) || (p.barcode && p.barcode.includes(searchTerm)));

  const deleteItem = (id: string, type: 'service' | 'product') => {
    if (!confirm('Permanently delete this entry?')) return;
    if (type === 'service') onUpdateServices(services.filter(s => s.id !== id));
    else onUpdateProducts(products.filter(p => p.id !== id));
  };

  const saveItem = (e: React.FormEvent) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget as HTMLFormElement);
    const itemData = Object.fromEntries(formData.entries());

    if (activeTab === 'services') {
      const newService: Service = {
        id: isEditing?.id || Math.random().toString(36).substr(2, 9).toUpperCase(),
        name: itemData.name as string,
        price: parseFloat(itemData.price as string) || 0,
        duration: parseInt(itemData.duration as string) || 30,
        category: itemData.category as string,
      };
      if (isEditing.id) onUpdateServices(services.map(s => s.id === isEditing.id ? newService : s));
      else onUpdateServices([...services, newService]);
    } else {
      const newProduct: Product = {
        id: isEditing?.id || Math.random().toString(36).substr(2, 9).toUpperCase(),
        name: itemData.name as string,
        price: parseFloat(itemData.price as string) || 0,
        cost: parseFloat(itemData.cost as string) || 0,
        stock: parseInt(itemData.stock as string) || 0,
        barcode: (itemData.barcode as string) || undefined,
        lowStockThreshold: parseInt(itemData.lowStockThreshold as string) || 15
      };
      if (isEditing.id) onUpdateProducts(products.map(p => p.id === isEditing.id ? newProduct : p));
      else onUpdateProducts([...products, newProduct]);
    }
    setIsEditing(null);
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
        <div>
          <h2 className="text-2xl md:text-3xl font-bold text-slate-800 dark:text-white font-brand">{t.shopCatalog}</h2>
          <p className="text-slate-500 dark:text-slate-400 text-sm">{t.updatePrices}</p>
        </div>
        <button onClick={() => setIsEditing({})} className="bg-slate-950 dark:bg-slate-800 text-white px-6 py-3 rounded-xl font-black flex items-center gap-2 hover:bg-slate-800 transition-all shadow-lg text-sm w-full sm:w-auto justify-center">
          <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M12 6v6m0 0v6m0-6h6m-6 0H6"/></svg>
          {activeTab === 'services' ? t.newService : t.newProduct}
        </button>
      </div>
      <div className="relative">
        <svg className="w-5 h-5 absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 dark:text-slate-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z"/></svg>
        <input type="text" placeholder={t.searchCatalog} value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} className="w-full bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-2xl py-3.5 pl-12 pr-6 outline-none focus:ring-4 focus:ring-amber-500/10 shadow-sm text-sm dark:text-slate-200" />
      </div>
      <div className="flex bg-white dark:bg-slate-900 p-1 rounded-xl shadow-sm border border-slate-100 dark:border-slate-800 self-start w-full sm:w-auto">
        <button onClick={() => setActiveTab('services')} className={`flex-1 sm:px-8 py-2.5 rounded-lg font-bold transition-all text-xs md:text-sm ${activeTab === 'services' ? 'bg-amber-500 text-slate-950 shadow-sm' : 'text-slate-400 dark:text-slate-500 hover:text-slate-600'}`}>{t.services}</button>
        <button onClick={() => setActiveTab('products')} className={`flex-1 sm:px-8 py-2.5 rounded-lg font-bold transition-all text-xs md:text-sm ${activeTab === 'products' ? 'bg-amber-500 text-slate-950 shadow-sm' : 'text-slate-400 dark:text-slate-500 hover:text-slate-600'}`}>{t.inventory}</button>
      </div>
      <div className="md:hidden space-y-4">
        {(activeTab === 'services' ? filteredServices : filteredProducts).map((item: any) => (
           <div key={item.id} className="bg-white dark:bg-slate-900 p-5 rounded-2xl border border-slate-100 dark:border-slate-800 shadow-sm">
              <div className="flex justify-between items-start mb-2">
                 <h4 className="font-bold text-slate-800 dark:text-slate-200">{item.name}</h4>
                 <span className="text-xl font-black text-amber-500">{settings.currency}{item.price}</span>
