    const client = sale.customerName || customers.find(c => c.id === sale.customerId)?.name || 'Guest Walk-in';
    doc.setFontSize(14).text(settings.shopName, 40, 15, { align: 'center' });
    doc.setFontSize(8).text(`Date: ${new Date(sale.timestamp).toLocaleString()}`, 10, 25);
    doc.text(`Staff: ${barber}`, 10, 30);
    doc.text(`Client: ${client}`, 10, 35);
    let y = 45;
    sale.items.forEach(item => {
      doc.text(`${item.quantity}x ${item.name}`, 10, y);
      doc.text(`${settings.currency}${(item.price * item.quantity).toFixed(2)}`, 70, y, { align: 'right' });
      y += 5;
