                   </div>
                )}

                <button type="submit" className="w-full py-4 bg-amber-500 text-slate-950 rounded-2xl font-black text-base shadow-xl mt-4">Save Changes</button>
              </form>
            </motion.div>
          </div>
        )}
      </AnimatePresence>
    </div>
  );
};

