import Settings from './components/Settings';
import Inventory from './components/Inventory';
import StaffManagement from './components/StaffManagement';
import Login from './components/Login';
import InstallBanner from './components/InstallBanner';
import { View, Sale, Expense, Service, Product, Staff, Customer, ShopSettings, Language } from './types';
import { INITIAL_SERVICES, INITIAL_PRODUCTS, INITIAL_STAFF, INITIAL_EXPENSES, INITIAL_CUSTOMERS, DEFAULT_SETTINGS } from './constants';
import { motion, AnimatePresence } from 'framer-motion';
import { supabase } from './supabaseClient';

interface ErrorBoundaryProps {
  children: ReactNode;
}

interface ErrorBoundaryState {
  hasError: boolean;
}

// Error Boundary to prevent white screens
class ErrorBoundary extends React.Component<ErrorBoundaryProps, ErrorBoundaryState> {
  constructor(props: ErrorBoundaryProps) {
    super(props);
    this.state = { hasError: false };
  }

  static getDerivedStateFromError(error: Error): ErrorBoundaryState {
    return { hasError: true };
  }

  componentDidCatch(error: Error, errorInfo: ErrorInfo) {
    console.error("Application Error:", error, errorInfo);
  }

  render() {
    if (this.state.hasError) {
      return (
        <div className="h-full w-full flex flex-col items-center justify-center p-8 text-center">
          <div className="w-16 h-16 bg-rose-100 dark:bg-rose-900/20 text-rose-500 rounded-full flex items-center justify-center text-3xl mb-4">
            ⚠️
          </div>
          <h2 className="text-xl font-black text-slate-800 dark:text-white mb-2">Something went wrong</h2>
          <p className="text-slate-500 dark:text-slate-400 mb-6 text-sm">We encountered an unexpected error loading this section.</p>
          <button 
            onClick={() => {
              this.setState({ hasError: false });
              window.location.reload();
            }}
            className="bg-slate-900 dark:bg-white text-white dark:text-slate-900 px-6 py-3 rounded-xl font-bold uppercase tracking-wider text-xs shadow-lg active:scale-95 transition-transform"
          >
            Reload App
          </button>
        </div>
      );
    }

    return this.props.children;
  }
}

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<Staff | null>(() => {
    const saved = localStorage.getItem('trimtime_session');
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        if (parsed.user && parsed.expiry && Date.now() < parsed.expiry) return parsed.user;
      } catch (e) {}
    }
    return null;
  });

  const [currentView, setCurrentView] = useState<View>(
    currentUser?.role === 'employee' ? View.POS : View.DASHBOARD
  );

  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [loading, setLoading] = useState(true);
  const [services, setServices] = useState<Service[]>([]);
  const [products, setProducts] = useState<Product[]>([]);
  const [staff, setStaff] = useState<Staff[]>([]);
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [sales, setSales] = useState<Sale[]>([]);
  const [settings, setSettings] = useState<ShopSettings>(DEFAULT_SETTINGS);
  const [sessionLanguage, setSessionLanguage] = useState<Language>(() => (localStorage.getItem('trimtime_lang') as Language) || 'en');
  const [isDarkMode, setIsDarkMode] = useState(() => localStorage.getItem('trimtime_theme') === 'dark');

  // PWA Install States
  const [deferredPrompt, setDeferredPrompt] = useState<any>(null);

  useEffect(() => {
    const handleBeforeInstallPrompt = (e: Event) => {
      e.preventDefault();
      setDeferredPrompt(e);
    };
    window.addEventListener('beforeinstallprompt', handleBeforeInstallPrompt);
    return () => window.removeEventListener('beforeinstallprompt', handleBeforeInstallPrompt);
  }, []);

  useEffect(() => {
    const fetchData = async () => {
      try {
        const [sv, pr, st, ex, cu, sa, se] = await Promise.all([
          supabase.from('services').select('*'),
          supabase.from('products').select('*'),
          supabase.from('staff').select('*'),
          supabase.from('expenses').select('*'),
          supabase.from('customers').select('*'),
          supabase.from('sales').select('*'),
          supabase.from('settings').select('*').single()
        ]);

        // --- SERVICES ---
        if (sv.data && sv.data.length > 0) {
            setServices(sv.data);
        } else if (sv.error) {
            console.error("Services DB Error:", sv.error);
            setServices(INITIAL_SERVICES); // Fallback only on error
        } else {
            setServices([]); // Valid empty state
        }

        // --- PRODUCTS ---
        if (pr.data && pr.data.length > 0) {
            setProducts(pr.data.map((p: any) => ({ ...p, lowStockThreshold: p.low_stock_threshold })));
        } else if (pr.error) {
            console.error("Products DB Error:", pr.error);
            setProducts(INITIAL_PRODUCTS);
        } else {
            setProducts([]);
        }

        // --- STAFF ---
        if (st.data && st.data.length > 0) {
            setStaff(st.data);
        } else if (st.error) {
            console.error("Staff DB Error:", st.error);
            setStaff(INITIAL_STAFF);
        } else {
            setStaff(INITIAL_STAFF); // Ensure at least one login exists
        }

        // --- EXPENSES ---
        if (ex.data && ex.data.length > 0) {
            setExpenses(ex.data.map((e: any) => ({ ...e, receiptImage: e.receipt_image })));
        } else if (ex.error) {
            console.error("Expenses DB Error:", ex.error);
        } else {
            setExpenses([]);
        }

        // --- CUSTOMERS ---
        if (cu.data && cu.data.length > 0) {
            setCustomers(cu.data.map((c: any) => ({ ...c, createdAt: c.created_at })));
        } else if (cu.error) {
            console.error("Customers DB Error:", cu.error);
            setCustomers(INITIAL_CUSTOMERS);
        } else {
            setCustomers([]);
        }

        // --- SALES ---
        if (sa.data) {
          setSales(sa.data.map((s: any) => ({ 
            ...s, 
            items: (typeof s.items === 'string' ? JSON.parse(s.items) : s.items) || [],
            staffName: s.professional_name,
            customerName: s.customer_name
          })));
        } else if (sa.error) {
            console.error("Sales DB Error:", sa.error);
        }

        // --- SETTINGS ---
        if (se.data?.data) {
            setSettings({ ...DEFAULT_SETTINGS, ...se.data.data });
        }

      } catch (e) { 
          console.error("Fatal Error loading data:", e); 
      } finally { 
          setLoading(false); 
      }
    };
    fetchData();
  }, []);

  useEffect(() => {
    document.documentElement.classList.toggle('dark', isDarkMode);
    localStorage.setItem('trimtime_theme', isDarkMode ? 'dark' : 'light');
  }, [isDarkMode]);

  useEffect(() => {
    document.documentElement.lang = sessionLanguage;
    document.dir = ['ur', 'fa'].includes(sessionLanguage) ? 'rtl' : 'ltr';
    localStorage.setItem('trimtime_lang', sessionLanguage);
  }, [sessionLanguage]);

  // --- DATABASE SYNC HANDLERS ---

  const handleUpdateServices = async (updated: Service[]) => {
    // 1. Calculate items to delete
    const currentIds = new Set<string>(services.map(i => i.id));
    const newIds = new Set<string>(updated.map(i => i.id));
    const toDelete: string[] = Array.from(currentIds).filter(id => !newIds.has(id));

    // 2. Optimistic Update
    setServices(updated);

    try {
      if (toDelete.length) {
          await supabase.from('services').delete().in('id', toDelete);
      }
      if (updated.length) {
          const { error } = await supabase.from('services').upsert(updated);
          if (error) throw error;
      }
    } catch (error) { 
        console.error("DB Sync Error (Services):", error);
        alert("Failed to sync services with database.");
    }
  };

  const handleUpdateProducts = async (updated: Product[]) => {
    const currentIds = new Set<string>(products.map(i => i.id));
    const newIds = new Set<string>(updated.map(i => i.id));
    const toDelete: string[] = Array.from(currentIds).filter(id => !newIds.has(id));

    setProducts(updated);

    // Map to DB column names (camelCase -> snake_case)
    const dbRowsFull = updated.map(p => ({
        id: p.id,
        name: p.name,
        price: p.price,
        cost: p.cost, // COGS
        stock: p.stock,
        barcode: p.barcode || null,
        low_stock_threshold: p.lowStockThreshold || 15
    }));

    try {
      if (toDelete.length) {
          await supabase.from('products').delete().in('id', toDelete);
      }

      if (dbRowsFull.length) {
          const { error } = await supabase.from('products').upsert(dbRowsFull);
          if (error) throw error;
      }
    } catch (error) { 
        console.error("DB Sync Error (Products):", error); 
        alert("Failed to sync products with database.");
    }
  };

  const handleUpdateStaff = async (updated: Staff[]) => {
    const currentIds = new Set<string>(staff.map(i => i.id));
    const newIds = new Set<string>(updated.map(i => i.id));
    const toDelete: string[] = Array.from(currentIds).filter(id => !newIds.has(id));

    setStaff(updated);

    try {
      if (toDelete.length) await supabase.from('staff').delete().in('id', toDelete);
      if (updated.length) {
          const { error } = await supabase.from('staff').upsert(updated);
          if (error) throw error;
      }
    } catch (error) { 
        console.error("DB Sync Error (Staff):", error);
        alert("Failed to sync staff with database.");
    }
  };

  const handleUpdateCustomers = async (updated: Customer[]) => {
    const currentIds = new Set<string>(customers.map(i => i.id));
    const newIds = new Set<string>(updated.map(i => i.id));
    const toDelete: string[] = Array.from(currentIds).filter(id => !newIds.has(id));

    setCustomers(updated);

    const dbRows = updated.map(c => ({
        id: c.id,
        name: c.name,
        phone: c.phone,
        email: c.email,
        notes: c.notes,
        created_at: c.createdAt
    }));

    try {
      if (toDelete.length) await supabase.from('customers').delete().in('id', toDelete);
      if (dbRows.length) {
          const { error } = await supabase.from('customers').upsert(dbRows);
          if (error) throw error;
      }
    } catch (error) { 
        console.error("DB Sync Error (Customers):", error);
        alert("Failed to sync customers with database.");
    }
  };

  const handleUpdateSettings = async (updated: ShopSettings) => {
    setSettings(updated);
    try {
      const { error } = await supabase.from('settings').upsert({ id: 1, data: updated });
      if (error) throw error;
    } catch (error) { 
        console.error("DB Sync Error (Settings):", error);
    }
  };

  const handleCompleteSale = async (sale: Sale) => {
    setSales(prev => [...prev, sale]);

    // 1. Prepare Sale Object for DB
    const dbSale = {
        id: sale.id,
        timestamp: sale.timestamp,
        items: sale.items, 
        staff_id: sale.staffId,
        customer_id: sale.customerId,
        total: sale.total,
        tax: sale.tax,
        discount: sale.discount,
        discount_code: sale.discountCode,
        payment_method: sale.paymentMethod,
        tax_type: sale.taxType,
        customer_name: sale.customerName,
        professional_name: sale.staffName
    };

    // 2. Insert Sale & Update Inventory
    try {
      // Insert Sale
      const { error: saleError } = await supabase.from('sales').insert(dbSale);
      if (saleError) throw saleError;

      // Update Stock Levels Locally & in DB
      let productsUpdated = false;
      const newProducts = [...products];

      sale.items.forEach(item => {
          if (item.type === 'product') {
              const idx = newProducts.findIndex(p => p.id === item.id);
              if (idx > -1) {
                  const newStock = Math.max(0, newProducts[idx].stock - item.quantity);
                  newProducts[idx] = { ...newProducts[idx], stock: newStock };
                  productsUpdated = true;
              }
          }
      });

      if (productsUpdated) {
          handleUpdateProducts(newProducts);
      }
    } catch (error) { 
        console.error("DB Sync Error (Sale):", error);
        alert("Transaction completed but failed to save to database.");
    }
  };

  const handleDeleteSales = async (ids: string[]) => {
    setSales(prev => prev.filter(s => !ids.includes(s.id)));
    try {
      const { error } = await supabase.from('sales').delete().in('id', ids);
      if (error) throw error;
    } catch (error) {
       console.error("DB Sync Error (Delete Sales):", error);
       alert("Failed to delete sales from database.");
    }
  };

  const handleAddExpense = async (expense: Expense) => {
      setExpenses(prev => [...prev, expense]);
      const dbExpense = {
          id: expense.id,
          date: expense.date,
          category: expense.category,
          amount: expense.amount,
          description: expense.description || '',
          receipt_image: expense.receiptImage || null
      };
      try {
        const { error } = await supabase.from('expenses').insert(dbExpense);
        if (error) throw error;
      } catch (error) { 
          console.error("DB Sync Error (Expense):", error);
          alert("Failed to save expense to database.");
      }
  };

  const handleDeleteExpense = async (id: string) => {
      setExpenses(prev => prev.filter(e => e.id !== id));
      try {
        const { error } = await supabase.from('expenses').delete().eq('id', id);
        if (error) throw error;
      } catch (error) { 
          console.error("DB Sync Error (Delete Expense):", error);
          alert("Failed to delete expense from database.");
      }
  };

  const handlePurgeSales = async () => {
    setSales([]);
    try {
       const { error } = await supabase.from('sales').delete().neq('id', '0'); // Delete all
       if (error) throw error;
    } catch (error) { 
        console.error("DB Sync Error (Purge Sales):", error);
        alert("Failed to purge sales from database.");
    }
  };

  const handleLogin = (user: Staff, remember: boolean) => {
    const expiry = Date.now() + (remember ? 30 : 1) * 24 * 60 * 60 * 1000;
    localStorage.setItem('trimtime_session', JSON.stringify({ user, expiry }));
    setCurrentUser(user);
    setCurrentView(user.role === 'employee' ? View.POS : View.DASHBOARD);
  };

  const handleLogout = () => {
    localStorage.removeItem('trimtime_session');
    setCurrentUser(null);
  };

  if (loading) return <div className="h-screen w-full flex items-center justify-center bg-slate-950"><div className="animate-spin rounded-full h-12 w-12 border-t-2 border-amber-500"></div></div>;
  if (!currentUser) return <Login onLogin={handleLogin} staffList={staff} shopName={settings.shopName} />;

  return (
    <div className="flex h-screen bg-slate-50 dark:bg-slate-950 overflow-hidden font-sans transition-colors duration-300">
      <Sidebar 
        currentView={currentView} onViewChange={setCurrentView} 
        shopName={settings.shopName} userRole={currentUser.role} 
        isOpen={isSidebarOpen} onClose={() => setIsSidebarOpen(false)}
        language={sessionLanguage} onLanguageChange={setSessionLanguage}
      />

      <div className="flex-1 flex flex-col min-w-0 md:pl-64 overflow-hidden relative">
        {/* Responsive Header */}
        <header className="flex md:hidden items-center justify-between p-4 bg-white dark:bg-slate-900 border-b border-slate-100 dark:border-slate-800 z-50 sticky top-0 shadow-sm">
          <div className="flex items-center gap-2">
             <div className="w-8 h-8 bg-amber-500 rounded-lg flex items-center justify-center font-brand text-lg text-slate-950">{settings.shopName.charAt(0)}</div>
             <span className="font-bold text-slate-900 dark:text-white truncate max-w-[120px]">{settings.shopName}</span>
          </div>
          <div className="flex gap-2">
            <button onClick={() => setIsDarkMode(!isDarkMode)} className="p-2 text-slate-400 bg-slate-50 dark:bg-slate-800 rounded-lg">
              {isDarkMode ? '🌞' : '🌙'}
            </button>
            <button onClick={() => setIsSidebarOpen(true)} className="p-2 text-slate-900 dark:text-white bg-amber-500 rounded-lg">
              <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M4 6h16M4 12h16m-7 6h7"/></svg>
            </button>
          </div>
        </header>

        {/* Desktop Header */}
        <header className="hidden md:flex justify-between items-center px-8 py-6 no-print">
            <h1 className="text-2xl font-black text-slate-900 dark:text-white font-brand">{tView(currentView, sessionLanguage)}</h1>
            <div className="flex items-center gap-4">
               <button onClick={() => setIsDarkMode(!isDarkMode)} className="p-2.5 bg-white dark:bg-slate-900 text-slate-400 rounded-xl border border-slate-200 dark:border-slate-800">
                 {isDarkMode ? '🌞' : '🌙'}
               </button>
               <div className="flex items-center gap-3 bg-white dark:bg-slate-900 p-1.5 pr-4 rounded-full border border-slate-100 dark:border-slate-800 shadow-sm">
                  <div className="w-8 h-8 rounded-full bg-amber-500 flex items-center justify-center font-black text-slate-950 text-xs">{currentUser.name.charAt(0)}</div>
                  <div className="flex flex-col"><span className="text-xs font-bold dark:text-white">{currentUser.name}</span><span className="text-[9px] uppercase font-black text-slate-400">{currentUser.role}</span></div>
               </div>
               <button onClick={handleLogout} className="p-2.5 bg-slate-100 dark:bg-slate-800 text-slate-500 rounded-xl">🚪</button>
            </div>
        </header>

        <main className="flex-1 overflow-y-auto p-4 md:p-8 relative scrollbar-hide">
          <AnimatePresence mode='wait'>
            <motion.div key={currentView} initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: -10 }} className="h-full">
              <ErrorBoundary key={currentView}>
                {renderView(currentView, { 
                  sales, expenses, products, services, staff, customers, settings, 
                  currentUser, sessionLanguage, isDarkMode, 
                  // DB Handlers passed to children
                  onUpdateServices: handleUpdateServices,
                  onUpdateProducts: handleUpdateProducts,
                  onUpdateStaff: handleUpdateStaff,
                  onUpdateCustomers: handleUpdateCustomers,
                  onUpdateSettings: handleUpdateSettings,
                  onCompleteSale: handleCompleteSale,
                  onAddExpense: handleAddExpense,
                  onDeleteExpense: handleDeleteExpense,
                  onLogout: handleLogout,
                  onPurgeSales: handlePurgeSales,
                  onDeleteSales: handleDeleteSales,

                  setCurrentView, handleLogout
                })}
              </ErrorBoundary>
            </motion.div>
          </AnimatePresence>
        </main>
      </div>

      <InstallBanner 
        deferredPrompt={deferredPrompt} 
        onClose={() => setDeferredPrompt(null)} 
      />
    </div>
  );
};

const tView = (v: View, l: Language) => {
  const map: any = { 
    en: { [View.DASHBOARD]: 'Dashboard', [View.POS]: 'Terminal', [View.FINANCE]: 'Finances', [View.INVENTORY]: 'Catalog', [View.STAFF]: 'Staff', [View.CUSTOMERS]: 'Clients', [View.SETTINGS]: 'Settings' },
    ur: { [View.DASHBOARD]: 'ڈیش بورڈ', [View.POS]: 'ٹرمینل', [View.FINANCE]: 'مالیات', [View.INVENTORY]: 'کیٹلاگ', [View.STAFF]: 'عملہ', [View.CUSTOMERS]: 'صارفین', [View.SETTINGS]: 'ترتیبات' },
    fa: { [View.DASHBOARD]: 'داشبورد', [View.POS]: 'پایانه', [View.FINANCE]: 'مالی', [View.INVENTORY]: 'موجودی', [View.STAFF]: 'پرسنل', [View.CUSTOMERS]: 'مشتریان', [View.SETTINGS]: 'تنظیمات' }
  };
  return map[l]?.[v] || map['en'][v];
};

const renderView = (v: View, props: any) => {
  const { sales, expenses, products, services, staff, customers, settings, currentUser, sessionLanguage, onUpdateServices, onUpdateProducts, onUpdateStaff, onUpdateCustomers, onUpdateSettings, onCompleteSale, onAddExpense, onDeleteExpense, onLogout, onPurgeSales, onDeleteSales, setCurrentView } = props;
  switch (v) {
    case View.DASHBOARD: return <Dashboard sales={sales} expenses={expenses} products={products} currency={settings.currency} language={sessionLanguage} onNavigate={setCurrentView} />;
    case View.POS: return <POS services={services} products={products} staff={staff} customers={customers} settings={settings} currentUser={currentUser} onCompleteSale={onCompleteSale} onAddCustomer={c => onUpdateCustomers([...customers, c])} />;
    case View.FINANCE: return <Finance sales={sales} expenses={expenses} staffList={staff} customers={customers} currency={settings.currency} language={sessionLanguage} currentUser={currentUser} onAddExpense={onAddExpense} onDeleteExpense={onDeleteExpense} onDeleteSales={onDeleteSales} settings={settings} />;
    case View.CUSTOMERS: return <Customers customers={customers} sales={sales} onUpdateCustomers={onUpdateCustomers} currency={settings.currency} language={sessionLanguage} />;
    case View.INVENTORY: return <Inventory services={services} products={products} settings={{...settings, language: sessionLanguage}} onUpdateServices={onUpdateServices} onUpdateProducts={onUpdateProducts} />;
    case View.STAFF: return <StaffManagement staffList={staff} onUpdateStaff={onUpdateStaff} currentUser={currentUser} language={sessionLanguage} />;
    case View.SETTINGS: return <Settings settings={{...settings, language: sessionLanguage}} onUpdateSettings={onUpdateSettings} currentUser={currentUser} onLogout={onLogout} onPurgeSales={onPurgeSales} />;
    default: return null;
  }
};

export default App;

import React, { useState, useMemo, useEffect, useRef } from 'react';
import { Service, Product, Staff, Sale, SaleItem, Customer, ShopSettings, HeldSale } from '../types';
import { TRANSLATIONS } from '../constants';
import { jsPDF } from 'jspdf';
import { motion, AnimatePresence } from 'framer-motion';
import { Html5Qrcode, Html5QrcodeSupportedFormats } from 'html5-qrcode';

interface POSProps {
  services: Service[];
  products: Product[];
  staff: Staff[];
  customers: Customer[];
  settings: ShopSettings;
  currentUser: Staff;
  onCompleteSale: (sale: Sale) => void;
  onAddCustomer: (customer: Customer) => void;
}

const POS: React.FC<POSProps> = ({ services, products, staff, customers, settings, currentUser, onCompleteSale, onAddCustomer }) => {
  const [cart, setCart] = useState<SaleItem[]>([]);
  const [selectedStaff, setSelectedStaff] = useState<string>(currentUser.role === 'employee' ? currentUser.id : '');
  const [selectedCustomer, setSelectedCustomer] = useState<string>('');
  const [discountCode, setDiscountCode] = useState<string>('');
  const [activeTab, setActiveTab] = useState<'services' | 'products'>('services');
  const [searchTerm, setSearchTerm] = useState('');
  // Load held sales from local storage to persist across refreshes
  const [heldSales, setHeldSales] = useState<HeldSale[]>(() => {
    try {
      const saved = localStorage.getItem('trimtime_held_sales');
      return saved ? JSON.parse(saved) : [];
    } catch (e) {
      return [];
    }
  });
  const [lastSale, setLastSale] = useState<Sale | null>(null);
  const [autoWhatsapp, setAutoWhatsapp] = useState(false);

  const [scanningFeedback, setScanningFeedback] = useState<string | null>(null);
  const [feedbackType, setFeedbackType] = useState<'success' | 'error'>('success');

  const [showMobileCart, setShowMobileCart] = useState(false);
  const [isAddingCustomer, setIsAddingCustomer] = useState(false);
  const [newCustomerData, setNewCustomerData] = useState({ name: '', phone: '', email: '' });
  const [isScanning, setIsScanning] = useState(false);

  const feedbackTimeoutRef = useRef<number | null>(null);
  const html5QrCodeRef = useRef<Html5Qrcode | null>(null);
  const isScannerActiveRef = useRef(false);
  const processingScanRef = useRef(false);

  const t = TRANSLATIONS[settings.language];

  // Persist held sales whenever they change
  useEffect(() => {
    localStorage.setItem('trimtime_held_sales', JSON.stringify(heldSales));
  }, [heldSales]);

  const activeCustomer = useMemo(() => customers.find(c => c.id === selectedCustomer), [selectedCustomer, customers]);
  const lastCustomer = useMemo(() => lastSale?.customerId ? customers.find(c => c.id === lastSale.customerId) : null, [lastSale, customers]);

  const sendWhatsappReceipt = (sale: Sale, customer: Customer) => {
    if (!customer.phone) return;
    const itemsList = sale.items.map(i => `• *${i.name}* (${settings.currency}${i.price} x ${i.quantity})`).join('\n');
    const message = `✨ *${settings.shopName} Receipt* ✨\n\n` +
      `👤 *Customer:* ${customer.name}\n` +
      `📅 *Date:* ${new Date(sale.timestamp).toLocaleDateString()}\n` +
      `🧾 *ID:* #${sale.id.slice(0, 8)}\n` +
      `--------------------------\n` +
      `${itemsList}\n` +
      `--------------------------\n` +
      `💰 *Total:* ${settings.currency}${sale.total.toFixed(2)}\n` +
      `💳 *Method:* ${sale.paymentMethod.toUpperCase()}\n\n` +
      `${settings.receiptFooter}\n\n` +
      `_Thank you for your visit!_`;
    const cleanPhone = customer.phone.replace(/\D/g, '');
    window.open(`https://wa.me/${cleanPhone}?text=${encodeURIComponent(message)}`, '_blank');
  };

  useEffect(() => {
    let isMounted = true;

    const cleanupScanner = async () => {
        if (!html5QrCodeRef.current) return;
        try {
            if (isScannerActiveRef.current) {
                await html5QrCodeRef.current.stop();
            }
        } catch (e) {
            console.warn("POS Scanner stop error", e);
        } finally {
            isScannerActiveRef.current = false;
            try { await html5QrCodeRef.current.clear(); } catch(e) {}
            html5QrCodeRef.current = null;
        }
    };

    if (isScanning) {
        const startScanner = async () => {
            await new Promise(resolve => setTimeout(resolve, 600));
            if (!isMounted || !isScanning) return;

            if (!document.getElementById("reader")) return;

            await cleanupScanner();

            try {
                const html5QrCode = new Html5Qrcode("reader", {
                  formatsToSupport: [
                    Html5QrcodeSupportedFormats.EAN_13,
                    Html5QrcodeSupportedFormats.EAN_8,
                    Html5QrcodeSupportedFormats.CODE_128,
                    Html5QrcodeSupportedFormats.UPC_A,
                    Html5QrcodeSupportedFormats.UPC_E,
                    Html5QrcodeSupportedFormats.QR_CODE
                  ],
                  verbose: false
                });

                html5QrCodeRef.current = html5QrCode;

                await html5QrCode.start(
                    { facingMode: "environment" }, 
                    { 
                        fps: 15, 
                        qrbox: (viewfinderWidth, viewfinderHeight) => {
                            const width = Math.floor(viewfinderWidth * 0.85);
                            const height = Math.floor(viewfinderHeight * 0.35);
                            return { width, height };
                        },
                        aspectRatio: 1.777778,
                        experimentalFeatures: {
                            useBarCodeDetectorIfSupported: true
                        }
                    }, 
                    (decodedText) => { if (isMounted) handleScan(decodedText); },
                    () => {} 
                );

                isScannerActiveRef.current = true;

                if (!isMounted) {
                    await cleanupScanner();
                }
            } catch (err: any) {
                const isPermissionError = err?.name === 'NotAllowedError' || err?.name === 'PermissionDeniedError' || err?.message?.includes('Permission');

                if (isMounted) {
                  if (isPermissionError) {
                      setScanningFeedback("Camera Permission Denied");
                      console.warn("POS Camera permission denied");
                  } else {
                      setScanningFeedback("Camera Error");
                      console.error("Scanner startup error:", err);
                  }
                  setFeedbackType("error");
                  setTimeout(() => setIsScanning(false), 2000);
                }
                await cleanupScanner();
            }
        };
        startScanner();
    }

    // Cleanup function
    return () => {
        isMounted = false;
        // Trigger async cleanup without awaiting
        if (html5QrCodeRef.current) {
             const scanner = html5QrCodeRef.current;
             const wasActive = isScannerActiveRef.current;

             if (wasActive) {
                 scanner.stop().catch((e) => console.warn("POS Stop failed during unmount", e))
                 .finally(() => {
                    try { scanner.clear(); } catch(e) {}
                    isScannerActiveRef.current = false;
                 });
             } else {
                 try { scanner.clear(); } catch(e) {}
             }
        }
    };
  }, [isScanning]);

  const handleScan = (barcode: string) => {
    if (processingScanRef.current) return;
    processingScanRef.current = true;

    const product = products.find(p => p.barcode === barcode);
    if (product) {
        if ("vibrate" in navigator) navigator.vibrate(100);
        addToCart(product, 'product');
        setScanningFeedback(`Added: ${product.name}`);
        setFeedbackType('success');

        if (feedbackTimeoutRef.current) window.clearTimeout(feedbackTimeoutRef.current);
        feedbackTimeoutRef.current = window.setTimeout(() => { 
            setScanningFeedback(null); 
            processingScanRef.current = false;
        }, 1500); 
    } else {
        if ("vibrate" in navigator) navigator.vibrate([100, 50, 100]);
        setScanningFeedback(`Unknown Product: ${barcode}`);
        setFeedbackType('error');

        if (feedbackTimeoutRef.current) window.clearTimeout(feedbackTimeoutRef.current);
        feedbackTimeoutRef.current = window.setTimeout(() => { 
            setScanningFeedback(null); 
            processingScanRef.current = false;
        }, 3500);
    }
  };

  const toggleScanner = () => setIsScanning(!isScanning);

  const addToCart = (item: Service | Product, type: 'service' | 'product') => {
    setCart(prev => {
      const existing = prev.find(i => i.id === item.id && i.type === type);
      if (existing) {
        return prev.map(i => i.id === item.id && i.type === type ? { ...i, quantity: i.quantity + 1 } : i);
      }
      return [...prev, { id: item.id, name: item.name, price: item.price, type, quantity: 1 }];
    });
  };

  const updateQuantity = (id: string, type: 'service' | 'product', delta: number) => {
    setCart(prev => prev.map(item => {
      if (item.id === id && item.type === type) return { ...item, quantity: Math.max(1, item.quantity + delta) };
      return item;
    }));
  };

  const removeFromCart = (id: string, type: 'service' | 'product') => {
    setCart(prev => prev.filter(i => !(i.id === id && i.type === type)));
  };

  const totals = useMemo(() => {
    const rawSubtotal = cart.reduce((acc, item) => acc + (item.price * item.quantity), 0);
    let discount = 0;
    const code = (settings.promoCodes || []).find(c => c.code === discountCode);
    if (code) discount = code.type === 'percentage' ? (rawSubtotal * code.value) / 100 : code.value;
    const discountedAmount = rawSubtotal - discount;
    let tax = 0;
    let total = 0;
    if (settings.taxType === 'included') {
      total = discountedAmount;
      tax = total - (total / (1 + (settings.taxRate / 100)));
    } else {
      tax = discountedAmount * (settings.taxRate / 100);
      total = discountedAmount + tax;
    }
    return { subtotal: rawSubtotal, discount, tax, total };
  }, [cart, discountCode, settings]);

  const handleHoldSale = () => {
    if (cart.length === 0) return;
    const newHold: HeldSale = {
      id: Math.random().toString(36).substr(2, 9).toUpperCase(),
      timestamp: new Date().toISOString(),
      cart: [...cart],
      customerId: selectedCustomer || undefined,
      staffId: selectedStaff || undefined,
    };
    setHeldSales([newHold, ...heldSales]);
    setCart([]);
    setSelectedCustomer('');
    if (currentUser.role !== 'employee') setSelectedStaff('');
  };

  const retrieveSale = (held: HeldSale) => {
    setCart(held.cart);
    if (held.customerId) setSelectedCustomer(held.customerId);
    if (held.staffId) setSelectedStaff(held.staffId);
    setHeldSales(heldSales.filter(h => h.id !== held.id));
    setShowMobileCart(true); // Open cart to show retrieved items
  };

  const deleteHeldSale = (id: string) => {
    if(confirm('Discard this held bill?')) {
      setHeldSales(prev => prev.filter(h => h.id !== id));
    }
  };

  const handleShareReceipt = async (sale: Sale) => {
    // Dynamic height calculation: Base 120mm + 5mm per item
    const docHeight = 120 + (sale.items.length * 6);
    const doc = new jsPDF({
        orientation: 'portrait',
        unit: 'mm',
        format: [80, docHeight] 
    });

    const centerX = 40;
    let y = 10;

    // --- Header ---
    doc.setFont("helvetica", "bold");
    doc.setFontSize(14);
    doc.text(settings.shopName, centerX, y, { align: 'center' });
    y += 5;

    doc.setFontSize(8);
    doc.setFont("helvetica", "normal");
    doc.text("Premium Grooming Services", centerX, y, { align: 'center' });
    y += 6;

    // Meta
    const dateStr = new Date(sale.timestamp).toLocaleString();
    doc.text(dateStr, centerX, y, { align: 'center' });
    y += 4;
    doc.text(`Receipt #${sale.id.slice(0, 8)}`, centerX, y, { align: 'center' });
    y += 5;

    // Divider
    doc.setLineWidth(0.2);
    doc.line(5, y, 75, y);
    y += 5;

    // --- Customer/Staff Info ---
    doc.setFontSize(9);
    const staffName = sale.staffName || staff.find(s => s.id === sale.staffId)?.name || 'Staff';
    doc.text(`Pro: ${staffName}`, 5, y);
    y += 4;

    const clientName = sale.customerName || customers.find(c => c.id === sale.customerId)?.name || 'Walk-in Client';
    doc.text(`Client: ${clientName}`, 5, y);
    y += 5;

    doc.line(5, y, 75, y);
    y += 5;

    // --- Items Header ---
    doc.setFont("helvetica", "bold");
    doc.text("Item", 5, y);
    doc.text("Price", 75, y, { align: "right" });
    y += 5;

    // --- Items List ---
    doc.setFont("helvetica", "normal");
    sale.items.forEach(item => {
        const itemName = `${item.quantity}x ${item.name}`;
        // Wrap long names
        const splitName = doc.splitTextToSize(itemName, 45);
        doc.text(splitName, 5, y);

        const priceStr = `${settings.currency}${(item.price * item.quantity).toFixed(2)}`;
        doc.text(priceStr, 75, y, { align: "right" });

        // Adjust Y based on lines used by name
        y += (splitName.length * 4) + 1; 
    });

    y += 2;
    doc.line(5, y, 75, y);
    y += 5;

    // --- Totals ---
    const rightCol = 75;
    const labelCol = 45;

    doc.text("Subtotal:", labelCol, y, { align: "right" });
    const subtotal = sale.total - sale.tax + sale.discount;
    doc.text(`${settings.currency}${subtotal.toFixed(2)}`, rightCol, y, { align: "right" });
    y += 4;

    if (sale.discount > 0) {
        doc.text("Discount:", labelCol, y, { align: "right" });
        doc.text(`-${settings.currency}${sale.discount.toFixed(2)}`, rightCol, y, { align: "right" });
        y += 4;
    }

    if (sale.tax > 0) {
        doc.text(`Tax (${settings.taxRate}%):`, labelCol, y, { align: "right" });
        doc.text(`${settings.currency}${sale.tax.toFixed(2)}`, rightCol, y, { align: "right" });
        y += 4;
    }

    y += 2;
    doc.setFont("helvetica", "bold");
    doc.setFontSize(11);
    doc.text("TOTAL:", labelCol, y, { align: "right" });
    doc.text(`${settings.currency}${sale.total.toFixed(2)}`, rightCol, y, { align: "right" });
    y += 7;

    // --- Payment Info ---
    doc.setFontSize(8);
    doc.setFont("helvetica", "normal");
    doc.text(`PAID VIA ${sale.paymentMethod.toUpperCase()}`, centerX, y, { align: "center" });
    y += 6;

    // --- Footer ---
    doc.setFont("helvetica", "italic");
    const footerLines = doc.splitTextToSize(settings.receiptFooter || "Thank you for your business!", 70);
    doc.text(footerLines, centerX, y, { align: "center" });

    doc.save(`Receipt-${sale.id}.pdf`);
  };

  const handleCheckout = (paymentMethod: 'cash' | 'card') => {
    if (cart.length === 0 || !selectedStaff) {
      alert('Please add items and assign a professional.');
      return;
    }
    const staffMember = staff.find(s => s.id === selectedStaff);
    const customerMember = customers.find(c => c.id === selectedCustomer);
    const sale: Sale = {
      id: Math.random().toString(36).substr(2, 9).toUpperCase(),
      timestamp: new Date().toISOString(),
      items: [...cart],
      staffId: selectedStaff,
      customerId: selectedCustomer || undefined,
      total: totals.total,
      tax: totals.tax,
      discount: totals.discount,
      discountCode: discountCode || undefined,
      paymentMethod,
      taxType: settings.taxType,
      staffName: staffMember?.name || 'Unknown',
      customerName: customerMember?.name || (selectedCustomer ? 'Unknown' : undefined)
    };
    onCompleteSale(sale);
    setLastSale(sale);
    if (autoWhatsapp && selectedCustomer) {
      const cust = customers.find(c => c.id === selectedCustomer);
      if (cust && cust.phone) setTimeout(() => sendWhatsappReceipt(sale, cust), 1200);
    }
    setCart([]);
    setSelectedCustomer('');
    setDiscountCode('');
    if (currentUser.role !== 'employee') setSelectedStaff('');
    setShowMobileCart(false);
  };

  const saveNewCustomer = () => {
      if(!newCustomerData.name) return;
      const newCustomer: Customer = {
          id: 'c' + Date.now().toString(36),
          name: newCustomerData.name,
          phone: newCustomerData.phone,
          email: newCustomerData.email,
          notes: '',
          createdAt: new Date().toISOString()
      };
      onAddCustomer(newCustomer);
      setSelectedCustomer(newCustomer.id);
      setIsAddingCustomer(false);
      setNewCustomerData({ name: '', phone: '', email: '' });
  };

  const filteredItems = useMemo(() => {
    const search = searchTerm.toLowerCase();
    if (activeTab === 'services') return services.filter(s => s.name.toLowerCase().includes(search) || s.category.toLowerCase().includes(search));
    return products.filter(p => p.name.toLowerCase().includes(search));
  }, [activeTab, services, products, searchTerm]);

  return (
    <div className="flex flex-col lg:flex-row gap-6 h-full relative">
      {/* Held Sales Sidebar/Indicator (Optional for Desktop) */}
      {heldSales.length > 0 && (
         <div className="absolute top-0 right-0 z-10 p-2 hidden lg:block">
            <div className="bg-amber-100 text-amber-800 px-3 py-1 rounded-full text-xs font-bold border border-amber-200 shadow-sm">
               {heldSales.length} Held Bills
            </div>
         </div>
      )}

      <AnimatePresence>
        {lastSale && (
          <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="fixed inset-0 bg-slate-950/80 backdrop-blur-xl z-[150] flex items-center justify-center p-6 no-print">
            <motion.div initial={{ scale: 0.8, opacity: 0, y: 20 }} animate={{ scale: 1, opacity: 1, y: 0 }} className="bg-white dark:bg-slate-900 rounded-[2.5rem] p-8 md:p-10 max-w-md w-full shadow-2xl text-center space-y-8">
              <div className="w-16 h-16 md:w-20 md:h-20 bg-emerald-50 dark:bg-emerald-900/20 text-emerald-500 rounded-full flex items-center justify-center text-3xl md:text-4xl mx-auto shadow-inner">✓</div>
              <div className="space-y-2">
                <h3 className="text-2xl md:text-3xl font-black text-slate-900 dark:text-white tracking-tight">{t.saleSuccess}</h3>
                <p className="text-slate-400 dark:text-slate-500 font-medium">{t.orderCompleted}</p>
              </div>
              <div className="flex flex-col gap-3">
                {lastCustomer && lastCustomer.phone && (
                  <button onClick={() => sendWhatsappReceipt(lastSale, lastCustomer)} className="w-full bg-emerald-500 text-white py-4 rounded-2xl font-black flex items-center justify-center gap-3 hover:bg-emerald-600 transition-all shadow-xl shadow-emerald-500/20 active:scale-95 text-sm md:text-base">
                    <svg className="w-5 h-5" fill="currentColor" viewBox="0 0 24 24"><path d="M.057 24l1.687-6.163c-1.041-1.804-1.588-3.849-1.587-5.946.003-6.556 5.338-11.891 11.893-11.891 3.181.001 6.167 1.24 8.413 3.488 2.246 2.248 3.484 5.232 3.484 8.412-.003 6.557-5.338 11.892-11.893 11.892-1.997-.001-3.951-.5-5.688-1.448l-6.309 1.656zm6.224-3.52c1.54.914 3.453 1.403 5.385 1.404h.005c5.632 0 10.211-4.579 10.214-10.211 0-2.729-1.063-5.295-2.993-7.225s-4.496-2.992-7.225-2.993c-5.633 0-10.213 4.58-10.214 10.214 0 2.022.529 3.996 1.531 5.74l-.991 3.618 3.707-.972zm11.233-5.62c-.301-.151-1.782-.879-2.057-.979-.275-.1-.475-.151-.675.151s-.777.979-.952 1.179-.35.225-.65.076c-.301-.151-1.268-.467-2.417-1.492-.892-.795-1.494-1.777-1.669-2.078-.175-.301-.019-.463.131-.613.135-.134.301-.351.451-.526s.201-.3.301-.5.101-.201.05-.376-.025-.526s-.675-1.629-.925-2.229c-.244-.583-.491-.504-.675-.513-.175-.008-.376-.01-.576-.01s-.526.076-.801.376c-.275.301-1.051 1.028-1.051 2.508s1.076 2.908 1.226 3.109c.151.201 2.118 3.235 5.132 4.537.717.309 1.277.494 1.714.633.72.228 1.375.196 1.892.119.577-.085 1.782-.728 2.032-1.429s.25-.151.25-.376-.101-.351-.401-.502z"/></svg>
                    WhatsApp Receipt
                  </button>
                )}
                <button onClick={() => handleShareReceipt(lastSale)} className="w-full bg-slate-950 dark:bg-amber-500 dark:text-slate-950 text-white py-4 rounded-2xl font-black flex items-center justify-center gap-3 hover:bg-slate-800 dark:hover:bg-amber-600 transition-all shadow-xl active:scale-95 text-sm md:text-base">
                  <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M8.684 13.342C8.886 12.938 9 12.482 9 12c0-.482-.114-.938-.316-1.342m0 2.684a3 3 0 110-2.684m0 2.684l6.632 3.316m-6.632-6l6.632-3.316m0 0a3 3 0 105.367-2.684 3 3 0 00-5.367 2.684zm0 9.316a3 3 0 105.368 2.684 3 3 0 00-5.368-2.684z"/></svg>
                  {t.shareReceipt}
                </button>
                <button onClick={() => setLastSale(null)} className="w-full py-4 text-slate-400 dark:text-slate-600 font-bold hover:text-slate-600 dark:hover:text-slate-400 text-sm">{t.startNewBill}</button>
              </div>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>

      <div className="flex-1 flex flex-col min-h-0">
        <div className="mb-4 md:mb-6 flex flex-col sm:flex-row gap-3 md:gap-4">
          <div className="flex-1 flex gap-2">
            <div className="flex-1 relative">
                <svg className="w-5 h-5 absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 dark:text-slate-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z"/></svg>
                <input type="text" placeholder={t.searchCatalog} value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} className="w-full bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-2xl py-3 md:py-3.5 pl-11 pr-4 md:pl-12 md:pr-6 outline-none focus:ring-4 focus:ring-amber-500/10 shadow-sm text-sm font-medium dark:text-slate-200" />
            </div>
            <button onClick={toggleScanner} className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-2xl px-4 flex items-center justify-center text-slate-500 dark:text-slate-400 hover:text-amber-500 transition-all shadow-sm"><svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 4v1m6 11h2m-6 0h-2v4m0-11v3m0 0h.01M12 12h4.01M16 20h4M4 12h4m12 0h.01M5 8h2a1 1 0 001-1V5a1 1 0 00-1-1H5a1 1 0 00-1 1v2a1 1 0 001 1zm12 0h2a1 1 0 001-1V5a1 1 0 00-1-1h-2a1 1 0 00-1 1v2a1 1 0 001 1zM5 20h2a1 1 0 001-1v-2a1 1 0 00-1-1H5a1 1 0 00-1 1v2a1 1 0 001 1z"/></svg></button>
          </div>
          <div className="flex bg-white dark:bg-slate-900 p-1 rounded-2xl border border-slate-100 dark:border-slate-800 shadow-sm self-start sm:self-auto">
            <button onClick={() => setActiveTab('services')} className={`px-4 md:px-6 py-2 rounded-xl text-[10px] md:text-xs font-black uppercase tracking-widest transition-all ${activeTab === 'services' ? 'bg-amber-500 text-slate-900 shadow-md' : 'text-slate-400 hover:text-slate-600'}`}>{t.services}</button>
            <button onClick={() => setActiveTab('products')} className={`px-4 md:px-6 py-2 rounded-xl text-[10px] md:text-xs font-black uppercase tracking-widest transition-all ${activeTab === 'products' ? 'bg-amber-500 text-slate-900 shadow-md' : 'text-slate-400 hover:text-slate-600'}`}>{t.products}</button>
          </div>
        </div>
        <div className="flex-1 overflow-y-auto grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-3 md:gap-4 pr-1 scrollbar-hide pb-24 lg:pb-0">
          {filteredItems.map(item => (
            <motion.button layout key={item.id} whileHover={{ scale: 1.02 }} whileTap={{ scale: 0.98 }} onClick={() => addToCart(item, activeTab === 'services' ? 'service' : 'product')} className="bg-white dark:bg-slate-900 p-4 md:p-5 rounded-[2rem] border border-slate-100 dark:border-slate-800 shadow-sm hover:shadow-md transition-all text-left flex flex-col justify-between group h-32 md:h-40 relative overflow-hidden">
              <div className="relative z-10">
                <span className={`text-[8px] md:text-[9px] font-black uppercase tracking-widest px-2 py-0.5 md:py-1 rounded-lg mb-1 md:mb-2 inline-block ${activeTab === 'services' ? 'bg-amber-50 dark:bg-amber-900/20 text-amber-600 dark:text-amber-400' : 'bg-indigo-50 dark:bg-indigo-900/20 text-indigo-600 dark:text-indigo-400'}`}>
                  {activeTab === 'services' ? (item as Service).category : 'Retail'}
                </span>
                <h4 className="font-bold text-slate-800 dark:text-slate-200 text-xs md:text-sm leading-tight line-clamp-2">{item.name}</h4>
              </div>
              <div className="flex items-center justify-between relative z-10">
                <p className="text-base md:text-lg font-black text-slate-900 dark:text-white">{settings.currency}{item.price}</p>
                <div className="w-7 h-7 md:w-8 md:h-8 bg-slate-900 dark:bg-slate-800 text-white rounded-full flex items-center justify-center opacity-100 lg:opacity-0 group-hover:opacity-100 transition-all">
                  <svg className="w-3.5 h-3.5 md:w-4 md:h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M12 6v6m0 0v6m0-6h6m-6 0H6"/></svg>
                </div>
              </div>
            </motion.button>
          ))}
        </div>
      </div>

      <AnimatePresence>
        {(cart.length > 0 && !showMobileCart && window.innerWidth < 1024) && (
            <motion.div 
                initial={{ y: 100 }} animate={{ y: 0 }} exit={{ y: 100 }}
                className="fixed bottom-0 left-0 right-0 p-4 bg-white dark:bg-slate-900 border-t border-slate-100 dark:border-slate-800 lg:hidden z-50 flex items-center justify-between shadow-[0_-5px_20px_rgba(0,0,0,0.1)] pb-8 md:pb-6"
            >
                <div>
                   <p className="text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wide">{cart.reduce((a, b) => a + b.quantity, 0)} Items</p>
                   <p className="text-xl font-black text-slate-900 dark:text-white">{settings.currency}{totals.total.toFixed(2)}</p>
                </div>
                <button 
                  onClick={() => setShowMobileCart(true)}
                  className="bg-amber-500 text-slate-950 px-8 py-3 rounded-xl font-black uppercase text-sm shadow-lg shadow-amber-500/20"
                >
                    View Cart
                </button>
            </motion.div>
        )}
      </AnimatePresence>

      <AnimatePresence>
        {(showMobileCart || window.innerWidth >= 1024) && (
          <>
            {showMobileCart && (
              <motion.div 
