import React, { useState, useEffect, Component, ReactNode, ErrorInfo, useRef } from 'react';
import Sidebar from './components/Sidebar';
import Dashboard from './components/Dashboard';
import POS from './components/POS';
import Finance from './components/Finance';
import Customers from './components/Customers';
import Settings from './components/Settings';
import Inventory from './components/Inventory';
import StaffManagement from './components/StaffManagement';
import Login from './components/Login';
import InstallBanner from './components/InstallBanner';
import { View, Sale, Expense, Service, Product, Staff, Customer, ShopSettings, Language } from './types';
import { INITIAL_SERVICES, INITIAL_PRODUCTS, INITIAL_STAFF, INITIAL_EXPENSES, INITIAL_CUSTOMERS, DEFAULT_SETTINGS } from './constants';
import { motion, AnimatePresence } from 'framer-motion';
import { supabase } from './supabaseClient';

interface ErrorBoundaryProps {
  children: ReactNode;
}

interface ErrorBoundaryState {
  hasError: boolean;
}

// Error Boundary to prevent white screens
class ErrorBoundary extends Component<ErrorBoundaryProps, ErrorBoundaryState> {
  constructor(props: ErrorBoundaryProps) {
    super(props);
    this.state = { hasError: false };
  }

  static getDerivedStateFromError(error: Error): ErrorBoundaryState {
    return { hasError: true };
  }

  componentDidCatch(error: Error, errorInfo: ErrorInfo) {
    console.error("Application Error:", error, errorInfo);
  }

  render() {
    if (this.state.hasError) {
      return (
        <div className="h-full w-full flex flex-col items-center justify-center p-8 text-center">
          <div className="w-16 h-16 bg-rose-100 dark:bg-rose-900/20 text-rose-500 rounded-full flex items-center justify-center text-3xl mb-4">
            ⚠️
          </div>
          <h2 className="text-xl font-black text-slate-800 dark:text-white mb-2">Something went wrong</h2>
          <p className="text-slate-500 dark:text-slate-400 mb-6 text-sm">We encountered an unexpected error loading this section.</p>
          <button 
            onClick={() => {
              this.setState({ hasError: false });
              window.location.reload();
            }}
            className="bg-slate-900 dark:bg-white text-white dark:text-slate-900 px-6 py-3 rounded-xl font-bold uppercase tracking-wider text-xs shadow-lg active:scale-95 transition-transform"
          >
            Reload App
          </button>
        </div>
      );
    }

    return this.props.children;
  }
}

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<Staff | null>(() => {
    const saved = localStorage.getItem('trimtime_session');
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        if (parsed.user && parsed.expiry && Date.now() < parsed.expiry) return parsed.user;
      } catch (e) {}
    }
    return null;
  });

  const [currentView, setCurrentView] = useState<View>(
    currentUser?.role === 'employee' ? View.POS : View.DASHBOARD
  );

  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [loading, setLoading] = useState(true);
  const [services, setServices] = useState<Service[]>([]);
  const [products, setProducts] = useState<Product[]>([]);
  const [staff, setStaff] = useState<Staff[]>([]);
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [sales, setSales] = useState<Sale[]>([]);
  const [settings, setSettings] = useState<ShopSettings>(DEFAULT_SETTINGS);
  const [sessionLanguage, setSessionLanguage] = useState<Language>(() => (localStorage.getItem('trimtime_lang') as Language) || 'en');
  const [isDarkMode, setIsDarkMode] = useState(() => localStorage.getItem('trimtime_theme') === 'dark');

  // PWA Install States
  const [deferredPrompt, setDeferredPrompt] = useState<any>(null);

  useEffect(() => {
    const handleBeforeInstallPrompt = (e: Event) => {
      e.preventDefault();
      setDeferredPrompt(e);
    };
    window.addEventListener('beforeinstallprompt', handleBeforeInstallPrompt);
    return () => window.removeEventListener('beforeinstallprompt', handleBeforeInstallPrompt);
  }, []);

  useEffect(() => {
    const fetchData = async () => {
      try {
        const [sv, pr, st, ex, cu, sa, se] = await Promise.all([
          supabase.from('services').select('*'),
          supabase.from('products').select('*'),
          supabase.from('staff').select('*'),
          supabase.from('expenses').select('*'),
          supabase.from('customers').select('*'),
          supabase.from('sales').select('*'),
          supabase.from('settings').select('*').single()
        ]);

        // --- SERVICES ---
        if (sv.data && sv.data.length > 0) {
            setServices(sv.data);
        } else if (sv.error) {
            console.error("Services DB Error:", sv.error);
            setServices(INITIAL_SERVICES); // Fallback only on error
        } else {
            setServices([]); // Valid empty state
        }

        // --- PRODUCTS ---
        if (pr.data && pr.data.length > 0) {
            setProducts(pr.data.map((p: any) => ({ ...p, lowStockThreshold: p.low_stock_threshold })));
        } else if (pr.error) {
            console.error("Products DB Error:", pr.error);
            setProducts(INITIAL_PRODUCTS);
        } else {
            setProducts([]);
        }

        // --- STAFF ---
        if (st.data && st.data.length > 0) {
            setStaff(st.data);
        } else if (st.error) {
            console.error("Staff DB Error:", st.error);
            setStaff(INITIAL_STAFF);
        } else {
            setStaff(INITIAL_STAFF); // Ensure at least one login exists
        }

        // --- EXPENSES ---
        if (ex.data && ex.data.length > 0) {
            setExpenses(ex.data.map((e: any) => ({ ...e, receiptImage: e.receipt_image })));
        } else if (ex.error) {
            console.error("Expenses DB Error:", ex.error);
        } else {
            setExpenses([]);
        }

        // --- CUSTOMERS ---
        if (cu.data && cu.data.length > 0) {
            setCustomers(cu.data.map((c: any) => ({ ...c, createdAt: c.created_at })));
        } else if (cu.error) {
            console.error("Customers DB Error:", cu.error);
            setCustomers(INITIAL_CUSTOMERS);
        } else {
            setCustomers([]);
        }

        // --- SALES ---
        if (sa.data) {
          setSales(sa.data.map((s: any) => ({ 
            ...s, 
            items: (typeof s.items === 'string' ? JSON.parse(s.items) : s.items) || [],
            staffName: s.professional_name,
            customerName: s.customer_name
          })));
        } else if (sa.error) {
            console.error("Sales DB Error:", sa.error);
        }

        // --- SETTINGS ---
        if (se.data?.data) {
            setSettings({ ...DEFAULT_SETTINGS, ...se.data.data });
        }

      } catch (e) { 
          console.error("Fatal Error loading data:", e); 
      } finally { 
          setLoading(false); 
      }
    };
    fetchData();
  }, []);

  useEffect(() => {
    document.documentElement.classList.toggle('dark', isDarkMode);
    localStorage.setItem('trimtime_theme', isDarkMode ? 'dark' : 'light');
  }, [isDarkMode]);

  useEffect(() => {
    document.documentElement.lang = sessionLanguage;
    document.dir = ['ur', 'fa'].includes(sessionLanguage) ? 'rtl' : 'ltr';
    localStorage.setItem('trimtime_lang', sessionLanguage);
  }, [sessionLanguage]);

  // --- DATABASE SYNC HANDLERS ---

  const handleUpdateServices = async (updated: Service[]) => {
    // 1. Calculate items to delete
    const currentIds = new Set<string>(services.map(i => i.id));
    const newIds = new Set<string>(updated.map(i => i.id));
    const toDelete: string[] = Array.from(currentIds).filter(id => !newIds.has(id));

    // 2. Optimistic Update
    setServices(updated);

    try {
      if (toDelete.length) {
          await supabase.from('services').delete().in('id', toDelete);
      }
      if (updated.length) {
          const { error } = await supabase.from('services').upsert(updated);
          if (error) throw error;
      }
    } catch (error) { 
        console.error("DB Sync Error (Services):", error);
        alert("Failed to sync services with database.");
    }
  };

  const handleUpdateProducts = async (updated: Product[]) => {
    const currentIds = new Set<string>(products.map(i => i.id));
    const newIds = new Set<string>(updated.map(i => i.id));
    const toDelete: string[] = Array.from(currentIds).filter(id => !newIds.has(id));

    setProducts(updated);

    // Map to DB column names (camelCase -> snake_case)
    const dbRowsFull = updated.map(p => ({
        id: p.id,
        name: p.name,
        price: p.price,
        cost: p.cost, // COGS
        stock: p.stock,
        barcode: p.barcode || null,
        low_stock_threshold: p.lowStockThreshold || 15
    }));

    try {
      if (toDelete.length) {
          await supabase.from('products').delete().in('id', toDelete);
      }

      if (dbRowsFull.length) {
          const { error } = await supabase.from('products').upsert(dbRowsFull);
          if (error) throw error;
      }
    } catch (error) { 
        console.error("DB Sync Error (Products):", error); 
        alert("Failed to sync products with database.");
    }
  };

  const handleUpdateStaff = async (updated: Staff[]) => {
    const currentIds = new Set<string>(staff.map(i => i.id));
    const newIds = new Set<string>(updated.map(i => i.id));
    const toDelete: string[] = Array.from(currentIds).filter(id => !newIds.has(id));

    setStaff(updated);

    try {
      if (toDelete.length) await supabase.from('staff').delete().in('id', toDelete);
      if (updated.length) {
          const { error } = await supabase.from('staff').upsert(updated);
          if (error) throw error;
      }
    } catch (error) { 
        console.error("DB Sync Error (Staff):", error);
        alert("Failed to sync staff with database.");
    }
  };

  const handleUpdateCustomers = async (updated: Customer[]) => {
    const currentIds = new Set<string>(customers.map(i => i.id));
    const newIds = new Set<string>(updated.map(i => i.id));
    const toDelete: string[] = Array.from(currentIds).filter(id => !newIds.has(id));

    setCustomers(updated);

    const dbRows = updated.map(c => ({
        id: c.id,
        name: c.name,
        phone: c.phone,
        email: c.email,
        notes: c.notes,
        created_at: c.createdAt
    }));

    try {
      if (toDelete.length) await supabase.from('customers').delete().in('id', toDelete);
      if (dbRows.length) {
          const { error } = await supabase.from('customers').upsert(dbRows);
          if (error) throw error;
      }
    } catch (error) { 
        console.error("DB Sync Error (Customers):", error);
        alert("Failed to sync customers with database.");
    }
  };

  const handleUpdateSettings = async (updated: ShopSettings) => {
    setSettings(updated);
    try {
      const { error } = await supabase.from('settings').upsert({ id: 1, data: updated });
      if (error) throw error;
    } catch (error) { 
        console.error("DB Sync Error (Settings):", error);
    }
  };

  const handleCompleteSale = async (sale: Sale) => {
    setSales(prev => [...prev, sale]);

    // 1. Prepare Sale Object for DB
    const dbSale = {
        id: sale.id,
        timestamp: sale.timestamp,
        items: sale.items, 
        staff_id: sale.staffId,
        customer_id: sale.customerId,
        total: sale.total,
        tax: sale.tax,
        discount: sale.discount,
        discount_code: sale.discountCode,
        payment_method: sale.paymentMethod,
        tax_type: sale.taxType,
        customer_name: sale.customerName,
        professional_name: sale.staffName
    };

    // 2. Insert Sale & Update Inventory
    try {
      // Insert Sale
      const { error: saleError } = await supabase.from('sales').insert(dbSale);
      if (saleError) throw saleError;

      // Update Stock Levels Locally & in DB
      let productsUpdated = false;
      const newProducts = [...products];

      sale.items.forEach(item => {
          if (item.type === 'product') {
              const idx = newProducts.findIndex(p => p.id === item.id);
              if (idx > -1) {
                  const newStock = Math.max(0, newProducts[idx].stock - item.quantity);
                  newProducts[idx] = { ...newProducts[idx], stock: newStock };
                  productsUpdated = true;
              }
          }
      });

      if (productsUpdated) {
          handleUpdateProducts(newProducts);
      }
    } catch (error) { 
        console.error("DB Sync Error (Sale):", error);
        alert("Transaction completed but failed to save to database.");
    }
  };

  const handleDeleteSales = async (ids: string[]) => {
    setSales(prev => prev.filter(s => !ids.includes(s.id)));
    try {
      const { error } = await supabase.from('sales').delete().in('id', ids);
      if (error) throw error;
    } catch (error) {
       console.error("DB Sync Error (Delete Sales):", error);
       alert("Failed to delete sales from database.");
    }
  };

  const handleAddExpense = async (expense: Expense) => {
      setExpenses(prev => [...prev, expense]);
      const dbExpense = {
          id: expense.id,
          date: expense.date,
          category: expense.category,
          amount: expense.amount,
          description: expense.description || '',
          receipt_image: expense.receiptImage || null
      };
      try {
        const { error } = await supabase.from('expenses').insert(dbExpense);
        if (error) throw error;
      } catch (error) { 
          console.error("DB Sync Error (Expense):", error);
          alert("Failed to save expense to database.");
      }
  };

  const handleDeleteExpense = async (id: string) => {
      setExpenses(prev => prev.filter(e => e.id !== id));
      try {
        const { error } = await supabase.from('expenses').delete().eq('id', id);
        if (error) throw error;
      } catch (error) { 
          console.error("DB Sync Error (Delete Expense):", error);
          alert("Failed to delete expense from database.");
      }
  };

  const handlePurgeSales = async () => {
    setSales([]);
    try {
       const { error } = await supabase.from('sales').delete().neq('id', '0'); // Delete all
       if (error) throw error;
    } catch (error) { 
        console.error("DB Sync Error (Purge Sales):", error);
        alert("Failed to purge sales from database.");
    }
  };

  const handleLogin = (user: Staff, remember: boolean) => {
    const expiry = Date.now() + (remember ? 30 : 1) * 24 * 60 * 60 * 1000;
    localStorage.setItem('trimtime_session', JSON.stringify({ user, expiry }));
    setCurrentUser(user);
    setCurrentView(user.role === 'employee' ? View.POS : View.DASHBOARD);
  };

  const handleLogout = () => {
    localStorage.removeItem('trimtime_session');
    setCurrentUser(null);
  };

  if (loading) return <div className="h-screen w-full flex items-center justify-center bg-slate-950"><div className="animate-spin rounded-full h-12 w-12 border-t-2 border-amber-500"></div></div>;
  if (!currentUser) return <Login onLogin={handleLogin} staffList={staff} shopName={settings.shopName} />;

  return (
    <div className="flex h-screen bg-slate-50 dark:bg-slate-950 overflow-hidden font-sans transition-colors duration-300">
      <Sidebar 
        currentView={currentView} onViewChange={setCurrentView} 
        shopName={settings.shopName} userRole={currentUser.role} 
        isOpen={isSidebarOpen} onClose={() => setIsSidebarOpen(false)}
        language={sessionLanguage} onLanguageChange={setSessionLanguage}
      />

      <div className="flex-1 flex flex-col min-w-0 md:pl-64 overflow-hidden relative">
        {/* Responsive Header */}
        <header className="flex md:hidden items-center justify-between p-4 bg-white dark:bg-slate-900 border-b border-slate-100 dark:border-slate-800 z-50 sticky top-0 shadow-sm">
          <div className="flex items-center gap-2">
             <div className="w-8 h-8 bg-amber-500 rounded-lg flex items-center justify-center font-brand text-lg text-slate-950">{settings.shopName.charAt(0)}</div>
             <span className="font-bold text-slate-900 dark:text-white truncate max-w-[120px]">{settings.shopName}</span>
          </div>
          <div className="flex gap-2">
            <button onClick={() => setIsDarkMode(!isDarkMode)} className="p-2 text-slate-400 bg-slate-50 dark:bg-slate-800 rounded-lg">
              {isDarkMode ? '🌞' : '🌙'}
            </button>
            <button onClick={() => setIsSidebarOpen(true)} className="p-2 text-slate-900 dark:text-white bg-amber-500 rounded-lg">
              <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M4 6h16M4 12h16m-7 6h7"/></svg>
            </button>
          </div>
        </header>

        {/* Desktop Header */}
        <header className="hidden md:flex justify-between items-center px-8 py-6 no-print">
            <h1 className="text-2xl font-black text-slate-900 dark:text-white font-brand">{tView(currentView, sessionLanguage)}</h1>
            <div className="flex items-center gap-4">
               <button onClick={() => setIsDarkMode(!isDarkMode)} className="p-2.5 bg-white dark:bg-slate-900 text-slate-400 rounded-xl border border-slate-200 dark:border-slate-800">
                 {isDarkMode ? '🌞' : '🌙'}
               </button>
               <div className="flex items-center gap-3 bg-white dark:bg-slate-900 p-1.5 pr-4 rounded-full border border-slate-100 dark:border-slate-800 shadow-sm">
                  <div className="w-8 h-8 rounded-full bg-amber-500 flex items-center justify-center font-black text-slate-950 text-xs">{currentUser.name.charAt(0)}</div>
                  <div className="flex flex-col"><span className="text-xs font-bold dark:text-white">{currentUser.name}</span><span className="text-[9px] uppercase font-black text-slate-400">{currentUser.role}</span></div>
               </div>
               <button onClick={handleLogout} className="p-2.5 bg-slate-100 dark:bg-slate-800 text-slate-500 rounded-xl">🚪</button>
            </div>
        </header>

        <main className="flex-1 overflow-y-auto p-4 md:p-8 relative scrollbar-hide">
          <AnimatePresence mode='wait'>
            <motion.div key={currentView} initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: -10 }} className="h-full">
              <ErrorBoundary key={currentView}>
                {renderView(currentView, { 
                  sales, expenses, products, services, staff, customers, settings, 
                  currentUser, sessionLanguage, isDarkMode, 
                  // DB Handlers passed to children
                  onUpdateServices: handleUpdateServices,
                  onUpdateProducts: handleUpdateProducts,
                  onUpdateStaff: handleUpdateStaff,
                  onUpdateCustomers: handleUpdateCustomers,
                  onUpdateSettings: handleUpdateSettings,
                  onCompleteSale: handleCompleteSale,
                  onAddExpense: handleAddExpense,
                  onDeleteExpense: handleDeleteExpense,
                  onLogout: handleLogout,
                  onPurgeSales: handlePurgeSales,
                  onDeleteSales: handleDeleteSales,

                  setCurrentView, handleLogout
                })}
              </ErrorBoundary>
            </motion.div>
          </AnimatePresence>
        </main>
      </div>

      <InstallBanner 
        deferredPrompt={deferredPrompt} 
        onClose={() => setDeferredPrompt(null)} 
      />
    </div>
  );
};

const tView = (v: View, l: Language) => {
  const map: any = { 
    en: { [View.DASHBOARD]: 'Dashboard', [View.POS]: 'Terminal', [View.FINANCE]: 'Finances', [View.INVENTORY]: 'Catalog', [View.STAFF]: 'Staff', [View.CUSTOMERS]: 'Clients', [View.SETTINGS]: 'Settings' },
    ur: { [View.DASHBOARD]: 'ڈیش بورڈ', [View.POS]: 'ٹرمینل', [View.FINANCE]: 'مالیات', [View.INVENTORY]: 'کیٹلاگ', [View.STAFF]: 'عملہ', [View.CUSTOMERS]: 'صارفین', [View.SETTINGS]: 'ترتیبات' },
    fa: { [View.DASHBOARD]: 'داشبورد', [View.POS]: 'پایانه', [View.FINANCE]: 'مالی', [View.INVENTORY]: 'موجودی', [View.STAFF]: 'پرسنل', [View.CUSTOMERS]: 'مشتریان', [View.SETTINGS]: 'تنظیمات' }
  };
  return map[l]?.[v] || map['en'][v];
};

const renderView = (v: View, props: any) => {
  const { sales, expenses, products, services, staff, customers, settings, currentUser, sessionLanguage, onUpdateServices, onUpdateProducts, onUpdateStaff, onUpdateCustomers, onUpdateSettings, onCompleteSale, onAddExpense, onDeleteExpense, onLogout, onPurgeSales, onDeleteSales, setCurrentView } = props;
  switch (v) {
    case View.DASHBOARD: return <Dashboard sales={sales} expenses={expenses} products={products} currency={settings.currency} language={sessionLanguage} onNavigate={setCurrentView} />;
    case View.POS: return <POS services={services} products={products} staff={staff} customers={customers} settings={settings} currentUser={currentUser} onCompleteSale={onCompleteSale} onAddCustomer={c => onUpdateCustomers([...customers, c])} />;
    case View.FINANCE: return <Finance sales={sales} expenses={expenses} staffList={staff} customers={customers} currency={settings.currency} language={sessionLanguage} currentUser={currentUser} onAddExpense={onAddExpense} onDeleteExpense={onDeleteExpense} onDeleteSales={onDeleteSales} settings={settings} />;
    case View.CUSTOMERS: return <Customers customers={customers} sales={sales} onUpdateCustomers={onUpdateCustomers} currency={settings.currency} language={sessionLanguage} />;
    case View.INVENTORY: return <Inventory services={services} products={products} settings={{...settings, language: sessionLanguage}} onUpdateServices={onUpdateServices} onUpdateProducts={onUpdateProducts} />;
    case View.STAFF: return <StaffManagement staffList={staff} onUpdateStaff={onUpdateStaff} currentUser={currentUser} language={sessionLanguage} />;
    case View.SETTINGS: return <Settings settings={{...settings, language: sessionLanguage}} onUpdateSettings={onUpdateSettings} currentUser={currentUser} onLogout={onLogout} onPurgeSales={onPurgeSales} />;
    default: return null;
  }
};

export default App;

export enum View {
  DASHBOARD = 'DASHBOARD',
  POS = 'POS',
  FINANCE = 'FINANCE',
  INVENTORY = 'INVENTORY',
  STAFF = 'STAFF',
  CUSTOMERS = 'CUSTOMERS',
  SETTINGS = 'SETTINGS'
}

export type UserRole = 'admin' | 'employee';

export interface User {
  id: string;
  name: string;
  username: string;
  role: UserRole;
}

export type Language = 'en' | 'ur' | 'fa';

export interface ShopSettings {
  shopName: string;
  currency: string;
  language: Language;
  countryCode: string; // New field for default phone prefix
  whatsappEnabled: boolean;
  whatsappNumber: string;
  receiptFooter: string;
  taxRate: number;
  taxType: 'included' | 'excluded';
  billingCycleDay: number; // 1-31
  promoCodes: DiscountCode[];
}

export interface Service {
  id: string;
  name: string;
  price: number;
  duration: number; // minutes
  category: string;
}

export interface Product {
  id: string;
  name: string;
  price: number;
  cost: number;
  stock: number;
  barcode?: string;
  lowStockThreshold?: number; // Custom threshold for notifications
}

export interface Staff {
  id: string;
  name: string;
  role: UserRole;
  commission: number; // percentage
  username: string;
  password?: string;
  email?: string;
}

export interface Customer {
  id: string;
  name: string;
  phone: string;
  email: string;
  notes: string;
  createdAt: string;
}

export interface DiscountCode {
  code: string;
  type: 'percentage' | 'fixed';
  value: number;
  description: string;
}

export interface SaleItem {
  id: string;
  name: string;
  price: number;
  type: 'service' | 'product';
  quantity: number;
}

export interface Sale {
  id: string;
  timestamp: string;
  items: SaleItem[];
  staffId: string;
  customerId?: string;
  total: number;
  tax: number;
  discount: number;
  discountCode?: string;
  paymentMethod: 'cash' | 'card';
  taxType: 'included' | 'excluded';
  // Stored snapshots of names at time of sale
  staffName?: string;
  customerName?: string;
}

export interface HeldSale {
  id: string;
  timestamp: string;
  cart: SaleItem[];
  customerId?: string;
  staffId?: string;
}

export interface Expense {
  id: string;
  date: string;
  category: string;
  amount: number;
  description: string;
  receiptImage?: string; // Base64 string of the receipt
}

import React, { useState, useEffect } from 'react';
import { ShopSettings, Language, Staff, DiscountCode } from '../types';
import { CURRENCY_OPTIONS, TRANSLATIONS, COUNTRY_CODES } from '../constants';
import { motion, AnimatePresence } from 'framer-motion';

interface SettingsProps {
  settings: ShopSettings;
  onUpdateSettings: (settings: ShopSettings) => void;
  currentUser?: Staff;
  onPurgeSales?: () => void;
  onLogout: () => void;
}

const Settings: React.FC<SettingsProps> = ({ settings, onUpdateSettings, currentUser, onPurgeSales, onLogout }) => {
  const [formData, setFormData] = useState<ShopSettings>(settings);
  const [isCustomCurrency, setIsCustomCurrency] = useState(!CURRENCY_OPTIONS.some(opt => opt.symbol === settings.currency));
  const [newPromo, setNewPromo] = useState<DiscountCode>({ code: '', type: 'percentage', value: 0, description: '' });

  const t = TRANSLATIONS[settings.language];

  // Sync formData with settings prop when it changes (e.g. after initial DB load)
  useEffect(() => {
    setFormData(settings);
    setIsCustomCurrency(!CURRENCY_OPTIONS.some(opt => opt.symbol === settings.currency));
  }, [settings]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onUpdateSettings(formData);
    alert('Configuration updated successfully!');
  };

  const handleCurrencyChange = (val: string) => {
    if (val === 'CUSTOM') {
      setIsCustomCurrency(true);
    } else {
      setIsCustomCurrency(false);
      setFormData({ ...formData, currency: val });
    }
  };

  const handleResetSales = () => {
    if (confirm(t.confirmReset)) {
        if (onPurgeSales) onPurgeSales();
    }
  };

  const addPromoCode = () => {
    if (!newPromo.code || newPromo.value <= 0) return;

    // Create the updated list
    const updatedCodes = [...(formData.promoCodes || []), { ...newPromo, code: newPromo.code.toUpperCase() }];
    const updatedSettings = { ...formData, promoCodes: updatedCodes };

    // Update local state immediately for UI responsiveness
    setFormData(updatedSettings);

    // Save to database immediately
    onUpdateSettings(updatedSettings);

    // Reset input fields
    setNewPromo({ code: '', type: 'percentage', value: 0, description: '' });
  };

  const removePromoCode = (codeToRemove: string) => {
    // Create the updated list
    const updatedCodes = (formData.promoCodes || []).filter(c => c.code !== codeToRemove);
    const updatedSettings = { ...formData, promoCodes: updatedCodes };

    // Update local state immediately
    setFormData(updatedSettings);

    // Save to database immediately
    onUpdateSettings(updatedSettings);
  };

  return (
    <div className="max-w-4xl mx-auto space-y-6 md:space-y-8 pb-12">
      <div>
        <h2 className="text-2xl md:text-3xl font-bold text-slate-800 dark:text-white font-brand">{t.settings}</h2>
        <p className="text-slate-500 dark:text-slate-400 text-sm">{t.fineTune}</p>
      </div>

      {currentUser?.role === 'admin' ? (
      <form onSubmit={handleSubmit} className="space-y-6 md:space-y-8">
        <motion.div 
          initial={{ opacity: 0, y: 10 }}
          animate={{ opacity: 1, y: 0 }}
          className="bg-white dark:bg-slate-900 p-6 md:p-8 rounded-[2rem] border border-slate-100 dark:border-slate-800 shadow-sm space-y-6"
        >
          <div className="flex items-center gap-4 mb-2">
            <div className="w-10 h-10 bg-amber-50 dark:bg-amber-900/20 rounded-xl flex items-center justify-center text-amber-500">
                <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 21V5a2 2 0 00-2-2H7a2 2 0 00-2 2v16m14 0h2m-2 0h-5m-9 0H3m2 0h5M9 7h1m-1 4h1m4-4h1m-1 4h1m-5 10v-5a1 1 0 011-1h2a1 1 0 011 1v5m-4 0h4"/></svg>
            </div>
            <h3 className="text-lg md:text-xl font-bold text-slate-800 dark:text-white">{t.shopBranding}</h3>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-5 md:gap-6">
            <div>
              <label className="text-[10px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest block mb-2 ml-1">{t.terminalIdentity}</label>
              <input 
                type="text" 
                value={formData.shopName}
                onChange={e => setFormData({...formData, shopName: e.target.value})}
                className="w-full bg-slate-50 dark:bg-slate-800 border-0 rounded-2xl px-5 py-3.5 focus:ring-4 focus:ring-amber-500/10 outline-none text-sm font-bold dark:text-slate-200" 
              />
            </div>

            <div>
              <label className="text-[10px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest block mb-2 ml-1">{t.language} / زبان</label>
              <select 
                value={formData.language}
                onChange={e => setFormData({...formData, language: e.target.value as Language})}
                className="w-full bg-slate-50 dark:bg-slate-800 border-0 rounded-2xl px-5 py-3.5 focus:ring-4 focus:ring-amber-500/10 outline-none text-sm font-bold dark:text-slate-200"
              >
                <option value="en">English (US)</option>
                <option value="ur">Urdu (اردو)</option>
                <option value="fa">Persian (فارسی)</option>
              </select>
            </div>

            <div className="space-y-2">
              <label className="text-[10px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest block ml-1">{t.preferredCurrency}</label>
              <select 
                value={isCustomCurrency ? 'CUSTOM' : formData.currency}
                onChange={e => handleCurrencyChange(e.target.value)}
                className="w-full bg-slate-50 dark:bg-slate-800 border-0 rounded-2xl px-5 py-3.5 focus:ring-4 focus:ring-amber-500/10 outline-none text-sm font-bold dark:text-slate-200"
              >
                {CURRENCY_OPTIONS.map(opt => (
                  <option key={opt.symbol} value={opt.symbol}>{opt.label}</option>
                ))}
                <option value="CUSTOM">{t.customSymbol}</option>
              </select>

              <AnimatePresence>
                {isCustomCurrency && (
                  <motion.div 
                    initial={{ opacity: 0, height: 0 }}
                    animate={{ opacity: 1, height: 'auto' }}
                    exit={{ opacity: 0, height: 0 }}
                    className="mt-2"
                  >
                    <input 
                      type="text" 
                      placeholder="Symbol (e.g. Rs.)"
                      value={formData.currency}
                      onChange={e => setFormData({...formData, currency: e.target.value})}
                      className="w-full bg-slate-100 dark:bg-slate-800/50 border-0 rounded-2xl px-5 py-3 focus:ring-4 focus:ring-amber-500/10 outline-none text-sm font-bold dark:text-slate-200" 
                    />
                  </motion.div>
                )}
              </AnimatePresence>
            </div>

            <div>
              <label className="text-[10px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest block mb-2 ml-1">{t.countryCode}</label>
              <select 
                value={formData.countryCode}
                onChange={e => setFormData({...formData, countryCode: e.target.value})}
                className="w-full bg-slate-50 dark:bg-slate-800 border-0 rounded-2xl px-5 py-3.5 focus:ring-4 focus:ring-amber-500/10 outline-none text-sm font-bold dark:text-slate-200"
              >
                {COUNTRY_CODES.map(code => (
                  <option key={code.code} value={code.code}>{code.label}</option>
                ))}
              </select>
            </div>

            <div>
              <label className="text-[10px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest block mb-2 ml-1">{t.taxCalculation}</label>
              <div className="flex bg-slate-50 dark:bg-slate-800 p-1 rounded-2xl border border-slate-100 dark:border-slate-700">
                <button 
                  type="button"
                  onClick={() => setFormData({...formData, taxType: 'excluded'})}
                  className={`flex-1 py-2.5 rounded-xl font-bold text-xs transition-all ${formData.taxType === 'excluded' ? 'bg-white dark:bg-slate-700 shadow-sm text-slate-900 dark:text-white' : 'text-slate-400 hover:text-slate-600 dark:hover:text-slate-300'}`}
                >
                  {t.excluded}
                </button>
                <button 
