  );
};

export default POS;

export enum View {
  DASHBOARD = 'DASHBOARD',
  POS = 'POS',
  FINANCE = 'FINANCE',
  INVENTORY = 'INVENTORY',
  STAFF = 'STAFF',
  CUSTOMERS = 'CUSTOMERS',
  SETTINGS = 'SETTINGS'
}

export type UserRole = 'admin' | 'employee';

export interface User {
  id: string;
  name: string;
  username: string;
  role: UserRole;
}

export type Language = 'en' | 'ur';

export interface ShopSettings {
  shopName: string;
  currency: string;
  language: Language;
  countryCode: string;
  whatsappEnabled: boolean;
  whatsappNumber: string;
  receiptFooter: string;
  taxRate: number;
  taxType: 'included' | 'excluded';
  billingCycleDay: number; // 1-31
